(window.QUESTIONS_PARTS = window.QUESTIONS_PARTS || {})["md4"] = [{"id":"md4-105-1-1","subject":"md4","topic":"兒科-感染神經","meta":"105年第1次第1題","year":105,"session":1,"number":1,"question":"一位4歲女童，因高燒5天及喉嚨疼痛就醫，給予ampicillin後出現如圖一所示的全身皮疹，同時發現其有眼皮浮腫和如圖二的扁桃腺變化。最可能的致病原為何？圖一圖二","options":["(A) 腸病毒（enterovirus）","(B) EB病毒（Epstein-Barr virus）","(C) 麻疹病毒（measles virus）","(D) 德國麻疹病毒（rubella virus）"],"answer":1,"image":"md4-105-1-1.jpeg"},{"id":"md4-105-1-2","subject":"md4","topic":"兒科-感染神經","meta":"105年第1次第2題","year":105,"session":1,"number":2,"question":"下列何種情況不屬於腸病毒重症的特徵？","options":["(A) 發病超過7天","(B) 出現類似驚嚇的全身性肢體抽動伴有心跳快或血壓高","(C) 年齡小於5歲","(D) 持續嘔吐"],"answer":[0,2],"image":"","answer_note":"更正:第2題答Ａ、Ｃ給分"},{"id":"md4-105-1-3","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"105年第1次第3題","year":105,"session":1,"number":3,"question":"核黃疸（kernicterus）的定義是指間接型膽紅素（unconjugated bilirubin）沈積在下列何處？","options":["(A) 腦膜","(B) 基底核","(C) 小腦","(D) 腦室旁"],"answer":1,"image":""},{"id":"md4-105-1-4","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"105年第1次第4題","year":105,"session":1,"number":4,"question":"新生兒比大人更容易散失熱量，其原因是：","options":["(A) 心跳、呼吸速率較快","(B) 體表面積與體重比值較高","(C) 棕色脂肪代謝率較快","(D) 血液甲狀腺素較高"],"answer":1,"image":""},{"id":"md4-105-1-5","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"105年第1次第5題","year":105,"session":1,"number":5,"question":"下列何者不是造成新生兒先天性感染之重要病原體？","options":["(A) 巨細胞病毒","(B) 梅毒螺旋體","(C) 弓蟲症","(D) 麻疹病毒"],"answer":3,"image":""},{"id":"md4-105-1-6","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"105年第1次第6題","year":105,"session":1,"number":6,"question":"下列有關新生兒暫時性呼吸急促（transient tachypnea of newborn）胸部X光變化，何者錯誤？","options":["(A) 肺門的浸潤增加","(B) 常常可見到minor fissure","(C) 胸部X光的不正常影像，常可持續4天以上","(D) 偶爾可見到少量的肋膜積液"],"answer":2,"image":""},{"id":"md4-105-1-7","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"105年第1次第7題","year":105,"session":1,"number":7,"question":"造成早發性（early-onset）新生兒感染的細菌中，最常見的格蘭氏陽性菌為：","options":["(A) 金黃色葡萄球菌","(B) B群鏈球菌","(C) 肺炎雙球菌","(D) 大腸桿菌"],"answer":1,"image":""},{"id":"md4-105-1-8","subject":"md4","topic":"兒科-消化系統疾病","meta":"105年第1次第8題","year":105,"session":1,"number":8,"question":"有關營養素的吸收之敘述，下列何者錯誤？","options":["(A) 蛋白質，須分解成胺基酸才能吸收","(B) 麥芽糖，須分解成單醣才能吸收","(C) 脂肪，須分解成單一脂肪酸才能吸收","(D) 乳糖，分解成半乳糖及葡萄糖，才能吸收"],"answer":[0,2],"image":"","answer_note":"更正:第8題答Ａ、Ｃ給分"},{"id":"md4-105-1-9","subject":"md4","topic":"兒科-消化系統疾病","meta":"105年第1次第9題","year":105,"session":1,"number":9,"question":"12歲男生，解血便前來求診。身體診察發現嘴唇有黑色斑點如下圖，最可能的疾病是：","options":["(A) Peutz-Jeghers syndrome","(B) familial polyposis coli","(C) Gardner's disease","(D) flat villous adenoma"],"answer":0,"image":"md4-105-1-9.jpeg"},{"id":"md4-105-1-10","subject":"md4","topic":"兒科-內分泌遺傳","meta":"105年第1次第10題","year":105,"session":1,"number":10,"question":"下列何者是兒童肥胖的最佳預測指標？","options":["(A) 出生體重過重","(B) 父母肥胖","(C) 隔代教養","(D) 單一子女"],"answer":1,"image":""},{"id":"md4-105-1-11","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"105年第1次第11題","year":105,"session":1,"number":11,"question":"一個8個月大的男童因第一次尿道感染住院，膀胱尿道攝影檢查（voiding cystourethrogram）顯示如附圖，你會如何給父母親建議？","options":["(A) 接受外科手術治療","(B) 建議接受局部玻尿酸注射治療","(C) 建議使用抗生素預防感染","(D) 建議只要觀察有無復發性感染，暫不需任何治療"],"answer":2,"image":"md4-105-1-11.jpeg"},{"id":"md4-105-1-12","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"105年第1次第12題","year":105,"session":1,"number":12,"question":"下列何者最不可能造成高容積性低血鈉症（hypervolemic hyponatremia）？","options":["(A) 低醛固酮血症（hypoaldosteronism）","(B) 急性腎小管壞死（acute tubular necrosis）初期","(C) 腎病症候群（nephrotic syndrome）","(D) 鬱血性心臟病（congestive heart disease）"],"answer":0,"image":""},{"id":"md4-105-1-13","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"105年第1次第13題","year":105,"session":1,"number":13,"question":"一位5歲的男童幾天前有呼吸道感染，這兩天出現眼皮浮腫，陰囊水腫。尿液檢查顯示尿蛋白>300 mg/dL，RBC 0～2/HPF，血中白蛋白1.9 gm/dL，醫師給予類固醇治療4週之後，再次檢測尿蛋白為陰性反應，下列何者最可能是男童的診斷？","options":["(A) 微小變化型腎病變（minimal change nephropathy）","(B) IgA腎炎（IgA nephritis）","(C) 局部巢狀絲球硬化（focal segmental glomerulosclerosis）","(D) 膜性腎炎（membranous nephropathy）"],"answer":0,"image":""},{"id":"md4-105-1-14","subject":"md4","topic":"兒科-感染神經","meta":"105年第1次第14題","year":105,"session":1,"number":14,"question":"出生體重低於1000公克的早產兒發生腦性麻痺（cerebral palsy）機率較高，是因為這類嬰兒較易有何種腦部病變發生？","options":["(A) brain malformation","(B) subdural hematoma","(C) congenital meningitis","(D) peri-ventricular leukomalacia"],"answer":3,"image":""},{"id":"md4-105-1-15","subject":"md4","topic":"兒科-感染神經","meta":"105年第1次第15題","year":105,"session":1,"number":15,"question":"2歲的男孩因不會講話而求診。他在1歲時可以放手走，現在會爬上下椅子。仍不會叫爸爸或媽媽，叫他不理人。有關其進一步的處置，下列何者敘述錯誤？","options":["(A) 應安排發展聯合評估","(B) 應排除聽力障礙，做聽力檢查","(C) 可能為自閉症的表徵","(D) 應做腦部磁振造影檢查"],"answer":3,"image":""},{"id":"md4-105-1-16","subject":"md4","topic":"兒科-感染神經","meta":"105年第1次第16題","year":105,"session":1,"number":16,"question":"有關抗癲癇藥物之使用原則，下列何者錯誤？","options":["(A) 藥物選擇依癲癇分類而定","(B) 逐漸增量而非馬上給予最高劑量","(C) 原則上使用兩種藥物優於單一藥物，避免發生抗藥性","(D) 藥物在體內之代謝速率有個別差異"],"answer":2,"image":""},{"id":"md4-105-1-17","subject":"md4","topic":"兒科-內分泌遺傳","meta":"105年第1次第17題","year":105,"session":1,"number":17,"question":"關於男童性早熟（precocious puberty），下列那一項的致病機轉與其他三者不同？","options":["(A) 下視丘錯構瘤（hypothalamic hamartoma）","(B) 分泌人類絨毛膜性腺促素（hCG-secreting）的松果腺腫瘤（pineal tumor）","(C) 先天性腎上腺增生（congenital adrenal hyperplasia）","(D) 萊氏細胞瘤（Leydig cell tumor）"],"answer":0,"image":""},{"id":"md4-105-1-18","subject":"md4","topic":"兒科-內分泌遺傳","meta":"105年第1次第18題","year":105,"session":1,"number":18,"question":"下列那一種胰島素在人體內的作用時間最長？","options":["(A) regular insulin","(B) NPH或Lente insulin","(C) lispro或aspart","(D) glargine"],"answer":3,"image":""},{"id":"md4-105-1-19","subject":"md4","topic":"兒科-心血管呼吸","meta":"105年第1次第19題","year":105,"session":1,"number":19,"question":"下列藥物何者不適合使用於輕度持續性氣喘患者作為長期控制藥物？","options":["(A) 吸入型低劑量類固醇（corticosteroid）","(B) 吸入型長效beta 2交感神經促進劑（long acting beta 2 agonist）","(C) 吸入型cromolyn sodium","(D) 口服緩釋型茶鹼（sustained release theophylline）"],"answer":1,"image":""},{"id":"md4-105-1-20","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"105年第1次第20題","year":105,"session":1,"number":20,"question":"6歲男童在2週以前有感冒症狀，最近2～3天發生腹絞痛和膝關節疼痛，隔日解黑便且下肢和臀部出現鼓起的出血點，尿液檢查顯示紅血球10～15/HPF，最有可能診斷是下列何種疾病？","options":["(A) 特發性血小板減少紫斑症（idiopathic thrombocytopenic purpura）","(B) 急性白血病（acute leukemia）","(C) 急性腎絲球腎炎（acute glomerulonephritis）","(D) 過敏性紫斑症（Henoch-Schönlein purpura）"],"answer":3,"image":""},{"id":"md4-105-1-21","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"105年第1次第21題","year":105,"session":1,"number":21,"question":"一位1歲男童體重有7公斤、身高68公分，母親說，孩童打完卡介苗後其注射位置直到目前尚無法癒合。男童自從2個月大開始，便有反覆性腹瀉、肺炎，一般CBC/DC檢查，一直都是lymphopenia 980/mm3，lymphocyte subsets顯示CD3+ 2%、CD4+ 1%、CD8+ 1%、CD19+ 85%、CD16+ CD56+(NK cell) 5%；immunoglobulin(Ig) level顯示IgG 86 mg/dL、IgA 5 mg/dL、IgM undetectable、IgE < 5 IU/mL。對此男童的治療原則是：","options":["(A) 積極使用治療性抗生素及預防性抗生素，終身規則性IVIG，即可有高生活品質，毋需考慮stem cell transplantation","(B) 在治療控制穩當後，積極執行stem cell transplantation","(C) 待基因突變確定後，方能擬定明確的治療計畫","(D) 病人最有可能的診斷為Bruton agammaglobulinemia"],"answer":1,"image":""},{"id":"md4-105-1-22","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"105年第1次第22題","year":105,"session":1,"number":22,"question":"下列何者為急性淋巴性白血病（ALL）最不好的預後因子？","options":["(A) 染色體數過多（hyperdiploidy）","(B) 病發時年紀介於2歲至9歲之間","(C) 有費城染色體（Philadelphia chromosome）","(D) minimal residual disease（MRD）在induction後已不存在"],"answer":2,"image":""},{"id":"md4-105-1-23","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"105年第1次第23題","year":105,"session":1,"number":23,"question":"關於輕型α海洋性貧血（α-thalssemia minor or trait）之敘述，下列何者錯誤？","options":["(A) 不需治療的病人，可能一輩子都不會出現心臟代償的問題","(B) 血色素電泳分析（hemoglobin electropheresis)的報告在正常範圍","(C) 未經治療的病人不會有嚴重的骨髓外造血","(D) 做血液常規檢查（CBC）時，絕大部分的病人紅血球容積（MCV）與血色素含量（MCH）不會明顯下降"],"answer":3,"image":""},{"id":"md4-105-1-24","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"105年第1次第24題","year":105,"session":1,"number":24,"question":"一位4歲男孩，在一次上呼吸道感染後，父母發現男孩臉色較蒼白，而到門診就診。血液檢查結果如下：WBC：4,200/mm3、segment 45%、lymphocyte 50%、RBC：3.2×106/mm3、Hb：7.2 g/dL、Hct：28%、MCV：83 fL、MCH：31 pg、MCHC：37.4g/dL、血小板：250,000/mm3、reticulocyte 3.2%。身體診察發現有脾臟腫大現象，他的下列那項檢查結果最可能有異常？","options":["(A) 血色素電泳（Hb electrophoresis）","(B) 鐵蛋白（ferritin）","(C) 血中鉛濃度","(D) 紅血球滲透壓脆性試驗（RBC osmotic fragility test）"],"answer":3,"image":""},{"id":"md4-105-1-25","subject":"md4","topic":"兒科-心血管呼吸","meta":"105年第1次第25題","year":105,"session":1,"number":25,"question":"下列何種情況，最不可能會有寬的脈搏壓（wide pulse pressure）？","options":["(A) 甲狀腺機能亢進","(B) 貧血","(C) 主動脈瓣逆流","(D) 二尖瓣狹窄"],"answer":3,"image":""},{"id":"md4-105-1-26","subject":"md4","topic":"兒科-心血管呼吸","meta":"105年第1次第26題","year":105,"session":1,"number":26,"question":"本題附圖之嬰兒胸部X光可看到什麼？","options":["(A) 胸腺（thymus）","(B) 心臟擴大（cardiomegaly）","(C) 肺炎（pneumonia）","(D) 肺出血（pulmonary hemorrhage）"],"answer":0,"image":"md4-105-1-26.jpeg"},{"id":"md4-105-1-27","subject":"md4","topic":"兒科-心血管呼吸","meta":"105年第1次第27題","year":105,"session":1,"number":27,"question":"QT間距延長症候群（long QT syndrome）是一種先天性心臟離子通道病變（channelopathy）。下列何種藥物有可能加重其QT延長之變化，應避免？①clarithromycin ②amiodarone ③acetaminophen ④haloperidol","options":["(A) ①②③","(B) ②③④","(C) ①③④","(D) ①②④"],"answer":3,"image":""},{"id":"md4-105-1-28","subject":"md4","topic":"兒科-內分泌遺傳","meta":"105年第1次第28題","year":105,"session":1,"number":28,"question":"先天性遺傳代謝疾病患童常散發出特異性體味，下列之對應組合中何者最不正確？","options":["(A) 苯酮尿症（phenylketonuria）– 霉臭味（musty odor）","(B) 異戊酸血症（isovaleric acidemia）– 腳汗臭味（sweaty feet odor）","(C) 酪胺酸血症（tyrosinemia）– 泳池消毒水味（swimming pool odor）","(D) 三甲基胺尿症（trimethylaminuria）– 腐魚味（rotten fish odor）"],"answer":2,"image":""},{"id":"md4-105-1-29","subject":"md4","topic":"兒科-內分泌遺傳","meta":"105年第1次第29題","year":105,"session":1,"number":29,"question":"一名3歲男孩因為跌倒後大腿骨折而住院，身體診察發現有藍色鞏膜（blue sclera），部分皮膚呈現瘀青斑（bruising spots），全身關節亦較鬆弛，影像檢查顯示下肢長骨（long bone）輕度彎曲並有骨折舊傷與骨質疏鬆（osteoporosis, Z score: -3.0），血中鈣及磷離子濃度正常，家族史中母親也有藍色鞏膜及青春期前重覆骨折病史，關於此病童所罹患的疾病，下列敘述何者最不正確？","options":["(A) 它是第一型膠原蛋白（type I collagen）質量缺陷所致的易碎骨頭症（brittle bone disease）","(B) 雙磷酸鹽（bisphosphonate）有增進造骨母細胞（osteoblast）功能改善骨質密度並減少骨折","(C) 它是一種以體染色體顯性方式遺傳的結締組織疾病，常合併身材矮小或早發性聽力障礙","(D) 此疾病患者病程預後主要與是否有反覆肺炎或心肺血管功能異常程度有關"],"answer":1,"image":""},{"id":"md4-105-1-30","subject":"md4","topic":"兒科-內分泌遺傳","meta":"105年第1次第30題","year":105,"session":1,"number":30,"question":"一位1歲的小孩這2天有感冒的症狀，食慾減退。早上起床時母親發現他意識不清，呼吸困難。送到醫院後抽血發現血糖值只有10 mg/dL，而且乳酸非常高。醫師同時發現病童的肝臟很大，在肋骨下緣8公分。最可能的診斷為下列何者？","options":["(A) 高胰島素血症","(B) 肝醣儲積症Ia型","(C) 有機酸血症","(D) 急性肝炎"],"answer":1,"image":""},{"id":"md4-105-1-31","subject":"md4","topic":"兒科-心血管呼吸","meta":"105年第1次第31題","year":105,"session":1,"number":31,"question":"一個3歲男童，發燒、咳嗽三天，並有喉嚨痛與聲音沙啞。血液檢查白血球11000/uL，其中segment佔45%，lymphocyte占50%，monocyte占3%，eosinophil占2%。身體診察肺部呼吸音較粗（coarse breathing sound），沒有囉音（rales）或喘鳴聲（wheezing）。請依此回答下列3題。X檢查如下，臨床診斷最有可能為下列何者？","options":["(A) 哮吼（croup）","(B) 喉頭軟化（laryngomalacia）","(C) 扁桃腺炎（tonsillitis）","(D) 細菌性氣管炎（bacterial tracheitis）"],"answer":0,"image":"md4-105-1-31.jpeg"},{"id":"md4-105-1-32","subject":"md4","topic":"兒科-心血管呼吸","meta":"105年第1次第32題","year":105,"session":1,"number":32,"question":"承上題，想要確定致病原因，應執行何種檢查？","options":["(A) 支氣管鏡檢查","(B) 咽喉細菌培養","(C) 咽喉病毒培養","(D) 抽血做黴漿菌抗體檢測"],"answer":2,"image":""},{"id":"md4-105-1-33","subject":"md4","topic":"兒科-心血管呼吸","meta":"105年第1次第33題","year":105,"session":1,"number":33,"question":"病童經過處置後燒退兩天，咳嗽減輕，但突然又開始發燒到39.1℃，咳嗽加重，有痰聲。此時診斷為下列何者？","options":["(A) 過敏性氣喘發作","(B) 治療藥物的副作用","(C) 再次罹患上呼吸道感染","(D) 併發細菌性支氣管肺炎"],"answer":3,"image":""},{"id":"md4-105-1-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"105年第1次第34題","year":105,"session":1,"number":34,"question":"貼膚試驗（patch test）是下列何種皮膚疾病的標準診斷方法？","options":["(A) 乾癬（psoriasis）","(B) 多形性紅斑（erythema multiforme）","(C) 慢性蕁麻疹（chronic urticaria）","(D) 過敏性接觸性皮膚炎（allergic contact dermatitis）"],"answer":3,"image":""},{"id":"md4-105-1-35","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"105年第1次第35題","year":105,"session":1,"number":35,"question":"關於異位性皮膚炎（atopic dermatitis）的處置，下列何者錯誤？","options":["(A) 外用局部皮質類固醇藥劑","(B) 紫外線光照治療","(C) 使用潤膚劑","(D) 外用維生素D3及其衍生物"],"answer":3,"image":""},{"id":"md4-105-1-36","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"105年第1次第36題","year":105,"session":1,"number":36,"question":"下列關於乾癬（psoriasis）的敘述，何者錯誤？","options":["(A) 好發於兒童","(B) 好發部位為頭部、肘膝和軀幹","(C) 部分病人會合併乾癬性關節炎（psoriatic arthritis）","(D) 病灶特徵為境界鮮明、表面有白色鱗屑之紅色斑塊"],"answer":0,"image":""},{"id":"md4-105-1-37","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"105年第1次第37題","year":105,"session":1,"number":37,"question":"關於成人型脂漏性皮膚炎（seborrheic dermatitis）的敘述，下列何者錯誤？","options":["(A) 好發於四肢伸側","(B) 病灶表面常伴有鱗屑","(C) 感染人類免疫不全病毒（HIV）的患者，罹患此病之機率及嚴重度增加","(D) 抗黴菌製劑ketoconazole對此病之治療有效"],"answer":0,"image":""},{"id":"md4-105-1-38","subject":"md4","topic":"皮膚-腫瘤","meta":"105年第1次第38題","year":105,"session":1,"number":38,"question":"68歲男性，主訴5年前開始，顏面出現如左圖箭頭所示之病變，病理檢查如右圖所示。下列何者為最適當的診斷？","options":["(A) 日光性角化症（actinic keratosis）","(B) 盤狀紅斑性狼瘡（discoid lupus erythematosus）","(C) 脂漏性角化症（seborrheic keratosis）","(D) 基底細胞癌（basal cell carcinoma）"],"answer":0,"image":"md4-105-1-38.jpeg"},{"id":"md4-105-1-39","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"105年第1次第39題","year":105,"session":1,"number":39,"question":"下列色素性病變何者常於中年後發生？","options":["(A) nevus of Ota（nevus fuscocaeruleus ophthalmomaxillaris）","(B) ephelides（freckle）","(C) mongolian spot","(D) nevus of Hori（bilateral nevus of Ota-like macules）"],"answer":3,"image":""},{"id":"md4-105-1-40","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"105年第1次第40題","year":105,"session":1,"number":40,"question":"30歲男性左前臂之皮膚病灶如圖，據患者描述此病灶約2至3歲即出現，最適宜之診斷為何？","options":["(A) 雀斑（freckles）","(B) 肝斑（melasma）","(C) 斑痣（nevus spilus）","(D) 咖啡牛奶斑（café-au-lait spot）"],"answer":2,"image":"md4-105-1-40.jpeg"},{"id":"md4-105-1-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"105年第1次第41題","year":105,"session":1,"number":41,"question":"26歲的女性，約從十歲起，身上便開始出現搔癢的角化丘疹如圖（一），數目時多時少，夏天工作流汗時會變得較嚴重。指甲板上出現紅白相間的長帶，及游離端有V字型的凹缺如圖（二）所示，下列有關此疾病之敘述何者正確？圖（一）圖（二）","options":["(A) 臨床病灶易發生於脂漏性區域（seborrheic area）","(B) 屬體染色體隱性遺傳","(C) 口服類固醇是最好的治療方式","(D) 突變基因為ATP2C2 gene，其功能為調節細胞鈣離子濃度"],"answer":0,"image":"md4-105-1-41.jpeg"},{"id":"md4-105-1-42","subject":"md4","topic":"皮膚-感染","meta":"105年第1次第42題","year":105,"session":1,"number":42,"question":"20歲女性，患有異位性皮膚炎，最近一週在臉上出現如圖之病變，下列敘述何者正確？","options":["(A) 異位性皮膚炎之惡化","(B) 念珠菌感染","(C) 單純疱疹病毒感染","(D) 皮癬菌感染"],"answer":2,"image":"md4-105-1-42.jpeg"},{"id":"md4-105-1-43","subject":"md4","topic":"皮膚-感染","meta":"105年第1次第43題","year":105,"session":1,"number":43,"question":"承上題，下列何項為正確的處置？","options":["(A) 外用類固醇藥膏","(B) 口服fluconazole","(C) 口服valacyclovir","(D) 外用抗生素藥膏"],"answer":2,"image":""},{"id":"md4-105-1-44","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"105年第1次第44題","year":105,"session":1,"number":44,"question":"20歲女性，近一個月在小腿出現疼痛的紅紫色結節（如圖）；一年前開始反覆出現口腔潰瘍，曾因為葡萄膜炎（uveitis）在眼科就診，最可能之診斷為何？","options":["(A) 疤痕性ৡ天疱瘡（cicatricial pemphigoid）","(B) 多形性紅斑（erythema multiforme）","(C) 尋常性天疱瘡（pemphigus vulgaris）","(D) 貝֠特氏病（Behçet’s disease）"],"answer":3,"image":"md4-105-1-44.jpeg"},{"id":"md4-105-1-45","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"105年第1次第45題","year":105,"session":1,"number":45,"question":"承上題，下列敘述，何者錯誤？","options":["(A) 全世界各國都有，以美國發生率最高","(B) pathergy test陽性","(C) 少數病人會合併中樞神經系統併發症","(D) 亞洲人與可能與HLA-B5及HLA-B51有關"],"answer":0,"image":""},{"id":"md4-105-1-46","subject":"md4","topic":"神經-中風","meta":"105年第1次第46題","year":105,"session":1,"number":46,"question":"50歲男性，整脊後不適至急診，腦部磁振照影顯示有右側延腦內側梗塞（infarction of right medial medulla），可能有那些症狀表現：①右側臉麻 ②左側肢體無力 ③右側肢體失調（dysmetria） ④右側舌頭無力","options":["(A) ①③","(B) ②④","(C) ①④","(D) ②③"],"answer":1,"image":""},{"id":"md4-105-1-47","subject":"md4","topic":"神經-中風","meta":"105年第1次第47題","year":105,"session":1,"number":47,"question":"60歲男性，有高血壓與糖尿病的病史，因急性神經症狀就醫，腦部磁振照影檢查顯示為急性小洞梗塞（lacunar infarction），下列那些是小洞梗塞中風常見的典型症狀：①肢體失調（dysmetria） ②失語（aphasia） ③ 構音困難（dysarthria） ④忽略（neglect）","options":["(A) ①③","(B) ②④","(C) ①④","(D) ②③"],"answer":0,"image":""},{"id":"md4-105-1-48","subject":"md4","topic":"神經-中風","meta":"105年第1次第48題","year":105,"session":1,"number":48,"question":"一位70歲女性患者，有高血壓、糖尿病病史多年，晚上11點入睡時皆正常，清晨6點起床時，卻發現說話不太清楚，左側肢體無力，早晨6點30分，被家人送至急診室，早晨7點20分，血壓：160/88 mmHg，所有血液生化檢查、心電圖皆正常，腦斷層檢查無腦出血或其它異常，此時最不適合的治療為何？","options":["(A) 給予靜脈血栓溶解劑（rt-PA）治療","(B) 給予口服抗血小板劑（aspirin）治療","(C) 住進腦中風加護病房診療","(D) 嚴格控制血糖值"],"answer":0,"image":""},{"id":"md4-105-1-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"105年第1次第49題","year":105,"session":1,"number":49,"question":"一位罹患躁鬱症（bipolar disorder）和氣喘的病人，偏頭痛變得越來越頻繁，目前一週會有兩三天的偏頭痛發作。醫師打算使用預防性藥物治療來減少她的偏頭痛，下列何種藥物是最合適的治療？","options":["(A) propranolol","(B) divalproex","(C) amitriptyline","(D) lithium"],"answer":1,"image":""},{"id":"md4-105-1-50","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"105年第1次第50題","year":105,"session":1,"number":50,"question":"關於癲癇（epilepsy）的敘述，下列何者正確？","options":["(A) 當發作純粹為déjà vu或jamais vu時，歸類於complex partial seizure","(B) 在complex partial seizure發作時，病人神智清醒","(C) 在reflex epilepsies中，以聲音誘發之發作（auditory-induced seizure）最為常見","(D) 70%至80%之complex partial seizure起源自大腦顳葉"],"answer":3,"image":""},{"id":"md4-105-1-51","subject":"md4","topic":"兒科-感染神經","meta":"105年第1次第51題","year":105,"session":1,"number":51,"question":"關於兒童失神癲癇（childhood absence epilepsy）的敘述，下列何者正確？","options":["(A) 好發於1至3歲","(B) 常伴有智力損傷或神經學檢查異常","(C) 每秒4到6次的棘波-慢波複合波（4-to 6-Hz spike-and-wave complexes）為其特徵性之腦電圖（EEG）表現","(D) 屬於良性的原發性全面性癲癇（idiopathic generalized epilepsy）之一"],"answer":3,"image":""},{"id":"md4-105-1-52","subject":"md4","topic":"兒科-感染神經","meta":"105年第1次第52題","year":105,"session":1,"number":52,"question":"有關簡單型熱痙攣（simple febrile seizure）的描述，下列何者正確？","options":["(A) 常有家族病史","(B) 通常到成人階段仍會發生","(C) 腦波檢查常發現不正常","(D) 常伴隨腦部病變"],"answer":0,"image":""},{"id":"md4-105-1-53","subject":"md4","topic":"神經-失智退化運動障礙","meta":"105年第1次第53題","year":105,"session":1,"number":53,"question":"一位63歲的男性退休記者被診斷得了失智症，過去沒有高血壓或糖尿病，也不曾發生腦中風。他在發病後不久，就經常出現視幻覺，尤其是看到小孩子在客廳玩耍，白天看電視時，常常就睡著了。2個月後這位病人的動作變得比較慢，但不至於跌倒。此時，最有可能的診斷是？","options":["(A) Alzheimer disease","(B) dementia with Lewy bodies","(C) Parkinson disease with dementia","(D) vascular dementia"],"answer":1,"image":""},{"id":"md4-105-1-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"105年第1次第54題","year":105,"session":1,"number":54,"question":"36歲油漆工林先生，身體一向健康，10天前罹患輕微感冒，而5天來出現漸進性四肢無力，肢體末端略感麻木，稍覺呼吸急促，但神智清楚，也無吞嚥困難或口齒不清的狀況，因此至門診求助。林先生最可能罹患下列何種疾病？","options":["(A) 重症肌無力症（myasthenia gravis）","(B) 多發性肌炎（polymyositis）","(C) 急性發炎性脫髓鞘多發性神經病變症候群（Guillain-Barré syndrome）","(D) 腦幹中風"],"answer":2,"image":""},{"id":"md4-105-1-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"105年第1次第55題","year":105,"session":1,"number":55,"question":"於一般臨床診療，下列何者是造成多發性神經病變之最常見原因？","options":["(A) 慢性酒精中毒","(B) 鉛中毒","(C) 糖尿病","(D) 尿毒症"],"answer":2,"image":""},{"id":"md4-105-1-56","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"105年第1次第56題","year":105,"session":1,"number":56,"question":"下列何種腦腫瘤使用皮質類固醇（corticosteroid）治療後，雖然會減輕腦水腫（brain edema），但也會使腦腫瘤消退（tumor regression）而影響正確的組織細胞學的診斷（histological diagnosis）？","options":["(A) 多形性膠質母細胞瘤（glioblastoma multiforme）","(B) 室管膜瘤（ependymoma）","(C) 顱咽管瘤（craniopharyngioma）","(D) 原發性中樞神經淋巴瘤（primary CNS lymphoma）"],"answer":3,"image":""},{"id":"md4-105-1-57","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"105年第1次第57題","year":105,"session":1,"number":57,"question":"下列何項檢查結果對診斷單純疱疹性腦炎（herpes simplex encephalitis）最不具有特異性？","options":["(A) 腦脊髓液的單純疱疹病毒的PCR（polymerase chain reaction）檢查呈陽性反應","(B) 腦部磁振照影檢查發現大腦之額葉和顳葉受侵犯","(C) 腦波出現單側週期性癲癇波（periodic lateralized epileptic discharges, PLEDs）","(D) 血清中抗疱疹病毒抗體上升"],"answer":3,"image":""},{"id":"md4-105-1-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"105年第1次第58題","year":105,"session":1,"number":58,"question":"如何計算腦脊髓液（cerebrospinal fluid, CSF）中的IgG index？","options":["(A) IgG (CSF) x albumin (serum) / IgG (serum) x albumin (CSF)","(B) IgG (CSF) x globulin (serum) / IgG (serum) x globulin (CSF)","(C) IgG (serum) x albumin (CSF) / IgG (CSF) x albumin (serum)","(D) IgG (serum) x globulin (CSF) / IgG (CSF) x globulin (serum)"],"answer":0,"image":""},{"id":"md4-105-1-59","subject":"md4","topic":"神經-失智退化運動障礙","meta":"105年第1次第59題","year":105,"session":1,"number":59,"question":"陳小姐今年25歲，二年前開始左手會不自主甩動，接著是右手、臉部、及雙腳都會發生不自主動作（如擠眉弄眼、聳肩、扮鬼臉、彈指或舉腿等等），最後在身體各部位都出現，且愈來愈頻繁。一年前她也感覺到記憶力減低，常常打錯字。她的母親在48歲時也出現類似症狀，在55歲時自殺身亡。陳小姐的身體理學檢查正常，但其智力減低且易怒。她最可能的診斷是：","options":["(A) 亨丁頓舞蹈症（Huntington chorea）","(B) 席登罕氏舞蹈症（Sydenham chorea）","(C) 高甲狀腺亢進舞蹈症","(D) 中風性半邊舞蹈症"],"answer":0,"image":""},{"id":"md4-105-1-60","subject":"md4","topic":"神經-失智退化運動障礙","meta":"105年第1次第60題","year":105,"session":1,"number":60,"question":"承上題，腦部磁振造影（magnetic resonance imaging）最典型的異常是：","options":["(A) 橋腦萎縮（pontine atrophy）","(B) 齒核萎縮（dentate nucleus atrophy）","(C) 尾核萎縮（caudate nucleus atrophy）","(D) 視丘萎縮（thalamus atrophy）"],"answer":2,"image":""},{"id":"md4-105-1-61","subject":"md4","topic":"精神-精神病","meta":"105年第1次第61題","year":105,"session":1,"number":61,"question":"有關躁症發作（manic episode）的藥物治療之敘述，下列何者錯誤？","options":["(A) 鋰鹽（lithium）可治療躁症發作","(B) 可合併使用benzodiazepine","(C) 部分抗精神病藥（antipsychotics）如olanzapine有治療躁症效果","(D) 可單獨使用抗憂鬱劑（antidepressant）治療躁症發作"],"answer":3,"image":""},{"id":"md4-105-1-62","subject":"md4","topic":"精神-器質性與物質使用","meta":"105年第1次第62題","year":105,"session":1,"number":62,"question":"對於冠狀動脈心臟病之精神科非藥物治療模式中，下列何者較欠缺實證醫學之佐證？","options":["(A) 放鬆訓練","(B) 壓力管理訓練","(C) 團體社會支持","(D) 精神分析"],"answer":3,"image":""},{"id":"md4-105-1-63","subject":"md4","topic":"精神-器質性與物質使用","meta":"105年第1次第63題","year":105,"session":1,"number":63,"question":"關於器官移植的精神科評估與治療，下列何者錯誤？","options":["(A) 器官受贈者時常會經歷許多生活適應上的困難與挑戰","(B) 器官的等待、移植評估、術後的適應過程時常會產生壓力性反應","(C) 器官受贈者最常見的精神疾病是創傷後壓力症候群","(D) 移植手術後的長期類固醇治療可能會引起情緒障礙"],"answer":2,"image":""},{"id":"md4-105-1-64","subject":"md4","topic":"精神-精神病","meta":"105年第1次第64題","year":105,"session":1,"number":64,"question":"有關雙極性疾患（bipolar disorder）之描述，下列何者正確？","options":["(A) 躁症症狀出現於老年期，須考慮失智症或譫妄之鑑別診斷","(B) 典型首次發病型態常為躁期","(C) 相較於重鬱症，第二型雙極性疾患（bipolar II disorder）之自殺危險性較低","(D) 長期追蹤發現半數以上個案終生只發病一次"],"answer":0,"image":""},{"id":"md4-105-1-65","subject":"md4","topic":"精神-器質性與物質使用","meta":"105年第1次第65題","year":105,"session":1,"number":65,"question":"有關生理節律（circadian biological rhythm）的敘述，下列何者錯誤？","options":["(A) 睡眠是生理節律的表現之一","(B) 生理節律同時受到外在與內在的因素調節","(C) 下視丘的suprachiasmatic nuclei是生理節律的重要中心","(D) 如果去除外在因素，只有內在因素調節的生理節律時間少於24小時"],"answer":3,"image":""},{"id":"md4-105-1-66","subject":"md4","topic":"精神-器質性與物質使用","meta":"105年第1次第66題","year":105,"session":1,"number":66,"question":"老年人的睡眠相（sleep phase）變化的特徵為：","options":["(A) 前移（advanced sleep phase）","(B) 後移（delayed sleep phase）","(C) 不規則","(D) 與一般成年人無異"],"answer":0,"image":""},{"id":"md4-105-1-67","subject":"md4","topic":"精神-器質性與物質使用","meta":"105年第1次第67題","year":105,"session":1,"number":67,"question":"下列何種物質長期濫用後，最不會產生戒斷症狀？","options":["(A) 幻覺劑（hallucinogen）","(B) 安非他命（amphetamine）","(C) 苯二氮平（benzodiazepine）","(D) 酒精（alcohol）"],"answer":0,"image":""},{"id":"md4-105-1-68","subject":"md4","topic":"精神-器質性與物質使用","meta":"105年第1次第68題","year":105,"session":1,"number":68,"question":"有關吸食強力膠的相關敘述，下列何者正確？","options":["(A) 所產生的作用類似於中樞神經抑制劑（CNS depressant），如酒精","(B) 長期吸食者常常容易產生戒斷症狀","(C) 長期吸食者的腦部斷層掃描，易發現有小區域之梗塞（infarction）","(D) 因其藥物作用時間短，懷孕期間持續吸食對於胎兒影響不大"],"answer":0,"image":""},{"id":"md4-105-1-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"105年第1次第69題","year":105,"session":1,"number":69,"question":"有關苯二氮平類（benzodiazepines）之鎮靜安眠藥戒斷症狀敘述，下列何者正確？","options":["(A) 戒斷產生之幻覺首選治療藥物為抗精神病藥物（antipsychotics）","(B) 治療失眠必要時可合併有鎮靜效果之抗憂鬱劑來治療","(C) 避免戒斷癲癇應改投以短效型藥物如lorazepam","(D) 若有住院則可立即停止鎮靜安眠藥"],"answer":1,"image":""},{"id":"md4-105-1-70","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"105年第1次第70題","year":105,"session":1,"number":70,"question":"一位8歲小孩因為上課不專心，寫作業拖拖拉拉，忘東忘西而常被老師處罰來求診。下列那一項醫師之診斷行為較不恰當？","options":["(A) 詢問父母，此患者有無好動現象","(B) 詢問父母，此患者是否在兩個情境以上有此現象","(C) 詢問父母，此患者幾歲開始有此現象","(D) 先安排影像學檢查（如CT, MRI）"],"answer":3,"image":""},{"id":"md4-105-1-71","subject":"md4","topic":"精神-器質性與物質使用","meta":"105年第1次第71題","year":105,"session":1,"number":71,"question":"生理回饋（biofeedback）最不適用於下面何種疾病？","options":["(A) 緊張性頭痛（tension headache）","(B) 思覺失調症（schizophrenia）","(C) 氣喘","(D) 心律不整"],"answer":1,"image":""},{"id":"md4-105-1-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"105年第1次第72題","year":105,"session":1,"number":72,"question":"關於自殺的敘述，何者正確？","options":["(A) 男女性自殺企圖（suicide attempt）與自殺死亡（completed suicide）率皆差不多","(B) 自殺企圖男性比女性多，自殺死亡女性比男性多","(C) 自殺企圖男性比女性多，自殺死亡也是男性多","(D) 自殺企圖女性比男性多，自殺死亡男性比女性多"],"answer":3,"image":""},{"id":"md4-105-1-73","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"105年第1次第73題","year":105,"session":1,"number":73,"question":"自殺風險評估之因子中，那些屬於相對低風險？","options":["(A) 鰥寡","(B) 衝動性之自殺行為","(C) 自責（self blame）","(D) 上吊或跳樓"],"answer":1,"image":""},{"id":"md4-105-1-74","subject":"md4","topic":"精神-精神官能症","meta":"105年第1次第74題","year":105,"session":1,"number":74,"question":"一名25歲女性業務員，過去身體狀況良好，無不良嗜好。近半年來在跑業務途中，已有七、八次於公車上突然發生呼吸困難、胸悶、手腳發麻、頭昏、心跳急促及有快要失控的感覺，因此變得害怕出門工作，整天擔心是否罹患不治之症。依據DSM-IV-TR診斷標準，此個案最有可能的診斷為何？","options":["(A) 急性壓力症候群（acute stress disorder）","(B) 慮病症（hypochondriasis）","(C) 社交畏懼症（social phobia）","(D) 恐慌症（panic disorder）"],"answer":3,"image":""},{"id":"md4-105-1-75","subject":"md4","topic":"精神-精神官能症","meta":"105年第1次第75題","year":105,"session":1,"number":75,"question":"承上題，能使患者病況達到長期穩定的治療首選用藥為何？","options":["(A) 苯二氮平類（benzodiazepines）","(B) 情緒穩定劑（mood stabilizers）","(C) 血清素再吸收抑制劑（SSRI）","(D) 抗精神病藥物（antipsychotics）"],"answer":2,"image":""},{"id":"md4-105-1-76","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"105年第1次第76題","year":105,"session":1,"number":76,"question":"14歲男童，其父親患有高血壓；男童電腦斷層掃描檢查如圖，其最可能診斷為何？","options":["(A) 腎絲球炎","(B) 腎盂腎炎","(C) 腎結石","(D) 多囊腎"],"answer":3,"image":"md4-105-1-76.jpeg"},{"id":"md4-105-1-77","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"105年第1次第77題","year":105,"session":1,"number":77,"question":"教導一般民眾對嬰兒及兒童實施心肺復甦術（cardiopulmonary resuscitation）時，壓胸及吹氣之比例為何？","options":["(A) 1歲以上至8歲為30：2","(B) 1歲以下為15：2","(C) 1歲以上至8歲為5：1","(D) 1歲以下為5：1"],"answer":0,"image":""},{"id":"md4-105-1-78","subject":"md4","topic":"神經-中風","meta":"105年第1次第78題","year":105,"session":1,"number":78,"question":"一位70歲老年人在2天前跌倒撞到頭後，今天覺得左側無力且嗜睡，在急診的電腦斷層掃描顯示硬腦膜下血腫（subdural hematoma）下列敘述何者錯誤？","options":["(A) 可能為中大腦動脈（middle cerebral artery）出血所致","(B) 這類病患可能需要手術處理","(C) 此類腦出血大多曾有頭部創傷所致","(D) 在老年病患有時神經學變化較晚才出現"],"answer":0,"image":""},{"id":"md4-105-1-79","subject":"md4","topic":"醫學倫理與法規","meta":"105年第1次第79題","year":105,"session":1,"number":79,"question":"F步行通過斑馬線之際，遭他人駕車撞擊昏迷，於加護病房接受照顧1個月後，身體逐漸康復，然而F出現失眠、夢魘、焦慮、憂鬱、不敢過馬路、逃避任何關於車禍的話題或畫面，經精神科專科醫師P診斷為「創傷後壓力症候群」（Post-traumatic stress disorder），接受治療達1年之久。F對於肇事者提出民事賠償訴訟，法院若委託P為F進行鑑定其心理創傷之程度，則下列何者最為恰當？","options":["(A) P應接受法院委託鑑定，因為P診療F已有1年之久，最了解F","(B) P應接受法院委託鑑定，因為P診療F已有1年之久，F最信任P，願意配合鑑定","(C) P應拒絕法院之委託鑑定，因為F有可能因此喪失恢復健康之動機","(D) P應拒絕法院之委託鑑定，因為P會有照顧F及公正鑑定之角色衝突"],"answer":3,"image":""},{"id":"md4-105-1-80","subject":"md4","topic":"醫學倫理與法規","meta":"105年第1次第80題","year":105,"session":1,"number":80,"question":"王小弟因為氣喘及反覆性細菌性肺炎，生長發育不良，經sweat chloride test而被診斷為囊腫纖維症（cystic fibrosis）。這是一種自體隱性遺傳性疾病，王家子女將有3/4機率是帶因或罹病者，這對夫婦於是希望另外兩個目前沒有症狀的7歲與10歲子女接受帶因者基因檢測。下列醫療的建議何者最正確？","options":["(A) 及早診斷隱藏罹病者可以改善疾病預後","(B) 及早發現攜帶基因有助於兒童心理調適","(C) 帶因者基因檢測應該經雙方家族會議後決定","(D) 待子女成年後，由他們自己決定是否接受帶因者基因檢測"],"answer":[0,3],"image":"","answer_note":"更正:第80題答Ａ、Ｄ給分。"},{"id":"md4-105-2-1","subject":"md4","topic":"兒科-感染神經","meta":"105年第2次第1題","year":105,"session":2,"number":1,"question":"住在新竹的5個月大男童，被媽媽被發現左側腋下有一個直徑約2公分的硬塊，後來硬塊愈來愈大，並且出現紅腫如圖所示，他被帶到診所接受第一代抗生素Keflex 40 mg/kg/day治療約一週，可是並未見到效果，但也沒有發燒，問診發現這位男童的預防注射均如期接種，並無旅遊史，下列那一項處置最正確？","options":["(A) 可能是抗生素劑量不夠，增加抗生素的劑量","(B) 應該是接種卡介苗引起之淋巴腺炎，可用細針穿刺引流，將膿液作耐酸性染色和結核菌培養","(C) 應該是血管瘤，不需要做特別處理，解釋病情並建議1歲大時追蹤即可","(D) 可能為惡性腫瘤，應儘速安排電腦斷層檢查"],"answer":1,"image":"md4-105-2-1.jpeg"},{"id":"md4-105-2-2","subject":"md4","topic":"兒科-感染神經","meta":"105年第2次第2題","year":105,"session":2,"number":2,"question":"2歲男童，被發現右邊膝蓋處和屁股有成群的水泡已有2天如圖所示，看診時你發現這位男童的口腔黏膜也有0.2公分大小的水泡，媽媽主訴男童食慾變差也有發燒情況，下列那一項是最可能的診斷？","options":["(A) 水痘（varicella）","(B) 手足口症（hand foot mouth disease）","(C) 天花（smallpox）","(D) 麻疹（measles）"],"answer":1,"image":"md4-105-2-2.jpeg"},{"id":"md4-105-2-3","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"105年第2次第3題","year":105,"session":2,"number":3,"question":"1歲8個月大的男童發燒、嘔吐和嗜睡3天住到病房，身體診察時發現皮膚出現出血點和紫斑現象如圖所示，血液檢查發現：血紅素為9.5gm/dL、血比容為28.5%、白血球為14000/mm3，以中性球占85%、其中不成熟白血球有20%、血小板為34000/mm3，發炎指數CRP: 20 mg/dL；詢問病史發現家中沒人有相同症狀且並無旅遊史，下列那一項是最可能的診斷？","options":["(A) 過敏性紫斑症","(B) 特發性血小板低下紫斑症","(C) 腦膜炎雙球菌感染","(D) 多形性紅斑"],"answer":2,"image":"md4-105-2-3.jpeg"},{"id":"md4-105-2-4","subject":"md4","topic":"兒科-感染神經","meta":"105年第2次第4題","year":105,"session":2,"number":4,"question":"關於猩紅熱的敘述，下列何者錯誤？","options":["(A) 為pyrogenic exotoxins引起","(B) 感染後會出現脫皮的情形為A群鏈球菌引起","(C) 治療首選藥物為紅黴素","(D) 會呈現草莓舌、皮膚通紅"],"answer":2,"image":""},{"id":"md4-105-2-5","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"105年第2次第5題","year":105,"session":2,"number":5,"question":"17歲男生，因為最近2週內體重增加10公斤且出現水腫狀況而求診，身體診察時發現下肢有按壓性水腫，尿液檢查發現有嚴重蛋白尿(3+)、白血球：20/HPF，血液檢查發現白蛋白低下：1.6 g/dL、膽固醇上升：425 mg/dL和三酸甘油酯上升300 mg/dL，下列何者為最有可能的診斷？","options":["(A) 腎病症候群","(B) 急性腎炎","(C) 泌尿道感染","(D) 擴張性心肌病變"],"answer":0,"image":""},{"id":"md4-105-2-6","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"105年第2次第6題","year":105,"session":2,"number":6,"question":"足月兒之生理性黃疸，黃疸數值尖峰通常於何時出現？","options":["(A) 出生6小時內","(B) 出生12小時內","(C) 出生24小時內","(D) 出生2～5天內"],"answer":3,"image":""},{"id":"md4-105-2-7","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"105年第2次第7題","year":105,"session":2,"number":7,"question":"下列那一項對足月新生兒清醒時是不正常的？","options":["(A) 心跳每分鐘72下","(B) 呼吸每分鐘40次","(C) 體溫37.5℃","(D) 前囟門平坦"],"answer":0,"image":""},{"id":"md4-105-2-8","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"105年第2次第8題","year":105,"session":2,"number":8,"question":"由氣管給予肺表面張力素（surfactant）的治療效果，是依賴它能否迅速地和均勻地在肺泡中被吸附和傳播。下列那一狀況的肺表面張力素是最有效率的分布？","options":["(A) 在使用呼吸器一段時間後","(B) 出生時仍有胎兒肺液體時","(C) 緩慢速率地注入","(D) 以aerosol的方式給予"],"answer":1,"image":""},{"id":"md4-105-2-9","subject":"md4","topic":"兒科-感染神經","meta":"105年第2次第9題","year":105,"session":2,"number":9,"question":"6週大之嬰兒，媽媽主訴昨天開始發燒，活力變差，剛剛突然發生抽搐，持續5分鐘，住院醫師認為病嬰疑似感染腦膜炎，進行脊椎穿刺檢查，脊髓液呈現leukocytes: 5000/mm3，protein: 300 mg/dL，glucose: 20 mg/dL。最可能的診斷是？","options":["(A) 細菌性腦膜炎","(B) 病毒性腦膜炎","(C) 嗜伊紅性腦膜炎","(D) 真菌性腦膜炎"],"answer":0,"image":""},{"id":"md4-105-2-10","subject":"md4","topic":"兒科-消化系統疾病","meta":"105年第2次第10題","year":105,"session":2,"number":10,"question":"懷孕29週出生的早產兒，出生體重1600公克，餵食後罹患壞死性腸炎。下列症狀何者最少出現？","options":["(A) 便秘","(B) 腹脹","(C) 嘔吐","(D) 血便"],"answer":0,"image":""},{"id":"md4-105-2-11","subject":"md4","topic":"兒科-內分泌遺傳","meta":"105年第2次第11題","year":105,"session":2,"number":11,"question":"6歲大男生，被發現肝功能異常，懷疑是Wilson disease，下列何者錯誤？","options":["(A) Wilson disease是性聯隱性遺傳","(B) serum copper和ceruloplasmin在Wilson disease早期不一定會低","(C) 5歲以上找不到合理解釋的肝功能異常病人，Wilson disease應被列為鑑別診斷之一","(D) 應會診眼科，看cornea是否有Kayser-Fleischer (K-F) ring"],"answer":0,"image":""},{"id":"md4-105-2-12","subject":"md4","topic":"兒科-消化系統疾病","meta":"105年第2次第12題","year":105,"session":2,"number":12,"question":"腸炎後腹瀉嬰兒，如果是腸粘膜受傷引發酵素缺乏，已給不含乳糖配方，仍然每天解多次酸性水性大便，下列那一種酵素缺乏最有可能？","options":["(A) trehalase","(B) sucrase-isomaltase","(C) glucoamylase","(D) maltase"],"answer":1,"image":""},{"id":"md4-105-2-13","subject":"md4","topic":"兒科-消化系統疾病","meta":"105年第2次第13題","year":105,"session":2,"number":13,"question":"有關腸套疊（intussusception）之敘述，下列何者正確？","options":["(A) 女性的發生率約為男性的3倍","(B) 典型的症狀是出現一陣一陣的腹痛","(C) 迴腸-迴腸型（ileoileal）腸套疊最常發生","(D) 鋇劑灌腸復位（barium enema reduction）後的復發率小於1%"],"answer":1,"image":""},{"id":"md4-105-2-14","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"105年第2次第14題","year":105,"session":2,"number":14,"question":"12歲的男童幾天前有呼吸道感染，這兩天出現眼皮浮腫，陰囊水腫。尿液檢查顯示尿蛋白>300 mg/dL, RBC 3～5/HPF, 血中白蛋白1.7 gm/dL, 醫師給予類固醇治療8週之後，再次檢測尿蛋白仍是>300mg/dL反應，且血中肌酐酸值兩個月間增加了1.2 mg/dL，下列何者最可能是男童的診斷？","options":["(A) 微小變化型腎病變（minimal change nephropathy）","(B) 局部巢狀腎絲球硬化（focal segmental glomerulosclerosis）","(C) 腎絲球基底膜薄膜病（thin glomerular basement membrane disease）","(D) IgA腎炎（IgA nephropathy）"],"answer":1,"image":""},{"id":"md4-105-2-15","subject":"md4","topic":"兒科-感染神經","meta":"105年第2次第15題","year":105,"session":2,"number":15,"question":"5歲男孩，有急性肢體無力麻痺（acute flaccid paralysis），最不可能的診斷或病因是：","options":["(A) Bell's palsy","(B) acute transverse myelitis","(C) polio-like syndrome","(D) hypokalemia"],"answer":0,"image":""},{"id":"md4-105-2-16","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"105年第2次第16題","year":105,"session":2,"number":16,"question":"2個月大的女嬰，因為最近一個月餵食越來越困難而住院，身體診察發現神智清楚，低肌肉張力，四肢無力，無深部肌腱反應，腹式呼吸以及舌頭顫動（fasciculation）。最可能的診斷是：","options":["(A) 缺氧缺血性腦病變（hypoxic ischemic encephalopathy）","(B) 脊髓肌肉萎縮症（spinal muscular atrophy）","(C) 先天性重症肌無力（congenital myasthenia gravis）","(D) 先天性肌肉失養症（congenital muscular dystrophy）"],"answer":1,"image":""},{"id":"md4-105-2-17","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"105年第2次第17題","year":105,"session":2,"number":17,"question":"當嬰幼兒因為外傷被帶至急診時，下列照顧者的敘述何者最合理？","options":["(A) 2個月的嬰兒自己翻身掉到床下撞到頭部","(B) 4個月大的嬰兒腳卡到床欄，在自行掙脫的過程中讓大腿骨折","(C) 5個月的嬰兒爬行時自己碰到熨斗而燙到手","(D) 1歲2個月的嬰兒抓到餐桌的桌巾，讓桌上熱湯翻下燙傷臉部"],"answer":3,"image":""},{"id":"md4-105-2-18","subject":"md4","topic":"兒科-內分泌遺傳","meta":"105年第2次第18題","year":105,"session":2,"number":18,"question":"關於Noonan syndrome之敘述，下列何者錯誤？","options":["(A) 身材矮小","(B) 蹼狀頸（webbed neck）","(C) 正常染色體核型（normal karyotype）","(D) 主動脈狹窄（aortic stenosis）為其最常見的心臟病變"],"answer":3,"image":""},{"id":"md4-105-2-19","subject":"md4","topic":"兒科-內分泌遺傳","meta":"105年第2次第19題","year":105,"session":2,"number":19,"question":"關於低血磷佝僂症（hypophosphatemic rickets）之敘述，下列何者較罕見？","options":["(A) 血鈣正常","(B) 血清鹼性磷酸酶（alkaline phosphatase）值高於正常","(C) 血清副甲狀腺素（parathyroid hormone）濃度高於正常","(D) 血清1,25-二羥維生素D（1,25-dihydroxyvitamin D）值正常"],"answer":2,"image":""},{"id":"md4-105-2-20","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"105年第2次第20題","year":105,"session":2,"number":20,"question":"6歲女童，2個月前有發燒、倦怠感和體重減輕的症狀，後來發生肌肉無力且有Gower徵候（Gower sign），眼瞼出現紅斑且因日曬有惡化現象，血液檢查時發現肌酐酸激酶（creatine kinase）值明顯升高，最有可能的診斷是下列那一種疾病？","options":["(A) 肌肉失養症（muscular dystrophy）","(B) 感染性肌炎（infectious myositis）","(C) 幼年型皮肌炎（juvenile dermatomyositis）","(D) 全身性紅斑性狼瘡（systemic lupus erythematosus）"],"answer":2,"image":""},{"id":"md4-105-2-21","subject":"md4","topic":"兒科-心血管呼吸","meta":"105年第2次第21題","year":105,"session":2,"number":21,"question":"小威的媽媽問醫生小威的氣喘病那時候才會好，醫生回答氣喘病是呼吸道組織持續的發炎反應，臨床不一定會有明顯症狀，但組織的發炎反應可能持續幾天甚至好幾年。下列何者不是造成慢性持續發炎的原因？","options":["(A) 反覆的過敏原接觸刺激過敏反應細胞如肥大細胞（mast cell），嗜伊紅性細胞（eosinophil）產生反應","(B) 第二型輔助T細胞（Th2）分泌細胞素如介白質-13（interleukin-13, IL-13），IL-5等而使上述的過敏反應細胞存活更久","(C) 介白質-5（IL-5）會誘使肥大細胞（mast cell）前驅物分化，而使肥大細胞增生，進而破壞局部組織","(D) 組織的重模組化（remodeling）造成氣管不可逆的組織變化而使疾病成慢性且持續"],"answer":2,"image":""},{"id":"md4-105-2-22","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"105年第2次第22題","year":105,"session":2,"number":22,"question":"8歲的小明，主述2天以來有肚子痛及左踝關節疼痛腫脹，身體檢查時發現下肢有許多紫斑（purpura），下列敘述何者錯誤？","options":["(A) 25～50%的此類病人會影響腎臟","(B) 血液中之血小板數目正常","(C) 若有嚴重腸胃症狀如出血或阻塞，可使用類固醇治療","(D) 急性期有尿液檢查異常者，建議尿液檢查追蹤2個月即可"],"answer":3,"image":""},{"id":"md4-105-2-23","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"105年第2次第23題","year":105,"session":2,"number":23,"question":"下列何者不是Kasabach-Merritt Syndrome的主要病徵？","options":["(A) Kaposiform hemangioendothelioma","(B) thrombocytopenia","(C) immune mediated hemolytic anemia","(D) acute or chronic consumptional coagulopathy"],"answer":2,"image":""},{"id":"md4-105-2-24","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"105年第2次第24題","year":105,"session":2,"number":24,"question":"10歲大的女孩，診斷為急性白血病的同時被檢查出有t(15,17)之染色體轉位。下列何者是最可能的診斷？","options":["(A) AML M7 type","(B) early pre-B ALL","(C) AML M3 type","(D) mature B-cell ALL"],"answer":2,"image":""},{"id":"md4-105-2-25","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"105年第2次第25題","year":105,"session":2,"number":25,"question":"15歲女病患，有家族性易出血現象，她易流鼻血、月經量多、貧血。血液檢驗結果顯示：bleeding time超過30分鐘，PT 10秒（control 11秒），aPTT 48秒（control 30秒），Hb 5.0g/dL，platelet count 480×103/mm3。最可能的診斷為：","options":["(A) hemophilia A","(B) hemophilia B","(C) von Willebrand disease","(D) Bernard-Soulier syndrome"],"answer":2,"image":""},{"id":"md4-105-2-26","subject":"md4","topic":"兒科-心血管呼吸","meta":"105年第2次第26題","year":105,"session":2,"number":26,"question":"4天大男嬰，因呼吸急促及厲害發紺現象住院，胸部X光檢查如圖所示。給予腎前列素（PGE 1）後，其發紺及呼吸急促現象並未改善，下列何者為最可能的心臟問題？","options":["(A) 肺靜脈回流異常合併阻塞","(B) 大血管轉位合併心室中膈缺損","(C) 法洛氏四合症合併單側肺動脈缺失","(D) 右心室雙出口合併肺動脈狹窄"],"answer":0,"image":"md4-105-2-26.jpeg"},{"id":"md4-105-2-27","subject":"md4","topic":"兒科-心血管呼吸","meta":"105年第2次第27題","year":105,"session":2,"number":27,"question":"下列何種心臟病，最常合併Wolff-Parkinson-White症候群？","options":["(A) Ebstein三尖瓣脈異常","(B) 大血管轉位（TGA）","(C) 法洛式四合症（TOF）","(D) 心室中隔缺損（VSD）"],"answer":0,"image":""},{"id":"md4-105-2-28","subject":"md4","topic":"兒科-心血管呼吸","meta":"105年第2次第28題","year":105,"session":2,"number":28,"question":"1歲小男孩，突然臉色蒼白，冒冷汗，父母描述過去因心跳慢，曾於出生不久接受某種手術，身體診查發現心跳只有56次/分，緊急CXR如下。此小男孩最可能過去接受過何種手術？","options":["(A) pacemaker implantation","(B) lobectomy","(C) peridectomy","(D) tracheostomy"],"answer":0,"image":"md4-105-2-28.jpeg"},{"id":"md4-105-2-29","subject":"md4","topic":"兒科-內分泌遺傳","meta":"105年第2次第29題","year":105,"session":2,"number":29,"question":"18個月大的男孩，因昏迷被送到急診室，腦部電腦斷層攝影發現右顳部有硬腦膜下出血，身體診察無外傷。據母親敘述此男孩從小頭圍比正常小孩大，曾有醫師懷疑有水腦。下列那種先天性代謝疾病最為可能的診斷？","options":["(A) 苯酮尿症（phenylketonuria）","(B) 中鏈脂肪酸去氫酶缺乏症（medium chain acyl CoA dehydrogenase deficiency）","(C) 戊二酸尿症第一型（glutaric aciduria type I）","(D) 異戊酸血症（isovaleric acidemia）"],"answer":2,"image":""},{"id":"md4-105-2-30","subject":"md4","topic":"兒科-內分泌遺傳","meta":"105年第2次第30題","year":105,"session":2,"number":30,"question":"小男孩來就診，非常矮，頭看起來很大，四肢短短的。醫師的診斷是侏儒症（achondroplasia）。醫師記得這是一種體染色體顯性遺傳疾病，但是患童的父母親身高卻是正常的。最適合的解釋為何？","options":["(A) 醫師記錯了，侏儒症應該是隱性遺傳的","(B) 父親其實不是很高，可能父親也有侏儒症，只是表現不完全","(C) 隔代遺傳","(D) 這個小男孩的疾病是來自新的突變"],"answer":3,"image":""},{"id":"md4-105-2-31","subject":"md4","topic":"兒科-內分泌遺傳","meta":"105年第2次第31題","year":105,"session":2,"number":31,"question":"家族型高膽固醇血症，有可能是因為低密度脂蛋白受體基因突變所引起。一對夫妻有一位5歲的小孩，身上出現黃色瘤（xanthoma）而就診。抽血檢查後發現其膽固醇大於1000 mg/dL。如果醫師進行家族分析，發現父母親的血中膽固醇都介於300 mg/dL到400 mg/dL之間。對於這個家族疾病遺傳的敘述，下列何者不適當？","options":["(A) 如果只著眼於血中膽固醇大於1000 mg/dL的同合子（homozygous）突變，這是一種隱性遺傳","(B) 如果著眼於膽固醇有升高，這是一種顯性遺傳","(C) 同樣的基因突變卻不一樣的表現，表示有epigenetics出現","(D) 家族中很可能還有其他的成員有高膽固醇血症"],"answer":2,"image":""},{"id":"md4-105-2-32","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"105年第2次第32題","year":105,"session":2,"number":32,"question":"9個月大的男嬰，上週健康檢查時體重10公斤。過去一週他持續有腹瀉的現象。今天尿布只換了2次，晚上父母送來急診就診。身體檢查發現男嬰體重9.2公斤，男嬰眼窩下凹，哭鬧不安，但是很少眼淚。男嬰血壓82/46 mmHg，心跳每分鐘170下，呼吸每分鐘21下。男嬰的脫水程度為：","options":["(A) 男嬰有輕度脫水現象","(B) 男嬰有中度脫水現象","(C) 男嬰有重度脫水現象","(D) 男嬰有休克現象"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第32題一律給分 (原公告答案 B)"},{"id":"md4-105-2-33","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"105年第2次第33題","year":105,"session":2,"number":33,"question":"承上題，抽血檢查結果[Na+]136 mmol/L；[K+]4.2 mmol/L，請算出男嬰接下來24小時最適合的水分總需要量？","options":["(A) 前2個小時先給200 mL生理食鹽水，後24小時再給1600 mL輸液","(B) 前2個小時先給200 mL生理食鹽水，後24小時再給1000 mL輸液","(C) 前8個小時先給500 mL生理食鹽水，後16小時再給500 mL輸液","(D) 前8個小時先給600 mL生理食鹽水，後16小時再給1000 mL輸液"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第33題一律給分 (原公告答案 A)"},{"id":"md4-105-2-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"105年第2次第34題","year":105,"session":2,"number":34,"question":"20歲女性，使用染髮劑後引起如圖所示之反應，下列敘述何者錯誤？","options":["(A) 染髮劑引起過敏反應最常見的成分為para-phenylenediamine","(B) 染髮劑引起的皮膚炎屬於第四型過敏反應","(C) 染髮劑引起的皮膚炎屬於第二型過敏反應","(D) 貼膚試驗有助於確認過敏成分"],"answer":2,"image":"md4-105-2-34.jpeg"},{"id":"md4-105-2-35","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"105年第2次第35題","year":105,"session":2,"number":35,"question":"5歲男孩，腳底出現如圖所示之症狀，下列何者為最適合的診斷？","options":["(A) tinea pedis","(B) juvenile plantar dermatosis","(C) ichthyosis","(D) asteatotic eczema"],"answer":1,"image":"md4-105-2-35.jpeg"},{"id":"md4-105-2-36","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"105年第2次第36題","year":105,"session":2,"number":36,"question":"43歲男性，在頭部、肘部、膝部、四肢及軀幹出現如圖之皮膚病變，反覆有10年之久。KOH鏡檢沒發現黴菌，而病理組織檢查如圖。患者除了皮膚之外，最容易侵犯何種器官？","options":["(A) 腎臟","(B) 心臟","(C) 關節","(D) 肌肉"],"answer":2,"image":"md4-105-2-36.jpeg"},{"id":"md4-105-2-37","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"105年第2次第37題","year":105,"session":2,"number":37,"question":"關於玫瑰糠疹（pityriasis rosea）的敘述，下列何者錯誤？","options":["(A) 病灶存在時間常小於一週","(B) 常可見先驅病灶（herald patch）","(C) 典型表徵呈現聖誕樹樣分布（Christmas tree pattern）","(D) 鑑別診斷包括二期梅毒（secondary syphilis）"],"answer":0,"image":""},{"id":"md4-105-2-38","subject":"md4","topic":"皮膚-感染","meta":"105年第2次第38題","year":105,"session":2,"number":38,"question":"台中市38歲男性，2週前太魯閣旅遊，回家後出現發燒、頭痛、全身倦怠感，及皮膚紅疹（如圖A）。理學檢查發現在右肘窩病灶（如圖B），最可能的診斷為何？","options":["(A) 鉤端螺旋體（leptospirosis）","(B) 二期梅毒（secondary syphilis）","(C) 麻疹（measles）","(D) 恙蟲病（scrub typhus）"],"answer":3,"image":"md4-105-2-38.jpeg"},{"id":"md4-105-2-39","subject":"md4","topic":"皮膚-感染","meta":"105年第2次第39題","year":105,"session":2,"number":39,"question":"36歲男性，主訴最近一星期，雙手掌及足底出現如圖所示之皮膚病變。那一項實驗室檢查對疾病確診最有幫忙？","options":["(A) 細菌培養（bacteria culture）","(B) KOH鏡檢（KOH examination）","(C) 貼膚試驗（patch test）","(D) VDRL及TPHA"],"answer":3,"image":"md4-105-2-39.jpeg"},{"id":"md4-105-2-40","subject":"md4","topic":"皮膚-感染","meta":"105年第2次第40題","year":105,"session":2,"number":40,"question":"45歲女性糖尿病患，3天前於右側額部出現叢集樣水疱（grouped vesicles）合併紅斑，同側鼻尖亦出現數個水疱，下列何者為最需要之檢查？","options":["(A) 皮膚劃紋反應（dermatographism）","(B) KOH鏡檢","(C) 眼科檢查","(D) 伍氏燈檢查（Wood's light examination）"],"answer":2,"image":""},{"id":"md4-105-2-41","subject":"md4","topic":"皮膚-腫瘤","meta":"105年第2次第41題","year":105,"session":2,"number":41,"question":"70歲女性，左側耳後有如左圖之腫瘤，數年之久，病理組織切片結果如右圖；下列何者為最適當的診斷？","options":["(A) 鱗狀細胞癌（squamous cell carcinoma）","(B) 基底細胞癌（basal cell carcinoma）","(C) 惡性黑色素細胞癌（malignant melanoma）","(D) 脂漏性角化症（seborrheic keratosis）"],"answer":1,"image":"md4-105-2-41.jpeg"},{"id":"md4-105-2-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"105年第2次第42題","year":105,"session":2,"number":42,"question":"關於硬皮症（morphea）的敘述，下列何者錯誤？","options":["(A) 硬皮症之皮膚病灶和全身性硬化症（systemic sclerosis）的皮膚病灶可明顯區分","(B) 極少見影響內臟器官，預後良好","(C) 常有雷諾氏現象（Raynaud phenomenon）","(D) 線形硬皮症（linear morphea）好犯於兒童之四肢"],"answer":2,"image":""},{"id":"md4-105-2-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"105年第2次第43題","year":105,"session":2,"number":43,"question":"68歲男性，長期使用多種藥物，最近發現在鼻、頰及耳部有藍灰色色素沉著，下列何種藥物，可能與其皮膚症狀相關？","options":["(A) amiodarone","(B) aspirin","(C) omeprazole","(D) magnesium oxide"],"answer":0,"image":"md4-105-2-43.jpeg"},{"id":"md4-105-2-44","subject":"md4","topic":"兒科-內分泌遺傳","meta":"105年第2次第44題","year":105,"session":2,"number":44,"question":"20歲男性，智力輕度發展遲緩，因為癲癇送到急診，理學檢查發現腰部有一個小脫色斑，以及臉上的丘疹，如圖所示，最可能的診斷為何？","options":["(A) 結節性硬化症（tuberous sclerosis）","(B) 第一型神經纖維瘤症（neurofibromatosis type I）","(C) 白斑（vitiligo）","(D) 漢生病（leprosy）"],"answer":0,"image":"md4-105-2-44.jpeg"},{"id":"md4-105-2-45","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"105年第2次第45題","year":105,"session":2,"number":45,"question":"惡性黑色棘皮症（malignant acanthosis nigricans）最常合併那種系統的腫瘤？","options":["(A) 呼吸系統","(B) 腸胃系統","(C) 生殖系統","(D) 泌尿系統"],"answer":1,"image":""},{"id":"md4-105-2-46","subject":"md4","topic":"神經-中風","meta":"105年第2次第46題","year":105,"session":2,"number":46,"question":"80歲女性，有高血壓與心房顫動病史，突發左側顏面與左側肢體無力，左上肢肌力為1分，左下肢肌力為3分，兩眼偏向右看，無明顯的視野缺損與忽略。病灶最可能在何處？","options":["(A) 右大腦額葉（frontal lobe）","(B) 右大腦頂葉（parietal lobe）","(C) 右內囊與被殼（internal capsule and putamen）","(D) 右橋腦（pons）"],"answer":0,"image":""},{"id":"md4-105-2-47","subject":"md4","topic":"神經-中風","meta":"105年第2次第47題","year":105,"session":2,"number":47,"question":"73歲女性，過去有高血壓與心律不整病史，突發左下肢無力、全身動作與說話變少，神經學檢查顯示意識正常，語言理解能力尚可，左下肢肌力下降，其它肢體肌力尚正常，臨床診斷為急性腦梗塞中風。最可能的病變血管為何？","options":["(A) 右側前大腦動脈（anterior cerebral artery）","(B) 右側中大腦動脈（middle cerebral artery）","(C) 右側後大腦動脈（posterior cerebral artery）","(D) 基底動脈（basilar artery）"],"answer":0,"image":""},{"id":"md4-105-2-48","subject":"md4","topic":"神經-中風","meta":"105年第2次第48題","year":105,"session":2,"number":48,"question":"李先生，75歲，有高血壓、糖尿病病史，因突發性右側肢體乏力，兩側眼球偏轉到左側，合併意識障礙而住院診治。如果李先生是腦梗塞患者，下列何者正確？","options":["(A) 是右側中大腦動脈區梗塞","(B) 腦水腫（edema）在梗塞後第1天最嚴重，3天後慢慢緩解","(C) 病人是小血管小洞性梗塞（small-vessel lacunar infarction）","(D) 預測病人預後不佳，有高死亡率"],"answer":3,"image":""},{"id":"md4-105-2-49","subject":"md4","topic":"神經-中風","meta":"105年第2次第49題","year":105,"session":2,"number":49,"question":"關於皮質傳播性抑制（cortical spreading depression）的敘述，下列何者正確？","options":["(A) 由腦部額葉向枕葉方向傳遞","(B) 傳導速度是每分鐘2～3公分","(C) 後續會有血流降低的現象","(D) 傳導的區域和血管分布的位置相關"],"answer":2,"image":""},{"id":"md4-105-2-50","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"105年第2次第50題","year":105,"session":2,"number":50,"question":"下列關於失神性癲癇（absence seizures）的敘述，何者錯誤？","options":["(A) 診斷的依據是腦電圖出現不對稱、不定頻率的棘慢複合波（spike-and-wave complexes）","(B) 腦雙側對稱3Hz的棘慢複合波容易以過度換氣誘發","(C) 絕大部分的失神性癲癇在青少年期開始發作","(D) 失神性癲癇發作時常有眨眼、咀嚼或上肢肌張力微增的現象"],"answer":[0,2],"image":"","answer_note":"更正:第50題答Ａ、Ｃ給分"},{"id":"md4-105-2-51","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"105年第2次第51題","year":105,"session":2,"number":51,"question":"下列關於青少年肌陣攣癲癇（juvenile myoclonic epilepsy）的敘述，何者錯誤？","options":["(A) 發作都是全面癲癇發作（generalized seizures）","(B) 以晨間睡醒時肌陣攣發作（myoclonic seizures）為主","(C) 大部分無法痊癒","(D) 目前尚未發現家族癲癇病史的相關性"],"answer":3,"image":""},{"id":"md4-105-2-52","subject":"md4","topic":"兒科-感染神經","meta":"105年第2次第52題","year":105,"session":2,"number":52,"question":"下列關於簡單型熱痙攣（simple febrile seizure）之敘述，何者錯誤？","options":["(A) 於一歲以前發作者，易再發","(B) 與將來是否智能不足無關","(C) 與將來是否有行為異常無關","(D) 即使神經理學檢查正常，其死亡率仍較正常人顯著增加"],"answer":3,"image":""},{"id":"md4-105-2-53","subject":"md4","topic":"神經-失智退化運動障礙","meta":"105年第2次第53題","year":105,"session":2,"number":53,"question":"阿茲海默症（Alzheimer disease）之患者，其腦部病理變化和臨床症狀最有相關性者是：","options":["(A) Negri body","(B) neurofibrillary tangles","(C) Lewy body","(D) Hirano body"],"answer":1,"image":""},{"id":"md4-105-2-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"105年第2次第54題","year":105,"session":2,"number":54,"question":"下列有關急性發炎性脫髓鞘多發性神經病變症候群（Guillain-Barré syndrome）之敘述，何者錯誤？","options":["(A) 大約30％病患在疾病發作之前，會有輕度之呼吸道或腸胃道感染症狀","(B) 主要臨床表現為漸進式肌肉無力，其病程進展時間約為數天至二週，甚至更長時間","(C) 通常同時侵犯肢體之近端及遠端肌肉","(D) 肌腱反射常會下降或消失"],"answer":[0,2],"image":"","answer_note":"更正:第54題答Ａ、Ｃ給分"},{"id":"md4-105-2-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"105年第2次第55題","year":105,"session":2,"number":55,"question":"26歲陳小姐在一家化學工廠擔任會計的工作，3個月來一到黃昏右眼皮就會往下垂，晚上看電視時，影像顯得模糊不清，稍作休息會有所改善；這2天喝水常會嗆到，因情況持續，而至門診求助。最可能的診斷為何？","options":["(A) 重症肌無力症（myasthenia gravis）","(B) 多發性肌炎（polymyositis）","(C) 多發性顱神經病變","(D) 代謝性肌病變"],"answer":0,"image":""},{"id":"md4-105-2-56","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"105年第2次第56題","year":105,"session":2,"number":56,"question":"愛滋病毒感染和器官移植後，長期接受免疫抑制劑治療的病人會增加下列何種腦腫瘤的罹患率？","options":["(A) 原發性中樞神經淋巴瘤（primary CNS lymphoma）","(B) 腦膜瘤（meningioma）","(C) 室管膜瘤（ependymoma）","(D) 顱咽管瘤（craniopharyngioma）"],"answer":0,"image":""},{"id":"md4-105-2-57","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"105年第2次第57題","year":105,"session":2,"number":57,"question":"下列那些腦膜炎，如果沒有及早治療，容易發生顱底腦膜嚴重滲出性發炎變化（basilar meningeal exduate），導致次發性腦血管梗塞（cerebral infarction）？①腮腺炎病毒腦膜炎（mumps） ②巨細胞病毒性腦膜炎（CMV） ③結核菌腦膜炎 ④ 隱球菌腦膜炎","options":["(A) ①②","(B) ②③","(C) ①④","(D) ③④"],"answer":3,"image":""},{"id":"md4-105-2-58","subject":"md4","topic":"精神-精神官能症","meta":"105年第2次第58題","year":105,"session":2,"number":58,"question":"有關慢性疲勞症候群之敘述，下列何者正確？","options":["(A) 最好發於40～60歲之男性","(B) 常與EB病毒（EBV）感染相關","(C) 絕大多數是心理因素引起","(D) 與免疫功能異常無關"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第58題一律給分。 (原公告答案 B)"},{"id":"md4-105-2-59","subject":"md4","topic":"神經-失智退化運動障礙","meta":"105年第2次第59題","year":105,"session":2,"number":59,"question":"劉太太，現年45歲。最近四年雙手發抖相當嚴重，右手幾乎無法用湯匙舀湯或用筷子夾菜，無法寫字，左手也無法拿碗，然而她仍然可以提水桶到花園澆花。經詢問病史，雙手發抖已將近20年，從右手開始，接著左手也發抖。她的父親也有類似長期雙手發抖現象，只是比較輕微。以及一位哥哥則有頭部顫抖的現象。除此之外，身體沒有其他異狀，也沒有慢性疾病。下列臨床診斷何者最有可能？","options":["(A) 全身性肌張力不全（generalized dystonia）","(B) 脊髓小腦共濟失調症（spinocerebellar ataxia）","(C) 巴金森病（Parkinson disease）","(D) 原發性顫抖症（essential tremor）"],"answer":3,"image":""},{"id":"md4-105-2-60","subject":"md4","topic":"神經-失智退化運動障礙","meta":"105年第2次第60題","year":105,"session":2,"number":60,"question":"承上題，下列治療藥物何者最有效？","options":["(A) 抗乙醯膽鹼藥物（anticholinergics）","(B) β阻抗劑（β-blocker）","(C) 左多巴（Levodopa）","(D) clonazepam"],"answer":1,"image":""},{"id":"md4-105-2-61","subject":"md4","topic":"精神-精神病","meta":"105年第2次第61題","year":105,"session":2,"number":61,"question":"依據美國精神醫學會出版的「精神疾病診斷和統計手冊第四版」，下列有關第二型雙極性疾患（bipolar II disorder）之敘述，何者正確？","options":["(A) 包括輕躁發作（hypomanic episode）及輕鬱發作（minor depressive episode）","(B) 憂鬱症病人服用抗鬱劑出現輕躁時，診斷應改成第一型雙極性疾患（bipolar I disorder）","(C) 第二型雙極性疾患（bipolar II disorder）發病年紀較第一型雙極性疾患（bipolar I disorder）早，且有較多的婚姻問題","(D) 第二型雙極性疾患（bipolar II disorder）企圖自殺及自殺死亡率較第一型雙極性疾患（bipolar I disorder）為低"],"answer":2,"image":""},{"id":"md4-105-2-62","subject":"md4","topic":"精神-精神病","meta":"105年第2次第62題","year":105,"session":2,"number":62,"question":"一名26歲男性，已經長達一ࠕ以上變得社交退縮，足不出戶。近六個月以來常ࡃ有人跟蹤他，要陷害他，有時自言自語好像在和別人對話，若該病人確診為思覺失調症（schizophrenia），下࠻敘述何者最正確？","options":["(A) 心਺治ऋ的第一選擇是精神分析","(B) 藥物治ऋ第一選擇是多巴胺再回收抑制劑（dopamine reuptake inhibitors）","(C) 合併尼古丁（nicotine）濫用時，病人血中的抗精神病藥藥物濃度會增加","(D) 神經科學文獻報告，思覺失調症（schizophrenia）患者腦部會有神經元樹突或軸突減少的情形"],"answer":3,"image":""},{"id":"md4-105-2-63","subject":"md4","topic":"精神-精神病","meta":"105年第2次第63題","year":105,"session":2,"number":63,"question":"有關使用傳統（第一代）抗精神病藥（antipsychotics）治療思覺失調症（schizophrenia），若引起錐體外症候群（extrapyramidal syndrome）時，下列敘述何者正確？","options":["(A) 智力障礙（mental retardation）與精神分裂症病人相較，前者較不會有錐體外症候群的副作用","(B) 把藥物換成第二代抗精神病藥並無法改善此錐體外症候群之副作用","(C) 換成高效價（high potency）的抗精神病藥可以改善","(D) 抗膽鹼藥物（anticholinergics）可用來減少該副作用"],"answer":3,"image":""},{"id":"md4-105-2-64","subject":"md4","topic":"精神-精神官能症","meta":"105年第2次第64題","year":105,"session":2,"number":64,"question":"依據社會再適應評估表（social readjustment rating scale），下列何種生活事件所造成的壓力強度最大？","options":["(A) 配偶死亡","(B) 離婚","(C) 入獄","(D) 子女死亡"],"answer":0,"image":""},{"id":"md4-105-2-65","subject":"md4","topic":"精神-精神病","meta":"105年第2次第65題","year":105,"session":2,"number":65,"question":"有關思覺失調症（schizophrenia）之預後，下列何者是預後較好的因子？","options":["(A) 病發前無誘發因子（precipitating factor）","(B) 負性症狀（negative symptoms）","(C) 較早發病","(D) 憂鬱症狀"],"answer":3,"image":""},{"id":"md4-105-2-66","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"105年第2次第66題","year":105,"session":2,"number":66,"question":"關於老人自殺相關的敘述，下列何者錯誤？","options":["(A) 65歲以上之老年族群自殺風險性比其他族群高","(B) 老人往往採取較激烈的自殺方式，而且男性自殺身亡者比例較高","(C) 和其他族群相較之下，老人自殺者較常合併酒精濫用","(D) 失落和身體疾病纏身是老人自殺最常見的促使因素（precipitants）"],"answer":2,"image":""},{"id":"md4-105-2-67","subject":"md4","topic":"精神-精神病","meta":"105年第2次第67題","year":105,"session":2,"number":67,"question":"如欲選擇valproate來治療急性躁症發作（acute mania），有效的血中濃度為多少µg/mL？","options":["(A) 0.6～1.2","(B) 4～10","(C) 10～15","(D) 50～120"],"answer":3,"image":""},{"id":"md4-105-2-68","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"105年第2次第68題","year":105,"session":2,"number":68,"question":"夢遊症（sleepwalking disorder）通常發生在睡眠腦波圖（EEG）的那一個時期？","options":["(A) stage I","(B) stage II","(C) stage III & IV","(D) REM（rapid eye movement）sleep"],"answer":2,"image":""},{"id":"md4-105-2-69","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"105年第2次第69題","year":105,"session":2,"number":69,"question":"下列何者違反有助於睡眠之睡眠衛生法則（sleep hygiene）？","options":["(A) 每人每天均應睡足7小時才足夠","(B) 若晚上失眠時，不建議在隔日白天即刻補足睡眠","(C) 避免入睡前看電視","(D) 晚餐後不宜飲用可樂、熱可可及巧克力"],"answer":0,"image":""},{"id":"md4-105-2-70","subject":"md4","topic":"精神-器質性與物質使用","meta":"105年第2次第70題","year":105,"session":2,"number":70,"question":"戒菸的人尼古丁戒斷症狀，下列敘述何者正確？","options":["(A) 心跳減慢","(B) 食慾下降","(C) 血壓上升","(D) 戒斷症狀在戒菸後4至6小時內達高峰"],"answer":0,"image":""},{"id":"md4-105-2-71","subject":"md4","topic":"精神-器質性與物質使用","meta":"105年第2次第71題","year":105,"session":2,"number":71,"question":"關於酒精相關疾患，下列何者錯誤？","options":["(A) Wernicke症候群是急性症候群","(B) Wernicke-Korsakoff症候群以thiamine治療","(C) Korsakoff症候群會近期記憶變差","(D) Korsakoff症候群治療後大多可完全恢復"],"answer":3,"image":""},{"id":"md4-105-2-72","subject":"md4","topic":"精神-器質性與物質使用","meta":"105年第2次第72題","year":105,"session":2,"number":72,"question":"下列何者不是搖頭丸（3,4-methylene-dioxymethamphetamine）引起的症狀？","options":["(A) 心跳加速，血壓升高","(B) 對感官刺激變得異常敏感，警醒度降低","(C) 視覺模糊","(D) 會導致情緒不悅，也可能引起妄想或幻覺"],"answer":1,"image":""},{"id":"md4-105-2-73","subject":"md4","topic":"精神-器質性與物質使用","meta":"105年第2次第73題","year":105,"session":2,"number":73,"question":"可用於鑑別診斷活動量較低之譫妄（delirium）與憂鬱症最佳的檢查為何？","options":["(A) 脊椎穿刺脊髓液檢查","(B) 腦波","(C) 腦部斷層掃描","(D) 生化檢查"],"answer":1,"image":""},{"id":"md4-105-2-74","subject":"md4","topic":"兒科-感染神經","meta":"105年第2次第74題","year":105,"session":2,"number":74,"question":"下列何者並非自閉症的核心症狀？","options":["(A) 社交互動缺損","(B) 智能障礙","(C) 溝通能力異常","(D) 侷限、反覆、固著的行為／興趣／活動"],"answer":1,"image":""},{"id":"md4-105-2-75","subject":"md4","topic":"精神-精神病","meta":"105年第2次第75題","year":105,"session":2,"number":75,"question":"僵直（catatonia）可見於多種精神疾病，以下何者非catatonia之症狀？","options":["(A) 不語（mutism）","(B) 蠟曲現象（waxy flexibility）","(C) 仿說（echolalia）","(D) 靜坐不能（akathisia）"],"answer":3,"image":""},{"id":"md4-105-2-76","subject":"md4","topic":"兒科-消化系統疾病","meta":"105年第2次第76題","year":105,"session":2,"number":76,"question":"12歲男生因急性發作腹痛、嘔吐、發燒而至急診室，注射對比劑後的下腹部電腦斷層掃描影像如圖，則最可能之原因為何？","options":["(A) 急性闌尾炎破裂","(B) 腎結石","(C) 血吸蟲病","(D) 膽結石"],"answer":0,"image":"md4-105-2-76.jpeg"},{"id":"md4-105-2-77","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"105年第2次第77題","year":105,"session":2,"number":77,"question":"一位30歲男性，和朋友喝酒吃完海鮮後，突然身上出現如圖病灶，發燙與奇癢無比，下列敘述何者錯誤？","options":["(A) 可能是過敏反應，首要評估有無呼吸道的問題","(B) 可給予抗組織胺（antihistamine）注射","(C) 可考慮給予口服類固醇","(D) H2接受器抑制劑（H2 receptor blocker），如ranitidine是沒有治療效果"],"answer":3,"image":"md4-105-2-77.jpeg"},{"id":"md4-105-2-78","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"105年第2次第78題","year":105,"session":2,"number":78,"question":"顳動脈炎（temporal arteritis）是一種較常發生於女性的血管炎，下列敘述何者最不恰當？","options":["(A) 好發年紀大於50歲","(B) 通常為單側","(C) 觸診可發現顳動脈炎（temporal arteritis）的脈動增強","(D) 常合併肌肉疼痛"],"answer":2,"image":""},{"id":"md4-105-2-79","subject":"md4","topic":"醫學倫理與法規","meta":"105年第2次第79題","year":105,"session":2,"number":79,"question":"周太太在懷孕17週時接受羊水穿刺（amniocentesis），檢查結果發現胎兒有唐氏症（Down syndrome），當時家境困苦的周太太仍決定保留胎兒。到23週時，超音波檢查發現羊水過少，胎兒有先天性心臟病「法洛氏四重症（tetralogy of Fallot）」，且兩側腎臟很小。經過2週的家族討論，產婦要求進行墮胎，因為晚期墮胎恐怕引來「殺胎」爭議，婦產科醫師拒絕執行。對此事件的下列評斷，何者最恰當？","options":["(A) 經醫學專家討論同意後，可施行晚期墮胎","(B) 可催生自然產下後，不給予奶水而由嬰兒自然死亡","(C) 未經法院核可之「殺胎」醫療行為屬犯法","(D) 臺灣民法規定胎兒雖未出生，已具備權利能力"],"answer":0,"image":""},{"id":"md4-105-2-80","subject":"md4","topic":"醫學倫理與法規","meta":"105年第2次第80題","year":105,"session":2,"number":80,"question":"45歲的張先生在中年失業經濟窘困之際，他的太太以家庭暴力之故訴請離婚成功，最令張先生憤恨的是離婚的太太瓜分了他的房產。這天，他因為失眠到你的門診拿藥，他除了抒發憤怒情緒外，還說要去燒了太太的房子。你判斷張先生採取傷害前妻行動之機會頗高，此時該如何處理？","options":["(A) 努力勸導，並清楚記載病歷","(B) 通報社工並採取保護前妻之措施","(C) 請張先生簽切結書聲明不會如此行動","(D) 給予安眠及抗焦慮藥物"],"answer":1,"image":""},{"id":"md4-106-1-1","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第1次第1題","year":106,"session":1,"number":1,"question":"2個月大女嬰，咳嗽已有3個星期之久，近幾天甚至偶爾咳至唇色發紫，這陣子並無發燒現象。血液檢查WBC為26,500/mm3，neutrophil為25%，lymphocyte為70%，鼻咽檢體的RSV（respiratory syncytial virus）antigen檢查結果為陰性反應，其最有可能之致病菌為何？","options":["(A) adenovirus","(B) Bordetella pertussis","(C) enterovirus","(D) Streptococcus pneumoniae"],"answer":1,"image":""},{"id":"md4-106-1-2","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第1次第2題","year":106,"session":1,"number":2,"question":"關於新生兒披衣菌感染（Chlamydia trachomatis）的肺炎，下列敘述何者錯誤？","options":["(A) 常有嗜伊紅性白血球增多（eosinophilia）的現象","(B) 聽診時常常可以聽到wheezing","(C) 通常不會發燒","(D) 可以用紅黴素（erythromycin）治療"],"answer":1,"image":""},{"id":"md4-106-1-3","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"106年第1次第3題","year":106,"session":1,"number":3,"question":"15個月大的孩子，因為兩個月前得到川崎症（Kawasaki disease）而住院，且接受免疫球蛋白靜脈注射治療。現已康復，想要補打疫苗，下列何者為最適合接種的疫苗？","options":["(A) 麻疹、德國麻疹、腮腺炎混合疫苗","(B) 肺炎鏈球菌疫苗","(C) 水痘疫苗","(D) 口服輪狀病毒疫苗"],"answer":1,"image":""},{"id":"md4-106-1-4","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"106年第1次第4題","year":106,"session":1,"number":4,"question":"有一孕期28週出生的早產兒，出院後小寶寶之發展追蹤評估中，若有下列那一項發現，需轉介兒童發展聯合評估中心做進一步處置？","options":["(A) 出生後2個月仍無有意義的微笑（smile）","(B) 出生後5個月仍不會翻身（roll over）","(C) 出生後2個月脖子仍無法穩定的撐起頭","(D) 出生後13個月仍無法在輔助下以下肢支撐身體站立起來"],"answer":3,"image":""},{"id":"md4-106-1-5","subject":"md4","topic":"兒科-內分泌遺傳","meta":"106年第1次第5題","year":106,"session":1,"number":5,"question":"新生男嬰，呈現肌張力不足（hypotonia）、餵食困難，膚色較白且有雙側隱睪，手掌、腳掌都比較小，造成他異常最可能的原因是：","options":["(A) 染色體之微缺失（microdeletion）","(B) 染色體複製時易位（translocation）","(C) 性染色體異常","(D) 生產傷害"],"answer":0,"image":""},{"id":"md4-106-1-6","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"106年第1次第6題","year":106,"session":1,"number":6,"question":"有關Apgar score的敘述，下列何者正確？","options":["(A) Apgar score分數愈低表示嬰兒愈健康","(B) 呼吸是嬰兒Apgar score的重要指標之一","(C) 出生1分鐘時嬰兒的Apgar score比5分鐘的Apgar score更與預後有關","(D) 母親使用硫酸鎂不會影響嬰兒Apgar score"],"answer":1,"image":""},{"id":"md4-106-1-7","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"106年第1次第7題","year":106,"session":1,"number":7,"question":"兒童出現下列何種症狀時，不需要考慮有腎臟疾病的存在？","options":["(A) 長期小便有泡泡（foamy urine）","(B) 多尿（polyuria）","(C) 生長遲滯（growth retardation）","(D) 尿道口疼痛（pain of urethral orifice）"],"answer":3,"image":""},{"id":"md4-106-1-8","subject":"md4","topic":"兒科-感染神經","meta":"106年第1次第8題","year":106,"session":1,"number":8,"question":"舟形頭（scaphocephaly）是因那一個骨縫先天性過早癒合所導致？","options":["(A) sagittal suture","(B) lambdoid suture","(C) coronal suture","(D) metopic suture"],"answer":0,"image":""},{"id":"md4-106-1-9","subject":"md4","topic":"兒科-內分泌遺傳","meta":"106年第1次第9題","year":106,"session":1,"number":9,"question":"下列那一項檢查與生長激素缺乏症（growth hormone deficiency）的診斷無關？","options":["(A) 血清第1型似胰島素生長因子（insulin-like growth factor-1, IGF-I）濃度","(B) 血清第3型似胰島素生長因子結合蛋白（insulin-like growth factor binding protein 3, IGF-BP3）濃度","(C) 升糖素刺激試驗（glucagon stimulation test）","(D) 葡萄糖耐受性試驗（glucose tolerance test）"],"answer":3,"image":""},{"id":"md4-106-1-10","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第1次第10題","year":106,"session":1,"number":10,"question":"8歲氣喘男童，最近3個月內，於白天出現氣喘症狀的次數平均一星期少於1次，一個月內半夜因咳嗽而醒來也少於2次，其FEV1＞80%的預測值，給與下列何種藥物最適當？","options":["(A) 吸入型短效支氣管擴張劑（inhaled short-acting β2 agonist）","(B) 吸入型長效支氣管擴張劑（inhaled long-acting β2 agonist）","(C) 吸入型類固醇（inhaled corticosteroid）","(D) 吸入型類固醇倂用口服白三烯素受體結抗劑（inhaled corticosteroid + oral leukotriene receptor antagonist）"],"answer":[0,2,3],"image":"","answer_note":"更正:第10題答Ａ、Ｃ、Ｄ給分"},{"id":"md4-106-1-11","subject":"md4","topic":"兒科-感染神經","meta":"106年第1次第11題","year":106,"session":1,"number":11,"question":"兒童的感染性關節炎（infective arthritis），最常見的菌種為：","options":["(A) 金黃色葡萄球菌（Staphylococcus aureus）","(B) 大腸桿菌（Escherichia coli）","(C) 沙門氏菌（Salmonella species）","(D) 黴漿菌（Mycoplasma pneumoniae）"],"answer":0,"image":""},{"id":"md4-106-1-12","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"106年第1次第12題","year":106,"session":1,"number":12,"question":"下列何者不屬於先天性血小板缺乏（congenital thrombocytopenia）的疾病？","options":["(A) Wiskott-Aldrich syndrome","(B) neonatal alloimmune thrombocytopenic purpura","(C) amegakaryocytic thrombocytopenia","(D) Fanconi anemia"],"answer":1,"image":""},{"id":"md4-106-1-13","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第1次第13題","year":106,"session":1,"number":13,"question":"2個月大的女嬰，出生後不久即被發現呼吸急促合併喘鳴聲（stridor），氣管鏡檢查發現氣管狹窄，食道攝影如圖所示。下列何者為最可能的診斷？","options":["(A) 雙主動脈弓（double aortic arch）","(B) 右主動脈弓併左開放性動脈導管（right aortic arch & left PDA）","(C) 肺動脈吊帶（pulmonary sling）","(D) 持續第五動脈弓（persistent fifth arch）"],"answer":2,"image":"md4-106-1-13.jpeg"},{"id":"md4-106-1-14","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第1次第14題","year":106,"session":1,"number":14,"question":"特定疾病或狀況，容易造成兒童阻塞性呼吸暫停（obstructive sleep apnea）或換氣不足（hypoventilation），導致睡眠障礙、生長不良，甚至腦缺氧，下列何者最不可能？","options":["(A) achondroplasia合併midface hypoplasia","(B) 腭裂（cleft palate）尚未經手術修補","(C) Pierre-Robin sequence合併micrognathia","(D) Prader-Willi syndrome併發肥胖（obesity）"],"answer":1,"image":""},{"id":"md4-106-1-15","subject":"md4","topic":"兒科-感染神經","meta":"106年第1次第15題","year":106,"session":1,"number":15,"question":"2歲女童，就診主訴為發高燒3天，喉嚨痛、口水直流，媽媽發現女童的手腳出現許多紅疹，同時女童這兩天幾乎無法進食，尿量明顯減少。身體診察發現喉嚨軟顎上出現水疱，手掌、腳掌、臀部也出現疹子（如圖所示），下列敘述何者錯誤？","options":["(A) 腸病毒引起的手足口症的典型表現","(B) 治療的首選藥物是Acyclovir","(C) 腸病毒71型較易引起重症","(D) 腸病毒的傳染途徑，主要經由糞口傳染或藉由呼吸道分泌物傳播"],"answer":1,"image":"md4-106-1-15.jpeg"},{"id":"md4-106-1-16","subject":"md4","topic":"兒科-感染神經","meta":"106年第1次第16題","year":106,"session":1,"number":16,"question":"新生兒由於子宮內生長遲滯（intrauterine growth retardation），腦部超音波（brain ultrasonography）檢查發現，有腦室週邊鈣化（periventricular calcification）與腦室擴大（ventriculomegaly）的異常，聽力篩檢亦出現異常。此新生兒最可能的診斷為：","options":["(A) congenital human parvovirus B19 infection","(B) congenital rubella syndrome","(C) congenital human herpes simplex virus infection","(D) congenital cytomegalovirus infection"],"answer":3,"image":""},{"id":"md4-106-1-17","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"106年第1次第17題","year":106,"session":1,"number":17,"question":"先天性橫膈膜疝氣（congenital diaphragmatic hernia），最有可能併發的嚴重問題為何？","options":["(A) 肺臟發育不全（pulmonary hypoplasia）","(B) 先天性心臟病（congenital heart disease）","(C) 食道閉鎖氣管食道廔管（esophageal atresia with tracheoesophageal fistula）","(D) 後鼻孔閉鎖（choanal atresia）"],"answer":0,"image":""},{"id":"md4-106-1-18","subject":"md4","topic":"兒科-消化系統疾病","meta":"106年第1次第18題","year":106,"session":1,"number":18,"question":"Hepatoportoenterostomy procedure是治療膽道閉鎖（biliary atresia）病童的重要方法，下列何種情形，可預期手術後的預後較差？","options":["(A) 手術後四週大便為深黃色","(B) 病理檢查顯微鏡下膽小管管徑小於100µm","(C) 出生後6週內接受手術","(D) 血型為O型"],"answer":1,"image":""},{"id":"md4-106-1-19","subject":"md4","topic":"兒科-消化系統疾病","meta":"106年第1次第19題","year":106,"session":1,"number":19,"question":"下列導致兒童患門脈高壓（portal hypertension）的疾病，何者預後最差？","options":["(A) 肝外門靜脈栓塞（extrahepatic portal vein obstruction）","(B) 新生兒曾插入臍靜脈管（catheterization of umbilical vein）","(C) 硬化性膽管炎（sclerosing cholangitis）","(D) 脾臟動靜脈瘻管（splenic arteriovenous fistula）"],"answer":2,"image":""},{"id":"md4-106-1-20","subject":"md4","topic":"兒科-消化系統疾病","meta":"106年第1次第20題","year":106,"session":1,"number":20,"question":"關於食道弛緩不能（achalasia），下列敘述何者錯誤？","options":["(A) 特徵為缺乏食道蠕動，下食道括約肌無法完全放鬆，進而增加下食道括約肌的壓力","(B) 臨床表現有嘔吐、吞嚥困難、體重減輕、胸痛、逆流及咳嗽等","(C) 食道壓力檢測（manometry）可協助診斷","(D) 以內視鏡注射肉毒桿菌毒素（botulinum toxin）可完全治癒"],"answer":3,"image":""},{"id":"md4-106-1-21","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"106年第1次第21題","year":106,"session":1,"number":21,"question":"下列引起兒童泌尿道感染（urinary tract infection）的細菌，何者最為罕見？","options":["(A) Streptococcus spp.","(B) Escherichia coli","(C) Klebsiella spp.","(D) Proteus spp."],"answer":0,"image":""},{"id":"md4-106-1-22","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"106年第1次第22題","year":106,"session":1,"number":22,"question":"5歲男童因為腹瀉3天，有脫水現象被送到急診。抽血檢查發現，血清鈉離子：142 mEq/L，鉀離子：3.6 mEq/L，氯離子：115 mEq/L，肌酐酸（creatinine）：1.1 mg/dL。動脈血液氣體分析為pH=7.12，PCO=50 mmHg，HCO-=14 mmol/L。下列何者23正確？","options":["(A) normal anion gap metabolic acidosis with respiratory acidosis","(B) high anion gap metabolic acidosis with respiratory acidosis","(C) normal anion gap metabolic acidosis with respiratory compensation","(D) normal anion gap metabolic acidosis with respiratory alkalosis"],"answer":[0,1],"image":"","answer_note":"更正:第22題答Ａ、Ｂ給分"},{"id":"md4-106-1-23","subject":"md4","topic":"兒科-感染神經","meta":"106年第1次第23題","year":106,"session":1,"number":23,"question":"有關單純型熱性痙攣（simple febrile seizure）的敘述，下列何者錯誤？","options":["(A) 可發生在發展正常的幼兒","(B) 家族中有熱性痙攣病史的機率較一般人高","(C) 重複發作的病兒須長期服用癲癇藥物","(D) 抽搐發作時間少於15分鐘"],"answer":2,"image":""},{"id":"md4-106-1-24","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"106年第1次第24題","year":106,"session":1,"number":24,"question":"一個孩子會跑、會正確的指認身體每個部位，依照正常的發展里程，此兒童最接近的年齡為何？","options":["(A) 2歲","(B) 1歲","(C) 1歲6個月","(D) 9個月"],"answer":[0,2],"image":"","answer_note":"更正:第24題答Ａ、Ｃ給分"},{"id":"md4-106-1-25","subject":"md4","topic":"兒科-內分泌遺傳","meta":"106年第1次第25題","year":106,"session":1,"number":25,"question":"正常新生兒，促甲狀腺素（thyroid-stimulating hormone, TSH）之敘述，下列何者錯誤？","options":["(A) 足月新生兒在出生30分鐘內，TSH最高可到達20 mIU/L","(B) TSH在出生24小時後快速減少","(C) TSH在出生後五天呈現＜10 mIU/L","(D) 經過新生兒期（neonatal period）之後，TSH ＜6 mIU/L"],"answer":0,"image":""},{"id":"md4-106-1-26","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第1次第26題","year":106,"session":1,"number":26,"question":"14歲男童患有氣喘，醫師希望以吸入型類固醇（inhaled corticosteroid, ICS）來控制其病情，有關吸入型類固醇（ICS）之使用，下列何者錯誤？","options":["(A) ICS是所有類型的氣喘病人的第一線控制型用藥","(B) 適當使用ICS，可減少氣喘病人的死亡率","(C) ICS的使用，可能引起該病童發生聲音沙啞及咽喉黴菌感染","(D) 使用吸藥輔助艙（spacer），可減少咽喉黴菌感染的發生"],"answer":0,"image":""},{"id":"md4-106-1-27","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"106年第1次第27題","year":106,"session":1,"number":27,"question":"有關Bruton agammaglobulinemia的特徵，下列何者錯誤？","options":["(A) 為體染色體顯性遺傳（autosomal dominant inheritance）疾病，且血中CD19陽性的B細胞通常小於1%","(B) 血中IgG、IgA、IgE濃度很低","(C) 容易有反覆性細菌性肺炎、中耳炎及鼻竇炎","(D) 反覆性細菌性感染常在嬰兒期6個月後出現"],"answer":0,"image":""},{"id":"md4-106-1-28","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"106年第1次第28題","year":106,"session":1,"number":28,"question":"有關兒童白血病的敘述，下列何者錯誤？","options":["(A) 慢性骨髓性白血病（chronic myelogenous leukemia，CML）在兒童發生的比率，相對於成人是非常低的","(B) 兒童慢性骨髓性白血病（CML）大部分都有t（9；22）（q34；q11）的染色體易位，因而產生了費城染色體（Philadelphia chromosome）","(C) 過去兒童慢性骨髓性白血病（CML）的預後並不好，必需盡早接受幹細胞移植，但自從有了基利克（imatinib, gleevec®）的問世，預後已顯著改善","(D) 和慢性骨髓性白血病（CML）相反，急性淋巴性白血病（acute lymphoblastic leukemia, ALL）患童，若有t（9；22）的染色體易位，會有較佳的預後"],"answer":3,"image":""},{"id":"md4-106-1-29","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"106年第1次第29題","year":106,"session":1,"number":29,"question":"有關兒童白血病治療的預後因子（prognostic factor），下列何者是較好的（favorable）預後因子？","options":["(A) 有t（12；21）的染色體易位","(B) 年齡小於1歲","(C) 有t（4；11）的染色體易位","(D) 骨髓細胞染色體數目小於44個（hypodiploidy）"],"answer":0,"image":""},{"id":"md4-106-1-30","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第1次第30題","year":106,"session":1,"number":30,"question":"下列血液中電解質的異常，常會使嬰幼兒心電圖出現QT波之延長（QT Prolongation）的現象，除了：","options":["(A) 低血鉀症（hypokalemia）","(B) 低血鈉症（hyponatremia）","(C) 低血鎂症（hypomagnesemia）","(D) 低血鈣症（hypocalcemia）"],"answer":1,"image":""},{"id":"md4-106-1-31","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第1次第31題","year":106,"session":1,"number":31,"question":"下列何種疾病最不常合併有accessory pathway，也較少引致心室上心搏過速（supraventricular tachycardia）？","options":["(A) 愛伯斯坦氏異常（Ebstein anomaly）","(B) 兩側右心房症（right atrial isomerism）","(C) 法洛氏四重症（tetrology of Fallot）","(D) Wolff–Parkinson–White症候群（WPW syndrome）"],"answer":2,"image":""},{"id":"md4-106-1-32","subject":"md4","topic":"兒科-內分泌遺傳","meta":"106年第1次第32題","year":106,"session":1,"number":32,"question":"在染色體微小缺失（microdeletion）的疾病中，Sotos syndrome的敘述，下列何者錯誤？","options":["(A) 為15q11 deletion","(B) 過度成長（overgrowth）","(C) 大頭症（macrocephaly）","(D) 智能障礙（mental disabilities）"],"answer":0,"image":""},{"id":"md4-106-1-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"106年第1次第33題","year":106,"session":1,"number":33,"question":"在尿素循環障礙（urea cycle defects）疾病中，下列敘述何者錯誤？","options":["(A) 除了瓜胺酸血症（citrullinemia）是性聯遺傳以外，其他的疾病，均為體染色體隱性遺傳（autosomal recessive）疾病","(B) 患有尿素循環障礙的嬰兒，早期的症狀，常是餵食欠佳、嘔吐、昏睡、焦躁不安及呼吸急促","(C) 維持性治療的原則是低蛋白飲食、補充必需胺基酸及建立氨排出之替代路徑","(D) 急性期血氨的移除非常重要"],"answer":0,"image":""},{"id":"md4-106-1-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"106年第1次第34題","year":106,"session":1,"number":34,"question":"關於蕁麻疹（urticaria）的敘述，下列何者錯誤？","options":["(A) 肥胖細胞（mast cell）是主要作用細胞","(B) 特定病灶存在時間通常小於24小時","(C) 部分慢性蕁麻疹患者的病因是自體免疫（autoimmunity）","(D) 病灶的組織病理變化主要是血管炎"],"answer":3,"image":""},{"id":"md4-106-1-35","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"106年第1次第35題","year":106,"session":1,"number":35,"question":"下列那一種血管炎，c-ANCA（c-antineutrophil cytoplasmic autoantibodies）呈陽性的比例最高？","options":["(A) microscopic polyangiitis","(B) Wegener granulomatosis","(C) Henoch-Schönlein purpura","(D) Churg-Strauss syndrome"],"answer":1,"image":""},{"id":"md4-106-1-36","subject":"md4","topic":"皮膚-感染","meta":"106年第1次第36題","year":106,"session":1,"number":36,"question":"70歲臥床男性，在腹股溝和大腿內側出現如圖A的紅色斑塊，周圍有散在性膿疱，KOH鏡檢如圖B，診斷為何？圖A圖B","options":["(A) 股癬（tinea cruris）","(B) 皮膚念珠菌感染（cutaneous candidiasis）","(C) 陰部單純性疱疹（herpes simplex genitalis）","(D) 汗斑（pityriasis versicolor）"],"answer":1,"image":"md4-106-1-36.jpeg"},{"id":"md4-106-1-37","subject":"md4","topic":"皮膚-腫瘤","meta":"106年第1次第37題","year":106,"session":1,"number":37,"question":"下列何者為最常見的惡性皮膚腫瘤？","options":["(A) 基底細胞癌（basal cell carcinoma）","(B) 鱗狀細胞癌（squamous cell carcinoma）","(C) 黑色素細胞瘤（melanoma）","(D) 梅克爾氏細胞癌（Merkel cell carcinoma）"],"answer":0,"image":""},{"id":"md4-106-1-38","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"106年第1次第38題","year":106,"session":1,"number":38,"question":"24歲女性，晚上吃完喜酒，數小時後，半夜皮膚開始發癢起疹，如圖所示，且奇癢難耐，清晨即趕至醫院急診，最可能的診斷為何？","options":["(A) 急性蕁麻疹","(B) 多型性紅斑","(C) 蜂窩性組織炎","(D) 體癬"],"answer":0,"image":"md4-106-1-38.jpeg"},{"id":"md4-106-1-39","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"106年第1次第39題","year":106,"session":1,"number":39,"question":"下列何種基因的突變與ichthyosis vulgaris最有相關？","options":["(A) profilaggrin","(B) steroid sulfatase","(C) transglutaminase","(D) keratin 1 or 10"],"answer":0,"image":""},{"id":"md4-106-1-40","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"106年第1次第40題","year":106,"session":1,"number":40,"question":"有關脂漏性皮膚炎（Seborrheic dermatitis）的敘述，下列何者錯誤？","options":["(A) 嬰兒期脂漏性皮膚炎需與異位性皮膚炎鑑別診斷","(B) 致病機轉可能與Malassezia相關","(C) 好發部位為四肢伸側及背部","(D) HIV感染可能伴隨脂漏性皮膚炎"],"answer":2,"image":""},{"id":"md4-106-1-41","subject":"md4","topic":"皮膚-感染","meta":"106年第1次第41題","year":106,"session":1,"number":41,"question":"對於leprosy常見併發症的敘述，下列何者錯誤？","options":["(A) 因為神經喪失疼痛知覺，因此常有末端指節關節受傷或是截肢現象","(B) 因為副交感神經受損，因此常有掌蹠多汗現象","(C) 可發生keratitis，甚至會失明","(D) 鼻樑塌陷"],"answer":1,"image":""},{"id":"md4-106-1-42","subject":"md4","topic":"皮膚-腫瘤","meta":"106年第1次第42題","year":106,"session":1,"number":42,"question":"關於蟹足腫（keloid）的敘述，下列何者錯誤？","options":["(A) 穿耳洞也有可能會產生蟹足腫","(B) 若手術部位在關節或前胸處，產生蟹足腫的機率，比顏面或腹部來的高","(C) 蟹足腫常會合併癢感或痛感","(D) 液態氮冷凍不能用於治療蟹足腫"],"answer":3,"image":""},{"id":"md4-106-1-43","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"106年第1次第43題","year":106,"session":1,"number":43,"question":"23歲男性，口服某種藥物兩週後，引起毒性表皮溶解症（toxic epidermal necrolysis），下列何者藥物較無相關？","options":["(A) carbamazepine","(B) allopurinol","(C) acetaminophen","(D) phenytoin"],"answer":2,"image":""},{"id":"md4-106-1-44","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"106年第1次第44題","year":106,"session":1,"number":44,"question":"對於先天性母斑（congenital nevus）的敘述，下列何者錯誤？","options":["(A) 太田氏母斑（nevus of Ota）多為單側，好發於三叉神經第一或第二分支處","(B) 蒙古斑（Mongolian spot）隨著年紀增長會逐漸淡化或消失","(C) 皮脂腺母斑（nevus sebaceous）常伴隨皮膚增厚及多毛的現象","(D) 先天性黑色素細胞痣（congenital melanocytic nevus）通常範圍越大者其轉變成惡性腫瘤機率就越高"],"answer":2,"image":""},{"id":"md4-106-1-45","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"106年第1次第45題","year":106,"session":1,"number":45,"question":"有關肝斑（melasma, chloasma）的敘述，下列何者錯誤？","options":["(A) 懷孕時期肝斑出現的機率較高","(B) 患者應儘量減少紫外線曝曬","(C) 雷射治療效果佳，且不易復發","(D) 肝斑跟肝功能異常無關"],"answer":2,"image":""},{"id":"md4-106-1-46","subject":"md4","topic":"神經-中風","meta":"106年第1次第46題","year":106,"session":1,"number":46,"question":"下列何種中風危險因子的控制，最能有效的減少腦中風的再發生率？","options":["(A) 高血壓以降血壓藥物治療","(B) 高血脂以statin治療","(C) 心房顫動以抗凝血劑（如warfarin）治療","(D) 頸動脈狹窄以支架置放治療"],"answer":2,"image":""},{"id":"md4-106-1-47","subject":"md4","topic":"神經-中風","meta":"106年第1次第47題","year":106,"session":1,"number":47,"question":"70歲男性，有高血壓、冠心症，某日在工作時突發左眼幾乎看不見，症狀持續約20分鐘後視力逐漸恢復，若為血管疾病則最可能的病變血管為何？","options":["(A) 前大腦動脈（anterior cerebral artery）","(B) 中大腦動脈（middle cerebral artery）","(C) 後大腦動脈（posterior cerebral artery）","(D) 內頸動脈（internal carotid artery）"],"answer":3,"image":""},{"id":"md4-106-1-48","subject":"md4","topic":"神經-中風","meta":"106年第1次第48題","year":106,"session":1,"number":48,"question":"一位70歲女性患者，有高血壓、糖尿病病史多年，清晨6點起床時皆正常，但盥洗時突然說話不太清楚，左側肢體無力，清晨6點50分被家人送至急診室，血壓：180/98 mmHg，下述處理何者最不適合？","options":["(A) 詢問病史和簡易身體神經學檢查後，就應立即安排腦部電腦斷層檢查","(B) 立即抽血進行血液生化和相關檢查，並做心電圖","(C) 先給預防性降血壓藥，並安排加護中心病床","(D) 若上述檢查皆正常，儘早給予血栓溶解劑rt-PA"],"answer":[2,3],"image":"","answer_note":"更正:第48題答Ｃ、Ｄ給分"},{"id":"md4-106-1-49","subject":"md4","topic":"神經-中風","meta":"106年第1次第49題","year":106,"session":1,"number":49,"question":"八十四歲的伍爺爺因突發頭痛及行動不便，被送至急診室，神經內科主治醫師認為是出血性中風，最合適的檢查為下列何者？","options":["(A) 血管攝影（angiogram）","(B) 電腦斷層攝影（CT）","(C) 核磁共振攝影（MRI）","(D) transcranial doppler"],"answer":1,"image":""},{"id":"md4-106-1-50","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"106年第1次第50題","year":106,"session":1,"number":50,"question":"治療偏頭痛的triptans類藥物是影響到5HT的那個受體？ ①1A ②1B ③1C ④1D","options":["(A) ①③","(B) ②④","(C) ①④","(D) ②③"],"answer":1,"image":""},{"id":"md4-106-1-51","subject":"md4","topic":"神經-失智退化運動障礙","meta":"106年第1次第51題","year":106,"session":1,"number":51,"question":"50歲男性，自1年前開始，左手做動作時會出現不自主的抽動、半年後左側肢體動作開始變的不靈活，且合併智力衰退等症狀，神經檢查出現肌躍症及肌張力不全，左手對針刺激特別敏感，但若讓他用左手摸硬幣或鑰匙、病人無法辨識，且常抱怨自己的左手像外星人的手。最可能的診斷為何？","options":["(A) 多發系統退化症（multiple system atrophy）","(B) 巴金森病（Parkinson disease）","(C) 皮質基底核退化症（corticobasal ganglionic degeneration）","(D) 漸進性上核麻痺症（progressive supranuclear palsy）"],"answer":2,"image":""},{"id":"md4-106-1-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"106年第1次第52題","year":106,"session":1,"number":52,"question":"下列有關威爾遜氏症（hepatolenticular degeneration；Wilson disease）的敘述，何者正確？","options":["(A) 病人的血中銅含量增加，但因為在肝臟及腦中沉澱，因此24小時尿中的總銅量反而減少","(B) 此病屬於自體顯性遺傳的疾病","(C) 在病人的角膜常出現具有診斷價值的凱斯-佛來斯環（Kayser-Fleischer ring）","(D) 所有病人都是先以神經學的功能異常先出現，之後才出現肝功能的異常"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第52題一律給分 (原公告答案 C)"},{"id":"md4-106-1-53","subject":"md4","topic":"神經-失智退化運動障礙","meta":"106年第1次第53題","year":106,"session":1,"number":53,"question":"下列關於阿茲海默症（Alzheimer disease）的敘述，何者正確？","options":["(A) 意識障礙是首發症狀","(B) 為持續性、進行性、可逆性病程","(C) 病理特徵為老年斑（senile plaques）和神經纖維糾結（neurofibrillary tangles）","(D) 疾病早期不會有人格改變"],"answer":2,"image":""},{"id":"md4-106-1-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"106年第1次第54題","year":106,"session":1,"number":54,"question":"54歲的陳先生，因數月來漸進性手腳末端無力、肌肉萎縮及肢體僵硬感，被診斷為運動神經元病變，而至門診諮詢其後之照護問題。下列敘述何者錯誤？","options":["(A) 具高度遺傳傾向（>50%的可能性）","(B) 生命期約2～5年","(C) 末期需藉呼吸器維持生命","(D) 有藥物可減緩病程惡化"],"answer":0,"image":""},{"id":"md4-106-1-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"106年第1次第55題","year":106,"session":1,"number":55,"question":"28歲女性病患，主訴每天醒來沒有異狀，經過一段時間漸漸產生眼皮下垂及複視現象，以上症狀經過休息會獲得改善，下列那種檢查最能幫助病人確認診斷？","options":["(A) 神經傳導測試（nerve conduction studies）","(B) 肌電圖檢查（electromyogram）","(C) 重複性電擊刺激（repetitive stimulation test）","(D) 瞬眼反射檢查（blink reflex）"],"answer":2,"image":""},{"id":"md4-106-1-56","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"106年第1次第56題","year":106,"session":1,"number":56,"question":"有關糖尿病多發性神經病變之敘述，下列何者錯誤？","options":["(A) 糖尿病是造成多發性神經病變最常見原因","(B) 最常見表現為慢性、漸進性且對稱侵犯遠端下肢足部感覺神經系統為主","(C) 病患常主訴足部及下肢麻、刺痛（tingling）","(D) 足部潰爛相當罕見"],"answer":3,"image":""},{"id":"md4-106-1-57","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"106年第1次第57題","year":106,"session":1,"number":57,"question":"變異型庫賈氏病（variant Creutzfeldt-Jakob disease, vCJD）和散發型庫賈氏病（sporadic Creutzfeldt-Jakob disease, sCJD）的差異，下列敘述何者錯誤？","options":["(A) vCJD的病程比sCJD較為緩慢","(B) vCJD的病人臨床上較少出現肌躍症（myoclonic jerk）","(C) vCJD病人腦脊液14-3-3蛋白上升的比率遠低於sCJD病人","(D) vCJD病人腦波出現周期性銳波（periodic synchronous bi- or triphasic sharp wave complexes）的概率遠高於sCJD病人"],"answer":3,"image":""},{"id":"md4-106-1-58","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"106年第1次第58題","year":106,"session":1,"number":58,"question":"下列何種疾病是性聯遺傳（sex-linked recessive）？","options":["(A) 肢帶型肌肉失養症（limb-girdle muscular dystrophy）","(B) 肌強直症（myotonic dystrophy）","(C) 裘馨氏肌肉失養症（Duchenne muscular dystrophy）","(D) 低鉀週期性麻痺（hypokalemic periodic paralysis）"],"answer":2,"image":""},{"id":"md4-106-1-59","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"106年第1次第59題","year":106,"session":1,"number":59,"question":"一位28歲的男性病人，最近一週每天晚上會發生劇烈頭痛，每次頭痛都發生在右邊眼眶和太陽穴的地方，同時也有右邊眼睛紅和流淚的現象，大約一個小時後就會緩解，他去年秋天的時候也有一個月的時間天天晚上發生類似的頭痛。下列何者為最可能的診斷？","options":["(A) 叢發性頭痛（cluster headache）","(B) 預兆偏頭痛（migraine with aura）","(C) 腦瘤","(D) 青光眼（glaucoma）"],"answer":0,"image":""},{"id":"md4-106-1-60","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"106年第1次第60題","year":106,"session":1,"number":60,"question":"承上題，關於該病患的治療之敘述，下列何者錯誤？","options":["(A) 急性發作時可以呼吸100%氧氣15分鐘","(B) 使用10～14天的類固醇治療","(C) 使用1個月的ergotamine來預防發作","(D) 急性發作時使用sumatriptan來止痛"],"answer":2,"image":""},{"id":"md4-106-1-61","subject":"md4","topic":"精神-精神病","meta":"106年第1次第61題","year":106,"session":1,"number":61,"question":"有關精神疾病與其首選藥物之配對，下列何者正確？","options":["(A) 思覺失調症（schizophrenia）─ serotonin and dopamine agonists","(B) 廣泛性焦慮症（generalized anxiety disorders）─ selective serotonin reuptake inhibitors","(C) 雙極性情感疾患（bipolar disorders）─ dopamine agonists","(D) 強迫症（obsessive compulsive disorders）─ lithium"],"answer":1,"image":""},{"id":"md4-106-1-62","subject":"md4","topic":"精神-器質性與物質使用","meta":"106年第1次第62題","year":106,"session":1,"number":62,"question":"下列關於功能性腸胃道疾患（functional gastrointestinal disorders）敘述，何者錯誤？","options":["(A) 具有腸胃道收縮異常以及功能性食道症狀的病人經常合併有精神疾病","(B) 焦慮症為功能性腸胃道疾患常見的精神科共病","(C) 在與功能性腸胃道疾患共病的焦慮疾患中，創傷後壓力症候群（posttraumatic stress disorder）是最常出現的","(D) 恐慌發作的症狀亦包含了腸胃道症狀"],"answer":2,"image":""},{"id":"md4-106-1-63","subject":"md4","topic":"精神-精神病","meta":"106年第1次第63題","year":106,"session":1,"number":63,"question":"根據DSM-IV-TR，下列何者不是雙極性疾患（bipolar disorder）與重鬱症常見共病（comorbid）的精神疾病？","options":["(A) 身體化症（somatoform disorder）","(B) 酒精濫用（alcohol abuse）","(C) 恐慌症（panic disorder）","(D) 強迫症（obsessive-compulsive disorder）"],"answer":0,"image":""},{"id":"md4-106-1-64","subject":"md4","topic":"精神-器質性與物質使用","meta":"106年第1次第64題","year":106,"session":1,"number":64,"question":"有關甲狀腺亢進與精神疾病的關聯性，下列何者錯誤？","options":["(A) 甲狀腺亢進可能說話會滔滔不絕","(B) 甲狀腺亢進不會造成認知功能缺損","(C) 甲狀腺亢進可能產生視幻覺、被害意念以及譫妄症","(D) 雖然甲狀腺亢進與躁症病因不同，但其臨床表現可能相似"],"answer":1,"image":""},{"id":"md4-106-1-65","subject":"md4","topic":"精神-精神官能症","meta":"106年第1次第65題","year":106,"session":1,"number":65,"question":"根據DSM-IV-TR，有關身體化症（somatoform disorder）的敘述，下列何者正確？","options":["(A) 身體畸形性疾患（body dysmorphic disorder）好發於15至30歲女性，且患者關注焦點通常著重在臉部缺陷（facial flaws）","(B) 身體化疾患（somatization disorder）較常發生於教育程度高或社經階層較高者","(C) 慮病症（hypochondriasis）通常女性較多，且與社經階層及教育程度相關","(D) 在疼痛疾患（pain disorder）中，急性疼痛最常與憂鬱疾患（depressive disorder）共病，而慢性疼痛則較常與焦慮性疾患（anxiety disorder）共病"],"answer":0,"image":""},{"id":"md4-106-1-66","subject":"md4","topic":"精神-精神病","meta":"106年第1次第66題","year":106,"session":1,"number":66,"question":"下列有關精神疾病的病因分析敘述何者錯誤？","options":["(A) 可以從前置（predisposing）、誘發（precipitating）、延續（perpetuating）三種因素作時序性的分析","(B) 可以從生理（biological）、心理（psychological）、社會（social）三種面向分析","(C) 先天的基因變異是精神疾病的生理病因之一","(D) 同卵雙胞胎其中之一若罹患思覺失調症（schizophrenia），則另外一位亦罹患此症之機率為100%"],"answer":3,"image":""},{"id":"md4-106-1-67","subject":"md4","topic":"神經-失智退化運動障礙","meta":"106年第1次第67題","year":106,"session":1,"number":67,"question":"快速動眼期睡眠行為障礙（REM sleep behavior disorder）最常發生在下列那種病人？","options":["(A) 帕金森氏症（Parkinson's disease）","(B) 阿茲海默症（Alzheimer's disease）","(C) 額顳葉失智症（frontotemporal dementia）","(D) 尿毒症（uremia）"],"answer":0,"image":""},{"id":"md4-106-1-68","subject":"md4","topic":"精神-精神官能症","meta":"106年第1次第68題","year":106,"session":1,"number":68,"question":"某送貨員個性緊張容易合併腹痛現象，一年前於高架道路塞車時，因腹痛及有腹瀉感近乎大便失禁的經驗，此後個案不敢再開車上高架道路與高速公路而失去工作，隨後甚至不敢搭火車、公車、到人多或郊外無廁所的地方，而影響生活甚鉅。此個案最可能符合下列那個診斷？","options":["(A) 適應障礙症（adjustment disorder）","(B) 創傷後壓力症（posttraumatic stress disorder）","(C) 懼曠症（agoraphobia）","(D) 泛焦慮症（generalized anxiety disorder）"],"answer":2,"image":""},{"id":"md4-106-1-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"106年第1次第69題","year":106,"session":1,"number":69,"question":"戒酒發泡錠（disulfiram）用來治療酒癮，其作用機轉主要為何？","options":["(A) 抑制酒精代謝過程中的aldehyde dehydrogenase","(B) 抑制酒精代謝過程中的alcohol dehydrogenase","(C) 抑制GABA type A receptors（GABAA）在alcohol ion channel activity的作用","(D) 抑制serotonin 5-HT3 receptors在alcohol ion channel activity的作用"],"answer":0,"image":""},{"id":"md4-106-1-70","subject":"md4","topic":"精神-器質性與物質使用","meta":"106年第1次第70題","year":106,"session":1,"number":70,"question":"有關鴉片類藥物戒斷症狀之敘述，下列何者正確？","options":["(A) 越短效之鴉片類藥物，越不會導致戒斷症狀","(B) 無嚴重生理疾病者，很少死於戒斷症狀","(C) 戒斷症狀主要有嗜睡以及心搏加速","(D) 鴉片類拮抗劑（opioid antagonist，如naloxone）不會造成戒斷症狀"],"answer":1,"image":""},{"id":"md4-106-1-71","subject":"md4","topic":"精神-器質性與物質使用","meta":"106年第1次第71題","year":106,"session":1,"number":71,"question":"一位長期喝酒之50歲男性患者因酒醉車禍骨折住院，住院前每天都喝500毫升以上酒精濃度30%以上的酒，為準備手術故暫停所有藥物及酒精，腦部電腦斷層掃描（CT scan）結果正常。但住院隔天開始出現顫抖、৅汗、血壓增高、心跳變快、煩躁失眠、手抖與視幻覺，下࠻敘述何者最恰當？","options":["(A) 為預防癲癇發作，要馬上給予抗癲癇藥物","(B) 經評估後，可投以苯二氮平ৡ藥物（benzodiazepines）","(C) 會自行好轉，觀察即可，不需要特別處置","(D) 為達到鎮靜效果，第一線用藥為抗精神病藥物"],"answer":1,"image":""},{"id":"md4-106-1-72","subject":"md4","topic":"精神-精神官能症","meta":"106年第1次第72題","year":106,"session":1,"number":72,"question":"士兵參與戰爭後，最可能產生的精神疾病為何？","options":["(A) 創傷後壓力症（post traumatic stress disorder）","(B) 強迫症（obsessive compulsive disorder）","(C) 妄想症（delusional disorder）","(D) 恐慌症（panic disorder）"],"answer":0,"image":""},{"id":"md4-106-1-73","subject":"md4","topic":"兒科-感染神經","meta":"106年第1次第73題","year":106,"session":1,"number":73,"question":"學齡兒童診斷注意力不足過動症後，在使用methylphenidate治療時，最需注意那個副作用？","options":["(A) 食慾不振","(B) 無顆粒球血症（agranulocytosis）","(C) 錐體外徑症候群（extrapyramidal tract syndrome）","(D) 抽搐（seizures）"],"answer":0,"image":""},{"id":"md4-106-1-74","subject":"md4","topic":"精神-精神病","meta":"106年第1次第74題","year":106,"session":1,"number":74,"question":"王小姐今年30歲，自從15歲起就因憂鬱症狀常進出精神科病房，長期無業靠政府補助及保險金過活，並且有反覆自傷以及作態性自殺的病史。她總認為自己是被家人及朋友所放棄了，長期感到非常空虛。她非常衝動，在一天之內心情常有劇烈變化，因此時常處於非常煩躁的狀態，時而有暴食、衝動購物、開快車的行為。她的朋友都認為，她日常生活與人相處非常極端，時常不是過度理想化，就是過度否定，因此，她的人際關係非常不穩定。依據DSM-IV-TR，王小姐屬於下列何種人格疾患診斷最為恰當？","options":["(A) 強迫性人格違常（obsessive-compulsive personality disorder）","(B) 依賴性人格違常（dependent personality disorder）","(C) 邊緣性人格違常（borderline personality disorder）","(D) 類分裂性人格違常（schizoid personality disorder）"],"answer":2,"image":""},{"id":"md4-106-1-75","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"106年第1次第75題","year":106,"session":1,"number":75,"question":"自殺是近年來臺灣社會中越來越引起關注的現象，關於自殺的描述，下列何者最正確？","options":["(A) 在流行病學的研究中發現，女性出現自殺行為的比率較男性較少，但自殺死亡率卻比較高","(B) 老年族群的自殺死亡率比年輕族群來得高","(C) 自殺死亡的族群中，只有10%曾被診斷出任一種精神疾病","(D) 過去是否曾有自殺企圖，與未來自殺風險的預測無關"],"answer":1,"image":""},{"id":"md4-106-1-76","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第1次第76題","year":106,"session":1,"number":76,"question":"6歲女童，偶然發現胸部Ｘ光異常，胸部影像如圖，最可能的診斷為下列何者？","options":["(A) 心臟腫瘤","(B) 神經性腫瘤（neurogenic tumor）","(C) 橫膈疝脫（diaphragmatic hernia）","(D) 右肺中葉肺炎"],"answer":1,"image":"md4-106-1-76.jpeg"},{"id":"md4-106-1-77","subject":"md4","topic":"皮膚-感染","meta":"106年第1次第77題","year":106,"session":1,"number":77,"question":"一位45歲男性，至金門旅遊回來，幾天後出現發燒，頭痛與咳嗽的情形，並於大腿出現如圖的皮膚病灶，下列敘述何者錯誤？","options":["(A) 高度懷疑是Scrub Typhus，又可稱為Tsutsugamushi disease","(B) 是必須通報的法定傳染病","(C) 皮膚病灶稱為焦痂（Eschar），是大多數病患者皆會出現的特徵","(D) 是經由恙蟲媒介"],"answer":[0,1,2,3],"image":"md4-106-1-77.jpeg","answer_note":"送分:第77題一律給分。 (原公告答案 C)"},{"id":"md4-106-1-78","subject":"md4","topic":"皮膚-感染","meta":"106年第1次第78題","year":106,"session":1,"number":78,"question":"承上題，下列何者為首選藥物？","options":["(A) Doxycycline","(B) Augmentin","(C) 2nd generation Cephalosporin","(D) 支持性療法（Supportive care），沒有特效藥"],"answer":0,"image":""},{"id":"md4-106-1-79","subject":"md4","topic":"醫學倫理與法規","meta":"106年第1次第79題","year":106,"session":1,"number":79,"question":"根據衛生福利部民國95年公告之「研究用人體檢體採集與使用注意事項」，有關「去連結」之定義，下列何者正確？","options":["(A) 將檢體編碼，以代碼取代姓名或其他可供辨識個人資訊，致無法辨識檢體提供者之作業方式","(B) 於檢體編碼後，將代碼與檢體提供者可供辨識個人資訊之對照資料，和檢體分開保存之作業方式","(C) 於檢體編碼後，將代碼與檢體提供者可供辨識個人資訊之對照資料再編碼方式處理之作業方式","(D) 於檢體編碼後，將代碼與檢體提供者可供辨識個人資訊之對照資料完全永久消除之作業方式"],"answer":3,"image":""},{"id":"md4-106-1-80","subject":"md4","topic":"醫學倫理與法規","meta":"106年第1次第80題","year":106,"session":1,"number":80,"question":"某憂鬱症患者M，最近因投資失利，病情惡化，產生精神病症狀，接受住院治療。於病情改善出院時，M希望能夠藉由身心障礙補助來改善其經濟狀況，因此要求主治醫師P為其進行身心障礙鑑定時，把情況寫得嚴重一點。在此個案中，P會遭遇那兩個倫理原則之衝突？","options":["(A) 尊重自主原則與不傷害原則","(B) 正義原則與不傷害原則","(C) 正義原則與行善原則","(D) 尊重自主原則與行善原則"],"answer":2,"image":""},{"id":"md4-106-2-1","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第2次第1題","year":106,"session":2,"number":1,"question":"14個月大的男生，出現咳嗽並有呼吸急促已有10天，因為一直沒有發燒，直到媽媽發現他食慾不振的情形才到門診求治，肺部聽診時發現兩側都可以聽到喘鳴聲（wheezing），左側呼吸音比右側小聲，胸部X光片檢查如圖所示，下列何者是最有可能的診斷？","options":["(A) 呼吸道異物","(B) 先天性心臟病","(C) 臟器轉位症候群","(D) 左側氣胸"],"answer":0,"image":"md4-106-2-1.jpeg"},{"id":"md4-106-2-2","subject":"md4","topic":"兒科-感染神經","meta":"106年第2次第2題","year":106,"session":2,"number":2,"question":"有關非傷寒沙門氏菌（nontyphoidal Salmonella）感染，下列何者不須常規使用抗生素治療？","options":["(A) 大於3個月大之嬰兒","(B) 腹脹且有毒性病容","(C) 合併菌血症","(D) 病人有sickle cell disease"],"answer":0,"image":""},{"id":"md4-106-2-3","subject":"md4","topic":"兒科-消化系統疾病","meta":"106年第2次第3題","year":106,"session":2,"number":3,"question":"剛出生的足月兒，體重3,000公克，嬰兒室護理師通知你，此足月兒呼吸60次/分，心跳130次/分，肛溫37℃，嘴邊常常流出大量白沫，偶爾會咳嗽。下列何者為最可能的診斷？","options":["(A) 肺炎","(B) 腦膜炎","(C) 食道閉鎖","(D) 十二指腸閉鎖"],"answer":2,"image":""},{"id":"md4-106-2-4","subject":"md4","topic":"兒科-內分泌遺傳","meta":"106年第2次第4題","year":106,"session":2,"number":4,"question":"自然產之7天大嬰兒，出現嘔吐及進食困難症狀，身體診察發現有角弓反張（opisthotonos），實驗室檢查有低血糖現象，尿液檢查正常，汗水有一奇特的味道，病人有代謝性酸中毒。最可能的診斷為：","options":["(A) 腎小管性酸中毒（renal tubular acidosis）","(B) 楓糖尿症（maple syrup urine disease）","(C) Arnold-Chiari氏畸型（Arnold-Chiari malformation）","(D) 先天性甲狀腺功能低下症（congenital hypothyroidism）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第4題一律給分 (原公告答案 B)"},{"id":"md4-106-2-5","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"106年第2次第5題","year":106,"session":2,"number":5,"question":"有關IgA nephropathy的敘述，下列何者錯誤？","options":["(A) 可能有家族的集群性（familial clustering）","(B) 有些病童在發病後的15～20年可能會進展到慢性腎病或腎衰竭","(C) 因為會復發，進入末期腎病後不建議腎移植","(D) 血中IgA值並沒有診斷價值，因為只有部分的病童會升高"],"answer":2,"image":""},{"id":"md4-106-2-6","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"106年第2次第6題","year":106,"session":2,"number":6,"question":"一位母親帶兩歲大幼兒至門診接受健康檢查，擔心孩子比同年齡的小孩發展較慢。下列那一個狀況需要轉介至聯合評估中心做進一步的發展評估？","options":["(A) 講話ㄓㄔㄕ發音不清楚","(B) 無法認出四種顏色","(C) 不會用手正確的指出自己的五官","(D) 不會說四個字的短句"],"answer":[2,3],"image":"","answer_note":"更正:第6題答Ｃ、Ｄ給分"},{"id":"md4-106-2-7","subject":"md4","topic":"兒科-內分泌遺傳","meta":"106年第2次第7題","year":106,"session":2,"number":7,"question":"先天性甲狀腺低能症（congenital hypothyroidism）的新生兒，最常見下列何項症狀？","options":["(A) 出生時身高體重明顯過小","(B) 出生時頭圍較小","(C) 睡眠不好常會哭鬧","(D) 新生兒黃疸持續時間較長"],"answer":3,"image":""},{"id":"md4-106-2-8","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"106年第2次第8題","year":106,"session":2,"number":8,"question":"有關Henoch-Schönlein purpura的敘述，下列何者正確？","options":["(A) 紫斑易出現在軀幹","(B) 主要是IgM抗體沈積所引起之血管炎","(C) 抗核抗體（antinuclear antibody）陽性","(D) 血小板數目正常或增加"],"answer":3,"image":""},{"id":"md4-106-2-9","subject":"md4","topic":"兒科-感染神經","meta":"106年第2次第9題","year":106,"session":2,"number":9,"question":"E-B病毒（Epstein-Barr virus）急性感染後引起的單核球增多症（infectious mononucleosis），下列何種血清抗體最晚出現？","options":["(A) anti-VCA IgG","(B) anti-VCA IgM","(C) anti-EBNA Ab","(D) anti-EA Ab"],"answer":2,"image":""},{"id":"md4-106-2-10","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第2次第10題","year":106,"session":2,"number":10,"question":"當法洛氏四重症（tetralogy of Fallot）病兒發生發紺發作（hypoxic spells, blue spells）時，心雜音會如何改變？","options":["(A) 變大聲","(B) 不變","(C) 變小聲","(D) 會改變成舒張期雜音"],"answer":2,"image":""},{"id":"md4-106-2-11","subject":"md4","topic":"兒科-內分泌遺傳","meta":"106年第2次第11題","year":106,"session":2,"number":11,"question":"16歲女孩，因遲遲沒有初經，但有乳房發育，外生殖器也屬於典型女性，染色體檢查結果為46, XY，下列何種情況最不可能？","options":["(A) 5α-reductase II基因突變","(B) 完全型androgen insensitivity syndrome","(C) aromatase基因突變或缺損","(D) SRY基因突變或缺損"],"answer":[0,2,3],"image":"","answer_note":"更正:第11題答Ａ、Ｃ、Ｄ給分"},{"id":"md4-106-2-12","subject":"md4","topic":"兒科-感染神經","meta":"106年第2次第12題","year":106,"session":2,"number":12,"question":"10個月大的男嬰高燒6天，軀幹及四肢可見皮膚紅疹且手腳腫脹，結膜充血發紅，同時有草莓舌及嘴唇乾裂，在頸部可摸到淋巴結腫大，下列何者錯誤？","options":["(A) 最可能的診斷是川崎氏症（Kawasaki disease）","(B) 治療可使用口服Aspirin","(C) 若此病人使用IVIG 2g/kg治療，於1歲1個月時可施打水痘疫苗","(D) 需安排心臟超音波檢查"],"answer":2,"image":""},{"id":"md4-106-2-13","subject":"md4","topic":"兒科-感染神經","meta":"106年第2次第13題","year":106,"session":2,"number":13,"question":"5歲女童因發燒5天而住院，同時有鼻塞及雙眼皮浮腫，身體診察有肝脾腫大、頸部淋巴結腫大、化膿性扁桃腺炎，住院後抽血檢查報告如下：血紅素：11 g/dL，血比容：34%，白血球 : 13300/uL，非典型淋巴球：20%，血小板：200000/uL，GOT：94 IU/L，GPT：109 IU/L，C-反應蛋白：3.535 mg/dL。最可能是下列何種感染？","options":["(A) Epstein-Barr virus","(B) Enterovirus","(C) Streptococcus pneumoniae","(D) Staphylococcus aureus"],"answer":0,"image":""},{"id":"md4-106-2-14","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"106年第2次第14題","year":106,"session":2,"number":14,"question":"足月新生兒，身長42 cm、體重2.3 kg、頭圍偏小、小眼廓、下頜發育不良、上唇薄，下列疾病中最可能的診斷為何？","options":["(A) 胎兒酒精症候群（fetal alcohol syndrome）","(B) 新生兒戒斷症候群（neonatal abstinence syndrome）","(C) 唐氏症（Down syndrome）","(D) 威廉氏症候群（Williams syndrome）"],"answer":0,"image":""},{"id":"md4-106-2-15","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"106年第2次第15題","year":106,"session":2,"number":15,"question":"新生兒胎便吸入（meconium aspiration syndrome）的標準處置中，為了避免惡化甚至引起持續性肺動脈高壓（pulmonary hypertension），下列何者為最首要的處理？","options":["(A) 出生後立即使用表面張力素","(B) 氣管內抽吸清除胎便並處理呼吸窘迫與缺氧","(C) 正壓換氣呼吸","(D) 體外膜氧合ECMO（extracorporeal membrane oxygenation）"],"answer":1,"image":""},{"id":"md4-106-2-16","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"106年第2次第16題","year":106,"session":2,"number":16,"question":"緊急處理新生兒氣胸（pneumothorax）時，可於胸壁那個位置垂直插入引流針治療？","options":["(A) 第一肋間隙（intercostal space）","(B) 第二肋間隙","(C) 第三肋間隙","(D) 第四肋間隙"],"answer":[1,3],"image":"","answer_note":"更正:第16題答Ｂ、Ｄ給分"},{"id":"md4-106-2-17","subject":"md4","topic":"兒科-消化系統疾病","meta":"106年第2次第17題","year":106,"session":2,"number":17,"question":"許多腸道病原體感染，亦會產生腸道外疾病，下列那一種病原體與腸道外疾病的組合錯誤？","options":["(A) Shigella- glomerulonephritis","(B) Campylobacter- immunoglobulin A（IgA）nephropathy","(C) rotavirus- reactive arthritis","(D) Yersinia- hemolytic anemia"],"answer":2,"image":""},{"id":"md4-106-2-18","subject":"md4","topic":"兒科-消化系統疾病","meta":"106年第2次第18題","year":106,"session":2,"number":18,"question":"下列何種檢查，最無法確定目前胃中有幽門桿菌（Helicobacter pylori）感染？","options":["(A) 胃切片組織培養陽性","(B) 血中抗幽門桿菌抗體陽性","(C) 碳-13尿素吹氣檢查陽性","(D) 糞便幽門桿菌抗原檢驗陽性"],"answer":1,"image":""},{"id":"md4-106-2-19","subject":"md4","topic":"兒科-消化系統疾病","meta":"106年第2次第19題","year":106,"session":2,"number":19,"question":"有關腸套疊（intussusception）之敘述，下列何者錯誤？","options":["(A) 常見的好發年齡，介於六個月至一歲","(B) 絕大部分病童，可以找出lead point","(C) 最好發的腸段是迴結腸（ileocolic）處","(D) 典型的症狀，為腹痛、腹部腫塊與血便"],"answer":1,"image":""},{"id":"md4-106-2-20","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"106年第2次第20題","year":106,"session":2,"number":20,"question":"關於高血鉀（hyperkalemia）的處理，下列何者敘述錯誤？","options":["(A) 停止所有鉀離子的補充","(B) 若血鉀濃度高於6.5 mEq/L，心電圖可能先出現peak T waves，進一步可能出現prolonged PR interval","(C) 靜脈內注射胰島素改善高血鉀時，不可同時加葡萄糖點滴","(D) 若高血鉀對於藥物的反應不佳，應考慮透析治療"],"answer":2,"image":""},{"id":"md4-106-2-21","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"106年第2次第21題","year":106,"session":2,"number":21,"question":"15歲男生為田徑隊員，在訓練3小時後，發生雙側大腿疼痛，尿液變成紅色而至急診求診。尿液檢查發現，潛血反應（occult blood）：3+，urobilinogen: 3+，RBC：1-2/HPF，WBC：0～2/HPF。抽血檢查發現，AST/ALT= 120/130 U/L，K=5.0 mM，LDH=400 mg/dL，CK=143,840 U/L。下列何者為最可能的診斷？","options":["(A) 急性肝炎（acute hepatitis)","(B) 急性腎絲球腎炎（acute glomerulonephritis）","(C) 橫紋肌溶解症（rhabdomyolysis）","(D) 急性溶血（acute hemolysis）"],"answer":2,"image":""},{"id":"md4-106-2-22","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"106年第2次第22題","year":106,"session":2,"number":22,"question":"下列何者為神經纖維瘤症（neurofibromatosis）最典型的皮膚特徵？","options":["(A) linear hypopigmentation","(B) cherry red spots","(C) port-wine stain","(D) café-au-lait spots"],"answer":3,"image":""},{"id":"md4-106-2-23","subject":"md4","topic":"兒科-內分泌遺傳","meta":"106年第2次第23題","year":106,"session":2,"number":23,"question":"12歲男童，出生體重、身長及一歲前生長發育均正常，身體診察發現身高低於正常平均值，骨齡比實際年齡小，抽血檢查發現生長因子（IGF-1）低於年齡正常值但與骨齡相吻合，下列何者正確？","options":["(A) IGF-1缺乏症（IGF-1 deficiency）","(B) 生長激素缺乏症（growth hormone deficiency）","(C) 甲狀腺功能低下（hypothyroidism）","(D) 體質遲緩（constitutional growth delay）"],"answer":3,"image":""},{"id":"md4-106-2-24","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"106年第2次第24題","year":106,"session":2,"number":24,"question":"有關於先天性免疫缺損症的敘述，下列何者錯誤？","options":["(A) severe combined immunodeficiency患者的淋巴節、扁桃腺、Peyer's patch等淋巴組織，通常缺乏或者極度發育不良","(B) severe combined immunodeficiency患者於出生時經常有淋巴球低下的情況發生，患者出生後幾個月就會感染肺炎，中耳炎，甚至併發敗血症","(C) chronic granulomatous disease和leukocyte adhesion deficiency皆屬吞噬細胞的問題，DiGeorge syndrome屬T細胞免疫功能異常","(D) 補體缺損易有自體免疫疾病，其中alternative pathway deficiencies最常合併發生自體免疫疾病"],"answer":3,"image":""},{"id":"md4-106-2-25","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"106年第2次第25題","year":106,"session":2,"number":25,"question":"關於嬰兒猝死症候群（sudden infant death syndrome , SIDS）的敘述，下列何者錯誤？","options":["(A) SIDS定義為一歲以下嬰兒突然死亡，且經過完整病理解剖、解析死亡過程並檢視臨床病史等詳細調查後，仍未能找到死因者","(B) 發生率在一個月以下的新生兒達高峰，其次在2-3個月大時，也很常見","(C) 危險因子包括胎兒在子宮內暴露吸菸、早產、未哺育母乳、趴睡、與父母共眠、嬰兒床有鬆軟物品","(D) 研究發現SIDS也可與基因變異有關，例如心肌之鈉鉀通道、自律神經系統發展、呼吸控制中樞等之基因異常"],"answer":[0,1],"image":"","answer_note":"更正:第25題答Ａ、Ｂ給分"},{"id":"md4-106-2-26","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"106年第2次第26題","year":106,"session":2,"number":26,"question":"有關6歲蕁麻疹（urticaria）病童，下列敘述何者正確？","options":["(A) 蕁麻疹急性發作時，類固醇是首選藥物","(B) 重複暴露特定過敏原引起的反覆急性蕁麻疹（recurrent acute urticaria with repeated exposures to a specific agent）亦屬慢性蕁麻疹","(C) 慢性蕁麻疹的病人大部分可以用抽血來找到過敏原","(D) 慢性蕁麻疹病人的治療藥物以H1 antihistamines為主，如病人反應效果不好，可以在該藥品許可範圍內加大劑量"],"answer":3,"image":""},{"id":"md4-106-2-27","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"106年第2次第27題","year":106,"session":2,"number":27,"question":"關於缺鐵性貧血（iron-deficiency anemia）的敘述，下列何者錯誤？","options":["(A) 易發生於9至24個月大的兒童","(B) 青春期的女生，常因經血量太多而引起","(C) 因為身體內的鐵不夠，每個紅血球會被盡量公平的分配到一樣的鐵，使得紅血球分布寬度（red cell distribution width）減少","(D) 發生缺鐵性貧血時，血清鐵（serum iron）的量會減少，總鐵結合能力（total iron binding capacity）會增加"],"answer":2,"image":""},{"id":"md4-106-2-28","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"106年第2次第28題","year":106,"session":2,"number":28,"question":"1歲孩童因眼睛無虹膜（aniridia），門診定期接受腹部超音波檢查，1年後發現腹部有腫瘤，下列何種腫瘤最有可能？","options":["(A) 威爾姆氏腫瘤（Wilms tumor）","(B) 神經母細胞瘤（neuroblastoma）","(C) 生殖細胞瘤（germ cell tumor）","(D) 橫紋肌肉瘤（rhadomyosarcoma）"],"answer":0,"image":""},{"id":"md4-106-2-29","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第2次第29題","year":106,"session":2,"number":29,"question":"下列何者為足月生產兒童最常見的先天性心臟病？","options":["(A) 心室中隔缺損（ventricular septal defect）","(B) 第二型心房中隔缺損（atrial septal defect secundum）","(C) 法洛氏四重症（tetralogy of Fallot）","(D) 開放性動脈導管（patant ductus arteriosus）"],"answer":0,"image":""},{"id":"md4-106-2-30","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第2次第30題","year":106,"session":2,"number":30,"question":"下列何種先天性心臟病（congenital heart disease），最少見到在新生兒出生一週內，即發生嚴重的發紺（severe cyanosis）現象？","options":["(A) 大動脈轉位（transposition of the great arteries）","(B) 單純型主動脈縮窄（simple coarctation of the aorta）","(C) 左心發育不全症候群（hypoplastic left heart syndrome）","(D) 全肺靜脈回流異常合併回流阻塞（total anomalous pulmonary venous return with obstruction）"],"answer":1,"image":""},{"id":"md4-106-2-31","subject":"md4","topic":"兒科-內分泌遺傳","meta":"106年第2次第31題","year":106,"session":2,"number":31,"question":"有關Trisomy18（Edwards syndrome）的敘述，下列何者錯誤？","options":["(A) 第2指交疊於第3指，第5指交疊於第4指","(B) 短胸骨（short sternum）","(C) 搖椅腳（rocker-bottom feet）","(D) 扁平枕部（flat occiput）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第31題答Ａ、Ｂ、Ｃ、Ｄ給分 (原公告答案 D)"},{"id":"md4-106-2-32","subject":"md4","topic":"兒科-感染神經","meta":"106年第2次第32題","year":106,"session":2,"number":32,"question":"4個月大的嬰兒，因為點頭式痙攣（infantile spasms）就診。身體診察發現皮膚上有葉狀脫色白斑（ash-leaf hypomelanosis），腦電波圖檢查有亂棘波（hypsarrhythmia）。最可能的診斷為何？","options":["(A) 神經纖維瘤（neurofibromatosis）","(B) 結節性硬化症（tuberous sclerosis）","(C) Sturge-Weber症候群","(D) 色素失調症（incontinentia pigmenti）"],"answer":1,"image":""},{"id":"md4-106-2-33","subject":"md4","topic":"兒科-感染神經","meta":"106年第2次第33題","year":106,"session":2,"number":33,"question":"承上題，對該嬰兒之處置，下列何者最非必要？","options":["(A) 腦部磁振造影檢查","(B) 腎臟超音波檢查","(C) 肺部電腦斷層檢查","(D) 心臟超音波檢查"],"answer":2,"image":""},{"id":"md4-106-2-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"106年第2次第34題","year":106,"session":2,"number":34,"question":"35歲男性，主訴從頸部到膝蓋散布脫屑的紅疹，如圖所示，理學檢查手掌腳掌皮膚正常，最可能的診斷為：","options":["(A) 玫瑰糠疹（pityriasis rosea）","(B) 玫瑰疹（roseola）","(C) 麻疹（measles）","(D) 多形性紅斑（erythema multiforme）"],"answer":0,"image":"md4-106-2-34.jpeg"},{"id":"md4-106-2-35","subject":"md4","topic":"皮膚-感染","meta":"106年第2次第35題","year":106,"session":2,"number":35,"question":"28歲男性，於手掌腳掌出現無症狀的脫屑性皮疹，如圖所示，最可能的診斷為：","options":["(A) 梅毒","(B) 單純性疱疹","(C) 疥瘡","(D) 淋病"],"answer":0,"image":"md4-106-2-35.jpeg"},{"id":"md4-106-2-36","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"106年第2次第36題","year":106,"session":2,"number":36,"question":"18歲男性，於前胸逐漸出現如圖所示之皮膚病變，合併輕度疼痛及癢感；下列何者是最不適當之治療方法？","options":["(A) 局部注射皮質類固醇","(B) 手術切除","(C) 染料雷射治療","(D) 局部貼敷矽膠"],"answer":1,"image":"md4-106-2-36.jpeg"},{"id":"md4-106-2-37","subject":"md4","topic":"皮膚-腫瘤","meta":"106年第2次第37題","year":106,"session":2,"number":37,"question":"關於基底細胞癌的敘述，下列何者錯誤？","options":["(A) 最常見的皮膚癌","(B) 具有局部侵犯性","(C) 容易轉移","(D) 與日光曝曬有關"],"answer":2,"image":""},{"id":"md4-106-2-38","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"106年第2次第38題","year":106,"session":2,"number":38,"question":"有關口周炎（perioral dermatitis）之敘述，下列何者錯誤？","options":["(A) 好發於女性","(B) 應使用外用類固醇治療","(C) 有時需要做細菌培養來排除金黃色葡萄球菌（S. aureus）感染的可能","(D) 若給與口服doxycycline治療，應提醒病人防曬以免光致敏（photosensitization）"],"answer":1,"image":""},{"id":"md4-106-2-39","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"106年第2次第39題","year":106,"session":2,"number":39,"question":"關於嬰兒異位性皮膚炎的敘述，下列何者正確？","options":["(A) 分布範圍主要為臉部、頭皮以及四肢的伸側（extensor side）","(B) 若患者合併thrombocytopenia以及免疫功能異常，需懷疑是hyper-IgE syndrome","(C) 臨床上不須與脂漏性皮膚炎做鑑別診斷","(D) 為避免局部類固醇造成的副作用，FDA建議首選外用藥物為0.03% tacrolimus或1% pimecrolimus"],"answer":0,"image":""},{"id":"md4-106-2-40","subject":"md4","topic":"皮膚-感染","meta":"106年第2次第40題","year":106,"session":2,"number":40,"question":"關於Leprosy的敘述，下列何者錯誤？","options":["(A) 致病菌為絕對胞內寄生的Mycobacterium leprae","(B) Mycobacterium leprae是唯一侵犯周邊神經的細菌","(C) Tuberculoid leprosy（TT）臨床上表現常見為單一病灶，同時伴隨有局部神經麻痺現象，但有時仍會因免疫力下降轉變成borderline tuberculoid leprosy（BT）","(D) Jopling's type I reaction特別常見於borderline lepromatous leprosy，Jopling's type II reaction多數發生在lepromatous leprosy"],"answer":[1,2],"image":"","answer_note":"更正:第40題答Ｂ、Ｃ給分"},{"id":"md4-106-2-41","subject":"md4","topic":"皮膚-腫瘤","meta":"106年第2次第41題","year":106,"session":2,"number":41,"question":"有關判斷是否為皮膚黑色素細胞癌（cutaneous melanoma）的ABCD口訣敘述，下列何者正確？","options":["(A) A：不對稱（asymmetry）：病灶左右上下不對稱","(B) B：邊緣（border）：規則的邊緣","(C) C：顏色（color）：病灶色澤均勻","(D) D：直徑（diameter）：小於6 mm時要特別考慮是黑色素細胞癌"],"answer":0,"image":""},{"id":"md4-106-2-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"106年第2次第42題","year":106,"session":2,"number":42,"question":"對於硬皮病（morphea）的敘述，下列何者錯誤？","options":["(A) 沿著Blaschko's line表現的linear morphea常出現在小兒患者","(B) circumscribed morphea患者身上並不會出現指端硬化現象，也不會有食道硬化等內臟器官影響","(C) generalized morphea患者血中ANA可能呈現陽性，但與患者預後關聯性仍未明","(D) generalized morphea多數病人會轉變為systemic sclerosis，出現指節腫大，吞嚥困難，以及續發性雷諾氏症候群"],"answer":3,"image":""},{"id":"md4-106-2-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"106年第2次第43題","year":106,"session":2,"number":43,"question":"66歲男性出現如圖所示病灶，最可能診斷，與最重要的臨床特徵為何？","options":["(A) 紅斑性狼瘡（lupus erythematosus）；狼瘡性脂肪炎（lupus panniculitis）","(B) 全身性硬皮症（systemic sclerosis）；手指硬化（sclerodactyly）、手指潰瘍（digital ulcerations）","(C) 類風濕性關節炎（rheumatoid arthritis）；類風濕性結節（rheumatoid nodules）","(D) 皮肌炎（dermatomyositis）；Gottron氏徵候（Gottron sign）"],"answer":1,"image":"md4-106-2-43.jpeg"},{"id":"md4-106-2-44","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"106年第2次第44題","year":106,"session":2,"number":44,"question":"20歲女性，在前胸出現如圖所示之病變，下列何種檢查無助於其診斷？","options":["(A) 伍氏燈可幫助脫色斑的顯現","(B) KOH鏡檢排除變色糠疹","(C) 皮膚切片DOPA染色陽性細胞減少","(D) 直接免疫螢光檢查出現lupus band"],"answer":3,"image":"md4-106-2-44.jpeg"},{"id":"md4-106-2-45","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"106年第2次第45題","year":106,"session":2,"number":45,"question":"承上題，該患者可接受下列治療獲得改善，下列何者例外？","options":["(A) topical glucocorticoid","(B) narrowband UVB（311 nm）","(C) Nd-YAG laser（532 nm）","(D) excimer light（308 nm）"],"answer":2,"image":""},{"id":"md4-106-2-46","subject":"md4","topic":"神經-中風","meta":"106年第2次第46題","year":106,"session":2,"number":46,"question":"60歲男性，有高血壓、糖尿病的病史，突發肢體無力、說話困難、站立不穩、複視、頭暈等症狀，神經學檢查顯示右側肢體肌力下降、左側肢體失調、兩眼的眼球無法向外側轉動。病灶最可能在何處？","options":["(A) 視丘（thalamus）","(B) 中腦（midbrain）","(C) 橋腦（pons）","(D) 延腦（medulla）"],"answer":2,"image":""},{"id":"md4-106-2-47","subject":"md4","topic":"神經-中風","meta":"106年第2次第47題","year":106,"session":2,"number":47,"question":"下列有關腦中風的敘述，何者錯誤？","options":["(A) 使用抗血小板藥物，有預防缺血性中風再發的效果","(B) 治療高血壓，可有效降低中風的發生","(C) 抽煙與腦中風，無直接的關聯性","(D) 缺血性腦中風的病人，只要合併心房震顫，應建議接受抗凝血劑治療"],"answer":2,"image":""},{"id":"md4-106-2-48","subject":"md4","topic":"神經-中風","meta":"106年第2次第48題","year":106,"session":2,"number":48,"question":"A先生，65歲男性，有高血壓病史多年，早上吃完早飯後，突然頭暈，步態不穩，被送至急診室，身體神經功能檢查，發現講話口語不清，吞嚥困難，右側gag reflex消失，左側疼痛感覺遲鈍，其病灶最可能與下列那條血管堵塞有關？","options":["(A) 右側後下小腦動脈","(B) 左側後下小腦動脈","(C) 右側前下小腦動脈","(D) 左側前下小腦動脈"],"answer":0,"image":""},{"id":"md4-106-2-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"106年第2次第49題","year":106,"session":2,"number":49,"question":"下列那些病人不宜使用triptans來治療偏頭痛？","options":["(A) 合併有心血管疾病","(B) 典型的視覺預兆偏頭痛","(C) 有持續10分鐘的感覺預兆的偏頭痛","(D) 合併有憂鬱症的病人"],"answer":0,"image":""},{"id":"md4-106-2-50","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"106年第2次第50題","year":106,"session":2,"number":50,"question":"下列關於癲癇發作型態國際分類的敘述，何者錯誤？","options":["(A) 失神性癲癇（absence seizures）屬於全面發作（generalized seizures）的癲癇型態","(B) 局部癲癇（focal seizures）發作的型態可以出現局部陣攣發作（focal clonic seizures）","(C) 癲癇發作型態的分類以臨床肢體表現的對稱與否為依據","(D) 癲癇發作型態的分類必須同時依據癲癇發作的腦電圖為依據"],"answer":[2,3],"image":"","answer_note":"更正:第50題答Ｃ、Ｄ給分"},{"id":"md4-106-2-51","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"106年第2次第51題","year":106,"session":2,"number":51,"question":"下列關於全面性強直陣攣癲癇發作（generalized tonic-clonic seizures）的敘述，何者錯誤？","options":["(A) 一定會造成意識上的喪失","(B) 通常不會有前兆（aura）","(C) ictal cry（或piercing cry）是導因於呼吸肌與咽喉肌的強直攣縮","(D) 發作時因副交感作用的加強會導致血壓上升、心跳急促及瞳孔放大"],"answer":3,"image":""},{"id":"md4-106-2-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"106年第2次第52題","year":106,"session":2,"number":52,"question":"下列何者與APOE基因的ε多型性（Polymorphism）關係最為密切？4","options":["(A) 巴金森失智症（Parkinson disease dementia）","(B) 額顳葉失智症（frontotemporal dementia）","(C) 阿茲海默失智症（Alzheimer dementia）","(D) 血管性失智症（vascular dementia）"],"answer":2,"image":""},{"id":"md4-106-2-53","subject":"md4","topic":"神經-失智退化運動障礙","meta":"106年第2次第53題","year":106,"session":2,"number":53,"question":"一位70歲的女性接受簡短智能測驗時，可以輕易地複誦三個不相關的名詞，經過五分鐘的計算能力檢測，大致正常；但是，此時卻無法自由回憶剛剛三個名詞，即使給予提示，還是沒有辦法回想出來。這位女性可能是：","options":["(A) 注意力不足","(B) 失語症","(C) 記憶的提取問題","(D) 海馬迴功能障礙"],"answer":3,"image":""},{"id":"md4-106-2-54","subject":"md4","topic":"神經-失智退化運動障礙","meta":"106年第2次第54題","year":106,"session":2,"number":54,"question":"大多數阿茲海默症的病人，在疾病早期受影響最多的認知功能為：","options":["(A) 情節性記憶（episodic memory）","(B) 人臉的辨認（face recognition）","(C) 穿衣服的能力（dressing）","(D) 人格改變（personality change）"],"answer":0,"image":""},{"id":"md4-106-2-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"106年第2次第55題","year":106,"session":2,"number":55,"question":"有關橈骨神經之敘述，下列何者錯誤？","options":["(A) 主要支配triceps、brachioradialis、supinator及extensors of the fingers等肌肉","(B) 神經主要源自頸椎第6～8節神經根","(C) 如果posterior interosseous nerve受傷，只會侵犯到手臂之伸肌","(D) 在鉛中毒患者常見本神經之侵犯"],"answer":2,"image":""},{"id":"md4-106-2-56","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"106年第2次第56題","year":106,"session":2,"number":56,"question":"一位26歲負責工廠會計工作之許小姐，身體一向健康，近2星期常覺得疲倦，皮膚出現紅疹（rash），全身無力，幾天前發現小腿有些腫脹感，尿液也呈現淡茶褐色，而至門診求助。你認為這位許小姐，最可能的診斷是什麼？","options":["(A) 重症肌無力症（myasthenia gravis）","(B) 皮肌炎（dermatomyositis）","(C) 肌強直性失養症（myotonic dystrophy）","(D) 代謝性肌病變（metabolic myopathy）"],"answer":1,"image":""},{"id":"md4-106-2-57","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"106年第2次第57題","year":106,"session":2,"number":57,"question":"下列有關神經系統病變的敘述，何者錯誤？","options":["(A) 鉛（lead）可以損害末稍神經","(B) 汞（mercury）可能引起中樞與周邊神經損傷","(C) 砷（arsenic）中毒可能發生消化與神經系統的症狀","(D) 紫質症（porphyria）與用藥無關"],"answer":3,"image":""},{"id":"md4-106-2-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"106年第2次第58題","year":106,"session":2,"number":58,"question":"下列有關神經性梅毒（neurosyphilis）之敘述，何者錯誤？","options":["(A) 10%沒有接受治療的早期梅毒的患者會罹病","(B) 因為AIDS的盛行，神經性梅毒的發生率增高","(C) 腦脊髓液的螺旋菌抗體（treponemal antibody）陽性反應有助於診斷","(D) 治療方法為經肌肉注射盤尼西林（penicillin）每週一次共三次"],"answer":[0,3],"image":"","answer_note":"更正:第58題答Ａ、Ｄ給分"},{"id":"md4-106-2-59","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"106年第2次第59題","year":106,"session":2,"number":59,"question":"下列有關腦膜瘤（meningioma）之敘述，何者正確？","options":["(A) 使用抗女性荷爾蒙（antiestrogen）治療是有效的","(B) 應先使用放射線治療（radiotherapy）","(C) 是後顱窩（posterior fossa）最常見之腫瘤","(D) 加碼刀（gamma knife）的治療限於小於3公分者"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第59題一律給分 (原公告答案 D)"},{"id":"md4-106-2-60","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"106年第2次第60題","year":106,"session":2,"number":60,"question":"腦部原發性淋巴瘤（primary central nervous system lymphoma）的治療方式中，下列何者最不適當？","options":["(A) 外科手術","(B) 類固醇","(C) 放射治療","(D) 化學療法"],"answer":0,"image":""},{"id":"md4-106-2-61","subject":"md4","topic":"精神-精神病","meta":"106年第2次第61題","year":106,"session":2,"number":61,"question":"思覺失調症（schizophrenia）患者的症狀可分為正性症狀（positive symptoms）與負性症狀（negative symptoms），下列何者是負性症狀？","options":["(A) 妄想（delusions）","(B) 幻覺（hallucinations）","(C) 貧語（alogia）","(D) 混亂語言（disorganized speech）"],"answer":2,"image":""},{"id":"md4-106-2-62","subject":"md4","topic":"精神-精神病","meta":"106年第2次第62題","year":106,"session":2,"number":62,"question":"有關雙極性疾患（bipolar disorders）的敘述，下列何者錯誤？","options":["(A) 第一型雙極性疾患也可能有妄想症狀","(B) 男女得病比率與重鬱症（major depressive disorder）相同","(C) 第二型雙極性疾患須至少有一次輕躁發作與一次重鬱發作","(D) 可能於青少年時期發作"],"answer":1,"image":""},{"id":"md4-106-2-63","subject":"md4","topic":"精神-精神病","meta":"106年第2次第63題","year":106,"session":2,"number":63,"question":"24歲男性思覺失調症（schizophrenia）患者，因為拒服藥一年致症狀惡化，醫師評估後，給予haloperidol針劑肌肉注射，12小時後，個案突然出現眼球上吊、脖子僵硬及軀幹扭曲，下列敘述，何者最正確？","options":["(A) 為癲癇發作，須給予抗癲癇藥物","(B) 為急性肌肉失張（acute dystonia），宜立即給予抗乙醯膽鹼藥物肌肉注射","(C) 為遲發性運動失調（tardive dyskinesia），宜換成第二代抗精神病藥物","(D) 抗焦慮劑為其禁忌用藥"],"answer":1,"image":""},{"id":"md4-106-2-64","subject":"md4","topic":"精神-精神病","meta":"106年第2次第64題","year":106,"session":2,"number":64,"question":"對於雙極性疾患（bipolar disorder）治ऋ之敘述，何者正確？","options":["(A) 急性躁期可以給予鋰鹽、抗癲癇藥物、或抗精神病藥物治療","(B) 維持（maintenance）治療可使用抗癲癇藥物或鋰鹽，但只有鋰鹽需進行血中藥物濃度監測","(C) 抗癲癇藥物lamotrigine對於預防躁症效果優於其他抗癲癇藥物","(D) 電痙攣治ऋ（electroconvulsive therapy）不適合治療雙極性疾患之鬱期"],"answer":0,"image":""},{"id":"md4-106-2-65","subject":"md4","topic":"精神-精神官能症","meta":"106年第2次第65題","year":106,"session":2,"number":65,"question":"下列何者不屬於美國精神醫學會「精神疾患診斷及統計手冊第四版」之焦慮性疾患（anxiety disorders）？","options":["(A) 創傷後壓力疾患","(B) 恐慌症","(C) 適應障礙合併焦慮","(D) 社交畏懼症"],"answer":2,"image":""},{"id":"md4-106-2-66","subject":"md4","topic":"精神-精神官能症","meta":"106年第2次第66題","year":106,"session":2,"number":66,"question":"楊小姐在與長官爭吵後，突然講不出話來，一個多月來在許多科別診治，並未發現有任何器官上的問題。今日來精神科就診，精神科醫師診斷楊小姐的講不出話並不是刻意裝出來，不過其症狀不是神經學或是其他生理疾病可以解釋。楊小姐最可能的診斷為何？","options":["(A) 詐病（malingering）","(B) 偽病（factitious disorder）","(C) 解離症（dissociative disorder）","(D) 轉化症（conversion disorder）"],"answer":[2,3],"image":"","answer_note":"更正:第66題答Ｃ、Ｄ給分"},{"id":"md4-106-2-67","subject":"md4","topic":"精神-精神官能症","meta":"106年第2次第67題","year":106,"session":2,"number":67,"question":"有關焦慮反應之敘述，何者最不適切？","options":["(A) 與焦慮反應相關的三種最主要神經傳導物質為血清素、正腎上腺素、乙醯膽鹼","(B) 適當的焦慮反應本身具有保護性及適應性","(C) 當焦慮反應過強時會呈現交感神經興奮之相關症狀","(D) 當焦慮反應造成日常生活功能、職業或社交功能損害時，需要就醫"],"answer":0,"image":""},{"id":"md4-106-2-68","subject":"md4","topic":"精神-精神官能症","meta":"106年第2次第68題","year":106,"session":2,"number":68,"question":"憂鬱症患者常見的快速動眼期睡眠（rapid eye movement sleep）之潛期（latency）變化為何？","options":["(A) 不變","(B) 縮短","(C) 延長","(D) 不會出現潛期"],"answer":1,"image":""},{"id":"md4-106-2-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"106年第2次第69題","year":106,"session":2,"number":69,"question":"戒菸的人可能出現下列何種尼古丁戒斷症狀？","options":["(A) 心搏速降低","(B) 體重減輕","(C) 降低肌肉張力","(D) 血壓升高"],"answer":0,"image":""},{"id":"md4-106-2-70","subject":"md4","topic":"精神-器質性與物質使用","meta":"106年第2次第70題","year":106,"session":2,"number":70,"question":"推測人體血液中酒精濃度至少須達到多少mg/dL才可能出現眼球震顫、言語不清等症狀？","options":["(A) 50","(B) 100","(C) 200","(D) 400"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第70題一律給分 (原公告答案 C)"},{"id":"md4-106-2-71","subject":"md4","topic":"精神-精神病","meta":"106年第2次第71題","year":106,"session":2,"number":71,"question":"思覺失調症（schizophrenia）患者所呈現之「新語症」（neologism），屬於下列何種障礙？","options":["(A) 知覺障礙","(B) 語言障礙","(C) 思考障礙","(D) 行為障礙"],"answer":2,"image":""},{"id":"md4-106-2-72","subject":"md4","topic":"精神-器質性與物質使用","meta":"106年第2次第72題","year":106,"session":2,"number":72,"question":"關於幻覺劑相關疾患（hallucinogen-related disorders）之敘述，下列何者錯誤？","options":["(A) 跟其他物質濫用疾患相較，幻覺劑較少出現合併症（comorbidity）及死亡（mortality）","(B) 幻覺劑中毒的症狀包括知覺改變，如現實失真感、幻覺等；而身體上的症狀包括瞳孔變大、心跳加快、冒汗、視力模糊及顫抖等等","(C) 幻覺劑使用常見於年輕族群，其中又以女性較男性為多","(D) D-麥角酸二乙胺（lysergic acid diethylamide, LSD）最主要是影響血清素系統"],"answer":2,"image":""},{"id":"md4-106-2-73","subject":"md4","topic":"精神-器質性與物質使用","meta":"106年第2次第73題","year":106,"session":2,"number":73,"question":"關於安非他命的描述何者錯誤？","options":["(A) 常與促進腦中多巴胺（dopamine）的釋放有關","(B) 安非他命中毒時，若停止使用，其中毒症狀多在2天內消失","(C) 安非他命戒斷最嚴重的症狀是焦慮","(D) 安非他命戒斷會使食慾增加"],"answer":2,"image":""},{"id":"md4-106-2-74","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"106年第2次第74題","year":106,"session":2,"number":74,"question":"下列有關注意力缺損／過動症（ADHD）兒童的敘述何者錯誤？","options":["(A) 由於其學業成就低、人際關係不佳，常常導致自尊心低落，在青春期時可能會加入偏差行為同儕團體","(B) 應用行為治療時，必須要有詳盡的行為觀察、詳細說明行為契約、適時給予回饋物","(C) 低於1/10的ADHD兒童到成年期仍符合ADHD診斷","(D) 目前台灣衛生福利部核准用以治療ADHD的藥物包括methylphenidate和atomoxetine"],"answer":2,"image":""},{"id":"md4-106-2-75","subject":"md4","topic":"精神-器質性與物質使用","meta":"106年第2次第75題","year":106,"session":2,"number":75,"question":"安非他命引起之精神病不易與思覺失調症（schizophrenia）區別，下列何者不是安非他命引起之精神病的特色？","options":["(A) 不適切之情感","(B) 視幻覺","(C) 活動量增加","(D) 性慾增加"],"answer":0,"image":""},{"id":"md4-106-2-76","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"106年第2次第76題","year":106,"session":2,"number":76,"question":"10歲女生因發高燒不退、劇烈右側腰痛而住院，注射對比劑後的電腦斷層掃描影像如圖，下列原因何者最為可能？","options":["(A) 腎盂腎炎","(B) 腎絲球炎","(C) 水腎","(D) 腎動脈栓塞"],"answer":3,"image":"md4-106-2-76.jpeg"},{"id":"md4-106-2-77","subject":"md4","topic":"兒科-心血管呼吸","meta":"106年第2次第77題","year":106,"session":2,"number":77,"question":"下列何者非會厭炎（epiglottitis）典型之症狀？","options":["(A) 喘鳴（stridor）","(B) 吞嚥困難（dysphagia）","(C) 哮鳴（wheezing）","(D) 流涎（drooling）"],"answer":2,"image":""},{"id":"md4-106-2-78","subject":"md4","topic":"精神-器質性與物質使用","meta":"106年第2次第78題","year":106,"session":2,"number":78,"question":"酒精戒斷癲癎（alcohol withdrawal seizure）之敘述，下列何者為最適當?","options":["(A) 常發生在停止喝酒五至六天後","(B) 發生single seizure比multiple generalized seizure比例高","(C) 大多發生在停止喝酒2天內","(D) 超過70%以上產生酒精戒斷癲癎病人會合併有delirium tremens"],"answer":2,"image":""},{"id":"md4-106-2-79","subject":"md4","topic":"醫學倫理與法規","meta":"106年第2次第79題","year":106,"session":2,"number":79,"question":"依我國相關法律規定，下列敘述何者錯誤？","options":["(A) 兒童及少年福利法規定，未滿12歲者為兒童","(B) 兒童及少年福利法規定，12歲以上18歲未滿者為少年","(C) 民法規定，未滿12歲的未成年人無行為能力","(D) 民法規定，滿20歲（且未受監護宣告）的人有完全行為能力"],"answer":[0,1,2],"image":"","answer_note":"更正:第79題答Ａ、Ｂ、Ｃ給分。"},{"id":"md4-106-2-80","subject":"md4","topic":"醫學倫理與法規","meta":"106年第2次第80題","year":106,"session":2,"number":80,"question":"12歲小婷罹患第一型糖尿病已有2年，這期間她因為暴瘦、多尿、喘息及脫水進出醫院加護病房已有7次，醫師懷疑她沒有遵循治療計畫，沒有施打胰島素。雖然經多方輔導及說服，她仍堅不配合，家屬也一副事不關己的態度，認為一切問題往醫院送就會得到解決。現在，她又很危急地被送到急診室來，下列何種處置最合適？","options":["(A) 通報社會局等相關主管單位","(B) 可以直接判定小婷沒有醫療決策能力","(C) 加入心理諮商或精神醫療之專業輔導治療","(D) 延長病童住院時間直到解決拒絕治療之問題"],"answer":2,"image":""},{"id":"md4-107-1-1","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"107年第1次第1題","year":107,"session":1,"number":1,"question":"足月兒出生時，母親有發燒症狀且羊膜已在出生前兩天破裂，嬰兒於出生後8小時開始明顯的呼吸窘迫，血壓下降，胸部X光呈現雙側全面的浸潤，並有少許肋膜腔積水，最可能的診斷為下列何者？","options":["(A) 大腸桿菌（Escherichia coli）感染","(B) 綠膿桿菌（Pseudomonas spp.）感染","(C) 肺炎鏈球菌（Streptococcus pneumoniae）感染","(D) B群鏈球菌（group B Streptococcus）感染"],"answer":3,"image":""},{"id":"md4-107-1-2","subject":"md4","topic":"兒科-感染神經","meta":"107年第1次第2題","year":107,"session":1,"number":2,"question":"幼稚園中班的小恩，前年和去年皆施打過流行性感冒疫苗，半個月前被診斷得了流行性感冒，而服用了克流感（oseltamivir）治療。有關小恩後續的流感防範措施，下列何者是最佳的選擇？","options":["(A) 今年施打一劑流感疫苗","(B) 年齡未達8歲且打過疫苗又得病，今年應施打兩劑流感疫苗","(C) 已服用過克流感，今年不必施打流感疫苗","(D) 流感疫苗無效，明年不要施打"],"answer":0,"image":""},{"id":"md4-107-1-3","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第1次第3題","year":107,"session":1,"number":3,"question":"7歲男童發燒、咳嗽3天，肺部聽診兩側有細囉音（fine crackles），經使用cefotaxime 150 mg/kg/day q6h治療3天之後，發燒持續存在，但該男童活力良好，無呼吸窘迫，胸部X光片呈對稱性間質性浸潤。下列那一項處置最適當？","options":["(A) 改用cefotaxime 300 mg/kg/day q6h","(B) 改用azithromycin 10 mg/kg/day qd","(C) 改用vancomycin 40 mg/kg/day q8h","(D) 改用penicillin 300,000 units/kg/day q6h"],"answer":1,"image":""},{"id":"md4-107-1-4","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第1次第4題","year":107,"session":1,"number":4,"question":"母親懷疑2歲女兒誤食異物而將她帶至急診室，母親主訴女童過去一直很好，剛才與哥哥在遊戲室玩耍，哥哥發現女童疑似吞下某物體，並開始咳嗽及哭泣，檢查時發現女童無發紺，呼吸略快，呼吸音正常，下列何項為最適當的處置？","options":["(A) 衛教後返家觀察","(B) 頸部及胸部X光檢查","(C) 上消化道鋇劑檢查","(D) 電腦斷層攝影檢查"],"answer":1,"image":""},{"id":"md4-107-1-5","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"107年第1次第5題","year":107,"session":1,"number":5,"question":"足月產的新生兒，出生體重3500公克，出生後第5天體重4200公克，腎臟超音波顯示有雙側水腎（hydronephrosis）及輸尿管擴大（hydroureter），膀胱壁厚而不規則，下列何者為最可能的診斷？","options":["(A) 膀胱輸尿管逆流（bilateral vesicoureteral reflux）","(B) 後尿道瓣（posterior urethral valves）","(C) 輸尿管膀胱接合處阻塞（ureterovesical junction stenosis）","(D) 輸尿管腎盂接合處阻塞（ureteropelvic junction stenosis）"],"answer":1,"image":""},{"id":"md4-107-1-6","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"107年第1次第6題","year":107,"session":1,"number":6,"question":"15歲男孩，因急性腎衰竭而需進行緊急之透析治療。尿液檢查發現男童有血尿及嚴重之蛋白尿（二十四小時尿蛋白值為7.6 g/24 hr）。血中的血清白蛋白值為3.2 g/dL，血中補體C3、C4均正常。腎切片發現Bowman's capsule內有細胞性的半月型增生（epithelial cell crescent formation），如圖所示，螢光染色可見免疫複合體沈積。下列何者診斷最恰當？","options":["(A) 鏈球菌感染後之急性腎炎（poststreptococcal glomerulonephritis）合併急性腎衰竭","(B) IgA腎炎（IgA nephropathy）合併急性腎衰竭","(C) WHO分類之第四類狼瘡性腎炎（WHO class IV lupus nephritis）合併急性腎衰竭","(D) ANCA-mediated腎絲球腎炎（ANCA-mediated glomerulonephritis）合併急性腎衰竭"],"answer":1,"image":"md4-107-1-6.jpeg"},{"id":"md4-107-1-7","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"107年第1次第7題","year":107,"session":1,"number":7,"question":"懷孕週數28週的早產兒，出生後五個月時至門診健康檢查。下列何種評估及建議最為正確？","options":["(A) 評估發展應該以兩個月年齡計算","(B) 如果還不會抓握東西，表示細動作發展遲緩","(C) 建議父母應該添加副食品","(D) 建議開始使用學步車以促進粗動作發展"],"answer":0,"image":""},{"id":"md4-107-1-8","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"107年第1次第8題","year":107,"session":1,"number":8,"question":"注意力不集中過動症（attention-deficit/hyperactivity disorder；ADHD）典型的診斷條件，不包括下列何者？","options":["(A) 注意力不足（inattention）","(B) 過動（hyperactivity）","(C) 衝動（impulsivity）","(D) 智能不足（mental retardation）"],"answer":3,"image":""},{"id":"md4-107-1-9","subject":"md4","topic":"兒科-內分泌遺傳","meta":"107年第1次第9題","year":107,"session":1,"number":9,"question":"12歲女童，因為身材矮小而就診，父親身高165公分，母親身高154公分。最近一年長3公分。身體診查顯示身高130公分（低於第3百分位），體重30公斤（第10百分位），無第二性徵發育，其他器官亦未發現異常。當時骨齡檢查為9歲，若要確切診斷，下列那一項刺激試驗，對診斷最無參考價值？","options":["(A) 運動（exercise）","(B) 胰島素（insulin）","(C) 精氨酸（arginine）","(D) 升糖素（glucagon）"],"answer":0,"image":""},{"id":"md4-107-1-10","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"107年第1次第10題","year":107,"session":1,"number":10,"question":"兒童時期發生的系統性紅斑性狼瘡（systemic lupus erythematosus, SLE），預後比成人時期才發作的系統性紅斑性狼瘡的預後差，主要是兒童的那個器官系統較易受影響？","options":["(A) 心臟","(B) 中樞神經系統","(C) 腎臟","(D) 血液"],"answer":2,"image":""},{"id":"md4-107-1-11","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"107年第1次第11題","year":107,"session":1,"number":11,"question":"關於缺鐵性貧血（iron-deficiency anemia, IDA）的敘述，下列何者錯誤？","options":["(A) 低體重早產兒為好發族群","(B) 青春期後的女性罹患慢性缺鐵性貧血應考慮月經過多","(C) 患者血清中（serum）ferritin是下降的","(D) 足月兒的缺鐵性貧血常發生在出生後前3個月"],"answer":3,"image":""},{"id":"md4-107-1-12","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第1次第12題","year":107,"session":1,"number":12,"question":"1個月大的新生兒，睡眠時正常心跳的範圍為：","options":["(A) 100～140次/分","(B) 160～180次/分","(C) 80～100次/分","(D) 180～220次/分"],"answer":0,"image":""},{"id":"md4-107-1-13","subject":"md4","topic":"兒科-內分泌遺傳","meta":"107年第1次第13題","year":107,"session":1,"number":13,"question":"某些特定先天性代謝異常疾病治療原則是飲食控制，以特殊配方奶粉而言，下列何種疾病是最無效的？","options":["(A) 半乳糖血症（galactosemia）","(B) 典型苯酮尿症（phenylketonuria）","(C) 典型高胱胺酸尿症（homocystinuria）","(D) 葡萄糖-6-磷酸去氫酶（glucose-6-phosphate dehydrogenase）缺乏症"],"answer":3,"image":""},{"id":"md4-107-1-14","subject":"md4","topic":"兒科-感染神經","meta":"107年第1次第14題","year":107,"session":1,"number":14,"question":"沙門氏菌（salmonella）會引起兒童的細菌性腸胃炎，關於沙門氏菌的敘述，下列何者錯誤？","options":["(A) 免疫不全的病童比一般兒童更容易發生菌血症","(B) 當腸胃炎孩童只有糞便培養出沙門氏菌，但血液培養未長菌，標準治療是及早給與抗生素","(C) 幼童應避免接觸爬蟲類、兩棲類的動物，以免被沙門氏菌感染","(D) 沙門氏菌腸炎的併發症包含反應性關節炎（reactive arthritis）"],"answer":1,"image":""},{"id":"md4-107-1-15","subject":"md4","topic":"兒科-感染神經","meta":"107年第1次第15題","year":107,"session":1,"number":15,"question":"新生兒出生時身高體重及頭圍正常，7天大時發燒，鞏膜呈現黃色，肝脾腫大，聽力檢查異常，最有可能是下列何種感染？","options":["(A) 單純性疱疹（herpes simplex virus）","(B) 先天性梅毒（congenital syphilis）","(C) Ｂ型肝炎（hepatitis B virus）","(D) 先天性巨細胞病毒（congenital cytomegalovirus）"],"answer":3,"image":""},{"id":"md4-107-1-16","subject":"md4","topic":"兒科-消化系統疾病","meta":"107年第1次第16題","year":107,"session":1,"number":16,"question":"6週大男嬰，從1週前吐奶的情況，突然越吐越厲害，最近幾乎每一餐喝完奶半小時內很快就吐光，吐出的內容物為沒有黃綠色，體重也沒有增加反而減少，住院後若抽血檢驗動脈血氣體分析（arterial blood gas analysis），最有可能會呈現下列那種結果？","options":["(A) 代謝性鹼中毒（metabolic alkalosis）","(B) 代謝性酸中毒（metabolic acidosis）","(C) 呼吸性鹼中毒（respiratory alkalosis）","(D) 呼吸性酸中毒（respiratory acidosis）"],"answer":0,"image":""},{"id":"md4-107-1-17","subject":"md4","topic":"兒科-消化系統疾病","meta":"107年第1次第17題","year":107,"session":1,"number":17,"question":"關於C型肝炎（hepatitis C），下列何者錯誤？","options":["(A) 和B型肝炎相比，C型肝炎垂直感染（perinatal transmission）的比率較低","(B) 若母親為C型肝炎帶原者且合併有高病毒血症或合併有愛滋病毒感染時，則垂直感染的風險會增加","(C) C型肝炎急性感染20～30年後，部分患者會進展至肝硬化（cirrhosis）、肝衰竭（liver failure）甚至肝癌（hepatocellular carcinoma）","(D) 目前可以接種疫苗預防"],"answer":3,"image":""},{"id":"md4-107-1-18","subject":"md4","topic":"兒科-消化系統疾病","meta":"107年第1次第18題","year":107,"session":1,"number":18,"question":"為正確診斷非酒精性脂肪肝疾病（nonalcoholic fatty liver disease），下列何項敘述，不是需做肝臟超音波檢查此病的危險因子？","options":["(A) 胰島素抗性（insulin resistance）","(B) 3歲以上肥胖男童","(C) B型肝炎帶原者（hepatitis B carrier）","(D) 三酸苷油酯（triglyceride）過高"],"answer":2,"image":""},{"id":"md4-107-1-19","subject":"md4","topic":"兒科-消化系統疾病","meta":"107年第1次第19題","year":107,"session":1,"number":19,"question":"一位兒童因腹瀉求診，他排的糞便為稀水便，糞便檢驗並無白血球（leukocytes），臨床上呈現因禁食而改善症狀，下列那一種檢查結果最為吻合？","options":["(A) 糞便檢查中無還原物質（reducing substances）","(B) 吐氣中氫氣濃度降低（decreased breath hydrogen）","(C) 困難梭狀桿菌（Clostridium difficile）毒素檢測為陽性","(D) 糞便離子間距（ion gap）大於200 mOsm/kg"],"answer":3,"image":""},{"id":"md4-107-1-20","subject":"md4","topic":"兒科-消化系統疾病","meta":"107年第1次第20題","year":107,"session":1,"number":20,"question":"關於梅克爾憩室（Meckel diverticulum），下列敘述何者錯誤？","options":["(A) 最常見的臨床表現為無痛性出血，其次為腸阻塞","(B) 通常位於離迴盲瓣（ileocecal valve）50～75公分內的迴腸端","(C) 可能含有異位性組織（ectopic tissue），胃組織比胰組織常見","(D) 年紀小的幼童比年紀大的孩童，更易發生憩室炎（diverticulitis）"],"answer":3,"image":""},{"id":"md4-107-1-21","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"107年第1次第21題","year":107,"session":1,"number":21,"question":"下列何種疾病引起的低血鈉（hyponatremia）與血液稀釋無關？","options":["(A) 肝硬化（liver cirrhosis）","(B) 鬱血性心臟衰竭（congestive heart failure）","(C) 抗利尿激素不適當分泌症候群（syndrome of inappropriate antidiuretic hormone secretion）","(D) 腎病症候群（nephrotic syndrome）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第21題一律給分 (原公告答案 C)"},{"id":"md4-107-1-22","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"107年第1次第22題","year":107,"session":1,"number":22,"question":"關於兒童急性鏈球菌感染後腎臟發炎（acute poststreptococcal glomerulonephritis）的治療，下列敘述何者正確？","options":["(A) 由於為鏈球菌感染所引起的，因此給與適當的抗生素治療可以縮短病程","(B) 高血壓的治療包括給與鈣離子抑制劑（calcium channel antagonists）或利尿劑（diuretics）","(C) 限制鈉離子的攝取，主要是針對慢性腎臟病的預防","(D) 類固醇為首選的治療藥物"],"answer":1,"image":""},{"id":"md4-107-1-23","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"107年第1次第23題","year":107,"session":1,"number":23,"question":"7歲兒童，自一年前起陸續出現清喉嚨的聲音，睡覺時聲音消失，緊張時更明顯，關於此疾病的敘述，下列何者正確？","options":["(A) 大多發生於女性","(B) 需注意有無合併注意力不集中過動異常（attention-deficit/hyperactivity disorders）","(C) 需照肺部X光片","(D) 需做腦部影像檢查"],"answer":1,"image":""},{"id":"md4-107-1-24","subject":"md4","topic":"兒科-內分泌遺傳","meta":"107年第1次第24題","year":107,"session":1,"number":24,"question":"足月出生六個月大之男嬰，經身體診查發現四肢短小，頭圍正常，前囟門大，眼瞼水腫，皮膚乾燥且黃疸，頭髮粗糙，下列何者為最正確之診斷？","options":["(A) 先天性甲狀腺低能症（congenital hypothyroidism）","(B) 先天性甲狀腺亢進症（congenital hyperthyroidism）","(C) 純母奶餵食且餵食量不足","(D) 新生兒高黃疸（hyperbilirubinemia）之併發症"],"answer":0,"image":""},{"id":"md4-107-1-25","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"107年第1次第25題","year":107,"session":1,"number":25,"question":"有關牛奶蛋白過敏，下列敘述何者錯誤？","options":["(A) 通常在一歲之後出現","(B) 兒童隨著年齡的成長，症狀可能緩解","(C) 屬於一種IgE抗體主導（IgE-mediated）的過敏反應","(D) 對牛奶蛋白過敏的兒童，改用羊奶或羊奶嬰兒配方，並沒有預防過敏的效果"],"answer":0,"image":""},{"id":"md4-107-1-26","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"107年第1次第26題","year":107,"session":1,"number":26,"question":"關於異位性皮膚炎（atopic dermatitis）的敘述，下列何者錯誤？","options":["(A) 嬰幼兒最常見之慢性復發性皮膚病（chronic relapsing disease），約一半的病人在一歲前發病","(B) Filaggrin基因的缺損可於所有異位性皮膚炎病童身上發現","(C) 異位性皮膚炎是和第二型輔助型T細胞（T-helper type 2 cells）有關的發炎疾病，因此多數患者血中IgE會上升","(D) 嚴重異位性皮膚炎可考慮使用口服類固醇，如長期使用，停藥時須逐漸減量，以避免反彈（rebound effect）"],"answer":1,"image":""},{"id":"md4-107-1-27","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"107年第1次第27題","year":107,"session":1,"number":27,"question":"過敏性鼻炎（allergic rhinitis）的敘述，下列何者錯誤？","options":["(A) 盛行率最高的學童慢性過敏性疾病","(B) 病人日後罹患氣喘的風險，是無過敏性鼻炎的人的三倍高","(C) 常伴隨著過敏性結膜炎發生，且比較容易發生中耳炎及鼻竇炎","(D) 嚴重之過敏性鼻炎病人常有鼻塞症狀而影響生活品質，治療需以抗組織胺（anti-histamine agent）和局部鼻用去充血劑（intranasal decongestant）合併治療2到4週，來改善生活品質"],"answer":3,"image":""},{"id":"md4-107-1-28","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"107年第1次第28題","year":107,"session":1,"number":28,"question":"關於兒童惡性肝腫瘤（malignant hepatic tumor）的敘述，下列何者最不恰當？","options":["(A) 肝母細胞癌（hepatoblastoma）主要發生在3歲以下的小孩，而肝細胞癌（hepatocellular carcinoma）的發病年齡較大","(B) Beckwith-Wiedemann syndrome的患者，較易發生肝母細胞癌（hepatoblastoma）","(C) 由於B型肝炎疫苗的施打，已讓國內肝母細胞癌（hepatoblastoma）發生率顯著下降，但肝細胞癌（hepatocellular carcinoma）則比率維持不變","(D) 肝細胞癌（hepatocellular carcinoma）容易轉移至肺部，影響預後"],"answer":2,"image":""},{"id":"md4-107-1-29","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"107年第1次第29題","year":107,"session":1,"number":29,"question":"有關兒童淋巴癌的敘述，下列何者錯誤？","options":["(A) 在臺灣10歲以下的孩童，非何傑金氏淋巴瘤（Non-Hodgkin lymphoma）的發生率，比何傑金氏淋巴瘤（Hodgkin lymphoma）高","(B) 大部分非何傑金氏淋巴瘤患童為新發性的（de novo）疾病，少部分有免疫缺陷的孩童則是次發性的（secondary）得到非何傑金氏淋巴瘤","(C) 與成人大部分是緩慢進展的（indolent）不同，兒童的非何傑金氏淋巴瘤，通常是高度惡性且具侵略性的（high grade and aggressive），所以預後甚差","(D) 勃氏淋巴瘤（Burkitt lymphoma）患童，會出現腫瘤溶解症後群（tumor lysis syndrome），需特別加以留意"],"answer":2,"image":""},{"id":"md4-107-1-30","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第1次第30題","year":107,"session":1,"number":30,"question":"雖然兒科病童少有心臟腫瘤（cardiac tumors）的發生，但若出現時，常造成心律不整及心衰竭的症狀，下列何種心臟腫瘤最為常見？","options":["(A) 纖維瘤（fibroma）","(B) 橫紋肌瘤（rhabdomyoma）","(C) 黏液瘤（myxoma）","(D) 淋巴瘤（lymphoma）"],"answer":1,"image":""},{"id":"md4-107-1-31","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第1次第31題","year":107,"session":1,"number":31,"question":"下列疾病，何者不是引起嬰幼兒發生鬱血性心衰竭（congestive heart failure）的原因？","options":["(A) 左心到右心分流（left-to-right cardiac shunts）","(B) 心室上心搏過速（supraventricular tachycardia）","(C) 心肌炎（myocarditis）","(D) 心內膜炎（endocarditis）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第31題一律給分 (原公告答案 D)"},{"id":"md4-107-1-32","subject":"md4","topic":"兒科-內分泌遺傳","meta":"107年第1次第32題","year":107,"session":1,"number":32,"question":"有關小胖威利症候群（Prader-Willi Syndrome）的敘述，下列何者錯誤？","options":["(A) 母源性（maternal）染色體15q11-q13缺失","(B) 新生兒及嬰兒期會有嚴重低張力與餵食困難","(C) 小手與小腳（small hands and feet）","(D) 性腺機能不足（hypogonadism）"],"answer":0,"image":""},{"id":"md4-107-1-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"107年第1次第33題","year":107,"session":1,"number":33,"question":"有關透納氏症（Turner syndrome）的敘述，下列何者錯誤？","options":["(A) Ｘ染色體短臂上有SHOX基因，因此病患會有矮小症狀（short stature）","(B) 可能有左心異常（left-heart abnormalities）","(C) 因為是性染色體異常，所以有性腺發育不全（gonadal dysgenesis）","(D) 智力皆不受影響，完全正常"],"answer":3,"image":""},{"id":"md4-107-1-34","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"107年第1次第34題","year":107,"session":1,"number":34,"question":"關於扁平苔癬（lichen planus）敘述，下列何者錯誤？","options":["(A) 偏紫色的扁平丘疹或斑塊","(B) 多無臨床症狀","(C) 病灶常呈多角型","(D) 可以外用類固醇治療"],"answer":1,"image":""},{"id":"md4-107-1-35","subject":"md4","topic":"皮膚-感染","meta":"107年第1次第35題","year":107,"session":1,"number":35,"question":"關於皮膚與軟組織感染skin and soft tissue infections（SSTIs）之敘述，下列何者錯誤？","options":["(A) impetigo與necrotizing fascitis之致病菌可能是Staphylococcus aureus","(B) methicillin-resistant S. aureus（MRSA）在SSTI的盛行率逐漸增加","(C) MRSA在異位性皮膚炎患者形成菌落的機會高於正常人","(D) MRSA引起的皮膚與軟組織感染，多發生在醫療機構工作人員或住院病患，很少發生於一般社區正常人"],"answer":3,"image":""},{"id":"md4-107-1-36","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"107年第1次第36題","year":107,"session":1,"number":36,"question":"40歲男性，在右大腳趾出現如圖所示之表徵，有一年之久，最適切之診斷為：","options":["(A) subungual hematoma","(B) subungual melanoma","(C) subungual pigmented nevus","(D) friction induced melanonychia"],"answer":1,"image":"md4-107-1-36.jpeg"},{"id":"md4-107-1-37","subject":"md4","topic":"兒科-內分泌遺傳","meta":"107年第1次第37題","year":107,"session":1,"number":37,"question":"下列何者與癩皮病（pellagra）無關？","options":["(A) 缺乏維生素B6（pyridoxine）","(B) 缺乏維生素C（ascorbic acid）","(C) 缺乏維生素B3（niacin）","(D) 長期使用isoniazid的病人"],"answer":1,"image":""},{"id":"md4-107-1-38","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"107年第1次第38題","year":107,"session":1,"number":38,"question":"59歲女性，染髮後2天出現搔癢性皮疹如圖所示；過去染髮後也曾有數次類似經驗。最可能的診斷與原因為何？","options":["(A) 刺激性接觸性皮膚炎；因為受到洗髮精中的介面活性劑（surfactant）刺激","(B) 過敏性接觸性皮膚炎；因為對於洗髮精中的介面活性劑（surfactant）過敏","(C) 刺激性接觸性皮膚炎；因為受到染髮劑中的對苯二胺（para-phenylenediamine）刺激","(D) 過敏性接觸性皮膚炎；因為對於染髮劑中的對苯二胺（para-phenylenediamine）過敏"],"answer":3,"image":"md4-107-1-38.jpeg"},{"id":"md4-107-1-39","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"107年第1次第39題","year":107,"session":1,"number":39,"question":"52歲女性，年輕時愛穿高跟鞋，於半年前發現右足掌前側，出現一疼痛角化結節如圖所示，最可能的診斷為何？","options":["(A) 胼胝（callus）","(B) 雞眼（corn）","(C) 蹠病毒疣（plantar wart）","(D) 化生骨贅（exostosis）"],"answer":2,"image":"md4-107-1-39.jpeg"},{"id":"md4-107-1-40","subject":"md4","topic":"皮膚-腫瘤","meta":"107年第1次第40題","year":107,"session":1,"number":40,"question":"有關皮膚黑色素細胞癌（cutaneous melanoma）的敘述，下列何者正確？","options":["(A) 在歐美白種人最常見的亞型是結節型黑色素細胞癌（nodular melanoma）","(B) 肢端黑痣型黑色素細胞癌（acral lentiginous melanoma）不會發生在指甲處","(C) 惡性黑痣型黑色素細胞癌（lentigo maligna melanoma）常見於40歲以下的青壯年人","(D) 表淺擴散型黑色素細胞癌（superficial spreading melanoma）好發於男性的上背和女性的下肢"],"answer":3,"image":""},{"id":"md4-107-1-41","subject":"md4","topic":"皮膚-腫瘤","meta":"107年第1次第41題","year":107,"session":1,"number":41,"question":"80歲男性出現如圖所示病灶，下列何者是最可能的診斷？","options":["(A) 鱗狀細胞癌（Squamous cell carcinoma）","(B) 黑色素細胞癌（Melanoma）","(C) 基底細胞癌（Basal cell carcinoma）","(D) 皮脂腺細胞癌（Sebaceous carcinoma）"],"answer":2,"image":"md4-107-1-41.jpeg"},{"id":"md4-107-1-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"107年第1次第42題","year":107,"session":1,"number":42,"question":"有關天疱瘡（pemphigus）的敘述，下列何者錯誤？","options":["(A) Pemphigus患者常在冬季或因工作壓力大，服用藥物或是病毒感染等等因素惡化","(B) 含有sulfhydryl groups (-S-H)藥物會與角質細胞的cystein結合，改變角質細胞鍵結強度，形成天疱瘡","(C) Thiols類藥物可誘發抗desmoglein 1和抗desmoglein 3抗體, 形成天疱瘡","(D) Drug-induced pemphigus患者的預後與一般pemphigus無異"],"answer":3,"image":""},{"id":"md4-107-1-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"107年第1次第43題","year":107,"session":1,"number":43,"question":"23歲男性，因癲癇服用carbamazepine，經兩周後，全身皮膚黏膜產生大面積水泡及破皮，經皮膚科醫師診斷為毒性表皮溶解症（toxic epidermal necrolysis），此病人的HLA-B基因型，最可能為下列何者？","options":["(A) HLA-B*1502","(B) HLA-B*1301","(C) HLA-B*5802","(D) HLA-B*5801"],"answer":0,"image":""},{"id":"md4-107-1-44","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"107年第1次第44題","year":107,"session":1,"number":44,"question":"關於伍氏燈（Wood's lamp）的臨床使用，下列何者錯誤？","options":["(A) 光源為紫外光，波長範圍屬於UVA","(B) 表皮色素病灶如雀斑，照射伍氏燈呈色會變淡","(C) 伍氏燈觀察下，真皮層色素病灶較不會有反差變化","(D) 伍氏燈觀察下，黑色素細胞缺乏的病灶，反差會加大"],"answer":1,"image":""},{"id":"md4-107-1-45","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"107年第1次第45題","year":107,"session":1,"number":45,"question":"15歲病人，從幼兒時期便開始出現如圖所示之全身脫屑，最可能之診斷為何？","options":["(A) 乾癬（psoriasis）","(B) 體癬（tinea corporis）","(C) 魚鱗癬（ichthyosis）","(D) 水疱性表皮鬆解症（epidermolysis bullosa）"],"answer":2,"image":"md4-107-1-45.jpeg"},{"id":"md4-107-1-46","subject":"md4","topic":"神經-中風","meta":"107年第1次第46題","year":107,"session":1,"number":46,"question":"臺灣最常見的腦中風是那一分類？","options":["(A) 腦梗塞（cerebral infarction）","(B) 腦內出血（intracerebral hemorrhage）","(C) 蜘蛛網膜下出血（subarachnoid hemorrhage）","(D) 缺氧性腦病變（hypoxic encephalopathy）"],"answer":0,"image":""},{"id":"md4-107-1-47","subject":"md4","topic":"神經-中風","meta":"107年第1次第47題","year":107,"session":1,"number":47,"question":"目前偵測早期腦梗塞，最敏銳的影像檢查是：","options":["(A) diffusion-weighted magnetic resonance image","(B) T-weighted magnetic resonance image 2","(C) computed tomography","(D) T1-weighted magnetic resonance image"],"answer":0,"image":""},{"id":"md4-107-1-48","subject":"md4","topic":"神經-中風","meta":"107年第1次第48題","year":107,"session":1,"number":48,"question":"下列何種腦血管疾病最不可能發生於兒童？","options":["(A) 缺血性腦梗塞（ischemic infarction）","(B) 澱粉樣血管病變（amyloid angiopathy）","(C) 先天性心臟病及突發性血栓症（congenital heart disease and paradoxical embolism）","(D) moyamoya disease"],"answer":1,"image":""},{"id":"md4-107-1-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"107年第1次第49題","year":107,"session":1,"number":49,"question":"一位55歲男性，妻子抱怨經常被他半夜睡覺時每隔20到90秒不等的一陣陣腿抖動吵醒，這種腿抖動以腳掌及大拇趾dorsiflexion為主，每次抖動約0.5到5秒，他辯稱自己完全不知道，但自覺睡眠品質差，白天工作時常打瞌睡。關於此一病人之病症，下列敘述何者錯誤？","options":["(A) 最可能診斷為睡眠陣發性肢體動作症（periodic limb movements in sleep）","(B) 腦電圖（EEG）上可發現在腿抖動的對側大腦額葉運動區，伴隨有20到90秒一次之癲癇放電（epileptic discharges）現象","(C) 常伴隨有不寧腿症候群（restless legs syndrome）","(D) dopamine agonist或anticonvulsants對部分病人有效"],"answer":1,"image":""},{"id":"md4-107-1-50","subject":"md4","topic":"神經-中風","meta":"107年第1次第50題","year":107,"session":1,"number":50,"question":"下列何者不屬於頭顱內會引發痛覺的結構？","options":["(A) 顱內的大血管（large intracranial vessels）","(B) 軟腦膜（pia matter）","(C) 硬腦膜（dura matter）","(D) 三叉神經（trigeminal nerve）"],"answer":1,"image":""},{"id":"md4-107-1-51","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"107年第1次第51題","year":107,"session":1,"number":51,"question":"下列關於癲癇症候群（epilepsy syndromes）藥物治療的敘述，何者錯誤？","options":["(A) 青少年肌陣攣癲癇（juvenile myoclonic epilepsy）常對單一抗癲癇藥的反應良好","(B) 青少年失神癲癇（juvenile absence epilepsy）常對單一抗癲癇藥的反應良好","(C) Lennox-Gastaut syndrome常對單一抗癲癇藥的反應良好","(D) 內側顳葉癲癇（medial temporal lobe epilepsy syndrome）常對單一抗癲癇藥的反應不佳"],"answer":2,"image":""},{"id":"md4-107-1-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"107年第1次第52題","year":107,"session":1,"number":52,"question":"當巴金森氏病病人在晚期開始出現運動阻滯（motor block）時，進行下列何種運動比較不受影響？","options":["(A) 上樓梯","(B) 在狹窄的走廊步行","(C) 過馬路","(D) 進出電梯門"],"answer":0,"image":""},{"id":"md4-107-1-53","subject":"md4","topic":"神經-失智退化運動障礙","meta":"107年第1次第53題","year":107,"session":1,"number":53,"question":"75歲的張先生因為記憶力及認路能力日漸惡化，經過神經科專科醫師診斷，得了阿茲海默症（Alzheimer disease），依照臨床嚴重度量表（CDR）的分級為1.0。這幾天，張先生看到太太與送報的人聊上幾句就大發脾氣，也不准張太太接電話，這可能是何種症狀？","options":["(A) delusion of persecution","(B) delusion of stealing（theft）","(C) delusion of jealousy","(D) delusion of not my home"],"answer":2,"image":""},{"id":"md4-107-1-54","subject":"md4","topic":"神經-失智退化運動障礙","meta":"107年第1次第54題","year":107,"session":1,"number":54,"question":"有關變異型庫賈氏病（variant Creutzfeldt-Jakob disease; vCJD）的描述，下列何者正確？","options":["(A) 通常發生此病之平均年齡為65歲","(B) 常合併憂鬱，智能急速減退，及肌躍症","(C) 平均存活時間比散發型庫賈氏病長","(D) 大多數於腦脊髓液中會有14-3-3蛋白，且可測得普利昂（prion）蛋白"],"answer":2,"image":""},{"id":"md4-107-1-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"107年第1次第55題","year":107,"session":1,"number":55,"question":"下列有關糖尿病神經病變之敘述，何者錯誤？","options":["(A) 遠端對稱性以感覺為主的多發性神經病變最為常見","(B) 糖尿病患者之死亡率與大纖維神經病變密切相關","(C) 動眼神經病變為常見的糖尿病性顱神經病變","(D) 第一型糖尿病患者神經病變與高血糖密切相關"],"answer":1,"image":""},{"id":"md4-107-1-56","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"107年第1次第56題","year":107,"session":1,"number":56,"question":"有關腕隧道症候群（carpal tunnel syrdrome）之敘述，下列何者錯誤？","options":["(A) 為最常見之神經壓迫症候群","(B) 於女性懷孕期間容易出現","(C) 尺骨神經減壓手術為其一有效治療方法","(D) 常見原因為過度使用手部或因職業病造成手部創傷"],"answer":2,"image":""},{"id":"md4-107-1-57","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"107年第1次第57題","year":107,"session":1,"number":57,"question":"一位20歲的陳姓大學生，參加露營活動，平日健康狀況良好。在搬一箱20公斤重的飲料，突然覺得腰痛，當天晚上腰痛加劇，且蔓延至右腳也呈現酸麻、無力，隔天他到門診求助。其最可能的診斷為何？","options":["(A) 右脛骨神經（tibial nerve）病變","(B) 右腓骨神經（peroneal nerve）病變","(C) 右股神經（femoral nerve）病變","(D) 右側腰椎神經根病變"],"answer":3,"image":""},{"id":"md4-107-1-58","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"107年第1次第58題","year":107,"session":1,"number":58,"question":"下列何者不是食物引起的肉毒桿菌毒素中毒（food-born botulism）的症狀？","options":["(A) 瞳孔放大（pupil dilatation）","(B) 吞嚥困難（dysphagia）","(C) 構音障礙（dysarthria）","(D) 角弓反張（opisthotonus）"],"answer":3,"image":""},{"id":"md4-107-1-59","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"107年第1次第59題","year":107,"session":1,"number":59,"question":"18歲男學生，因為上課時發生頭痛、意識混亂、雙腿無力及尿失禁被送到急診。在兩星期前，他曾有幾天的上呼吸道感染、發燒，經過治療後，當時症狀已完全緩解。根據病史，最可能的診斷是：","options":["(A) 多發性硬化症（multiple sclerosis）","(B) 急性發炎性脫髓鞘多發性神經病變症候群（Guillain-Barré syndrome）","(C) 病毒性腦膜腦炎（viral meningoencephalitis）","(D) 急性瀰散型腦脊髓炎（acute disseminated encephalomyelitis）"],"answer":3,"image":""},{"id":"md4-107-1-60","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"107年第1次第60題","year":107,"session":1,"number":60,"question":"承上題，所述病症，最廣為採用的第一線治療方式是：","options":["(A) 血漿置換術（plasmapheresis）","(B) 皮質類固醇激素治療（corticosteroid therapy）","(C) 免疫球蛋白治療（immunoglobulin therapy）","(D) 給予藥物acyclovir"],"answer":1,"image":""},{"id":"md4-107-1-61","subject":"md4","topic":"精神-精神病","meta":"107年第1次第61題","year":107,"session":1,"number":61,"question":"一位20歲女性精神科住院病患，濃妝豔抹穿露肩晚禮服，在大廳高歌且手舞足蹈。她自信是最吸引人的巨星，並深信自己是因為表現太過突出，而遭嫉妒陷害被關在這裡。如要診斷該女士為第一型雙極性疾患（bipolar I disorder），下列何者正確？","options":["(A) 必須也有重鬱發作（major depressive episode）","(B) 上述症狀不一定要造成病人的功能損失","(C) 不需考慮藥物之可能影響","(D) 必須排除甲狀腺功能亢進或低下造成的影響"],"answer":3,"image":""},{"id":"md4-107-1-62","subject":"md4","topic":"精神-精神病","meta":"107年第1次第62題","year":107,"session":1,"number":62,"question":"關於輕躁症發作（hypomanic episode）在DSM-IV-TR的診斷準則（criteria）之敘述，下列何者正確？","options":["(A) 睡眠增加","(B) 注意力集中","(C) 比平常多話或不能克制地說個不停","(D) 減少活動，社交退縮"],"answer":2,"image":""},{"id":"md4-107-1-63","subject":"md4","topic":"精神-精神官能症","meta":"107年第1次第63題","year":107,"session":1,"number":63,"question":"下列關於功能性腸胃道疾患（functional gastrointestinal disorders）的敘述何者錯誤？","options":["(A) 許多患有心身症狀者時常以腸胃道症狀表現","(B) 腸胃道疾病當中，有相當高比例為功能性疾患","(C) 對於功能性腸胃道疾患，心理因素時常會影響疾病的嚴重度與預後","(D) 焦慮不太會導致功能性腸胃道疾患"],"answer":3,"image":""},{"id":"md4-107-1-64","subject":"md4","topic":"精神-精神病","meta":"107年第1次第64題","year":107,"session":1,"number":64,"question":"下列何者症狀不屬於思考形式障礙（formal thought disorders）？","options":["(A) 意念飛躍（flight of ideas）","(B) 新語症（neologism）","(C) 思考停頓（thought blocking）","(D) 被害妄想（persecutory delusion）"],"answer":3,"image":""},{"id":"md4-107-1-65","subject":"md4","topic":"精神-精神官能症","meta":"107年第1次第65題","year":107,"session":1,"number":65,"question":"下列關於恐慌症（panic disorder）的治療，何者正確？","options":["(A) 認知行為治療（cognitive behavioral therapy）效果不佳","(B) 苯二氮平類（benzodiazepines）的藥物治療效果好，故在治療第4～12週後可將劑量往上調","(C) 選擇性血清素再吸收抑制劑（SSRI）對恐慌症有不錯的療效","(D) 使用alprazolam治療，其成癮性低"],"answer":2,"image":""},{"id":"md4-107-1-66","subject":"md4","topic":"精神-精神官能症","meta":"107年第1次第66題","year":107,"session":1,"number":66,"question":"「以小人之心度君子之腹」是那種的防衛機轉？","options":["(A) 隔離（isolation）","(B) 否定（denial）","(C) 投射（projection）","(D) 合理化（rationalization）"],"answer":2,"image":""},{"id":"md4-107-1-67","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"107年第1次第67題","year":107,"session":1,"number":67,"question":"賴同學，男性，17歲，就讀高二，因為服藥過量自殺被送到急診室。病史澄清顯示賴同學這次主要因感情問題，女友提分手而出現憂鬱症狀已達二個多月，過去沒有憂鬱或精神科病史。家族史顯示賴同學的爸爸有憂鬱症和酗酒病史，父母離異，自小由母親帶大。關於賴同學這次憂鬱症的病因分析，下列敘述何者正確？","options":["(A) 父母離異是屬於社會性的前置因子（socio-predisposing）","(B) 分手事件是屬於心理性的前置因子（psycho-predisposing）","(C) 家族憂鬱症病史是屬於生物性的誘發因子（bio-precipitating）","(D) 家族憂鬱症病史是屬於社會性的延續因子（socio-perpetuating）"],"answer":0,"image":""},{"id":"md4-107-1-68","subject":"md4","topic":"精神-精神官能症","meta":"107年第1次第68題","year":107,"session":1,"number":68,"question":"呼吸訓練（respiratory training）最適宜用來輔助治療下列何種精神疾患？","options":["(A) 恐慌症（panic disorder）","(B) 強迫症（obsessive-compulsive disorder）","(C) 重鬱症（major depressive disorder）","(D) 身體化症（somatization disorder）"],"answer":0,"image":""},{"id":"md4-107-1-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"107年第1次第69題","year":107,"session":1,"number":69,"question":"酒精戒斷症狀可能因人而異，可分為四大類包含：①知覺障礙（如：幻覺） ②震顫（tremulousness） ③抽搐（seizure） ④譫妄（delirium tremens）；雖未必人人有一樣的發作順序，但若以最典型的發生時序，中斷飲用酒精後，依先後排序為何？","options":["(A) ③①④②","(B) ①③②④","(C) ④②③①","(D) ②①③④"],"answer":3,"image":""},{"id":"md4-107-1-70","subject":"md4","topic":"精神-精神病","meta":"107年第1次第70題","year":107,"session":1,"number":70,"question":"有關「抽象思考」，下列敘述何者錯誤？","options":["(A) 可以詢問「看電影時發生火災，您該怎麼辦？」來加以評估","(B) 可以詢問成語「長江後浪推前浪」的意涵來加以評估","(C) 思覺失調症（schizophrenia）患者可能會有抽象思考障礙","(D) 失智症患者可能會有抽象思考障礙"],"answer":0,"image":""},{"id":"md4-107-1-71","subject":"md4","topic":"精神-器質性與物質使用","meta":"107年第1次第71題","year":107,"session":1,"number":71,"question":"有關ketamine敘述何者正確？","options":["(A) 濫用者多半使用血管注射","(B) Ketamine半衰期很長，作用於γ-aminobutyric acid（GABA）受體","(C) Ketamine可能誘發精神病症狀，其症狀之表現類似思覺失調症（schizophrenia）","(D) Ketamine中毒時呈現高血壓心悸、呼吸抑制而導致死亡"],"answer":2,"image":""},{"id":"md4-107-1-72","subject":"md4","topic":"精神-器質性與物質使用","meta":"107年第1次第72題","year":107,"session":1,"number":72,"question":"一位36歲男性患者被送至急診室就醫，當時血壓182/126 mmHg、心跳每分鐘112次、發燒、流鼻涕、腹痛、瞳孔放大、全身肌肉抽痛。此患者最可能之臨床診斷為何？","options":["(A) 海洛因中毒（heroin intoxication）","(B) K他命中毒（ketamine intoxication）","(C) 安非他命戒斷（amphetamine withdrawal）","(D) 海洛因戒斷（heroin withdrawal）"],"answer":3,"image":""},{"id":"md4-107-1-73","subject":"md4","topic":"精神-器質性與物質使用","meta":"107年第1次第73題","year":107,"session":1,"number":73,"question":"關於譫妄（delirium）的診斷，何者正確？","options":["(A) 主要核心症狀是定向感（orientation）障礙","(B) 自然病程約數天到數週","(C) 與物質濫用有關者，只在物質戒斷（substance withdrawal）時才會發生","(D) 通常都緩慢發生，不容易注意到"],"answer":[0,1],"image":"","answer_note":"更正:第73題答Ａ、Ｂ給分"},{"id":"md4-107-1-74","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"107年第1次第74題","year":107,"session":1,"number":74,"question":"關於說話（speech）和語言（language）使用的正常發展階段，下列何者正確？","options":["(A) 1歲時尚無法以姿勢來溝通表達","(B) 2歲左右只能說5個以內不同的字","(C) 8歲開始能說組織完整的複雜句子","(D) 3歲左右說的話通常家人可清楚了解"],"answer":3,"image":""},{"id":"md4-107-1-75","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"107年第1次第75題","year":107,"session":1,"number":75,"question":"關於自殺企圖（suicide attempt）之相關敘述，下列何者正確？","options":["(A) 自殺企圖者當中，男性較女性為多","(B) 評估自殺企圖患者時，為避免促進患者重複自殺行為，問句應迂迴，不宜直接訊問其目前之自殺意念或相關計劃","(C) 邊緣性人格疾患者（borderline personality disorder）常出現具操縱意味的自殺企圖","(D) 自殺企圖者中，絕大多數沒有精神科相關診斷"],"answer":2,"image":""},{"id":"md4-107-1-76","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第1次第76題","year":107,"session":1,"number":76,"question":"根據所附影像檢查圖，下列何者為最不可能的診斷？","options":["(A) 右肺發育不全（right lung agenesis）","(B) 右肺塌陷","(C) 右胸大量肋膜積水","(D) 右支氣管異物導致完全阻塞"],"answer":2,"image":"md4-107-1-76.jpeg"},{"id":"md4-107-1-77","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"107年第1次第77題","year":107,"session":1,"number":77,"question":"嬰兒建立輸液管道有下列幾種方式，何者最不適用？","options":["(A) 頭皮靜脈（scalp vein）","(B) 骨內注射（intraosseous infusion）","(C) 臍動脈（umbilical artery）","(D) 靜脈切開（venous cutdown）"],"answer":2,"image":""},{"id":"md4-107-1-78","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"107年第1次第78題","year":107,"session":1,"number":78,"question":"一位75歲男性，半小時前突然右側無力，被送至急診室，下列各種狀況之處置何者較不適當？","options":["(A) 立即驗血糖，血糖值為30 mg/dL，給予50％葡萄糖溶液","(B) 血氧濃度為85％，給予氧氣治療","(C) 電腦斷層顯示無腦出血，可考慮使用血栓溶解劑","(D) 測量血壓為190/100 mmHg，給予labetalol 10 mg靜脈注射，以免中風惡化"],"answer":3,"image":""},{"id":"md4-107-1-79","subject":"md4","topic":"醫學倫理與法規","meta":"107年第1次第79題","year":107,"session":1,"number":79,"question":"A君在林教授指導下，花了半年時間寫了一篇有關兒童尿路感染的論文，第一次投稿到某雜誌後被退稿，理由是收集尿液與診斷尿路感染的標準有誤，林教授要A君依據審稿者的指示標準，造假數據改寫論文後投到另一知名雜誌，下列何種做法最好？","options":["(A) 若林教授做通訊作者（負責人），造假的部分就屬他的責任","(B) 這論文還是有其他價值，部分造假無傷大雅","(C) 婉拒造假，A君與林教授試投其他雜誌","(D) 個人退出作者群，將論文交給林教授全權處理"],"answer":2,"image":""},{"id":"md4-107-1-80","subject":"md4","topic":"醫學倫理與法規","meta":"107年第1次第80題","year":107,"session":1,"number":80,"question":"35歲的王太太在懷孕第7個月時，經超音波檢查，發現胎兒是無腦兒，因為無腦兒沒有存活的機會，王家夫妻表明要放棄治療。王太太在第38週時產下一無腦男嬰，出生還有心跳呼吸，下列何者是最佳處置？","options":["(A) 尊重父母意見，不必給予維生治療","(B) 應該轉嬰兒室，給予氧氣與點滴輸液","(C) 抽血驗染色體後才能放棄急救","(D) 立即轉送加護病房使用呼吸器"],"answer":[0,1],"image":"","answer_note":"更正:第80題答Ａ、Ｂ給分。"},{"id":"md4-107-2-1","subject":"md4","topic":"兒科-感染神經","meta":"107年第2次第1題","year":107,"session":2,"number":1,"question":"一名5歲男童就診主訴發高燒3天，喉嚨痛、口水直流，媽媽發現男童手上腳上出現許多紅疹。身體診察發現喉嚨軟顎上出現如滿天星般的水泡，手掌、腳掌、臀部也出現如水泡般的疹子，下列敘述何者錯誤？","options":["(A) 這是腸病毒引起的手足口症的典型表現","(B) 腸病毒的治療主要是支持性療法","(C) 若腸病毒感染併發重症則屬於第三類法定傳染病，須在1週內通報","(D) 腸病毒的病情嚴重時用抗病毒藥物Acyclovir來治療，可改善存活率"],"answer":3,"image":""},{"id":"md4-107-2-2","subject":"md4","topic":"兒科-感染神經","meta":"107年第2次第2題","year":107,"session":2,"number":2,"question":"9個月大的男嬰高燒5天，今天早上開始呈現嗜睡狀態，晚上因全身僵直陣攣性發作（Generalized tonic clonic seizure）5分鐘被送來急診。在加護病房做了脊髓穿刺檢查，腦脊髓液報告顯示WBC 10000/µL（90% PMNs和10% Lymphocyte），Protein 380 mg/dL，Glucose 5 mg/dL。下列何者為最可能的致病原？","options":["(A) 單純疱疹病毒第一型（HSV type 1）","(B) 肺炎鏈球菌（Streptococcus pneumoniae）","(C) 腸病毒（Enterovirus）","(D) 新型隱球菌（Cryptococcus neoformans）"],"answer":1,"image":""},{"id":"md4-107-2-3","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"107年第2次第3題","year":107,"session":2,"number":3,"question":"1歲半兒童被帶來門診想接受疫苗注射，在他11個月大時，曾因病接受免疫球蛋白（IVIG）的治療。下列何種疫苗之補接種較為適合？","options":["(A) 麻疹－德國麻疹－腮腺炎疫苗","(B) 水痘疫苗","(C) A型肝炎疫苗","(D) 活性日本腦炎疫苗"],"answer":2,"image":""},{"id":"md4-107-2-4","subject":"md4","topic":"兒科-感染神經","meta":"107年第2次第4題","year":107,"session":2,"number":4,"question":"10個月大的男嬰發燒和皮疹已2天。過去健康狀況良好，家人沒有生病。此男嬰精神好，身體診察發現口腔黏膜有潰瘍，頭皮、臉部、耳朵和軀幹有水泡，部分水泡中央凹陷呈肚臍狀。最可能的診斷是：","options":["(A) 手足口症（Hand-foot-and-mouth disease）","(B) 猩紅熱（Scarlet fever）","(C) 水痘（Varicella）","(D) 麻疹（Measles）"],"answer":2,"image":""},{"id":"md4-107-2-5","subject":"md4","topic":"兒科-感染神經","meta":"107年第2次第5題","year":107,"session":2,"number":5,"question":"5歲男孩2天前開始出現發燒、頭痛和喉嚨痛。發燒1天後頸部出現皮疹，接著散佈到軀幹和四肢。其紅色小丘疹感覺像砂紙一樣。病童口腔沒有潰瘍，舌頭呈草莓樣。此病最可能的致病原是：","options":["(A) 第6型人類疱疹病毒","(B) 微小病毒B19型","(C) 金黃色葡萄球菌","(D) A型鏈球菌"],"answer":3,"image":""},{"id":"md4-107-2-6","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第2次第6題","year":107,"session":2,"number":6,"question":"9個月大的女嬰，發燒咳嗽2天，出現聲音沙啞、咳嗽聲音異常、呼吸費力，來急診就醫，醫師發現有明顯的喘鳴音（Stridor），下列何種處置最不合適？","options":["(A) 給與氧氣吸入治療","(B) 給與吸入性腎上腺素治療","(C) 給與類固醇治療","(D) 給與抗生素注射治療"],"answer":3,"image":""},{"id":"md4-107-2-7","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"107年第2次第7題","year":107,"session":2,"number":7,"question":"下列何者不是足月新生兒會有的正常姿勢？","options":["(A) 平躺時四肢呈屈曲姿勢","(B) 俯臥時骨盆會平貼床面","(C) 驚嚇時雙手先向外伸張，再作擁抱狀","(D) 頭轉向一側，同側手腳呈現伸張姿勢"],"answer":1,"image":""},{"id":"md4-107-2-8","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"107年第2次第8題","year":107,"session":2,"number":8,"question":"一個40週出生2,000公克的新生兒，在出生後第2小時出現呼吸喘快、有肋骨下凹陷、全身發紅但嘴唇為紫紅色的現象，體溫脈博正常，檢測血糖值為30 mg/dL。接下來應做何種檢驗最為重要？","options":["(A) C反應蛋白（CRP）","(B) 血球血比容（Hematocrit）","(C) 心臟超音波（Heart ultrasound）","(D) 血液鈉離子濃度（Serum sodium concentration）"],"answer":1,"image":""},{"id":"md4-107-2-9","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"107年第2次第9題","year":107,"session":2,"number":9,"question":"一個新生兒以真空吸引器輔助娩出後，頭顳葉與枕部發現一腫塊，它摸起來像水袋樣有波動，而且跨越骨縫。身體診察發現前囟門無突出，血壓40/25 mmHg、心跳每分鐘190次，無神經學異常，下列何者為最可能之診斷？","options":["(A) 帽狀腱膜下血腫（Subgaleal hemorrhage）","(B) 硬膜上出血（Epidural hemorrhage）","(C) 胎頭血腫（Cephalohematoma）","(D) 胎頭產瘤（Caput succedaneum）"],"answer":0,"image":""},{"id":"md4-107-2-10","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"107年第2次第10題","year":107,"session":2,"number":10,"question":"一個足月嬰兒出生後哭聲洪亮、四肢活動力好、全身膚色紅潤、心跳大約140/分、呼吸40/分，抽吸刺激時會有打噴嚏反應，他的Apgar Score為幾分？","options":["(A) 4","(B) 6","(C) 8","(D) 10"],"answer":3,"image":""},{"id":"md4-107-2-11","subject":"md4","topic":"兒科-消化系統疾病","meta":"107年第2次第11題","year":107,"session":2,"number":11,"question":"下列物質的主要吸收位置，何者不是在十二指腸和近端空腸？","options":["(A) 鈣（Calcium）","(B) 鐵（Iron）","(C) 葉酸（Folic acid）","(D) 膽汁酸（Bile acid）"],"answer":3,"image":""},{"id":"md4-107-2-12","subject":"md4","topic":"兒科-消化系統疾病","meta":"107年第2次第12題","year":107,"session":2,"number":12,"question":"除初乳之外，下列關於母乳（Breast milk）與嬰兒配方（Infant formula）的描述和比較何者最為正確？","options":["(A) 母乳所含的蛋白質濃度較低，嬰兒配方所含的蛋白質濃度較高","(B) 母乳所含的脂肪濃度較低，嬰兒配方所含的脂肪濃度較高","(C) 母乳中不含維生素A，嬰兒配方則含有維生素A","(D) 母乳中不含維生素D，嬰兒配方則含有維生素D"],"answer":0,"image":""},{"id":"md4-107-2-13","subject":"md4","topic":"兒科-消化系統疾病","meta":"107年第2次第13題","year":107,"session":2,"number":13,"question":"關於胃食道逆流（Gastroesophageal reflux）與肥厚性幽門狹窄（Hypertrophic pyloric stenosis）之比較，下列何者正確？","options":["(A) 胃食道逆流沒有男女性別比的差異，肥厚性幽門狹窄則是女生比男生多","(B) 胃食道逆流的嬰兒大多會嚴重影響體重增加，肥厚性幽門狹窄未治療大多會嚴重嘔吐甚至脫水","(C) 胃食道逆流嬰兒的嘔吐物多不含膽汁，肥厚性幽門狹窄嬰兒的嘔吐物多含有膽汁","(D) 胃食道逆流的嬰兒大多隨年齡增長而自行改善，肥厚性幽門狹窄嬰兒確診後需要手術或藥物治療"],"answer":3,"image":""},{"id":"md4-107-2-14","subject":"md4","topic":"兒科-消化系統疾病","meta":"107年第2次第14題","year":107,"session":2,"number":14,"question":"關於兒童腸套疊（Intussusception）的表現，下列何者最為典型？","options":["(A) 通常在1至2歲腸套疊的病童，大都可問到在發病前有受到病毒感染，以致於淋巴增生產生引導點（Leading point）","(B) 病童多為急性持續性腹痛，中間不停歇，膝蓋彎曲朝向腹部，臉色蒼白表情痛苦","(C) 除了腹痛嘔吐和草莓醬樣大便（Currant jelly stool）之外，在病童右上腹可能會摸到硬塊，且在腹痛病程之間可能會有嗜睡的現象","(D) 以顯影劑或生理食鹽水或空氣從肛門端導入大腸回灌將腸套疊灌通後，復發的機率為20%以上"],"answer":2,"image":""},{"id":"md4-107-2-15","subject":"md4","topic":"兒科-消化系統疾病","meta":"107年第2次第15題","year":107,"session":2,"number":15,"question":"1個月大的嬰兒到健兒門診接受預防注射，目前全母乳哺餵，身體診察時發現眼白泛黃，胸腹部皮膚呈現黃褐色，詢問大便顏色屬「嬰兒大便辨識卡」5號。下列處置何者最不適當？","options":["(A) 建議停止哺餵母乳，2天後再追蹤黃疸是否下降","(B) 檢驗血中直接及總膽紅素值","(C) 安排腹部超音波","(D) 檢驗γGT（γ-glutamyl transpeptidase）"],"answer":0,"image":""},{"id":"md4-107-2-16","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"107年第2次第16題","year":107,"session":2,"number":16,"question":"女童突發四肢無力至急診。血壓100/60 mmHg，血液檢查發現：肌酸酐0.6 mg/dL，鈉離子濃度136 mmol/L，鉀離子濃度2.2 mmol/L，滲透壓293 mOsmol/kgH2O。尿液檢查發現：肌酸酐98.5 mg/dL，鈉離子濃度30 mmol/L，鉀離子濃度37 mmol/L，滲透壓370 mOsmol/kgH2O，女童Trans-tubular potassium gradient（TTKG）數值為何？","options":["(A) 0.075","(B) 13.3","(C) 9.76","(D) 0.1024"],"answer":1,"image":""},{"id":"md4-107-2-17","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"107年第2次第17題","year":107,"session":2,"number":17,"question":"臨床上最廣泛使用來估算兒童腎絲球過濾率（Estimated GFR）的公式或指標為何？","options":["(A) Modification of Diet in Renal Disease（MDRD）公式","(B) Schwartz formula","(C) Cockcroft-Gault equations","(D) 血中肌酸酐濃度（Creatinine）"],"answer":1,"image":""},{"id":"md4-107-2-18","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"107年第2次第18題","year":107,"session":2,"number":18,"question":"關於嬰兒搖晃症（Shaken baby syndrome）之成因，下列何者較正確？","options":["(A) 多因坐在嬰兒搖椅造成","(B) 多因照顧者搖抱哄睡造成","(C) 多因照顧者惡意搖晃造成","(D) 多因照顧者與嬰兒玩耍造成"],"answer":2,"image":""},{"id":"md4-107-2-19","subject":"md4","topic":"兒科-內分泌遺傳","meta":"107年第2次第19題","year":107,"session":2,"number":19,"question":"15天大女嬰實驗數值顯示Free T4 0.32 ng/dL（正常值：0.8～2 ng/dL）、T4 2.2 µg/dL（正常值：4.5～12.5 µg/dL）、TSH 102 mIU/L（正常值：1.0～15.0 mIU/L），下列敘述何者最正確？","options":["(A) 為甲狀腺功能亢進之個案","(B) 這類疾病多為自體隱性遺傳導致","(C) 可能與先天性甲狀腺發育不良有關","(D) 身體診察可發現女嬰前囟門已癒合"],"answer":2,"image":""},{"id":"md4-107-2-20","subject":"md4","topic":"兒科-內分泌遺傳","meta":"107年第2次第20題","year":107,"session":2,"number":20,"question":"16歲男學生身體診察顯示ޮ側睪丸均為2～3毫升，性釋素ജ激試驗顯示睪固酮（Testosterone）＜1.0 ng/mL，ߵ泡促素（FSH）之最高值為89.7 IU/L，黃體促素（LH）之最高值為68.6 IU/L。下列何者最符合病人診斷？","options":["(A) 柯林菲特氏症（Klinefelter syndrome）","(B) 卡門氏症（Kallmann syndrome）","(C) 普瑞德威利氏症（Prader-Willi syndrome）","(D) 先天性腦垂體低能症（Congenital hypopituitarism）"],"answer":0,"image":""},{"id":"md4-107-2-21","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第2次第21題","year":107,"session":2,"number":21,"question":"有關川崎氏症（Kawasaki disease）的治療考量，下列何者最為正確？","options":["(A) 以免疫球蛋白（IVIG）2 g/kg為主要之治療","(B) 使用高劑量Aspirin（80～100 mg/kg/day）是為了抗凝血作用","(C) 使用低劑量Aspirin（3～5 mg/kg/day）是為了抗發炎作用","(D) 高燒時需用第三線抗生素以預防感染"],"answer":0,"image":""},{"id":"md4-107-2-22","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第2次第22題","year":107,"session":2,"number":22,"question":"1歲半的幼兒，昨晚發燒、咳嗽，今天到急診。醫師發現呼吸聲音變得明顯，聽診雙側有喘息音（Wheezing），給與短效型支氣管擴張劑（Bronchodilator）後，喘息音沒有改變，下列何種診斷最有可能？","options":["(A) 上呼吸道感染（Upper respiratory tract infection）","(B) 細支氣管炎（Bronchiolitis）","(C) 氣喘（Asthma）","(D) 氣道異物阻塞（Airway foreign body obstruction）"],"answer":1,"image":""},{"id":"md4-107-2-23","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"107年第2次第23題","year":107,"session":2,"number":23,"question":"有關預防嬰幼兒過敏的觀念，下列敘述何者最不恰當？","options":["(A) 孕婦飲食不需避免高過敏食物（例如海鮮、花生等）","(B) 應延遲添加嬰幼兒副食品至6個月大之後","(C) 母乳哺育對於預防氣喘的效果不確定","(D) 目前國際指引尚未建議嬰幼兒常規性使用益生菌來預防過敏"],"answer":1,"image":""},{"id":"md4-107-2-24","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"107年第2次第24題","year":107,"session":2,"number":24,"question":"兒童嚴重型再生不良性貧血的治療選項中，下列何種治療方式之治癒率較高？","options":["(A) 放射治療","(B) 化療","(C) 輸血","(D) 血液幹細胞移植"],"answer":3,"image":""},{"id":"md4-107-2-25","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第2次第25題","year":107,"session":2,"number":25,"question":"一個7天大的新生兒有發紺現象，身體診察聽到分裂的第一心音與第二心音，左側胸骨線出現第三度收縮期的心雜音。胸部X光顯示心臟有擴大情形，心電圖顯示心軸右偏與右心房擴大。此新生兒的診斷較可能是：","options":["(A) 主動脈窄縮（Coarctation of aorta）","(B) 左心發育不全症候群（Hypoplastic left heart syndrome）","(C) 法洛氏四重症（Tetralogy of Fallot）","(D) 艾伯斯坦異常（Ebstein anomaly）"],"answer":3,"image":""},{"id":"md4-107-2-26","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第2次第26題","year":107,"session":2,"number":26,"question":"下列何者不是胎兒循環轉換為新生兒循環會發生的生理過程？","options":["(A) 動脈導管變成由左至右分流","(B) 靜脈導管關閉","(C) 卵圓孔變成由右至左分流","(D) 臍動脈萎縮關閉"],"answer":2,"image":""},{"id":"md4-107-2-27","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第2次第27題","year":107,"session":2,"number":27,"question":"單一心室合併肺動脈狹窄（Single ventricle with pulmonary stenosis）之8個月大病童，在病房發現其活力不佳，且有嚴重發紺現象。身體診察發現心跳速率每分鐘40下，血氧濃度40%。下列何種處置不恰當？","options":["(A) 將病患維持Knee-chest position，並給與氧氣","(B) 如有嚴重酸中毒，給與Bicarbonate治療","(C) 給與Epinephrine急救治療","(D) 會診小兒心臟外科醫師評估手術治療介入時機"],"answer":2,"image":""},{"id":"md4-107-2-28","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第2次第28題","year":107,"session":2,"number":28,"question":"典型的法洛氏四重症（Tetralogy of Fallot）患者在手術矯正前，胸前聽診時可以聽到一個明顯的收縮期心雜音（Systolic murmur），此雜音的成因為何？","options":["(A) 主動脈跨位（Overriding aorta）造成經過主動脈的血流過多","(B) 大型的心室中膈缺損（Ventricular septal defect）造成肺部血流過多","(C) 主動脈分出的側枝循環（Collateral circulation）過於旺盛","(D) 右心室出口狹窄（Right ventricular outflow tract obstruction）造成血流加速"],"answer":3,"image":""},{"id":"md4-107-2-29","subject":"md4","topic":"兒科-內分泌遺傳","meta":"107年第2次第29題","year":107,"session":2,"number":29,"question":"關於染色體核型（Karyotyping），下列敘述何者錯誤？","options":["(A) 正常男性染色體核型為46,XY","(B) 47,XXY即為Klinefelter syndrome","(C) 45,X為女性表徵，病人容易有Premature ovarian failure","(D) 46,XY,del(5)(p12)指的是第五號染色體的長臂發生了Deletion"],"answer":3,"image":""},{"id":"md4-107-2-30","subject":"md4","topic":"兒科-內分泌遺傳","meta":"107年第2次第30題","year":107,"session":2,"number":30,"question":"12歲男孩，身高185公分，四肢極為細長。經眼科檢查發現雙側Lens subluxation，下列何種檢查對診斷最無幫助？","options":["(A) Plasma amino acid level","(B) Serum homocysteine level","(C) Mutation analysis of Marfan Syndrome","(D) Muscle biopsy"],"answer":3,"image":""},{"id":"md4-107-2-31","subject":"md4","topic":"兒科-內分泌遺傳","meta":"107年第2次第31題","year":107,"session":2,"number":31,"question":"病人發生代謝性酸血症（Metabolic acidosis）合併下列何種臨床情境，則可能為Inborn errors of metabolism的機率最高？","options":["(A) 3週大新生兒，一直嘔吐、無法進食、活力差。血液Anion gap與Lactic acid增加；尿液Ketones 4+","(B) 10個月大男嬰持續腹瀉3天。血液呈現氯高而Anion gap正常","(C) 3歲大男童高燒5天且食慾差。血液白血球增高","(D) 8歲女童多吃、多喝、多尿但體重下降。血糖410 mg/dL，血液呈現Anion gap增加"],"answer":0,"image":""},{"id":"md4-107-2-32","subject":"md4","topic":"兒科-內分泌遺傳","meta":"107年第2次第32題","year":107,"session":2,"number":32,"question":"4歲男童因有自閉行為（Autistic behavior）而就診，出生時的基本新生兒篩檢及常規染色體檢查並無異常。身體診察顯示頭圍正常、臉型稍長、耳朵大、睪丸體積亦較同年紀男生大。其30歲的媽媽亦因遲遲未能再懷孕，經檢查發現有早發性卵巢衰竭。此男童最有可能患有下列何種疾病？","options":["(A) Asperger syndrome","(B) Fragile X syndrome","(C) Klinefelter syndrome","(D) Tourette syndrome"],"answer":1,"image":""},{"id":"md4-107-2-33","subject":"md4","topic":"醫學倫理與法規","meta":"107年第2次第33題","year":107,"session":2,"number":33,"question":"下列何種情形可不需立刻通報兒少保護小組？","options":["(A) 4歲男童無法行走，3日後檢查發現右股骨骨折，已是今年第3次外傷就醫","(B) 2個月女嬰頭皮血腫合併硬腦膜下出血","(C) 4歲男童攀爬遊戲器材時跌落，手腳多處挫傷擦傷","(D) 4歲女童據家屬描述走路跌倒後便無法行走，現就醫發現左股骨骨折"],"answer":2,"image":""},{"id":"md4-107-2-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"107年第2次第34題","year":107,"session":2,"number":34,"question":"下列何者是濕疹（eczema），在病理下通常不會出現的特徵？","options":["(A) 表皮層出現海綿狀病變（spongiosis）","(B) 真皮層血管周圍出現淋巴球和嗜伊紅性球","(C) 表皮下出現水疱（subepidermal vesicle）","(D) 表皮層出現不規則的棘狀增生變化（irregular acanthosis）"],"answer":2,"image":""},{"id":"md4-107-2-35","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"107年第2次第35題","year":107,"session":2,"number":35,"question":"19歲女性，因為腳扭傷而貼敷酸痛藥布，兩天後，出現如圖所示會癢之皮膚病變，下列何種檢查最有助於診斷？","options":["(A) KOH鏡檢（KOH examination）","(B) 貼膚試驗（patch test）","(C) 針刺試驗（prick test）","(D) Tzanck抹片檢查（Tzanck test）"],"answer":1,"image":"md4-107-2-35.jpeg"},{"id":"md4-107-2-36","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"107年第2次第36題","year":107,"session":2,"number":36,"question":"有關太田母斑（nevus of Ota）的敘述，下列何者錯誤？","options":["(A) 好發於臉上三叉神經第三分支部位","(B) 可伴隨同側之眼鞏膜黑藍色斑","(C) 通常是單側病變","(D) 好發於東方女性"],"answer":0,"image":""},{"id":"md4-107-2-37","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"107年第2次第37題","year":107,"session":2,"number":37,"question":"關於鋅缺乏（zinc deficiency）引起的皮膚疾病的敘述，下列何者錯誤？","options":["(A) 可為先天性或後天性原因造成鋅缺乏","(B) 病人在眼睛、口唇及肛門周圍可見急性濕疹樣皮膚病變","(C) 病徵以皮疹表現為主，通常不會有掉髮、腹瀉和昏睡等症狀","(D) 血液中鋅和alkaline phosphatase的濃度有助於確診"],"answer":2,"image":""},{"id":"md4-107-2-38","subject":"md4","topic":"皮膚-感染","meta":"107年第2次第38題","year":107,"session":2,"number":38,"question":"20歲女性於六週前，發現前臂出現一微癢紅色斑塊，自行使用藥膏，但皮疹逐漸擴大如圖所示，下列敘述何者錯誤？","options":["(A) 應該使用伍氏燈（Wood's lamp）檢查，若沒有螢光反應，則可以排除體癬的診斷","(B) 應詢問是否有養寵物","(C) 應進行KOH鏡檢","(D) 若皮疹合併有搔抓之小潰瘍，亦要小心是否合併繼發性細菌感染"],"answer":0,"image":"md4-107-2-38.jpeg"},{"id":"md4-107-2-39","subject":"md4","topic":"皮膚-感染","meta":"107年第2次第39題","year":107,"session":2,"number":39,"question":"關於梅毒的敘述，下列何者正確？","options":["(A) 梅毒螺旋體（Treponema pallidum）可以利用鏡檢與其他nonvenereal diseases的treponemes做鑑別診斷","(B) 二期梅毒皮疹經治療後，皮疹通常在4~12週後消褪","(C) 二期梅毒皮疹典型發生在chancre出現的3~12週後，但在HIV病患出現的時間可能與chancre有所重疊","(D) 血液專一性treponemal test是監測梅毒治療效果的最佳指標"],"answer":[1,2],"image":"","answer_note":"更正:第39題答Ｂ、Ｃ給分"},{"id":"md4-107-2-40","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"107年第2次第40題","year":107,"session":2,"number":40,"question":"35歲女性主述於2年前，手部遇冷會出現指端變紫黑色的情形，另外也抱怨顏面紅斑及多發性關節痛。最近1年，工作時容易疲勞，實驗室檢查Anti-U1 RNP抗體為1:1280。最可能的診斷為：","options":["(A) 全身性硬化症（systemic sclerosis）","(B) 系統性紅斑狼瘡（systemic lupus erythematosus）","(C) 皮膚肌炎（dermatomyositis）","(D) 混合性結締組織病（mixed connective tissue disease）"],"answer":3,"image":""},{"id":"md4-107-2-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"107年第2次第41題","year":107,"session":2,"number":41,"question":"Sjogren's syndrome常見的皮膚病變，下列何者錯誤？","options":["(A) cutaneous vasculitis","(B) acquired ichthyosis","(C) Raynaud phenomenon","(D) erythema multiforme"],"answer":1,"image":""},{"id":"md4-107-2-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"107年第2次第42題","year":107,"session":2,"number":42,"question":"曾接受腹部手術後的病人，因腸胃不適，常長期局部熱敷減輕症狀，皮膚出現如圖所示的色素沉著，下列敘述何者正確？","options":["(A) 因為紫外線所引起之黑色素細胞增生","(B) 因為患部燙傷起水疱後發炎所留下","(C) 患部皮膚可併發皮膚鱗狀上皮細胞癌","(D) 繼續局部熱敷可促進色素消散"],"answer":2,"image":"md4-107-2-42.jpeg"},{"id":"md4-107-2-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"107年第2次第43題","year":107,"session":2,"number":43,"question":"下列何者為皮膚角質層主要的脂質成分，且缺少時，與異位性皮膚炎的發生有關？","options":["(A) cholesterol","(B) ceramide","(C) free fatty acid","(D) triglyceride"],"answer":1,"image":""},{"id":"md4-107-2-44","subject":"md4","topic":"皮膚-腫瘤","meta":"107年第2次第44題","year":107,"session":2,"number":44,"question":"6歲男孩，在嬰兒時右側頭皮出現一肉色隆起之斑塊如圖所示，隨著時間緩慢變大，最有可能的診斷為何？","options":["(A) seborrheic keratosis","(B) sebaceous hyperplasia","(C) nevus sebaceous","(D) verruca"],"answer":2,"image":"md4-107-2-44.jpeg"},{"id":"md4-107-2-45","subject":"md4","topic":"皮膚-腫瘤","meta":"107年第2次第45題","year":107,"session":2,"number":45,"question":"承上題，關於此腫瘤之敘述，下列何者錯誤？","options":["(A) 若其顏色及形狀無不規則的變化，只是緩慢變大，可先觀察不需馬上切除","(B) 此腫瘤雖然是良性的，但之後仍可能在其上產生基底細胞癌或其他皮膚癌","(C) 成年後病灶會自然消失","(D) 除了手術切除以外，二氧化碳雷射也是一種治療的選擇"],"answer":2,"image":""},{"id":"md4-107-2-46","subject":"md4","topic":"神經-中風","meta":"107年第2次第46題","year":107,"session":2,"number":46,"question":"當發生腦血管阻塞後，腦細胞會發生缺血連鎖反應（ischemic cascade）；下列反應順序何者為最正確？① 細胞去極化（depolarization） ②鈉鉀離子能量系統瓦解（sodium/potassium ATP pump failure） ③細胞內的鈣離子增加，活化細胞內酵素，溶解胞器（apoptosis） ④釋放興奮性神經傳遞物質，如麩胺酸（glutamate）","options":["(A) ②→①→④→③","(B) ①→②→③→④","(C) ①→③→④→②","(D) ②→③→①→④"],"answer":0,"image":""},{"id":"md4-107-2-47","subject":"md4","topic":"神經-中風","meta":"107年第2次第47題","year":107,"session":2,"number":47,"question":"因長期高血壓造成的腦出血，以下何者為最常見的部位？","options":["(A) 殼核（putamen）","(B) 額葉（frontal lobe）","(C) 橋腦（pons）","(D) 小腦（cerebellum）"],"answer":0,"image":""},{"id":"md4-107-2-48","subject":"md4","topic":"神經-中風","meta":"107年第2次第48題","year":107,"session":2,"number":48,"question":"造成腦靜脈竇栓塞（cerebral venous sinus thrombosis）的原因，下列何者可能性最低？","options":["(A) 血小板低下（thrombocythemia）","(B) 高血壓","(C) 惡性腫瘤","(D) 服用口服避孕藥"],"answer":[0,1],"image":"","answer_note":"更正:第48題答Ａ、Ｂ給分。"},{"id":"md4-107-2-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"107年第2次第49題","year":107,"session":2,"number":49,"question":"下列有關健康成人正常睡眠的結構，何者正確？","options":["(A) 每個睡眠週期約60分鐘","(B) 非動眼睡眠第三期約占睡眠50%的時間","(C) 入睡通常小於5分鐘","(D) 每晚經歷3～5個睡眠週期"],"answer":3,"image":""},{"id":"md4-107-2-50","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"107年第2次第50題","year":107,"session":2,"number":50,"question":"關於重積癲癇（status epilepticus）治療，下列何者錯誤？","options":["(A) 癲癇發作時應立即給與抗癲癇藥物如phenytoin，並避免給予苯二氮類藥物（benzodiazepines）如lorazepam","(B) 抗癲癇藥物應使用靜脈注射類而不是口服類","(C) 若使用抗癲癇藥物後仍持續發作，進入頑固性重積癲癇（refractory status epilepticus），應再加上麻醉類藥物如propofol","(D) 腦波監控是必要檢查"],"answer":0,"image":""},{"id":"md4-107-2-51","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"107年第2次第51題","year":107,"session":2,"number":51,"question":"下列有關額葉癲癇（frontal lobe epilepsy）的描述何者錯誤？","options":["(A) 癲癇發作（seizure）短暫，可能不會有癲癇發作後混亂（postictal confusion）","(B) 腦波圖（scalp EEG）可能看不出明顯異常","(C) 癲癇發作傾向在晚上睡眠中","(D) phenytoin為治療首選藥物"],"answer":3,"image":""},{"id":"md4-107-2-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"107年第2次第52題","year":107,"session":2,"number":52,"question":"一位20歲男性突然發生頸部僵硬的症狀，持續維持在奇怪的姿勢而很難轉動。此患者並無外傷，最近因為胃食道逆流服用metoclopramide藥物治療。此時最好的治療方式是給與下列那一種藥物？","options":["(A) phenytoin","(B) botulinum toxin","(C) benztropine mesylate","(D) haloperidol"],"answer":2,"image":""},{"id":"md4-107-2-53","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"107年第2次第53題","year":107,"session":2,"number":53,"question":"46歲女性，近2、3週覺得疲倦、無力、有輕微發燒，必須用雙手支撐才能從椅子站起，右手也無法舉高去梳頭髮。上眼瞼及手指關節背面出現紫紅色脫屑斑。根據病史及臨床症狀，下列何者與此疾病最不相關？","options":["(A) 自體免疫性疾病（autoimmune disease）","(B) 以侵犯神經（nerve）及皮膚（skin）為主","(C) 合併有惡性腫瘤","(D) 出現四肢對稱性的近端肌肉無力"],"answer":1,"image":""},{"id":"md4-107-2-54","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"107年第2次第54題","year":107,"session":2,"number":54,"question":"52歲男性，主訴反覆出現之左臉陣發性劇烈疼痛一年多，在發作數週或數月後，可自行緩解數月。疼痛部位大多在左臉中下部分，無感覺缺失。其最可能診斷為下列何者？","options":["(A) 中腦（midbrain）中風","(B) 三叉神經痛（trigeminal neuralgia）","(C) 舌咽神經痛（glossopharyngeal neuralgia）","(D) 癲癇發作（seizures）"],"answer":1,"image":""},{"id":"md4-107-2-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"107年第2次第55題","year":107,"session":2,"number":55,"question":"65歲女性素食者來門診，主訴漸進性步態不穩6個月，血液檢查發現維生素B12（Vitamin B12）偏低，神經學檢查發現膝反射和踝反射增強，陽性巴賓斯基氏徵象（positive Babinski sign），下肢振動覺和位置覺受損，神經傳導檢查出現周圍神經病變，其診斷最可能為何？","options":["(A) 前額葉腦中風","(B) 中腦中風","(C) 梅毒脊髓症","(D) 亞急性聯合變性（subacute combined degeneration）"],"answer":3,"image":""},{"id":"md4-107-2-56","subject":"md4","topic":"神經-失智退化運動障礙","meta":"107年第2次第56題","year":107,"session":2,"number":56,"question":"下列有關脊髓小腦共濟失調症（spinocerebellar ataxia）的敘述，何者正確？","options":["(A) 有些是體染色體顯性遺傳、有些是隱性遺傳、有些則是偶發性的","(B) 造成脊髓小腦共濟失調症（spinocerebellar ataxia）的基因突變只有三核甘酸重複（trinucleotide repeat）延長的型態","(C) 三核甘酸重複（trinucleotide repeat）延長的位置只出現在編碼位置（coding region）","(D) 巴金森氏症候群主要是因為丘腦的異常而導致，不會有小腦共濟失調的現象"],"answer":0,"image":""},{"id":"md4-107-2-57","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"107年第2次第57題","year":107,"session":2,"number":57,"question":"下列有關多發性硬化症（multiple sclerosis）的敘述，何者正確？","options":["(A) 典型的多發性硬化症發生於20～40歲的年輕人，而且男性明顯多於女性","(B) 常見的症狀包括脊髓脫髓鞘病變、兩側聽神經麻痺及大面積類中風症狀","(C) 多發性硬化症的患者時常在背部有類似電流流過的現象，這種現象常因向後伸展頸椎而得到舒緩，這種表徵稱為Lhermitte表徵","(D) 某些多發性硬化症的患者在體溫升高的情形下會引發或加重其發作，這種現象稱為Uhthoff現象"],"answer":3,"image":""},{"id":"md4-107-2-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"107年第2次第58題","year":107,"session":2,"number":58,"question":"下列何者的異常值高低和粒線體疾病的病況嚴重程度最相關？","options":["(A) 血中乳酸量的高低","(B) 血中乳酸去氫酶（lactic dehydrogenase, LDH）的活性","(C) 脊髓液中的蛋白質含量","(D) 脊髓液中免疫球蛋白G的指數（IgG index）"],"answer":0,"image":""},{"id":"md4-107-2-59","subject":"md4","topic":"神經-失智退化運動障礙","meta":"107年第2次第59題","year":107,"session":2,"number":59,"question":"72歲男性，出現波動性的認知障礙及注意力不集中（fluctuating cognitive and attention disturbances），並且有視幻覺（visual hallucination）。這半年來，除了上述病症加劇外，病人出現記憶力衰退，肢體僵硬，步態緩慢，並容易跌倒。其最可能的診斷為何？","options":["(A) 阿茲海默症（Alzheimer disease）","(B) 路易氏體失智症（dementia with Lewy bodies）","(C) 巴金森氏失智症（Parkinson disease dementia）","(D) 進行性核上麻痺（progressive supranuclear palsy）"],"answer":1,"image":""},{"id":"md4-107-2-60","subject":"md4","topic":"神經-失智退化運動障礙","meta":"107年第2次第60題","year":107,"session":2,"number":60,"question":"承上題，所述病症，最可能是下列何種蛋白不正常堆積？","options":["(A) tau蛋白（tau protein）","(B) β-類澱粉蛋白（β-amyloid protein）","(C) α-突觸核蛋白（α-synuclein protein）","(D) 普里昂蛋白（prion protein）"],"answer":2,"image":""},{"id":"md4-107-2-61","subject":"md4","topic":"精神-器質性與物質使用","meta":"107年第2次第61題","year":107,"session":2,"number":61,"question":"有關甲狀腺亢進與精神疾病的關聯性，下列何者正確？","options":["(A) 甲狀腺亢進可能引發情緒激躁、意念飛躍等躁症症狀，但不致於引起憂鬱情緒","(B) 甲狀腺亢進不致於出現幻覺或被害意念之精神病症狀","(C) 甲狀腺亢進與甲狀腺低下均可能引起認知障礙","(D) 甲狀腺亢進會引起心跳加速，但不列入恐慌症之鑑別診斷"],"answer":2,"image":""},{"id":"md4-107-2-62","subject":"md4","topic":"精神-精神病","meta":"107年第2次第62題","year":107,"session":2,"number":62,"question":"下列何者為思覺失調症（schizophrenia）預後不佳的預測因子？","options":["(A) 有明顯的誘發因子（precipitating factors）","(B) 急性發作","(C) 情緒症狀","(D) 負性症狀（negative symptoms）"],"answer":3,"image":""},{"id":"md4-107-2-63","subject":"md4","topic":"精神-精神官能症","meta":"107年第2次第63題","year":107,"session":2,"number":63,"question":"有關罹患重鬱症的患者可能會出現melancholic特徵，下列敘述何者正確？","options":["(A) 在晚上呈現更憂鬱情緒","(B) 與自主神經系統及內分泌系統之改變無關","(C) 肇因於外在壓力事件","(D) 主要特徵為缺乏興趣（anhedonia）、早醒與體重下降等"],"answer":3,"image":""},{"id":"md4-107-2-64","subject":"md4","topic":"精神-精神病","meta":"107年第2次第64題","year":107,"session":2,"number":64,"question":"下列何者不是第一型雙極性疾患（bipolar I disorder）預後較差的危險因子？","options":["(A) 男性","(B) 發作時伴隨有精神病症狀","(C) 個案發病年齡較大","(D) 合併酒精依賴"],"answer":2,"image":""},{"id":"md4-107-2-65","subject":"md4","topic":"精神-精神病","meta":"107年第2次第65題","year":107,"session":2,"number":65,"question":"關於第一型雙極性疾患（bipolar I disorder）的敘述，下列何者錯誤？","options":["(A) 多數個案第一次發作為憂鬱症，而非躁症","(B) 只有極少數躁症個案，會有幻覺或妄想產生","(C) 主要的治療藥物為情緒穩定劑","(D) 男性的個案常合併物質濫用"],"answer":1,"image":""},{"id":"md4-107-2-66","subject":"md4","topic":"精神-精神官能症","meta":"107年第2次第66題","year":107,"session":2,"number":66,"question":"焦慮時下列何者不是其生理症狀？","options":["(A) 瞳孔縮小","(B) 呼吸急促","(C) 胸悶","(D) 腹瀉"],"answer":0,"image":""},{"id":"md4-107-2-67","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"107年第2次第67題","year":107,"session":2,"number":67,"question":"高先生的太太觀察到高先生半夜起來走出房門，甚至打開冰箱取用食物，家人呼喊也未能叫醒，隔天清晨高先生對於這些事情沒有印象，這種情形發生在睡眠的那一期？","options":["(A) 非快速動眼期的第一期（non-REM, stage I）","(B) 非快速動眼期的第二期（non-REM, stage II）","(C) 非快速動眼期的第三、四期（non-REM, stages III & IV）","(D) 快速動眼期（REM）"],"answer":2,"image":""},{"id":"md4-107-2-68","subject":"md4","topic":"精神-器質性與物質使用","meta":"107年第2次第68題","year":107,"session":2,"number":68,"question":"當戒菸治療的取代療法（replacement therapy）失敗，可以考慮下列那一種藥物？","options":["(A) trazodone","(B) bupropion","(C) citalopram","(D) venlafaxine"],"answer":1,"image":""},{"id":"md4-107-2-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"107年第2次第69題","year":107,"session":2,"number":69,"question":"下列有關頭部受傷（head trauma）引起精神症狀敘述，何者錯誤？","options":["(A) 頭部受傷6至12個月後若症狀仍未改善，則可能會慢性化","(B) 注意力不集中、記憶變差及學習新資訊有困難是常見的認知功能障礙","(C) 行為問題包括：憂鬱、易衝動、攻擊性增加及人格改變","(D) 對藥物反應較慢，因此需要較高的初始劑量及較快地調劑速度才能達到療效"],"answer":3,"image":""},{"id":"md4-107-2-70","subject":"md4","topic":"精神-器質性與物質使用","meta":"107年第2次第70題","year":107,"session":2,"number":70,"question":"有關濫用大麻（cannabis）的作用，下列何者正確？","options":["(A) 其依賴主要為生理的依賴（physical dependence）而較少心理的依賴","(B) 中毒時其動作協調變差（impaired motor coordination）","(C) 戒斷時會產生嗜睡及食慾增加之症狀","(D) 常見的生理反應包括明顯心搏變緩（bradycardia）及瞳孔縮小"],"answer":1,"image":""},{"id":"md4-107-2-71","subject":"md4","topic":"精神-器質性與物質使用","meta":"107年第2次第71題","year":107,"session":2,"number":71,"question":"有關酒精戒斷下列何者錯誤？","options":["(A) 酒精戒斷會引起譫妄（delirium），但若其本身就已有身體疾病則較易引起譫妄","(B) 酒精戒斷會引起攻擊，因此需盡快將患者約束在床上","(C) 常須給benzodiazepine類藥物治療","(D) 避免給抗精神病藥物（antipsychotics）"],"answer":1,"image":""},{"id":"md4-107-2-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"107年第2次第72題","year":107,"session":2,"number":72,"question":"關於輕度智能障礙（mild mental retardation）的敘述，下列何者錯誤？","options":["(A) 智商約為70～85，是最常見的智能障礙，約占智能障礙總人數的85%","(B) 通常到小學一、二年級才被發現跟不上功課","(C) 到國、高中的年紀，其學業能力約相當於小學六年級的學生","(D) 合併出現行為規範障礙症（conduct disorder）的機會大於合併出現自閉症（autistic disorder）"],"answer":0,"image":""},{"id":"md4-107-2-73","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"107年第2次第73題","year":107,"session":2,"number":73,"question":"治療注意力缺損／過動疾患（attention-deficit / hyperactivity disorder）之兒童青少年病患使用神經刺激劑（stimulants）前，那個不是一般建議要先測量的項目？","options":["(A) 血壓","(B) 心跳","(C) 血糖","(D) 身高"],"answer":2,"image":""},{"id":"md4-107-2-74","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"107年第2次第74題","year":107,"session":2,"number":74,"question":"「做夢（dreaming）」主要出現在下列那一個睡眠週期？","options":["(A) stage I","(B) stage II","(C) stage III","(D) 快速動眼期睡眠（REM sleep）"],"answer":3,"image":""},{"id":"md4-107-2-75","subject":"md4","topic":"精神-精神官能症","meta":"107年第2次第75題","year":107,"session":2,"number":75,"question":"關於人格違常（personality disorder），下列敘述何者正確？","options":["(A) 邊緣性人格違常（borderline personality disorder）男性個案是女性個案的兩倍","(B) 反社會人格違常（antisocial personality disorder）相較一般大眾並沒有較高比率的酒精或物質濫用","(C) 強迫性人格違常（obsessive-compulsive personality disorder）的核心症狀是完美主義並且缺乏彈性，但他們仍保有良好的社交技巧，交友並不受影響","(D) 人格違常常共病其他精神疾病，如物質濫用，憂鬱症，焦慮症等"],"answer":3,"image":""},{"id":"md4-107-2-76","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第2次第76題","year":107,"session":2,"number":76,"question":"7歲男童因突發性高燒、吞嚥困難就醫，在對比劑注射後，接受電腦斷層掃描檢查如圖示，箭號所指病灶最可能診斷為何？","options":["(A) 扁桃腺炎","(B) 咽喉後膿瘍","(C) 咽喉癌","(D) 甲狀腺水囊"],"answer":1,"image":"md4-107-2-76.jpeg"},{"id":"md4-107-2-77","subject":"md4","topic":"兒科-心血管呼吸","meta":"107年第2次第77題","year":107,"session":2,"number":77,"question":"一位1歲女嬰因呼吸急促至急診就醫，身體檢查發現有吐氣末端哮鳴（end-expiratory wheezing），若因感染造成，下列敘述何者最不恰當？","options":["(A) 嚴重病人常發生於1歲以下","(B) 最常見的病毒為RSV（respiratory syncytial virus）","(C) 傳染途徑主要為空氣傳染（air-borne）","(D) 常先有上呼吸道症狀如流鼻水，然後發生哮鳴（wheezing）"],"answer":2,"image":""},{"id":"md4-107-2-78","subject":"md4","topic":"神經-中風","meta":"107年第2次第78題","year":107,"session":2,"number":78,"question":"某天您在某小型醫院的急診室值班，電腦斷層室技術員突然來電告知您電腦斷層發生不明原因之故障，無法進行檢查。隨後，一位60歲男性病患被家屬送到急診，告訴您該病患在半小時之前突然右側肢體無力，講話不清楚，吞口水頻頻嗆到且有嘔吐。您檢視該名病患時，發現他的Glasgow Coma Scale只有E2V2M4，血壓170/100 mmHg，心跳每分鐘120下，下列處置何者最不恰當？","options":["(A) 儘速給予aspirin的治療，並轉院到有頭部電腦斷層的醫院進行進一步處理","(B) 馬上維持呼吸道的暢通，必要時給予插管，儘速轉院至有頭部電腦斷層的醫院","(C) 病人血壓雖然偏高，但目前不考慮給予降血壓之藥物治療","(D) 轉院前要事先聯絡待轉院醫院，以及早做準備"],"answer":0,"image":""},{"id":"md4-107-2-79","subject":"md4","topic":"醫學倫理與法規","meta":"107年第2次第79題","year":107,"session":2,"number":79,"question":"3天大的陳小弟因為一種很少見的先天性疾病（Pierre-Robin Syndrome）住在嬰兒室，你必須為他照相以在討論會中使用，但是陳家正處於產下畸形兒的傷痛中，下列何種處理方式是最好的？","options":["(A) 照相不會傷害病人，不需家屬同意","(B) 須取得家屬同意才能照相","(C) 討論案例時在顯示病人照片時遮蓋其眼睛，使他人無法辨認，不需家屬同意","(D) 向人體試驗委員會申請照相"],"answer":1,"image":""},{"id":"md4-107-2-80","subject":"md4","topic":"醫學倫理與法規","meta":"107年第2次第80題","year":107,"session":2,"number":80,"question":"患有精神疾病之家庭主婦D，因急性腹痛數天，被家屬帶至急診求助，經外科醫師診斷為急性闌尾炎併發之急性腹膜炎。外科醫師完善告知D及其家屬關於D之病情後，建議緊急開刀，然而D確信自己乃是造成世界災難的罪人，應該以死贖罪，拒絕接受任何勸說及解釋，亦拒絕簽署手術同意書及麻醉同意書。外科醫師照會精神科醫師P，P應作何處理或建議，較為恰當？","options":["(A) 建議外科醫師尊重D不接受手術之自主決定","(B) P應以心理治療之技巧，勸D接受手術","(C) D之醫療決定能力受其精神疾病之影響，脫離現實，無同意或拒絕手術之意思能力，P應建議由其家屬代為簽署手術同意書及麻醉同意書","(D) 建議外科醫師給予D抗精神病藥物，待D之妄想消解之後，再勸其接受手術"],"answer":2,"image":""},{"id":"md4-108-1-1","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第1次第1題","year":108,"session":1,"number":1,"question":"2歲男童半夜因發燒及呼吸窘迫被帶⾄急診求診，問診有Hoarseness和Barking cough的症狀，聽診有Stridor，X光檢查如附圖，下列敘述何者錯誤？","options":["(A) ⽩⾊箭頭標⽰稱為尖塔徵象（Steeple sign）","(B) 此病的診斷最可能為哮吼（Croup）","(C) 急性期可先給與氧氣及Epinephrine混合⽣理食鹽⽔以吸入⽅式治療","(D) 此疾病最常⾒的病原為腸病毒（Enterovirus）"],"answer":3,"image":"md4-108-1-1.jpeg"},{"id":"md4-108-1-2","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"108年第1次第2題","year":108,"session":1,"number":2,"question":"第⼀次感染Epstein-Barr virus所致之傳染性單核球增多症（Infectious mononucleosis），在急性期⾎清的EBV特異性抗體檢查結果，以下何者最為可能？","options":["(A) anti-VCA IgM（-）、anti-VCA IgG（+）、anti-EBNA Ab NEA（+）","(B) anti-VCA IgM（+）、anti-VCA IgG（+）、anti-EBNA Ab NEA（+）","(C) anti-VCA IgM（+）、anti-VCA IgG（+）、anti-EBNA Ab NEA（-）","(D) anti-VCA IgM（-）、anti-VCA IgG（-）、anti-EBNA Ab NEA（+）"],"answer":2,"image":""},{"id":"md4-108-1-3","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第1次第3題","year":108,"session":1,"number":3,"question":"下列何者是造成1歲健康兒童罹患急性細⽀氣管炎（Acute bronchiolitis）的最常⾒病原？","options":["(A) ⼈類間質肺炎病毒（Human metapneumovirus）","(B) 呼吸道融合病毒（Respiratory syncytial virus）","(C) 副流感病毒（Parainfluenza）","(D) 肺炎披衣菌（Chlamydia pneumoniae）"],"answer":1,"image":""},{"id":"md4-108-1-4","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第1次第4題","year":108,"session":1,"number":4,"question":"有關兒童社區性細菌性肺炎之併發症，下列何者最不常⾒？","options":["(A) 腦膜炎（Meningitis）","(B) ⼼包膜炎（Pericarditis）","(C) 膿胸（Empyema）","(D) 肋膜積⽔（Pleural effusion）"],"answer":0,"image":""},{"id":"md4-108-1-5","subject":"md4","topic":"兒科-消化系統疾病","meta":"108年第1次第5題","year":108,"session":1,"number":5,"question":"下列何種肝炎病毒不會經由周產期（Perinatal）傳染？","options":["(A) A型肝炎病毒（Hepatitis A virus）","(B) B型肝炎病毒（Hepatitis B virus）","(C) C型肝炎病毒（Hepatitis C virus）","(D) D型肝炎病毒（Hepatitis D virus）"],"answer":0,"image":""},{"id":"md4-108-1-6","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"108年第1次第6題","year":108,"session":1,"number":6,"question":"滿周歲的幼兒不適合接種下列何種疫苗？","options":["(A) ⽔痘疫苗","(B) A型肝炎疫苗","(C) 輪狀病毒疫苗","(D) 肺炎鏈球菌疫苗"],"answer":2,"image":""},{"id":"md4-108-1-7","subject":"md4","topic":"兒科-消化系統疾病","meta":"108年第1次第7題","year":108,"session":1,"number":7,"question":"剛出⽣的34週⼤的嬰兒，嘴⾓⼀直流⼝⽔並冒出泡泡，值班醫師無法順利將⿐胃管放入。出⽣12⼩時後KUB發現無腸氣，下列那個診斷最有可能？","options":["(A) 單純食道氣管瘻管","(B) 食道閉鎖合併上段食道氣管瘻管","(C) 食道閉鎖合併下段食道氣管瘻管","(D) 食道閉鎖合併上段及下段食道氣管瘻管"],"answer":1,"image":""},{"id":"md4-108-1-8","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"108年第1次第8題","year":108,"session":1,"number":8,"question":"⼀個G1P1 / 39週出⽣體重3,200公克的新⽣兒，出⽣後哺餵全⺟乳。第19個⼩時⼤時檢測總膽紅素值為12 mg/dL、直接型膽紅素值為0.22 mg/dL。⺟親為O型Rh陽性、⽗親B型Rh陽性⾎型。⺟親之前未曾接受過任何 ⾎品輸注。⽗親有⼄型海洋性貧⾎、⺟親則無海洋性貧⾎。下列何者為最可能之診斷？","options":["(A) Rh其他⾎型不合（Rh minor group incompatibility）","(B) ABO⾎型不合（ABO incompatibility）","(C) ⺟乳性黃疸（Breast milk jaundice）","(D) ⼄型海洋性貧⾎（ß-Thalassemia）"],"answer":1,"image":""},{"id":"md4-108-1-9","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"108年第1次第9題","year":108,"session":1,"number":9,"question":"新⽣兒出⽣後即有呼吸窘迫、唇⾊發紫、胸部較腹部來得⾼突的現象。⾝體診察發現最⼤⼼⾳在右側。胸腹部X光片如附圖，最有可能的診斷為何？","options":["(A) 張⼒性氣胸（Tension pneumothorax）","(B) 食道閉鎖（Esophageal atresia）","(C) ⼗⼆指腸閉鎖（Duodenal atresia）","(D) 橫膈膜疝氣（Diaphragmatic hernia）"],"answer":3,"image":"md4-108-1-9.jpeg"},{"id":"md4-108-1-10","subject":"md4","topic":"兒科-消化系統疾病","meta":"108年第1次第10題","year":108,"session":1,"number":10,"question":"比較先天性巨結腸症（Hirschsprung disease, HD）和功能性便秘（Functional constipation, FC）各種症狀出現之機率，下列敘述何者錯誤？","options":["(A) ⼤便失禁（Encopresis）：HD＞FC","(B) ⽣⻑遲緩（Failure to thrive）：HD＞FC","(C) ⼩腸結腸炎（Enterocolitis）：HD＞FC","(D) 腹漲（Abdominal distention）：HD＞FC"],"answer":0,"image":""},{"id":"md4-108-1-11","subject":"md4","topic":"兒科-消化系統疾病","meta":"108年第1次第11題","year":108,"session":1,"number":11,"question":"下列何種腸胃道息⾁（Polyps）發⽣⼤腸癌（Colon cancer）的風險最⾼？","options":["(A) 幼年性息⾁症（Juvenile polyposis）","(B) 家族性結直腸息⾁症（Familial adenomatous polyposis）","(C) Peutz-Jeghers症候群（Peutz-Jeghers syndrome）","(D) Cowden症候群（Cowden syndrome）"],"answer":1,"image":""},{"id":"md4-108-1-12","subject":"md4","topic":"兒科-消化系統疾病","meta":"108年第1次第12題","year":108,"session":1,"number":12,"question":"1歲⼤女嬰因為每天解綠黏⾎絲便2⾄3次，間斷式體溫上升⾄38℃已經2天，體重從10公⽄降⾄9.8公⽄，給與腹瀉藥物和飲食控制。3天後⾎絲便減⾄每天1次，⼤便培養為非傷寒沙⾨⽒桿菌（Nontyphoidal Salmonella）感染，此時體溫37.5℃，體重為9.7公⽄，精神及活動⼒正常，下列處置何者最為恰當？","options":["(A) 應給與電解質⼝服液或稀飯等清淡飲食，開給⼝服抗⽣素治療⾄少7天","(B) 應住院打點滴並禁食，給與靜脈抗⽣素治療⾄少7天","(C) 應給與電解質⼝服液或稀飯等清淡飲食，無需給與⼝服抗⽣素","(D) 應該住院打點滴並禁食，無需給與抗⽣素"],"answer":2,"image":""},{"id":"md4-108-1-13","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"108年第1次第13題","year":108,"session":1,"number":13,"question":"有關副食品添加的原則，下列何者最不適當？","options":["(A) ⺟乳哺餵的孩⼦到6個⽉⼤時必須添加","(B) 有過敏體質的嬰兒宜延後到8個⽉⼤時添加","(C) 1歲以下嬰兒避免餵食蜂蜜","(D) 每次只添加⼀種新食物，由少量開始，逐漸增加，觀察4⾄7天"],"answer":1,"image":""},{"id":"md4-108-1-14","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"108年第1次第14題","year":108,"session":1,"number":14,"question":"關於純⺟乳哺育之嬰幼兒的衛教指導，下列敘述何者最正確？","options":["(A) ⿎勵純⺟乳哺育⾄嬰兒12個⽉⼤","(B) 純⺟乳哺餵之嬰兒維⽣素K可能不⾜，6個⽉後須額外補充","(C) 純⺟乳哺育的嬰兒，在出⽣後6個⽉內無需補充氟","(D) 早產兒純⺟乳哺餵時鐵質可能不⾜，須額外補充；⾜⽉兒則會⾜夠，無需額外補充"],"answer":2,"image":""},{"id":"md4-108-1-15","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"108年第1次第15題","year":108,"session":1,"number":15,"question":"10歲女童學校尿液篩檢發現有⾎尿。主訴在上呼吸道感染後⼀兩天就會有⾁眼可見的⾎尿。詢問病史發現她的舅舅於國三時，因末期腎臟病開始接受透析治療。病童尿液常規檢查顯⽰潛⾎反應（Occult blood）：強陽性（3+）；蛋⽩質（Protein）：100 mg/dL；⽩⾎球（WBC）3-5/HPF；紅⾎球（RBC）100～ 150/HPF。下列何者為最可能之診斷？","options":["(A) 局部巢狀腎絲球硬化（Focal segmental glomerulosclerosis）","(B) 家族性薄基底膜疾病（Familial thin basement membrane disease）","(C) ⾼鈣尿（Hypercalciuria）","(D) Alport症候群（Alport syndrome）"],"answer":3,"image":""},{"id":"md4-108-1-16","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"108年第1次第16題","year":108,"session":1,"number":16,"question":"2 3歲的女童因全⾝⽔腫，體重增加2公⽄就診。體表⾯積Body surface area（BSA）為0.5m，實驗檢查發現蛋⽩尿4+，24⼩時蛋⽩尿為3.3gm，單次尿液檢查：尿蛋⽩（Urine protein）250 mg/dL，尿肌酸酐（Urine creatinine）50 mg/dL，⾎中⽩蛋⽩為1.5 gm/dL，膽固醇：420 mg/dL，三酸⽢油脂：248 mg/dL，下列相關敘述何者錯誤？","options":["(A) 應立即以Statin類降⾎脂藥物治療⾼⾎脂","(B) ⼀般是原發性，不⽤腎臟切片，可先⽤類固醇治療","(C) 蛋⽩尿的量已達到Nephrotic range proteinuria的定義","(D) 若患者對類固醇反應良好則預後好，很少會進展到慢性腎臟病⽽須透析治療"],"answer":0,"image":""},{"id":"md4-108-1-17","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"108年第1次第17題","year":108,"session":1,"number":17,"question":"⼀個正常孩童可以不扶東⻄單腳站立10秒、能照樣式畫圓圈、能表達「你的」「我的」，其發展年齡最接近下列何者範圍？","options":["(A) 滿2歲但未滿3歲","(B) 滿3歲但未滿4歲","(C) 滿4歲但未滿5歲","(D) 滿5歲但未滿6歲"],"answer":1,"image":""},{"id":"md4-108-1-18","subject":"md4","topic":"兒科-感染神經","meta":"108年第1次第18題","year":108,"session":1,"number":18,"question":"下列關於熱性痙攣之敘述，何者正確？","options":["(A) 複雜型熱性痙攣之病⼈，未來發⽣癲癇的機會與⼀般族群相同","(B) 年紀⼩於6個⽉之熱性痙攣患者，須做腰椎穿刺排除中樞神經感染之可能性","(C) ⾸次發⽣單純型熱性痙攣，⼤多須安排神經影像檢查以排除腦部構造異常","(D) 熱性痙攣之發⽣與基因或家族史無關"],"answer":1,"image":""},{"id":"md4-108-1-19","subject":"md4","topic":"兒科-內分泌遺傳","meta":"108年第1次第19題","year":108,"session":1,"number":19,"question":"關於女童性早熟（Precocious puberty），下列那⼀項的致病機轉與其他最不相同？","options":["(A) 環境荷爾蒙接觸（Exogenous estrogens）","(B) 先天性腎上腺增⽣（Congenital adrenal hyperplasia）","(C) 早期McCune-Albright⽒症候群（McCune-Albright syndrome, early）","(D) 下視丘錯構瘤（Hypothalamic hamartoma）"],"answer":3,"image":""},{"id":"md4-108-1-20","subject":"md4","topic":"兒科-內分泌遺傳","meta":"108年第1次第20題","year":108,"session":1,"number":20,"question":"先天性腎上腺增⽣（Congenital adrenal hyperplasia）為⼀群因酵素缺乏⽽導致⽪質醇製造不⾜的疾病，下列何種型別盛⾏率最⾼？","options":["(A) 21-hydroxylase deficiency, nonclassic type","(B) 11β-hydroxylase deficiency","(C) 3β-hydroxysteroid dehydrogenase deficiency, classic type","(D) 17α-hydroxylase/17,20-lyase deficiency"],"answer":0,"image":""},{"id":"md4-108-1-21","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"108年第1次第21題","year":108,"session":1,"number":21,"question":"有關類過敏性紫斑症（Henoch-Schönlein Purpura）的敘述，下列何者最為適切？","options":["(A) 是⼀個以IgE為主的過敏反應","(B) ⼤多數病⼈需使⽤類固醇治療","(C) 因有⽪膚的症狀，須局部治療","(D) 注意是否合併腹痛、關節痛、⾎尿"],"answer":3,"image":""},{"id":"md4-108-1-22","subject":"md4","topic":"兒科-感染神經","meta":"108年第1次第22題","year":108,"session":1,"number":22,"question":"1歲6個⽉的男孩因為連續發燒6天⽽來就診，下列那⼀個臨床表徵最不像川崎⽒症（Kawasaki disease）的臨床表徵？","options":["(A) 草莓舌且嘴唇紅腫⿔裂","(B) 軟顎與扁桃腺出現⽔泡與潰瘍","(C) 頸部淋巴結腫⼤","(D) 雙眼結膜發炎"],"answer":1,"image":""},{"id":"md4-108-1-23","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第1次第23題","year":108,"session":1,"number":23,"question":"2歲的⼩朋友，昨晚飯後跑動玩耍時突然持續咳嗽，今天到急診，發現呼吸聲⾳變得明顯，聽診有單側喘息 ⾳（Wheezing），給與短效型⽀氣管擴張劑（Bronchodilator）後，喘息⾳沒有改變，下列何者為最可能之診斷？","options":["(A) 上呼吸道感染（Upper respiratory tract infection）","(B) 細⽀氣管炎（Bronchiolitis）","(C) 氣喘（Asthma）","(D) 氣道異物阻塞（Airway foreign body obstruction）"],"answer":3,"image":""},{"id":"md4-108-1-24","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"108年第1次第24題","year":108,"session":1,"number":24,"question":"有關預防嬰幼兒過敏的觀念，下列敘述何者最不恰當？","options":["(A) 建議孕婦飲食不需避免⾼過敏食物（例如海鮮、花⽣等）","(B) 建議在4～6個⽉⼤開始添加副食品","(C) 尚未有國際指引建議嬰幼兒常規性使⽤益⽣菌來預防過敏","(D) ⺟乳餵哺期間，⺟親需要避免食⽤⾼過敏食物"],"answer":3,"image":""},{"id":"md4-108-1-25","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第1次第25題","year":108,"session":1,"number":25,"question":"有關漏⽃胸（Funnel chest）的描述，下列何者錯誤？","options":["(A) 幼童因運動⽽出現症狀的比率較青少年低","(B) 女孩發⽣的機率比男孩⾼","(C) 肺功能檢查常⾒到阻塞性的異常","(D) 美觀為⼿術的考量主因之⼀"],"answer":[1,2],"image":"","answer_note":"更正:第25題答Ｂ、Ｃ給分"},{"id":"md4-108-1-26","subject":"md4","topic":"兒科-消化系統疾病","meta":"108年第1次第26題","year":108,"session":1,"number":26,"question":"有關肝病病童疑似猛爆性肝衰竭（Fulminant liver failure）之實驗室診斷數據評估和相關處置，下列何者正確？","options":["(A) 可由⾎清轉胺酶Aspartate aminotransferase（AST）、Alanine aminotransferase（ALT）之數值⾼低判斷猛爆性肝衰竭的嚴重度","(B) 若⾎清⽩蛋⽩（Serum albumin）數值低下，加上超⾳波發現有腹⽔，治療⾸先應給與⽩蛋⽩輸注，並給與維持性點滴輸液","(C) 若凝⾎酶原時間（Prothrombin time）和部分凝⾎活酶時間（Activated partial thromboplastin time）延⻑，應給與維⽣素K以提升肝臟合成凝⾎因⼦II, VII, IX, X","(D) 對於有昏睡或意識障礙的肝病病童，若⾎氨（Ammonia）已經上升且合併第⼆期肝腦病變（Hepatic encephalopathy Stage II）之意識混淆及嗜睡，應立即插管使⽤呼吸器"],"answer":2,"image":""},{"id":"md4-108-1-27","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第1次第27題","year":108,"session":1,"number":27,"question":"2天⼤的⾜⽉新⽣兒，接受例⾏性的⾎氧篩檢時發現雙側下肢的⾎氧飽和度是90%，右⼿⾎氧飽和度是98%，最有可能是下列那⼀種先天性⼼臟病？","options":["(A) 完全型動脈幹（Complete truncus arteriosus）","(B) 主動脈⼸窄縮合併開放性動脈導管（Coarctation of the aorta with patent ductus arteriosus）","(C) 法洛⽒四重症（Tetralogy of Fallot）","(D) 極端型肺動脈瓣狹窄合併開放性動脈導管（Critical pulmonary valve stenosis with patent ductus arteriosus）"],"answer":1,"image":""},{"id":"md4-108-1-28","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第1次第28題","year":108,"session":1,"number":28,"question":"學齡前的兒童常會被聽到無意義（Innocent）、良性（Benign）、或稱作功能性（Functional）的⼼雜⾳ （Heart murmur）。下列那⼀種⼼雜⾳的特徵不太可能是這類型的⼼雜⾳？","options":["(A) ⼼雜⾳的強度達第4級","(B) ⼼雜⾳的強度會隨著姿勢與呼吸⽽改變","(C) ⼼雜⾳僅僅在收縮期出現","(D) 第⼆⼼⾳會因吸氣⽽出現分岔的情形（S2 split）"],"answer":0,"image":""},{"id":"md4-108-1-29","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第1次第29題","year":108,"session":1,"number":29,"question":"在下列那⼀種狀況之下給與⼀個患有先天性⼼臟病的新⽣兒使⽤前列腺素E1（Prostaglandin E1）維持動脈導管（Ductus arteriosus）的開放對病情最沒有幫助？","options":["(A) 上⼼臟型全肺靜脈回流異常合併阻塞（Supracardiac type total anomalous pulmonary venous return with obstruction）","(B) 嚴重主動⼸窄縮（Coarctation of the aorta）","(C) 肺動脈瓣閉鎖且無⼼室中膈缺損（Pulmonary atresia with intact ventricular septum）","(D) 左⼼發育不全症候群（Hypoplastic left heart syndrome）"],"answer":0,"image":""},{"id":"md4-108-1-30","subject":"md4","topic":"兒科-內分泌遺傳","meta":"108年第1次第30題","year":108,"session":1,"number":30,"question":"3個⽉⼤的女嬰經診斷為體染⾊體隱性遺傳的Phenylketonuria，致病原因為缺乏Phenylalanine hydroxylase（PAH），其家族譜系如附圖。哥哥和姊姊分別為6歲和4歲⼤，無任何臨床症狀，發育發展皆正常。哥哥和姊姊帶有突變基因影響到PAH活性的機率為何？","options":["(A) 分別是1/4，1/2","(B) 皆為1/4","(C) 皆為1/2","(D) 皆為2/3"],"answer":3,"image":"md4-108-1-30.jpeg"},{"id":"md4-108-1-31","subject":"md4","topic":"兒科-內分泌遺傳","meta":"108年第1次第31題","year":108,"session":1,"number":31,"question":"有關臺灣現⾏的新⽣兒代謝異常篩檢，下列敘述何者錯誤？","options":["(A) 剛出⽣的寶寶需⼀天內採腳跟⾎，滴在⾎片上，送新⽣兒篩檢中⼼檢查","(B) Tandem mass spectrometry是⽬前最主要的篩檢⼯具","(C) 篩檢的疾病以胺基酸、有機酸、脂肪酸代謝異常為主","(D) 低體重兒、產程有併發症的寶寶比較會有偽陽性（False positive）的結果"],"answer":0,"image":""},{"id":"md4-108-1-32","subject":"md4","topic":"兒科-內分泌遺傳","meta":"108年第1次第32題","year":108,"session":1,"number":32,"question":"下列何種疾病最有可能以如附圖之⽅式遺傳？","options":["(A) 軟骨發育不全（Achondroplasia）","(B) 庫利⽒貧⾎（Cooley anemia）","(C) 裘馨⽒肌⾁失養症（Duchenne muscular dystrophy）","(D) 結節性硬化症（Tuberous sclerosis complex）"],"answer":1,"image":"md4-108-1-32.jpeg"},{"id":"md4-108-1-33","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"108年第1次第33題","year":108,"session":1,"number":33,"question":"15歲男⽣，半夜睡覺突然左側睪丸劇痛，痛到臉⾊蒼⽩、冒冷汗，立即送到醫院急診。在缺乏超⾳波等影像檢查之下，下列何種檢查或治療較符合⼀般醫療現⾏常規？","options":["(A) 抗⽣素治療","(B) 睪丸切片","(C) 睪丸探查⼿術","(D) 睪丸切除⼿術"],"answer":2,"image":""},{"id":"md4-108-1-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"108年第1次第34題","year":108,"session":1,"number":34,"question":"有關脂漏性⽪膚炎（seborrheic dermatitis）的敘述，下列何者錯誤？","options":["(A) 好發在頭⽪、眉⽑、⿐⼦兩側、⽿朵後⾯","(B) 常發於嬰兒和成⼈","(C) 外⽤抗黴菌藥物不能有效治療脂漏性⽪膚炎","(D) 若是病程頑固且臨床表現不尋常，需留意HIV感染"],"answer":2,"image":""},{"id":"md4-108-1-35","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"108年第1次第35題","year":108,"session":1,"number":35,"question":"關於類天疱瘡（bullous pemphigoid）的敘述，下列何者錯誤？","options":["(A) 常發⽣於年輕⼈","(B) 初期可以搔癢、蕁⿇疹樣的病灶表現","(C) 病灶的病理組織檢查常⾒嗜伊紅球（eosinophil）浸潤","(D) 治療藥物以⼝服⽪質類固醇和免疫抑制劑為主"],"answer":0,"image":""},{"id":"md4-108-1-36","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"108年第1次第36題","year":108,"session":1,"number":36,"question":"60歲男性，近⼗年來在背上、四肢⻑出（如圖A）的發癢⽪疹，⽪膚切片做congo red staining（如圖B），在偏光顯微鏡（polarizing microscope）下觀察（如圖C）。最可能診斷為：","options":["(A) 點滴狀乾癬（guttate psoriasis）","(B) 結節性癢疹（prurigo nodularis）","(C) 扁平苔癬（lichen planus）","(D) 類澱粉性苔癬（lichen amyloidsis）"],"answer":3,"image":"md4-108-1-36.jpeg"},{"id":"md4-108-1-37","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"108年第1次第37題","year":108,"session":1,"number":37,"question":"貼膚試驗（patch testing）是診斷接觸性⽪膚炎（contact dermatitis）的重要⼯具，主要⽬的是：","options":["(A) 可作為各類接觸性⽪膚炎的確診","(B) 找出接觸性過敏原","(C) 判斷接觸性⽪膚炎的嚴重度","(D) 確認發病時間是否超過48⼩時"],"answer":1,"image":""},{"id":"md4-108-1-38","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"108年第1次第38題","year":108,"session":1,"number":38,"question":"6歲男孩，從2歲起即反覆出現如圖所⽰之劇癢⽪膚病變；⽗⺟親都常有⿐塞、打噴嚏的症狀，診斷為何？","options":["(A) 脂漏性⽪膚炎","(B) 接觸性⽪膚炎","(C) 異位性⽪膚炎","(D) 鬱⾎性⽪膚炎"],"answer":2,"image":"md4-108-1-38.jpeg"},{"id":"md4-108-1-39","subject":"md4","topic":"皮膚-感染","meta":"108年第1次第39題","year":108,"session":1,"number":39,"question":"下列何者疾病Nikolsky sign是陰性反應？","options":["(A) staphylococcal scalded skin syndrome","(B) pemphigus vulgaris","(C) Stevens-Johnson syndrome","(D) bullous pemphigoid"],"answer":3,"image":""},{"id":"md4-108-1-40","subject":"md4","topic":"皮膚-感染","meta":"108年第1次第40題","year":108,"session":1,"number":40,"question":"有關Toxic shock syndrome的敘述，下列何者錯誤？","options":["(A) 臨床上表現包括⼤⾯積⽪膚紅腫疼痛或是膿皰、以及⽪膚廣泛性脫屑現象","(B) 初期會出現⽪膚疼痛現象，⼤部分是因為術後傷⼝感染或是腹腔感染引起","(C) 病患會出現發燒、喉嚨痛、肌⾁痠痛、嘔吐或是腹瀉，嚴重時會造成低⾎壓以及多重器官衰竭","(D) 主要致病機轉為Pseudomonas製造的exfoliative toxin所引起"],"answer":3,"image":""},{"id":"md4-108-1-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"108年第1次第41題","year":108,"session":1,"number":41,"question":"青年型⽪肌炎（juvenile dermatomyositis）的敘述，下列何者錯誤？","options":["(A) 可以amyopathic dermatomyositis表現","(B) 易合併⽪膚鈣化症（calcinosis cutis）","(C) 易併發⽪膚⾎管病變（vasculopathy）","(D) 易併發⿐咽癌"],"answer":3,"image":""},{"id":"md4-108-1-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"108年第1次第42題","year":108,"session":1,"number":42,"question":"關於⽪膚⿊⾊素過度沉著（hypermelanosis）的敘述，下列何者錯誤？","options":["(A) ⿊⾊素細胞增加或⿊⾊素顆粒製造變多，皆會引起⽪膚⿊⾊素過度沉著","(B) 汗斑（pityriasis versicolor）只會造成膚⾊變深，不會變淺","(C) 轉移性⿊⾊素癌可能造成全⾝⽪膚⿊⾊素過度沉著（universal melanosis）","(D) 基因、賀爾蒙、紫外線等因素都可能會造成⽪膚⿊⾊素過度沉著"],"answer":1,"image":""},{"id":"md4-108-1-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"108年第1次第43題","year":108,"session":1,"number":43,"question":"關於⿊⾊素沉著的治療，下列敘述何者錯誤？","options":["(A) 若增加的⿊⾊素顆粒在表⽪層，使⽤對苯⼆酚（hydroquinone）藥膏可有效淡化","(B) 若增加的⿊⾊素顆粒在真⽪層，使⽤脈衝光（intense pulsed light, IPL）比釹雅各（Nd:YAG）雷射效果更好","(C) 若施打雷射的劑量太強或施打太頻繁，容易造成醫源性⾊素脫失","(D) 外⽤A酸（retinoic acid）藥膏對於雀斑（freckles）有淡化效果"],"answer":1,"image":""},{"id":"md4-108-1-44","subject":"md4","topic":"皮膚-腫瘤","meta":"108年第1次第44題","year":108,"session":1,"number":44,"question":"75歲男性，2年來逐漸在⾜部出現紫⾊斑塊（如圖A），⽪膚病理檢查發現有篩板狀⾎管的增⽣（如圖B），最可能的診斷為何？","options":["(A) ⾎管⾁瘤（angiosarcoma）","(B) 卡波⻄⽒⾁瘤（Kaposi’s sarcoma）","(C) ⾎管⾓化瘤（angiokeratoma）","(D) 竇狀⾎管瘤（sinusoid hemangioma）"],"answer":1,"image":"md4-108-1-44.jpeg"},{"id":"md4-108-1-45","subject":"md4","topic":"皮膚-腫瘤","meta":"108年第1次第45題","year":108,"session":1,"number":45,"question":"承上題，可能與下列何種病毒相關？","options":["(A) human herpesvirus type 8（HHV-8）","(B) human herpes simplex virus type 2（HSV-2）","(C) human papilloma virus（HPV）","(D) Epstein-Barr virus（EBV）"],"answer":0,"image":""},{"id":"md4-108-1-46","subject":"md4","topic":"神經-中風","meta":"108年第1次第46題","year":108,"session":1,"number":46,"question":"⼀位77歲婦⼈，晚間10點入睡時正常，但⼀早8點醒來右側肢體無⼒、⼝齒不清，早上10點即被家⼈送到急診，經神經學及影像學檢查，研判為左側放射冠梗塞（corona radiata infarction），以下何者是對婦⼈最適當的急性中風治療？","options":["(A) 靜脈⾎栓溶解（IV tPA）","(B) 裝置頸動脈⽀架（stenting）","(C) 抗⾎⼩板藥物（antiplatelet）","(D) 抗凝⾎藥物（anticoagulants）"],"answer":2,"image":""},{"id":"md4-108-1-47","subject":"md4","topic":"神經-中風","meta":"108年第1次第47題","year":108,"session":1,"number":47,"question":"下列何者是造成蜘蛛膜下腔出⾎（subarachnoid hemorrhage）最常⾒的原因？","options":["(A) 頭部外傷（trauma）","(B) 顱內動靜脈⾎管畸形（arteriovenous malformations）","(C) 顱內囊狀（saccular type）動脈瘤","(D) 顱內梭狀（fusiform type）動脈瘤"],"answer":[0,2],"image":"","answer_note":"更正:第47題答Ａ、Ｃ給分。"},{"id":"md4-108-1-48","subject":"md4","topic":"神經-中風","meta":"108年第1次第48題","year":108,"session":1,"number":48,"question":"以下何者是腦靜脈竇栓塞（cerebral venous sinus thrombosis）最常⾒的臨床表現？","options":["(A) 複視","(B) 頭痛","(C) 單側肢體無⼒","(D) 意識障礙"],"answer":1,"image":""},{"id":"md4-108-1-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"108年第1次第49題","year":108,"session":1,"number":49,"question":"下列有關快速動眼期睡眠⾏為疾患（REM sleep behavior disorder）的特⾊，何者正確？","options":["(A) 通常在後半夜出現","(B) 每次發⽣通常有固定的動作模式","(C) ⽇後極可能變成阿茲海默⽒症","(D) 多數夢境是愉快的"],"answer":0,"image":""},{"id":"md4-108-1-50","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"108年第1次第50題","year":108,"session":1,"number":50,"question":"⼀位智⼒正常伴有家族性癲癇病史的14歲女孩，常在起床後被家⻑發現不⾃主肢體抽搐，有時甚⾄會跌倒在地上，下列有關診斷及治療的敘述何者錯誤？","options":["(A) 腦波可能出現4～6Hz廣泛性棘波（generalized spikes）","(B) 家族癲癇基因的檢測有助於診斷","(C) 抗癲癇藥（valproate）是治療⾸選藥物","(D) 診斷可能為兒童失神性癲癇"],"answer":3,"image":""},{"id":"md4-108-1-51","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"108年第1次第51題","year":108,"session":1,"number":51,"question":"下列何者不是國際頭痛疾病分類第3版測試版（ICHD-3, beta）偏頭痛（migraine）的診斷標準？","options":["(A) 不治療或治療無效時，頭痛發作會持續4～72⼩時","(B) 伴隨噁⼼及／或嘔吐","(C) ⽇常活動會使頭痛加劇","(D) 伴隨流淚及眼結膜充⾎"],"answer":3,"image":""},{"id":"md4-108-1-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"108年第1次第52題","year":108,"session":1,"number":52,"question":"瞻妄（delirium）與失智症（dementia）的最⼤區別在於瞻妄病⼈容易出現下列那⼀症狀？","options":["(A) 聽幻覺（auditory hallucinations）","(B) 注意⼒（attention）不集中","(C) 攻擊⾏為（aggression）","(D) 癲癇發作（seizures）"],"answer":1,"image":""},{"id":"md4-108-1-53","subject":"md4","topic":"神經-失智退化運動障礙","meta":"108年第1次第53題","year":108,"session":1,"number":53,"question":"⼀位52歲男性突然發⽣右⼿的辨距不良（dysmetria），經頭部電腦斷層檢查發現是中腦左側紅核（red nucleus）附近的⼩出⾎。幾個⽉後，此患者出現喉部不⾃主的動作，檢查發現軟腭出現很有節奏性的2～ 2.5Hz向上收縮的動作。頭部核磁共振造影檢查最可能的發現是：","options":["(A) 左側齒狀核（dentate nucleus）肥⼤","(B) 右側齒狀核（dentate nucleus）肥⼤","(C) 左側下橄欖核（inferior olivary nucleus）肥⼤","(D) 右側下橄欖核（inferior olivary nucleus）肥⼤"],"answer":2,"image":""},{"id":"md4-108-1-54","subject":"md4","topic":"神經-失智退化運動障礙","meta":"108年第1次第54題","year":108,"session":1,"number":54,"question":"當病⼈出現下列那⼀個症狀，比較有可能不是原發性的巴⾦森⽒病（idiopathic Parkinson disease）？","options":["(A) 嗅覺減退（hyposmia）","(B) 不寧腳症候群（restless legs syndrome）","(C) ⽪質性感覺喪失（cortical sensory loss）","(D) 快速動眼期睡眠⾏為異常（rapid eye movement sleep behavior disorder）"],"answer":2,"image":""},{"id":"md4-108-1-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"108年第1次第55題","year":108,"session":1,"number":55,"question":"下列各項神經疾病，何者的感覺系統最不會受到侵犯？","options":["(A) 糖尿病多發性神經病變（diabetic polyneuropathy）","(B) 腕隧道症候群（carpal tunnel syndrome）","(C) 運動神經元病變（motor neuron disease）","(D) 腰神經根病變（lumbar root lesion）"],"answer":2,"image":""},{"id":"md4-108-1-56","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"108年第1次第56題","year":108,"session":1,"number":56,"question":"30歲男性，背負50公⽄沙袋跑完100公尺後，發現嚴重腰痛，合併右下肢後側傳⾄腳底的⿇痛感，最有可能的診斷為何？","options":["(A) 帶狀皰疹神經炎（herpes zoster neuritis）","(B) Guillain-Barré 症候群（Guillain-Barré syndrome）","(C) 多發性肌炎（polymyositis）","(D) 腰椎椎間盤突出（herniation of intervertebral disc）"],"answer":3,"image":""},{"id":"md4-108-1-57","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"108年第1次第57題","year":108,"session":1,"number":57,"question":"45歲女性主訴右腳無⼒兩天，神經學檢查發現右下肢無⼒，肚臍以下左側痛、溫覺喪失，檢查顯⽰為發炎性脊髓病變，對於她的檢查結果之敘述，下列何者錯誤？","options":["(A) 磁振造影呈現病灶處T1訊號上升（T1-weighted hyperintense）、T2訊號不變（T2-weighted isointense），則可能為急性脊髓炎","(B) 視神經檢查可幫助診斷視神經脊髓炎","(C) 腰椎穿刺結果可能發現細胞–蛋⽩分離（cytoalbuminologic dissociation）","(D) ⾎液檢查可能出現anti-SSA antibody"],"answer":0,"image":""},{"id":"md4-108-1-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"108年第1次第58題","year":108,"session":1,"number":58,"question":"下列何者不是神經纖維瘤第⼀型（neurofibromatosis type 1）的典型症狀？","options":["(A) 虹膜⾊素瘤（Lisch nodule）","(B) 咖啡⽜奶斑（café au lait spots）","(C) 雙側聽神經瘤（bilateral acoustic neuromas）","(D) ⽪膚多發性神經纖維瘤（multiple skin neurofibromas）"],"answer":2,"image":""},{"id":"md4-108-1-59","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"108年第1次第59題","year":108,"session":1,"number":59,"question":"下列有關視神經脊髓炎（neuromyelitis optica spectrum disorder, NMOSD）的敘述，何者正確？","options":["(A) 視神經脊髓炎對脊髓的侵犯範圍通常可以超過三節以上","(B) 典型的視神經脊髓炎的臨床症狀包括：視神經炎、急性脊髓炎發作及周邊神經病變","(C) 視神經脊髓炎的病⼈比起多發性硬化症的病⼈的預後要好，其視⼒和脊髓炎導致下肢無⼒的情況，均可恢復80%以上","(D) 因為視神經脊髓炎病⼈的脊髓液，並不會出現蛋⽩質升⾼或是有oligoclonal band的現象，因此容易和多發性硬化症（multiple sclerosis）區分"],"answer":0,"image":""},{"id":"md4-108-1-60","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"108年第1次第60題","year":108,"session":1,"number":60,"question":"對於神經性梅毒（neurosyphilis）的敘述，下列何者正確？","options":["(A) 若測得病患⾎中的VDRL（Veneral Disease Research Laboratory）效價增⾼，即可⽤來確診神經性梅毒感染","(B) 病患的脊髓液需要做螢光螺旋體抗體試驗（fluorescent treponemal antibody absorption test, FTA-ABS）。這個試驗的結果也可以⽤來監測治療效果","(C) 病患可以出現Argyll-Robertson瞳孔，其症狀是光反射消失，兩眼往內往近看時，瞳孔的收縮反射消失","(D) 可以導致tabes dorsalis病徵，病患出現類似⼑割的神經痛、進⾏性的共濟失調及本體感覺缺失"],"answer":3,"image":""},{"id":"md4-108-1-61","subject":"md4","topic":"精神-精神病","meta":"108年第1次第61題","year":108,"session":1,"number":61,"question":"有關妄想症（delusional disorder）之敘述，下列何者錯誤？","options":["(A) ⼀般發作年齡從18到90歲都有可能，但平均發作年齡是40歲左右","(B) 此類病患除非被家⼈或法庭強制送醫，否則很少主動尋求醫師協助","(C) 社交孤立是此症之危險因⼦","(D) 此症較常發⽣於男性"],"answer":3,"image":""},{"id":"md4-108-1-62","subject":"md4","topic":"精神-精神病","meta":"108年第1次第62題","year":108,"session":1,"number":62,"question":"何者不是⽬前美國食品及藥物管理署（FDA）核准⽤於治療雙極性疾患（bipolar disorder）躁期的藥物？","options":["(A) 鋰鹽（lithium）","(B) carbamazepine","(C) valproic acid","(D) lamotrigine"],"answer":3,"image":""},{"id":"md4-108-1-63","subject":"md4","topic":"精神-精神病","meta":"108年第1次第63題","year":108,"session":1,"number":63,"question":"關於雙極性疾患（bipolar disorder）與重度憂鬱症（major depressive disorder）的敘述，下列何者正確？","options":["(A) 重度憂鬱症的終⽣盛⾏率（lifetime prevalence）較低","(B) 雙極性疾患的定義為必須包括重鬱期（major depressive episode）及躁期（manic episode）皆經歷","(C) 重度憂鬱症的家族遺傳關聯性低於雙極性疾患，且女性患者較多","(D) 兩種疾患的個案在憂鬱期接受的藥物治療皆以抗憂鬱劑為⾸選"],"answer":2,"image":""},{"id":"md4-108-1-64","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"108年第1次第64題","year":108,"session":1,"number":64,"question":"有關老年⼈⾃殺之敘述何者錯誤？","options":["(A) 憂鬱症為最常⾒的共病精神疾患","(B) 老年⼈⾃殺較少採⽤激烈的⼿段","(C) ⾃殺死亡者，男性多於女性","(D) 常常因為失落或⾝體疾病誘發⾃殺⾏為"],"answer":1,"image":""},{"id":"md4-108-1-65","subject":"md4","topic":"精神-精神官能症","meta":"108年第1次第65題","year":108,"session":1,"number":65,"question":"關於社交焦慮症（social anxiety disorder (social phobia)）的描述下列何者錯誤？","options":["(A) 個案主要是害怕他⼈批評或評價的眼光","(B) 常伴隨逃避⼈群及社交場合的⾏為","(C) 個案認為這種對社交的害怕是過度或不合理的","(D) 通常初次發⽣於成⼈早期"],"answer":3,"image":""},{"id":"md4-108-1-66","subject":"md4","topic":"精神-精神官能症","meta":"108年第1次第66題","year":108,"session":1,"number":66,"question":"認知學說解釋情緒障礙，認為最主要的影響因素是？","options":["(A) 想法","(B) 事件本⾝","(C) 結果","(D) 潛意識"],"answer":0,"image":""},{"id":"md4-108-1-67","subject":"md4","topic":"精神-器質性與物質使用","meta":"108年第1次第67題","year":108,"session":1,"number":67,"question":"在尼古丁的戒癮治療中，下列那種治療⽅式成效最好？","options":["(A) 病⼈⾃⼰靠意志⼒戒除","(B) 醫⽣建議病⼈戒除","(C) 使⽤尼古丁貼片或⼝香糖","(D) 使⽤戒菸藥物併⽤團體治療"],"answer":3,"image":""},{"id":"md4-108-1-68","subject":"md4","topic":"精神-器質性與物質使用","meta":"108年第1次第68題","year":108,"session":1,"number":68,"question":"⼀位72歲男性，有反覆性之痔瘡脫垂（hemorrhoid prolapse），但拒絕接受⼿術治療，外科醫師遂轉介個案接受精神科⼼智狀態評估，以照會精神醫學的觀點，精神科醫師與病患會談的重點，不應該包含下列何者？","options":["(A) 評估病患或其家屬之術後照顧能⼒","(B) 評估病患⼼智狀態對於⼿術之利弊與後遺症了解程度","(C) 告知⼿術的必要性與成功率","(D) 了解個案拒絕⼿術的原委"],"answer":2,"image":""},{"id":"md4-108-1-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"108年第1次第69題","year":108,"session":1,"number":69,"question":"⼀位61歲男性⻑期使⽤diazepam每天50～60毫克達15年，若立即停⽌服⽤後，下列何者為最正確的描述？","options":["(A) ⼼搏變慢","(B) 戒斷症狀不會在停⽤5天後才出現","(C) 抽搐發作為較嚴重之戒斷症狀","(D) 戒斷症狀不致於產⽣譫妄"],"answer":2,"image":""},{"id":"md4-108-1-70","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"108年第1次第70題","year":108,"session":1,"number":70,"question":"⼀位8歲兒童，原本個性害羞，在搬家換學校後，⼀直抱怨上學後⾃⼰⾝體不適、擔⼼⽗⺟親不來接⾃⼰回家，某天上學前會哭鬧抗拒上學，晚上睡覺⼀直做有關爸媽不⾒了的惡夢，持續超過⼀個⽉。下列何者正確？","options":["(A) 以上的描述完全符合兒童的廣泛性焦慮症（generalized anxiety disorder）的特徵","(B) 第⼀線的治療⽅式是精神分析性的⼼理治療","(C) 若要藥物治療，應選擇具⾎清素（serotonin）回收抑制效果的抗憂鬱劑","(D) 症狀明顯改善之後，才對其家⼈進⾏衛教和家族性的⼼理介入"],"answer":2,"image":""},{"id":"md4-108-1-71","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"108年第1次第71題","year":108,"session":1,"number":71,"question":"下列有關妥瑞⽒症（Tourette's disorder）的敘述，何者錯誤？","options":["(A) 須合併有動作抽搐（tic）和聲⾳抽搐","(B) 症狀須在12歲前出現","(C) 可使⽤低劑量的抗精神病藥物（antipsychotics）治療","(D) 男⽣多於女⽣"],"answer":1,"image":""},{"id":"md4-108-1-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"108年第1次第72題","year":108,"session":1,"number":72,"question":"關於注意⼒缺損／過動疾患（attention-deficit/hyperactivity disorder）何者錯誤？","options":["(A) 過動症狀比注意⼒問題較早改善","(B) 到成⼈時期仍然有部分患者有注意⼒缺損問題","(C) 注意⼒缺損／過動疾患治療之統合分析結果顯⽰，非藥物治療之療效遠優於藥物治療","(D) 易共病物質使⽤相關疾患"],"answer":2,"image":""},{"id":"md4-108-1-73","subject":"md4","topic":"精神-器質性與物質使用","meta":"108年第1次第73題","year":108,"session":1,"number":73,"question":"下列何種藥物已被美國FDA認可⽤於治療嗜睡症（narcolepsy）？","options":["(A) clozapine","(B) lorazepam","(C) lithium","(D) modafinil"],"answer":3,"image":""},{"id":"md4-108-1-74","subject":"md4","topic":"精神-器質性與物質使用","meta":"108年第1次第74題","year":108,"session":1,"number":74,"question":"關於酒精相關障礙症（alcohol related disorders）之敘述，下列何者錯誤？","options":["(A) 常共病（comorbid）其他物質相關障礙症、反社會型⼈格障礙症（antisocial personality disorder）、情感性疾患（mood disorders）、或焦慮性疾患（anxiety disorders）","(B) 酒精戒斷症候群包括：⼿抖、焦慮、噁⼼、幻覺及癲癇發作等","(C) 酒精戒斷症候群治療⾸選為benzodiazepines","(D) 使⽤酒精可幫助入眠，減少睡眠中斷，增加快速動眼期睡眠（REM sleep）及stage 4 sleep"],"answer":3,"image":""},{"id":"md4-108-1-75","subject":"md4","topic":"精神-器質性與物質使用","meta":"108年第1次第75題","year":108,"session":1,"number":75,"question":"關於睡眠障礙，下列何者正確？","options":["(A) 睡眠驚恐症（sleep terror）常發⽣於睡眠的後半夜","(B) 夢遊（sleepwalking）主要發⽣於快速動眼期（REM period）","(C) 夢魘（噩夢，nightmare）主要發⽣於非快速動眼期（NREM）","(D) 睡眠驚恐症（sleep terror）常發⽣於非快速動眼期的深睡期（deep NREM sleep）"],"answer":3,"image":""},{"id":"md4-108-1-76","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"108年第1次第76題","year":108,"session":1,"number":76,"question":"15歲學⽣不幸摔⾞疑似造成上腹部器官挫傷，抱怨上腹部疼痛、⼼跳加快，若欲進⾏腹部影像評估是否有肝臟⾎管傷害出⾎，下列何者最為優先？","options":["(A) ⾎管攝影","(B) 電腦斷層掃描","(C) 磁振造影","(D) 同位素肝臟掃描"],"answer":1,"image":""},{"id":"md4-108-1-77","subject":"md4","topic":"兒科-感染神經","meta":"108年第1次第77題","year":108,"session":1,"number":77,"question":"⼀位10歲兒童因發燒2天及起疹⼦⾄急診就醫，檢查時發現疹⼦型態有maculae、papulae和vesicles等，下列何者敘述最不恰當？","options":["(A) 由Herpes virus引起","(B) 疹⼦出現後開始具傳染性","(C) 可能產⽣的併發症包括腦炎、肺炎","(D) 避免使⽤aspirin治療"],"answer":1,"image":""},{"id":"md4-108-1-78","subject":"md4","topic":"神經-中風","meta":"108年第1次第78題","year":108,"session":1,"number":78,"question":"有關腦中風之治療，下列敘述何者錯誤？","options":["(A) ⼤多數腦中風病⼈的⾎壓，會在疼痛、躁動、腦壓受控制後⾃然降低","(B) 缺⾎性腦中風，收縮壓＞200 mmHg，舒張壓＞100 mmHg以上時，要緊急降壓","(C) 針對3⼩時內缺⾎性腦中風病⼈，適合給r-tPA治療者，可改善神經學預後","(D) 以r-tPA治療缺⾎性腦中風之劑量，最⼤量不超過90 mg"],"answer":1,"image":""},{"id":"md4-108-1-79","subject":"md4","topic":"醫學倫理與法規","meta":"108年第1次第79題","year":108,"session":1,"number":79,"question":"「耶和華⾒證⼈」（Jehovah's Witnesses）教派信徒在醫療上堅持不接受輸⾎。近來基於尊重病⼈⾃主的倫理原則，法律與倫理逐漸接受耶和華⾒證⼈拒絕輸⾎的意願，應該予以尊重；下列那⼀種情形，醫師應該尊重⼀個表明為耶和華⾒證⼈的信徒拒絕輸⾎的意願？","options":["(A) 成年且有⾏為能⼒的病⼈情況緊急，如果不輸⾎的話，病⼈就會死亡；但有清楚的文書證據，證明病⼈的確有拒絕輸⾎的意願","(B) 病⼈是懷孕36週的婦女拒絕輸⾎","(C) 病⼈是15歲的未成年⼈拒絕輸⾎","(D) ⽗⺟都是耶和華⾒證⼈信徒，為其8歲病童拒絕輸⾎"],"answer":0,"image":""},{"id":"md4-108-1-80","subject":"md4","topic":"醫學倫理與法規","meta":"108年第1次第80題","year":108,"session":1,"number":80,"question":"2000公克早產兒在加護病房住院近兩個⽉，她因為雙側腎臟發育不全⽽合併慢性腎衰竭，⼜因為肺發育不全合併肺炎⼀直倚賴呼吸器治療，於3週前需開始⻑期腹膜透析以維持電解質及體液等平衡。很不幸地，這兩天醫師發現嬰兒發燒、透析液轉為混濁，並且流量⼤為減少，初步檢查診斷為黴菌性腹膜炎，除了⽤藥外，醫師建議⼿術更換腹膜透析管。這時候，不滿20歲的年輕⽗⺟親要求醫師：「她實在好可憐，不要救了，讓她⾛吧，請幫我們移除呼吸器，讓我們回家吧！」。下列何種做法最合適？","options":["(A) ⽗⺟⽣她，也是法定代理⼈，必須由⽗⺟移除其呼吸器","(B) 取得⽗⺟同意書後，施予緩和醫療，可由醫護⼈員移除呼吸器，讓她回家","(C) 以所有可⽤之現代醫療盡全⼒搶救到最後","(D) 不移除維⽣之呼吸器，但停⽌⼿術等積極治療"],"answer":1,"image":""},{"id":"md4-108-2-1","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"108年第2次第1題","year":108,"session":2,"number":1,"question":"3天大的新生兒，在軀幹與手腳出現大小1～2 mm的紅色丘疹與水泡，一週後這些疹子在未經治療的情形之下自行消失。下列那一項是最可能的診斷？","options":["(A) Erythema toxicum","(B) Carbuncle","(C) Salmon patch","(D) Congenital syphilis"],"answer":0,"image":""},{"id":"md4-108-2-2","subject":"md4","topic":"兒科-感染神經","meta":"108年第2次第2題","year":108,"session":2,"number":2,"question":"關於嬰幼兒感染砂眼披衣菌（Chlamydia trachomatis）肺炎之敘述，下列何者較正確？","options":["(A) 罹患砂眼披衣菌母親且未接受治療，約九成其新生兒會得到砂眼披衣菌肺炎","(B) 通常新生兒出生後1週內會有明顯肺炎症狀","(C) 相對呼吸道融合病毒感染，砂眼披衣菌肺炎較容易發燒及喘鳴聲（Wheezing）","(D) 砂眼披衣菌感染後，血液中嗜伊紅白血球會增加（eosinophils > 400 cells/μL）"],"answer":3,"image":""},{"id":"md4-108-2-3","subject":"md4","topic":"兒科-感染神經","meta":"108年第2次第3題","year":108,"session":2,"number":3,"question":"有關猩紅熱（Scarlet fever）的敘述，下列何者錯誤？","options":["(A) 臨床上需與病毒疹、川崎氏症（Kawasaki disease）或是金黃色葡萄球菌感染區別","(B) 猩紅熱的疹子摸起來有粗糙的感覺","(C) 典型症狀亦包含草莓舌、全身性瀰漫紅疹、嘴唇周圍蒼白，數天後皮膚會脫屑","(D) 猩紅熱的致病機轉和A群鏈球菌（Group A streptococcus）所產生的內毒素（Endotoxin）有關"],"answer":3,"image":""},{"id":"md4-108-2-4","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"108年第2次第4題","year":108,"session":2,"number":4,"question":"未規則產檢的媽媽急產，其新生兒因呼吸窘迫住院，細菌室通知血液培養長革蘭氏陽性球菌，下列何者為最可能造成此新生兒敗血症的細菌？","options":["(A) Staphylococcus aureus","(B) Streptococcus agalactiae","(C) Escherichia coli","(D) Listeria monocytogenes"],"answer":1,"image":""},{"id":"md4-108-2-5","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第2次第5題","year":108,"session":2,"number":5,"question":"7天大男嬰，發現有呼吸窘迫、發紺及心雜音。呼吸次數每分鐘60次合併厲害胸凹（Subcostal retraction）現象，肝臟下緣位於右肋骨下4公分，右手血壓為90/50 mmHg，左手及下肢血壓約為60/45 mmHg。下列敘述何者錯誤？","options":["(A) 需要給與前列腺素（Prostaglandin E）1","(B) 常合併胸腺發育不良（Thymic hypoplasia）","(C) 常合併臉部異常及顎裂（Cleft palate）","(D) 常合併血中鈣離子偏高（Hypercalcemia）"],"answer":3,"image":""},{"id":"md4-108-2-6","subject":"md4","topic":"兒科-消化系統疾病","meta":"108年第2次第6題","year":108,"session":2,"number":6,"question":"下列何種疾病是因膽色素結合酵素（glucuronyl transferase）活性不良所引起新生兒間接型高膽色素血症（indirect hyperbilirubinemia）之原因？","options":["(A) Gilbert disease","(B) Hereditary spherocytosis","(C) G6PD deficiency","(D) ABO incompatibility"],"answer":0,"image":""},{"id":"md4-108-2-7","subject":"md4","topic":"兒科-消化系統疾病","meta":"108年第2次第7題","year":108,"session":2,"number":7,"question":"新生兒出生後，發現腹腔內臟突出，並有一層薄膜覆蓋包住並與臍帶相連，最有可能的診斷為何？","options":["(A) 臍膨出（omphalocele）","(B) 腹裂（gastroschisis）","(C) 臍疝氣（umbilical hernia）","(D) 臍肉芽腫（umbilical granuloma）"],"answer":0,"image":""},{"id":"md4-108-2-8","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第2次第8題","year":108,"session":2,"number":8,"question":"下列有關新生兒暫時性呼吸過速（Transient tachypnea of newborn）之敘述，何者最不適當？","options":["(A) 與肺部液體吸收不全有關","(B) 自然產嬰兒相較剖腹產嬰兒容易發生","(C) 大部份呼吸窘迫症狀於72小時內緩解","(D) 少數個案可併發持續性肺動脈高壓"],"answer":1,"image":""},{"id":"md4-108-2-9","subject":"md4","topic":"兒科-消化系統疾病","meta":"108年第2次第9題","year":108,"session":2,"number":9,"question":"下列何種疾病，最少合併膽囊水腫（Hydrops of gallbladder）？","options":["(A) 川崎症（Kawasaki disease）","(B) 多脾症（Polysplenia syndrome）","(C) 鏈球菌咽喉炎（Streptococcal pharyngitis）","(D) 過敏性紫斑症（Henoch–Schönlein purpura）"],"answer":1,"image":""},{"id":"md4-108-2-10","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"108年第2次第10題","year":108,"session":2,"number":10,"question":"依據兒童健康手冊，關於母乳哺育兒的正常生理現象，下列何者錯誤？","options":["(A) 喝母乳的寶寶，黃疸可能持續到2～3個月才完全消退，但為避免其他疾病，如果寶寶滿月後仍有黃疸，應請教兒科醫師","(B) 喝母乳的寶寶在頭幾個月的大便通常是稀稀水水的，帶有顆粒或酸味，甚至一吃就解便，一般屬於正常現象，如果身高體重異常，應請教兒科醫師","(C) 有些寶寶在3週大以後，可能大便次數變少，變成3至4天才解1次軟便，甚至10到14天才解便1次","(D) 喝母乳的寶寶其第一次胎便，常延遲至24至48小時才排出，屬於正常現象"],"answer":3,"image":""},{"id":"md4-108-2-11","subject":"md4","topic":"兒科-消化系統疾病","meta":"108年第2次第11題","year":108,"session":2,"number":11,"question":"關於威爾森氏疾病（Wilson disease），下列敘述何者錯誤？","options":["(A) 屬於體染色體隱性（Autosomal recessive）遺傳疾病","(B) 找不到病因的肝炎應把威爾森氏疾病列為鑑別診斷","(C) 眼睛視網膜（Retina）會出現Kayser-Fleischer ring","(D) 大部份病患血清中的Ceruloplasmin濃度會降低"],"answer":2,"image":""},{"id":"md4-108-2-12","subject":"md4","topic":"兒科-消化系統疾病","meta":"108年第2次第12題","year":108,"session":2,"number":12,"question":"關於兒童次發性消化性潰瘍（Secondary peptic ulcers），下列敘述何者錯誤？","options":["(A) Nonsteroidal anti-inflammatory drugs（NSAIDs）藉由抑制prostaglandin，而造成黏膜損傷","(B) Nonsteroidal anti-inflammatory drugs（NSAIDs）造成的潰瘍位置，最常見於十二指腸（duodenum）","(C) 壓力性潰瘍（Stress ulcer）通常在事件開始後的24小時內發生","(D) 氫離子幫浦抑制劑（Proton pump inhibitors），可用於治療嚴重潰瘍出血的病患"],"answer":1,"image":""},{"id":"md4-108-2-13","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"108年第2次第13題","year":108,"session":2,"number":13,"question":"引起高陰離子間隙代謝性酸中毒（High anion gap metabolic acidosis）的疾病，下列何者最為罕見？","options":["(A) 糖尿病引起酮酸血症（Diabetic ketoacidosis, DKA）","(B) 因休克引起的乳酸中毒（Sepsis induced lactic acidosis）","(C) 腎小管酸血症（Renal tubular acidosis）","(D) 乙二醇中毒（Ethylene glycol intoxication）"],"answer":2,"image":""},{"id":"md4-108-2-14","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"108年第2次第14題","year":108,"session":2,"number":14,"question":"下列何種情形與鉀離子流失所造成的低血鉀（Hypokalemia）最無關？","options":["(A) 注射胰島素（Insulin）","(B) 長期使用利尿劑（Long-term usage of diuretics）","(C) 腸胃炎引起腹瀉（Gastroenteritis induced diarrhea）","(D) 腎小管酸血症（Renal tubular acidosis）"],"answer":0,"image":""},{"id":"md4-108-2-15","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"108年第2次第15題","year":108,"session":2,"number":15,"question":"有關兒童過敏性紫斑症引起的腎臟發炎（Henoch-Schӧnlein purpura nephritis），下列敘述何者正確？","options":["(A) 於發病時，都會同時合併上呼吸道感染（Upper respiratory tract infection）的症狀","(B) 血尿（Hematuria）或蛋白尿（proteinuria）等腎臟方面的表現，都會與皮膚的表現（palpable purpura）同時出現","(C) 與IgA腎炎（IgA nephropathy）的鑑別診斷，必需藉由病理切片作判斷","(D) 急性期有併發腎炎的患者，成年後罹患慢性腎臟病（Chronic kidney disease）的機會較大"],"answer":3,"image":""},{"id":"md4-108-2-16","subject":"md4","topic":"兒科-感染神經","meta":"108年第2次第16題","year":108,"session":2,"number":16,"question":"3歲大的兒童，門診的身體診察發現此病童頭圍小，戴助聽器，只能說出簡單的詞彙，而無法說出短句，其它的身體診察正常。其出生史為足月自然產並合併黃疸及血小板過低。本次電腦斷層檢查發現腦室周圍有鈣化。根據以上資訊下列那一種先天性感染疾病最有可能？","options":["(A) 梅毒（Syphilis）","(B) 弓漿蟲病（Toxoplasmosis）","(C) 疱疹病毒（Herpes simplex virus infection）","(D) 巨細胞病毒感染（Cytomegalovirus infection）"],"answer":3,"image":""},{"id":"md4-108-2-17","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"108年第2次第17題","year":108,"session":2,"number":17,"question":"罹患頭痛的小孩，出現以下何種情形時，最需要做神經影像檢查？","options":["(A) 頭痛持續一個小時以上","(B) 出現發燒","(C) 有局部不正常神經學徵兆（Focal neurological sign）","(D) 有偏頭痛（Migraine）家族史"],"answer":2,"image":""},{"id":"md4-108-2-18","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"108年第2次第18題","year":108,"session":2,"number":18,"question":"一歲小孩自6個月大起，發生數次大哭後面色發黑，並喪失意識，數秒後清醒正常，身體診察無明顯異常，最常見之疾病為何？","options":["(A) 屏氣發作（Breath-holding spell）","(B) 先天性心臟病（Congenital heart disease）","(C) 過度換氣症候群（Hyperventilation syndrome）","(D) 失神發作（Absence attack）"],"answer":0,"image":""},{"id":"md4-108-2-19","subject":"md4","topic":"兒科-內分泌遺傳","meta":"108年第2次第19題","year":108,"session":2,"number":19,"question":"由於母親的甲狀腺促素受器阻斷抗體（maternal thyrotropin receptor-blocking antibody），導致其新生兒發生先天性甲狀腺低能症（congenital hypothyroidism），下列敘述何者錯誤？","options":["(A) 當母親患有甲狀腺自體免疫疾病（autoimmune thyroid disease）時，應考慮此診斷","(B) 患兒及其母親均可測到甲狀腺促素受器抗體（thyrotropin receptor antibody）","(C) 患兒接受甲狀腺超音波檢查無法顯示甲狀腺存在，但同位素檢查可見其存在","(D) 患兒是否需長期接受甲狀腺素補充，取決於後續抗體及甲狀腺功能追蹤結果"],"answer":2,"image":""},{"id":"md4-108-2-20","subject":"md4","topic":"兒科-內分泌遺傳","meta":"108年第2次第20題","year":108,"session":2,"number":20,"question":"下列何者不是確診生長激素缺乏症（growth hormone deficiency）之激發試驗（provocative test）？","options":["(A) Oral glucose tolerance test","(B) Arginine test","(C) Clondine test","(D) Glucagon test"],"answer":0,"image":""},{"id":"md4-108-2-21","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第2次第21題","year":108,"session":2,"number":21,"question":"下列何者不是典型嚴重氣喘患童之肺功能測量儀（spirometry）測量結果？（FVC：forced vital capacity全力吐氣量；FEV：forced expiratory volume at one second一秒全力吐氣量。）1","options":["(A) FEV/ FVC比值＜0.80 1","(B) 支氣管擴張反應FEV改善值≧12% 1","(C) 運動激發試驗FEV值下降≧15% 1","(D) 每天晨間和晚間FEV變異度≦20% 1"],"answer":3,"image":""},{"id":"md4-108-2-22","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"108年第2次第22題","year":108,"session":2,"number":22,"question":"關於幼年型類風濕性關節炎（Juvenile idiopathic arthritis, JIA），下列何者錯誤？","options":["(A) 根據美國風濕病醫學會（ACR）診斷標準，關節炎需持續超過6週","(B) 多關節型（Polyarthritis）JIA患者，風濕因子（Rheumatoid factor, RF）陽性者的預後較陰性者佳","(C) 全身系統型（Systemic arthritis）的JIA患者，有時會併發巨噬細胞活化症候群（Macrophage activation syndrome），臨床表現為高燒，肝脾與淋巴結腫大，白血球減低等","(D) 少關節型（Oligoarthritis）JIA患者容易併發慢性葡萄膜炎（Chronic uveitis）"],"answer":1,"image":""},{"id":"md4-108-2-23","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"108年第2次第23題","year":108,"session":2,"number":23,"question":"兒童全身性紅斑性狼瘡（Systemic lupus erythematosus, SLE）可以產生多種自體抗體，那兩種自體抗體專一性最高？","options":["(A) Antinuclear antibody（ANA）和Anti-double-stranded DNA（anti-dsDNA）","(B) Anti-La antibody和Anti-Smith antibody","(C) Anti-dsDNA和Anti-Smith antibody","(D) Anti-Ro antibody和Anti-dsDNA"],"answer":2,"image":""},{"id":"md4-108-2-24","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"108年第2次第24題","year":108,"session":2,"number":24,"question":"10歲女童小華，患有皮膚疹已經三個月，經醫師診斷為慢性蕁麻疹(Urticaria)，下列敘述何者錯誤？","options":["(A) 診斷慢性蕁麻疹時，病人症狀反覆發生須超過6星期","(B) 抽血通常有很高的機率找出過敏原","(C) 蕁麻疹分為急性和慢性，兩者形成機轉和治療方式不同","(D) 慢性蕁麻疹之病患血中之IgE抗體，不一定會升高"],"answer":1,"image":""},{"id":"md4-108-2-25","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"108年第2次第25題","year":108,"session":2,"number":25,"question":"關於缺鐵性貧血（Iron-deficiency anemia）病人，如果沒有發生心衰竭或嚴重胃腸道出血，下列何者錯誤？","options":["(A) 服用鐵劑後注意腸胃及便秘情形","(B) 網狀紅血球追蹤檢查","(C) 在血液常規檢查正常後，一般建議繼續給與鐵劑治療2-3個月","(D) 立即給與紅血球輸血"],"answer":3,"image":""},{"id":"md4-108-2-26","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"108年第2次第26題","year":108,"session":2,"number":26,"question":"白血病患童，若白血球數目高於十萬時，屬腫瘤急症，可能會併發各種問題，下列何項最不會出現？","options":["(A) 高尿酸血症（Hyperuricemia）","(B) 血栓形成（Thrombosis）","(C) 腹瀉（Diarrhea）","(D) 缺氧（Hypoxia）"],"answer":2,"image":""},{"id":"md4-108-2-27","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"108年第2次第27題","year":108,"session":2,"number":27,"question":"凝血酶原時間（Prothrombin time, PT）延長，但活化部分凝血活酶時間（activated partial thromboplastin time, aPTT）正常，最常是因為下列那一因子缺乏所造成？","options":["(A) Factor 8","(B) Factor 9","(C) Factor 7","(D) Factor 11"],"answer":2,"image":""},{"id":"md4-108-2-28","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第2次第28題","year":108,"session":2,"number":28,"question":"有關常見無害心雜音（Innocent murmur）的敘述，下列何者錯誤？","options":["(A) 心雜音強度通常低於第三度","(B) 坐姿比平躺時，雜音較明顯","(C) 心雜音強度會隨著呼吸改變","(D) 雜音常在收縮期，且為共振音或樂音（Vibratory or musical murmur）"],"answer":1,"image":""},{"id":"md4-108-2-29","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第2次第29題","year":108,"session":2,"number":29,"question":"治療發紺性先天性心臟病常用的外科Blalock-Taussig分流術式（Blalock-Taussig shunt），主要是連接下列那二條血管，以達到改善缺氧的效果？","options":["(A) 鎖骨下動脈和同側肺靜脈（Subclavian artery and pulmonary vein of the same side）","(B) 升主動脈和肺動脈（Ascending aorta and main pulmonary artery）","(C) 頸動脈和同側肺動脈（Carotid artery and subclavian artery of the same side）","(D) 鎖骨下動脈和同側肺動脈（Subclavian artery and pulmonary artery of the same side）"],"answer":3,"image":""},{"id":"md4-108-2-30","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第2次第30題","year":108,"session":2,"number":30,"question":"有關兒童感染性心內膜炎（Infective endocarditis）臨床表徵的敘述，下列何者錯誤？","options":["(A) 病童可能是先天性心臟病的患者，或是有放置中央靜脈導管（Central venous catheter）的患者","(B) 病童有呼吸喘，夜間盜汗，體重下降的症狀","(C) 病童身體檢查有脾臟腫大，或是出現Roth spots等栓塞性現象（Embolic phenomena）","(D) 病童的實驗室檢查常有白血球低下（Leukopenia）或蛋白尿（Proteinuria）現象"],"answer":3,"image":""},{"id":"md4-108-2-31","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"108年第2次第31題","year":108,"session":2,"number":31,"question":"4歲男孩，因走路容易跌倒及爬樓梯有困難而就診，而且無法很順利的由椅子站起來，需要雙手幫忙，抽血發現血中CK（Creatine kinase）濃度為18,000 IU/L，過去史顯示3歲以前發展里程碑是正常的，本病例最可能的診斷是：","options":["(A) Charcot-Marie-Tooth disease","(B) Duchenne muscular dystrophy","(C) Myotonic dystrophy","(D) Spinal muscular atrophy"],"answer":1,"image":""},{"id":"md4-108-2-32","subject":"md4","topic":"兒科-內分泌遺傳","meta":"108年第2次第32題","year":108,"session":2,"number":32,"question":"下列有關苯酮尿症（Phenylketonuria）的敘述，何者正確？","options":["(A) 為體染色體顯性遺傳模式，主要為Phenylalanine hydroxylase（PAH）或Tetrahydrobiopterin（BH4）defect所造成","(B) 典型的苯酮尿症患者，出現發展遲緩，嘔吐，皮膚毛髮顏色變淡等症狀","(C) 為避免智力受損，需限制苯丙胺酸（Phenylalanine）的攝食，建議維持血中苯丙胺酸在2 mg/dL以下","(D) 生育期之女性苯酮尿症（Phenylketonuria）患者，更應該嚴格控制血中苯丙胺酸（Phenylalanine）濃度，以免生出苯酮尿症之嬰兒"],"answer":1,"image":""},{"id":"md4-108-2-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"108年第2次第33題","year":108,"session":2,"number":33,"question":"有關Trisomy18（Edwards syndrome）的敘述，下列何者錯誤？","options":["(A) 容易早產","(B) 窄及外展受限的髖關節（Narrow hips with limited abduction）","(C) 經過良好治療，90%可存活至成年","(D) 存活者有嚴重的神經學發展遲緩"],"answer":2,"image":""},{"id":"md4-108-2-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"108年第2次第34題","year":108,"session":2,"number":34,"question":"45歲男性，兩年來在足背逐步形成搔癢的皮疹，如圖所示，最適合的診斷為何？","options":["(A) 急性濕疹（acute eczema）","(B) 慢性濕疹（chronic eczema）","(C) 尋常性乾癬（psoriasis vulgaris）","(D) 類澱粉症苔癬（lichen amyloidosis）"],"answer":1,"image":"md4-108-2-34.jpeg"},{"id":"md4-108-2-35","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"108年第2次第35題","year":108,"session":2,"number":35,"question":"有關外用pimecrolimus及tacrolimus的敘述，下列何者錯誤？","options":["(A) 可以用來治療異位性皮膚炎（atopic dermatitis）","(B) 容易引起皮膚萎縮的副作用","(C) 是一種calcineurin inhibitor","(D) 會抑制T cell的活化"],"answer":1,"image":""},{"id":"md4-108-2-36","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"108年第2次第36題","year":108,"session":2,"number":36,"question":"40歲男性，從小就發現軀幹皮膚出現多發性色素斑及腫瘤，如圖所示，最可能的診斷為：","options":["(A) tuberous sclerosis","(B) neurofibromatosis","(C) neurocutaneous melanosis","(D) xeroderma pigmentosum"],"answer":1,"image":"md4-108-2-36.jpeg"},{"id":"md4-108-2-37","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"108年第2次第37題","year":108,"session":2,"number":37,"question":"關於異位性皮膚炎的敘述，下列何者正確？","options":["(A) 血清E型免疫球蛋白（IgE）偏低","(B) 常出現紅色皮膚劃紋症（red dermatographism）","(C) 手掌與腳掌掌紋變少（hypolinearity of palms and soles）","(D) 可合併尋常性魚鱗癬（ichthyosis vulgaris）"],"answer":3,"image":""},{"id":"md4-108-2-38","subject":"md4","topic":"皮膚-感染","meta":"108年第2次第38題","year":108,"session":2,"number":38,"question":"有關二期梅毒（secondary syphilis）的臨床表現，下列何者錯誤？","options":["(A) 不規則禿髮（moth-eaten hair loss）","(B) 軀幹皮膚出現多發性紅色斑塊（roseola syphilitica）","(C) 扁平濕疣（condylomata lata）","(D) 結節性梅毒腫（nodular gumma）"],"answer":3,"image":""},{"id":"md4-108-2-39","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"108年第2次第39題","year":108,"session":2,"number":39,"question":"20歲男性，近兩個月出現關節腫脹，間歇性發燒至39°C伴隨肌肉痠痛情形。發燒後軀幹出現鮭魚色的皮疹，全身檢查後沒有明顯的感染源，抽血檢查發現ANA(-)，rheumatoid factor (-)，ferritin > 10000 ng/ml，Anti- U1RNP (-)。最有可能為下列何種疾病？","options":["(A) 全身性紅斑性狼瘡（systemic lupus erythematosus）","(B) 風濕性關節炎（rheumatoid arthritis）","(C) 成人史迪爾氏病（adult onset Still's disease）","(D) 混合性結締組織症（mixed connective tissue disease）"],"answer":2,"image":""},{"id":"md4-108-2-40","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"108年第2次第40題","year":108,"session":2,"number":40,"question":"下列何者是亞急性皮膚紅斑性狼瘡（subacute cutaneous lupus erythematosus；SCLE）常見的皮膚表現形式？","options":["(A) malar rash與papulosquamous lesions","(B) papulosquamous與annular lesions","(C) malar rash與discoid rash","(D) discoid rash與annular lesions"],"answer":1,"image":""},{"id":"md4-108-2-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"108年第2次第41題","year":108,"session":2,"number":41,"question":"乾癬（psoriasis）是一種常見的慢性皮膚病，下列敘述何者正確？","options":["(A) 第一型乾癬往往好發於40歲以前，與HLA遺傳形態有關，而且治療效果往往較差","(B) 乾癬患者有10~25%會併發有乾癬性關節炎","(C) 乾癬病灶處表皮細胞分泌的抗菌蛋白β-defensin 2或cathelicidin（LL37）減少，因此皮表細菌感染機會增加，容易誘發乾癬發作","(D) HIV族群中乾癬的盛行率高於一般民眾，且嚴重性較高"],"answer":1,"image":""},{"id":"md4-108-2-42","subject":"md4","topic":"皮膚-腫瘤","meta":"108年第2次第42題","year":108,"session":2,"number":42,"question":"穿耳洞後在耳垂出現逐漸長大之皮膚病灶如圖所示，下列何者為最可能的診斷？","options":["(A) 化膿性肉芽腫（pyogenic granuloma）","(B) 蟹足腫（keloid）","(C) 上皮囊腫（epidermal inclusion cyst）","(D) 皮膚纖維瘤（dermatofibroma）"],"answer":1,"image":"md4-108-2-42.jpeg"},{"id":"md4-108-2-43","subject":"md4","topic":"皮膚-腫瘤","meta":"108年第2次第43題","year":108,"session":2,"number":43,"question":"承上題，對此皮膚病灶的敘述，下列何者錯誤？","options":["(A) 手術切除是治療最佳選擇","(B) 膚色越深的人種越好發","(C) 好發於皮膚張力較大處","(D) 放射治療是治療方法之一"],"answer":0,"image":""},{"id":"md4-108-2-44","subject":"md4","topic":"神經-中風","meta":"108年第2次第44題","year":108,"session":2,"number":44,"question":"40歲男性，自2個月前開始有漸進性的右側耳鳴，此耳鳴與脈搏頻率相近，夜間會較大聲且影響其睡眠，並有右側耳後枕部頭痛。最可能的診斷為何？","options":["(A) 腦內動靜脈畸形（arteriovenous malformation）","(B) 硬腦膜靜脈竇栓塞（dural sinus thrombosis）","(C) 硬腦膜動靜脈瘻管（dural arteriovenous fistula）","(D) 腦動脈瘤（cerebral aneurysm）"],"answer":2,"image":""},{"id":"md4-108-2-45","subject":"md4","topic":"神經-中風","meta":"108年第2次第45題","year":108,"session":2,"number":45,"question":"75歲男性，有高血壓及心房顫動多年，突發右側肢體偏癱與意識混沌而送至急診。至急診的時間為症狀發生後1小時，初步的腦部CT未顯示腦出血，下列何種狀況不適合使用靜脈血栓溶解藥物（tissue plasminogen activator, tPA）治療？","options":["(A) 一週前有短暫腦缺血發作","(B) 血糖320 mg/dL","(C) 使用warfarin，INR為1.3","(D) 血壓200/120 mmHg"],"answer":3,"image":""},{"id":"md4-108-2-46","subject":"md4","topic":"神經-中風","meta":"108年第2次第46題","year":108,"session":2,"number":46,"question":"李小姐，55歲，因突發性頭痛及癲癇發作、意識障礙被同事送到急診室，其電腦斷層攝影檢查（CT）如下圖。下列敘述何者錯誤？","options":["(A) 可能診斷為蜘蛛網膜下腔出血（subarachnoid hemorrhage）","(B) 最常見之病因為腦動脈瘤（aneurysm）破裂","(C) 併發症中，可能會出現水腦症","(D) 併發症中，大腦血管痙攣（vasospasm）通常比再出血（rebleeding）早發生"],"answer":3,"image":"md4-108-2-46.jpeg"},{"id":"md4-108-2-47","subject":"md4","topic":"神經-中風","meta":"108年第2次第47題","year":108,"session":2,"number":47,"question":"李先生，45歲，患有偏頭痛（migraine），無高血壓、糖尿病病史，因腦梗塞住院。他的父親及弟弟也有腦梗塞病史，弟弟除腦梗塞外，也有失智症（dementia）。下列敘述何者最正確？","options":["(A) 腦影像檢查顯示有水腦症","(B) 合併有多發性神經病變（polyneuropathy）","(C) 可以做NOTCH3基因分析檢查","(D) 偏頭痛為診斷此疾病之必要條件"],"answer":2,"image":""},{"id":"md4-108-2-48","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"108年第2次第48題","year":108,"session":2,"number":48,"question":"關於癲癇手術（epilepsy surgery）的敘述，下列何者錯誤？","options":["(A) Rasmussen encephalitis以半邊大腦切除術（hemispherectomy）為主","(B) 失張發作（atonic seizure）以胼胝體切斷術（corpus callosotomy）為主","(C) 兒童失神性癲癇（childhood absence epilepsy）以迷走神經刺激術（vagus nerve stimulation）為主","(D) 內側顳葉硬化症（medial temporal sclerosis）以顳葉切除術（temporal lobectomy）或杏仁體–海馬迴切除術（amygdalohippocampectomy）為主"],"answer":2,"image":""},{"id":"md4-108-2-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"108年第2次第49題","year":108,"session":2,"number":49,"question":"關於睡眠呼吸中止症（sleep apnea）的敘述，下列何者錯誤？","options":["(A) 在中樞型睡眠呼吸中止症（central sleep apnea），橫膈膜及其他呼吸肌肉的運動中斷，空氣停止進出呼吸道","(B) 以阻塞型睡眠呼吸中止症（obstructive sleep apnea）最為常見","(C) 在阻塞型睡眠呼吸中止症（obstructive sleep apnea）的治療上，可利用各種不同形式的口腔矯正器，或懸壅垂軟顎咽整形手術（uvulopalatopharyngoplasty）、扁桃腺切除術、鼻部手術等","(D) 給與輕鎮靜劑、安眠藥、肌肉鬆弛劑或抗焦慮等藥物為睡眠呼吸中止症首選之治療方法"],"answer":3,"image":""},{"id":"md4-108-2-50","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"108年第2次第50題","year":108,"session":2,"number":50,"question":"抗癲癇藥物在患者的血液中達到穩定濃度（steady state concentrations）的時間通常是此藥物半衰期的幾倍？","options":["(A) 二","(B) 三","(C) 四","(D) 五"],"answer":3,"image":""},{"id":"md4-108-2-51","subject":"md4","topic":"神經-失智退化運動障礙","meta":"108年第2次第51題","year":108,"session":2,"number":51,"question":"85歲老太太身體一向硬朗，行動自如，女兒從美國回來，與老太太共眠。半夜，老太太醒來，問床邊人：妳是誰？同住家人表示，這幾個月來，老太太常常找不到物品放在何處。到菜市場買菜，常常買回來冰箱已堆滿的相同食材。這位老太太最可能得了何種病？","options":["(A) Alzheimer disease","(B) dementia with Lewy bodies","(C) Parkinson disease with dementia","(D) vascular dementia"],"answer":0,"image":""},{"id":"md4-108-2-52","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"108年第2次第52題","year":108,"session":2,"number":52,"question":"下列何者與神經性梅毒（neurosyphilis）較無關？","options":["(A) tabes dorsalis","(B) general paresis","(C) Marcus-Gunn pupils","(D) lancinating or lightning pains"],"answer":2,"image":""},{"id":"md4-108-2-53","subject":"md4","topic":"神經-失智退化運動障礙","meta":"108年第2次第53題","year":108,"session":2,"number":53,"question":"62歲的老師上課中突然變得怪異，重複問同樣的問題。他的意識清楚、手腳靈活，最近沒有頭部外傷。被送到鄰近醫院檢查，6小時後，逐漸恢復正常，但是對過去幾個小時完全沒有記憶。他最有可能的情況為：","options":["(A) 暫時性失憶症（transient global amnesia）","(B) 阿茲海默症（Alzheimer disease）","(C) 額顳葉失智症（frontotemporal dementia）","(D) 枕葉癲癇發作（occipital seizure）"],"answer":0,"image":""},{"id":"md4-108-2-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"108年第2次第54題","year":108,"session":2,"number":54,"question":"下列關於顱神經病變之敘述，何者錯誤？","options":["(A) 類固醇治療有助於貝爾氏顏面神經麻痺（Bell’s palsy）","(B) 瞳孔反射正常為糖尿病性動眼神經病變的特色","(C) 頭部外傷導致複視最常見之顱神經病變為外展神經","(D) 三叉神經痛最少侵犯第一分支"],"answer":2,"image":""},{"id":"md4-108-2-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"108年第2次第55題","year":108,"session":2,"number":55,"question":"下列何者為最常見之遺傳性運動感覺神經病變（inherited motor-sensory neuropathies）？","options":["(A) Charcot-Marie-Tooth 1A（CMT1A）","(B) Charcot-Marie-Tooth 2A（CMT2A）","(C) Charcot-Marie-Tooth X（CMTX）","(D) Charcot-Marie-Tooth 2D（CMT2D）"],"answer":0,"image":""},{"id":"md4-108-2-56","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"108年第2次第56題","year":108,"session":2,"number":56,"question":"52歲男性主訴雙手漸進性肌肉萎縮及無力，之後伴隨言語及吞嚥困難，神經學檢查發現舌頭及手腳肌肉萎縮、肌束震顫（fasciculation）和深部肌腱反射增強，但感覺系統並無異常。下列何者為最可能之診斷？","options":["(A) 肌萎縮性側索硬化（amyotrophic lateral sclerosis）","(B) 多發性硬化症（multiple sclerosis）","(C) 多發性神經病變（polyneuropathy）","(D) 肌肉性失養症（muscular dystrophy）"],"answer":0,"image":""},{"id":"md4-108-2-57","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"108年第2次第57題","year":108,"session":2,"number":57,"question":"有關普利昂病（prion disease）腦組織病理變化的特點，下列何者錯誤？","options":["(A) 海綿樣病變（spongiform change）","(B) 明顯的發炎性細胞浸潤","(C) 免疫細胞化學反應（immunocytochemistry）可見普利昂蛋白（prion protein）沉積物","(D) 神經元細胞數量減少且合併星狀膠質細胞增生（astrocytosis）"],"answer":1,"image":""},{"id":"md4-108-2-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"108年第2次第58題","year":108,"session":2,"number":58,"question":"下列有關急性散發性腦脊髓炎（acute disseminated encephalomyelitis, ADEM）的敘述，何者錯誤？","options":["(A) 肇因於病毒感染後或疫苗接種後誘發的自體免疫疾病","(B) 很容易復發","(C) 若有嚴重大腦傷害，死亡率高","(D) 病理變化以髓鞘（myelin）的破壞為主"],"answer":1,"image":""},{"id":"md4-108-2-59","subject":"md4","topic":"精神-精神病","meta":"108年第2次第59題","year":108,"session":2,"number":59,"question":"使用抗精神病藥（antipsychotics）引起錐體外症候群（extrapyramidal syndrome）的症狀，下列何者最有可能造成呼吸困難？","options":["(A) 肌張力異常（dystonia）","(B) 靜坐不能（akathisia）","(C) 帕金森氏症候群（parkinsonism）","(D) 運動異常（dyskinesia）"],"answer":0,"image":""},{"id":"md4-108-2-60","subject":"md4","topic":"精神-器質性與物質使用","meta":"108年第2次第60題","year":108,"session":2,"number":60,"question":"有關糖尿病與精神疾病的關聯性，下列何者錯誤？","options":["(A) 許多抗精神病藥物的長期服用可能引發糖尿病","(B) 與糖尿病共病之憂鬱症其致病機轉及治療原則與無生理疾病共病的憂鬱症類似","(C) 心理壓力、挫折、孤獨等高壓力情境時常會造成飲食控制的改變，進而影響到血糖的控制","(D) 低血糖可能造成焦慮、意識混亂、行為混亂等症狀"],"answer":1,"image":""},{"id":"md4-108-2-61","subject":"md4","topic":"精神-精神病","meta":"108年第2次第61題","year":108,"session":2,"number":61,"question":"有關思覺失調症（schizophrenia）之敘述，何者正確？","options":["(A) 少有淡漠（blunted）或不適切（inappropriate）的情緒","(B) 在罹患此症多年後才開始出現負性症狀（negative symptoms）","(C) 連結鬆散（loosening of association）是思考型式（thought form）的症狀","(D) 最常見之兩種幻覺為聽幻覺和觸幻覺"],"answer":2,"image":""},{"id":"md4-108-2-62","subject":"md4","topic":"精神-器質性與物質使用","meta":"108年第2次第62題","year":108,"session":2,"number":62,"question":"有關甲狀腺功能低下（hypothyroidism）與精神疾病的關聯性，下列何者錯誤？","options":["(A) 針對甲狀腺功能低下所引發的精神症狀，應該一開始就使用高劑量的抗精神病藥物","(B) 甲狀腺功能低下可能引發認知障礙","(C) 甲狀腺功能低下可能是難治型憂鬱症(treatment refractory depression)的原因之一","(D) 甲狀腺功能低下可能引發憂鬱情緒"],"answer":0,"image":""},{"id":"md4-108-2-63","subject":"md4","topic":"精神-精神病","meta":"108年第2次第63題","year":108,"session":2,"number":63,"question":"34歲的吳先生因多話，三天三夜沒睡，覺得自己能力很好可以選總統，一個月花了50萬買電視購物的產品，被家人送至急診室，醫師診斷為躁症發作（manic episode），此時不應給予何種藥物？","options":["(A) fluoxetine","(B) olanzapine","(C) lithium","(D) aripiprazole"],"answer":0,"image":""},{"id":"md4-108-2-64","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"108年第2次第64題","year":108,"session":2,"number":64,"question":"失眠的病人需要處方安眠藥時，下列那些衛教或處置最恰當？","options":["(A) 處方安眠藥時，宜確定排除睡眠呼吸中止症候群","(B) 睡前喝酒有助於提升安眠藥的療效","(C) 在晚餐後仍可以飲用可樂、熱可可及巧克力","(D) 因前一天睡不好，中午想補眠時卻睡不著，可服用短效安眠藥"],"answer":0,"image":""},{"id":"md4-108-2-65","subject":"md4","topic":"精神-精神官能症","meta":"108年第2次第65題","year":108,"session":2,"number":65,"question":"有關γ-aminobutyric acid（GABA）receptor complex的描述何者錯誤？","options":["(A) Zolpidem的作用機轉與GABA receptor complex有關","(B) 與抗焦慮效果相關","(C) Buspirone可以結合上GABA receptor complex","(D) 與抑制效果相關"],"answer":2,"image":""},{"id":"md4-108-2-66","subject":"md4","topic":"精神-器質性與物質使用","meta":"108年第2次第66題","year":108,"session":2,"number":66,"question":"強力膠因含有那種物質導致常被吸食濫用？","options":["(A) 甲苯","(B) 乙醚","(C) 甲醇","(D) 甲醛"],"answer":0,"image":""},{"id":"md4-108-2-67","subject":"md4","topic":"精神-精神病","meta":"108年第2次第67題","year":108,"session":2,"number":67,"question":"相似測驗（similarity testing）及成語測驗最常用來檢測：","options":["(A) 記憶力（memory）","(B) 抽象思考（abstract thinking）","(C) 判斷力（judgment）","(D) 定向力（orientation）"],"answer":1,"image":""},{"id":"md4-108-2-68","subject":"md4","topic":"精神-器質性與物質使用","meta":"108年第2次第68題","year":108,"session":2,"number":68,"question":"下列何者少見於鴉片類物質過量（opioid overdose）？","options":["(A) 瞳孔縮小","(B) 反應變差（unresponsiveness）","(C) 呼吸抑制（respiratory depression）","(D) 體溫升高"],"answer":3,"image":""},{"id":"md4-108-2-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"108年第2次第69題","year":108,"session":2,"number":69,"question":"對酒精相關疾患的描述，何者錯誤？","options":["(A) 酒精戒斷時會心跳變慢","(B) 酒精戒斷時會冒汗","(C) 長期使用酒精時會低血鈉","(D) 酒精戒斷時會誘發譫妄，是高風險病症"],"answer":0,"image":""},{"id":"md4-108-2-70","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"108年第2次第70題","year":108,"session":2,"number":70,"question":"罹患注意力缺損／過動症的兒童進入青少年和成年期之變化，下列何者錯誤？","options":["(A) 約有半數以上的兒童症狀會延續至成年","(B) 造成症狀持續的危險因子有家族史、心理社會壓力、合併行為規範障礙或情緒焦慮疾患","(C) 過動情形常變得更嚴重","(D) 可能出現社交困難或偏差行為"],"answer":2,"image":""},{"id":"md4-108-2-71","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"108年第2次第71題","year":108,"session":2,"number":71,"question":"關於妥瑞氏症（Tourette's disorder），何者錯誤？","options":["(A) 大多數在青少年後症狀會變嚴重","(B) 常合併注意力缺損／過動疾患（attention-deficit/hyperactivity disorder）","(C) 常合併強迫症","(D) 輕度症狀不需要治療"],"answer":0,"image":""},{"id":"md4-108-2-72","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"108年第2次第72題","year":108,"session":2,"number":72,"question":"快速動眼期睡眠行為疾患（REM sleep behavior disorder）較常發生於下列那一種疾病？","options":["(A) 恐慌症","(B) 思覺失調症（schizophrenia）","(C) 帕金森氏症","(D) 雙相性疾患（bipolar disorder）"],"answer":2,"image":""},{"id":"md4-108-2-73","subject":"md4","topic":"精神-精神官能症","meta":"108年第2次第73題","year":108,"session":2,"number":73,"question":"關於慮病症（hypochondriasis）的敘述，何者正確？","options":["(A) 低社經階層之患者預後較佳","(B) 個案治療後改善率極佳，90%以上能痊癒","(C) 常伴隨憂鬱或焦慮相關疾患","(D) 病程較少超過6個月"],"answer":2,"image":""},{"id":"md4-108-2-74","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第2次第74題","year":108,"session":2,"number":74,"question":"足月產新生兒因呼吸急促住進新生兒加護病房，胸腹部Ｘ光如附圖，則最可能的診斷為下列何者？","options":["(A) 橫膈疝脫（diaphragmatic hernia）","(B) 左側氣胸","(C) 胎便吸入（meconium aspiration）","(D) 右肋膜積液"],"answer":[0,1,2,3],"image":"md4-108-2-74.jpeg","answer_note":"送分:第74題一律給分。 (原公告答案 A)"},{"id":"md4-108-2-75","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"108年第2次第75題","year":108,"session":2,"number":75,"question":"50歲男性患者，主訴左側肢體無力已經二個星期，接受磁振造影檢查，圖A是注射顯影劑後的T1加權影像，圖B是擴散加權影像（diffusion-weighted image），下列何者是最可能的診斷？","options":["(A) 多型性神經膠母細胞瘤（glioblastoma）","(B) 細菌性膿瘍（pyogenic abscess）","(C) 轉移（metastasis）","(D) 多發性硬化症（multiple sclerosis）"],"answer":1,"image":"md4-108-2-75.jpeg"},{"id":"md4-108-2-76","subject":"md4","topic":"兒科-心血管呼吸","meta":"108年第2次第76題","year":108,"session":2,"number":76,"question":"下列先天性兒童心臟病臨床表現，何者比較不會以發紺（cyanosis）表現？","options":["(A) PDA（patent ductus arteriosus）","(B) TOF（tetralogy of Fallot）","(C) TGV（transposition of the great vessels）","(D) TA（truncus arteriosus）"],"answer":0,"image":""},{"id":"md4-108-2-77","subject":"md4","topic":"神經-中風","meta":"108年第2次第77題","year":108,"session":2,"number":77,"question":"33歲健康女性，突發劇烈頭痛及暈厥（syncope），病人清醒後有頭痛、嘔吐及頸部酸痛現象，此時最優先的檢查為何？","options":["(A) 不打顯影劑的腦部電腦斷層","(B) 打顯影劑的腦部電腦斷層","(C) 打顯影劑的腦部磁振造影","(D) 血管攝影"],"answer":0,"image":""},{"id":"md4-108-2-78","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"108年第2次第78題","year":108,"session":2,"number":78,"question":"一位50歲男性，過去並無特殊病史，突然發生癲癇大發作5分鐘，送入急診時又發作一次約3分鐘，現已停止，目前意識不清楚，下列何者為不適當的處置？","options":["(A) 維持呼吸道暢通","(B) 安排頭部電腦斷層掃描","(C) 給予phenytoin治療","(D) 給予benzodiazepine治療"],"answer":3,"image":""},{"id":"md4-108-2-79","subject":"md4","topic":"醫學倫理與法規","meta":"108年第2次第79題","year":108,"session":2,"number":79,"question":"14歲的小鐘因出生時發生周產期窒息，導致腦部嚴重受傷，對外界的反應只是少許的身體扭動及喉頭模糊不清的聲音，十幾年來此種狀況無明顯改變。他的父母因年老無法再照顧他，3年前將他遷入重殘機構照顧。兩天前於鼻胃管餵食後數小時出現呼吸急促現象，機構特約醫師給予口服藥物治療後情況仍未改善，機構護理人員緊急將他送到醫院，你在急診室為他做相關的檢查，發現他兩側嚴重肺炎，血液氣體分析顯示嚴重呼吸衰竭，需緊急做氣管插管使用呼吸器。但無法聯繫上他的父母，而小鐘的情況於使用氧氣及鼻式正壓裝置後未見改善，且出現低血壓現象，此時下列那一種作法最為恰當？","options":["(A) 持續聯繫他的父母及繼續目前的治療，但不插管","(B) 請送小鐘來的機構護理人員做決定","(C) 打電話給機構負責人請他做決定","(D) 依照你的專業判斷給他做氣管插管及使用呼吸器"],"answer":3,"image":""},{"id":"md4-108-2-80","subject":"md4","topic":"醫學倫理與法規","meta":"108年第2次第80題","year":108,"session":2,"number":80,"question":"保護病人隱私是由來已久的醫學倫理傳統，但在例外的情形下，醫師有主動通報的義務。依照我國醫療法規定，醫師遇有下列那些情形，應該主動向主管機關通報？①病人可能是受虐兒童②病人可能罹患法定傳染病③病人可能涉及保險詐欺④病人可能是警政機關通緝的犯人","options":["(A) 僅①③④","(B) 僅①②④","(C) 僅①②","(D) 僅②"],"answer":2,"image":""},{"id":"md4-109-1-1","subject":"md4","topic":"兒科-感染神經","meta":"109年第1次第1題","year":109,"session":1,"number":1,"question":"1歲女童高燒3天並有輕微咳嗽，懸壅垂與舌顎交界處（Uvulopalatoglossal junction）有紅色小斑或出血點（Nagayama spots），第4天開始出現紅疹後不再發燒，同時出現輕微腹瀉，此女童最可能是被下列何種病原體感染？","options":["(A) 麻疹病毒（Measles）","(B) 呼吸道融合病毒（Respiratory syncytial virus）","(C) 人類疱疹病毒第六型（Human Herpesviruses 6）","(D) 輪狀病毒（Rotavirus）"],"answer":2,"image":""},{"id":"md4-109-1-2","subject":"md4","topic":"兒科-感染神經","meta":"109年第1次第2題","year":109,"session":1,"number":2,"question":"下列有關傳染性單核球增多症（Infectious mononucleosis）Epstein-Barr virus感染的敘述，何者最為正確？","options":["(A) 3歲以下的患者常有典型的疲倦、咽喉炎及淋巴結腫大","(B) 90%以上患者會有抽筋或步態不穩等神經學症狀，因此治療要以類固醇為主","(C) 若使用Ampicillin常會引起皮疹","(D) 主要感染的淋巴球是T淋巴球"],"answer":2,"image":""},{"id":"md4-109-1-3","subject":"md4","topic":"兒科-感染神經","meta":"109年第1次第3題","year":109,"session":1,"number":3,"question":"3歲女童發燒2天、喉嚨痛、流口水、胃口不佳，口腔前部無異常、後咽壁有潰瘍，且合併有手掌腳掌皮疹。最可能的診斷是：","options":["(A) 疱疹性齒齦口腔炎（Herpetic gingivostomatitis）","(B) 手足口症（Hand-foot-and-mouth disease）","(C) 德國麻疹（Rubella）","(D) 水痘（Chickenpox）"],"answer":1,"image":""},{"id":"md4-109-1-4","subject":"md4","topic":"兒科-心血管呼吸","meta":"109年第1次第4題","year":109,"session":1,"number":4,"question":"對於肺炎黴漿菌（Mycoplasma pneumoniae）感染的描述，下列何者錯誤？","options":["(A) 是學齡兒童社區性肺炎的常見病原","(B) 肺外病徵包括腦炎、關節炎和皮疹","(C) 潛伏期2～3週，家庭內傳染性高","(D) 正確診斷主要靠痰液和血液培養"],"answer":3,"image":""},{"id":"md4-109-1-5","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"109年第1次第5題","year":109,"session":1,"number":5,"question":"下列何種疫苗為口服劑型？","options":["(A) A型肝炎疫苗（Hepatitis A vaccine）","(B) 輪狀病毒疫苗（Rotavirus vaccine）","(C) 卡介苗（BCG vaccine）","(D) 水痘疫苗（Varicella vaccine）"],"answer":1,"image":""},{"id":"md4-109-1-6","subject":"md4","topic":"兒科-心血管呼吸","meta":"109年第1次第6題","year":109,"session":1,"number":6,"question":"有關哮吼（Croup）的描述，下列何者最正確？","options":["(A) 哮吼是以細菌感染為主","(B) 通常會有喘息聲（Wheezing）","(C) 其臨床呼吸道症狀為聲門下方或聲帶處的軟組織水腫所致","(D) 哭鬧可協助患者維持充足的換氣動作，所以不必刻意安撫"],"answer":2,"image":""},{"id":"md4-109-1-7","subject":"md4","topic":"兒科-感染神經","meta":"109年第1次第7題","year":109,"session":1,"number":7,"question":"21天大的新生兒發高燒，被醫師懷疑為細菌性腦膜炎，下列那一個症狀最不常見？","options":["(A) 黃疸","(B) 躁動哭鬧","(C) 頸部僵硬","(D) 活動力不佳"],"answer":2,"image":""},{"id":"md4-109-1-8","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"109年第1次第8題","year":109,"session":1,"number":8,"question":"一位妊娠週數40週、出生體重3,500公克的新生兒，其出生之後的體重變化，下列何者最不正常？","options":["(A) 滿24小時體重為3,400公克","(B) 滿48小時體重是3,400公克","(C) 滿3天體重是3,100公克","(D) 滿5天體重是3,200公克"],"answer":2,"image":""},{"id":"md4-109-1-9","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"109年第1次第9題","year":109,"session":1,"number":9,"question":"一個新生兒出生後第5分鐘時呈現心跳每分鐘75次、呼吸緩慢不規則、全身發紺（Cyanosis）、上肢體有些微彎曲但下肢體軟趴、對抽痰刺激僅有皺眉反應。根據你的評估Apgar score是幾分？","options":["(A) 2","(B) 4","(C) 6","(D) 8"],"answer":1,"image":""},{"id":"md4-109-1-10","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"109年第1次第10題","year":109,"session":1,"number":10,"question":"新生兒出生後即發現肌肉張力不佳無哭聲，經保溫、擦乾、清除口鼻分泌物與重新擺位後，心跳仍每分鐘40次且無自發性呼吸。接下來何種處置最為恰當？","options":["(A) 給與自由流量氧氣","(B) 以甦醒球做正壓換氣","(C) 開始胸外按壓心臟","(D) 先評估Apgar score再決定下一步動作"],"answer":1,"image":""},{"id":"md4-109-1-11","subject":"md4","topic":"兒科-消化系統疾病","meta":"109年第1次第11題","year":109,"session":1,"number":11,"question":"下列何種疾病或原因所導致的黃疸，以直接型高膽紅素血症（Conjugated hyperbilirubinemia）為主？","options":["(A) ABO血型不合溶血（ABO incompatibility hemolysis）","(B) 溶血性尿毒症（Hemolytic-uremic syndrome）","(C) Alagille症候群（Alagille syndrome）","(D) Gilbert症候群（Gilbert syndrome）"],"answer":2,"image":""},{"id":"md4-109-1-12","subject":"md4","topic":"兒科-消化系統疾病","meta":"109年第1次第12題","year":109,"session":1,"number":12,"question":"下列何種腹瀉（Diarrhea）的機制是屬於Secretory type diarrhea？","options":["(A) 先天性氯化物性腹瀉（Congenital chloride diarrhea）","(B) 乳糖耐受不良腹瀉（Lactase deficiency）","(C) 腸躁症（Irritable bowel syndrome）","(D) 乳糜瀉（Celiac disease）"],"answer":0,"image":""},{"id":"md4-109-1-13","subject":"md4","topic":"兒科-消化系統疾病","meta":"109年第1次第13題","year":109,"session":1,"number":13,"question":"下列何種疾病較不會導致Hydrops of the gallbladder？","options":["(A) 川崎氏症（Kawasaki disease）","(B) 鏈球菌咽喉炎（Streptococcal pharyngitis）","(C) 過敏性紫斑症（Henoch-Schönlein purpura）","(D) 囊狀纖維化（Cystic fibrosis）"],"answer":3,"image":""},{"id":"md4-109-1-14","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"109年第1次第14題","year":109,"session":1,"number":14,"question":"下列有關如何培養嬰幼兒及兒童良好飲食習慣的敘述，何者最為適當？","options":["(A) 2歲半到3歲之間為黃金訓練期","(B) 3歲後可以開始規定一些簡單的餐桌禮儀","(C) 2至4歲可以使用脫脂鮮奶","(D) 少喝含糖飲料，補充水分以稀釋果汁為宜"],"answer":1,"image":""},{"id":"md4-109-1-15","subject":"md4","topic":"兒科-消化系統疾病","meta":"109年第1次第15題","year":109,"session":1,"number":15,"question":"在兒童便秘的病史或身體評估時發現紅旗（Red-flags）徵象時，應積極診斷有無器質性病變。下列現象何者不屬於紅旗徵象？","options":["(A) 出生後48小時未排出胎便（Delayed meconium passage）","(B) 糞便有潛血反應（Occult blood in stool）","(C) 生長遲緩（Failure to thrive）","(D) 直腸檢查有糞便（Stool in rectum）"],"answer":3,"image":""},{"id":"md4-109-1-16","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"109年第1次第16題","year":109,"session":1,"number":16,"question":"10歲女童突發四肢無力至急診。血壓100/60 mmHg，血液檢查：肌酸酐（Creatinine）0.6 mg/dL，鉀離子為2.2 mmol/L，鈉離子為138 mmol/L，氯離子為96 mmol/L，鎂離子為1.3 mg/dL（正常值為1.6～2.4 mg/dL），血中 - pH值為7.56，重碳酸根離子（HCO3）為30 mmol/L。尿鈣與尿肌酸酐比值（Urine Ca/Cr）為0.1，女童最可能的診斷為：","options":["(A) 第一型腎小管酸血症（Renal tubular acidosis, type I）","(B) 吉特曼症候群（Gitelman syndrome）","(C) Bartter氏症候群（Bartter syndrome）","(D) Fanconi症候群（Fanconi syndrome）"],"answer":1,"image":""},{"id":"md4-109-1-17","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"109年第1次第17題","year":109,"session":1,"number":17,"question":"6個月大男嬰因泌尿道感染合併敗血症，之後安排VCUG（Voiding cystourethrogram）檢查結果如附圖。下列敘述何者錯誤？","options":["(A) 要進一步做鎝-99m-DMSA腎皮質掃描","(B) 要考慮是因膀胱異常導致的次發性（Secondary）膀胱輸尿管逆流","(C) 要立即接受手術矯正治療","(D) 要排除病人是否有合併Sacral agenesis, occult spinal dysraphism"],"answer":2,"image":"md4-109-1-17.jpeg"},{"id":"md4-109-1-18","subject":"md4","topic":"兒科-感染神經","meta":"109年第1次第18題","year":109,"session":1,"number":18,"question":"關於熱性痙攣之發生原因及處置，下列何項敘述較不適當？","options":["(A) 常與嬰兒玫瑰疹（人類疱疹病毒第六型感染）有關","(B) 若病患精神活力不佳，須排除中樞神經感染","(C) 腦波檢查為單純熱性痙攣之常規檢查","(D) 若意識持續未恢復，須檢驗血糖以鑑別低血糖之昏迷"],"answer":2,"image":""},{"id":"md4-109-1-19","subject":"md4","topic":"兒科-內分泌遺傳","meta":"109年第1次第19題","year":109,"session":1,"number":19,"question":"生長激素注射用於促進身高的效果，於下列何種疾病有最多的實證醫學證據支持，且同時符合美國FDA及臺灣健保給付標準？","options":["(A) 透納氏症（Turner syndrome）","(B) CATCH 22症候群（CATCH 22 syndrome）","(C) 性聯遺傳低血磷佝僂症（X-linked hypophosphatemic rickets）","(D) 中樞性性早熟（Central precocious puberty）"],"answer":0,"image":""},{"id":"md4-109-1-20","subject":"md4","topic":"兒科-內分泌遺傳","meta":"109年第1次第20題","year":109,"session":1,"number":20,"question":"兒童佝僂症（Rickets）常因體內鈣磷代謝異常所導致，下列那一項致病機轉所造成的佝僂症與其他最不相同？","options":["(A) 慢性腎臟病（Chronic kidney disease）","(B) 低血磷佝僂症（Hypophosphatemic rickets）","(C) 腸胃吸收障礙（Malabsorption）","(D) 營養不良致維生素D缺乏（Nutritional vitamin D deficiency）"],"answer":1,"image":""},{"id":"md4-109-1-21","subject":"md4","topic":"兒科-感染神經","meta":"109年第1次第21題","year":109,"session":1,"number":21,"question":"下列有關川崎氏症（Kawasaki disease）的臨床表現敘述，何者最為正確？","options":["(A) 即使未治療，通常會高燒3天後退燒","(B) 淋巴腺腫大多為雙側且小於0.5mm","(C) 眼睛紅，多為單側且有膿樣分泌物","(D) 手、腳的脫皮多在症狀開始後2～3星期出現"],"answer":3,"image":""},{"id":"md4-109-1-22","subject":"md4","topic":"兒科-心血管呼吸","meta":"109年第1次第22題","year":109,"session":1,"number":22,"question":"診斷4歲孩童氣喘，下列何者為最主要的診斷方式？","options":["(A) 病史詢問","(B) 抽血檢查Total IgE","(C) 肺功能測試","(D) 皮膚過敏測試"],"answer":0,"image":""},{"id":"md4-109-1-23","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"109年第1次第23題","year":109,"session":1,"number":23,"question":"10歲孩童參加喜宴，忽然覺得呼吸困難、眼睛四周及口唇血管水腫、同時全身癢及吞嚥困難，立即轉送至急診室，下列何者是最適合的立即性處置？","options":["(A) 注射腎上腺素（Epinephrine）","(B) 注射類固醇","(C) 使用升壓劑，如Dopamine","(D) 使用抗組織胺"],"answer":0,"image":""},{"id":"md4-109-1-24","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"109年第1次第24題","year":109,"session":1,"number":24,"question":"有關預防嬰幼兒過敏的觀念，下列敘述何者最不恰當？","options":["(A) 孕婦飲食不需避免高過敏食物（例如海鮮、花生等）","(B) 建議在4～6個月大可開始添加副食品","(C) 母乳哺育對於預防氣喘的效果不確定","(D) 按照國際指引建議嬰幼兒常規性使用益生菌來預防過敏"],"answer":3,"image":""},{"id":"md4-109-1-25","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"109年第1次第25題","year":109,"session":1,"number":25,"question":"有關急性骨髓性白血病（AML）的描述，下列何者最正確？","options":["(A) 整體而言，AML五年存活率比急性淋巴性白血病（ALL）佳","(B) 為Down syndrome 1～3歲時，最常見之白血病","(C) 發生率是急性淋巴性白血病（ALL）的3倍","(D) 使用干擾素、Hydroxyurea及Ara-c的組合，治癒率與移植相同"],"answer":1,"image":""},{"id":"md4-109-1-26","subject":"md4","topic":"兒科-心血管呼吸","meta":"109年第1次第26題","year":109,"session":1,"number":26,"question":"6歲大的兒童因為突然暈倒被送到醫院，心電圖顯示如圖，心跳頻率約為200/min。病童的血壓經測量為50/25 mmHg，可以摸到微弱的脈搏但週邊循環不佳，接下來應做的處置為何？","options":["(A) 靜脈快速給與Adenosine治療","(B) 使用冰袋輕輕壓迫前額（Valsalva maneuver）","(C) 使用同步整流術（Synchronized DC cardioversion）治療","(D) 靜脈給與Amiodarone治療"],"answer":2,"image":"md4-109-1-26.jpeg"},{"id":"md4-109-1-27","subject":"md4","topic":"兒科-心血管呼吸","meta":"109年第1次第27題","year":109,"session":1,"number":27,"question":"下列何種心音比較不會出現在心房中膈缺損（Atrial septal defect, ASD）的病患？","options":["(A) 寬且固定的第二心音分裂（Wide and fixed splitting of second heart sound）","(B) 左側第二肋間出現噴射性收縮期的心雜音（Ejection systolic murmur）","(C) 左下胸骨邊緣出現中期舒張期的心雜音（Mid-diastolic murmur）","(D) 巨大且分裂的第一心音（Loud and splitting of first heart sound）"],"answer":3,"image":""},{"id":"md4-109-1-28","subject":"md4","topic":"兒科-心血管呼吸","meta":"109年第1次第28題","year":109,"session":1,"number":28,"question":"關於膜邊型的心室中膈缺損（Perimembranous type ventricular septal defect），下列敘述何者錯誤？","options":["(A) 此類缺損在心室中膈缺損各種分型中最常見，即使在東方人亦是如此","(B) 此類缺損不太可能會自行癒合，而且在各型的心室中膈缺損中，日後會造成主動脈瓣脫垂（Aortic cusp prolapse）的機率最高","(C) 此類缺損不屬於感染性心內膜炎（Infective endocarditis）之高風險族群","(D) 若因過多左向右分流而造成明顯的肺高壓，即使臨床症狀可用藥物控制，仍建議盡早接受手術修補"],"answer":[1,2],"image":"","answer_note":"更正:第28題答Ｂ、Ｃ給分"},{"id":"md4-109-1-29","subject":"md4","topic":"兒科-內分泌遺傳","meta":"109年第1次第29題","year":109,"session":1,"number":29,"question":"活產嬰兒約1～2%有染色體異常。下列那一個臨床情境最不需要做染色體檢查？","options":["(A) 周產期窒息導致腦性麻痺（Cerebral palsy, perinatal asphyxia induced）","(B) 多重畸形（Ｍultiple congenital anomalies）","(C) 心智障礙（Intellectual disability）","(D) 生長畸變（Growth aberration）"],"answer":0,"image":""},{"id":"md4-109-1-30","subject":"md4","topic":"兒科-內分泌遺傳","meta":"109年第1次第30題","year":109,"session":1,"number":30,"question":"大多數先天性代謝異常疾病（Inborn errors of metabolism）的遺傳模式（Mode of inheritance）為Autosomal recessive，下列何種代謝異常除外？","options":["(A) Phenylketonuria（PKU）","(B) Ornithine transcarbamylase deficiency（OTC deficiency）","(C) Methylmalonic acidemia（MMA）","(D) Maple syrup urine disease（MSUD）"],"answer":1,"image":""},{"id":"md4-109-1-31","subject":"md4","topic":"兒科-內分泌遺傳","meta":"109年第1次第31題","year":109,"session":1,"number":31,"question":"下列家族譜系最有可能為何種遺傳模式？","options":["(A) Mitochondrial inheritance","(B) Autosomal recessive inheritance","(C) X-linked recessive inheritance","(D) Autosomal dominant inheritance"],"answer":0,"image":"md4-109-1-31.jpeg"},{"id":"md4-109-1-32","subject":"md4","topic":"兒科-內分泌遺傳","meta":"109年第1次第32題","year":109,"session":1,"number":32,"question":"3歲男童因過度肥胖而就診，出生時的基本新生兒篩檢無異常，亦無新生兒低張力的過去病史。家族史無特殊肥胖體質。身體診察發現手腳皆有軸後多指（趾）症（post-axial polydactyly）、外生殖器短小發育不良、眼底呈現色素病變，此男童最有可能患有下列何種疾病？","options":["(A) Bardet-Biedl syndrome","(B) Noonan syndrome","(C) Prader-Willi syndrome","(D) Williams syndrome"],"answer":0,"image":""},{"id":"md4-109-1-33","subject":"md4","topic":"醫學倫理與法規","meta":"109年第1次第33題","year":109,"session":1,"number":33,"question":"下列何種情形不符合立即通報兒少保護小組之條件？","options":["(A) 有超過3次以上急診外傷就醫紀錄且檢查結果與受傷機制不符","(B) 病史前後不一致且延遲就醫","(C) 低處（小於150公分）跌落以致骨折","(D) 2歲以上兒童之單一手部骨折"],"answer":3,"image":""},{"id":"md4-109-1-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"109年第1次第34題","year":109,"session":1,"number":34,"question":"56歲男性，於冬季寒流來臨時，雙側小腿出現如圖所示會癢之皮膚病變。下列何種處置最不適當？","options":["(A) 鼓勵患者多洗澡","(B) 塗抹類固醇","(C) 提高室內濕度","(D) 使用潤膚劑"],"answer":0,"image":"md4-109-1-34.jpeg"},{"id":"md4-109-1-35","subject":"md4","topic":"皮膚-感染","meta":"109年第1次第35題","year":109,"session":1,"number":35,"question":"80歲老先生住在安養院，皮膚有一些丘疹，經皮膚科醫師診斷確定為疥瘡，下列敘述何者正確？","options":["(A) 有一無疥瘡病史的朋友，在探望老先生後第二天開始覺得全身發癢，其得到疥瘡機會很高","(B) 頭部是疥蟲好犯的部位","(C) 當疥蟲離開人體後，數個小時內就死亡","(D) 鏡檢下，若只看到蟲卵或排泄物而不見蟲體，也可以確定是疥瘡感染"],"answer":3,"image":""},{"id":"md4-109-1-36","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"109年第1次第36題","year":109,"session":1,"number":36,"question":"有關白色糠疹（pityriasis alba）的敘述，下列何者錯誤？","options":["(A) 出現白色脫屑斑","(B) 常見於臉上","(C) 好發於小孩","(D) 患者即使成年後，多數病變仍不易痊癒"],"answer":3,"image":""},{"id":"md4-109-1-37","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"109年第1次第37題","year":109,"session":1,"number":37,"question":"關於乾癬（psoriasis）的敘述，下列何者正確？","options":["(A) 白種人罹患乾癬的比例比華人低","(B) Köebner phenomenon只見於這個疾病","(C) 部分患者會有家族史","(D) 不會造成指甲及關節病變"],"answer":2,"image":""},{"id":"md4-109-1-38","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"109年第1次第38題","year":109,"session":1,"number":38,"question":"關於異位性皮膚炎（atopic dermatitis）致病機轉的敘述，下列何者錯誤？","options":["(A) FLG基因突變使filaggrin的製造減少","(B) 可觀察到皮膚生理功能（包括經皮水分散失及含水量）異常","(C) 病人的皮膚免疫系統缺陷，因此易合併細菌感染","(D) 慢性期的病理機轉主要以Th2細胞的活化為主要之角色，Th1細胞角色較少"],"answer":3,"image":""},{"id":"md4-109-1-39","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"109年第1次第39題","year":109,"session":1,"number":39,"question":"關於Sturge-Weber syndrome之敘述，下列何者錯誤？","options":["(A) 顏面三叉神經支配區皮膚有酒色斑（port-wine stain）","(B) 酒色斑是惡性的血管瘤","(C) 病患可能併發癲癇","(D) 可能出現青光眼"],"answer":1,"image":""},{"id":"md4-109-1-40","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"109年第1次第40題","year":109,"session":1,"number":40,"question":"皮膚病灶的臨床及病理的發現如圖所示，胸部X片發現有雙側肺門淋巴結腫大，下列何者為最可能的皮膚疾病？","options":["(A) 類肉芽腫（sarcoidosis）","(B) 結核病（tuberculosis）","(C) 皮膚T細胞淋巴癌（cutaneous T cell lymphoma）","(D) 卡波希氏肉瘤（Kaposi's sarcoma）"],"answer":0,"image":"md4-109-1-40.jpeg"},{"id":"md4-109-1-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"109年第1次第41題","year":109,"session":1,"number":41,"question":"下列何種自體抗體為Sjögren's syndrome特異性標示抗體？","options":["(A) 抗SSB/La抗體","(B) 抗U1-RNP抗體","(C) 抗Jo-1抗體","(D) 抗Scl-70抗體"],"answer":0,"image":""},{"id":"md4-109-1-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"109年第1次第42題","year":109,"session":1,"number":42,"question":"下列何者為慢性紅斑性狼瘡（chronic cutaneous lupus erythematosus）的特徵？","options":["(A) 最常見的臨床表現狼瘡性脂肪炎（lupus panniculitis）","(B) 凍瘡型紅斑性狼瘡（chilblain lupus erythematosus）好發於冬季低溫季節，常發生在軀幹部位","(C) 典型的圓盤型紅斑性狼瘡（classic discoid lupus erythematosus）病人大約只有5%最後會演變成全身型紅斑性狼瘡（systemic lupus erythematosus）","(D) 肥厚型紅斑性狼瘡（hypertrophic discoid lupus erythematosus）是因為真皮有黏液素（mucin）沉積，才造成肥厚外觀"],"answer":2,"image":""},{"id":"md4-109-1-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"109年第1次第43題","year":109,"session":1,"number":43,"question":"24歲女性在臉部、頸部出現脫色病灶，如圖所示，關於此病的敘述，下列何者錯誤？","options":["(A) 此病症可能出現Koebner phenomenon","(B) 此病症可能造成病人社會適應困難","(C) 病灶內的黑色素細胞雖存在，但無法有效製造黑色素顆粒","(D) 波長308 nm之準分子光治療（excimer phototherapy）有效"],"answer":2,"image":"md4-109-1-43.jpeg"},{"id":"md4-109-1-44","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"109年第1次第44題","year":109,"session":1,"number":44,"question":"下列何者非治療重症肌無力症之正確方式?","options":["(A) 抗膽鹼脂藥物（anticholinesterase drugs）","(B) 類固醇藥物（corticosteroid）","(C) 胸腺切除術（thymectomy）","(D) 病人感染時使用aminoglycoside藥物"],"answer":3,"image":""},{"id":"md4-109-1-45","subject":"md4","topic":"神經-中風","meta":"109年第1次第45題","year":109,"session":1,"number":45,"question":"48歲男性罹患高血壓多年，沒有規則服藥。在工作中，突然感覺右臂、右腿及右臉麻木（numbness），但沒有明顯的無力（weakness），最可能的病灶位置（lesion site）在何處？","options":["(A) 右側丘腦（right thalamus）","(B) 左側丘腦（left thalamus）","(C) 右側中央溝前側腦迴（right precentral gyrus）","(D) 左側中央溝前側腦迴（left precentral gyrus）"],"answer":1,"image":""},{"id":"md4-109-1-46","subject":"md4","topic":"神經-中風","meta":"109年第1次第46題","year":109,"session":1,"number":46,"question":"磁振造影（MRI）在臨床運用中，對於接近大腦皮質（cortical）或是腦室（ventricle）旁的腦部梗塞，下列何種序列（sequences）可提供最高敏感度將病灶突顯出來？","options":["(A) T1-weighted imaging","(B) T2-weighted imaging","(C) fluid-attenuated inversion recovery（FLAIR）imaging","(D) susceptibility-weighted imaging（SWI）"],"answer":2,"image":""},{"id":"md4-109-1-47","subject":"md4","topic":"神經-中風","meta":"109年第1次第47題","year":109,"session":1,"number":47,"question":"因腦中風造成閉鎖症候群（locked-in syndrome），下列何者為最常見的原因？","options":["(A) 內頸動脈阻塞（internal carotid artery occlusion）","(B) 基底動脈阻塞（basilar artery occlusion）","(C) 小血管梗塞（small-vessel infarction）","(D) 心房顫動造成心因性血栓（cardiac emboli）"],"answer":1,"image":""},{"id":"md4-109-1-48","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"109年第1次第48題","year":109,"session":1,"number":48,"question":"有關顳葉癲癇（temporal lobe epilepsy）的敘述，下列何者錯誤？","options":["(A) 是成人最常見的癲癇症候群（epilepsy syndrome）","(B) 癲癇發生區（epileptogenic region）通常和外側顳葉結構（lateral temporal lobe structures）有關","(C) 對藥物反應不佳的病人可接受顳葉切除術，大約一半的病人可以在一年後達到癲癇不發作（seizure free）的療效","(D) 海馬回硬化（hippocampus sclerosis）是顳葉癲癇主要病因之一"],"answer":1,"image":""},{"id":"md4-109-1-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"109年第1次第49題","year":109,"session":1,"number":49,"question":"下列對於癲癇診斷分類何者正確？","options":["(A) 失神性發作（absence seizures）常常會有先兆（aura），並且時間常常超過5分鐘以上","(B) 肌攣性發作（myoclonic seizures）以快速而短暫的肌肉收縮與躍動為主要表現","(C) 肌攣性發作（myoclonic seizures）主要影響四肢（limbs），並不會影響軀幹（trunk）","(D) 失張力性發作（atonic seizures）往往在強直–陣攣性發作（tonic-clonic seizure）後發生"],"answer":1,"image":""},{"id":"md4-109-1-50","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"109年第1次第50題","year":109,"session":1,"number":50,"question":"36歲男性，主訴近2年每年冬天都有持續2個月，在後眼窩劇烈疼痛，固定每晚發作，且時間約15分鐘到3小時不等，每次痛起來都會有單側流淚和眼睛紅的情形。此病人最可能的診斷是：","options":["(A) 偏頭痛（migraine）","(B) 叢發性頭痛（cluster headache）","(C) 緊張性頭痛（tension-type headache）","(D) 三叉神經痛（trigeminal neuralgia）"],"answer":1,"image":""},{"id":"md4-109-1-51","subject":"md4","topic":"神經-失智退化運動障礙","meta":"109年第1次第51題","year":109,"session":1,"number":51,"question":"關於亨丁頓舞蹈症（Huntington disease）之敘述，下列何者錯誤？","options":["(A) 可能在動作症狀出現前15年，便能看到尾核（caudate nucleus）萎縮","(B) 隨著病程的進行，舞蹈症（chorea）的嚴重程度會逐漸加重","(C) 認知功能的退化，主要在執行功能（executive function）","(D) 年輕發病的病人可能以巴金森症候群（parkinsonism）表現"],"answer":1,"image":""},{"id":"md4-109-1-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"109年第1次第52題","year":109,"session":1,"number":52,"question":"一位52歲男性因為重複問一樣的問題被送來急診，該病人過去有偏頭痛之病史，最近並無外傷病史。身體檢查發現此患者仍有警覺性及對人的定向感，注意力、遠程記憶（remote memory）及語言功能都還正常，常規之實驗室檢查結果都正常。該患者7小時後，症狀自然緩解。最可能的診斷是：","options":["(A) 短暫性全面腦失憶（transient global amnesia）","(B) 基底偏頭痛（basilar migraine）","(C) 失智症（dementia）","(D) 癲癇發作後意識混亂（postictal confusion）"],"answer":0,"image":""},{"id":"md4-109-1-53","subject":"md4","topic":"神經-失智退化運動障礙","meta":"109年第1次第53題","year":109,"session":1,"number":53,"question":"巴金森氏病人服用左多巴（levodopa）者，會比服用多巴胺促效劑（dopamine agonist）者容易出現下列何種副作用？","options":["(A) 異動症（dyskinesia）","(B) 肢體水腫","(C) 幻覺（hallucination）","(D) 衝動控制失調（impulse control disorder）"],"answer":0,"image":""},{"id":"md4-109-1-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"109年第1次第54題","year":109,"session":1,"number":54,"question":"關於肌強直營養不良（myotonic dystrophy），下列敘述何者錯誤？","options":["(A) 自體顯性遺傳","(B) 以近端無力為主，常見複視","(C) 經常合併多系統疾病，例如白內障、糖尿病、心律不整等","(D) 血液中的肌肉酵素一般是正常或輕微上升"],"answer":1,"image":""},{"id":"md4-109-1-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"109年第1次第55題","year":109,"session":1,"number":55,"question":"下列有關馬尾症候群（cauda equina syndrome）的敘述，何者正確？","options":["(A) 以上運動神經元（upper motor neuron）表徵為主","(B) 通常臨床症狀是左右兩側對稱","(C) 深部肌腱反射增強","(D) 球海綿體肌反射（bulbocavernosus reflex）消失"],"answer":3,"image":""},{"id":"md4-109-1-56","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"109年第1次第56題","year":109,"session":1,"number":56,"question":"下列分泌何種荷爾蒙的腦下垂體腺瘤（hormone-secreting pituitary adenoma），可以考慮服用多巴胺促效劑（dopamine agonist）治療？","options":["(A) 促甲狀腺激素（thyroid-stimulating hormone, TSH）","(B) 促腎上腺皮質激素（adrenocorticotropic hormone, ACTH）","(C) 泌乳激素（prolactin）","(D) 生長激素（growth hormone）"],"answer":2,"image":""},{"id":"md4-109-1-57","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"109年第1次第57題","year":109,"session":1,"number":57,"question":"42歲男性，沒有糖尿病及慢性器官衰竭病史；15天前曾有2天腹瀉，緊接著雙腳腳底有麻刺感，逐漸轉為麻木，沿著腳底一路麻到膝蓋，也發現兩側小腿的肌肉鬆垮及力量減弱，雙手使用筷子及扭瓶蓋的動作也變困難。下列有關病患的診斷臆測，何者最為正確？","options":["(A) 右側中大腦動脈的大面積中風","(B) 遺傳性運動及感覺神經病變","(C) 陳舊性的脊髓白質病變後遺症","(D) 急性的周邊神經病變"],"answer":3,"image":""},{"id":"md4-109-1-58","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"109年第1次第58題","year":109,"session":1,"number":58,"question":"承上題，若在急診處，下列何種項目是最不需要的檢查？","options":["(A) 腰椎穿刺（lumbar puncture）","(B) 神經傳導及肌電圖檢查","(C) 緊急安排骨頭掃描（bone scan）","(D) 監測血氧濃度及肺活量（vital capacity）"],"answer":2,"image":""},{"id":"md4-109-1-59","subject":"md4","topic":"精神-精神病","meta":"109年第1次第59題","year":109,"session":1,"number":59,"question":"下列何者是思覺失調症（schizophrenia）預後較佳之預測因子？","options":["(A) 年輕發病","(B) 有情感性疾患（mood disorders）家族史","(C) 沒有促發因子（precipitating factor）","(D) 有思覺失調症家族史"],"answer":1,"image":""},{"id":"md4-109-1-60","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"109年第1次第60題","year":109,"session":1,"number":60,"question":"關於不寧腿症候群（restless leg syndrome），下列何者錯誤？","options":["(A) 可能於懷孕期間出現","(B) 可能與缺鐵性貧血有關","(C) 睡前飲酒有助於緩解不寧腿症候群之症狀","(D) Ropinirole（Requip）是一種多巴胺致效劑（dopamine agonist），可用來治療此症"],"answer":2,"image":""},{"id":"md4-109-1-61","subject":"md4","topic":"精神-精神病","meta":"109年第1次第61題","year":109,"session":1,"number":61,"question":"思覺失調症（schizophrenia）的病人長期追蹤約有多少比率會自殺死亡？","options":["(A) 1～3%","(B) 10～13%","(C) 25～30%","(D) 40～50%"],"answer":1,"image":""},{"id":"md4-109-1-62","subject":"md4","topic":"精神-器質性與物質使用","meta":"109年第1次第62題","year":109,"session":1,"number":62,"question":"關於譫妄（delirium），下列敘述何者錯誤？","options":["(A) 抗精神病長效針劑是治療譫妄之首選藥物之一","(B) 年齡大於70歲的患者為譫妄的高危險群","(C) 譫妄是一個臨床整體預後不佳的指標","(D) 譫妄的核心症狀包含了意識狀態的障礙及認知、知覺的改變"],"answer":0,"image":""},{"id":"md4-109-1-63","subject":"md4","topic":"精神-精神官能症","meta":"109年第1次第63題","year":109,"session":1,"number":63,"question":"下列何者不是選擇性血清素再吸收抑制劑（SSRI）的副作用？","options":["(A) 血糖急速上升","(B) 噁心","(C) 性功能障礙","(D) 睡眠障礙"],"answer":0,"image":""},{"id":"md4-109-1-64","subject":"md4","topic":"精神-精神官能症","meta":"109年第1次第64題","year":109,"session":1,"number":64,"question":"有關身體形象畏懼症（body dysmorphic disorder）的敘述，下列何者錯誤？","options":["(A) 以手術或醫學美容醫療介入可以有效地減緩病情","(B) 患者對身體常見不滿意部位包含鼻子及頭髪","(C) 常見的精神科共病包含重鬱症與強迫症","(D) 藥物治療身體形象畏懼症以抗憂鬱劑治療為主"],"answer":0,"image":""},{"id":"md4-109-1-65","subject":"md4","topic":"精神-精神官能症","meta":"109年第1次第65題","year":109,"session":1,"number":65,"question":"有關急性壓力疾患（acute stress disorder）及創傷後壓力症候群（posttraumatic stress disorder）之敘述，下列何者錯誤？","options":["(A) 急性壓力疾患之症狀若超過一個月以上則需考慮診斷可能為創傷後壓力症候群","(B) 創傷後壓力症候群治療合併藥物治療及心理治療是有助益的","(C) 急性壓力疾患之症狀中不會出現解離症狀","(D) 創傷後壓力症候群的病因包含hypothalamic-pituitary-adrenal（HPA）axis之功能失調"],"answer":2,"image":""},{"id":"md4-109-1-66","subject":"md4","topic":"精神-器質性與物質使用","meta":"109年第1次第66題","year":109,"session":1,"number":66,"question":"一位35歲男性卡車司機，一向身體健康，這2年來因須開長途夜車而吸食安非他命，最近兩週產生明顯之聽幻覺及被害妄想、易躁動（agitation）且易怒而打傷同事，下列何者錯誤？","options":["(A) 宜停止使用安非他命","(B) 可短期使用抗精神病劑，如haloperidol","(C) 若難以照顧時，可先肢體約束以降低傷人自傷風險，然須密切觀察","(D) 若有憂鬱症狀，可給予情緒穩定劑，如carbamazepine"],"answer":3,"image":""},{"id":"md4-109-1-67","subject":"md4","topic":"精神-器質性與物質使用","meta":"109年第1次第67題","year":109,"session":1,"number":67,"question":"虛談（confabulation）代表個案最可能有下列何種精神障礙？","options":["(A) 思考（thought）障礙","(B) 情緒（emotion）障礙","(C) 記憶（memory）障礙","(D) 語言（language）障礙"],"answer":2,"image":""},{"id":"md4-109-1-68","subject":"md4","topic":"精神-器質性與物質使用","meta":"109年第1次第68題","year":109,"session":1,"number":68,"question":"咖啡因（caffeine）的戒斷症狀，下列何者正確？","options":["(A) 戒斷症狀常於咖啡停止一星期後發生","(B) 最常見症狀包括頭痛、倦怠","(C) 常見症狀包括幻聽、妄想","(D) 戒斷症狀的嚴重度與咖啡因的使用量無關"],"answer":1,"image":""},{"id":"md4-109-1-69","subject":"md4","topic":"兒科-感染神經","meta":"109年第1次第69題","year":109,"session":1,"number":69,"question":"對於注意力缺損／過動症的診斷標準，下列何者錯誤？","options":["(A) 至少有部分過動、衝動難控制、注意力不集中的症狀在7歲之前即已出現","(B) 只要有部分症狀在一個情境中出現就算","(C) 症狀必須造成明顯的社交、學業或工作功能的損害","(D) 必須和廣泛性發展障礙（pervasive developmental disorder）、思覺失調症（schizophrenia）、其他精神病態、情緒疾患、焦慮症、解離症、人格疾患作區辨"],"answer":[0,1],"image":"","answer_note":"更正:第69題答Ａ、Ｂ給分。"},{"id":"md4-109-1-70","subject":"md4","topic":"兒科-感染神經","meta":"109年第1次第70題","year":109,"session":1,"number":70,"question":"關於兒童青少年妥瑞氏症（Tourette's disorder），下列敘述何者正確？","options":["(A) 只要出現動作抽動（motor tics）或聲帶型抽動（vocal tics）其中一種即可診斷為妥瑞氏症","(B) 只要長大成年後都會痊癒","(C) 同卵雙胞胎手足和異卵雙胞胎手足同時罹患妥瑞氏症的機會相同","(D) 作用在多巴胺接受器拮抗作用的抗精神藥物對於妥瑞氏症具有療效"],"answer":3,"image":""},{"id":"md4-109-1-71","subject":"md4","topic":"精神-精神病","meta":"109年第1次第71題","year":109,"session":1,"number":71,"question":"下列那種藥物，臨床上通常並不需要定期抽血監測該種藥物之血中濃度？","options":["(A) clozapine","(B) lithium","(C) valproic acid","(D) carbamazepine"],"answer":0,"image":""},{"id":"md4-109-1-72","subject":"md4","topic":"精神-精神官能症","meta":"109年第1次第72題","year":109,"session":1,"number":72,"question":"有關經前症候群（premenstrual syndrome）症狀，下列何者不常見？","options":["(A) 憂鬱（depression）","(B) 焦慮（anxiety）","(C) 熱潮紅（hot flashes）","(D) 腹脹（abdominal bloating）"],"answer":2,"image":""},{"id":"md4-109-1-73","subject":"md4","topic":"精神-精神官能症","meta":"109年第1次第73題","year":109,"session":1,"number":73,"question":"關於轉化症（conversion disorder〔functional neurological symptom disorder〕）的敘述，何者錯誤？","options":["(A) 常見於戲劇型人格（histrionic personality disorder）","(B) 癱瘓（paralysis）、視盲（blindness）、不語（mutism）是最常見的症狀","(C) 在男性患者中，與反社會型人格障礙症（antisocial personality disorder）相關","(D) 最佳的治療方式為告知患者其症狀是想像出來的"],"answer":3,"image":""},{"id":"md4-109-1-74","subject":"md4","topic":"兒科-心血管呼吸","meta":"109年第1次第74題","year":109,"session":1,"number":74,"question":"下圖為一孩童之胸部X光素片，最可能的診斷為：","options":["(A) 肺隔離症（pulmonary sequestration）","(B) 氣胸（pneumothorax）","(C) 大葉性肺炎（lobar pneumonia）","(D) 肺支氣管發育不良（bronchopulmonary dysplasia）"],"answer":3,"image":"md4-109-1-74.jpeg"},{"id":"md4-109-1-75","subject":"md4","topic":"神經-中風","meta":"109年第1次第75題","year":109,"session":1,"number":75,"question":"一位22歲女性，因左頂葉出血，接受腦部血管攝影檢查如圖，診斷是？","options":["(A) 動靜脈畸形（arteriovenous malformation）","(B) 靜脈畸形（venous malformation）","(C) 靜脈竇栓塞（sinus thrombosis）","(D) 海綿狀血管瘤（cavernous hemangioma）"],"answer":0,"image":"md4-109-1-75.jpeg"},{"id":"md4-109-1-76","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"109年第1次第76題","year":109,"session":1,"number":76,"question":"一位8歲兒童被熱水燙傷手臂，紅腫起水泡，非常疼痛，他最有可能為第幾度灼傷？","options":["(A) 一度","(B) 二度","(C) 三度","(D) 四度"],"answer":1,"image":""},{"id":"md4-109-1-77","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"109年第1次第77題","year":109,"session":1,"number":77,"question":"一位75歲男性，沒有糖尿病，但雙下肢皆有靜脈曲張（varicose vein），下肢水腫的情形有多年，至急診主訴雙下肢癢和紅腫，並有傷口癒合不良的情形，如圖，下列敘述何者錯誤？","options":["(A) 懷疑是stasis dermatitis","(B) 這是周邊動脈阻塞疾病（peripheral arterial occlusion disease, PAOD）的臨床徵候","(C) 若合併感染，則需使用抗生素","(D) 病患平常需使用彈性襪，並將下肢抬高以減少下肢的靜脈高壓（venous hypertension）"],"answer":1,"image":"md4-109-1-77.jpeg"},{"id":"md4-109-1-78","subject":"md4","topic":"精神-器質性與物質使用","meta":"109年第1次第78題","year":109,"session":1,"number":78,"question":"在急診治療酒精戒斷（alcohol withdrawal）時，下列何者治療最不適當？","options":["(A) phenobarbital","(B) magnesium sulfate","(C) lorazepam","(D) thiamine"],"answer":0,"image":""},{"id":"md4-109-1-79","subject":"md4","topic":"醫學倫理與法規","meta":"109年第1次第79題","year":109,"session":1,"number":79,"question":"下列何者是比較符合病人自願（voluntariness）之醫療介入方式？","options":["(A) 焦慮症（anxiety disorder）病人A長期接受醫師P之診治，非常信任醫師P，遵照醫師P認為正確的方式進行治療","(B) 醫師P建議慢性思覺失調症患者S之家屬，可以增加病人零用錢之方式，來勸誘S定期服藥","(C) 醫師P擔心慢性思覺失調症患者B女不願服用抗精神病藥物，並未對B女說明長期用藥可能導致體重增加之效果","(D) 醫師P對躁症患者M說：「如果妳不答應自願住院，我就將妳強制住院。」M終於簽了自願住院同意書"],"answer":0,"image":""},{"id":"md4-109-1-80","subject":"md4","topic":"醫學倫理與法規","meta":"109年第1次第80題","year":109,"session":1,"number":80,"question":"老王是退休的單身男性，78歲，有心臟病、高血壓、糖尿病，只有間斷服藥，在一家工廠擔任倉庫管理員，最近一年半來走路容易跌倒，因此住院檢查，發現罹患了小腦萎縮症，醫師也告之此病症的預後不佳，因此曾拜託老闆，如果有什麼重病突發時，不要再急救。他並且留下書面的不予急救（DNR）意願書。某日晚上，在大門值班時突然昏迷，緊急送往醫院急救，發現有左前腦及中腦動脈阻塞之大片梗塞，又病人的實驗室檢查發現有慢性腎功能衰竭，宜進行透析治療。病人在急診處呼吸逐漸不規則，血中二氧化碳分壓升高。如果不施行氣管插管，可能危及生命，則下列的處理何者最適切？","options":["(A) 請工廠負責人代為簽署同意書，進行氣管插管，因醫師以救命為第一職責","(B) 請醫院之警衛或社工人員當見證人簽同意書，進行氣管插管，因醫師以救命為第一職責","(C) 直接進行氣管插管，並安排腹膜透析","(D) 只進行一般之支持療法，但不安排透析，也不進行氣管插管，以尊重病人的意願"],"answer":3,"image":""},{"id":"md4-109-2-1","subject":"md4","topic":"兒科-感染神經","meta":"109年第2次第1題","year":109,"session":2,"number":1,"question":"下列何種傳染病，在病好隔了數年後，病毒可能會再度活化而出現帶狀疱疹？","options":["(A) 麻疹（Measles）","(B) 德國麻疹（Rubella）","(C) 腮腺炎（Mumps）","(D) 水痘（Varicella）"],"answer":3,"image":""},{"id":"md4-109-2-2","subject":"md4","topic":"皮膚-感染","meta":"109年第2次第2題","year":109,"session":2,"number":2,"question":"4歲男童，因為喉嚨痛及發燒，服用抗生素2星期後，仍持續發燒並出現臨床表徵，如圖所示。下列何者為最可能的診斷？","options":["(A) Scarlet fever","(B) Stevens-Johnson syndrome","(C) Roseola infantum","(D) Erythema multiforme"],"answer":[1,3],"image":"md4-109-2-2.jpeg","answer_note":"更正:第2題答Ｂ、Ｄ給分"},{"id":"md4-109-2-3","subject":"md4","topic":"兒科-感染神經","meta":"109年第2次第3題","year":109,"session":2,"number":3,"question":"關於新生兒感染巨細胞病毒（Cytomegalovirus）的敘述，下列何者錯誤？","options":["(A) 血清陽性（Seropositive）的媽媽哺餵乳汁，新生兒感染巨細胞病毒的機率為60～70%","(B) 先天性巨細胞病毒感染的新生兒，約有90%會有臨床症狀","(C) 臨床症狀包括肝脾腫大、黃疸、出疹（Petechiae、Purpura）等","(D) 任何沒有通過聽力篩檢的新生兒，都須考慮先天性巨細胞病毒感染之可能性"],"answer":1,"image":""},{"id":"md4-109-2-4","subject":"md4","topic":"兒科-心血管呼吸","meta":"109年第2次第4題","year":109,"session":2,"number":4,"question":"治療黴漿菌（Mycoplasma pneumoniae）肺炎，下列何種藥物最適當？","options":["(A) Penicillin","(B) Vancomycin","(C) Azithromycin","(D) Gentamicin"],"answer":2,"image":""},{"id":"md4-109-2-5","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"109年第2次第5題","year":109,"session":2,"number":5,"question":"新生女嬰為妊娠38周出生、體重4,400 gm，母親有妊娠糖尿病病史。此女嬰在出生24小時內，最有可能發生的臨床症狀？","options":["(A) 早發性黃疸","(B) 低血糖","(C) 貧血","(D) 高血鈣"],"answer":1,"image":""},{"id":"md4-109-2-6","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"109年第2次第6題","year":109,"session":2,"number":6,"question":"剛出生的嬰兒身體診察發現手足發紺（acrocyanosis），下列何種是最常見的原因？","options":["(A) 胎便吸入症候群（Meconium aspiration syndrome）","(B) 先天性發紺心臟疾病（Congenital cyanotic heart disease）","(C) 體溫過熱（Hyperthermia）","(D) 周邊血液循環不良（Peripheral circulatory sluggishness）"],"answer":3,"image":""},{"id":"md4-109-2-7","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"109年第2次第7題","year":109,"session":2,"number":7,"question":"下列有關副食品添加的原則，何者最正確？","options":["(A) 多種食物可以同時導入以增加副食品接受度","(B) 餵食果汁一天至少200 c.c.以達水分需求","(C) 8個月大時應添加蜂蜜水以增加免疫能力","(D) 注意含鐵之副食品的導入以符合營養需求"],"answer":3,"image":""},{"id":"md4-109-2-8","subject":"md4","topic":"兒科-內分泌遺傳","meta":"109年第2次第8題","year":109,"session":2,"number":8,"question":"先天性腎上腺增生症（congenital adrenal hyperplasia）屬於下列何種遺傳模式？","options":["(A) Autosomal dominant","(B) Autosomal recessive","(C) X-linked dominant","(D) X-linked recessive"],"answer":1,"image":""},{"id":"md4-109-2-9","subject":"md4","topic":"兒科-消化系統疾病","meta":"109年第2次第9題","year":109,"session":2,"number":9,"question":"3個月大的女嬰，體重5.8公斤，純母乳哺育。最近常出現血便，但沒有發燒，體力、精神、食慾都很好。大便除帶血絲外無特殊變化。下列敘述何者最為正確？","options":["(A) 以母乳哺育之嬰兒也會因母親喝牛奶而發生牛奶蛋白過敏（cow's milk protein allergy）","(B) 因為沒發燒所以不可能是罹患細菌性大腸炎（bacterial colitis）","(C) 可能是塵蟎過敏，驗血檢查過敏原是最標準的診斷方法","(D) 潰瘍性大腸炎（ulcerative colitis）機率最大，立即做大腸鏡檢查"],"answer":0,"image":""},{"id":"md4-109-2-10","subject":"md4","topic":"兒科-消化系統疾病","meta":"109年第2次第10題","year":109,"session":2,"number":10,"question":"學齡兒童急性腹痛，下列那一種最少發生背部轉移性疼痛？","options":["(A) 腸套疊（Intussusception）","(B) 胰臟炎（Pancreatitis）","(C) 腸阻塞（Intestinal obstruction）","(D) 急性闌尾炎（Appendicitis）"],"answer":0,"image":""},{"id":"md4-109-2-11","subject":"md4","topic":"兒科-消化系統疾病","meta":"109年第2次第11題","year":109,"session":2,"number":11,"question":"各種成分在小腸吸收的主要部位，下列敘述何者錯誤？","options":["(A) 葉酸（Folic acid）在十二指腸（Duodenum）與近端空腸（Proximal jejunum）","(B) 膽酸（Bile acids）在遠端迴腸（Distal ileum）","(C) 蛋白質在小腸前段100-200公分（Proximal 100-200 cm of small intestine）","(D) 鐵在遠端迴腸（Distal ileum）"],"answer":3,"image":""},{"id":"md4-109-2-12","subject":"md4","topic":"兒科-消化系統疾病","meta":"109年第2次第12題","year":109,"session":2,"number":12,"question":"關於全靜脈營養合併膽汁滯留（Total parenteral nutrition（TPN）-associated cholestasis）的敘述，下列何者錯誤？","options":["(A) 危險因子包括早產、敗血症與短腸症候群（Short bowel syndrome）","(B) 脂肪給與的形式和劑量與TPN-associated cholestasis的發生有關","(C) 典型症狀通常在接受TPN治療的一個星期內發生","(D) Ursodeoxycholic acid（UDCA）對改善黃疸可能有助益"],"answer":2,"image":""},{"id":"md4-109-2-13","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"109年第2次第13題","year":109,"session":2,"number":13,"question":"有關兒童泌尿道感染（Urinary tract infection）的危險因子，下列何者最不相關？","options":["(A) 未割包皮的男性（Uncircumcised male）","(B) 慢性便祕（Chronic constipation）","(C) 泡泡浴（Bubble bath）","(D) 膀胱輸尿管逆流（Vesicoureteral reflux）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第13題一律給分 (原公告答案 C)"},{"id":"md4-109-2-14","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"109年第2次第14題","year":109,"session":2,"number":14,"question":"下列那一項不是診斷抗利尿激素不適當分泌症候群（Syndrome of inappropriate antidiuretic hormone secretion）的排除條件？","options":["(A) 同時合併心臟、肝臟、腎臟與甲狀腺等器官的問題","(B) 尿液滲透壓（Urine osmolality）﹥100 mOsm/kg","(C) 血清滲透壓（Serum osmolality）﹤280 mOsm/kg合併血鈉值（serum sodium）﹤135 mEq/L","(D) 限水治療後無法改變低血鈉的情形"],"answer":[1,2,3],"image":"","answer_note":"更正:第14題答Ｂ、Ｃ、Ｄ給分"},{"id":"md4-109-2-15","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"109年第2次第15題","year":109,"session":2,"number":15,"question":"關於兒童血尿（Hematuria），下列敘述何者錯誤？","options":["(A) 若為急性腎絲球發炎（Acute glomerulonephritis），多半會合併高血壓的症狀","(B) 血尿若來自腎絲球發炎，則在尿液檢查中可以發現變形紅血球（Dysmorphic RBC, acanthocytes）","(C) 若血尿來自下泌尿道（Lower urinary tract）的病變，尿液為茶色（Tea-colored）或可樂顏色（Cola-colored）","(D) 細菌性泌尿道感染（Bacterial urinary tract infection）也會引起血尿"],"answer":2,"image":""},{"id":"md4-109-2-16","subject":"md4","topic":"兒科-感染神經","meta":"109年第2次第16題","year":109,"session":2,"number":16,"question":"關於Tics的敘述，下列何者錯誤？","options":["(A) Gilles de la Tourette syndrome大部分案例可能是屬於隱性遺傳","(B) Tic disorder是最常見的兒童運動異常（Movement disorder）的疾病","(C) 採用Dopamine receptor拮抗劑可以抑制Tics的行為","(D) 部分Gilles de la Tourette syndrome的病人會合併有Obsessive-compulsive的症狀"],"answer":0,"image":""},{"id":"md4-109-2-17","subject":"md4","topic":"兒科-感染神經","meta":"109年第2次第17題","year":109,"session":2,"number":17,"question":"4個月大的嬰兒，發現神智不清，送至急診，電腦斷層發現少量蜘蛛膜下腔出血（Subarachnoid hemorrhage）與嚴重腦水腫（Brain edema），眼底檢查發現視網膜出血（Retinal hemorrhage），身體診察無外傷之表現，下列何者是最可能的診斷？","options":["(A) 腦膜炎（Meningitis）","(B) 虐待性腦傷（Abusive head trauma）","(C) 腦炎（Encephalitis）","(D) 腦血管畸型（Cerebral vascular malformation）"],"answer":1,"image":""},{"id":"md4-109-2-18","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"109年第2次第18題","year":109,"session":2,"number":18,"question":"下列何者非新生兒之原始反射動作（Primitive reflexes）？","options":["(A) 手掌抓握（Palmar grasp reflex）","(B) 擁抱反射（Moro reflex）","(C) 降落傘反射（Parachute reflex）","(D) 覓乳反射（Rooting reflex）"],"answer":2,"image":""},{"id":"md4-109-2-19","subject":"md4","topic":"兒科-內分泌遺傳","meta":"109年第2次第19題","year":109,"session":2,"number":19,"question":"下列何項不是兒童接受合成生長激素（recombinant growth hormone）治療的併發症或副作用？","options":["(A) 第二型糖尿病（type 2 diabetes mellitus）","(B) 腦假瘤（pseudotumor cerebri）","(C) 庫賈氏病（Creutzfeldt-Jakob disease）","(D) 使脊柱側彎（scoliosis）惡化"],"answer":2,"image":""},{"id":"md4-109-2-20","subject":"md4","topic":"兒科-內分泌遺傳","meta":"109年第2次第20題","year":109,"session":2,"number":20,"question":"10歲女孩，瘦小，家族無糖尿病病史，最近發現有多吃多尿，尿液檢查呈現尿糖及尿酮反應，血液檢查發現高血糖，最有可能之診斷為何？","options":["(A) 小胖威利症候群（Prader-Willi syndrome）","(B) 第二型糖尿病（Type 2 diabetes）","(C) 年輕人成年型糖尿病（Maturity-onset diabetes of the young）","(D) 第一型糖尿病（Type 1 diabetes）"],"answer":3,"image":""},{"id":"md4-109-2-21","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"109年第2次第21題","year":109,"session":2,"number":21,"question":"下列有關藥物誘發狼瘡（Drug-induced lupus）的敘述，何者正確？","options":["(A) 女性的發生率高於男性","(B) 常出現抗histone抗體（Antihistone antibody）","(C) 常引起嚴重的腎炎（Nephritis）","(D) 常合併補體（Complement）下降"],"answer":1,"image":""},{"id":"md4-109-2-22","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"109年第2次第22題","year":109,"session":2,"number":22,"question":"嬰兒的皮膚、口腔、呼吸道以及腸胃道常反覆地發生細菌感染，每次感染時的抽血檢查均發現白血球非常高，臍帶很晚才掉，且有肚臍炎（Omphalitis），此病嬰最可能罹患何種疾病？","options":["(A) Bruton agammaglobulinemia","(B) 慢性肉芽腫病（Chronic granulomatous disease）","(C) 嚴重合併性免疫缺乏症（Severe combined immunodeficiency）","(D) 白血球沾黏分子缺乏症（Leukocyte adhesion deficiency）"],"answer":3,"image":""},{"id":"md4-109-2-23","subject":"md4","topic":"兒科-心血管呼吸","meta":"109年第2次第23題","year":109,"session":2,"number":23,"question":"有關氣喘（asthma）的治療，下列敘述何者錯誤？","options":["(A) 對於持續型氣喘的小朋友，建議使用吸入型類固醇（inhaled corticosteroids），作為初始的控制藥物","(B) 緩釋型茶鹼（theophylline）也可作為氣喘控制藥物","(C) 如果藥物控制良好持續3個月以上，則可以考慮降階（step down）治療","(D) 白三烯素調節劑（leukotriene-modifying agent）為目前最有效的氣喘控制藥物"],"answer":3,"image":""},{"id":"md4-109-2-24","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"109年第2次第24題","year":109,"session":2,"number":24,"question":"關於過敏性紫斑症（Henoch-Schönlein purpura）之敘述，下列何者錯誤？","options":["(A) 常發生在3～10歲之間，並且常發生於冬季及春季","(B) 紫斑（Purpura）主要出現在下肢，抽血會發現血小板低下","(C) 以支持性療法為主，大部分病人預後良好，病情大多可於4週內改善","(D) 過敏性紫斑症若有較嚴重之腸胃侵犯，可考慮給與類固醇"],"answer":1,"image":""},{"id":"md4-109-2-25","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"109年第2次第25題","year":109,"session":2,"number":25,"question":"下列何種腫瘤其最高發生機率之年紀於一歲以內？","options":["(A) Acute lymphoblastic leukemia","(B) Brain tumor","(C) Bone tumor","(D) Neuroblastoma"],"answer":3,"image":""},{"id":"md4-109-2-26","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"109年第2次第26題","year":109,"session":2,"number":26,"question":"有關重度乙型海洋性貧血（β-thalassemia major）的敘述，下列何者最不正確？","options":["(A) 通常在6個月到1歲大間，貧血會越來越嚴重而需輸血","(B) 輸血會造成鐵質沉積，最好控制在血色素7 g/dL即可","(C) 又稱為庫利氏貧血（Cooley anemia）","(D) 為自體隱性（Autosomal recessive）遺傳"],"answer":1,"image":""},{"id":"md4-109-2-27","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"109年第2次第27題","year":109,"session":2,"number":27,"question":"感染相關的噬血症候群（Infection-associated hemophagocytic syndrome），下列那一項最不支持此診斷？","options":["(A) Hypofibrinogenemia","(B) Hypertriglyceridemia","(C) Hyperferritinemia","(D) Thrombocytosis"],"answer":3,"image":""},{"id":"md4-109-2-28","subject":"md4","topic":"兒科-心血管呼吸","meta":"109年第2次第28題","year":109,"session":2,"number":28,"question":"Reverse differential cyanosis是指上肢血氧飽和度低於下肢血氧飽和度，此現象最常發現於下列何種疾病？","options":["(A) 主動脈弓截斷（Interruption of aortic arch）","(B) 開放性動脈導管（Patent ductus arteriosus）","(C) 心室中隔缺損（Ventricular septal defect）","(D) 完全大血管轉位合併開放性動脈導管（Transposition of the great arteries with patent ductus arteriosus）"],"answer":3,"image":""},{"id":"md4-109-2-29","subject":"md4","topic":"兒科-心血管呼吸","meta":"109年第2次第29題","year":109,"session":2,"number":29,"question":"下列何種兒童心臟疾病，最不會出現左心室擴大的現象？","options":["(A) 心肌炎（Myocarditis）","(B) 心室中隔缺損（Ventricular septal defect）","(C) 心房中隔缺損（Atrial septal defect）","(D) 擴張型心肌病變（Dilated cardiomyopathy）"],"answer":2,"image":""},{"id":"md4-109-2-30","subject":"md4","topic":"兒科-心血管呼吸","meta":"109年第2次第30題","year":109,"session":2,"number":30,"question":"下列何種細菌較少造成兒童感染性心內膜炎（Infective endocarditis）？","options":["(A) Group D streptococcus（enterococcus）","(B) Streptococcus sanguinis","(C) Staphylococcus aureus","(D) Streptococcus pneumoniae"],"answer":3,"image":""},{"id":"md4-109-2-31","subject":"md4","topic":"兒科-內分泌遺傳","meta":"109年第2次第31題","year":109,"session":2,"number":31,"question":"2歲女童體型特別高瘦，手腳與手指（腳趾）特別細長，關節鬆弛，有輕度漏斗胸，心臟超音波呈現二尖瓣脈脫垂及主動脈回流，下列何者為最可能之診斷？","options":["(A) Marfan syndrome","(B) Menkes syndrome","(C) Kallmann syndrome","(D) Klinefelter syndrome"],"answer":0,"image":""},{"id":"md4-109-2-32","subject":"md4","topic":"兒科-內分泌遺傳","meta":"109年第2次第32題","year":109,"session":2,"number":32,"question":"Noonan Syndrome與Turner Syndrome有許多相似的異常表徵，不包括下列何者？","options":["(A) 身材矮小（Short stature）","(B) 盾狀胸（Shield chest）","(C) 短或蹼狀頸（Short or webbed neck）","(D) 左心異常（Left-heart abnormalities）"],"answer":3,"image":""},{"id":"md4-109-2-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"109年第2次第33題","year":109,"session":2,"number":33,"question":"足月新生兒出現餵食困難、嘔吐、嗜睡，進而抽搐、昏迷。當排除肝膽腸道異常及感染或其他產傷，而發現血氨升高，且陰離子隙（anion gap）升高，則最可能為：","options":["(A) 尿素循環障礙（Urea cycle defects）","(B) 有機酸血症（Organic acidemia）","(C) 胺基酸血症（Aminoacidopathies）","(D) 半乳糖血症（Galactosemia）"],"answer":1,"image":""},{"id":"md4-109-2-34","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"109年第2次第34題","year":109,"session":2,"number":34,"question":"44歲男性，主要於頭部、肘部、膝部及小腿出現如圖所示之皮膚病變，有4年病史。最可能的診斷為何？","options":["(A) 慢性單純苔癬（lichen simplex chronicus）","(B) 蕈狀肉芽腫（mycosis fungoides）","(C) 玫瑰糠疹（pityriasis rosea）","(D) 乾癬（psoriasis vulgaris）"],"answer":3,"image":"md4-109-2-34.jpeg"},{"id":"md4-109-2-35","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"109年第2次第35題","year":109,"session":2,"number":35,"question":"關於多形性紅斑（erythema multiforme）的敘述，下列何者錯誤？","options":["(A) 病理組織檢查常見真皮纖維化","(B) 典型表徵為標靶病灶（target lesion）","(C) 部分病人和單純疱疹病毒的感染相關","(D) 發病部位可包括黏膜"],"answer":0,"image":""},{"id":"md4-109-2-36","subject":"md4","topic":"皮膚-感染","meta":"109年第2次第36題","year":109,"session":2,"number":36,"question":"下列何種疾病，不是金黃色葡萄球菌（Staphylococcus aureus）所引起？","options":["(A) 膿痂疹（impetigo）","(B) 癤（furuncle）","(C) 癰（carbuncle）","(D) 疣（wart）"],"answer":3,"image":""},{"id":"md4-109-2-37","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"109年第2次第37題","year":109,"session":2,"number":37,"question":"45歲男性，數星期內於軀幹及四肢皮膚出現許多鬆垮的水疱；這些水疱非常容易破裂並留下十分疼痛之糜爛病灶。口腔黏膜亦見有糜爛病灶，皮膚理學檢查有Nikolsky sign。將此患者病灶旁的正常皮膚切片做直接免疫螢光檢查（direct immunofluorescent test），下列何者為最可能的結果？圖一圖二圖三圖四","options":["(A) IgM沈積（附圖一）","(B) IgA沈積（附圖二）","(C) IgG沈積（附圖三）","(D) IgE沈積（附圖四）"],"answer":2,"image":"md4-109-2-37.jpeg"},{"id":"md4-109-2-38","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"109年第2次第38題","year":109,"session":2,"number":38,"question":"白斑在UVB治療後，出現以毛孔為中心的黑色小點（follicular pattern repigmentation），這些黑色素細胞來自於：","options":["(A) 表皮殘餘的黑色素細胞","(B) 真皮的黑色素細胞移行到表皮","(C) 毛囊matrix決定髮色的黑色素細胞，移行到表皮","(D) 毛囊outer root sheath的黑色素母細胞活化後，移行到表皮"],"answer":3,"image":""},{"id":"md4-109-2-39","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"109年第2次第39題","year":109,"session":2,"number":39,"question":"關於日光性角化症（actinic keratosis）的敘述，下列何者錯誤？","options":["(A) 此病為一種癌前期的病徵（precancerous or premalignant lesion）","(B) 男性較為常見","(C) 長期的紫外線曝曬是危險因子之一","(D) 若不接受治療，很可能進展為黑色素細胞癌（melanoma）"],"answer":3,"image":""},{"id":"md4-109-2-40","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"109年第2次第40題","year":109,"session":2,"number":40,"question":"關於異位性皮膚炎（atopic dermatitis）的敘述，下列何者錯誤？","options":["(A) 血清中IL-31的濃度增加和異位性皮膚炎的嚴重程度有關","(B) 病情嚴重難以控制的病人，可考慮使用口服環孢靈素（cyclosporine）治療","(C) 大部分患者可發現血液中IgE及嗜中性白血球增加","(D) 急性發作期，光照治療可有效做為輔助治療"],"answer":2,"image":""},{"id":"md4-109-2-41","subject":"md4","topic":"兒科-內分泌遺傳","meta":"109年第2次第41題","year":109,"session":2,"number":41,"question":"有關neurofibromatosis type 1（NF-1）的敘述，下列何者錯誤？","options":["(A) 自體顯性遺傳","(B) 符合NF-1診斷的café-au-lait spots病灶大小，在成年人要大於30mm","(C) pigmented hamartoma of the iris（Lisch nodules）是臨床上的重要表徵","(D) plexiform neurofibromas可能會出現惡性變化"],"answer":1,"image":""},{"id":"md4-109-2-42","subject":"md4","topic":"皮膚-腫瘤","meta":"109年第2次第42題","year":109,"session":2,"number":42,"question":"有關基底細胞癌（basal cell carcinoma）的生物特性，下列何者正確？","options":["(A) 生長緩慢、大多數進展惡化以遠端轉移為主，較少局部侵犯","(B) 神經周圍侵犯（perineural invasion）很常見","(C) 遠端轉移部位最常發生位置是腦部與肝臟","(D) 神經周圍侵犯（perineural invasion）與復發病灶、腫瘤時間長短、腫瘤大小、眼窩侵犯有關"],"answer":3,"image":""},{"id":"md4-109-2-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"109年第2次第43題","year":109,"session":2,"number":43,"question":"皮肌炎（dermatomyositis）最具診斷重要性（pathognomonic）的皮膚表現是：","options":["(A) 皮膚鈣化（calcinosis cutis）","(B) 雷諾氏現象（Raynaud phenomenon）","(C) Gottron氏徵候（Gottron's sign）","(D) 多樣性皮膚（poikiloderma）"],"answer":2,"image":""},{"id":"md4-109-2-44","subject":"md4","topic":"神經-中風","meta":"109年第2次第44題","year":109,"session":2,"number":44,"question":"頸動脈剝離（carotid dissection）最不常發生於下列何者疾病？","options":["(A) 肌纖維發育不良（fibromuscular dysplasia）","(B) 高安氏動脈炎（Takayasu arteritis）","(C) 馬凡氏症候群（Marfan syndrome）","(D) Ehlers-Danlos症候群第四型（Ehlers-Danlos syndrome type IV）"],"answer":1,"image":""},{"id":"md4-109-2-45","subject":"md4","topic":"神經-中風","meta":"109年第2次第45題","year":109,"session":2,"number":45,"question":"下列何者最不可能是腦部小血管梗塞（small-vessel infarction）所表現的中風症狀？","options":["(A) 共濟失調性偏癱（ataxic hemiparesis）","(B) 單純感覺異常（pure sensory syndrome）","(C) 半側偏盲（hemianopia）","(D) 單純半側肢體無力（pure motor hemiparesis）"],"answer":2,"image":""},{"id":"md4-109-2-46","subject":"md4","topic":"神經-中風","meta":"109年第2次第46題","year":109,"session":2,"number":46,"question":"一位70歲男性病人，有多年高血壓病史，沒有常規藥物控制。早上做晨間運動時，突然失去意識倒地不起，經119轉送急診，腦部電腦斷層掃瞄如下圖，最有可能的診斷為：","options":["(A) 腦室出血（intraventricular hemorrhage）","(B) 蜘蛛膜下腔出血（subarachnoid hemorrhage）","(C) 基底動脈阻塞（basilar artery occlusion）","(D) 內頸動脈阻塞（internal carotid artery occlusion）"],"answer":1,"image":"md4-109-2-46.jpeg"},{"id":"md4-109-2-47","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"109年第2次第47題","year":109,"session":2,"number":47,"question":"下列何者不是猝睡症（narcolepsy）的臨床症狀？","options":["(A) 日間嗜睡","(B) 猝倒症（cataplexy）","(C) 覺醒混淆症（confusional arousal）","(D) 入睡幻覺（hypnagogic hallucination）"],"answer":2,"image":""},{"id":"md4-109-2-48","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"109年第2次第48題","year":109,"session":2,"number":48,"question":"65歲女性，因左側頭痛合併全身虛弱疼痛，下列敘述何者不是顳動脈炎（temporal arteritis）之特性？","options":["(A) 好發族群：病人多大於50歲，在70～80歲達到高峰，女性略多於男性","(B) 屬腦部小型血管炎，故觸診不會在顳部摸到腫脹的動脈","(C) 其頭痛發作可伴隨視力模糊，嚴重者甚至失明","(D) 其頭痛對於類固醇反應效果良好"],"answer":1,"image":""},{"id":"md4-109-2-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"109年第2次第49題","year":109,"session":2,"number":49,"question":"28歲男性，為頑固型癲癇病人，目前已使用3種高劑量的口服抗癲癇藥物控制中，每週仍有多次短暫意識喪失，有時合併四肢抽搐，經腦部核磁共振檢查發現有雙側海馬回硬化（hippocampus sclerosis）。對此病人不建議採用下列何種外科手術治療？","options":["(A) 迷走神經刺激術（vagus nerve stimulation）","(B) 深腦刺激術（deep brain stimulation）","(C) 雙側顳葉切除（modified bilateral temporal lobectomy）","(D) 反應式神經刺激術（responsive neurostimulation）"],"answer":2,"image":""},{"id":"md4-109-2-50","subject":"md4","topic":"神經-失智退化運動障礙","meta":"109年第2次第50題","year":109,"session":2,"number":50,"question":"59歲女性，出現漸進性行動遲緩（slow motion），左側肢體動作笨拙。如果這個病人是罹患巴金森氏病（Parkinson disease），最不可能出現下列何種症狀？","options":["(A) 靜坐時，左手震顫（tremor）","(B) 走路時，左上肢擺動減少（reduced arm swing）","(C) 左側肢體出現僵硬強直（rigidity）","(D) 左側上肢出現辨距障礙（dysmetria）"],"answer":3,"image":""},{"id":"md4-109-2-51","subject":"md4","topic":"神經-失智退化運動障礙","meta":"109年第2次第51題","year":109,"session":2,"number":51,"question":"一位60歲男性因為記憶減退，時常遺失東西，被女兒懷疑有失智症（dementia）帶來門診。下列何種功能異常最能鑑別診斷出輕度認知障礙（mild cognitive impairment）和失智症？","options":["(A) 執行功能（executive function）","(B) 語言能力（language skills）","(C) 視覺空間能力（visuospatial skills）","(D) 日常生活活動（activities of daily living）"],"answer":3,"image":""},{"id":"md4-109-2-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"109年第2次第52題","year":109,"session":2,"number":52,"question":"服用下列那一種藥物之後，可能會出現兩手的顫抖，必須與本態性顫抖（essential tremor）做鑑別診斷？","options":["(A) phenytoin","(B) phenobarbital","(C) valproic acid","(D) carbamazepine"],"answer":2,"image":""},{"id":"md4-109-2-53","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"109年第2次第53題","year":109,"session":2,"number":53,"question":"60歲男性出現膀胱功能失調導致頻尿、無法憋住尿意，下肢感覺異常，包括臀部、大腿內側、雙腳及腳跟的感覺喪失，核磁共振發現有一腫瘤，此腫瘤最可能位於何處？","options":["(A) 頸椎第五節（C5）","(B) 胸椎第四節（T4）","(C) 胸椎第十節（T10）","(D) 馬尾（cauda equina）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第53題一律給分。 (原公告答案 D)"},{"id":"md4-109-2-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"109年第2次第54題","year":109,"session":2,"number":54,"question":"有關肌肉失養症（muscular dystrophy）的描述，下列何者正確？","options":["(A) 裘馨氏肌肉失養症（Duchenne muscular dystrophy）的病人常出現小腿肌肉假性肥大（pseudohypertrophy）的現象","(B) 裘馨氏肌肉失養症是體染色體隱性遺傳","(C) 貝克氏肌肉失養症（Becker muscular dystrophy）的致病基因和裘馨氏肌肉失養症的基因不同","(D) 肌強直肌肉失養症（myotonic dystrophy）並不會侵犯到顏面肌肉"],"answer":0,"image":""},{"id":"md4-109-2-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"109年第2次第55題","year":109,"session":2,"number":55,"question":"有關恰克–馬利–杜斯氏症（Charcot-Marie-Tooth disease, CMT）的敘述，下列何者正確？","options":["(A) 屬於體染色體隱性遺傳","(B) 病患會有馬蹄步空凹足（pes cavus）以及手內在肌肉（intrinsic hand muscle）萎縮","(C) 臨床表現主要為自主神經功能障礙","(D) 感覺缺失是最早出現的症狀且比肢體肌肉萎縮更明顯"],"answer":1,"image":""},{"id":"md4-109-2-56","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"109年第2次第56題","year":109,"session":2,"number":56,"question":"下列和庫賈氏症（Creutzfeldt–Jakob disease）相關的敘述，何者正確？","options":["(A) 導致庫賈氏症的普里昂蛋白（prion protein）是一種經煮沸後會消失活性的蛋白","(B) 庫賈氏症的病患臨床表徵，可包括小腦共濟失調、肌肉抽搐、關節僵硬、肢體肌肉無力，最後有嚴重失智現象","(C) SC正常人細胞的普里昂蛋白（prion protein）是以PrP的型式存在","(D) 庫賈氏症的表現和遲滯病毒（slow virus）感染的症狀相似，從感染到死亡，通常超過10年"],"answer":1,"image":""},{"id":"md4-109-2-57","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"109年第2次第57題","year":109,"session":2,"number":57,"question":"關於神經系統感染，下列敘述何者正確？","options":["(A) 結核菌腦膜炎的脊髓液外觀經常是混濁的，細胞數通常為每毫升25～500顆，以嗜中性白血球為主，脊髓液中葡萄糖量減少，但是蛋白質量增加","(B) 結核菌腦膜炎從感染到發作症狀，通常只有幾個小時","(C) 脊髓硬膜外膿腫（spinal epidural abscess）通常會有嚴重的背痛、疲倦、發燒，接著會有嚴重的神經根痛及肢體麻痺無力","(D) 脊髓硬膜外膿腫（spinal epidural abscess）不是腫瘤轉移，因此不會有敲擊痛，也不會出現Kernig徵狀（Kernig sign）"],"answer":2,"image":""},{"id":"md4-109-2-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"109年第2次第58題","year":109,"session":2,"number":58,"question":"45歲女性，為減重並避免高血壓，過去2個月只食用極度少鹽少糖的餐點，因為全身無力倦怠被送到醫院。血液生化檢查發現血中的鈉離子濃度為117 mEq/L，醫師緊急使用高濃度（3%）的食鹽水靜脈點滴補充，在6小時內血中鈉離子濃度升高到137 mEq/L，結果病人出現神經學症狀。有關低血鈉的處理及這位病人的神經學病變，下列何者正確？","options":["(A) 鈉離子濃度過低會有癲癇的危險，鈉離子補充的速度越快越濃越好","(B) 太快的鈉離子補充，容易導致橋腦中央髓鞘溶解症（central pontine myelinolysis, CPM）","(C) 臨床上橋腦中央髓鞘溶解症病人的症狀，通常在鈉離子補充2週後產生","(D) 橋腦中央髓鞘溶解症，只會發生在橋腦的白質"],"answer":1,"image":""},{"id":"md4-109-2-59","subject":"md4","topic":"精神-精神病","meta":"109年第2次第59題","year":109,"session":2,"number":59,"question":"有關思覺失調症之敘述，下列何者錯誤？","options":["(A) 抗精神病藥物的坐立不安之副作用可使用β-blockers如propranolol","(B) 使用抗精神病藥物出現錐體外徑路副作用（extrapyramidal side effects）者，也可能較有機會出現遲發性運動異常（tardive dyskinesia）","(C) 思覺失調症女性盛行率較高，約為男性兩倍，可能與賀爾蒙有關","(D) 思覺失調症之非藥物治療可包括支持性心理治療、職業復健、社交技巧訓練等，以幫助病患回復社會功能"],"answer":2,"image":""},{"id":"md4-109-2-60","subject":"md4","topic":"精神-精神病","meta":"109年第2次第60題","year":109,"session":2,"number":60,"question":"有關自閉性思考（autistic thinking）之敘述，下列何項錯誤？","options":["(A) 思考內容之特徵為自我中心","(B) 強調思考之客觀性","(C) 多脫離現實","(D) 常見於思覺失調症與自閉症患者"],"answer":1,"image":""},{"id":"md4-109-2-61","subject":"md4","topic":"精神-精神病","meta":"109年第2次第61題","year":109,"session":2,"number":61,"question":"下列何者是雙相情緒障礙症預後較好的因子？","options":["(A) 早發","(B) 病程中出現較多自殺意念","(C) 合併藥物及酒精濫用","(D) 躁期時間較短"],"answer":3,"image":""},{"id":"md4-109-2-62","subject":"md4","topic":"精神-精神病","meta":"109年第2次第62題","year":109,"session":2,"number":62,"question":"有關雙相情緒障礙症（bipolar disorder）之敘述何者錯誤？","options":["(A) 常反覆躁症發作者，可使用抗精神病藥物之長效針劑治療","(B) 長期雙相情緒障礙症患者可能會有認知功能及社會功能障礙，難以回復到生病前的狀態","(C) 有思覺失調症家族史者，罹患雙相情緒障礙症的機率可能較一般人高","(D) 雙相情緒障礙症患者首次發作皆為躁症或輕躁症，之後才出現憂鬱期"],"answer":3,"image":""},{"id":"md4-109-2-63","subject":"md4","topic":"精神-精神病","meta":"109年第2次第63題","year":109,"session":2,"number":63,"question":"下列關於情緒障礙症（mood disorders）的敘述何者正確？","options":["(A) 憂鬱對於睡眠的影響包括增加夜醒次數，減少總睡眠時間以及睡眠時核心體溫較低","(B) 大多數的正子攝影（positron emission tomography）研究顯示，多數憂鬱患者之大腦前側（anterior brain）代謝下降，特別是在左側","(C) 大多數的正子攝影（positron emission tomography）研究顯示，憂鬱患者之優勢側大腦前側活性相對非優勢側為高","(D) 大多數的正子攝影（positron emission tomography）研究顯示，躁症患者之優勢側大腦前側活性相對非優勢側為低"],"answer":1,"image":""},{"id":"md4-109-2-64","subject":"md4","topic":"精神-精神官能症","meta":"109年第2次第64題","year":109,"session":2,"number":64,"question":"有關泛焦慮症（generalized anxiety disorder），下列敘述何者錯誤？","options":["(A) 常共病（comorbid）其他精神疾病","(B) 最常見的發病年齡（age of onset）是50～65歲","(C) 認知行為治療（cognitive-behavioral therapy）是主要的心理治療模式之一","(D) 藥物治療可選用苯二氮平類（benzodiazepines）鎮靜劑，選擇性血清素回收抑制劑（selective serotonin reuptake inhibitors）...等"],"answer":1,"image":""},{"id":"md4-109-2-65","subject":"md4","topic":"精神-精神官能症","meta":"109年第2次第65題","year":109,"session":2,"number":65,"question":"經前不悅症（premenstrual dysphoric disorder）常見的症狀，不包括下列何者？","options":["(A) 焦慮（anxiety）","(B) 憂鬱（depression）","(C) 妄想（delusion）","(D) 易怒（irritability）"],"answer":2,"image":""},{"id":"md4-109-2-66","subject":"md4","topic":"精神-器質性與物質使用","meta":"109年第2次第66題","year":109,"session":2,"number":66,"question":"有關正常老化過程之生物學變化（biological changes）的敘述，下列何者錯誤？","options":["(A) 一般智商（intelligence quotient﹐IQ）可穩定保留到80歲","(B) 隨著老化會減少腦血流量和氧氣","(C) 隨著老化會增加跨血腦屏障（blood-brain barrier）的運輸","(D) 隨著老化正腎上腺素（norepinephrine）在中樞神經系統中會增加"],"answer":3,"image":""},{"id":"md4-109-2-67","subject":"md4","topic":"精神-器質性與物質使用","meta":"109年第2次第67題","year":109,"session":2,"number":67,"question":"Alcoholic blackouts常發生在飲用大量酒精之後，下列敘述何者錯誤？","options":["(A) 是一種順行性失憶（anterograde amnesia），當事人在事後記不起酒醉（alcohol intoxication）時發生的事情之部分或全部內容","(B) 短期記憶（short-term memory）和長期記憶（long-term memory）皆受損","(C) 當事人仍可以執行生活任務，在旁人看來無異狀","(D) 和酒精阻斷新記憶的固化有關（consolidation of new memories），涉及海馬迴和一些顳葉區域"],"answer":1,"image":""},{"id":"md4-109-2-68","subject":"md4","topic":"精神-器質性與物質使用","meta":"109年第2次第68題","year":109,"session":2,"number":68,"question":"下列有關amphetamine/methamphetamine濫用的敘述，何者錯誤？","options":["(A) 可能會引發心血管、腦血管以及腸胃道併發症，其中最嚴重的是心肌梗塞、嚴重高血壓、腦血管疾病以及缺血性腸炎（ischemic colitis）","(B) 在神經症狀部分，可能會出現抽搐（twitching）、強直（tetany）、癲癇、昏迷，甚至死亡","(C) 在精神症狀部分，會造成鎮靜，並降低焦慮","(D) 戒斷時會出現焦慮、憂鬱、無力、疲倦思睡、過度飲食、頭痛、多汗等，大約一週後緩解"],"answer":2,"image":""},{"id":"md4-109-2-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"109年第2次第69題","year":109,"session":2,"number":69,"question":"下列關於鎮靜安眠藥敘述，何者錯誤？","options":["(A) 抗焦慮藥物大劑量時也具安眠作用","(B) 作用時間短且強效的安眠藥物是長期使用助眠藥物開立的首選用藥","(C) 酒癮患者對安眠藥物作用通常有耐受性，故不可以併用酒精和安眠藥物","(D) 巴比妥類藥物（barbiturates）的安全性低，現在很少用在失眠治療"],"answer":1,"image":""},{"id":"md4-109-2-70","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"109年第2次第70題","year":109,"session":2,"number":70,"question":"有關自閉症類群障礙症（autism spectrum disorder）的社會心理治療（psychosocial intervention），下列何者錯誤？","options":["(A) 主要的目標為改善社交互動、溝通，融入學校與同儕的能力，進而可以獲得技能與獨立生活","(B) 經過隨機對照試驗（randomized controlled trial）方能確認治療的療效","(C) 感覺統合治療（sensory integration therapy）對自閉症的核心症狀（例如社會—情緒相互性）具有治療效果","(D) 認知行為治療（cognitive-behavioral therapy）對自閉症的焦慮、憂鬱及強迫症狀具有治療效果"],"answer":2,"image":""},{"id":"md4-109-2-71","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"109年第2次第71題","year":109,"session":2,"number":71,"question":"有關行為疾患（conduct disorder），下列敘述何者錯誤？","options":["(A) 長期追蹤研究顯示：此病症具有長期且廣泛的影響，也可能發展成反社會人格（antisocial personality disorder）","(B) 長期暴露在暴力的影片、電動玩具，可能使兒童較不具有同理心（empathy），具有發展行為疾患之風險","(C) 此病症在人際互動上之缺陷包括有缺乏罪惡感、缺乏同理心，對自己的表現不在意，情感平淡或冷漠","(D) 18歲以上之患者則不做此診斷，改為以反社會人格做診斷"],"answer":3,"image":""},{"id":"md4-109-2-72","subject":"md4","topic":"精神-精神官能症","meta":"109年第2次第72題","year":109,"session":2,"number":72,"question":"下列有關轉化症（conversion disorder）的敘述，何者錯誤？","options":["(A) 轉化症的診斷需要排除重大內外科疾病","(B) 若可以透過建議、暗示或藥物如lorazepam的使用有所緩解，就不是轉化症","(C) 許多神經科疾病如腦腫瘤、腦病變、重症肌無力等可能在病程早期易被診斷為轉化症","(D) 轉化症之常見症狀為運動或感覺功能異常"],"answer":1,"image":""},{"id":"md4-109-2-73","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"109年第2次第73題","year":109,"session":2,"number":73,"question":"關於飲食疾患（eating disorders），下列敘述何者正確？","options":["(A) 厭食症（anorexia nervosa）在男性與女性的盛行率差不多","(B) 厭食症（anorexia nervosa）患者常見生理變化包括：低體溫、心搏過緩、低血壓、無月經等","(C) 厭食症（anorexia nervosa）患者可能出現催吐或濫用瀉劑等行為，須小心個案出現血鉀過高的現象","(D) 暴食症（bulimia nervosa）比厭食症盛行率低，患者中女性較男性為多"],"answer":1,"image":""},{"id":"md4-109-2-74","subject":"md4","topic":"兒科-心血管呼吸","meta":"109年第2次第74題","year":109,"session":2,"number":74,"question":"2歲女童因咳嗽就醫，由於胸部X光顯示縱膈腔變寬，因此在接受對比劑注射後，接受電腦斷層掃描檢查如圖，在主動脈弓之前可見明顯軟組織，其最常見原因為何？","options":["(A) 胸腺","(B) 淋巴瘤","(C) 淋巴管瘤","(D) 血管瘤"],"answer":0,"image":"md4-109-2-74.jpeg"},{"id":"md4-109-2-75","subject":"md4","topic":"神經-中風","meta":"109年第2次第75題","year":109,"session":2,"number":75,"question":"72歲男性，突然昏倒，送急診室，未注射對比劑之腦部電腦斷層（CT）檢查如圖，診斷是：","options":["(A) 蜘蛛網膜下腔出血（subarachnoid hemorrhage）","(B) 硬腦膜外血腫（epidural hematoma）","(C) 急性腦梗塞（acute cerebral infarction）","(D) 硬腦膜下血腫（subdural hematoma）"],"answer":0,"image":"md4-109-2-75.jpeg"},{"id":"md4-109-2-76","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"109年第2次第76題","year":109,"session":2,"number":76,"question":"兒童因脫水減少體重8%時，下列何種臨床表現最不常見？","options":["(A) 口渴","(B) 黏膜乾燥","(C) 微血管充填時間大於3秒","(D) 血壓正常"],"answer":2,"image":""},{"id":"md4-109-2-77","subject":"md4","topic":"精神-精神病","meta":"109年第2次第77題","year":109,"session":2,"number":77,"question":"對一位20歲男性急性躁動（agitation）的病人，下列何種藥物最不適合肌肉注射？","options":["(A) haloperidol","(B) droperidol","(C) lorazepam","(D) diazepam"],"answer":3,"image":""},{"id":"md4-109-2-78","subject":"md4","topic":"精神-精神病","meta":"109年第2次第78題","year":109,"session":2,"number":78,"question":"鋰鹽（Lithium）用於下列何者？","options":["(A) 酗酒（alcoholism）","(B) 恐慌症（panic disorder）","(C) 躁症發作（acute mania）","(D) 厭食（anorexia nervosa）"],"answer":2,"image":""},{"id":"md4-109-2-79","subject":"md4","topic":"醫學倫理與法規","meta":"109年第2次第79題","year":109,"session":2,"number":79,"question":"2歲大的陳小弟罹患川崎病，他有典型的皮膚紅疹、眼結膜紅及眼皮腫症狀，為了製作教學片在討論會中使用，你必須為他拍攝整個面部（包括眼睛）的特寫照片，下列何種處理方式最適當？","options":["(A) 此照片只做教學用途，就可露出眼睛","(B) 照相無損病人權益不需病人同意","(C) 徵得家長同意才能露出其眼睛","(D) 申請倫理委員會的許可就可以拍攝全臉部照片"],"answer":2,"image":""},{"id":"md4-109-2-80","subject":"md4","topic":"醫學倫理與法規","meta":"109年第2次第80題","year":109,"session":2,"number":80,"question":"40歲陳先生自幼罹患癲癇症，這些年來以抗癲癇藥物控制得還不錯，但是一年中在疲累或身體不適時還是會發作一、兩次。在3個月前他所服務的公司經營不善倒閉，在中年失業的情況下，尋找工作不易，他就隱瞞病情開始跑計程車維生。在他規則到診所拿1個月抗癲癇藥時，醫師得知此事後，警告他跑計程車將造成公共危險，叮嚀他儘快找個安全性高的職業，3個月過去，他表示沒有機會轉換工作，下列何種處置最為正確？","options":["(A) 努力勸導，並清楚記載於病歷中","(B) 通報其雇主，避免造成公共危險","(C) 請張先生簽切結書聲明1個月內轉換工作","(D) 提高抗癲癇藥物劑量並測量血中濃度"],"answer":1,"image":""},{"id":"md4-110-1-1","subject":"md4","topic":"兒科-感染神經","meta":"110年第1次第1題","year":110,"session":1,"number":1,"question":"5歲女童發燒5天住院，身體診察有雙眼皮浮腫、肝脾腫大、頸部淋巴結腫大和扁桃腺有象牙白的滲出物，抽血檢查如下：Hb：11 g/dL，Hct：34%，WBC：18300/uL，Atypical lymphocyte：18%，Platelet：350000/uL，GOT：188 IU/L，GPT：374 IU/L，CRP：0.9 mg/dL。此女童最可能是感染下列何種病原體？","options":["(A) 肺炎鏈球菌（Streptococcus pneumoniae）","(B) 白色念珠菌（Candida albicans）","(C) EB病毒（Epstein-Barr virus）","(D) 腸病毒（Enterovirus）"],"answer":2,"image":""},{"id":"md4-110-1-2","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"110年第1次第2題","year":110,"session":1,"number":2,"question":"1歲大男嬰於接種水痘和麻疹-德國麻疹-腮腺炎疫苗2天後開始高燒6天，經診斷為川崎氏症（Kawasaki disease）並接受高劑量免疫球蛋白治療，出院後服用每天5mg/公斤阿斯匹靈治療。現已出院滿1個月，關於預防接種建議，下列何者最為正確？","options":["(A) 因正在服用阿斯匹靈，不能接種流感疫苗","(B) 1歲3個月大時可以如期接種活性日本腦炎疫苗","(C) 1個月後應重新接種水痘和麻疹-德國麻疹-腮腺炎疫苗","(D) 肺炎鏈球菌疫苗接種期程不受影響"],"answer":3,"image":""},{"id":"md4-110-1-3","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"110年第1次第3題","year":110,"session":1,"number":3,"question":"25歲媽媽未規則產檢，急自然產娩出新生兒，患嬰出生後因呼吸窘迫進加護病房並做抽血檢查，2天後血液細菌培養有細菌滋生，Gram stain smear如附圖所示，下列敘述何者正確？","options":["(A) 此圖細菌為革蘭氏陰性","(B) 最常見的感染細菌為李斯特菌（Listeria monocytogenes）","(C) 最有可能的感染途徑是經由母體產道上行性感染（ascending infection）導致","(D) 此菌為新生兒泌尿道最常見之致病細菌"],"answer":2,"image":"md4-110-1-3.jpeg"},{"id":"md4-110-1-4","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"110年第1次第4題","year":110,"session":1,"number":4,"question":"關於預防注射的建議，下列何者錯誤？","options":["(A) 早產兒的預防注射是依出生後年紀施打","(B) 早產兒施打五合一疫苗的劑量要減半","(C) 施打高劑量免疫球蛋白後11個月內不可施打活性疫苗","(D) B型肝炎疫苗與五合一疫苗可以同時施打"],"answer":1,"image":""},{"id":"md4-110-1-5","subject":"md4","topic":"兒科-心血管呼吸","meta":"110年第1次第5題","year":110,"session":1,"number":5,"question":"最常見引起成人（adults）及兒童（children）感冒（Common cold）的病毒，為下列何者？","options":["(A) 流感病毒（Influenza viruses）","(B) 鼻病毒（Rhinoviruses）","(C) 腸病毒（Enteroviruses）","(D) 腺病毒（Adenoviruses）"],"answer":1,"image":""},{"id":"md4-110-1-6","subject":"md4","topic":"兒科-心血管呼吸","meta":"110年第1次第6題","year":110,"session":1,"number":6,"question":"有關哮吼（Croup），下列何者描述最不恰當？","options":["(A) 頸部X光片可見thumb sign","(B) 6個月至3歲為好發年齡","(C) 嚴重病童建議使用類固醇治療","(D) 好發季節為晚秋和早冬較寒冷的氣候"],"answer":0,"image":""},{"id":"md4-110-1-7","subject":"md4","topic":"兒科-消化系統疾病","meta":"110年第1次第7題","year":110,"session":1,"number":7,"question":"純母乳哺餵之足月新生兒在第5天大時被發現皮膚較黃，檢驗全血清膽紅素值為19 mg/dL，直接型膽紅素值為0.5 mg/dL，下列處置何者最不適合？","options":["(A) 可檢驗是否有貧血情形","(B) 建議接受膽道胰管磁振造影檢查","(C) 建議給與照光治療","(D) 建議增加母乳餵食次數"],"answer":1,"image":""},{"id":"md4-110-1-8","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"110年第1次第8題","year":110,"session":1,"number":8,"question":"關於38週的新生男嬰，出生後第1天身體診察的發現，下列何者最為異常？","options":["(A) 心跳次數130次／分鐘","(B) 呼吸次數50次／分鐘","(C) 頭圍30公分","(D) 身長50公分"],"answer":2,"image":""},{"id":"md4-110-1-9","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"110年第1次第9題","year":110,"session":1,"number":9,"question":"根據臺灣兒科醫學會指引建議，母親有下列何種狀況仍可以親自哺餵母乳？","options":["(A) 乳房有活動性單純疱疹（HSV）感染","(B) 肺結核菌（Tuberculosis）感染已接受2週適當治療","(C) 人類免疫不全病毒（HIV）感染","(D) 人類嗜T淋巴球病毒（HTLV）感染"],"answer":1,"image":""},{"id":"md4-110-1-10","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"110年第1次第10題","year":110,"session":1,"number":10,"question":"37週出生體重3980公克的新生兒，身體診察發現無呼吸窘迫，右肩內縮，右手臂往內轉（Internal rotation），右手掌呈現內旋（Pronation）姿勢，其抓握反射正常，驚嚇反射左手正常但右手無法舉起，其他神經學檢查正常。最有可能神經受損的部位為何？","options":["(A) C1、C2","(B) C3、C4","(C) C5、C6","(D) C7、C8"],"answer":2,"image":""},{"id":"md4-110-1-11","subject":"md4","topic":"兒科-消化系統疾病","meta":"110年第1次第11題","year":110,"session":1,"number":11,"question":"下列何項不是逐步式鑑別診斷（Setpwise diagnostic approach）兒童慢性腹瀉（Chronic diarrhea）的建議？","options":["(A) 感染性檢查如糞便細菌培養需考慮","(B) 可安排前白蛋白（Prealbumin）檢驗","(C) 糖化血色素（HbA1c）是有效判讀營養不良程度的生物標記","(D) 過敏性評估（Allergic workup）在兒童慢性腹瀉有其角色"],"answer":2,"image":""},{"id":"md4-110-1-12","subject":"md4","topic":"兒科-消化系統疾病","meta":"110年第1次第12題","year":110,"session":1,"number":12,"question":"關於兒童急性闌尾炎（Acute appendicitis）之敘述，下列何者正確？","options":["(A) 大部分病童之腹部X光片可見右下腹糞石（Fecalith）","(B) 非傷寒沙門氏桿菌（Nontyphoidal Salmonella）感染性腸炎不會引起急性闌尾炎","(C) 典型（Typical）的急性闌尾炎病童，臨床表現通常為先腹痛後嘔吐","(D) 病童身體檢查時若無腹部肌肉僵直（Muscle guarding），可排除急性闌尾炎破裂"],"answer":2,"image":""},{"id":"md4-110-1-13","subject":"md4","topic":"兒科-消化系統疾病","meta":"110年第1次第13題","year":110,"session":1,"number":13,"question":"有關膽道閉鎖（Biliary atresia）與新生兒肝炎（Neonatal hepatitis）之敘述，下列何者正確？","options":["(A) 膽道閉鎖的發生率稍高於新生兒肝炎的發生率","(B) 肝臟病理切片中，膽道閉鎖可見小膽管增生（Bile ductular proliferation）；新生兒肝炎可見發炎細胞浸潤，局部肝細胞壞死","(C) 膽道閉鎖目前尚未有確定的病因；而新生兒肝炎的病毒性病因主要是B型肝炎病毒","(D) 膽道閉鎖在滿4個月大時手術預後較佳；新生兒肝炎則以內科治療為主"],"answer":1,"image":""},{"id":"md4-110-1-14","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"110年第1次第14題","year":110,"session":1,"number":14,"question":"有關嬰幼兒及兒童期每日膳食營養素參考攝取量（RDIs）的建議，下列何者錯誤？","options":["(A) 1歲以下的嬰兒攝取植物性蛋白占總蛋白質2/3以上為宜","(B) 在兒童期時，鈣的攝取量隨著年齡增加而增加","(C) 在兒童期時，磷的攝取量隨著年齡增加而增加","(D) 在兒童期時，鋅的攝取量隨著年齡增加需些微增加"],"answer":0,"image":""},{"id":"md4-110-1-15","subject":"md4","topic":"兒科-消化系統疾病","meta":"110年第1次第15題","year":110,"session":1,"number":15,"question":"9個月大男嬰發生一陣陣無法安撫的哭鬧，時間持續3小時，有嘔吐3次，但沒有發燒和腹瀉症狀。腹部X光（圖一）和腹部超音波（圖二），最有可能的診斷為何？","options":["(A) 急性闌尾炎（Acute appendicitis）","(B) 嬰兒腸絞痛（Infantile coli）","(C) 腸套疊（Intussusception）","(D) 腸道旋轉不良（Intestinal malrotation）"],"answer":2,"image":"md4-110-1-15.jpeg"},{"id":"md4-110-1-16","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"110年第1次第16題","year":110,"session":1,"number":16,"question":"5歲女童接受化學藥物治療後，發現有輕微蛋白尿與尿糖現象，抽血檢查顯示血中鉀離子2.8 mmol/L，鈉離子 - 146 mmol/L，氯離子115 mmol/L。血液pH值7.2，重碳酸根離子（HCO3）18 mmol/L，BE：-4.5 mmol/L，女童Serum anion gap數值為何？","options":["(A) 13","(B) 29","(C) 11","(D) 6"],"answer":0,"image":""},{"id":"md4-110-1-17","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"110年第1次第17題","year":110,"session":1,"number":17,"question":"造成慢性腎臟病兒童身材矮小的原因，下列敘述何者錯誤？","options":["(A) 腎骨失養症（Renal osteodystrophy）","(B) 代謝性酸中毒","(C) 生長激素分泌下降","(D) 貧血"],"answer":2,"image":""},{"id":"md4-110-1-18","subject":"md4","topic":"兒科-感染神經","meta":"110年第1次第18題","year":110,"session":1,"number":18,"question":"下列有關單純型熱性痙攣（simple febrile seizure）的敘述，何者錯誤？","options":["(A) 抽搐不超過15分鐘","(B) 通常為局部型抽搐（focal convulsion）","(C) 24小時之內抽搐不會再復發","(D) 抽搐後可以短暫意識混亂"],"answer":1,"image":""},{"id":"md4-110-1-19","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"110年第1次第19題","year":110,"session":1,"number":19,"question":"下列何種肌肉疾病，是因肌肉細胞的Dystrophin蛋白發生質或量的變異造成的？","options":["(A) Myotonic muscular dystrophy","(B) Central core disease","(C) Spinal muscular atrophy","(D) Becker muscular dystrophy"],"answer":3,"image":""},{"id":"md4-110-1-20","subject":"md4","topic":"兒科-內分泌遺傳","meta":"110年第1次第20題","year":110,"session":1,"number":20,"question":"關於兒童生長發育的描述，下列何者最不像有內分泌異常的問題？","options":["(A) 幼稚園大班的5歲男孩，最近生長速率一年只長高2公分","(B) 小學一年級剛入學的7歲男生，媽媽注意到有陰毛發育","(C) 剛升國一的13歲女生，班上很多同學月經都來了，但自己初經還沒來","(D) 高一的16歲男生，發現半年來胸部隆起越來越明顯，且有明顯的硬塊"],"answer":2,"image":""},{"id":"md4-110-1-21","subject":"md4","topic":"兒科-內分泌遺傳","meta":"110年第1次第21題","year":110,"session":1,"number":21,"question":"滿月的男嬰因嚴重尿道下裂來求診，檢查發現陰莖長度1.8公分，尿道開口位於陰囊與陰莖交界處，出生後抽血檢查染色體核型為46,XY。下列那一項是最不可能的診斷？","options":["(A) Partial androgen insensitivity syndrome","(B) Gonadal dysgenesis","(C) Congenital adrenal hyperplasia due to 21-hydroxylase deficiency","(D) 5α-reductase deficiency"],"answer":2,"image":""},{"id":"md4-110-1-22","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"110年第1次第22題","year":110,"session":1,"number":22,"question":"4歲小男孩被診斷為Henoch-Schönlein Purpura（HSP），血液檢查報告最有可能是下列何種組合？","options":["(A) WBC：12000 /μL、Hb 9.0 g/dL、platelet：5000 /μL","(B) WBC：12000 /μL、Hb 12.0 g/dL、platelet：235000 /μL","(C) WBC：5000 /μL、Hb 12.0 g/dL、platelet：5000 /μL","(D) WBC：5000 /μL、Hb 9.0 g/dL、platelet：235000 /μL"],"answer":1,"image":""},{"id":"md4-110-1-23","subject":"md4","topic":"兒科-心血管呼吸","meta":"110年第1次第23題","year":110,"session":1,"number":23,"question":"3歲半的小朋友，沒有發燒，昨晚夜間咳嗽明顯。身體診察發現呼吸聲音明顯，聽診雙側有喘息音（Wheezing），給與短效型支氣管擴張劑（Bronchodilator）後，喘息音明顯改善，下列何種診斷最有可能？","options":["(A) 上呼吸道感染（Upper respiratory tract infection）","(B) 細支氣管炎（Bronchiolitis）","(C) 氣喘（Asthma）","(D) 氣道異物阻塞（Airway foreign body obstruction）"],"answer":2,"image":""},{"id":"md4-110-1-24","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"110年第1次第24題","year":110,"session":1,"number":24,"question":"有關兒童異位性皮膚炎（Atopic dermatitis）的臨床表現，下列敘述何者最不恰當？","options":["(A) 在嬰幼兒時期，皮膚病灶好發在包尿布區域","(B) 兒童常因為癢的感受而搔抓","(C) 兒童皮膚會比較乾燥","(D) 兒童年紀漸大後，皮膚病灶好發在四肢屈側"],"answer":0,"image":""},{"id":"md4-110-1-25","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"110年第1次第25題","year":110,"session":1,"number":25,"question":"有關預防嬰幼兒過敏的觀念，下列敘述何者最不恰當？","options":["(A) 建議孕婦飲食應避免高過敏食物（例如海鮮、花生等）","(B) 4～6個月大嬰兒可正常添加副食品，不需延後添加來預防過敏","(C) 母乳哺育對於預防氣喘的效果不確定","(D) 目前國際指引尚未建議嬰幼兒常規性使用益生菌來預防過敏"],"answer":0,"image":""},{"id":"md4-110-1-26","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"110年第1次第26題","year":110,"session":1,"number":26,"question":"有關兒童急性淋巴性白血病的治療，下列何者最正確？","options":["(A) 大多急性淋巴性白血病患童使用單一化療藥物即可治癒","(B) 無需誘導期（induction phase）化療，可直接進入鞏固期（consolidation phase）化療","(C) 中樞神經系統的預防多使用腰椎穿刺化療藥物注射","(D) 放射治療在兒童急性淋巴性白血病為第一線治療選擇"],"answer":2,"image":""},{"id":"md4-110-1-27","subject":"md4","topic":"兒科-心血管呼吸","meta":"110年第1次第27題","year":110,"session":1,"number":27,"question":"有關兒童感染性心內膜炎（Infective endocarditis），下列何者不是感染後預後不佳的高風險（highest risk）族群？","options":["(A) 複雜發紺性先天性心臟病的病童","(B) 年齡小於1歲的病童","(C) 曾接受人工血管分流手術的病童","(D) 患有風濕性心臟病的病童"],"answer":1,"image":""},{"id":"md4-110-1-28","subject":"md4","topic":"兒科-心血管呼吸","meta":"110年第1次第28題","year":110,"session":1,"number":28,"question":"下列何者不是嬰兒期需要修補心室中膈缺損（Ventricular septal defect, VSD）的適應症？","options":["(A) 無法以藥物控制的心臟衰竭（Heart failure）","(B) 9個月大時出現肺高壓（Pulmonary hypertension）臨床症狀","(C) 出現生長遲滯表現（Failure to thrive）對內科治療無效","(D) 超音波檢查Pulmonary-to-systemic flow ratio（Qp：Qs ratio）＜ 2：1"],"answer":3,"image":""},{"id":"md4-110-1-29","subject":"md4","topic":"兒科-心血管呼吸","meta":"110年第1次第29題","year":110,"session":1,"number":29,"question":"足月嬰兒2個月大在健兒門診時被聽到第3度收縮期的心雜音，懷疑是心室中膈缺損（Ventricular septal defect）。下列那一種臨床表現最有可能暗示該心臟缺損已經對小嬰兒產生不良的影響？","options":["(A) 每餐餵食時間需超過1小時","(B) 每分鐘的呼吸次數為32下","(C) 在右側肋骨下緣可摸到約1公分的肝臟","(D) 在哭泣厲害的時候會出現唇色稍微偏紫的情形"],"answer":0,"image":""},{"id":"md4-110-1-30","subject":"md4","topic":"兒科-心血管呼吸","meta":"110年第1次第30題","year":110,"session":1,"number":30,"question":"下列那一種先天性心臟病或心臟手術術後，最不可能被聽到連續性心雜音（Continuous murmur）？","options":["(A) 開放性動脈導管（Patent ductus arteriosus）","(B) 左冠狀動脈到右心房瘻管","(C) 接受Blalock-Taussig shunt術後","(D) 大型的肺動脈-肺靜脈瘻管（Pulmonary arteriovenous fistula）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第30題一律給分 (原公告答案 D)"},{"id":"md4-110-1-31","subject":"md4","topic":"兒科-內分泌遺傳","meta":"110年第1次第31題","year":110,"session":1,"number":31,"question":"一位新生兒經身體診察懷疑唐氏症（Down syndrome），血液染色體核型（Karyotyping）證實為47,XX,+21。下列敘述何者最為正確？","options":["(A) 病童的染色體都可以發現三條獨立的21號染色體","(B) 除外觀異常外，通常會呈現高張力（Hypertonia）","(C) 對於唐氏症的診斷，斷掌（Simian crease）特異性高","(D) 唐氏症有可能合併心內膜墊缺損（Endocardial cushion defect）"],"answer":3,"image":""},{"id":"md4-110-1-32","subject":"md4","topic":"兒科-內分泌遺傳","meta":"110年第1次第32題","year":110,"session":1,"number":32,"question":"關於Inborn errors of metabolism，下列敘述何者錯誤？","options":["(A) 大多數Inborn errors of metabolism為性聯遺傳模式","(B) 新生兒篩檢（Newborn screening）可幫助早期診斷","(C) 臨床上大多呈現非特異性症狀，常與敗血症無法區分","(D) 患者體液或尿液的味道有時可提供診斷的線索"],"answer":0,"image":""},{"id":"md4-110-1-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"110年第1次第33題","year":110,"session":1,"number":33,"question":"下列有關臺灣新生兒「篩檢疾病」與其「篩檢項目」之配對，何者錯誤？","options":["(A) 苯酮尿症：Phenylalanine","(B) 高胱胺酸尿症：Methionine","(C) 先天性甲狀腺功能低能症：TSH","(D) 先天性腎上腺增生症：Androgen"],"answer":3,"image":""},{"id":"md4-110-1-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"110年第1次第34題","year":110,"session":1,"number":34,"question":"使用口服isotretinoin治療青春痘時，下列何者為絕對禁忌？","options":["(A) B型肝炎帶原","(B) 培養出格蘭氏陰性菌","(C) 對抗生素有抗藥性","(D) 懷孕"],"answer":3,"image":""},{"id":"md4-110-1-35","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"110年第1次第35題","year":110,"session":1,"number":35,"question":"關於異位性皮膚炎診斷的主要依據，下列何者錯誤？","options":["(A) 皮疹於嬰幼兒時期主要出現在臉部及四肢伸側","(B) 通常伴隨難以控制的癢感","(C) 通常有家族或個人藥物過敏史","(D) 通常呈現慢性且反覆發作病程"],"answer":2,"image":""},{"id":"md4-110-1-36","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"110年第1次第36題","year":110,"session":1,"number":36,"question":"罹患Parkinson's disease的50歲男性，近來常有頭皮屑及頭皮發癢，在臉上眉毛以及鼻子四周出現如圖所示的脫屑性紅斑，最可能的診斷是：","options":["(A) 脂漏性皮膚炎（seborrheic dermatitis）","(B) 缺脂性皮膚炎（asteatotic dermatitis）","(C) 異位性皮膚炎（atopic dermatitis）","(D) 接觸性皮膚炎（contact dermatitis）"],"answer":0,"image":"md4-110-1-36.jpeg"},{"id":"md4-110-1-37","subject":"md4","topic":"皮膚-感染","meta":"110年第1次第37題","year":110,"session":1,"number":37,"question":"40歲男性，一週前有輕微感冒症狀，至診所求診，服用五天藥物之後感冒症狀緩解，但昨天發現自己手腳掌開始出現無痛性紅斑如圖所示，微癢，下列敘述何者錯誤？","options":["(A) 應詢問有何特殊接觸史，以鑑別診斷二期梅毒","(B) 應該抽血檢查VDRL及HIV","(C) 應詢問是否有口腔及眼睛黏膜等症狀，以鑑別診斷藥物過敏","(D) 應抽血檢查IgE，若數值異常升高，則可診斷為異位性皮膚炎"],"answer":3,"image":"md4-110-1-37.jpeg"},{"id":"md4-110-1-38","subject":"md4","topic":"皮膚-腫瘤","meta":"110年第1次第38題","year":110,"session":1,"number":38,"question":"60歲男性，近三個月內於臉頰上出現一直徑約1.5公分快速成長的腫瘤，病灶中央陷凹填塞角質的結節（nodule），外觀有點像是個火山口（crater）如圖所示，下列何者為最可能的診斷？","options":["(A) 基底細胞癌（basal cell carcinoma）","(B) 波文氏病（Bowen's disease）","(C) 角化棘皮瘤（keratoacanthoma）","(D) 惡性黑色素瘤（malignant melanoma）"],"answer":2,"image":"md4-110-1-38.jpeg"},{"id":"md4-110-1-39","subject":"md4","topic":"皮膚-腫瘤","meta":"110年第1次第39題","year":110,"session":1,"number":39,"question":"臺灣人最常見的皮膚黑色素細胞癌（cutaneous melanoma）為下列那一型？","options":["(A) 結節型黑色素細胞癌（nodular melanoma）","(B) 肢端黑痣型黑色素細胞癌（acral lentiginous melanoma）","(C) 表淺擴散型黑色素細胞癌（superficial spreading melanoma）","(D) 惡性黑痣型黑色素細胞癌（lentigo maligna melanoma）"],"answer":1,"image":""},{"id":"md4-110-1-40","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"110年第1次第40題","year":110,"session":1,"number":40,"question":"55歲男性慢性糖尿病病患，上背皮膚出現如圖所示無症狀的增厚硬化病灶，最有可能是下列何種疾病？","options":["(A) 庫欣氏症候群（Cushing syndrome）","(B) 硬腫病（scleredema）","(C) 硬化性黏液水腫（scleromyxedema）","(D) 皮肌炎（dermatomyositis）"],"answer":1,"image":"md4-110-1-40.jpeg"},{"id":"md4-110-1-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"110年第1次第41題","year":110,"session":1,"number":41,"question":"有關皮肌炎（dermatomyositis）的敘述，下列何者錯誤？","options":["(A) Gottron papules及heliotrope sign為皮肌炎典型的皮膚表現","(B) 病程中大多沒有搔癢症狀","(C) 成人皮肌炎患者有較高的罹癌風險，例如卵巢癌、鼻咽癌","(D) 皮膚鈣化（calcinosis cutis）較常出現在小兒皮肌炎"],"answer":1,"image":""},{"id":"md4-110-1-42","subject":"md4","topic":"皮膚-感染","meta":"110年第1次第42題","year":110,"session":1,"number":42,"question":"6歲男童，數月前臉部出現數塊脫屑性白色斑，用伍氏燈（Wood's lamp）照射並無特別顏色顯現，進一步優先之檢查為何？","options":["(A) 皮膚切片","(B) KOH鏡檢","(C) 貼膚試驗","(D) 黴菌培養"],"answer":1,"image":""},{"id":"md4-110-1-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"110年第1次第43題","year":110,"session":1,"number":43,"question":"有關乾癬（psoriasis）病人的指甲病變之敘述，下列何者錯誤？","options":["(A) nail pitting, oil spots, onycholysis, subungual hyperkeratosis都是乾癬常見的指甲病變，其中以nail pitting最常見","(B) nail pitting是影響nail matrix角化異常所致","(C) nail pitting與發生乾癬性關節病變有強烈相關性","(D) oil spots是具高度專一性的乾癬指甲病變"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第43題一律給分 (原公告答案 C)"},{"id":"md4-110-1-44","subject":"md4","topic":"兒科-感染神經","meta":"110年第1次第44題","year":110,"session":1,"number":44,"question":"12歲男性，出生即發現右臉有朱紅胎記，合併有癲癇、左側肢體肌力較差，最可能的診斷為何？","options":["(A) 結節硬化症（tuberous sclerosis）","(B) 神經纖瘤症（neurofibromatosis）","(C) von Hippel-Lindau疾病（von Hippel-Lindau disease）","(D) Sturge-Weber疾病（Sturge-Weber disease）"],"answer":3,"image":""},{"id":"md4-110-1-45","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"110年第1次第45題","year":110,"session":1,"number":45,"question":"下列遺傳性疾病，何者最容易有腦出血的併發症？","options":["(A) 蛋白C缺乏症（protein C deficiency）","(B) 蛋白S缺乏症（protein S deficiency）","(C) 馮希伯–林島氏症（von Hippel-Lindau disease）","(D) 抗凝血酶III缺乏症（antithrombin III deficiency）"],"answer":2,"image":""},{"id":"md4-110-1-46","subject":"md4","topic":"神經-中風","meta":"110年第1次第46題","year":110,"session":1,"number":46,"question":"李小姐，45歲，因頭痛及癲癇發作，被診斷為腦靜脈栓塞（cerebral venous thrombosis）。對此疾病的敘述下列何者最正確？","options":["(A) 腦靜脈栓塞不會合併腦出血","(B) 電腦斷層攝影檢查（CT）較核磁共振攝影檢查（MRI）診斷價值高","(C) 腦壓太高時，應考慮以腰椎穿刺做緊急腦脊髓液引流","(D) 可給與抗凝血藥物治療"],"answer":3,"image":""},{"id":"md4-110-1-47","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"110年第1次第47題","year":110,"session":1,"number":47,"question":"一位28歲女性突然發生劇烈頭痛，當她躺下後數分鐘內會改善，起床後數分鐘內頭痛又會加劇。她接受注射顯影劑的腦部磁振造影檢查發現硬腦膜有瀰漫性的顯影。下列何者為最可能的診斷？","options":["(A) 偏頭痛","(B) 蜘蛛網膜下腔出血","(C) 自發性顱內低壓性頭痛","(D) 叢發性頭痛"],"answer":2,"image":""},{"id":"md4-110-1-48","subject":"md4","topic":"神經-中風","meta":"110年第1次第48題","year":110,"session":1,"number":48,"question":"下列關於顱內壓上升（increased intracranial pressure）之臨床徵候與檢視的敘述，何者錯誤？","options":["(A) 嚴重的顱內壓上升，病人可能出現低血壓、心搏加速及頭痛的現象","(B) 出現庫欣氏反射（Cushing reflex）暗示有續發急性腦疝脫的可能","(C) 進行腰椎穿刺前的病人應先做腦部攝影","(D) 可藉由眼底鏡檢視是否有視乳突水腫（papilledema）的現象"],"answer":0,"image":""},{"id":"md4-110-1-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"110年第1次第49題","year":110,"session":1,"number":49,"question":"關於重積癲癇（status epilepticus）的敘述，下列何者錯誤？","options":["(A) 在兒童之抽搐性重積癲癇（convulsive status epilepticus），死亡率為50%以上","(B) 血中catecholamine濃度升高可誘發致死性心律不整","(C) 所有罹患抽搐性重積癲癇（convulsive status epilepticus）的發燒病人，就算無明顯的腦膜炎跡象，也須做腰椎穿刺檢驗腦脊髓液","(D) 所有罹患抽搐性重積癲癇（convulsive status epilepticus）之成人及無發燒症狀之孩童，均須接受神經影像學檢查，例如CT或MRI"],"answer":0,"image":""},{"id":"md4-110-1-50","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"110年第1次第50題","year":110,"session":1,"number":50,"question":"關於睡眠呼吸中止症（sleep apnea）的敘述，下列何者錯誤？","options":["(A) 中樞型睡眠呼吸中止症（central sleep apnea）可發生於腦幹中風或腦幹發炎之病人","(B) 阻塞型睡眠呼吸中止症（obstructive sleep apnea）常發生於肥胖短頸或肢端肥大症（acromegaly）之病人","(C) 阻塞型睡眠呼吸中止症只發生於快速動眼期睡眠（REM sleep）","(D) 連續氣道正壓呼吸器（CPAP）為睡眠呼吸中止症最常用且有效的治療方法"],"answer":2,"image":""},{"id":"md4-110-1-51","subject":"md4","topic":"神經-失智退化運動障礙","meta":"110年第1次第51題","year":110,"session":1,"number":51,"question":"有關原發性常壓性水腦症（idiopathic normal pressure hydrocephalus）的臨床表現與檢查發現，何者正確？","options":["(A) 病人很少併有尿失禁","(B) 步態異常（gait disturbance）往往是第一個、也是最常見的症狀","(C) 病人辨認人臉（face recognition）的功能障礙特別嚴重","(D) 脊髓液引流術對步態不穩無法改善"],"answer":1,"image":""},{"id":"md4-110-1-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"110年第1次第52題","year":110,"session":1,"number":52,"question":"有關早期阿茲海默症病人的腦脊髓液分析，下列何者最有可能？","options":["(A) Aβ42上升、phosphorylated tau protein上升","(B) Aβ42上升、phosphorylated tau protein下降","(C) Aβ42下降、phosphorylated tau protein上升","(D) Aβ42下降、phosphorylated tau protein下降"],"answer":2,"image":""},{"id":"md4-110-1-53","subject":"md4","topic":"神經-失智退化運動障礙","meta":"110年第1次第53題","year":110,"session":1,"number":53,"question":"下列有關路易氏體失智症（dementia with Lewy bodies）的敘述，何者錯誤？","options":["(A) 應儘量使用dopamine agonist以治療病人的parkinsonism的症狀","(B) 早期即可能出現視幻覺","(C) 出現動眼期睡眠行為障礙（REM sleep behavior disorder）","(D) 常有不明原因意識不清、跌倒或昏倒"],"answer":0,"image":""},{"id":"md4-110-1-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"110年第1次第54題","year":110,"session":1,"number":54,"question":"下列何者非周邊神經病變之常見症狀？","options":["(A) 運動功能障礙","(B) 肌腱反射增強","(C) 感覺功能障礙","(D) 自律神經病變"],"answer":1,"image":""},{"id":"md4-110-1-55","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"110年第1次第55題","year":110,"session":1,"number":55,"question":"有關疱疹病毒神經病變（neuropathy of herpes zoster）之敘述，下列何者最不恰當？","options":["(A) 可能引起角膜（cornea）損傷","(B) 疱疹病毒主要侵犯運動神經元","(C) 好發於肋間神經","(D) 好發於三叉神經第一分支"],"answer":1,"image":""},{"id":"md4-110-1-56","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"110年第1次第56題","year":110,"session":1,"number":56,"question":"下列何者不是屬於離子通道病變（channelopathy）?","options":["(A) 先天性肌強直症（myotonia congenita）","(B) 先天性肌強直性痙攣病（paramyotonia congenita）","(C) 高血鉀性週期性麻痺症（hyperkalemic periodic paralysis）","(D) 肌強直性失養症（myotonic dystrophy）"],"answer":3,"image":""},{"id":"md4-110-1-57","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"110年第1次第57題","year":110,"session":1,"number":57,"question":"如果要診斷為神經性梅毒合併失智症，下列那一組檢查結果最具有診斷的正確性？①血清之梅毒螺旋體血球凝集試驗（T. pallidum particle agglutination test, MHA-TP）為陽性反應 ②腦脊髓液之VDRL為陽性反應 ③ 腦脊髓液之TPHA為陽性反應 ④腦波呈現典型的週期性單側癲癇樣放電（periodic lateralized epileptiform discharges）","options":["(A) ①②","(B) ②④","(C) ①④","(D) ③④"],"answer":0,"image":""},{"id":"md4-110-1-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"110年第1次第58題","year":110,"session":1,"number":58,"question":"關於治療結核菌腦膜炎的敘述，下列何者錯誤？","options":["(A) 不可使用類固醇（corticosteroid）","(B) 如果症狀與腦脊髓液檢查結果皆高度懷疑結核菌腦膜炎，就必須儘早投予抗結核菌藥物","(C) 抗結核菌藥物需持續服用6個月以上","(D) 使用isoniazid治療時需併用pyridoxine以避免發生周邊神經炎（peripheral neuropathy）"],"answer":0,"image":""},{"id":"md4-110-1-59","subject":"md4","topic":"精神-精神病","meta":"110年第1次第59題","year":110,"session":1,"number":59,"question":"雖無外界感官刺激，但知覺上卻感受到刺激存在，此症狀稱為：","options":["(A) 錯覺（illusion）","(B) 妄想（delusion）","(C) 幻覺（hallucination）","(D) 失憶（amnesia）"],"answer":2,"image":""},{"id":"md4-110-1-60","subject":"md4","topic":"精神-器質性與物質使用","meta":"110年第1次第60題","year":110,"session":1,"number":60,"question":"關於抗精神病藥物引起動作障礙（medication-induced movement disorders）的敘述，下列何者正確？","options":["(A) rabbit syndrome的臨床表現是嘴唇與口周（perioral）的肌肉震顫（tremor）","(B) 抗精神病藥物誘發之neuroleptic malignant syndrome好發於年長女性","(C) 年輕男性是抗精神病藥物誘發parkinsonism的高風險族群","(D) 年長女性是抗精神病藥物誘發角弓反張（opisthotonos）的高風險族群"],"answer":0,"image":""},{"id":"md4-110-1-61","subject":"md4","topic":"精神-精神病","meta":"110年第1次第61題","year":110,"session":1,"number":61,"question":"關於雙相情緒障礙症（bipolar disorder）個案於懷孕期接受藥物治療之相關描述，下列何者錯誤？","options":["(A) lithium使用與胎兒發生Ebstein氏三尖瓣膜異常症（Ebstein's anomaly）有關","(B) valproic acid會增加胎兒有心臟畸型（cardiac malformation）的風險","(C) lamotrigine使用可能與胎兒唇口裂（oral cleft）有關","(D) carbamazepine使用與胎兒發生神經管異常有關"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第61題一律給分。 (原公告答案 B)"},{"id":"md4-110-1-62","subject":"md4","topic":"精神-精神病","meta":"110年第1次第62題","year":110,"session":1,"number":62,"question":"在精神科急性病房，一名中年男性病人，在護理站徘徊，向護理人員求救，表示有外星人在監視他的一舉一動，甚至叫他去自殺；他腦內被植入可衛星定位的晶片，性命受到很大威脅。如果其診斷為思覺失調症（schizophrenia），下列敘述何者正確？","options":["(A) 上述的症狀至少要有一年以上方能診斷為思覺失調症","(B) 依現行精神衛生法之規定，病人因有極高自殺風險，若再經另一位精神科專科醫師鑑定後判定病人為嚴重病人，則可逕行強制住院達60天","(C) 兒童時期發展疾患如注意力不足／過動症（attention-deficit / hyperactivity disorder）須先行排除，方能診斷為思覺失調症","(D) 可開立risperidone 2mg治療上述疾病"],"answer":3,"image":""},{"id":"md4-110-1-63","subject":"md4","topic":"精神-器質性與物質使用","meta":"110年第1次第63題","year":110,"session":1,"number":63,"question":"接受移植手術，術後身體狀況穩定的個案，仍需注意可能出現精神科併發症。以下何者最不會出現？","options":["(A) 適應障礙症（adjustment disorder）","(B) 創傷後壓力症（posttraumatic stress disorder）","(C) 妄想症（delusional disorder）","(D) 重鬱症（major depression）"],"answer":2,"image":""},{"id":"md4-110-1-64","subject":"md4","topic":"精神-精神病","meta":"110年第1次第64題","year":110,"session":1,"number":64,"question":"有關憂鬱症生物機轉的神經傳遞物質敘述，下列何者正確？","options":["(A) norepinephrine主要來自raphe nuclei，與交感神經的活化及焦慮有關","(B) serotonin主要來自locus ceruleus，與疼痛感覺有關","(C) 與憂鬱症致病機轉有關的神經化學傳導物質包括：norepinephrine、serotonin、dopamine等","(D) 加強serotonin再回收（reuptake）是抗憂鬱症藥物基本的作用"],"answer":2,"image":""},{"id":"md4-110-1-65","subject":"md4","topic":"精神-精神官能症","meta":"110年第1次第65題","year":110,"session":1,"number":65,"question":"李太太表示最近8個月來常常覺得煩躁不安，擔心工作業績下降，但其實她過去工作表現一直很不錯。常莫名地擔心2歲孩子會受傷跌倒，也常擔心小孩未來的課業學習問題。此外，雖然她每年身體檢查結果並無異常，但一直擔心身體遲早會變壞，越擔心則身體各方面越覺得不舒服，常覺得心悸、胸悶、頭痛、晚上也睡不安穩，最近甚至嚴重到無法好好專心工作。此病患最可能的診斷為何？","options":["(A) 廣泛性焦慮症","(B) 解離症","(C) 畏懼症","(D) 強迫症"],"answer":0,"image":""},{"id":"md4-110-1-66","subject":"md4","topic":"精神-精神官能症","meta":"110年第1次第66題","year":110,"session":1,"number":66,"question":"罹患下列那種精神疾病的患者主動前往急診室求助的比率最高？","options":["(A) 恐慌症（panic disorder）","(B) 重鬱症（major depressive disorder）","(C) 畏懼症（phobic disorder）","(D) 雙相情緒障礙症（bipolar disorder）"],"answer":0,"image":""},{"id":"md4-110-1-67","subject":"md4","topic":"精神-器質性與物質使用","meta":"110年第1次第67題","year":110,"session":1,"number":67,"question":"有關老人精神疾病之敘述，下列何者錯誤？","options":["(A) 在一般社區及護理之家（nursing home）的老人居民約有15%的有憂鬱症狀","(B) 一般在大於65歲以上老人之疾病中，關節炎（arthritis）所造成之失能（disability）比失智（dementia）常見","(C) 老年人出現精神病症狀（psychotic symptoms），對於抗精神病藥物反應不佳","(D) 妄想症最常發生在40～55歲，但大於60歲以上的老人任何時期都有可能發生，其中最常見之妄想症狀為被害妄想"],"answer":2,"image":""},{"id":"md4-110-1-68","subject":"md4","topic":"神經-失智退化運動障礙","meta":"110年第1次第68題","year":110,"session":1,"number":68,"question":"依據美國精神醫學會所出版的精神疾病診斷準則手冊第五版（DSM-5），有關額顳葉認知障礙症的敘述，下列何者錯誤？","options":["(A) 分為行為與語言兩種類型（behavioral variant and language variant）","(B) 具家族遺傳傾向的個案有較早期發作之特質","(C) 比較阿茲海默症，此症的疾病進展平均速度較快","(D) 學習記憶與社會認知兩類認知功能相對保存（relative sparing）"],"answer":3,"image":""},{"id":"md4-110-1-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"110年第1次第69題","year":110,"session":1,"number":69,"question":"關於K他命（ketamine）的敘述，下列何者錯誤？","options":["(A) 對心血管系統有刺激效果，但不會抑制呼吸","(B) 作用機轉是N-methyl-D-aspartate（NMDA）受器的促效劑（agonist）","(C) 使用後可能出現解離（dissociation）及記憶缺損","(D) 有研究指出某種低劑量之K他命，可降低憂鬱症狀"],"answer":1,"image":""},{"id":"md4-110-1-70","subject":"md4","topic":"精神-器質性與物質使用","meta":"110年第1次第70題","year":110,"session":1,"number":70,"question":"有關酒精戒斷最常見症狀出現的時間先後順序排列，下列何者正確？①幻覺 ②手抖 ③譫妄（delirium） ④抽搐（seizure）","options":["(A) ①②③④","(B) ④②①③","(C) ②①④③","(D) ③②①④"],"answer":2,"image":""},{"id":"md4-110-1-71","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"110年第1次第71題","year":110,"session":1,"number":71,"question":"有關兒童發展之敘述，下列何者正確？ ①大多數兒童在1歲時已能發出近似語言、但不若語言清楚的聲音 ②大多數輕度智能障礙的兒童在5歲之前能被診斷出來 ③大多數兒童在2歲時已能對簡單指示如「把球給我」有合宜反應 ④特定學習障礙症中的書寫障礙（specific learning disorder with impairment in written expression）是因為智能障礙所致","options":["(A) ①③","(B) ②③","(C) ②④","(D) ③④"],"answer":0,"image":""},{"id":"md4-110-1-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"110年第1次第72題","year":110,"session":1,"number":72,"question":"有關注意力不足／過動症（ADHD）的共病，下列何者錯誤？","options":["(A) 對立反抗症（oppositional defiant disorder）是ADHD最常出現的共病之一，尤其出現在混合表現型的ADHD個案","(B) 比一般人較易罹患焦慮症（anxiety disorders）","(C) ADHD診斷與特定的學習障礙症（specific learning disorders）不能同時成立","(D) 長期追蹤研究發現ADHD個案比起一般人有較高的機會罹患第一型雙相情緒障礙症（bipolar I disorders）"],"answer":2,"image":""},{"id":"md4-110-1-73","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"110年第1次第73題","year":110,"session":1,"number":73,"question":"有關於自殺的危險性（risk），下列敘述何者錯誤？","options":["(A) 伴有嚴重憂鬱（severe depression）的個案自殺危險性較高","(B) 伴有精神病（psychosis）的個案自殺危險性較低","(C) 伴有無望感（hopelessness）的個案自殺危險性較高","(D) 家庭關係佳，社會支持良好的個案自殺危險性較低"],"answer":1,"image":""},{"id":"md4-110-1-74","subject":"md4","topic":"兒科-消化系統疾病","meta":"110年第1次第74題","year":110,"session":1,"number":74,"question":"下列關於先天性氣管食道瘻管（congenital tracheoesophageal fistula）的敘述，何者正確？","options":["(A) 約有十分之一會合併其他器官先天性畸形","(B) 診斷可根據胃管在上縱膈腔打圈的X光片","(C) 注入少量高滲透壓離子性對比劑對診斷氣管食道瘻管非常必要","(D) 無論有無合併其他器官先天性畸形，氣管食道瘻管病患多具高存活率"],"answer":1,"image":""},{"id":"md4-110-1-75","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"110年第1次第75題","year":110,"session":1,"number":75,"question":"26歲女性患者，主訴姿態性頭痛已經一個星期，接受磁振造影檢查，圖A是FLAIR影像，圖B是注射顯影劑後的T1加權影像，下列何者是最可能的診斷？","options":["(A) 腦膜炎（meningitis）","(B) 顱內低壓（intracranial hypotension）","(C) 蜘蛛網膜下出血（subarachnoid hemorrhage）","(D) 硬腦膜下水囊（subdural hygroma）"],"answer":1,"image":"md4-110-1-75.jpeg"},{"id":"md4-110-1-76","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"110年第1次第76題","year":110,"session":1,"number":76,"question":"關於5歲兒童外傷（pediatric trauma）輸液的給法，何者錯誤？","options":["(A) 生理食鹽水一般以每公斤20 mL給與","(B) 輸血量一般以每公斤10 mL給與","(C) 失血量達到20%時，就會表現出低血壓","(D) 可以骨內注射（intraosseus injection）給與輸液"],"answer":2,"image":""},{"id":"md4-110-1-77","subject":"md4","topic":"皮膚-感染","meta":"110年第1次第77題","year":110,"session":1,"number":77,"question":"有關疥瘡的治療方式，下列敘述何者錯誤？","options":["(A) 病人接觸過的衣物皆須高溫消毒，其同室住民也需接受檢查與治療","(B) 可使用藥物permethrin cream，塗抹於頸部以下的所有皮膚表面","(C) lindane lotion因為不具有神經毒，可適用於孕婦與小孩","(D) 可使用antihistamines或局部塗抹中強度局部類固醇（mid-potency topical corticosteroid）來緩解癢的症狀"],"answer":2,"image":""},{"id":"md4-110-1-78","subject":"md4","topic":"精神-器質性與物質使用","meta":"110年第1次第78題","year":110,"session":1,"number":78,"question":"下列benzodiazepines中，何者半衰期最短？","options":["(A) midazolam","(B) diazepam","(C) alprazolam","(D) lorazepam"],"answer":0,"image":""},{"id":"md4-110-1-79","subject":"md4","topic":"醫學倫理與法規","meta":"110年第1次第79題","year":110,"session":1,"number":79,"question":"佳佳是一個15歲的國三少女，即將參加升學考試之際被診斷出罹患一種十分罕見且預後不佳的癌症，所需的化療劑量比起其他癌症高出許多，白血球數目降到很低，為避免感染入住單人病房隔離，此外常常需要接受骨髓檢查以了解治療之效果。主治醫師與家長討論佳佳預後十分不樂觀，目前也無有效的治療方式，但家長堅持無論如何一定要救治他們的女兒，否則就要轉院。佳佳身體狀況越來越差，常常疼痛難耐，且因為掉髮所造成的外觀問題，感到極度沮喪與封閉。下列那一個是佳佳的主治醫師考量她最大利益的最好作法？","options":["(A) 同意他們轉院","(B) 繼續給予化學治療","(C) 照會安寧照護團隊為佳佳控制疼痛","(D) 說服佳佳轉到安寧病房"],"answer":2,"image":""},{"id":"md4-110-1-80","subject":"md4","topic":"醫學倫理與法規","meta":"110年第1次第80題","year":110,"session":1,"number":80,"question":"有關隱私保密，下列何者錯誤？","options":["(A) 與病患有關的一切個人資訊，醫療人員都有義務保守秘密，不得以任何理由洩漏出去","(B) 因為某些公共衛生、公共安全的理由，或是涉及到第三者的重大利益，醫療人員可適當的違反守密義務，揭露病患的個人資訊","(C) 醫療人員因為第三者利益得在必要時揭露病患資訊，但最好還是先經過與病患的溝通，取得病患的理解與配合","(D) 當遇到如開放性肺結核的法定傳染性病案例，醫師有通報義務"],"answer":0,"image":""},{"id":"md4-110-2-1","subject":"md4","topic":"兒科-感染神經","meta":"110年第2次第1題","year":110,"session":2,"number":1,"question":"有關咽峽炎（Herpangina）的正確處置，不包括下列何者？","options":["(A) 若有發燒，給與退燒藥","(B) 避免硬或燙的食物","(C) 給與抗生素","(D) 給與口腔止痛噴劑"],"answer":2,"image":""},{"id":"md4-110-2-2","subject":"md4","topic":"兒科-感染神經","meta":"110年第2次第2題","year":110,"session":2,"number":2,"question":"10個月大男童15天前從國外返台，6天前開始出現發燒、咳嗽、流鼻水和結膜炎，身體診察發現臉上和身上有皮疹如圖所示，下列何者是最有可能的診斷？","options":["(A) 疱疹口腔炎（Herpetic gingivostomatitis）","(B) 猩紅熱（Scarlet fever）","(C) 麻疹（Measles）","(D) 玫瑰疹（Roseola infantum）"],"answer":2,"image":"md4-110-2-2.jpeg"},{"id":"md4-110-2-3","subject":"md4","topic":"兒科-感染神經","meta":"110年第2次第3題","year":110,"session":2,"number":3,"question":"對於百日咳（Pertussis）的敘述，下列何者錯誤？","options":["(A) Bordetella pertussis為致病病原體之一，致病機轉與毒素有關","(B) 建議隔離百日咳病人到macrolide抗生素治療滿五天以後","(C) 小於3個月嬰兒，容易表現典型的卡它期（catarrhal stage）、陣發期（paroxysmal stage）和恢復期（convalescent stage）症狀","(D) 為預防百日咳感染，青少年及成人亦建議追加接種減量破傷風白喉，非細胞性百日咳混合疫苗（Tdap）"],"answer":2,"image":""},{"id":"md4-110-2-4","subject":"md4","topic":"兒科-感染神經","meta":"110年第2次第4題","year":110,"session":2,"number":4,"question":"下列何種不是活性減毒疫苗？","options":["(A) 卡介苗（BCG vaccine）","(B) 輪狀病毒疫苗（Rotavirus vaccine）","(C) 麻疹、腮腺炎、德國麻疹疫苗（MMR vaccine）","(D) Ｂ型肝炎疫苗（Hepatitis B vaccine）"],"answer":3,"image":""},{"id":"md4-110-2-5","subject":"md4","topic":"兒科-消化系統疾病","meta":"110年第2次第5題","year":110,"session":2,"number":5,"question":"我國衛生福利部國民健康署提供之兒童健康手冊中有嬰兒糞便顏色辨識圖的敘述，何者較正確？","options":["(A) 辨識圖1-3號顏色視為正常","(B) 可用來篩檢肝膽疾病引起的黃疸","(C) 嬰兒糞便顏色正常即可排除膽道閉鎖","(D) 辨識圖4-6號顏色可以確診母乳性黃疸"],"answer":1,"image":""},{"id":"md4-110-2-6","subject":"md4","topic":"兒科-心血管呼吸","meta":"110年第2次第6題","year":110,"session":2,"number":6,"question":"新生兒出生後馬上出現嚴重的呼吸窘迫和發紺，身體診察最大心音往右偏移，腹部凹陷且胸廓前後徑增加，下列何者為最有可能的診斷？","options":["(A) 先天性發紺性心臟病（Congenital cyanotic heart disease）","(B) 先天性腸阻塞（Congenital intestinal obstruction）","(C) 食道閉鎖氣管食道廔管（Esophageal atresia with tracheoesophageal fistula）","(D) 先天性橫膈膜疝氣（Congenital diaphragmatic hernia）"],"answer":3,"image":""},{"id":"md4-110-2-7","subject":"md4","topic":"兒科-內分泌遺傳","meta":"110年第2次第7題","year":110,"session":2,"number":7,"question":"新生兒出生後身上發現有10幾個咖啡色斑點（café-au-lait spots）如圖所示，最可能罹患下列何種疾病？","options":["(A) Epidermal nevus syndrome","(B) Giant nevus","(C) Mongolian spots","(D) Neurofibromatosis"],"answer":3,"image":"md4-110-2-7.jpeg"},{"id":"md4-110-2-8","subject":"md4","topic":"兒科-感染神經","meta":"110年第2次第8題","year":110,"session":2,"number":8,"question":"嬰兒時期之原始反射，何者不會隨著年紀成長而消失？","options":["(A) Parachute reflex","(B) Moro reflex","(C) Asymmetrical tonic neck reflex","(D) Sucking reflex"],"answer":0,"image":""},{"id":"md4-110-2-9","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"110年第2次第9題","year":110,"session":2,"number":9,"question":"Acetaminophen中毒之兒童，發生昏迷（coma）、無反射（areflexia），下列治療方式，何者最適當？","options":["(A) 低血容量（Hypovolemia）為常見情形，但無需處理","(B) 可注射0.45%食鹽水治療低血容量情形","(C) 維持低血鈉對治療有益","(D) 可給與N-acetylcysteine治療"],"answer":3,"image":""},{"id":"md4-110-2-10","subject":"md4","topic":"兒科-消化系統疾病","meta":"110年第2次第10題","year":110,"session":2,"number":10,"question":"下列何種急性感染性腹瀉，並非由致病菌直接導致？","options":["(A) Staphylococcus aureus","(B) Shigella species","(C) Salmonella enteritidis","(D) Campylobacter jejuni"],"answer":0,"image":""},{"id":"md4-110-2-11","subject":"md4","topic":"兒科-消化系統疾病","meta":"110年第2次第11題","year":110,"session":2,"number":11,"question":"六個月大嬰兒，過去無腹部開刀病史，突然發生持續膽汁性嘔吐（Bilious emesis），腹部X光呈現小腸以上有明顯腸阻塞，下列那一種疾病最有可能？","options":["(A) 幽門狹窄（Pyloric stenosis）","(B) 腸扭結（Midgut volvulus）","(C) 迴腸閉鎖（Ileal atresia）","(D) 胎糞性腸阻塞（Meconium ileus）"],"answer":1,"image":""},{"id":"md4-110-2-12","subject":"md4","topic":"兒科-消化系統疾病","meta":"110年第2次第12題","year":110,"session":2,"number":12,"question":"下列何種營養素，不是主要在十二指腸（Duodenum）和近端空腸（Proximal jejunum）被吸收？","options":["(A) 鎂（Magnesium）","(B) 鐵（Iron）","(C) 葉酸（Folic acid）","(D) 維生素B12（Vitamin B12）"],"answer":3,"image":""},{"id":"md4-110-2-13","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"110年第2次第13題","year":110,"session":2,"number":13,"question":"7歲男童因肺炎住院，身體診察發現臉色蒼白、呼吸急促；血液尿素氮（BUN）90 mg/dL、肌酐酸（Creatinine）7.8 mg/dL、血紅素（hemoglobin）4.5 g/dL、血小板（platelet）50,000/μL，血液抹片發現有許多破碎的紅血球。下列何者為最可能的診斷？","options":["(A) 急性白血病（Acute leukemia）","(B) 原發性血小板低下（Idiopathic thrombocytopenia）","(C) 溶血性尿毒症候群（Hemolytic uremic syndrome）","(D) 伊凡斯症候群（Evans syndrome）"],"answer":2,"image":""},{"id":"md4-110-2-14","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"110年第2次第14題","year":110,"session":2,"number":14,"question":"1歲男童被診斷為泌尿道感染（Urinary tract infection）合併發燒。下列何種檢查對泌尿道感染之評估最不具價值性？","options":["(A) Intravenous pyelography（IVP）","(B) Renal ultrasonography","(C) Voiding cystourethrogram（VCUG）","(D) Renal scintigraphy with technetium-labeled dimercaptosuccinic acid（DMSA）"],"answer":0,"image":""},{"id":"md4-110-2-15","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"110年第2次第15題","year":110,"session":2,"number":15,"question":"下列何種引起兒童急性腎衰竭之疾病，其尿鈉（Urine sodium）濃度的高低與其他三者不同？","options":["(A) 急性腸胃炎引起脫水（Dehydration）","(B) 急性腎絲球發炎（Acute glomerulonephritis）","(C) 藥物引起急性腎小管壞死（Acute tubular necrosis）","(D) 泌尿道阻塞（Urinary tract obstruction）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第15題一律給分 (原公告答案 C)"},{"id":"md4-110-2-16","subject":"md4","topic":"兒科-感染神經","meta":"110年第2次第16題","year":110,"session":2,"number":16,"question":"出生3天大之新生兒發生抽搐（Neonatal seizure），下列敘述何者錯誤？","options":["(A) 較少以Generalized tonic-clonic seizures來表現","(B) 早產兒容易以Subtle seizures來表現","(C) 此時期最常見的病因是感染導致","(D) 除非有其他確定病因，一般而言腦脊髓液檢查是必須的"],"answer":2,"image":""},{"id":"md4-110-2-17","subject":"md4","topic":"神經-中風","meta":"110年第2次第17題","year":110,"session":2,"number":17,"question":"6歲兒童突然發生急性腦動脈缺血性梗塞（Cerebral ischemic stroke），下列何者是最不常見的病因？","options":["(A) 高血壓","(B) 先天性心臟病","(C) 血液凝血功能異常","(D) 腦血管構造異常"],"answer":0,"image":""},{"id":"md4-110-2-18","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"110年第2次第18題","year":110,"session":2,"number":18,"question":"5個月大男嬰，發現肌肉無力來求診，身體診察無肝臟腫大，神經學診察發現面部表情正常，但有四肢低張力及舌頭震顫，最可能為何種疾病？","options":["(A) Spinal muscular atrophy","(B) Duchenne muscular dystrophy","(C) Guillain-Barré syndrome","(D) Acute myositis"],"answer":0,"image":""},{"id":"md4-110-2-19","subject":"md4","topic":"兒科-內分泌遺傳","meta":"110年第2次第19題","year":110,"session":2,"number":19,"question":"接受hypothalamic-pituitary手術的病童，一星期後發現血鈉125 mmol/L，尿鈉80 mmol/L，血中滲透壓低，尿中滲透壓高，且血管內容積（intravascular volume）正常，下列何者為最可能之診斷？","options":["(A) Syndrome of inappropriate antidiuretic hormone secretion（SIADH）","(B) Cerebral salt wasting","(C) Central diabetes insipidus","(D) Adrenal crisis"],"answer":0,"image":""},{"id":"md4-110-2-20","subject":"md4","topic":"兒科-內分泌遺傳","meta":"110年第2次第20題","year":110,"session":2,"number":20,"question":"8歲男生兩側睪丸大小均為5 c.c.，性釋素檢查（GnRH test）結果顯示FSH 10.5 mIU/ml、LH 5.6 mIU/ml、Testosterone 125 ng/dl，下列何者最符合男童診斷？","options":["(A) 生殖細胞瘤合併性早熟","(B) 中樞性性早熟","(C) 腎上腺早熟症（Premature adrenarche）","(D) 巨大睪丸（Macroorchidism）"],"answer":1,"image":""},{"id":"md4-110-2-21","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"110年第2次第21題","year":110,"session":2,"number":21,"question":"有關1歲2個月兒童的發展，下列何者應懷疑發展遲緩，需建議進一步就醫檢查？","options":["(A) 不會撕紙","(B) 不會堆兩塊積木","(C) 不會拉著物體自己站起來","(D) 不會有意義的叫爸爸、媽媽"],"answer":2,"image":""},{"id":"md4-110-2-22","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"110年第2次第22題","year":110,"session":2,"number":22,"question":"下列何者不屬於全身性紅斑狼瘡（Systemic lupus erythematosus）的診斷標準？","options":["(A) 關節炎（Arthritis）","(B) 白血球增加（Leukocytosis）","(C) 抗核抗體（Antinuclear antibody, ANA）陽性","(D) 漿膜炎（Serositis）"],"answer":1,"image":""},{"id":"md4-110-2-23","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"110年第2次第23題","year":110,"session":2,"number":23,"question":"有關Leukocyte adhesion deficiency的敘述，下列何者正確？","options":["(A) 為性聯遺傳","(B) 常有臍帶感染、且合併臍帶較晚脫落之病史","(C) 通常嗜中性白血球絕對值會下降","(D) 感染部位會產生比正常人更多量的膿液為此病的典型表現"],"answer":1,"image":""},{"id":"md4-110-2-24","subject":"md4","topic":"兒科-消化系統疾病","meta":"110年第2次第24題","year":110,"session":2,"number":24,"question":"有關食物過敏的敘述，下列何者錯誤？","options":["(A) 對於雞蛋過敏的小朋友，不可施打MMR疫苗（Measles-Mumps-Rubella vaccine）","(B) 躁動不安、吐奶、腹瀉可能為嬰兒食物過敏之症狀","(C) 健康嬰兒哺餵母乳時，媽媽不需要刻意避開奶、蛋等高過敏性的食物，來預防嬰兒的食物過敏","(D) 牛奶過敏的病童，大部份長大後症狀會改善"],"answer":0,"image":""},{"id":"md4-110-2-25","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"110年第2次第25題","year":110,"session":2,"number":25,"question":"1歲男童，因最近時常皮膚瘀青而來就診，下列何者不是初步篩檢（screening tests）項目？","options":["(A) 完整血球檢查（Complete blood cell count）","(B) 血小板功能性檢查（platelet function studies）","(C) 凝血時間：Prothrombin time（PT）","(D) 凝血時間：activated partial thromboplastin time（aPTT）"],"answer":1,"image":""},{"id":"md4-110-2-26","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"110年第2次第26題","year":110,"session":2,"number":26,"question":"兒童急性淋巴性白血病（Acute lymphoblastic leukemia）的化學治療藥物中，下列那一種最常引起心肌病變（Cardiomyopathy）？","options":["(A) Vincristine","(B) Methotrexate","(C) L-asparaginase","(D) Doxorubicin"],"answer":3,"image":""},{"id":"md4-110-2-27","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"110年第2次第27題","year":110,"session":2,"number":27,"question":"2歲孩童出現眼陣攣—肌陣攣—共濟失調症候群（Opsoclonus-myoclonus-ataxia syndrome)，腹部電腦斷層檢查發現腫瘤，最有可能為下列何種腫瘤？","options":["(A) 威爾姆氏腫瘤（Wilms tumor）","(B) 神經母細胞瘤（Neuroblastoma）","(C) 生殖細胞瘤（Germ cell tumor）","(D) 橫紋肌肉瘤（Rhadomyosarcoma）"],"answer":1,"image":""},{"id":"md4-110-2-28","subject":"md4","topic":"兒科-心血管呼吸","meta":"110年第2次第28題","year":110,"session":2,"number":28,"question":"有關兒童心房中膈缺損（Atrial septal defect，ASD）之敘述，下列何者錯誤？","options":["(A) 單純ASD第二型，觸診除了有右心室挺舉（Heave）現象外，常可摸到心音震顫（thrill）","(B) 靜脈竇型（Sinus venous type）ASD常合併部分肺靜脈回流異常（partial anomalous pulmonary venous return）","(C) ASD若不處理，成年後常可見心房心律不整（Atrial dysrhythmia）","(D) 大部分的第二型ASD可考慮免開刀而施行心導管經皮栓塞術（Device occlusion）"],"answer":0,"image":""},{"id":"md4-110-2-29","subject":"md4","topic":"兒科-心血管呼吸","meta":"110年第2次第29題","year":110,"session":2,"number":29,"question":"有關風濕熱（Rheumatic fever）敘述，下列何者錯誤？","options":["(A) 致病機轉可能是自體免疫（Autoimmunity）導致","(B) 多發性關節炎（Polyarthritis）為最常見，主要是侵犯小關節","(C) 侵犯心臟，以二尖瓣最常見，肺動脈瓣則少見","(D) 皮下結節是在關節伸側面，且不會有壓痛"],"answer":1,"image":""},{"id":"md4-110-2-30","subject":"md4","topic":"兒科-心血管呼吸","meta":"110年第2次第30題","year":110,"session":2,"number":30,"question":"法洛氏四重症（Tetrology of Fallot）的病童，最少發生下列何種併發症？","options":["(A) 腦血栓（Cerebral thromboses）","(B) 感染性心內膜炎（Infective endocarditis）","(C) 鬱血性心衰竭（Congestive heart failure）","(D) 腦膿瘍（Brain abscess）"],"answer":2,"image":""},{"id":"md4-110-2-31","subject":"md4","topic":"兒科-內分泌遺傳","meta":"110年第2次第31題","year":110,"session":2,"number":31,"question":"兒童時期發生肥胖容易在青少年期併發糖尿病，此類情況為某些特定遺傳疾病之主要表徵，下列何者疾病最不可能？","options":["(A) Alstrom syndrome","(B) Bardet-Biedl syndrome","(C) McCune-Albright syndrome","(D) Prader-Willi syndrome -+"],"answer":2,"image":""},{"id":"md4-110-2-32","subject":"md4","topic":"兒科-內分泌遺傳","meta":"110年第2次第32題","year":110,"session":2,"number":32,"question":"出生7天大嬰兒吐奶、吸奶無力，血液檢查pH值為7.21，pCO2：24 torr，HCO3：12 mEq/L，Na：140 mEq/L， + K：5.6 mEq/L。尿液之ketone bodies為陽性，病嬰身上則有一種臭腳味。此病嬰最有可能為下列何種疾病？","options":["(A) 苯酮尿症（Phenylketonuria）","(B) 中鏈脂肪酸去氫酶缺乏症（Medium-chain acyl CoA dehydrogenase deficiency）","(C) 戊二酸尿症第一型（Glutaric aciduria type I）","(D) 異戊酸血症（Isovaleric acidemia）"],"answer":3,"image":""},{"id":"md4-110-2-33","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"110年第2次第33題","year":110,"session":2,"number":33,"question":"有關DiGeorge syndrome的敘述，下列何者錯誤？","options":["(A) 染色體22q11.2微小缺失（Microdeletion）","(B) 腭咽畸形（Velopharyngeal incompetence）","(C) 胸腺發育異常（Hypoplasia of the thymus）","(D) 高血鈣（Hypercalcemia）"],"answer":3,"image":""},{"id":"md4-110-2-34","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"110年第2次第34題","year":110,"session":2,"number":34,"question":"30歲女性，在軀幹出現一個直徑約5公分的紅斑，如圖所示，發生病灶前她曾因經痛自行服用diclofenac；半年前她也曾服用該藥而在相同部位出現相似皮疹。最適當的診斷為：","options":["(A) 多形性紅斑","(B) 固定藥物疹","(C) 遠心性環狀紅斑","(D) 自體免疫水疱症"],"answer":1,"image":"md4-110-2-34.jpeg"},{"id":"md4-110-2-35","subject":"md4","topic":"皮膚-腫瘤","meta":"110年第2次第35題","year":110,"session":2,"number":35,"question":"關於基底細胞癌（basal cell carcinoma）的敘述，下列何者錯誤？","options":["(A) 好發於頭頸部","(B) 好發於老年人","(C) 極易轉移到內臟器官","(D) 可以考慮莫氏切除手術（Mohs micrographic surgery）"],"answer":2,"image":""},{"id":"md4-110-2-36","subject":"md4","topic":"皮膚-腫瘤","meta":"110年第2次第36題","year":110,"session":2,"number":36,"question":"中年男性主訴自兩個月前起，臉上有一快速增生的腫瘤，理學檢查發現在病患的右臉頰，有一個約2公分的暗紅色結節，結節的周圍突起，中央略微凹陷呈火山口狀，內有角質堆質，如圖所示。此病患最可能罹患下列何者？","options":["(A) 角質棘皮瘤（keratoacanthoma）","(B) 黑色素細胞瘤（melanoma）","(C) 基底細胞癌（basal cell carcinoma）","(D) 鱗狀細胞癌（squamous cell carcinoma）"],"answer":0,"image":"md4-110-2-36.jpeg"},{"id":"md4-110-2-37","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"110年第2次第37題","year":110,"session":2,"number":37,"question":"關於尋常型天疱瘡（pemphigus vulgaris）的敘述，下列何者錯誤？","options":["(A) 好犯部位包括口腔黏膜","(B) 病理組織檢查可見水疱發生部位在表皮基底層上方","(C) 病灶的直接免疫螢光檢查，可見IgG沉積於表皮層與真皮層交界處","(D) 自體抗原包括desmogleins"],"answer":2,"image":""},{"id":"md4-110-2-38","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"110年第2次第38題","year":110,"session":2,"number":38,"question":"魚鱗癬﹙ichthyosis﹚主要是皮膚的何種構造異常？","options":["(A) epidermis","(B) dermis","(C) subcutis","(D) sweat gland"],"answer":0,"image":""},{"id":"md4-110-2-39","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"110年第2次第39題","year":110,"session":2,"number":39,"question":"有關脂漏性皮膚炎（seborrheic dermatitis）的敘述，下列何者錯誤？","options":["(A) 治療中不會考慮到使用外用抗黴菌製劑","(B) 遇到難以控制的脂漏性皮膚炎患者，醫師須考慮病人感染HIV的可能性","(C) 遇到難以控制的脂漏性皮膚炎患者，醫師須考慮病人罹患乾癬的可能性","(D) Parkinson's disease可能會加重脂漏性皮膚炎的臨床症狀"],"answer":0,"image":""},{"id":"md4-110-2-40","subject":"md4","topic":"皮膚-感染","meta":"110年第2次第40題","year":110,"session":2,"number":40,"question":"35歲男性，腋下出現如圖所示的搔癢皮疹，使用外用抗黴菌藥物治療三週仍沒有進步。經醫師執行KOH皮屑染色為陰性，使用伍氏燈（Wood's lamp）照射呈現珊瑚紅螢光反應。下列敘述何者正確？","options":["(A) 伍氏燈呈現的螢光反應是因為coproporphyrin III所導致","(B) 正確診斷為對磨疹（intertrigo）","(C) 正確診斷為體癬（tinea corporis）","(D) 治療以外用類固醇藥膏為主"],"answer":0,"image":"md4-110-2-40.jpeg"},{"id":"md4-110-2-41","subject":"md4","topic":"皮膚-感染","meta":"110年第2次第41題","year":110,"session":2,"number":41,"question":"下列那種黴菌感染症，在免疫不全病患最為常見？","options":["(A) aspergillosis","(B) candidiasis","(C) zygomycosis","(D) cryotococcosis"],"answer":1,"image":""},{"id":"md4-110-2-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"110年第2次第42題","year":110,"session":2,"number":42,"question":"有關類天疱瘡（bullous pemphigoid）的敘述，下列何者正確？","options":["(A) Pemphigoid好發於30-50歲患者，或是患有腦中風或中樞神經病變之患者","(B) 重症肌無力（myathenia gravis）或是胸腺瘤（thymoma）可能發生在半數pemphigoid病患身上，而且這些疾病與pemphigoid兩者病程進展有高度相關性","(C) pemphigoid致病機轉為desmoglein 3抗原與自體抗體結合後，導致表皮細胞解離","(D) bullous pemphigoid無法藉由皮膚切片H&E染色與後天水疱性表皮鬆解症（epidermolysis bullosa acquisita）做區分"],"answer":3,"image":""},{"id":"md4-110-2-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"110年第2次第43題","year":110,"session":2,"number":43,"question":"有關白斑（vitiligo）的敘述，下列何者正確？","options":["(A) 父或母有白斑，其兒女也有白斑的機率大於70%","(B) 波長308nm的紫外光照射治療，可促使黑色素細胞再生","(C) 臉上有白斑，因為陽光中的紫外線對白斑有療效，因此不需要防曬","(D) 白斑常常合併自體免疫疾病，口服類固醇是第一線治療且須長期使用"],"answer":1,"image":""},{"id":"md4-110-2-44","subject":"md4","topic":"神經-中風","meta":"110年第2次第44題","year":110,"session":2,"number":44,"question":"有關腦中風併發症之敘述，下列何者最不恰當？","options":["(A) 腦中風併發症常包括關節僵硬、泌尿道感染、吸入性肺炎、褥瘡","(B) 復健有助於減少腦中風之併發症","(C) 急性期意識不清容易引起吸入性肺炎","(D) 抗憂鬱症藥物對腦中風後併發憂鬱症之病人沒有幫助"],"answer":3,"image":""},{"id":"md4-110-2-45","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"110年第2次第45題","year":110,"session":2,"number":45,"question":"關於ergotamine的敘述，下列何者錯誤？","options":["(A) 是一種beta-adrenergic agonist","(B) 會造成血管收縮","(C) 有血清素受體親和力（serotonin receptor affinity）","(D) 可用來做急性偏頭痛發作時之治療"],"answer":0,"image":""},{"id":"md4-110-2-46","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"110年第2次第46題","year":110,"session":2,"number":46,"question":"關於癲癇發作（epileptic seizures）與昏厥（syncope）的鑑別診斷之描述，下列何者最不適合？","options":["(A) 若有Valsalva maneuver、姿勢性低血壓（orthostatic hypotension）為前導因素，應先考慮昏厥","(B) 若發生前有盜汗（diaphoresis）、倦怠（tiredness），應先考慮癲癇發作","(C) 癲癇發作較常導致舌頭咬傷","(D) 幾秒鐘後立刻回復意識且合併心律不整者，應先考慮昏厥"],"answer":1,"image":""},{"id":"md4-110-2-47","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"110年第2次第47題","year":110,"session":2,"number":47,"question":"15歲女孩，無過去病史，兩年前開始清晨剛睡醒時，偶有全身性僵直陣攣發作（generalized tonic-clonic seizure）及雙手短暫抽動，刷牙時曾因雙手突然抽動而將漱口杯甩掉，也曾在白天時被見到有短暫發呆的情形。下列敘述何者錯誤？","options":["(A) 家族成員中亦可能見到類似之癲癇病人","(B) 每秒4到6次的棘波-慢波（4- to 6-Hz spike waves）及多重棘波（polyspikes）為其特徵性之腦電圖（EEG）表現","(C) 最可能的診斷為青少年肌抽躍癲癇（juvenile myoclonic epilepsy）","(D) 屬於頑固性的次發性全面性癲癇（secondary generalized epilepsy）之一"],"answer":3,"image":""},{"id":"md4-110-2-48","subject":"md4","topic":"神經-中風","meta":"110年第2次第48題","year":110,"session":2,"number":48,"question":"一位76歲婦人突然發生頭暈、口齒不清、聲調嘶啞（hoarseness）、右臉及左側肢體麻木（numbness）、步態不穩及嘔吐等症狀，此婦人最有可能發生病灶的部位在何處？","options":["(A) 中腦（midbrain）","(B) 橋腦（pons）","(C) 延髓（medulla oblongata）","(D) 小腦（cerebellum）"],"answer":2,"image":""},{"id":"md4-110-2-49","subject":"md4","topic":"神經-中風","meta":"110年第2次第49題","year":110,"session":2,"number":49,"question":"最常發生腦靜脈竇栓塞（cerebral venous sinus thrombosis）的血管為何？","options":["(A) 上矢狀竇（superior sagittal sinus）","(B) 下矢狀竇（inferior sagittal sinus）","(C) 橫竇（transverse sinus）","(D) 海綿竇（cavernous sinus）"],"answer":[0,2],"image":"","answer_note":"更正:第49題答Ａ、Ｃ給分"},{"id":"md4-110-2-50","subject":"md4","topic":"神經-失智退化運動障礙","meta":"110年第2次第50題","year":110,"session":2,"number":50,"question":"一位70歲男性因為記憶減退及尿失禁被帶來門診。身體檢查發現他走路變慢，兩腳像是被黏在地上。但並無顫抖，也沒有相關疾病的家族史。核磁共振造影檢查發現兩側腦室變大。此時應該進一步安排下列那一項檢查，最可能幫助診斷的確立？","options":["(A) 檢查亨丁頓舞蹈症（Huntington disease）的基因突變","(B) 做腰椎穿刺引流大量之腦脊髓液","(C) 給與左多巴（levodopa）","(D) 氟化去氧葡萄糖正子斷層造影（2-fluoro-2-deoxy-D-glucose positron emission tomography）"],"answer":1,"image":""},{"id":"md4-110-2-51","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"110年第2次第51題","year":110,"session":2,"number":51,"question":"一位28歲懷孕30週的婦女最近失眠，因為在晚上入睡前會感覺兩腳不舒服，好像有小蟲在爬，讓她很想去動一下，而且在摩擦兩腳或是起來踏步後，會減輕症狀。她最近並未服用任何藥物，身體檢查發現兩腳輕微水腫。此孕婦最可能的診斷是：","options":["(A) 肌肉病變（myopathy）","(B) 不寧腳症候群（restless leg syndrome）","(C) 腳水腫後遺症","(D) 靜坐不能（akathisia）"],"answer":1,"image":""},{"id":"md4-110-2-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"110年第2次第52題","year":110,"session":2,"number":52,"question":"一位55歲男性巴金森氏病（Parkinson disease）病人，在服用多巴胺促效劑（dopamine agonists）之後，出現病態賭博（pathological gambling）的症狀，其最可能是下列那一種神經傳導素接受體被過度刺激的結果所造成？","options":["(A) D1多巴胺接受體","(B) D2多巴胺接受體","(C) D3多巴胺接受體","(D) 5-HT接受體"],"answer":2,"image":""},{"id":"md4-110-2-53","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"110年第2次第53題","year":110,"session":2,"number":53,"question":"30歲健康男性，早晨起床刷牙時發現臉歪到左邊，漱口時水會從右嘴角流出，右眼無法緊閉，右耳殼及耳道較為紅腫，伴有小水泡，且會疼痛。根據病史及臨床症狀，下列敘述何者最適合？","options":["(A) 可能罹患疱疹性三叉神經痛（herpetic trigeminal neuralgia）","(B) 通常預後良好","(C) 需要併用抗病毒藥物（antivirals）及非類固醇消炎藥（non-steroid anti-inflammatory drug, NSAID）治療","(D) 需要使用類固醇（steroids）及抗病毒藥物（antivirals）治療"],"answer":3,"image":""},{"id":"md4-110-2-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"110年第2次第54題","year":110,"session":2,"number":54,"question":"關於粒線體肌病變（mitochondrial myopathies），下列敘述何者錯誤？","options":["(A) 病人幾乎活不過青春期","(B) 以影響近端肌肉無力為主","(C) 測血液中乳酸（lactate）濃度是一種有價值的非侵犯性檢查","(D) 粒線體DNA的突變量要達到一定的閥值才會表現徵狀"],"answer":0,"image":""},{"id":"md4-110-2-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"110年第2次第55題","year":110,"session":2,"number":55,"question":"關於急性發炎性脫髓鞘多發性神經病變症候群（Guillain-Barré syndrome）的敘述，下列何者正確？","options":["(A) 屬於感染性疾病","(B) 大部分病程在2至3個月到達頂點","(C) 典型症狀有肢體無力及感覺異常","(D) 不會有自律神經系統功能異常"],"answer":2,"image":""},{"id":"md4-110-2-56","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"110年第2次第56題","year":110,"session":2,"number":56,"question":"下列有關結節性硬化症（tuberous sclerosis complex）的臨床表現，何者正確？","options":["(A) 臉上出現葡萄酒色的色斑（port-wine facial stain）","(B) 雙側額葉出現腦膜瘤","(C) 眼眶周圍出現heliotrope徵兆","(D) 在腦部出現室管膜巨細胞星形膠質細胞瘤（subependymal giant cell astrocytoma）"],"answer":3,"image":""},{"id":"md4-110-2-57","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"110年第2次第57題","year":110,"session":2,"number":57,"question":"36歲健康女性，因為發燒頭痛數日來到急診。病人意識混亂、頸部僵硬，但腦部電腦斷層檢查無異常。腦脊髓液檢查發現，白血球20個／μL，絕大部分是淋巴球，紅血球有2個／μL，蛋白質45 mg/dL，葡萄糖50 mg/dL，血液中葡萄糖80 mg/dL。最可能的診斷是：","options":["(A) 蜘蛛膜下腔出血（subarachnoid hemorrhage）","(B) 病毒性腦膜炎（viral meningitis）","(C) 真菌性腦膜炎（fungal meningitis）","(D) 細菌性腦膜炎（bacterial meningitis）"],"answer":1,"image":""},{"id":"md4-110-2-58","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"110年第2次第58題","year":110,"session":2,"number":58,"question":"下列何者是自主神經病變時的臨床表徵？","options":["(A) 瞳孔對於光亮和黑暗的調適困難","(B) 從臥姿到站姿時，在3分鐘內心跳的變動每分鐘超過30下","(C) 收縮血壓在躺、坐、臥三種狀態的變化範圍小於10 mmHg","(D) 夜尿次數每個夜晚1～2次"],"answer":0,"image":""},{"id":"md4-110-2-59","subject":"md4","topic":"精神-精神病","meta":"110年第2次第59題","year":110,"session":2,"number":59,"question":"有關思覺失調症（schizophrenia）之敘述，下列何者錯誤？","options":["(A) 腦部結構性變化如腦部灰質減少可能在疾病早期就出現","(B) 思覺失調症患者通常缺乏病識感","(C) 知覺障礙常見有聽幻覺及嗅幻覺","(D) 患者較一般人可能有較多暴力行為（violence），但並沒有較多殺人行為（homicide）"],"answer":2,"image":""},{"id":"md4-110-2-60","subject":"md4","topic":"精神-精神病","meta":"110年第2次第60題","year":110,"session":2,"number":60,"question":"有關雙相情緒障礙症（bipolar disorder）之病因，下列敘述何者錯誤？","options":["(A) 有研究指出雙相情緒障礙症之家人成員之自殺身亡比率較一般人高","(B) 雙胞胎研究指出單卵雙胞胎之共病率有70～90%，而同性別異卵雙胞胎為16～35%","(C) 目前基因研究指出有幾個基因之位置與此病症相關，在第18對染色體長臂及第22對染色體長臂被認為是較相關之區域","(D) 目前研究顯示環境因素可以解釋其病因之70%，生物體質病因大約為30%"],"answer":[1,3],"image":"","answer_note":"更正:第60題答Ｂ、Ｄ給分"},{"id":"md4-110-2-61","subject":"md4","topic":"精神-精神病","meta":"110年第2次第61題","year":110,"session":2,"number":61,"question":"有關雙相情緒障礙症（bipolar disorder）之治療，下列敘述何者錯誤？","options":["(A) 抗精神病藥物近年來可使用於治療躁症發作","(B) 抗精神病藥物也可被使用於難治型憂鬱之輔助治療","(C) 抗精神病藥物副作用包括有肥胖、錐體外徑路症候群等","(D) 尚未有證據顯示抗精神病藥物可使用於預防性之維持治療"],"answer":3,"image":""},{"id":"md4-110-2-62","subject":"md4","topic":"精神-器質性與物質使用","meta":"110年第2次第62題","year":110,"session":2,"number":62,"question":"王爺爺是一位85歲長者，罹患末期肝癌，住院中發現有嚴重的視幻覺、被害妄想、合併行為症狀，診斷為譫妄（delirium），下列關於譫妄的治療何者錯誤？","options":["(A) 老年人產生譫妄時若不及時診斷並治療，其致死率高","(B) 低劑量抗精神病藥物haloperidol常用於短期控制譫妄病人的嚴重精神症狀","(C) 在一般臨床情境中，治療譫妄病人失眠症狀的苯二氮平類（benzodiazepine）藥物選擇，宜優先使用長效型藥物","(D) 譫妄之首要治療目標是治療造成其譫妄症狀之潛在病因"],"answer":2,"image":""},{"id":"md4-110-2-63","subject":"md4","topic":"精神-精神官能症","meta":"110年第2次第63題","year":110,"session":2,"number":63,"question":"有關睡眠衛教（sleep hygiene）的敘述，下列何者錯誤？","options":["(A) 白天應減少臥床的時間","(B) 睡不著時應避免看鐘錶檢查時間","(C) 晚上失眠不應利用白天補眠","(D) 謹慎使用安眠藥做為第一線治療"],"answer":3,"image":""},{"id":"md4-110-2-64","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"110年第2次第64題","year":110,"session":2,"number":64,"question":"一位國三女學生，原本身高151公分、體重45公斤，因罹患厭食症（anorexia nervosa）而在幾個月內暴瘦到31公斤，後來猝死，經媒體報導，震撼校園。關於飲食相關疾患的臨床表徵以及其內外科合併症的敘述，下列何者錯誤？","options":["(A) 厭食症會造成大腦萎縮、腦室擴大","(B) 因目前體重未達理想體重之70%，建議於小兒科病房住院治療","(C) 厭食症會造成低血糖（hypoglycemia）、高膽固醇（hypercholesterolemia）","(D) 暴食症（bulimia nervosa）會因為患者使用催吐藥emetine（ipecac）而造成心臟和骨骼肌病變（cardiac and skeletal myopathies）"],"answer":1,"image":""},{"id":"md4-110-2-65","subject":"md4","topic":"兒科-內分泌遺傳","meta":"110年第2次第65題","year":110,"session":2,"number":65,"question":"一位研究所博士生，身高150公分、體重94公斤、BMI達42，合併多囊性卵巢症候群及糖尿病。在醫師的建議之下，接受外科治療。術後3個月後，個案內分泌指數大幅改善，糖化血色素值（HbA1C）也降到5.8，糖尿病因此痊癒。然而術後1年，個案的體重又復發到98公斤。關於病態肥胖（morbid obesity）及減重手術（bariatric surgery）之敘述，下列何者錯誤？","options":["(A) 病態肥胖的治療必需先排除染色體異常（例如Prader-Willi syndrome）或代謝相關疾病（例如Cushing's syndrome）","(B) 病態肥胖有可能是起因於精神疾病或精神疾病藥物治療的副作用","(C) 減重手術常見的胃繞道手術，美國糖尿病學會也將減重手術列為第二型糖尿病人的治療策略","(D) 術後補充Vitamin B12和鐵劑，就足以減少復胖"],"answer":3,"image":""},{"id":"md4-110-2-66","subject":"md4","topic":"精神-精神官能症","meta":"110年第2次第66題","year":110,"session":2,"number":66,"question":"有關zolpidem和zopiclone類藥物的敘述，下列何者錯誤？","options":["(A) 是新興的安眠藥物，在GABA receptor作用上選擇性比benzodiazepine（BZD）高，不易成癮","(B) zolpidem和zopiclone類藥物會造成失憶、睡眠自動化行為（automatic behaviors）和幻覺","(C) 失眠常有潛在的生理或心理疾病，使用zolpidem和BZD類藥物是「治標不治本」，只能暫時緩和症狀","(D) 沒有任何醫學研究支持長期使用短效型zolpidem和BZD類藥物來治療失眠"],"answer":[0,3],"image":"","answer_note":"更正:第66題答Ａ、Ｄ給分。"},{"id":"md4-110-2-67","subject":"md4","topic":"精神-器質性與物質使用","meta":"110年第2次第67題","year":110,"session":2,"number":67,"question":"阿正描述自己使用海洛因的歷程中的感受：甲、第一次使用海洛因時吐得很厲害，難受得很乙、再繼續使用幾次後，開始會想念使用海洛因後輕鬆無憂慮的感受丙、繼續使用一段時間後，反覆靜脈注射導致感染急性肝炎丁、使用一段時間後，發現和太太吵架後心情不好時，注射海洛因能平撫煩躁的心情下列敘述何者正確？ ћ甲具有嫌惡作用，可能會降低海洛因成癮的危險性 ќ乙具有引發愉悅情緒作用，可能會增加海洛因成癮的危險性 ѝ丙會導致負向身體狀況，可能會降低海洛因成癮的危險性 ў丁具有降低負向情緒作用，可能會增加海洛因成癮的危險性","options":["(A) 僅ћќѝ","(B) 僅ћќў","(C) 僅ќѝў","(D) ћќѝў"],"answer":3,"image":""},{"id":"md4-110-2-68","subject":"md4","topic":"精神-器質性與物質使用","meta":"110年第2次第68題","year":110,"session":2,"number":68,"question":"有關酒精使用引起之症狀與影響，下列敘述何者錯誤？","options":["(A) 酒精中毒會影響情緒行為或動作，並不會有死亡風險","(B) 血中酒精濃度愈高，平衡受損（incoordination）、情緒不穩，甚而認知缺損的情況愈更明顯","(C) 若在高濃度時（如150 mg/dL或是0.15%以上），仍無動作或情緒不穩問題，則可能表示對酒精已出現耐受性","(D) 血中酒精濃度大於30 mg/dL（或是0.03%），大約是吐氣酒精濃度0.15 mg/L，即可能減慢動作與思考反應，依「道路交通安全規則」規定，不得駕車"],"answer":0,"image":""},{"id":"md4-110-2-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"110年第2次第69題","year":110,"session":2,"number":69,"question":"有關認知障礙症（major neurocognitive disorder）之診斷條件，下列敘述何者錯誤？","options":["(A) 其認知障礙包含六大範疇：複雜注意力、社交認知、語言功能、知覺－動作、學習記憶、執行功能","(B) 診斷輕型認知障礙症（mild neurocognitivve disorder）之認知缺損須達干擾其日常活動獨立進進行","(C) 輕型認知障礙症（mild neurocognitive dissorder）之認知缺損非只出現於譫妄情境","(D) 認知缺損無法以另一精神疾病作更好的的解釋（例如：重鬱症、思覺失調症）"],"answer":1,"image":""},{"id":"md4-110-2-70","subject":"md4","topic":"精神-精神官能症","meta":"110年第2次第70題","year":110,"session":2,"number":70,"question":"關於鎮靜安眠藥物的敘述，下列何者錯誤誤？","options":["(A) 苯二氮平（benzodiazepines）和巴比妥類類藥物（barbiturates）與受器結合後是作用在同樣的的離子通道","(B) 苯二氮平（benzodiazepines）使用超過兩兩週可能出現耐受性","(C) zolpidem目前在臨床上發現並無任何耐受受性或戒斷問題","(D) zolpidem較無肌肉鬆弛效果"],"answer":2,"image":""},{"id":"md4-110-2-71","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"110年第2次第71題","year":110,"session":2,"number":71,"question":"有關自閉症類群障礙症（autism spectrum ddisorder, ASD），下列敘述何者正確？","options":["(A) 根據DSM-5診斷準則，ASD的症狀分成成三大範圍（domains），包括社交溝通障礙、侷限限與重複行為和語言發展障礙","(B) ASD的症狀一般在四歲左右出現","(C) ASD患者若智力功能正常，而且語言功功能只有輕度障礙，則可能到兒童中期（middle chiildhood）才會被發現","(D) 符合DSM-5的ASD診斷準則的患者，有有四分之三同時合併有輕度智能不足（mild intellectual disability）"],"answer":2,"image":""},{"id":"md4-110-2-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"110年第2次第72題","year":110,"session":2,"number":72,"question":"有關妥瑞氏症（Tourette's disorder）之敘述述，下列何者錯誤？","options":["(A) 通常在15歲之後發生","(B) 常見的症狀為多重動作抽搐及一種或多多種的發聲抽搐","(C) 男性的發生率高於女性","(D) 常合併注意力不足／過動症或強迫症症症狀"],"answer":0,"image":""},{"id":"md4-110-2-73","subject":"md4","topic":"精神-精神官能症","meta":"110年第2次第73題","year":110,"session":2,"number":73,"question":"具有下列何種特質的個案不適合接受心理理分析（psychoanalysis）治療？","options":["(A) 低動機（low motivation）","(B) 建立關係的能力（ability to form a relationnship）","(C) 洞察力（capacity for insight）","(D) 充分的自我強度（ego strength）"],"answer":0,"image":""},{"id":"md4-110-2-74","subject":"md4","topic":"兒科-感染神經","meta":"110年第2次第74題","year":110,"session":2,"number":74,"question":"32歲女性患者有癲癇、心智遲緩的病史，接受電腦斷層檢查，2張圖分別是未注射顯影劑劑的不同切面影像，下列何者是最可能的診斷？","options":["(A) 結節硬化症（tuberous sclerosis）","(B) 神經纖維瘤第一型（neurofibromatosis typpe 1）","(C) 神經纖維瘤第二型（neurofibromatosis typpe 2）","(D) 馮希伯－林島氏症候群（von Hippel-Linndau syndrome）"],"answer":0,"image":"md4-110-2-74.jpeg"},{"id":"md4-110-2-75","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"110年第2次第75題","year":110,"session":2,"number":75,"question":"41歲女性患者，主訴近幾天有頭痛、噁心心和嘔吐症狀，接受電腦斷層檢查，圖A為未注射射顯影劑的影像，圖B則為注射顯影劑後的影像，在圖B箭頭頭所指的是：","options":["(A) 硬腦膜下血腫（subdural hematoma）","(B) 蜘蛛網膜下腔出血（subarachnoid hemorrrhage）","(C) 硬腦膜外血腫（epidural hematoma）","(D) 靜脈竇栓塞（venous sinus thrombosis）"],"answer":3,"image":"md4-110-2-75.jpeg"},{"id":"md4-110-2-76","subject":"md4","topic":"兒科-心血管呼吸","meta":"110年第2次第76題","year":110,"session":2,"number":76,"question":"關於呼吸道梗塞的急救方法，下列敘述何何者錯誤？","options":["(A) 有意識情況下，成人可以使用哈姆立克克法急救","(B) 若小孩失去意識，單人施救以30：2的的循環開始CPR","(C) 有意識情況下，嬰兒（1歲以下）也可以以使用哈姆立克法急救","(D) 若嬰兒失去意識且沒脈搏，單人施救以以30：2的循環開始CPR"],"answer":2,"image":""},{"id":"md4-110-2-77","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"110年第2次第77題","year":110,"session":2,"number":77,"question":"一位6歲兒童約重20 kg，因車禍至急診，血壓量不到，在急救時應立即靜脈注射生理食鹽鹽水（0.9% NaCl），其劑量為：","options":["(A) 10 mL/kg","(B) 15 mL/kg","(C) 20 mL/kg","(D) 25 mL/kg"],"answer":2,"image":""},{"id":"md4-110-2-78","subject":"md4","topic":"神經-失智退化運動障礙","meta":"110年第2次第78題","year":110,"session":2,"number":78,"question":"有關急性肌張力不全症（acute dystonia）之之敘述，下列何者錯誤？","options":["(A) 常見於antipsychotic治療之副作用","(B) 可以用diphenhydramine靜脈治療","(C) 肌肉抽筋（spasm）主要發生於四肢","(D) 較常發生於年輕人"],"answer":2,"image":""},{"id":"md4-110-2-79","subject":"md4","topic":"醫學倫理與法規","meta":"110年第2次第79題","year":110,"session":2,"number":79,"question":"臨床試驗進行前應有之考量，下列那幾項項正確？ћ應權衡對個別受試者及整體社會之可能能風險、不便及預期利益 ќ預期利益應超過可能風險及不便便，始得進行試驗 ѝ受試者之權利、安全及福祉祉為藥品臨床試驗之最重要考量，且應勝於科學及社會之利益益 ў人體試驗委員會應確保受試者之權利、安全全以及福祉受到保護","options":["(A) ћќѝў","(B) 僅ћѝў","(C) 僅ћќў","(D) 僅ћќѝ"],"answer":0,"image":""},{"id":"md4-110-2-80","subject":"md4","topic":"醫學倫理與法規","meta":"110年第2次第80題","year":110,"session":2,"number":80,"question":"林同學是17歲的高中生，因為看到媽媽飽受癌症末期治療的痛苦，林同學自己想要預立選擇安寧緩和醫療意願書，是否合乎安寧緩和醫療條例之規定？","options":["(A) 可以，因為只要是中華民國國民就可以","(B) 可以，因為林同學已經具備自立遺囑的能力","(C) 不可以，必須要20歲以上具完全行為能力之人","(D) 不可以，必須要已經診斷確定是末期病人才行"],"answer":2,"image":""},{"id":"md4-111-1-1","subject":"md4","topic":"兒科-感染神經","meta":"111年第1次第1題","year":111,"session":1,"number":1,"question":"5歲男童高燒3天合併畏寒，咳嗽、喉嚨痛、頭痛、雙小腿痠痛、活動力下降，流感快篩呈現B型流感陽性。有關流行性感冒病毒的疫苗接種及治療敘述，何者錯誤？","options":["(A) 流感疫苗只能施打在年紀1歲以上的孩童","(B) 8歲以下初次接種流感疫苗的孩童，間隔1個月後須再施打第二劑","(C) 可以考慮給與對抗流感藥物，如Neuraminidase inhibitor治療","(D) 流感病毒感染抽血檢驗時可能會見到白血球偏低"],"answer":0,"image":""},{"id":"md4-111-1-2","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"111年第1次第2題","year":111,"session":1,"number":2,"question":"關於新生兒感染巨細胞病毒（Cytomegalovirus）的敘述，下列何者錯誤？","options":["(A) 受到先天性巨細胞病毒感染的足月新生兒，約有90%會有臨床症狀","(B) 足月健康的新生兒，即使母親血清反應陽性仍可哺餵母乳","(C) 臨床症狀為肝脾腫大、黃疸、紅疹等","(D) 對於沒有通過聽力篩檢的新生兒，須考慮先天性巨細胞病毒感染之可能性"],"answer":0,"image":""},{"id":"md4-111-1-3","subject":"md4","topic":"兒科-感染神經","meta":"111年第1次第3題","year":111,"session":1,"number":3,"question":"下列何者是學齡兒童細菌性咽喉炎最常見的病原？","options":["(A) 嗜血桿菌（Haemophilus influenzae）","(B) A型鏈球菌（Group A streptococcus）","(C) 肺炎黴漿菌（Mycoplasma pneumoniae）","(D) 肺炎鏈球菌（Streptococcus pneumoniae）"],"answer":1,"image":""},{"id":"md4-111-1-4","subject":"md4","topic":"兒科-感染神經","meta":"111年第1次第4題","year":111,"session":1,"number":4,"question":"下列何者不是腸病毒（Enteroviruses）感染的典型表現？","options":["(A) 手足口症（Hand-foot-and-mouth disease）","(B) 腦炎（Encephalitis）","(C) 骨髓炎（Osteomyelitis）","(D) 心肌炎（Myocarditis）"],"answer":2,"image":""},{"id":"md4-111-1-5","subject":"md4","topic":"兒科-感染神經","meta":"111年第1次第5題","year":111,"session":1,"number":5,"question":"下列何者是2歲兒童罹患感冒（Common cold）後最常見的併發症？","options":["(A) 急性中耳炎","(B) 細菌性肺炎","(C) 急性鼻竇炎","(D) 腦膜炎"],"answer":0,"image":""},{"id":"md4-111-1-6","subject":"md4","topic":"兒科-感染神經","meta":"111年第1次第6題","year":111,"session":1,"number":6,"question":"下列何種肺炎鏈球菌疫苗的製程機轉，明顯與其他三種疫苗不同？","options":["(A) 7價","(B) 10價","(C) 13價","(D) 23價"],"answer":3,"image":""},{"id":"md4-111-1-7","subject":"md4","topic":"兒科-內分泌遺傳","meta":"111年第1次第7題","year":111,"session":1,"number":7,"question":"下列何種檢查較不適宜用於單基因疾病（Single genetic disease）的分子診斷（Molecular diagnosis）？","options":["(A) Linkage analysis","(B) array Comparative Genomic Hybridization（aCGH）","(C) DNA sequence-based analysis","(D) Fluorescence in situ hybridization（FISH）"],"answer":3,"image":""},{"id":"md4-111-1-8","subject":"md4","topic":"兒科-內分泌遺傳","meta":"111年第1次第8題","year":111,"session":1,"number":8,"question":"下列新生兒的肢體表現（如附圖），最可能是那一種診斷？","options":["(A) Down syndrome","(B) Edwards syndrome","(C) Neonatal Marfan syndrome","(D) Spinal muscular atrophy"],"answer":1,"image":"md4-111-1-8.jpeg"},{"id":"md4-111-1-9","subject":"md4","topic":"兒科-內分泌遺傳","meta":"111年第1次第9題","year":111,"session":1,"number":9,"question":"對於葡萄糖-六-磷酸鹽脫氫酵素缺乏症（G-6-PD缺乏症，俗稱蠶豆症）患者，下列何者可正常使用，不需特別避免？","options":["(A) 乙醯胺酚（Acetaminophen）","(B) 龍膽紫（Gentian violet）","(C) 萘丸（Naphthalene）","(D) 磺胺劑（Sulfa drug）"],"answer":0,"image":""},{"id":"md4-111-1-10","subject":"md4","topic":"兒科-內分泌遺傳","meta":"111年第1次第10題","year":111,"session":1,"number":10,"question":"5歲男童因常出現魚腥體味而就診，出生時基本新生兒篩檢並無異常，身體診察亦無特殊發現，父母描述這種刺鼻味道只在吃了蛋黃或豬肝後出現，下列何種疾病為最可能之診斷？","options":["(A) 異戊酸血症（Isovaleric acidemia）","(B) 苯酮尿症（Phenylketonuria）","(C) 三甲基胺尿症（Trimethylaminuria）","(D) 酪胺酸血症（Tyrosinemia）"],"answer":2,"image":""},{"id":"md4-111-1-11","subject":"md4","topic":"兒科-消化系統疾病","meta":"111年第1次第11題","year":111,"session":1,"number":11,"question":"新生兒出生1天後開始出現嘔吐症狀，嘔吐物含膽汁。身體診察發現腹部平坦，腹部X光片（如附圖）顯示中腹有3團腸氣而其他部位無腸氣出現。下列何者為最可能之診斷？","options":["(A) 胃幽門狹窄（Pyloric stenosis）","(B) 十二指腸閉鎖（Duodenal atresia）","(C) 空腸閉鎖（Jejunal atresia）","(D) 迴腸閉鎖（Ileum atresia）"],"answer":2,"image":"md4-111-1-11.jpeg"},{"id":"md4-111-1-12","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"111年第1次第12題","year":111,"session":1,"number":12,"question":"39週出生體重2,200公克的新生兒，在出生後第2個小時出現手腳震顫（Jitteriness）現象，當下檢驗血糖值為20 mg/dL。有關後續的處置，下列何者最為恰當？","options":["(A) 2小時大時本來血糖就是最低值，可觀察下一個血糖值再做下一步決定","(B) 配合母嬰親善政策，應儘快讓母親以母乳哺餵新生兒","(C) 應先靜脈注射葡萄糖一次，接著再以葡萄糖輸注液緩慢滴注","(D) 應置放臍靜脈導管後，以高濃度葡萄糖輸注液滴注"],"answer":2,"image":""},{"id":"md4-111-1-13","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"111年第1次第13題","year":111,"session":1,"number":13,"question":"一位母親急產下一個2,000公克的新生兒。詢問母親病史，她懷孕過程未接受過產檢，也不知最後一次月經是什麼時候。如果要以新生兒狀況來做週數預估，則評估判斷的內容不包括下列何項？","options":["(A) 眼睛到耳朵的距離","(B) 乳頭與乳暈大小","(C) 胎毛稀疏程度","(D) 腳掌橫紋紋路"],"answer":0,"image":""},{"id":"md4-111-1-14","subject":"md4","topic":"兒科-消化系統疾病","meta":"111年第1次第14題","year":111,"session":1,"number":14,"question":"剛出生的36週大嬰兒，嘴角一直流口水並冒出泡泡，醫師無法將口胃管順利放入。腹部X光片可見有胃與腸氣。下列何者為最可能之診斷？","options":["(A) 單純食道氣管瘻管","(B) 上段食道閉鎖合併下段食道氣管瘻管","(C) 下段氣管閉鎖合併上段食道氣管瘻管","(D) 上段氣管閉鎖合併下段食道氣管瘻管"],"answer":1,"image":""},{"id":"md4-111-1-15","subject":"md4","topic":"兒科-消化系統疾病","meta":"111年第1次第15題","year":111,"session":1,"number":15,"question":"下列何種疾病所導致的嘔吐為非膽汁性嘔吐（Nonbilious emesis）？","options":["(A) 增生性胃幽門狹窄（Hypertrophic pyloric stenosis）","(B) 十二指腸閉鎖（Duodenal atresia）","(C) 腸道旋轉不良合併扭轉（Intestinal malrotation with volvulus）","(D) 先天性巨結腸症（Hirschsprung disease）"],"answer":0,"image":""},{"id":"md4-111-1-16","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"111年第1次第16題","year":111,"session":1,"number":16,"question":"關於嬰幼兒常見造成維生素及營養素缺乏的原因，下列何者正確？","options":["(A) 相較於一般飲食的兒童，吃全素的兒童容易缺乏維生素B12及維生素D","(B) 相較於餵配方奶的嬰幼兒，餵母乳的嬰幼兒不容易缺乏維生素K","(C) 相較於餵母乳的嬰幼兒，餵配方奶的嬰幼兒容易缺乏鐵質和維生素D","(D) 膽汁淤積症的病童容易缺乏水溶性維生素及維生素B群"],"answer":0,"image":""},{"id":"md4-111-1-17","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"111年第1次第17題","year":111,"session":1,"number":17,"question":"關於嬰幼兒生長遲滯（Failure to thrive）的敘述，下列何者錯誤？","options":["(A) 發生營養不良時首先造成體重增加不良，幾個月後才會影響到身高","(B) 有超過一半以上生長遲滯的病童，經門診或住院檢查可找出病因","(C) 為了追趕性生長所需，其熱量和蛋白質的攝取可能需達同年齡層兒童的1.5倍","(D) 進入追趕性生長期的前兩週，其體重增加的速度可比同年齡層兒童多出2到3倍"],"answer":1,"image":""},{"id":"md4-111-1-18","subject":"md4","topic":"兒科-消化系統疾病","meta":"111年第1次第18題","year":111,"session":1,"number":18,"question":"1個月大全母奶餵哺的男嬰因為延長性黃疸（prolonged jaundice）被帶至門診，下列處置何者正確？","options":["(A) 告知家屬此為母乳性黃疸，可先暫停哺餵母乳2天，無需採取腳跟微量血檢測總膽紅素值","(B) 若家屬表示男嬰的大便顏色為淡黃色，可暫時不採取腳跟血檢測總膽紅素值，觀察即可","(C) 若採取腳跟血檢測直接與總膽紅素值之比例（Direct-to-total bilirubin）為3%，總膽紅素值12 mg/dL，最好住院照光治療","(D) 若採取腳跟血檢測直接與總膽紅素值之比例（Direct-to-total bilirubin）為21%，總膽紅素值10 mg/dL，應儘快轉診或住院檢查"],"answer":3,"image":""},{"id":"md4-111-1-19","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"111年第1次第19題","year":111,"session":1,"number":19,"question":"7個月大的男嬰因發燒、嘔吐和大量水樣性腹瀉持續3天之久而來急診。經量測，體重為7.5公斤（上個月預防注射時體重8公斤），嘴唇乾裂，尿量減少，哭沒有眼淚。常規血液檢查正常，血液生化檢查中電解質正常，糞便檢查正常，目前哺育母乳，以下何種處置最為適當？","options":["(A) 給與稀釋運動飲料500c.c.於4小時內喝完","(B) 停止哺餵母乳，給與無乳糖配方奶","(C) 給與止瀉藥如Loperamide（Imodium）","(D) 矯正脫水後立刻給與進食（Early feeding）"],"answer":3,"image":""},{"id":"md4-111-1-20","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"111年第1次第20題","year":111,"session":1,"number":20,"question":"6歲女童為原發性微小腎病變患者，對類固醇反應不好，此次因復發住院，正接受類固醇脈衝治療，今突然發生「泛發性強直–陣攣發作（Generalized tonic-clonic seizures）」，其抽搐原因最不可能是下列何者？","options":["(A) 顱內出血（Intracranial hemorrhage）","(B) 低血鈉（Hyponatremia）","(C) 可逆性後腦病變症候群（Posterior reversible encephalopathy syndrome, PRES）","(D) 腦部血管栓塞（Cerebral venous sinus thrombosis）"],"answer":0,"image":""},{"id":"md4-111-1-21","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"111年第1次第21題","year":111,"session":1,"number":21,"question":"5歲女童接受化學藥物治療一段期間後，發現有輕微蛋白尿與尿糖現象，抽血檢查顯示血中鉀離子為2.8 - mmol/L，鈉離子為146 mmol/L，氯離子為115 mmol/L。血液pH值為7.2，重碳酸根離子（HCO3）為18 mmol/L，BE：-4.5 mmol/L，下列何者為最可能之診斷？","options":["(A) 第四型腎小管酸血症（Renal tubular acidosis, type IV）","(B) Fanconi症候群（Fanconi syndrome）","(C) Bartter氏症候群（Bartter syndrome）","(D) 吉特曼症候群（Gitelman syndrome）"],"answer":1,"image":""},{"id":"md4-111-1-22","subject":"md4","topic":"兒科-感染神經","meta":"111年第1次第22題","year":111,"session":1,"number":22,"question":"下列何者在嬰兒受虐性腦傷中最不常見？","options":["(A) 硬腦膜下出血（Subdural hemorrhage）","(B) 視網膜出血（Retinal hemorrhage）","(C) 腦水腫（Brain edema）","(D) 小腦出血（Cerebellar hemorrhage）"],"answer":3,"image":""},{"id":"md4-111-1-23","subject":"md4","topic":"兒科-感染神經","meta":"111年第1次第23題","year":111,"session":1,"number":23,"question":"下列關於單純型熱性痙攣之處置何者正確？","options":["(A) 為避免復發，建議預防性使用抗癲癇藥","(B) 使用退燒藥物可以降低熱性痙攣再發生的風險","(C) 長期抗癲癇藥物之使用可預防患者未來發生癲癇","(D) 患者不需接受腦電波檢查"],"answer":3,"image":""},{"id":"md4-111-1-24","subject":"md4","topic":"兒科-內分泌遺傳","meta":"111年第1次第24題","year":111,"session":1,"number":24,"question":"11歲女童經醫師確診為甲狀腺功能亢進，下列有關症狀、實驗室檢查及治療之描述何者最不適當？","options":["(A) 食慾會減退","(B) 短期內會快速生長","(C) Free T4 3.2 ng/dL、T4 18.2 μg/dL、TSH＜0.05 mIU/L","(D) 應開始使用Methimazole治療"],"answer":0,"image":""},{"id":"md4-111-1-25","subject":"md4","topic":"兒科-內分泌遺傳","meta":"111年第1次第25題","year":111,"session":1,"number":25,"question":"兒童第一型糖尿病（Type 1 diabetes mellitus, T1DM）與第二型糖尿病相比較，下列何者最不正確？","options":["(A) T1DM病童體型通常較為消瘦","(B) T1DM病童首次發病時，較常合併酮酸中毒","(C) T1DM病童較不常合併其他自體免疫疾病","(D) T1DM病童通常需要注射胰島素治療"],"answer":2,"image":""},{"id":"md4-111-1-26","subject":"md4","topic":"兒科-感染神經","meta":"111年第1次第26題","year":111,"session":1,"number":26,"question":"關於川崎氏症（Kawasaki disease）的描述，下列何者錯誤？","options":["(A) 發生的原因目前仍然不明，但是一些證據顯示可能跟感染有關","(B) 比較常發生在年齡5歲以下的兒童身上","(C) 鑑別診斷包括猩紅熱、麻疹、腺病毒感染、青少年原發性系統型關節炎與藥物過敏等","(D) 急性發燒期治療包括阿斯匹林（Aspirin）5 mg/kg與免疫球蛋白（Immunoglobulin）2 g/kg"],"answer":3,"image":""},{"id":"md4-111-1-27","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"111年第1次第27題","year":111,"session":1,"number":27,"question":"有關兒童異位性皮膚炎（Atopic dermatitis）的臨床表現及照護，下列敘述何者最不恰當？","options":["(A) 在嬰幼兒時期，包尿布區域不是典型好發的部位","(B) 兒童常因為癢的感受而搔抓","(C) 由於皮膚敏感，不建議泡澡保濕","(D) 兒童年紀漸大後，四肢屈側是好發的部位"],"answer":2,"image":""},{"id":"md4-111-1-28","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"111年第1次第28題","year":111,"session":1,"number":28,"question":"有關預防嬰幼兒過敏的觀念，下列敘述何者不恰當？","options":["(A) 孕婦飲食可不需避免高過敏食物（例如海鮮、花生等）","(B) 嬰幼兒6個月大以後再添加副食品可以預防過敏","(C) 母乳哺育對於預防氣喘的效果不確定","(D) 目前國際指引尚未建議嬰幼兒常規性使用益生菌來預防過敏"],"answer":1,"image":""},{"id":"md4-111-1-29","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"111年第1次第29題","year":111,"session":1,"number":29,"question":"下列何者是兒童後天性再生不良性貧血最常見的病因？","options":["(A) 藥物","(B) 不明原因","(C) 化學毒物","(D) 病毒感染"],"answer":1,"image":""},{"id":"md4-111-1-30","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"111年第1次第30題","year":111,"session":1,"number":30,"question":"下列那一項疾病較不會以小球性貧血（Microcytic anemia）來表現？","options":["(A) 缺鐵性貧血（Iron deficiency anemia）","(B) 再生不良性貧血（Aplastic anemia）","(C) 海洋性貧血（Thalassemia）","(D) 鉛中毒（Lead poisoning）"],"answer":1,"image":""},{"id":"md4-111-1-31","subject":"md4","topic":"兒科-心血管呼吸","meta":"111年第1次第31題","year":111,"session":1,"number":31,"question":"9個月大女嬰嘴唇被發現有發紺的現象，經診斷為先天性心臟病法洛氏四重症（Tetralogy of Fallot, TOF）。下列何種機轉是造成病童直到9個月才出現明顯發紺現象？","options":["(A) 動脈導管持續開放","(B) 卵圓孔延遲關閉","(C) 心室中膈缺損產生心臟衰竭","(D) 右心室代償肥厚造成嚴重的肺動脈狹窄"],"answer":3,"image":""},{"id":"md4-111-1-32","subject":"md4","topic":"兒科-心血管呼吸","meta":"111年第1次第32題","year":111,"session":1,"number":32,"question":"2天大的足月新生兒，接受例行性的血氧篩檢時發現雙側下肢的血氧飽和度是90%，但臨床上活動力正常、進食狀況良好，下列那一種先天性心臟病最有可能出現此現象？","options":["(A) 心室中膈缺損（Ventricular septal defect）","(B) 完全型心內膜墊缺損（Complete form endocardial cushion defect）","(C) 大血管轉位（D-transposition of the great arteries）","(D) 開放性動脈導管（Patent ductus arteriosus）"],"answer":2,"image":""},{"id":"md4-111-1-33","subject":"md4","topic":"兒科-心血管呼吸","meta":"111年第1次第33題","year":111,"session":1,"number":33,"question":"有關部分肺靜脈回流異常（Partial anomalous pulmonary venous return）之血行力學變化（Hemodynamic change），與下列何種先天性心臟病較相似？","options":["(A) 心室中隔缺損（Ventricular septal defect）","(B) 心房中隔缺損（Atrial septal defect）","(C) 肺動脈瓣狹窄（Pulmonary valve stenosis）","(D) 開放性動脈導管（Patent ductus arteriosus）"],"answer":1,"image":""},{"id":"md4-111-1-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"111年第1次第34題","year":111,"session":1,"number":34,"question":"關於異位性皮膚炎的敘述，下列何者錯誤？","options":["(A) 皮膚的屏障功能常有缺陷","(B) 皮膚金黃色葡萄球菌菌落數常會增加","(C) 血中IgE上升是診斷必須的生物標記","(D) 臨床病程與情緒壓力及環境有關"],"answer":2,"image":""},{"id":"md4-111-1-35","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"111年第1次第35題","year":111,"session":1,"number":35,"question":"下列何者不會引起落屑性皮膚炎（exfoliative dermatitis）？","options":["(A) 毛囊炎（folliculitis）","(B) 異位性皮膚炎（atopic dermatitis）","(C) 乾癬（psoriasis）","(D) 皮膚T細胞淋巴癌（cutaneous T cell lymphoma）"],"answer":0,"image":""},{"id":"md4-111-1-36","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"111年第1次第36題","year":111,"session":1,"number":36,"question":"有關過敏性接觸性皮膚炎（allergic contact dermatitis）的免疫機轉敘述，下列何者正確？","options":["(A) 接觸過敏原其分子量多大於500 Daltons的親水性物質","(B) 表皮的抗原表現（antigen-presenting）角色主要由藍格罕氏細胞（Langerhans cells）擔任","(C) 淋巴結中的T細胞在受到抗原刺激後會分化成Mast cells，並且會回到皮膚中","(D) 致敏期（sensitization phase）大約需要30~35天，且此時期症狀嚴重"],"answer":1,"image":""},{"id":"md4-111-1-37","subject":"md4","topic":"皮膚-感染","meta":"111年第1次第37題","year":111,"session":1,"number":37,"question":"70歲男性，從四天前右背和右腹出現如圖所示的水疱病變，晚上疼痛無法入睡，他以前未曾長過類似皮疹。最可能的診斷為：","options":["(A) 接觸性皮膚炎（contact dermatitis）","(B) 單純性疱疹（herpes simplex）","(C) 膿痂疹（impetigo）","(D) 帶狀疱疹（herpes zoster）"],"answer":3,"image":"md4-111-1-37.jpeg"},{"id":"md4-111-1-38","subject":"md4","topic":"皮膚-感染","meta":"111年第1次第38題","year":111,"session":1,"number":38,"question":"關於紅癬（erythrasma）的敘述，下列何者錯誤？","options":["(A) 是一種黴菌的感染","(B) Wood's lamp下可以看到珊瑚紅的螢光反應","(C) 主要好犯於腋下或胯下","(D) 臨床上可以有輕微脫屑（fine scales）"],"answer":0,"image":""},{"id":"md4-111-1-39","subject":"md4","topic":"皮膚-腫瘤","meta":"111年第1次第39題","year":111,"session":1,"number":39,"question":"30歲男子發現大腿內側有一個逐漸長大之皮膚腫瘤如圖所示，下列何者為最可能的診斷？","options":["(A) 表皮囊腫（epidermal cyst）","(B) 皮脂腺囊腫（steatocystoma）","(C) 黏液囊腫（mucous cyst）","(D) 纖毛囊腫（vellus hair cyst）"],"answer":0,"image":"md4-111-1-39.jpeg"},{"id":"md4-111-1-40","subject":"md4","topic":"皮膚-腫瘤","meta":"111年第1次第40題","year":111,"session":1,"number":40,"question":"承上題，當病人身上有此種多發性腫瘤，同時罹患大腸息肉及甲狀腺癌，要考慮下列何種遺傳性疾病？","options":["(A) Carney complex","(B) Cowden syndrome","(C) Proteus syndrome","(D) Gardner syndrome"],"answer":3,"image":""},{"id":"md4-111-1-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"111年第1次第41題","year":111,"session":1,"number":41,"question":"45歲男性，頸部皮膚出現脫屑性萎縮皮疹已有半年，皮屑KOH染色為陰性。皮膚切片發現表皮萎縮、毛孔角質瘀塞、基底細胞液樣變性（hydropic degeneration）、毛囊周圍淋巴球浸潤，直接免疫螢光染色在表皮真皮交接處出現IgG線性沈積。何者為最可能的診斷？","options":["(A) 皮膚淋巴癌（cutaneous lymphoma）","(B) 皮膚類肉瘤（sarcoidosis）","(C) 盤狀紅斑性狼瘡（discoid lupus erythematosus）","(D) 亞急性皮膚紅斑性狼瘡（subacute cutaneous lupus erythematosus）"],"answer":2,"image":"md4-111-1-41.jpeg"},{"id":"md4-111-1-42","subject":"md4","topic":"皮膚-腫瘤","meta":"111年第1次第42題","year":111,"session":1,"number":42,"question":"關於脂漏性角化症（seborrheic keratosis）的敘述，何者錯誤？","options":["(A) 脂漏性角化症為一種原位癌的皮膚疾病","(B) 日曬可能是造成此疾病的原因之一","(C) 好發於老年人","(D) 若短期間內出現大量脂漏性角化症病灶，稱為Leser-Trélat sign；需注意是否合併其他惡性疾患（如胃癌）"],"answer":0,"image":""},{"id":"md4-111-1-43","subject":"md4","topic":"兒科-消化系統疾病","meta":"111年第1次第43題","year":111,"session":1,"number":43,"question":"14歲女生血便，身體診察發現嘴唇有黑色斑點如圖所示。下列敘述何者正確？","options":["(A) 自體隱性遺傳","(B) 黏膜黑斑多在成年後才會開始出現","(C) 常伴發胃腸道、生殖系統和其他器官的良性或惡性腫瘤","(D) 胃腸道如有息肉，常發生在大腸"],"answer":2,"image":"md4-111-1-43.jpeg"},{"id":"md4-111-1-44","subject":"md4","topic":"神經-中風","meta":"111年第1次第44題","year":111,"session":1,"number":44,"question":"65歲婦女，因突發複視（diplopia）來求診。神經學檢查顯示：當患者看向左邊，右眼無法內收（adduction），而左眼可以完全外展（abduction）且合併眼球震顫（nystagmus）。當眼睛往右邊或上面或下面看時，兩眼的轉動均正常。最可能的病灶位置在：","options":["(A) 左邊內側縱向束（left medial longitudinal fasciculus）","(B) 右邊內側縱向束（right medial longitudinal fasciculus）","(C) 左邊正中旁橋腦網狀結構（left paramedian pontine reticular formation）","(D) 右邊正中旁橋腦網狀結構（right paramedian pontine reticular formation）"],"answer":1,"image":""},{"id":"md4-111-1-45","subject":"md4","topic":"神經-中風","meta":"111年第1次第45題","year":111,"session":1,"number":45,"question":"下列何種磁振造影序列（sequences），對於偵測腦細胞在梗塞數分鐘後所產生細胞毒性水腫（cytotoxic edema）具有最高敏感度？","options":["(A) T1-weighted imaging","(B) T2-weighted imaging","(C) fluid-attenuated inversion recovery（FLAIR）imaging","(D) diffusion-weighted imaging（DWI）"],"answer":3,"image":""},{"id":"md4-111-1-46","subject":"md4","topic":"神經-中風","meta":"111年第1次第46題","year":111,"session":1,"number":46,"question":"一位66歲女性病人，有高血壓及心律不整病史多年，被家人發現突然無法言語及右側肢體無力，之後意識逐漸昏迷，其腦部電腦斷層掃描如下，最有可能發生問題的血管為何？","options":["(A) 左側內頸動脈（internal carotid artery）","(B) 左側前大腦動脈（anterior cerebral artery）","(C) 左側中大腦動脈（middle cerebral artery）","(D) 左側後大腦動脈（posterior cerebral artery）"],"answer":2,"image":"md4-111-1-46.jpeg"},{"id":"md4-111-1-47","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"111年第1次第47題","year":111,"session":1,"number":47,"question":"關於癲癇發作（epileptic seizures），下列敘述何者最恰當？","options":["(A) 正常的腦部磁振造影可以排除病人有癲癇的可能","(B) 暈厥（syncope）的病人如腦電圖出現棘波（spike waves）就可確診為癲癇","(C) 嬰幼兒童一旦曾發生熱痙攣（febrile convulsion）就可確認以後會有癲癇","(D) 暈厥同時有短暫的肌肉強直仍不可確診為癲癇"],"answer":3,"image":""},{"id":"md4-111-1-48","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"111年第1次第48題","year":111,"session":1,"number":48,"question":"關於偏頭痛的藥物治療，下列何者最不恰當？","options":["(A) 急性期的治療藥物triptan的使用，須注意心血管疾病的禁忌症","(B) 如果一個月發作4次以上，可以考慮使用預防性藥物","(C) 抗癲癇藥物如carbamazepine常用於預防偏頭痛","(D) 預防性用藥的選擇宜考慮病患是否有其他共病，如高血壓或躁鬱症"],"answer":2,"image":""},{"id":"md4-111-1-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"111年第1次第49題","year":111,"session":1,"number":49,"question":"關於青少年肌躍性癲癇（juvenile myoclonic epilepsy）需避免使用下列何種抗癲癇藥物？","options":["(A) levetiracetam","(B) phenytoin","(C) valproate","(D) topiramate"],"answer":1,"image":""},{"id":"md4-111-1-50","subject":"md4","topic":"神經-失智退化運動障礙","meta":"111年第1次第50題","year":111,"session":1,"number":50,"question":"因為一氧化碳中毒造成的巴金森症候群（parkinsonism），病灶位置常發生在：","options":["(A) 尾核（caudate）","(B) 殼部（putamen）","(C) 蒼白球（globus pallidus）","(D) 黑質（substantia nigra）"],"answer":2,"image":""},{"id":"md4-111-1-51","subject":"md4","topic":"神經-失智退化運動障礙","meta":"111年第1次第51題","year":111,"session":1,"number":51,"question":"典型的原發性巴金森氏病（idiopathic Parkinson disease）在發病兩年內最不會出現下列那一個症狀？","options":["(A) 兩側不對稱（asymmetric）的顫抖","(B) 起步時兩腳會顫抖，出現凍僵步態（freezing of gait）","(C) 做動作時會減輕顫抖","(D) 動腦（mental tasks）時會加重顫抖"],"answer":1,"image":""},{"id":"md4-111-1-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"111年第1次第52題","year":111,"session":1,"number":52,"question":"60歲男性病患被診斷為失智症，下列那一項檢查結果最不像是阿茲海默症（Alzheimer disease）？","options":["(A) 腦脊髓液中的類澱粉蛋白β-42（amyloid β-42）增加","(B) 核磁共振造影發現海馬迴（hippocampus）萎縮","(C) 類澱粉正子斷層造影（amyloid positron emission tomography）結果陽性","(D) 氟化去氧葡萄糖正子斷層造影（2-fluoro-2-deoxy-D-glucose positron emission tomography）發現顳葉及頂葉（temporoparietal lobes）代謝活性降低"],"answer":0,"image":""},{"id":"md4-111-1-53","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"111年第1次第53題","year":111,"session":1,"number":53,"question":"關於週期性麻痺（periodic paralysis），下列敘述何者最恰當？","options":["(A) 高血鉀是最常見的原因","(B) 無力的肌肉常常影響到吞嚥和呼吸","(C) 屬於神經肌肉接合疾病（neuro-muscular junction diseases）","(D) 對於反覆發作的病人可以使用carbonic anhydrase inhibitor（acetazolamide）預防"],"answer":3,"image":""},{"id":"md4-111-1-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"111年第1次第54題","year":111,"session":1,"number":54,"question":"30歲女性騎馬墜落後送往急診室，神經學檢查發現右下肢無力，左側肚臍以下痛覺和溫覺喪失，其最可能診斷為何？","options":["(A) 胸椎第十節（T10）以上前脊髓損傷","(B) 胸椎第十節（T10）以上後脊髓損傷","(C) 馬尾症候群","(D) 胸椎第十節（T10）以上Brown-Séquard症候群"],"answer":3,"image":""},{"id":"md4-111-1-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"111年第1次第55題","year":111,"session":1,"number":55,"question":"下列何種疾病主要且首先影響到運動神經軸突，造成軸突性神經病變（axonal neuropathy）？","options":["(A) 鉛中毒","(B) 類澱粉神經病變","(C) 格林–巴利症候群（Guillain-Barré syndrome）","(D) 單株免疫球蛋白增高血症（monoclonal gammopathy）"],"answer":0,"image":""},{"id":"md4-111-1-56","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"111年第1次第56題","year":111,"session":1,"number":56,"question":"下列何者不是下運動神經元病灶表徵（lower motor neuron signs）？","options":["(A) 在肌電圖上出現肌肉纖維顫動（fibrillation）","(B) 肌肉痙攣（spasticity）","(C) 病人自覺肌纖維自發性跳動（fasciculation）","(D) 肌肉萎縮（muscle atrophy）"],"answer":1,"image":""},{"id":"md4-111-1-57","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"111年第1次第57題","year":111,"session":1,"number":57,"question":"關於軸突缺失（axonal loss）與去髓鞘（demyelination）引起之神經病變的比較，下列敘述何者最恰當？","options":["(A) 去髓鞘神經病變時常造成早期肌肉萎縮","(B) 兩者所造成的神經病變，均以近端肌肉無力來表現","(C) 糖尿病神經病變可以出現軸突缺失和去髓鞘的神經病理變化","(D) 急性軸突缺失神經病變通常可以同時觀察到去髓鞘的病理變化"],"answer":2,"image":""},{"id":"md4-111-1-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"111年第1次第58題","year":111,"session":1,"number":58,"question":"下列何者與視神經脊髓炎（neuromyelitis optica spectrum disorder, NMOSD）的相關性最為密切？","options":["(A) anti-aquaporin (AQP4) antibody","(B) anti-ganglioside GQ1b antibody","(C) anti- muscle specific kinase (MuSK) antibody","(D) anti-glutamic acid decarboxylase (GAD) antibody"],"answer":0,"image":""},{"id":"md4-111-1-59","subject":"md4","topic":"精神-精神病","meta":"111年第1次第59題","year":111,"session":1,"number":59,"question":"有關思覺失調症之敘述，下列何者正確？","options":["(A) 幻覺妄想為思覺失調症最主要之長期核心症狀","(B) haloperidol屬於第二代抗精神病藥物","(C) Eugene Bleuler的Schizophrenia原發症狀包括associations、autism、affect及ambivalence四個層面之障礙","(D) 第二代抗精神病藥物主要與glutamate機轉有關"],"answer":2,"image":""},{"id":"md4-111-1-60","subject":"md4","topic":"精神-精神病","meta":"111年第1次第60題","year":111,"session":1,"number":60,"question":"下列有關思考形式障礙（formal thought disorders）之描述，下列何者錯誤？","options":["(A) 此症狀可透過書寫文字或口語表達觀察","(B) 為思想之表達與組織出現障礙","(C) 為思考內容出現異常","(D) 新語症（neologism）屬於思考形式障礙"],"answer":2,"image":""},{"id":"md4-111-1-61","subject":"md4","topic":"精神-精神病","meta":"111年第1次第61題","year":111,"session":1,"number":61,"question":"有關雙相情緒障礙症（bipolar disorder）之敘述，下列何者錯誤？","options":["(A) 雙相情緒障礙症比重鬱症較少合併有物質使用障礙症","(B) 雙相情緒障礙症也可能出現明顯的幻聽或妄想症狀","(C) 每次躁症的發作都可能增加後續發作的風險，臨床治療上需要預防復發","(D) 早發的憂鬱症以及治療效果不佳者，將來可能轉變為雙相情緒障礙症的診斷"],"answer":0,"image":""},{"id":"md4-111-1-62","subject":"md4","topic":"精神-精神病","meta":"111年第1次第62題","year":111,"session":1,"number":62,"question":"下列何者藥物不是美國食品及藥物管理署（FDA）核准用於治療雙相情緒障礙症之躁症？","options":["(A) risperidone","(B) olanzapine","(C) lamotrigine","(D) aripiprazole"],"answer":2,"image":""},{"id":"md4-111-1-63","subject":"md4","topic":"精神-器質性與物質使用","meta":"111年第1次第63題","year":111,"session":1,"number":63,"question":"一位32歲男性護理師，主訴下腹痛、血尿、血便。因門診治療無效，多次住院診治，住院後各項檢查卻完全正常。醫療團隊深入探查，發現個案生病及住院並沒有明顯外在利益或目的（例如因生病獲得賠償，或因生病逃避法律責任等），但住院前均食用紅色火龍果。此個案最可能的診斷為何？","options":["(A) illness anxiety disorder（hypochondriasis）","(B) factitious disorder","(C) malingering","(D) conversion disorder"],"answer":1,"image":""},{"id":"md4-111-1-64","subject":"md4","topic":"精神-器質性與物質使用","meta":"111年第1次第64題","year":111,"session":1,"number":64,"question":"李姓男性國民，20歲（簡稱李男）須服義務兵役，李男為了逃避兵役，故意裝病。李男最有可能的診斷為何？","options":["(A) factitious disorder","(B) malingering","(C) conversion disorder","(D) panic disorder"],"answer":1,"image":""},{"id":"md4-111-1-65","subject":"md4","topic":"精神-精神官能症","meta":"111年第1次第65題","year":111,"session":1,"number":65,"question":"有關轉化症的臨床表徵，下列敘述何者正確？","options":["(A) pseudoseizure幾乎不會和seizure共病，可清楚鑑別","(B) astasia-abasia是最常見的動作異常","(C) La belle indifférence是診斷此症的主要特徵","(D) paralysis是最常見的症狀之一"],"answer":3,"image":""},{"id":"md4-111-1-66","subject":"md4","topic":"精神-精神官能症","meta":"111年第1次第66題","year":111,"session":1,"number":66,"question":"關於失眠治療的benzodiazepine使用原則，下列敘述何者錯誤？","options":["(A) 使用以最低有效劑量為原則","(B) 老年人使用benzodiazepine時，要注意其跌倒之風險","(C) 短效benzodiazepine通常比長效benzodiazepine更易成癮","(D) 為加速戒除長期使用benzodiazepine的病患，安排住院後宜立即停用所有benzodiazepine"],"answer":3,"image":""},{"id":"md4-111-1-67","subject":"md4","topic":"精神-器質性與物質使用","meta":"111年第1次第67題","year":111,"session":1,"number":67,"question":"依據美國精神醫學會所出版的精神疾病診斷準則手冊第五版（DSM-5），下列何項不屬於執行功能（executive function）的認知功能範疇（cognitive domain）？","options":["(A) 工作記憶（working memory）","(B) 錯誤修正（error correction）","(C) 操作能力（praxis）","(D) 決策（decision making）"],"answer":2,"image":""},{"id":"md4-111-1-68","subject":"md4","topic":"兒科-感染神經","meta":"111年第1次第68題","year":111,"session":1,"number":68,"question":"有關後天免疫不全症候群（AIDS，簡稱愛滋病）之敘述，下列何者錯誤？","options":["(A) 一般被愛滋病毒（HIV）感染初期不會有任何症狀，但約有30%個案在被感染後會出現類流感症候群（flulike syndrome）","(B) 愛滋病患者若出現失智症狀是一預後不良的跡象，約有50～75%病患在出現失智症狀半年內死亡","(C) 物質使用之共用針頭行為是愛滋病毒（HIV）傳播的主要媒介","(D) 患者通常發生在感染愛滋病毒（HIV）的前、中期階段就出現精神病症狀，可使用抗精神病藥物治療"],"answer":3,"image":""},{"id":"md4-111-1-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"111年第1次第69題","year":111,"session":1,"number":69,"question":"有關以methadone治療海洛因（heroin）成癮者之描述，下列何者正確？","options":["(A) methadone本身極少導致病患依賴","(B) methadone可口服，讓海洛因（heroin）成癮者降低用針頭注射之風險","(C) methadone目前為衛生福利部食藥署（TFDA）第三級管制藥品","(D) methadone藥效不及24小時，所以每天須至少使用兩次"],"answer":1,"image":""},{"id":"md4-111-1-70","subject":"md4","topic":"精神-器質性與物質使用","meta":"111年第1次第70題","year":111,"session":1,"number":70,"question":"下列對酒精相關的描述，何者錯誤？","options":["(A) 依我國道路交通安全規則規定違規酒駕的標準為吐氣所含酒精濃度達0.15mg/L或血液中酒精濃度達0.03%以上","(B) 酒精會降低深層睡眠時間（deep sleep, stage 4）","(C) 酒精戒斷初期常見的症狀會嗜睡","(D) 酒精戒斷有可能出現幻覺"],"answer":2,"image":""},{"id":"md4-111-1-71","subject":"md4","topic":"精神-精神官能症","meta":"111年第1次第71題","year":111,"session":1,"number":71,"question":"小明從國小四年級開始就很怕上臺或公開講話，如果被叫上臺，他就會兩腳發軟、滿臉通紅、手心額角直冒汗，半句話也講不全。同學們也很多人很害羞，但像他這樣怕上台的還沒第二個人。到國中這情形益發嚴重，如果有需要發表意見或輪到要站起來背誦的課，他甚至會翹課，因此他的學業表現也受到影響。下列敘述何者正確？","options":["(A) 診斷是創傷後壓力症（posttraumatic stress disorder）","(B) 第一線的治療藥物是抗精神藥物","(C) 認知行為治療被證明對此疾病具有療效","(D) 良好預後的預測指標包括較晚發病、合併憂鬱症"],"answer":2,"image":""},{"id":"md4-111-1-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"111年第1次第72題","year":111,"session":1,"number":72,"question":"關於注意力不足／過動症（attention-deficit/hyperactivity disorder, ADHD）之敘述，下列何者錯誤？","options":["(A) 成人注意力不足／過動症患者用藥物治療的效果不佳","(B) 使用methylphenidate治療為首選用藥之一","(C) 家庭功能不良雖不是造成ADHD的原因，但會影響治療效果","(D) 過動症狀比注意力缺失和衝動控制不佳在成人期改善較明顯"],"answer":0,"image":""},{"id":"md4-111-1-73","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"111年第1次第73題","year":111,"session":1,"number":73,"question":"當病人陳述自殺意念或呈現自傷行為，下列何種處置最合適？","options":["(A) 人命關天，應立即住院治療","(B) 曾企圖自殺，近來又患有重大內科疾病，宜轉內科門診治療","(C) 憂鬱症狀明顯，深覺無望，缺乏社會支持，移轉至社會工作師與門診治療","(D) 斷續存有自殺意念，自傷方式是割腕，可門診治療或相關心理治療"],"answer":3,"image":""},{"id":"md4-111-1-74","subject":"md4","topic":"兒科-感染神經","meta":"111年第1次第74題","year":111,"session":1,"number":74,"question":"懷孕週數20週出生的早產兒，出生後2個月出現腦室擴大，其T2加重磁振造影像可見腦室壁上的低訊號病灶如圖，最可能原因為何？","options":["(A) 先天性巨細胞病毒感染（congenital CMV infection）","(B) 結節硬化症（tuberous sclerosis）","(C) 腦動脈梗塞（cerebral infarction）","(D) 生長質出血（hemorrhage of germinal matrix）"],"answer":3,"image":"md4-111-1-74.jpeg"},{"id":"md4-111-1-75","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"111年第1次第75題","year":111,"session":1,"number":75,"question":"5歲男童因超音波篩檢發現腹部腫瘤，磁振造影T1加權影像如圖示，則該腫瘤位於何處？","options":["(A) 肝臟左外節","(B) 肝臟左內節","(C) 肝臟右前節","(D) 脾臟內"],"answer":0,"image":"md4-111-1-75.jpeg"},{"id":"md4-111-1-76","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"111年第1次第76題","year":111,"session":1,"number":76,"question":"50歲男性最近服用allopurinol，2週後突然出現全身性紅斑及水泡、黏膜潰爛與表皮剝落壞死，身體檢查發現有40%的體表面積受到影響。關於此病人的診斷，下列何者最有可能？","options":["(A) 史蒂文強生氏症候群（Stevens-Johnson syndrome）","(B) 毒性表皮溶解症（toxic epidermal necrolysis）","(C) 多形性紅斑（erythema multiforme）","(D) 尋常型天疱瘡（pemphigus vulgaris）"],"answer":1,"image":""},{"id":"md4-111-1-77","subject":"md4","topic":"精神-器質性與物質使用","meta":"111年第1次第77題","year":111,"session":1,"number":77,"question":"關於安非他命（amphetamine）濫用的敘述，下列何者最不適當？","options":["(A) 中毒症狀可出現躁動、盜汗、高體溫、心律不整、高血壓等","(B) 在吸食安非他命後之48小時內可由尿液篩檢出安非他命","(C) 戒斷症狀包括無力、嗜睡","(D) 對於中毒病人，重要治療包括支持療法及給與足夠鎮定劑"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第77題，一律給分。。 (原公告答案 C)"},{"id":"md4-111-1-78","subject":"md4","topic":"兒科-心血管呼吸","meta":"111年第1次第78題","year":111,"session":1,"number":78,"question":"一位50歲男性，5年前做過心臟二尖瓣膜手術，至急診主訴發燒10日，這2天逐漸出現喘與胸悶的情形，身體檢查出現一些皮膚與眼睛病灶如圖，下列敘述何者錯誤？","options":["(A) 手指或腳趾出現小而壓痛的腫塊病灶稱為Osler node","(B) 指甲床出現病灶為Roth spots","(C) 結膜、口腔黏膜和四肢可見瘀血點","(D) 手掌或腳掌出現小而無痛的出血性斑塊病灶稱為Janeway lesions"],"answer":1,"image":"md4-111-1-78.jpeg"},{"id":"md4-111-1-79","subject":"md4","topic":"醫學倫理與法規","meta":"111年第1次第79題","year":111,"session":1,"number":79,"question":"關於台灣精神衛生法保護精神疾病病人安全及權利之規定，下列敘述何者正確？","options":["(A) 為了避免病房中有視線之死角，導致無法觀察到病人之自傷或自殺行為，在不需告知病人之情況下，精神科病房可以全面裝設攝影設備","(B) 某憂鬱症病人與其父親素來不合，屢次與其父親爭吵之後，發生自殘之行為（例如撞牆、割腕），因此住院接受治療；考慮病情需要及病人之安全，主治醫師可以暫時禁止病人父親來訪","(C) 精神科主治醫師為了讓學生觀察到少見的僵直性精神分裂症（catatonic schizophrenia）患者之症狀（不語、不動等），可以在該病人未出言反對之情況下，將其症狀錄影供其後教學之用","(D) 某躁症（mania）病人屢次出現攻擊他人之行為，醫療團隊可以決定將之連續約束2小時，約束期間不予探視，以達到降低攻擊傾向之效果"],"answer":1,"image":""},{"id":"md4-111-1-80","subject":"md4","topic":"醫學倫理與法規","meta":"111年第1次第80題","year":111,"session":1,"number":80,"question":"4歲男童在遊戲中，因為衝撞牆壁引起腦部廣泛性出血，送到醫院急救後，回復心跳及血壓，但持續重度昏迷、倚賴呼吸器與升壓藥物維持生命現象，隨後兩天又出現尿崩症。第3天由兩位腦死判定研習完訓之小兒科專科醫師和此病患之主治醫師一起經標準流程，如腦幹反射測試與自主呼吸測驗等兩次之測驗後而判定腦死。患者過世後，家屬認為判定過程之「停止呼吸器及供氧」造成病人過世。對此事件，下列何控訴最能成立？","options":["(A) 沒有說明做腦死判斷之理由（如器官捐贈移植）","(B) 沒有具備神經內科、或神經外科之專科醫師參與判定","(C) 臺灣法律沒有定義腦死","(D) 文獻證明「停止呼吸器及供氧」會加速腦死病人走向不可逆的死亡"],"answer":0,"image":""},{"id":"md4-111-2-1","subject":"md4","topic":"兒科-感染神經","meta":"111年第2次第1題","year":111,"session":2,"number":1,"question":"8歲女孩，因突發高燒、頭痛、嘔吐及腹瀉而至急診求治，在急診因血壓下降而被轉到加護病房。其3腦脊髓液檢查正常，血液WBC 21,000/mm（band: 3%, segment: 70%），CRP 12.7 mg/dL。身體診察發現左手臂有一大塊紅腫的區域，位於先前被蚊子叮咬而抓破皮的周圍，胸部、腹部有會癢的紅疹。此時最適當給與的抗生素為下列何者？","options":["(A) Ampicillin","(B) Oxacillin","(C) Ampicillin + Gentamicin","(D) Oxacillin + Clindamycin"],"answer":3,"image":""},{"id":"md4-111-2-2","subject":"md4","topic":"兒科-感染神經","meta":"111年第2次第2題","year":111,"session":2,"number":2,"question":"貓抓病（Cat scratch disease）是下列何種細菌引起？","options":["(A) Bartonella henselae","(B) Brucella canis","(C) Burkholderia cepacia","(D) Bartonella quintana"],"answer":0,"image":""},{"id":"md4-111-2-3","subject":"md4","topic":"兒科-感染神經","meta":"111年第2次第3題","year":111,"session":2,"number":3,"question":"8個月大的女嬰高燒3天，除了發燒外有輕微鼻塞，第4天軀幹出現紅疹後不再發燒，關於此疾病下列何者錯誤？","options":["(A) 最可能的診斷為嬰兒玫瑰疹（Roseola infantum）","(B) 最主要的致病原為人類疱疹病毒第八型（HHV-8）","(C) 在亞洲國家的病人，於uvulopalatoglossal junction處常可見Nagayama spots","(D) 熱性痙攣（Febrile convulsion）是可能的併發症"],"answer":1,"image":""},{"id":"md4-111-2-4","subject":"md4","topic":"兒科-感染神經","meta":"111年第2次第4題","year":111,"session":2,"number":4,"question":"先天性梅毒（Congenital syphilis）的敘述，下列何者錯誤？","options":["(A) 新生兒Venereal Disease Research Laboratory（VDRL）陽性可確診為先天性梅毒感染","(B) 垂直感染可發生在孕期的任何階段，可造成流產、早產、低體重胎兒之情形","(C) 先天性梅毒早期症狀常見肝脾腫大、肝炎、黃疸；若未治療，晚期會侵犯中樞神經、骨關節","(D) 治療先天性梅毒首選的抗生素是Penicillin-G"],"answer":0,"image":""},{"id":"md4-111-2-5","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"111年第2次第5題","year":111,"session":2,"number":5,"question":"新生兒維持正常體溫而氧氣消耗量最少的環境溫度叫中性環境溫度（neutral thermal environment）。下列何者不會影響中性環境溫度的調控？","options":["(A) 環境對流作用（Convection）","(B) 環境相對濕度（Relative humidity）","(C) 新生兒出生週數（Gestational age）","(D) 新生兒餵食量（Feeding amount）"],"answer":3,"image":""},{"id":"md4-111-2-6","subject":"md4","topic":"兒科-內分泌遺傳","meta":"111年第2次第6題","year":111,"session":2,"number":6,"question":"一個新生兒外觀異常，有低位耳（low-set ears）、上顎裂（midline facial clefts）與下頜骨發育異常（hypomandibular abnormalities），並因為低血鈣（hypocalcemia）而引發肌肉強直性痙攣（tetany），最可能的診斷為：","options":["(A) Turner syndrome","(B) DiGeorge syndrome","(C) Wiskott-Aldrich syndrome","(D) Noonan syndrome"],"answer":1,"image":""},{"id":"md4-111-2-7","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"111年第2次第7題","year":111,"session":2,"number":7,"question":"剛出生的男嬰，出生後不久隨即發現口鼻冒泡泡，餵食時容易嗆奶、咳嗽、喘，甚至會發紺，放置口胃管時，有阻力而無法順利完成，最有可能的診斷為何？","options":["(A) 先天性橫膈膜疝氣（congenital diaphragmatic hernia）","(B) 食道閉鎖（esophageal atresia）","(C) 後鼻孔閉鎖（choanal atresia）","(D) 喉頭軟化症（laryngomalacia）"],"answer":1,"image":""},{"id":"md4-111-2-8","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"111年第2次第8題","year":111,"session":2,"number":8,"question":"有關懷孕週數40週新生兒的身體診察，下列何者最為異常？","options":["(A) 體重3.3公斤","(B) 身長50公分","(C) 頭圍38公分","(D) 體溫36.8℃"],"answer":2,"image":""},{"id":"md4-111-2-9","subject":"md4","topic":"兒科-消化系統疾病","meta":"111年第2次第9題","year":111,"session":2,"number":9,"question":"下列何種狀況最不易見到急性膽囊水腫（Acute hydrops of the gallbladder）？","options":["(A) 川崎氏病（Kawasaki disease）","(B) 囊腫性纖維化（Cystic fibrosis）","(C) 病毒性肝炎（Viral hepatitis）","(D) 沙門氏菌敗血症（Salmonellosis）"],"answer":1,"image":""},{"id":"md4-111-2-10","subject":"md4","topic":"兒科-消化系統疾病","meta":"111年第2次第10題","year":111,"session":2,"number":10,"question":"15歲女童，每當感冒或月經來潮時，就會出現輕微黃疸，其總膽紅素（bilirubin）介於3～5 mg/dL，屬間接型。無溶血現象，其餘肝功能檢查都正常，約5天就緩解。最可能的疾病是：","options":["(A) Wilson's disease","(B) Gilbert syndrome","(C) Dubin-Johnson syndrome","(D) Autoimmune hepatitis"],"answer":1,"image":""},{"id":"md4-111-2-11","subject":"md4","topic":"兒科-消化系統疾病","meta":"111年第2次第11題","year":111,"session":2,"number":11,"question":"下列有關先天性巨結腸症（Hirschsprung disease）的敘述，何者錯誤？","options":["(A) 直腸內壓測定（anorectal manometry）時肛門括約肌壓力下降","(B) 直腸指診時會有爆發式排泄（explosive stools）的情形","(C) 可用直腸組織切片（rectal biopsy）來做為輔助診斷的工具","(D) 鋇劑灌腸檢查（barium enema examination）可見病變處狹窄"],"answer":0,"image":""},{"id":"md4-111-2-12","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"111年第2次第12題","year":111,"session":2,"number":12,"question":"8歲女童一個月前皮膚出現化膿性感染，這兩天尿液變少、雙側眼皮水腫。血壓115/80 mmHg、心跳每分鐘85 33次、呼吸每分鐘22次。血中白血球數為12,000/mm、血色素9.6 g/dL、血小板280,000/mm。尿液檢查顯示OB 3+、RBC 35～50/HPF、WBC 5～10/HPF、尿蛋白100 mg/dL。下列何者為最可能的診斷？","options":["(A) 急性腎盂腎炎（Acute pyelonephritis）","(B) 急性鏈球菌感染後腎絲球腎炎（Acute poststreptococcal glomerulonephritis）","(C) 急性溶血症（Acute hemolytic syndrome）","(D) 腎病症候群（Nephrotic syndrome）"],"answer":1,"image":""},{"id":"md4-111-2-13","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"111年第2次第13題","year":111,"session":2,"number":13,"question":"有關兒童腎病症候群（Idiopathic nephrotic syndrome）的敘述，下列何者錯誤？","options":["(A) 尿中蛋白大量流失（Nephrotic-range proteinuria）","(B) 血管內滲透壓減低（Decrease intravascular oncotic pressure）","(C) 病童會出現高血脂（Hyperlipidemia）的現象","(D) 血液不易凝固（Hypocoagulability）的狀態 +"],"answer":3,"image":""},{"id":"md4-111-2-14","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"111年第2次第14題","year":111,"session":2,"number":14,"question":"10歲男童有癲癇病史，長期使用抗癲癇藥物控制。出現全身性強直陣攣發作送到急診，抽血檢驗發現，[Na] +-- ＝140 mEq/L， [K]＝4.0 mEq/L， [Cl]＝98 mEq/L，動脈血液氣體分析為pH＝7.14，PaCO2＝46 mmHg，[HCO3] ＝17 mEq/L。有關此病人的敘述，下列何者錯誤？","options":["(A) 代謝性酸中毒（Metabolic acidosis）合併呼吸性酸中毒（respiratory acidosis）","(B) 低陰離子間隙（Low anion gap）","(C) 治療包括控制癲癇及呼吸支持","(D) 此代謝性酸中毒（Metabolic acidosis）可能因癲癇發作而引起"],"answer":1,"image":""},{"id":"md4-111-2-15","subject":"md4","topic":"兒科-感染神經","meta":"111年第2次第15題","year":111,"session":2,"number":15,"question":"有關腸病毒（Enterovirus）重症的敘述，下列何者錯誤？","options":["(A) 重症病人常會脫水故需大量給與輸液補充","(B) 未滿5歲兒童居多","(C) 腸病毒71型為腦幹脊髓炎（Rhombencephalitis）之主要病原之一","(D) 頻繁的肌跳躍（Myoclonic jerks）是重症前兆"],"answer":0,"image":""},{"id":"md4-111-2-16","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"111年第2次第16題","year":111,"session":2,"number":16,"question":"5歲男童早上醒來後，發覺他兩腳無法走路，急診檢查時發現體溫為38.5℃且血清中Creatine kinase（CK）比正常值高20倍，下列何種疾病為最有可能之診斷？","options":["(A) Acute myositis","(B) Acute transverse myelitis","(C) Myasthenia gravis","(D) Guillian-Barré syndrome"],"answer":0,"image":""},{"id":"md4-111-2-17","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"111年第2次第17題","year":111,"session":2,"number":17,"question":"13歲男孩，自述4週前有輕微腹瀉，最近2週內有進行性的四肢無力和感覺異常，神經學診查發現四肢深部肌腱反射（Deep tendon reflexes）減弱，腦部和脊椎磁振造影掃描無特殊異常，腦脊髓液檢查報告如下：33 WBC：0 cell/mm，RBC：0 cell/mm，glucose：80 mg/dL，protein：105 mg/dL。此病人最可能的診斷為何？","options":["(A) Poliomyelitis","(B) Acute inflammatory demyelinating polyradiculoneuropathy","(C) Myasthenia gravis","(D) Viral myositis"],"answer":1,"image":""},{"id":"md4-111-2-18","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"111年第2次第18題","year":111,"session":2,"number":18,"question":"有關新生兒的身體診察，下列敘述何者錯誤？","options":["(A) Moro reflex若兩手臂呈不對稱伸張，要考慮是否有臂神經叢受損（Brachial plexus injury）","(B) 在頭部摸到一軟而有波動之腫塊，且越過骨縫，此為胎頭血腫（Cephalohematoma）","(C) 出生後第3天身體軀幹出現毒性紅斑（Erythema toxicum）此為正常現象","(D) 身體中線兩側的皮膚呈現半紅半白(Harlequin color change)，係屬暫時性的，無任何意義"],"answer":1,"image":""},{"id":"md4-111-2-19","subject":"md4","topic":"兒科-內分泌遺傳","meta":"111年第2次第19題","year":111,"session":2,"number":19,"question":"新生兒一再發生低血糖（hypoglycemia），當血糖低至40 mg/dL時所做的實驗室檢查結果，其中何者不支持高胰島素症（hyperinsulinism）的診斷？","options":["(A) 血清胰島素（insulin）值為10 μU/mL（正常範圍5～15 μU/mL）","(B) 血漿游離脂肪酸濃度（free fatty acid level）低","(C) 血漿酮體（ketone body）為3.0 mmol/L（正常值＜0.6 mmol/L）","(D) 1 mg升糖素（glucagon）靜脈注射後，病人血糖值為90 mg/dL"],"answer":2,"image":""},{"id":"md4-111-2-20","subject":"md4","topic":"兒科-內分泌遺傳","meta":"111年第2次第20題","year":111,"session":2,"number":20,"question":"男童青春期第二性徵的發育，下列何項變化最晚出現？","options":["(A) 陰莖變長（growth of penis）","(B) 睪丸變大（enlargement of testes）","(C) 生長衝刺（growth spurt）","(D) 陰毛發育（development of pubic hair）"],"answer":2,"image":""},{"id":"md4-111-2-21","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"111年第2次第21題","year":111,"session":2,"number":21,"question":"6個月大的男童，皮膚和臟器反覆出現膿瘍，且合併發生骨髓炎（osteomyelitis）、全身性濕疹（eczema），最有可能是下列那一種先天性免疫缺損問題？","options":["(A) T淋巴球免疫缺乏（T cells immunodeficiency）","(B) 自然殺手細胞免疫缺乏（natural killer cells immunodeficiency）","(C) 補體免疫缺乏（complement deficiency）","(D) 吞噬細胞趨化性缺陷（phagocyte chemotaxis defect）"],"answer":3,"image":""},{"id":"md4-111-2-22","subject":"md4","topic":"兒科-心血管呼吸","meta":"111年第2次第22題","year":111,"session":2,"number":22,"question":"下呼吸道阻塞，最不會出現下列那一項徵候？","options":["(A) Intercostal retraction","(B) Wheezing","(C) Stridor","(D) Tachypnea"],"answer":2,"image":""},{"id":"md4-111-2-23","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"111年第2次第23題","year":111,"session":2,"number":23,"question":"有關幼年特發性關節炎（Juvenile idiopathic arthritis, JIA），下列敘述何者錯誤？","options":["(A) 不管是診斷那一種亞型的JIA，一定要有關節炎，才能下診斷","(B) JIA之診斷主要是靠臨床診斷，所有的實驗室檢查都只是幫助診斷及預後參考之用","(C) 多關節亞型（Polyarthritis）的患者，會有較高比例合併葡萄膜炎（Uveitis）","(D) ANA陽性在少關節亞型（Oligoarthritis）的比例，較其他亞型為高"],"answer":2,"image":""},{"id":"md4-111-2-24","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"111年第2次第24題","year":111,"session":2,"number":24,"question":"有關異位性皮膚炎（Atopic dermatitis）的敘述，下列何者錯誤？","options":["(A) 異位性皮膚炎診斷之依據包括皮疹是否呈現典型分布以及是否有慢性、復發性癢疹","(B) 第一代口服抗組織胺可能會導致嗜睡，因此考慮夜間睡前使用","(C) 異位性皮膚炎病童皮膚傷口最常會受到鏈球菌感染，發生時可使用局部抗生素治療","(D) 異位性皮膚炎如果使用局部型類固醇效果不好者，可考慮使用topical calcineurin inhibitors來治療"],"answer":2,"image":""},{"id":"md4-111-2-25","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"111年第2次第25題","year":111,"session":2,"number":25,"question":"10個月大的男童，最近3個月內反覆發生中耳炎及細菌性肺炎，但之前健康情形尚稱良好。病童有一個哥哥於9個月大時，因敗血症過世。身體診察發現無扁桃腺（Tonsils），血中IgG＜200 mg/dL、IgA＜5 mg/dL、IgM＜100 mg/dL，此男童最可能的診斷為何？","options":["(A) 嬰兒暫時性低免疫球蛋白血症（Transient hypogammaglobulinemia of infancy）","(B) 選擇性IgA缺乏症（Selective IgA deficiency）","(C) 嚴重合併性免疫缺乏症（Severe combined immunodeficiency）","(D) Bruton氏免疫球蛋白缺乏症（Bruton agammaglobulinemia）"],"answer":3,"image":""},{"id":"md4-111-2-26","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"111年第2次第26題","year":111,"session":2,"number":26,"question":"唐氏症（Down syndrome）兒童最常罹患下列何種白血病 ?","options":["(A) T-cell acute lymphoblastic leukemia（T-ALL）","(B) B-cell acute lymphoblastic leukemia（B-ALL）","(C) Acute myelogenous leukemia（AML）","(D) Chronic myelogenous leukemia（CML）"],"answer":2,"image":""},{"id":"md4-111-2-27","subject":"md4","topic":"兒科-感染神經","meta":"111年第2次第27題","year":111,"session":2,"number":27,"question":"發生嗜中性球低下發燒（Febrile neutropenia）時，有關Vancomycin的給與時機及方式，下列何者較不恰當？","options":["(A) 休克時使用Vancomycin，應加快靜脈輸注速率（輸注時間小於10分鐘）","(B) 如果有明顯的導管相關感染，應給與Vancomycin","(C) 如果過去有Methicillin-resistant金黃色葡萄球菌（Staphylococcus aureus）菌落形成（colonization）的病史，應給與Vancomycin","(D) 如果病人有嚴重的口腔黏膜炎（Mucositis），且已使用quinolone類藥物做預防性抗生素，仍應給與Vancomycin"],"answer":0,"image":""},{"id":"md4-111-2-28","subject":"md4","topic":"兒科-心血管呼吸","meta":"111年第2次第28題","year":111,"session":2,"number":28,"question":"有關川崎氏病（Kawasaki disease）的敘述，除了持續發高燒超過5天外，亦須出現主要臨床準據（principal clinical criteria），以符合診斷，但下列何者錯誤？","options":["(A) 出現不同型態的皮疹，廣泛分布於四肢和軀幹","(B) 一週內會出現皮膚脫屑，特別是指尖周圍","(C) 兩眼結膜充血，或口腔黏膜變化，如草莓舌或嘴唇紅裂甚至出血","(D) 急性非化膿性頸淋巴結腫大，單側或雙側，直徑至少1.5公分"],"answer":1,"image":""},{"id":"md4-111-2-29","subject":"md4","topic":"兒科-心血管呼吸","meta":"111年第2次第29題","year":111,"session":2,"number":29,"question":"引起兒童胸痛（chest pain）的原因當中，下列何者相對少見（less common）？","options":["(A) 先天性心臟病（Congenital heart disease）","(B) 肌肉骨骼原因（Musculoskeletal）","(C) 肺部原因（Pulmonary）","(D) 焦慮（Anxiety）"],"answer":0,"image":""},{"id":"md4-111-2-30","subject":"md4","topic":"兒科-心血管呼吸","meta":"111年第2次第30題","year":111,"session":2,"number":30,"question":"一位6個月大男嬰因呼吸急促就醫，身體診察時在左胸前可聽到第三度to-and-fro心雜音，於右肋下緣4公分可觸摸到肝臟腫大，胸部X光如圖所示。下列何者為最可能的診斷？","options":["(A) 法洛氏四合症（tetralogy of Fallot）","(B) 先天肺動脈瓣膜缺失症伴有心室中隔缺損（congenital absence of the pulmonary valves and ventricular septal defect）","(C) 三尖瓣膜閉鎖（tricuspid atresia）","(D) 總肺靜脈回流異常（total anomalous pulmonary venous return）合併阻塞"],"answer":1,"image":"md4-111-2-30.jpeg"},{"id":"md4-111-2-31","subject":"md4","topic":"兒科-內分泌遺傳","meta":"111年第2次第31題","year":111,"session":2,"number":31,"question":"7歲男童，視力減退；之後出現步伐蹣跚、無法行走。8歲時皮膚明顯變黑，9歲死亡。他的舅舅在10歲大時，也因類似病程而死亡。下列何者為最可能的診斷？","options":["(A) 龐貝氏症（Pompe disease）","(B) 威爾森氏症（Wilson disease）","(C) 腎上腺腦白質失養症（Adrenoleukodystrophy, ALD）","(D) 高雪氏症（Gaucher Disease）"],"answer":2,"image":""},{"id":"md4-111-2-32","subject":"md4","topic":"兒科-內分泌遺傳","meta":"111年第2次第32題","year":111,"session":2,"number":32,"question":"5歲男童，身材較矮，學習遲緩，眼裂下垂，耳位低，而且有肺動脈狹窄。下列何者為最可能的診斷？","options":["(A) 威廉氏症（Williams syndrome）","(B) 努南氏症（Noonan syndrome）","(C) 特納氏症（Turner syndrome）","(D) 唐氏症（Down syndrome）"],"answer":1,"image":""},{"id":"md4-111-2-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"111年第2次第33題","year":111,"session":2,"number":33,"question":"唐氏症（Down syndrome）的患童約15%有頸椎曲度異常（Misalignment of cervical vertebra），其中最好發在那一節頸椎？","options":["(A) C1","(B) C2","(C) C3","(D) C4"],"answer":0,"image":""},{"id":"md4-111-2-34","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"111年第2次第34題","year":111,"session":2,"number":34,"question":"下列何者不是慢性蕁麻疹（chronic urticaria）的建議療法？","options":["(A) 抗組織胺（antihistamine）","(B) 環孢素（cyclosporine）","(C) 抗IgE之單株抗體omalizumab","(D) 長期口服類固醇（long term oral corticosteroid）"],"answer":3,"image":""},{"id":"md4-111-2-35","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"111年第2次第35題","year":111,"session":2,"number":35,"question":"關於乾癬（psoriasis）的敘述，下列何者錯誤？","options":["(A) 乾癬病患可合併出現乾癬性關節炎","(B) 心肌梗塞是乾癬病患可能的共病","(C) 肥胖是乾癬的危險因子","(D) 口服類固醇是首選治療"],"answer":3,"image":""},{"id":"md4-111-2-36","subject":"md4","topic":"皮膚-感染","meta":"111年第2次第36題","year":111,"session":2,"number":36,"question":"有關於汗斑（pityriasis versicolor）的敘述，下列何者錯誤？","options":["(A) 最常見的致病菌是馬拉色菌（Malassezia）","(B) 用伍氏燈（Wood lamp）照射可以看到黃綠色的螢光","(C) 口服首選治療為griseofulvin，因其療效較口服itraconazole有效","(D) 若常處於悶熱潮濕環境，治療後仍容易復發"],"answer":2,"image":""},{"id":"md4-111-2-37","subject":"md4","topic":"皮膚-感染","meta":"111年第2次第37題","year":111,"session":2,"number":37,"question":"一位5歲男童出現發燒、倦怠、上呼吸道症狀、喉嚨痛、肚子痛，以及如圖皮疹約3天，下列相關敘述何者錯誤？","options":["(A) 此病的病程大多為benign, self-limited","(B) 疾病緩解後的3～6週間可能出現脫甲症（onychomadesis）的指甲變化","(C) 病灶常出現在手、腳、四肢及嘴巴周圍","(D) 可由克沙奇病毒（coxsackievirus）感染造成，病程表現大多比腸病毒（enterovirus）71型感染嚴重，重症比率也較高"],"answer":3,"image":"md4-111-2-37.jpeg"},{"id":"md4-111-2-38","subject":"md4","topic":"皮膚-腫瘤","meta":"111年第2次第38題","year":111,"session":2,"number":38,"question":"60歲的女性，病患自述約一週前在下唇出現一個直徑約1公分、無痛、暗紫色、有彈性的丘疹（如圖一所示），並否認有外傷的情況。經切片手術之病理檢查如附圖二。下列何者為最可能的診斷？","options":["(A) 皮膚纖維瘤（dermatofibroma）","(B) 靜脈湖（venous lake）","(C) 黑色素瘤（melanoma）","(D) 色素性基底細胞癌（pigmented basal cell carcinoma）"],"answer":1,"image":"md4-111-2-38.jpeg"},{"id":"md4-111-2-39","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"111年第2次第39題","year":111,"session":2,"number":39,"question":"下列何者不是診斷全身性紅斑性狼瘡（systemic lupus erythematosus）的重要皮膚特徵？","options":["(A) 兩側臉頰的蝴蝶斑","(B) 皮膚具有光敏感性","(C) 蕁麻疹時常發作","(D) 圓盤狀皮膚疹"],"answer":2,"image":""},{"id":"md4-111-2-40","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"111年第2次第40題","year":111,"session":2,"number":40,"question":"下列有關真皮層黑色素細胞增生疾病（dermal melanocytosis），何者正確？","options":["(A) 相較於表皮的色素沉澱，真皮層黑色素細胞增生疾病通常會呈現藍灰色的色澤","(B) Hori氏母斑（nevus of Hori）較常出現於亞洲女性，因常見於臉部通常一出生就會被發現","(C) Ito氏母斑（nevus of Ito）常沿著臉部三叉神經的位置分布，一部分的患者會伴隨鞏膜色素異常（scleral pigmentation）","(D) 蒙古斑（mongolian spot）好發於亞洲人等有色人種，最常見的部位為嬰兒的下腹部"],"answer":0,"image":""},{"id":"md4-111-2-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"111年第2次第41題","year":111,"session":2,"number":41,"question":"45歲男性於某工廠擔任作業員，常接觸化學藥品。因為手部皮膚出現類似白斑（vitiligo）之脫色斑塊（depigmented patches）而前往皮膚科就診，被判定為因化學物質所造成的皮膚表現，最有可能接觸的化學藥品為何？","options":["(A) 酚（phenol）","(B) 聚乙烯（polyethylene）","(C) 對羥基苯甲酸酯（parabens）","(D) 酒精（alcohol）"],"answer":0,"image":""},{"id":"md4-111-2-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"111年第2次第42題","year":111,"session":2,"number":42,"question":"下列有關雄性禿（androgenetic alopecia）之敘述，何者錯誤？","options":["(A) 男性可用Hamilton-Norwood classification評估掉髮的嚴重程度","(B) 雄性禿患者常抱怨大量的active hair loss","(C) 仔細觀察頭皮可以發現毳毛（vellus hair）增加","(D) 不論男女，topical minoxidil為雄性禿的治療選項"],"answer":1,"image":""},{"id":"md4-111-2-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"111年第2次第43題","year":111,"session":2,"number":43,"question":"出生後便立即去世之胎兒，全身被極厚的膜狀物包覆（如圖所示），此病患最可能之診斷為何？","options":["(A) ichthyosis vulgaris","(B) palmoplantar keratosis","(C) harlequin ichthyosis","(D) incontinentia pigmenti"],"answer":2,"image":"md4-111-2-43.jpeg"},{"id":"md4-111-2-44","subject":"md4","topic":"神經-中風","meta":"111年第2次第44題","year":111,"session":2,"number":44,"question":"下列何者的表現最有可能是小血管中風（small-vessel stroke）？","options":["(A) 右側無力合併失語症（aphasia）","(B) 左側無力合併左側半邊忽略（hemineglect）","(C) 右側無力合併雙眼偏向左側（conjugated eye deviation to left）","(D) 左側無力合併左側肢體共濟失調（ataxia）"],"answer":3,"image":""},{"id":"md4-111-2-45","subject":"md4","topic":"神經-中風","meta":"111年第2次第45題","year":111,"session":2,"number":45,"question":"42歲男性病人突然發生左側肢體無力，無顯影劑之腦部電腦斷層（non-contrast CT）檢查結果如圖①，於2天後病人因漸進性意識不清再次安排了腦部CT檢查，結果如圖②。下列何種治療最有可能增進此病人的存活機會？","options":["(A) 抗凝血劑（anticoagulants）","(B) 抗癲癇藥物（antiepileptic drugs）","(C) 顱骨切開術（craniectomy）","(D) 收縮壓控制在160 mmHg以下"],"answer":2,"image":"md4-111-2-45.jpeg"},{"id":"md4-111-2-46","subject":"md4","topic":"神經-中風","meta":"111年第2次第46題","year":111,"session":2,"number":46,"question":"下列造成心因性缺血性腦中風的原因，何者最不建議使用抗凝血劑預防中風？","options":["(A) 非瓣膜性心房顫動（atrial fibrillation）合併CHA2DS2-VASc分數為3","(B) 曾接受機械性瓣膜置換術（mechanical valve replacement）","(C) 感染性心內膜炎（infective endocarditis）","(D) 非細菌性血栓性心内膜炎（nonbacterial thrombotic endocarditis）"],"answer":2,"image":""},{"id":"md4-111-2-47","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"111年第2次第47題","year":111,"session":2,"number":47,"question":"21歲女性初次被診斷為顳葉癲癇，並準備開始服用抗癲癇藥物，下列何者考量最不適當？","options":["(A) 開立phenytoin之前要抽血檢驗，確認不帶有人類組織配對抗原HLA-B*1500基因","(B) 病人處於適婚年齡並有懷孕之可能，避免開立valproic acid","(C) 若病人目前正在服用避孕藥，若開立phenytoin或carbamazepine應告知可能會有意外懷孕的風險","(D) 如果抗癲癇藥物不能有效控制病情或癲癇發作影響生活品質，癲癇手術是可能的選擇"],"answer":0,"image":""},{"id":"md4-111-2-48","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"111年第2次第48題","year":111,"session":2,"number":48,"question":"57歲男性因睡眠異常行為由妻子陪伴來診，妻子表示他經常在後半夜發作，會與人對話、大聲謾罵、揮手踢腳，甚至衝撞牆壁跌落床下。有時發作中醒來，他可以栩栩如生描述夢境，與他所表現的行為吻合。有關他的疾病，下列敘述何者最不適當？","options":["(A) 主要好發於老年男性","(B) 睡眠多項生理檢查（polysomnography）主要的發現為快速動眼期睡眠（rapid eye movement sleep, REM sleep）不能維持肌肉失張力狀態（muscle atonia）","(C) 使用抗憂鬱劑（例如serotonin或norepinephrine reuptake blockers）可以改善症狀","(D) 十年內發展成巴金森氏病的危險率增加"],"answer":2,"image":""},{"id":"md4-111-2-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"111年第2次第49題","year":111,"session":2,"number":49,"question":"下列何種治療證實對於慢性緊縮性頭痛（chronic tension-type headache）具有療效？","options":["(A) verapamil","(B) amitriptyline","(C) alprazolam","(D) onabotulinum toxin type A"],"answer":1,"image":""},{"id":"md4-111-2-50","subject":"md4","topic":"神經-中風","meta":"111年第2次第50題","year":111,"session":2,"number":50,"question":"40歲女性得了急性失語症，測驗時她還可以重複簡短字句。她最可能的失語症類型是：","options":["(A) 傳導性失語症（conduction aphasia）","(B) 渥尼克氏失語症（Wernicke's aphasia）","(C) 純字聾（pure word deafness）","(D) 跨皮質失語症（transcortical aphasia）"],"answer":3,"image":""},{"id":"md4-111-2-51","subject":"md4","topic":"神經-失智退化運動障礙","meta":"111年第2次第51題","year":111,"session":2,"number":51,"question":"54歲女性主訴最近三年來記憶力減退，她在49歲時曾發生右側肢體無力，後來完全恢復。她的簡易智能測驗（Mini-Mental State Examination）得分22分（滿分30分），她的父親、叔叔和哥哥都有中風和失智的病史。她的腦部磁振造影掃描結果如下圖，她最有可能是那一個基因變異？","options":["(A) Notch-3","(B) MTHFR","(C) SOD","(D) PSEN-1"],"answer":0,"image":"md4-111-2-51.jpeg"},{"id":"md4-111-2-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"111年第2次第52題","year":111,"session":2,"number":52,"question":"60歲男性，一年前右手姆指以及食指出現顫抖現象；寫字不如以前靈活、字越寫越小，走路時右手不太擺動，但是仍然可以用鋤頭整地種菜，感覺功能正常。最近半年右腳比較僵硬、臉部表情較少。下列臨床診斷何者最有可能？","options":["(A) 半身肌張力不全（hemidystonia）","(B) 脊髓小腦共濟失調症（spinocerebellar ataxia）","(C) 巴金森氏病（Parkinson disease）","(D) 本態性顫抖（essential tremor）"],"answer":2,"image":""},{"id":"md4-111-2-53","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"111年第2次第53題","year":111,"session":2,"number":53,"question":"肉毒桿菌中毒（botulism）與重症肌無力（myasthenia gravis）之比較，下列何者錯誤？","options":["(A) 肉毒桿菌中毒之自律神經症狀明顯","(B) 肉毒桿菌中毒影響在突觸前神經末端（presynaptic terminal）","(C) 肉毒桿菌中毒不會影響呼吸","(D) 肉毒桿菌中毒使用類固醇無效"],"answer":2,"image":""},{"id":"md4-111-2-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"111年第2次第54題","year":111,"session":2,"number":54,"question":"下列疾病中，何者最常以近端肢體無力（proximal weakness）為初期表現？","options":["(A) 多發性肌炎（polymyositis）","(B) 糖尿病多發性神經病變（diabetic polyneuropathy）","(C) 肌萎縮性側索硬化（amyotrophic lateral sclerosis）","(D) 肘隧道症候群（cubital tunnel syndrome）"],"answer":0,"image":""},{"id":"md4-111-2-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"111年第2次第55題","year":111,"session":2,"number":55,"question":"63歲長年茹素女性出現漸進性步態不穩，檢查發現痙攣步態（spastic gait），合併振動感覺（vibration sense）及關節位置感覺（joint position sense）喪失，但痛覺及溫覺正常。兩側膝蓋的深層肌腱反射（deep tendon reflex, DTR）較上肢增強，但兩腳踝的DTR卻是減弱。其最可能的診斷為何？","options":["(A) 肌萎縮性側索硬化（amyotrophic lateral sclerosis）","(B) 後脊髓動脈症候群（posterior spinal artery syndrome）","(C) 亞急性合併退化症（subacute combined degeneration）","(D) 慢性脫髓鞘多發性神經病變（chronic inflammatory demyelinating polyneuropathy）"],"answer":2,"image":""},{"id":"md4-111-2-56","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"111年第2次第56題","year":111,"session":2,"number":56,"question":"下列何種造成中樞神經感染之病原體易攻擊腦部的前顳葉，常可於腦部磁振造影發現該處之病灶？","options":["(A) 單純疱疹病毒","(B) 肺炎鏈球菌","(C) 結核菌","(D) 隱球菌"],"answer":0,"image":""},{"id":"md4-111-2-57","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"111年第2次第57題","year":111,"session":2,"number":57,"question":"高惡性度神經膠質瘤（high-grade glioma）與低惡性度神經膠質瘤（low-grade glioma）的臨床病症相比較，下列何者錯誤？","options":["(A) 高惡性度神經膠質瘤的病人較可能發生認知功能障礙","(B) 高惡性度神經膠質瘤的病人較可能發生單側上下肢體無力（hemiparesis）","(C) 高惡性度神經膠質瘤的病人較可能發生失語症（aphasia）","(D) 高惡性度神經膠質瘤的病人較可能發生癲癇發作（seizures）"],"answer":3,"image":""},{"id":"md4-111-2-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"111年第2次第58題","year":111,"session":2,"number":58,"question":"關於多發性硬化症（multiple sclerosis）急性發作時腦脊髓液檢查的敘述，下列何者錯誤？","options":["(A) 腦脊髓液中的總蛋白濃度常大於100 mg/dL","(B) 部分病人腦脊髓液中的白血球數量有輕微程度的增加","(C) 部分病人的腦脊髓液經免疫電泳分析後，可以發現在病人血清樣本中所不存在的oligoclonal bands","(D) 腦脊髓液中葡萄糖量是在正常範圍"],"answer":0,"image":""},{"id":"md4-111-2-59","subject":"md4","topic":"精神-精神病","meta":"111年第2次第59題","year":111,"session":2,"number":59,"question":"在精神狀態的檢查中，病患講話的速度快且難以打斷，話題不斷變化，內容多在描述其能力超過常人、可三天不睡也不累、只是在執行拯救地球的任務、不知道為何被要求住院。上述描述，不包括下列何者症狀？","options":["(A) 意念飛躍","(B) 解離現象","(C) 誇大妄想","(D) 無病識感"],"answer":1,"image":""},{"id":"md4-111-2-60","subject":"md4","topic":"神經-失智退化運動障礙","meta":"111年第2次第60題","year":111,"session":2,"number":60,"question":"關於失智症藥物的敘述，下列何者正確？","options":["(A) cholinesterase inhibitors類藥物對治療重度失智症有效","(B) donepezil因具中樞神經系統選擇性，相較其他cholinesterase inhibitor有較少的腸胃道副作用","(C) memantine為N-methyl-D-aspartate（NMDA）receptor agonist","(D) memantine多用於治療輕度阿茲海默失智症（Alzheimer's disease）"],"answer":1,"image":""},{"id":"md4-111-2-61","subject":"md4","topic":"精神-精神病","meta":"111年第2次第61題","year":111,"session":2,"number":61,"question":"有關精神疾病之治療，下列何者正確？","options":["(A) 躁期之治療藥物可包括鋰鹽（lithium）、valproic acid、抗憂鬱劑及抗精神病藥物（antipsychotics）","(B) 抗精神病藥物，例如：aripiprazole，已被FDA核准作為憂鬱症的輔助治療藥物","(C) 經顱刺激（transcranial magnetic stimulation）已被核可做為思覺失調症（schizophrenia）的治療","(D) 抗憂鬱劑在憂鬱症與雙相情緒障礙症（bipolar disorder）鬱期，都是首選藥物"],"answer":1,"image":""},{"id":"md4-111-2-62","subject":"md4","topic":"精神-精神病","meta":"111年第2次第62題","year":111,"session":2,"number":62,"question":"一位中年男性病人，深信女傭偷走他的錢，抽走他的想法，試圖對他不利。此外，眼前的太太只剩下外表，整個人的內在都被女傭所取代，而且電視都在報導他們家發生的事情。上述病情，沒有涵蓋下列何者症狀？","options":["(A) 關係妄想（referential delusions）","(B) 思考抽離（thought withdrawal）","(C) 被害妄想（persecutory delusions）","(D) 思考置入（thought insertion）"],"answer":3,"image":""},{"id":"md4-111-2-63","subject":"md4","topic":"精神-精神官能症","meta":"111年第2次第63題","year":111,"session":2,"number":63,"question":"功能性腸胃障礙（functional gastrointestinal disorder），最常伴隨的精神疾患為下列何者？","options":["(A) 焦慮疾患（anxiety disorders）","(B) 憂鬱疾患（depressive disorders）","(C) 思覺失調症（schizophrenia）","(D) 妄想症（delusional disorder）"],"answer":0,"image":""},{"id":"md4-111-2-64","subject":"md4","topic":"精神-精神官能症","meta":"111年第2次第64題","year":111,"session":2,"number":64,"question":"有關憂鬱症相關治療模式的敘述，下列何者正確？","options":["(A) 睡眠剝奪治療具持久性療效","(B) 照光治療（light therapy）屬有效治療，且無轉為躁症之風險","(C) 癲癇為經顱磁刺激治療（transcranial magnetic stimulation）最常見的副作用","(D) 嚴重個案合併藥物與心理治療，會比使用單一治療效果好"],"answer":3,"image":""},{"id":"md4-111-2-65","subject":"md4","topic":"精神-精神官能症","meta":"111年第2次第65題","year":111,"session":2,"number":65,"question":"有關疾病盛行率（prevalence）的性別差異，下列敘述何者錯誤？","options":["(A) 社交焦慮症（social anxiety disorder）女性罹病率高於男性","(B) 泛焦慮症（generalized anxiety disorder）女性罹病率高於男性","(C) 恐慌症（panic disorder）女性罹病率高於男性","(D) 強迫症（obsessive-compulsive disorder）女性罹病率高於男性"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第65題，一律給分。。 (原公告答案 D)"},{"id":"md4-111-2-66","subject":"md4","topic":"精神-精神官能症","meta":"111年第2次第66題","year":111,"session":2,"number":66,"question":"關於苯二氮平（benzodiazepine, BZD）類藥物的敘述，下列何者錯誤？","options":["(A) 急性副作用是嚴重的戒斷症候群","(B) 在精神疾病應用最主要的藥理作用，是加速入睡以及產生生理上鬆弛和心理上放鬆的效果","(C) 短效型BZD類藥物，可以迅速改善患者的症狀，再加上藥理上易產生耐受性（tolerance）的特性，是高度成癮性的藥物","(D) 高劑量或混合使用可產生肝臟毒性，長期使用會提高各類生理疾病和意外事故的風險"],"answer":0,"image":""},{"id":"md4-111-2-67","subject":"md4","topic":"精神-器質性與物質使用","meta":"111年第2次第67題","year":111,"session":2,"number":67,"question":"有關海洛因之中毒和戒斷，下列敘述何者正確？ ①Opioid、catecholamine、γ-aminobutyric acid system是形成藥物濫用和成癮最主要的神經傳導物質 ②急性中毒的症狀包括過度興奮、多話、記憶過度活躍、瞳孔擴大，如果用量過大而缺氧時會瞳孔縮小至針尖狀 ③戒斷症狀在停藥6至8小時後就可能出現，一般在7至10天內改善 ④戒斷症狀和locus ceruleus of pons有關，在停用海洛因時這區域的noradrenergic neurons會降低活性","options":["(A) 僅①③","(B) ①②④","(C) ①③④","(D) ②③④"],"answer":0,"image":""},{"id":"md4-111-2-68","subject":"md4","topic":"精神-器質性與物質使用","meta":"111年第2次第68題","year":111,"session":2,"number":68,"question":"依據美國精神醫學會所出版的精神疾病診斷準則手冊第五版（DSM-5），有關路易氏體認知障礙症的核心診斷特徵（core diagnostic feature）的認知功能，下列何者錯誤？","options":["(A) 結構且有系統的妄想","(B) 清楚而具體的視幻覺且反覆發生","(C) 認知波動合併有顯著的注意力和警覺力改變","(D) 認知退化進展後，發生自發性巴金森氏的特徵"],"answer":0,"image":""},{"id":"md4-111-2-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"111年第2次第69題","year":111,"session":2,"number":69,"question":"有關菸草使用疾患之敘述，下列何者錯誤？","options":["(A) 一般而言，戒斷症狀在使用最後一根菸的兩個小時內就會產生，戒斷高峰期為1至2天，有些則可持續至幾週或幾個月都可能有戒斷症狀","(B) 抽菸女性若能在懷孕前或懷孕第一產程前三個月時戒菸，可減少嬰兒出生體重過輕的危險性","(C) 門診思覺失調症患者約有30%吸菸，盛行率較其他精神疾病患者少","(D) 替代性治療可降低病人戒菸期間的戒斷症狀"],"answer":2,"image":""},{"id":"md4-111-2-70","subject":"md4","topic":"精神-器質性與物質使用","meta":"111年第2次第70題","year":111,"session":2,"number":70,"question":"與譫妄症病人會談時，即使已經問下一個問題，但是病人仍然反覆固著（perseverate）回答上一個問題，這種現象反應病人有下列何項認知功能障礙？","options":["(A) 察覺力（awareness）","(B) 轉換注意力（shift attention）","(C) 聚焦注意力（focus attention）","(D) 維持注意力（sustain attention）"],"answer":1,"image":""},{"id":"md4-111-2-71","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"111年第2次第71題","year":111,"session":2,"number":71,"question":"有關自閉症類群障礙症（autism spectrum disorder﹐ASD），下列敘述何者正確？","options":["(A) ASD盛行率男女的比例相當","(B) 臨床病患中，女生比男生更常出現智能不足（intellectual disability）","(C) ASD主要是單基因突變所導致的疾病","(D) 與一般族群相比，此症的手足罹患其他發展障礙症的比例並未較高"],"answer":1,"image":""},{"id":"md4-111-2-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"111年第2次第72題","year":111,"session":2,"number":72,"question":"有關妥瑞氏症（Tourette's disorder），下列敘述何者錯誤？","options":["(A) 具有高度遺傳病因，其中第13對染色體長臂可能與其病因有關","(B) 常會併有過動症及強迫症","(C) 在腦部影像學之研究顯示有幾個腦區與壓抑其症狀有關，包括蒼白球（globus pallidus）、殼核（putamen）、尾核（caudate nucleus）及前額葉（prefrontal cortex）","(D) 通常增加多巴胺之藥物，譬如治療過動症之藥物有可能用來治療妥瑞氏症狀"],"answer":3,"image":""},{"id":"md4-111-2-73","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"111年第2次第73題","year":111,"session":2,"number":73,"question":"有關自殺死亡的危險因子，下列敘述何者正確？","options":["(A) 一般而言，女性危險性較高","(B) 醫師族群中，精神科醫師屬高危險群之一","(C) 在所有年齡層中，兒童青少年危險性最高","(D) 精神疾病，例如思覺失調症或酒癮，並非重要因素"],"answer":1,"image":""},{"id":"md4-111-2-74","subject":"md4","topic":"神經-失智退化運動障礙","meta":"111年第2次第74題","year":111,"session":2,"number":74,"question":"55歲男性由於認知功能退化到精神科求診，根據所附頭部磁振造影（MRI）影像，下列何者為最可能的診斷？","options":["(A) 阿茲海默症（Alzheimer's disease）","(B) 額顳葉失智症（frontotemporal dementia）","(C) 路易氏體失智症（dementia with Lewy bodies）","(D) 血管性失智症（vascular dementia）"],"answer":3,"image":"md4-111-2-74.jpeg"},{"id":"md4-111-2-75","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"111年第2次第75題","year":111,"session":2,"number":75,"question":"關於嬰幼兒斜頸症，下列敘述何者最不恰當？","options":["(A) 嬰兒斜頸症大多為肌肉性斜頸症","(B) 大多發生在右側肌肉","(C) 6週大以前應安排髖關節超音波檢查","(D) 頸部磁振造影多可見頸長肌纖維化現象"],"answer":3,"image":""},{"id":"md4-111-2-76","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"111年第2次第76題","year":111,"session":2,"number":76,"question":"6歲女童倒在路邊，現場無其他路人，當你確認無呼吸、無心跳後開始CPR，壓胸與吹氣的比例為何？","options":["(A) 30：1","(B) 30：2","(C) 15：1","(D) 15：2"],"answer":1,"image":""},{"id":"md4-111-2-77","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"111年第2次第77題","year":111,"session":2,"number":77,"question":"性侵兒童者最常見於下列何種身分？","options":["(A) 陌生人","(B) 熟人","(C) 男人","(D) 老人"],"answer":1,"image":""},{"id":"md4-111-2-78","subject":"md4","topic":"皮膚-感染","meta":"111年第2次第78題","year":111,"session":2,"number":78,"question":"60歲漁夫過去病史有糖尿病與肝硬化，因處理魚鰭不慎刺傷左手，隔天出現發燒，手掌與手背出現暗黑色出血的水泡，檢傷時生命徵象如下：體溫38.1℃，心跳140/min，呼吸24/min，血壓80/54 mmHg，此病人的病因與處置，下列何者最正確？","options":["(A) 最有可能感染的致病菌是A群鏈球菌（group A streptococcus）","(B) 抗生素可以合併使用ceftriaxone和doxycycline","(C) 廣效的抗生素給與後如反應不佳，再照會外科執行清創","(D) 血管收縮劑如norepinephrine不適合用在此病人身上"],"answer":1,"image":""},{"id":"md4-111-2-79","subject":"md4","topic":"醫學倫理與法規","meta":"111年第2次第79題","year":111,"session":2,"number":79,"question":"小兒科的林醫師看診時，一位婦女依燈號進入診間，說明此次來是要為她5歲的兒子辦保險，需要開立診斷證明書，而兒子沒來。她的兒子於兩年前因志賀桿菌腸炎（Shigella enteritis）住院10天，林醫師是當時他的主治醫師。病人出院後未遵照出院時的約診回診，其後來門診4次看病，均不是給林醫師看。此位母親要求林醫師在診斷書上說明兒子2年前住院情形及目前一切正常。下列林醫師的那一種作法最不恰當？","options":["(A) 告知此位母親因孩子未來看診，不能開立上述內容的診斷書","(B) 給病人方便，依其要求開立上述內容的診斷書","(C) 請她下次帶孩子給他看過後再決定可以如何寫診斷書","(D) 請她詢問兒子保險公司業務員只開立前次住院之診斷書是否有幫助"],"answer":1,"image":""},{"id":"md4-111-2-80","subject":"md4","topic":"醫學倫理與法規","meta":"111年第2次第80題","year":111,"session":2,"number":80,"question":"未婚的60歲吳先生罹患進行性肌肉萎縮症，近20年來，他孤單地住在療養院完全躺臥在床。雖然他意識與智能正常，但須仰賴他人餵食及翻身，大小便也需他人協助。近2年來因為罹患尿毒症，療養院每週三次推他去接受洗腎。近半年來，雖然經各方輔導鼓勵，吳先生不停地要求:「不要再推他去洗腎，希望早日回天國，結束這一生的痛苦」。療養院人員與醫師均認為生命來自天主，堅持須繼續進行洗腎。下列何者最適當？","options":["(A) 應尊重吳先生的決定","(B) 應該珍惜生命，繼續進行洗腎到最後","(C) 需要法院判定才能停止洗腎","(D) 需由法定代理人決定是否停止洗腎"],"answer":0,"image":""},{"id":"md4-112-1-1","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"112年第1次第1題","year":112,"session":1,"number":1,"question":"根據兒童健康手冊的內容，下列關於兒童口腔保健的注意事項，何者最不適當？","options":["(A) 喝完母奶後，可用紗布幫寶寶清潔口腔、牙齦、舌頭及牙齒","(B) 在長出第一顆牙後至一歲期間，就可以開始看牙醫，並每一年進行一次牙齒塗氟","(C) 幼兒約12個月左右時，開始戒斷使用奶瓶餵奶，避免齲齒的發生","(D) 3～6歲的兒童可以使用含氟量1000 ppm的牙膏刷牙"],"answer":1,"image":""},{"id":"md4-112-1-2","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"112年第1次第2題","year":112,"session":1,"number":2,"question":"下列關於9個月的幼兒發展敘述，何者最可能為發展遲緩的警訊，須轉介做進一步評估？","options":["(A) 還不會自己坐穩數分鐘","(B) 還不會扶著站","(C) 還不會由躺著坐起來","(D) 還不會揮手再見"],"answer":0,"image":""},{"id":"md4-112-1-3","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"112年第1次第3題","year":112,"session":1,"number":3,"question":"下列何種情況與large anterior fontanel最不相關？","options":["(A) hypothyroidism","(B) achondroplasia","(C) hypoxic event","(D) prematurity"],"answer":2,"image":""},{"id":"md4-112-1-4","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"112年第1次第4題","year":112,"session":1,"number":4,"question":"孕期32週、出生體重1650公克的早產兒，4天大時發現腹脹、腸音減少、肚臍附近膚色變青紫。此病患最不可能的診斷為下列何者？","options":["(A) necrotizing enterocolitis","(B) intestinal perforation","(C) intestinal volvulus","(D) Hirschsprung disease"],"answer":3,"image":""},{"id":"md4-112-1-5","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"112年第1次第5題","year":112,"session":1,"number":5,"question":"下列關於新生兒黃疸（neonatal jaundice）及其相關疾病之敘述，何者最不適當？","options":["(A) 新生兒黃疸會從臉部開始變黃，隨著膽紅素（bilirubin）數值變高，膚色變黃的部位向下延伸","(B) 嚴重新生兒高膽紅素血症的危險因子包括出生後24小時內出現黃疸、母子血型不合、蠶豆症、出生週數超過41週等","(C) 母乳哺餵之新生兒較容易有新生兒黃疸，可能原因是腸肝循環（enterohepatic circulation）增加造成","(D) 核黃疸（kernicterus）是因未鍵結型（unconjugated）膽紅素沉積於基底核（basal ganglia）及腦幹神經核（brainstem nuclei）造成的"],"answer":1,"image":""},{"id":"md4-112-1-6","subject":"md4","topic":"兒科-心血管呼吸","meta":"112年第1次第6題","year":112,"session":1,"number":6,"question":"關於先天性心臟病盛行率的描述，下列何者最不適當？","options":["(A) 先天性心臟病在早產兒與死產胎兒中的比例，較一般健康新生兒來得高","(B) 先天性心臟病絕大多數出生沒多久就會有症狀，超過90%在出生1個月之內會被診斷","(C) 近年來先天性心臟病患者長大成人比例增加","(D) 先天性心臟病仍是先天性畸形兒童中，最常見的死亡原因"],"answer":1,"image":""},{"id":"md4-112-1-7","subject":"md4","topic":"兒科-心血管呼吸","meta":"112年第1次第7題","year":112,"session":1,"number":7,"question":"12歲女童因為學校健康檢查發現心電圖異常如圖，下列何種先天性心臟病最不可能？","options":["(A) 心房中隔缺損（atrial septal defect, ASD）","(B) 肺動脈瓣膜狹窄（pulmonary valvular stenosis）","(C) 主動脈弓窄縮（coarctation of aorta）","(D) 法洛氏四重症（tetralogy of Fallot）"],"answer":2,"image":"md4-112-1-7.jpeg"},{"id":"md4-112-1-8","subject":"md4","topic":"兒科-心血管呼吸","meta":"112年第1次第8題","year":112,"session":1,"number":8,"question":"有關法洛氏四重症（tetralogy of Fallot）病童發生缺氧性發作（blue spell or hypoxic spell）時，下列處置何者最不適當？","options":["(A) 給與O2 supplement","(B) 保持病童在knee-chest position","(C) 給與鎮靜藥物，減少病童哭鬧","(D) 給與支氣管擴張劑（β2 agonist）"],"answer":3,"image":""},{"id":"md4-112-1-9","subject":"md4","topic":"兒科-感染神經","meta":"112年第1次第9題","year":112,"session":1,"number":9,"question":"10歲兒童血清抗B型肝炎表面抗體陽性（anti-HBs positive），下列何項血清檢查最能區別此抗體是疫苗或是曾經感染B型肝炎病毒（HBV）所產生的？","options":["(A) 核心抗體IgM（anti-HBc IgM）","(B) 核心抗體IgG（anti-HBc IgG）","(C) 表面抗原（HBsAg）","(D) 病毒去氧核糖核酸（HBV DNA）"],"answer":1,"image":""},{"id":"md4-112-1-10","subject":"md4","topic":"兒科-消化系統疾病","meta":"112年第1次第10題","year":112,"session":1,"number":10,"question":"4週大男嬰無特殊病史，因餵奶後嘔吐4天就醫。嘔吐物為凝乳塊、沒有膽汁、沒有血，沒有發燒、皮膚疹。身體診察顯示前囟門凹陷（sunken anterior fontanel）、心搏快、上腹摸到橄欖狀腫塊。下列何項是最適當的診斷檢查？","options":["(A) 腹部電腦斷層檢查（computed tomographic scan of the abdomen）","(B) 腹部超音波檢查（abdominal ultrasonography）","(C) 腦部超音波檢查（brain ultrasonography）","(D) 腦部電腦斷層檢查（computed tomographic scan of the brain）"],"answer":1,"image":""},{"id":"md4-112-1-11","subject":"md4","topic":"兒科-消化系統疾病","meta":"112年第1次第11題","year":112,"session":1,"number":11,"question":"下列嬰兒膽汁滯留症（cholestasis）中，何者屬於肝外（extrahepatic）膽汁滯留？","options":["(A) 膽道閉鎖（biliary atresia）","(B) 拜勒病（Byler disease）","(C) 阿拉吉歐症候群（Alagille syndrome）","(D) 新生兒肝炎（neonatal hepatitis）"],"answer":0,"image":""},{"id":"md4-112-1-12","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"112年第1次第12題","year":112,"session":1,"number":12,"question":"關於抗利尿激素不適當分泌症候群（syndrome of inappropriate antidiuretic hormone secretion, SIADH），下列敘述何者最不適當？","options":["(A) 診斷SIADH需先排除腎病症候群、肝硬化、心衰竭、腎上腺或甲狀腺功能低下、利尿劑使用、脫水等造成低血鈉的原因","(B) 在低血鈉與低血液滲透壓（osmolality）的情況下，尿液滲透壓大於100 mOsm/kg","(C) 治療上主要為限制水分攝取，但不限制鈉鹽的攝取","(D) 血液中尿酸（uric acid）與尿素氮（BUN）數值通常偏高"],"answer":3,"image":""},{"id":"md4-112-1-13","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"112年第1次第13題","year":112,"session":1,"number":13,"question":"5歲的孩童主訴嚴重嘔吐及腹瀉4天，精神活力變差。腹瀉次數一天5～8次，已有兩天無法進食。心跳每分鐘150下，血壓72/50 mmHg，皮膚彈性（skin turgor）不佳，口腔黏膜乾燥。尿量明顯減少，血液鈉離子濃度175 mEq/L。下列敘述何者最不適當？","options":["(A) 應儘快於24小時內矯正血鈉至正常值","(B) 首先應儘快給與生理食鹽水20 mL/kg，於20分鐘內給完","(C) 可使用低張溶液（如5% dextrose + half-normal saline）矯正其高血鈉與脫水","(D) 治療高血鈉的併發症包括癲癇（seizure）甚至腦水腫（brain edema）"],"answer":0,"image":""},{"id":"md4-112-1-14","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"112年第1次第14題","year":112,"session":1,"number":14,"question":"下列何種兒童腎臟疾病在腎臟移植後，腎臟疾病復發的機率最低？","options":["(A) 先天性腎病症候群（congenital nephrotic syndrome）","(B) 局部腎絲球硬化症（focal segmental glomerulosclerosis）","(C) 第二型膜增生性腎小球腎炎（membranoproliferative glomerulonephritis type II）","(D) IgA腎病變（IgA nephropathy）"],"answer":0,"image":""},{"id":"md4-112-1-15","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"112年第1次第15題","year":112,"session":1,"number":15,"question":"有關貝塞特氏病（Behçet disease），下列敘述何者最不適當？","options":["(A) 嘴部潰瘍（oral ulcer）大多3～10天後修復無結痂","(B) 生殖器的潰瘍容易留下結痂","(C) 若影響眼睛造成葡萄膜炎，則後葡萄膜炎（posterior uveitis）為最常見","(D) pathergy test陽性是指用細針刺皮膚後24～48小時後產生pustular reaction"],"answer":2,"image":""},{"id":"md4-112-1-16","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"112年第1次第16題","year":112,"session":1,"number":16,"question":"有關Bruton agammaglobulinemia，下列敘述何者最不適當？","options":["(A) 是B-lymphocyte的先天性免疫缺失的疾病","(B) 主要是autosomal recessive，男女得病比例為1：1","(C) 通常是出生後6～9個月開始有症狀","(D) 定期輸注intravenous immunoglobulin（IVIG）是有效的治療方法"],"answer":1,"image":""},{"id":"md4-112-1-17","subject":"md4","topic":"兒科-心血管呼吸","meta":"112年第1次第17題","year":112,"session":1,"number":17,"question":"氣喘急性發作時的肺功能檢查數值，下列何者最不可能降低？","options":["(A) 尖峰呼氣流速值（peak expiratory flow, PEF）","(B) 第一秒用力呼氣量（forced expiratory volume in 1 second, FEV1）","(C) 第一秒流速容積比（FEV1/FVC, forced vital capacity）","(D) 肺總容量（total lung capacity, TLC）"],"answer":3,"image":""},{"id":"md4-112-1-18","subject":"md4","topic":"兒科-內分泌遺傳","meta":"112年第1次第18題","year":112,"session":1,"number":18,"question":"下列何種疾病通常不屬於性聯遺傳模式？","options":["(A) A型血友病（hemophilia A）","(B) 遺傳性球性紅血球症（hereditary spherocytosis）","(C) 蠶豆症（G6PD deficiency）","(D) 法布瑞氏症（Fabry disease）"],"answer":1,"image":""},{"id":"md4-112-1-19","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"112年第1次第19題","year":112,"session":1,"number":19,"question":"關於兒童缺鐵性貧血（iron-deficiency anemia），下列敘述何者最不適當？","options":["(A) 延遲斷臍（delayed clamping of the umbilical cord）1至3分鐘，可降低嬰兒缺鐵性貧血的發生率","(B) 青春期女生的缺鐵性貧血，常是因為月經出血與快速成長的關係","(C) 未經治療的缺鐵性貧血，抽血可見低鐵蛋白（ferritin）與高運鐵蛋白飽和度（transferrin saturation）","(D) 開始鐵劑補充約莫2至3天後，抽血可見網狀紅血球增多（reticulocytosis）"],"answer":2,"image":""},{"id":"md4-112-1-20","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"112年第1次第20題","year":112,"session":1,"number":20,"question":"有關化學治療藥物與其毒性的組合，下列何組較不相關？","options":["(A) doxorubicin：心臟毒性（cardiotoxicity）","(B) vincristine：出血性膀胱炎（hemorrhagic cystitis）","(C) bleomycin：肺部纖維化（pulmonary fibrosis）","(D) L-asparaginase：胰臟炎（pancreatitis）"],"answer":1,"image":""},{"id":"md4-112-1-21","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"112年第1次第21題","year":112,"session":1,"number":21,"question":"6歲22公斤重的男童，發燒4天、臉色蒼白、精神活力差、意識混亂、呼吸淺快，血氧濃度95%、血壓60/25 mmHg。下列處置何者最適當？","options":["(A) 給與生理食鹽水450 mL，輸注時間為1小時","(B) 進行快速誘導插管（rapid sequence intubation）","(C) 立刻輸注大量血液製品","(D) 每3分鐘給與一次強心劑（epinephrine）"],"answer":1,"image":""},{"id":"md4-112-1-22","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"112年第1次第22題","year":112,"session":1,"number":22,"question":"正常的呼吸速率範圍，早產兒應為每分鐘幾次？","options":["(A) 15～20次","(B) 25～30次","(C) 40～70次","(D) 75～90次"],"answer":2,"image":""},{"id":"md4-112-1-23","subject":"md4","topic":"兒科-心血管呼吸","meta":"112年第1次第23題","year":112,"session":1,"number":23,"question":"1歲大男孩，咳嗽流鼻水2天，今晚咳嗽變嚴重，體溫38.2℃且聲音沙啞，出現咳嗽如狗吠聲及費力呼吸，下列何者為最可能的診斷？","options":["(A) 氣喘（asthma）","(B) 細支氣管炎（bronchiolitis）","(C) 異物吸入（foreign body aspiration）","(D) 哮吼（croup）"],"answer":3,"image":""},{"id":"md4-112-1-24","subject":"md4","topic":"兒科-內分泌遺傳","meta":"112年第1次第24題","year":112,"session":1,"number":24,"question":"下列何種情況最不可能造成中樞性尿崩症（central diabetes insipidus）？","options":["(A) 蘭格罕細胞組織球增生症（Langerhans cell histiocytosis）","(B) 下視丘神經手術術後","(C) Wolfram氏症候群（Wolfram syndrome）","(D) 高血鈣（hypercalcemia）"],"answer":3,"image":""},{"id":"md4-112-1-25","subject":"md4","topic":"兒科-內分泌遺傳","meta":"112年第1次第25題","year":112,"session":1,"number":25,"question":"先天性甲狀腺功能低下症（congenital hypothyroidism）若區分為甲狀腺發育不全（dysgenesis）及合成異常（dyshormonogenesis）兩大類病因，下列那一選項的致病病因與其他三者最不相同？","options":["(A) Pendred syndrome","(B) lingual thyroid","(C) iodide transport defect","(D) iodide organification defect"],"answer":1,"image":""},{"id":"md4-112-1-26","subject":"md4","topic":"兒科-感染神經","meta":"112年第1次第26題","year":112,"session":1,"number":26,"question":"10歲男童，過去無病史且完整接種常規疫苗。近3日微燒，臉部及軀幹處出現10餘顆水泡及紅疹，常因搔癢抓破水泡，疹子型態如圖示，其班上同學也有類似疹子。最可能的診斷為何？","options":["(A) varicella","(B) scarlet fever","(C) hand-foot-mouth disease","(D) coronavirus disease 2019（COVID-19）"],"answer":0,"image":"md4-112-1-26.jpeg"},{"id":"md4-112-1-27","subject":"md4","topic":"兒科-感染神經","meta":"112年第1次第27題","year":112,"session":1,"number":27,"question":"關於兒童常見細菌性感染症，下列「疾病－常見細菌」的組合何者最不適當？","options":["(A) 皮膚膿瘍－金黃色葡萄球菌（Staphylococcus aureus）","(B) 猩紅熱（scarlet fever）－A群鏈球菌（group A Streptococcus）","(C) 泌尿道感染－沙門氏細菌（Salmonella）","(D) 骨關節炎－金黃色葡萄球菌（Staphylococcus aureus）"],"answer":2,"image":""},{"id":"md4-112-1-28","subject":"md4","topic":"兒科-感染神經","meta":"112年第1次第28題","year":112,"session":1,"number":28,"question":"9個月大女嬰發燒、躁動不安5天後住院。經給與ampicillin及gentamicin 2天後，發燒持續不退，雙腳與腹部出現一些紅疹，卡介苗結痂處出現發紅的變化。接下來，下列何項是最適當的檢查？","options":["(A) 皮膚結核菌素測試","(B) 腦部電腦斷層攝影","(C) 心臟超音波","(D) Widal試驗"],"answer":2,"image":""},{"id":"md4-112-1-29","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"112年第1次第29題","year":112,"session":1,"number":29,"question":"關於妥瑞氏症（Tourette disorder）或抽動症（tic disorder），下列敘述何者最不適當？","options":["(A) 發病年齡（age of onset）須小於18歲","(B) 病患有症狀時老師須提醒他不要發出聲音或有動作","(C) 並非所有病患都需要藥物治療","(D) 一般妥瑞氏症或抽動症的臨床嚴重度會在18～20歲以後大幅改善"],"answer":1,"image":""},{"id":"md4-112-1-30","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"112年第1次第30題","year":112,"session":1,"number":30,"question":"有關隱形脊柱裂（occult spinal bifida或occult spinal dysraphism），下列敘述何者最不適當？","options":["(A) 通常是指椎體（vertebral body）中線的缺損，但未合併脊髓或腦膜膨出","(B) 病灶上如果有合併毛髮、血管瘤，因為大多數患者無症狀，所以不需做影像學檢查","(C) 病灶處可能合併有皮膚凹陷、脂肪瘤、血管瘤或一撮毛髮等特徵，但無脊髓外露","(D) 常見在第五節腰椎（L5）至第一節薦椎（S1）的位置"],"answer":1,"image":""},{"id":"md4-112-1-31","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"112年第1次第31題","year":112,"session":1,"number":31,"question":"10歲大的男童，因為身上多處色素斑被帶至門診，身體診察發現軀幹以及四肢有7顆直徑超過5 mm大小不一的咖啡牛奶斑（café-au-lait spots），右上肢內側可摸到兩顆直徑約2 cm的軟瘤。有關此兒童的敘述何者最適當？","options":["(A) 合併學習障礙的機率比一般學童多","(B) 常合併視網膜色素沉著不全","(C) 常合併青光眼","(D) 常合併心臟腫瘤"],"answer":0,"image":""},{"id":"md4-112-1-32","subject":"md4","topic":"兒科-消化系統疾病","meta":"112年第1次第32題","year":112,"session":1,"number":32,"question":"關於兒童沙門氏桿菌腸胃炎，下列敘述何者最不適當？","options":["(A) 潛伏期約2～5天，平均為72小時","(B) 臨床症狀有嘔吐、腹絞痛，腹痛位置在肚臍周圍和下腹，伴隨輕度到嚴重的水瀉，糞便有時有黏液和血絲","(C) 沙門氏桿菌腸胃炎併發暫時性菌血症（transient bacteremia）的機率約1～5%","(D) 鐮刀型貧血症（sickle cell anemia）的兒童罹患沙門氏桿菌腸胃炎，需要使用抗生素治療"],"answer":0,"image":""},{"id":"md4-112-1-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"112年第1次第33題","year":112,"session":1,"number":33,"question":"有關粒線體DNA（mtDNA）與其所造成的疾病，下列敘述何者最不適當？","options":["(A) mtDNA突變的機率高於細胞核DNA","(B) 粒線體疾病的表徵多為影響神經肌肉的症狀","(C) mtDNA上tRNA的基因點突變（m.3243A＞G）會造成MELAS","(D) Leber hereditary optic neuropathy（LHON）男性發病機率低於女性"],"answer":3,"image":""},{"id":"md4-112-1-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"112年第1次第34題","year":112,"session":1,"number":34,"question":"有關乾癬（psoriasis）與脂漏性皮膚炎（seborrheic dermatitis）的敘述與比較，何者錯誤？","options":["(A) 皮膚切片不一定可以區分乾癬與脂漏性皮膚炎","(B) 脂漏性皮膚炎較常伴隨關節炎一起發生","(C) 乾癬患者若有human immunodeficiency virus（HIV）感染，可能以乾癬病灶嚴重惡化作為臨床表徵","(D) human immunodeficiency virus（HIV）感染者若有脂漏性皮膚炎，其脂漏性皮膚炎會比較嚴重"],"answer":1,"image":""},{"id":"md4-112-1-35","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"112年第1次第35題","year":112,"session":1,"number":35,"question":"對於刺激性接觸性皮膚炎（irritant contact dermatitis）與過敏性接觸性皮膚炎（allergic contact dermatitis）的比較，下列敘述何者較不適當？","options":["(A) 刺激性接觸性皮膚炎在接觸後症狀發作的速度較快","(B) 過敏性接觸性皮膚炎較可能會擴散至暴露處周圍甚至全身","(C) 過敏性接觸性皮膚炎是屬於第四型過敏反應（type IV hypersensitivity reaction）","(D) 抽血驗過敏原是診斷刺激性接觸性皮膚炎的主要方法"],"answer":3,"image":""},{"id":"md4-112-1-36","subject":"md4","topic":"皮膚-感染","meta":"112年第1次第36題","year":112,"session":1,"number":36,"question":"下列有關傳染性軟疣（molluscum contagiosum）之敘述，何者錯誤？","options":["(A) 在異位性皮膚炎等皮膚屏障不好的狀況下，可能會有較多且較持久的病灶","(B) 是人類乳突瘤病毒（human papilloma virus）透過皮膚接觸感染造成","(C) 有時可先觀察不治療，病人有機會靠自己的免疫力清除此病毒感染的病灶","(D) 可考慮藥物治療，如使用imiquimod cream"],"answer":1,"image":""},{"id":"md4-112-1-37","subject":"md4","topic":"皮膚-感染","meta":"112年第1次第37題","year":112,"session":1,"number":37,"question":"35歲女性體育老師主訴背上出現許多略癢的白色斑塊，視診發現其表面有局部脫屑，KOH檢查的結果如圖所示，下列敘述何者正確？","options":["(A) 此病人應為念珠菌（candida）感染","(B) 若病人有足癬（tinea pedis），則其身上的病灶與足癬應為同一致病原","(C) 若使用含有ketoconazole成分的外用藥，對於此疾病沒有療效","(D) 同樣的致病原也可能侵犯毛囊造成毛囊發炎"],"answer":3,"image":"md4-112-1-37.jpeg"},{"id":"md4-112-1-38","subject":"md4","topic":"皮膚-腫瘤","meta":"112年第1次第38題","year":112,"session":1,"number":38,"question":"45歲男性，自5個月前在右手拇指出現一個無症狀的淡紅色硬實結節（如圖一所示），X光攝影檢查未發現骨骼病變。皮膚手術切除病灶之病理檢查結果如附圖二。此患者最可能的診斷為下列何者？","options":["(A) 尋常疣（verruca vulgaris）","(B) 基底細胞癌（basal cell carcinoma）","(C) 後天性指纖維角化瘤（acquired digital fibrokeratoma）","(D) 角化棘皮瘤（keratoacanthoma）"],"answer":2,"image":"md4-112-1-38.jpeg"},{"id":"md4-112-1-39","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"112年第1次第39題","year":112,"session":1,"number":39,"question":"關於全身性硬化症（systemic sclerosis）的敘述，下列何者錯誤？","options":["(A) 患者常伴有Raynaud phenomenon","(B) 常出現heliotrope sign","(C) 可伴有食道吞嚥困難","(D) 血清ANA檢查常呈陽性"],"answer":1,"image":""},{"id":"md4-112-1-40","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"112年第1次第40題","year":112,"session":1,"number":40,"question":"自體免疫水疱病所產生皮膚表皮的裂解，下列何者最淺層？","options":["(A) pemphigus vulgaris","(B) pemphigus foliaceus","(C) pemphigus vegetans","(D) bullous pemphigoid"],"answer":1,"image":""},{"id":"md4-112-1-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"112年第1次第41題","year":112,"session":1,"number":41,"question":"19歲男性，約5年前開始在頸部、腋下及其他皺褶處之皮膚變厚變黑，如圖所示，最可能的診斷為何？","options":["(A) 黑癬（tinea nigra）","(B) 黑色棘皮症（acanthosis nigricans）","(C) 硬皮症（scleroderma）","(D) 發炎後色素沉澱（post-inflammatory hyperpigmentation）"],"answer":1,"image":"md4-112-1-41.jpeg"},{"id":"md4-112-1-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"112年第1次第42題","year":112,"session":1,"number":42,"question":"承上題，下列何者為此疾病最常見的相關致病因子？","options":["(A) 藥物","(B) 肥胖","(C) 癌症","(D) 感染"],"answer":1,"image":""},{"id":"md4-112-1-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"112年第1次第43題","year":112,"session":1,"number":43,"question":"下列有關尋常性魚鱗癬（ichthyosis vulgaris）之敘述，何者錯誤？","options":["(A) 是最常見的魚鱗癬疾病，與絲聚蛋白（filaggrin）基因突變有關","(B) 手掌掌紋會相較於一般人來的多（hyperlinearity）","(C) 通常皮膚症狀會在四肢的屈側及關節內側特別明顯","(D) 常合併毛孔角化症（keratosis pilaris）或異位性皮膚炎（atopic dermatitis）"],"answer":2,"image":""},{"id":"md4-112-1-44","subject":"md4","topic":"神經-中風","meta":"112年第1次第44題","year":112,"session":1,"number":44,"question":"50歲男性病人突然發生右側肢體無力，無顯影劑之腦部電腦斷層（non-contrast CT）檢查結果如下圖①，經顯影劑造影之腦部電腦斷層如下圖②。於圖②中箭頭所指的小白點，其名稱及意義為何？","options":["(A) spot sign；代表中風容易惡化且預後較差","(B) lentiform nucleus sign；代表中風發生於基底核的小血管","(C) dot sign；代表血管有阻塞，後續可能發生腦缺血","(D) insula ribbon sign；代表先發生缺血性中風，而後發生出血"],"answer":0,"image":"md4-112-1-44.jpeg"},{"id":"md4-112-1-45","subject":"md4","topic":"神經-中風","meta":"112年第1次第45題","year":112,"session":1,"number":45,"question":"針對可逆性後腦病變症候群（posterior reversible encephalopathy syndrome, PRES），下列敘述何者最不恰當？","options":["(A) 可能因血壓過高，超過大腦自主調節（autoregulation）的極限所造成","(B) 病人的神經學症狀會顯著改善，但腦部磁振造影的影像通常會長期存在明顯異常","(C) 病人常會出現頭痛和視覺異常的症狀","(D) 典型腦部影像會出現枕葉水腫，但該現象也有可能出現在其它腦區"],"answer":1,"image":""},{"id":"md4-112-1-46","subject":"md4","topic":"神經-中風","meta":"112年第1次第46題","year":112,"session":1,"number":46,"question":"關於急性缺血性腦中風病人使用靜脈血栓溶解劑，組織胞漿素原活化劑（tissue plasminogen activator, tPA）治療的敘述，下列何者錯誤？","options":["(A) 在發病4.5小時內使用可以增加功能回復的比率","(B) 治療前須確認腦部電腦斷層沒有顱內出血","(C) 對正在服用非維他命K口服抗凝血劑（non-vitamin K oral anticoagulants）的病人，要先抽血確認凝血功能在正常值範圍，才可以使用","(D) 如果懷疑是因為主動脈剝離（aortic dissection）所導致的急性腦中風症狀，絕對禁止使用"],"answer":2,"image":""},{"id":"md4-112-1-47","subject":"md4","topic":"兒科-感染神經","meta":"112年第1次第47題","year":112,"session":1,"number":47,"question":"8歲男童由父母帶來求診，主訴經常出現短暫性的恍神，一天可以發作上百次，每次只持續約10秒。病人智力正常，腦部電腦斷層和磁振造影無異常發現，腦波出現規律之全面性3Hz棘慢波複合波（spike–and–slow– wave），下列何種藥物最適合使用？","options":["(A) valproic acid","(B) levetiracetam","(C) phenytoin","(D) carbamazepine"],"answer":0,"image":""},{"id":"md4-112-1-48","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"112年第1次第48題","year":112,"session":1,"number":48,"question":"58歲男性，常被妻子抱怨幾乎每晚睡覺時鼾聲大作，而且鼾聲消失十幾秒後，突然又大聲喘息。他自覺不管睡多久，早晨醒來都沒有睡飽，且經常頭痛，白天工作時也常打瞌睡。下列何者與他的臨床診斷最沒有關係？","options":["(A) 肥胖","(B) 高血壓","(C) 扁桃腺肥大（large tonsils）","(D) 下顎前突（antero-flexed mandible）"],"answer":3,"image":""},{"id":"md4-112-1-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"112年第1次第49題","year":112,"session":1,"number":49,"question":"45歲女性，自15歲左右就偶爾頭痛。發作時常從下午持續到睡覺。發作位置在雙側，劇痛，常合併噁心想吐，畏光怕吵，需要躺下休息，身體活動會加劇頭痛。近十年來頭痛皆以止痛糖漿自行治療。近二年來頭痛越來越頻繁，幾乎兩、三天就得喝半瓶止痛糖漿。因近三個月來幾乎天天頭痛而來就診。下列敘述何者最適當？","options":["(A) 此病人之診斷應為緊縮型頭痛（tension-type headache）","(B) 此病人之診斷應為叢發性頭痛（cluster headache）","(C) 此病人之頭痛應為次發性頭痛，並無原發性頭痛","(D) 此病人之診斷應為偏頭痛合併藥物過度使用頭痛"],"answer":3,"image":""},{"id":"md4-112-1-50","subject":"md4","topic":"神經-失智退化運動障礙","meta":"112年第1次第50題","year":112,"session":1,"number":50,"question":"68歲女性主訴記憶力不佳，目前日常生活可自理，仍可擔任志工工作。她沒有憂鬱或是焦慮的症狀。她的蒙特利爾認知評估（Montreal Cognitive Assessment）得分23分（滿分30分），其中五項物品回想她都無法記起來，腦部磁振造影掃描結果正常。她最可能的診斷是：","options":["(A) 正常老化（normal aging）","(B) 輕度認知障礙（mild cognitive impairment）","(C) 失智症（dementia）","(D) 主觀認知退化（subjective cognitive decline）"],"answer":1,"image":""},{"id":"md4-112-1-51","subject":"md4","topic":"神經-失智退化運動障礙","meta":"112年第1次第51題","year":112,"session":1,"number":51,"question":"59歲男性因為姿勢性低血壓暈倒多次，他同時還有動作遲緩、步態不穩及性功能障礙問題，他的腦部磁振造影掃描結果如下圖，下列何者為最可能的診斷？","options":["(A) 行為變異型額顳葉失智症（behavioral variant frontotemporal dementia）","(B) 阿茲海默氏病（Alzheimer disease）","(C) 多重系統萎縮症（multiple system atrophy）","(D) 進行性上眼神經核麻痺症（progressive supranuclear palsy）"],"answer":2,"image":"md4-112-1-51.jpeg"},{"id":"md4-112-1-52","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"112年第1次第52題","year":112,"session":1,"number":52,"question":"關於庫賈氏病（Creutzfeldt-Jakob disease, CJD）致病原之敘述，下列何者正確？","options":["(A) 可以用134℃的高壓釜（autoclave）消毒手術器械，破壞該致病原","(B) 致病原內含有核糖核酸（RNA）","(C) 被致病原感染後的潛伏期（incubation period）短","(D) 食用罹患狂牛症的牛肉之後出現的變異型庫賈氏病（variant CJD）較易出現在年輕人"],"answer":3,"image":""},{"id":"md4-112-1-53","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"112年第1次第53題","year":112,"session":1,"number":53,"question":"格林–巴利症候群（Guillain-Barré syndrome）不同於重症肌無力（myasthenia gravis）的主要區別為何？","options":["(A) 自主神經功能異常","(B) 四肢癱瘓","(C) 吞嚥困難","(D) 呼吸困難"],"answer":0,"image":""},{"id":"md4-112-1-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"112年第1次第54題","year":112,"session":1,"number":54,"question":"關於脊髓空洞症（syringomyelia）的敘述，下列何者最不恰當？","options":["(A) 多發生在20～49歲的男性","(B) 在病變位置以下部位，同側的本體感覺及對側的疼痛感覺會有障礙","(C) 經常會合併Chiari type I malformation","(D) 可使用磁振造影（MRI）來確立診斷"],"answer":1,"image":""},{"id":"md4-112-1-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"112年第1次第55題","year":112,"session":1,"number":55,"question":"55歲男性，主訴漸進性全身無力兩年，神經學檢查發現舌頭顫動（tongue fasciculation）、口齒不清、吞嚥困難、四肢肌肉萎縮，無感覺異常，四肢深部肌腱反射增強，最可能罹患何種疾病？","options":["(A) 多次腦中風（multi-infarction）","(B) 頸部椎間盤突出（cervical herniated intervertebral disc）","(C) 巴金森氏病（Parkinson disease）","(D) 肌萎縮性側索硬化（amyotrophic lateral sclerosis）"],"answer":3,"image":""},{"id":"md4-112-1-56","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"112年第1次第56題","year":112,"session":1,"number":56,"question":"當病人疑似罹患急性細菌性腦膜炎時，下列給與抗生素治療的時機，何者最不合適？","options":["(A) 血液細菌培養採樣後","(B) 確定腦脊髓液的革蘭氏染色（Gram's stain）結果後","(C) 腦部電腦斷層攝影前","(D) 確定腦脊髓液細菌培養報告前"],"answer":1,"image":""},{"id":"md4-112-1-57","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"112年第1次第57題","year":112,"session":1,"number":57,"question":"下列何者不是視神經脊髓炎（neuromyelitis optica spectrum disorder, NMOSD）病人常見的共病症（comorbidity）之一？","options":["(A) 重症肌無力（myasthenia gravis）","(B) 胸腺瘤（thymoma）","(C) Sjögren's症候群（Sjögren's syndrome）","(D) 紅斑性狼瘡（systemic lupus erythematosus）"],"answer":1,"image":""},{"id":"md4-112-1-58","subject":"md4","topic":"兒科-內分泌遺傳","meta":"112年第1次第58題","year":112,"session":1,"number":58,"question":"下列有關威爾森氏病（Wilson disease）的敘述，何者正確？","options":["(A) 體染色體顯性遺傳，其致病基因是ATP7B基因","(B) 和鐵離子代謝相關的疾病","(C) 常出現肝硬化及角膜周邊有所謂的Kayser-Fleischer rings棕綠色環","(D) 可以用penicillin來治療"],"answer":2,"image":""},{"id":"md4-112-1-59","subject":"md4","topic":"精神-精神病","meta":"112年第1次第59題","year":112,"session":1,"number":59,"question":"下列何者是思覺失調症（schizophrenia）較好預後（good prognosis）之預測因子？","options":["(A) 較無誘發因素","(B) 發病年齡早，可及早治療","(C) 病程過程為急性發作","(D) 負性症狀比正性症狀明顯"],"answer":2,"image":""},{"id":"md4-112-1-60","subject":"md4","topic":"精神-精神病","meta":"112年第1次第60題","year":112,"session":1,"number":60,"question":"有關思覺失調症（schizophrenia）的敘述，下列何者最不適當？","options":["(A) 患者之第一等親罹患思覺失調症的機率較一般人高10倍","(B) 同卵雙胞胎罹病的機率約50%，顯示除了遺傳外仍有環境因素之影響","(C) 女性患者發病較早，預後較不佳","(D) 治療阻抗型之思覺失調症且對其他藥物反應不佳的患者可考慮clozapine治療，也可降低自殺風險，但有許多副作用，如體重增加、血糖血脂異常等代謝副作用"],"answer":2,"image":""},{"id":"md4-112-1-61","subject":"md4","topic":"精神-器質性與物質使用","meta":"112年第1次第61題","year":112,"session":1,"number":61,"question":"有關治療抗精神病藥物之副作用，下列敘述何者最不適當？","options":["(A) 合併糖尿病之個案若使用β-接受器阻斷propranolol來緩解靜坐不能（akathisia）時，可能會影響對低血糖應有之生理反應","(B) 哺乳婦女使用β-接受器阻斷propranolol應注意此藥物會經由乳汁分泌","(C) trihexyphenidyl用於減輕藥物引起之帕金森氏症，此藥物無濫用的風險","(D) trihexyphenidyl使用會惡化隅角閉鎖性青光眼與攝護腺肥大"],"answer":2,"image":""},{"id":"md4-112-1-62","subject":"md4","topic":"精神-精神官能症","meta":"112年第1次第62題","year":112,"session":1,"number":62,"question":"有關泛焦慮症（generalized anxiety disorder），下列敘述何者最不適當？","options":["(A) 個案常於年輕時即發病","(B) 因病情需要，可以單獨藥物治療或單獨心理治療，也可兩者合併治療","(C) 泛焦慮症為治療效果不錯的輕型精神疾病，不會慢性化（chronic condition）","(D) 負面生活事件（negative life events）可能誘發泛焦慮症發作"],"answer":2,"image":""},{"id":"md4-112-1-63","subject":"md4","topic":"精神-精神官能症","meta":"112年第1次第63題","year":112,"session":1,"number":63,"question":"下列何種治療模式或藥物可用於治療疼痛疾患（pain disorder）？①生理回饋（biofeedback） ②神經阻斷術（nerve blocks） ③抗憂鬱藥（antidepressants） ④催眠（hypnosis）","options":["(A) 僅①③","(B) 僅②④","(C) 僅①②③","(D) ①②③④"],"answer":3,"image":""},{"id":"md4-112-1-64","subject":"md4","topic":"精神-精神官能症","meta":"112年第1次第64題","year":112,"session":1,"number":64,"question":"抗憂鬱劑（antidepressants），例如selective serotonin reuptake inhibitors（SSRIs）或serotonin norepinephrine reuptake inhibitors（SNRIs）等，除了用於憂鬱症的治療外，還可用於治療下列何者？①疼痛症（pain disorder） ②泛焦慮症（generalized anxiety disorder） ③恐慌症（panic disorder） ④雙相情緒障礙症躁期（bipolar mania）","options":["(A) 僅①③","(B) 僅②④","(C) 僅①②③","(D) ①②③④"],"answer":2,"image":""},{"id":"md4-112-1-65","subject":"md4","topic":"精神-精神官能症","meta":"112年第1次第65題","year":112,"session":1,"number":65,"question":"吳小姐，22歲，墮胎後發現男友移情別戀，被雙親嚴厲指責後離家出走，忘記如何回家，深夜被路人發現送至警察局再轉送醫院急診，血液和神經影像檢測皆無異常，下列何者是最有可能的診斷？","options":["(A) 中風","(B) 適應障礙症","(C) 解離症","(D) 泛焦慮症"],"answer":2,"image":""},{"id":"md4-112-1-66","subject":"md4","topic":"精神-器質性與物質使用","meta":"112年第1次第66題","year":112,"session":1,"number":66,"question":"有關正常老化的生理、心理與社會的變化，下列敘述何者最不適當？","options":["(A) 神經質（neuroticism）的特質會隨著年紀變化","(B) 大腦重量會減少，腦室會變寬","(C) 到了最老的老年期（oldest-old），個性的外向性（extroversion）會輕微減弱，隨和性（agreeableness）會輕微增加","(D) 老年人的孤立感增加時，會增加罹患憂鬱的風險"],"answer":0,"image":""},{"id":"md4-112-1-67","subject":"md4","topic":"精神-器質性與物質使用","meta":"112年第1次第67題","year":112,"session":1,"number":67,"question":"長期酗酒後，若突然中斷或減少飲酒，有可能會出現酒精戒斷譫妄（alcohol withdrawal delirium），有關其臨床現象與處理上，下列敘述何者最不適當？","options":["(A) 是一種醫療急症（medical emergency），若未於急症期治療，會有約20%的致死（mortality）率","(B) 致死原因多和併發或並存的身體疾病有關，如肺炎、腎病、肝病變或心臟衰竭","(C) 首選預防戒斷用藥是抗精神病劑（antipsychotics）","(D) 雖然患者可能會呈現出十分激動或暴力行為，應儘量避免身體約束，以避免其對抗約束時呈現的體力過支（a dangerous level of exhaustion）"],"answer":2,"image":""},{"id":"md4-112-1-68","subject":"md4","topic":"神經-失智退化運動障礙","meta":"112年第1次第68題","year":112,"session":1,"number":68,"question":"Gerstmann syndrome是因為左側大腦受損產生的症候群，症狀之一是對講出手指的名稱有困難，下列何者為此症狀的名稱？","options":["(A) 手指失語（finger aphasia）","(B) 手指失用（finger apraxia）","(C) 手指失辨識（finger agnosia）","(D) 手指失憶（finger amnesia）"],"answer":2,"image":""},{"id":"md4-112-1-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"112年第1次第69題","year":112,"session":1,"number":69,"question":"72歲男性糖尿病患者，過去無菸酒史或鎮靜安眠藥物之使用，於接受白內障手術後當晚，出現視幻覺、情緒驚恐、坐立難安，以致於入睡困難；隔天開始有注意力不集中，且視幻覺又加重。下列何種藥物，對此患者症狀改善效果較好？","options":["(A) haloperidol","(B) lithium","(C) propranolol","(D) diazepam"],"answer":0,"image":""},{"id":"md4-112-1-70","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"112年第1次第70題","year":112,"session":1,"number":70,"question":"有關注意力不足／過動症（ADHD）的治療，下列何者最為適當？","options":["(A) ADHD個案單純接受藥物治療，ADHD的症狀並不會明顯改善","(B) 若個案合併焦慮與憂鬱症狀，同時接受藥物與社會心理行為治療者，會比單純使用藥物改善更顯著","(C) ADHD的藥物治療選擇有精神刺激劑（stimulants）與非精神刺激劑（non-stimulants）兩種，其中精神刺激劑具有高成癮性，因此是作為最後一線的治療選擇","(D) α-agonist類藥物（例如clonidine）有惡化抽搐症（tic disorders）的疑慮，因此不宜處方給合併有抽動症的ADHD個案"],"answer":1,"image":""},{"id":"md4-112-1-71","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"112年第1次第71題","year":112,"session":1,"number":71,"question":"有關精神疾患之敘述，下列何者最適當？","options":["(A) 社交畏懼症的好發年齡為需要很多社交活動的中壯年期","(B) 兒童若出現憂鬱症，情緒症狀表現與成人類似，但更常出現無望感、精神遲滯等症狀","(C) 兒童難以呈現典型的妄想和幻聽，所以無法診斷思覺失調症（schizophrenia）","(D) 兒童若出現雙相情緒障礙症（bipolar disorder），常表現非典型的躁、鬱症狀"],"answer":3,"image":""},{"id":"md4-112-1-72","subject":"md4","topic":"精神-精神病","meta":"112年第1次第72題","year":112,"session":1,"number":72,"question":"有關人格障礙症個案的防衛機轉（defensive mechanism），下列敘述何者最適當？ ①從想像的朋友獲得心理慰藉，是幻想（fantasy） ②和親密伴侶激烈爭吵後，突然忘記自己是誰，是解離（dissociation） ③每次醫師問到過往經驗，個案都不帶感情地詳細描述每一次被父母不良對待的經過和細節，是情感抽離（isolation of affect） ④在醫療過程不想付出努力，指責醫師不專業導致治療成效有限，是投射（projection）","options":["(A) 僅①③","(B) 僅①②④","(C) 僅②③④","(D) ①②③④"],"answer":3,"image":""},{"id":"md4-112-1-73","subject":"md4","topic":"精神-精神官能症","meta":"112年第1次第73題","year":112,"session":1,"number":73,"question":"關於經前不悅症（premenstrual dysphoric disorder），下列敘述何者最不適當？","options":["(A) 典型臨床表現為月經來潮前一週出現","(B) 症狀包括易怒、情緒起伏、焦慮及憂鬱等","(C) 若伴隨身體症狀如水腫、乳房壓痛等，就不是經前不悅症","(D) 選擇性血清素回收抑制劑（selective serotonin reuptake inhibitor, SSRI）是治療選項之一"],"answer":2,"image":""},{"id":"md4-112-1-74","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"112年第1次第74題","year":112,"session":1,"number":74,"question":"28歲女性，最近偶爾會有突發性的暈厥，腦部CT及MRI影像如附圖所示，下列敘述何者最不恰當？","options":["(A) 此腫瘤有鈣化現象","(B) 此腫瘤可能是瀰漫性膠質瘤（diffuse glioma）","(C) 此腫瘤可能是腦膜瘤（meningioma）","(D) 此腫瘤可能是寡樹突膠質細胞瘤（oligodendroglioma）"],"answer":2,"image":"md4-112-1-74.jpeg"},{"id":"md4-112-1-75","subject":"md4","topic":"神經-中風","meta":"112年第1次第75題","year":112,"session":1,"number":75,"question":"60歲女性因頭痛到急診就醫，根據所附頭部電腦斷層（CT）與電腦斷層血管造影（CTA）影像判斷，下列敘述何者正確？","options":["(A) 診斷為前交通動脈瘤破裂","(B) 治療方式包括經動脈栓塞或是外科手術","(C) 必須加做磁振血管造影（MRA）才能確定診斷","(D) 診斷為內頸動脈剝離"],"answer":1,"image":"md4-112-1-75.jpeg"},{"id":"md4-112-1-76","subject":"md4","topic":"精神-器質性與物質使用","meta":"112年第1次第76題","year":112,"session":1,"number":76,"question":"40歲男性，酒精性肝硬化病人，每天喝200 mL的58%高粱酒，已經30小時未曾再進食或喝酒，現在出現有情緒不穩且躁動、頭痛、血壓高，偶而會有癲癇發作，下列敘述何者最正確？","options":["(A) 治療此病人第一線選擇是benzodiazepine","(B) 此病人持續性產生癲癇時，過去沒有頭部病灶時，可以使用phenytoin來治療","(C) 此病人同時出現有幻覺時，產生視幻覺比聽幻覺更常見","(D) 此病人若為震顫性譫妄（delirium tremens），以現在醫療水準經過積極性治療後，死亡率仍偏高"],"answer":0,"image":""},{"id":"md4-112-1-77","subject":"md4","topic":"神經-中風","meta":"112年第1次第77題","year":112,"session":1,"number":77,"question":"有關腦部出血相關疾病，下列敘述何者正確？","options":["(A) 65歲男性，腦出血部位在額葉–顳葉（frontotemporal region）連接部位，是高血壓引起的腦出血好發部位之一","(B) 硬腦膜下（subdural）出血須要儘早手術，因為是腦動脈出血","(C) 蜘蛛膜下腔出血（subarachnoid hemorrhage）時，通常在第一次誤診的病人，臨床症狀會屬於Hunt and Hess Scale中的第一級（grade 1）較容易發生","(D) 小腦出血（cerebellar hemorrhage）時，原因與高血壓有關，在Romberg test及tandem gait會是正常的"],"answer":2,"image":""},{"id":"md4-112-1-78","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"112年第1次第78題","year":112,"session":1,"number":78,"question":"一般癲癇發作時的處理原則，何者最優先？","options":["(A) 立即靜脈注射抗癲癇藥物","(B) 發作期間給予正壓人工呼吸","(C) 讓病人側躺","(D) 立即進行氣管內管插管"],"answer":2,"image":""},{"id":"md4-112-1-79","subject":"md4","topic":"醫學倫理與法規","meta":"112年第1次第79題","year":112,"session":1,"number":79,"question":"年輕夫妻懷孕20週，胎兒超音波診斷為單純的左側唇裂，羊水染色體與基因晶片檢查無異常發現，然而夫妻要求終止懷孕。下列敘述何者最不恰當？","options":["(A) 倘若生育單邊唇裂寶寶會影響夫妻的精神健康狀態，應尊重夫妻之決定","(B) 遺傳諮詢時應說明單邊唇裂的治療成效，給予心理支持，並討論終止懷孕是否有必要","(C) 為維護胎兒生存權，建議召開雙方家族討論會，再根據共識決定","(D) 經詳盡溝通後，若醫師無法認同夫妻的決定，得拒絕施行人工流產"],"answer":2,"image":""},{"id":"md4-112-1-80","subject":"md4","topic":"醫學倫理與法規","meta":"112年第1次第80題","year":112,"session":1,"number":80,"question":"B醫師剛經歷一段痛苦的離婚過程。A醫師最近發現B醫師的行為怪異，疑似有藥物濫用的情形，在談話中獲得證實。B醫師要求A醫師幫忙保守秘密，稱這只是過渡時間罷了。A醫師勸B醫師應儘快尋求幫助、接受治療，但B醫師表示不需要。有一天，A和B醫師的主管察覺有異，特別來問A醫師：「B醫師怎麼了？」依照醫師倫理守則，有關A醫師之回應，下列何者最適當？","options":["(A) 醫師有保密的倫理義務，B醫師雖涉及藥物濫用，仍必須為其保密","(B) 三緘其口，因讓主管知道後，反而陷主管於處分或不處分的兩難，所以還是不要讓主管為難","(C) 據實以告，因為屬下對主管的詢問有絕對服從的忠誠義務","(D) 若B醫師的作為已影響專業判斷能力，增加病人風險，應告知主管以進行介入"],"answer":3,"image":""},{"id":"md4-112-2-1","subject":"md4","topic":"兒科-感染神經","meta":"112年第2次第1題","year":112,"session":2,"number":1,"question":"有關嬰兒玫瑰疹（roseola infantum）的敘述，下列何者最不恰當？","options":["(A) 最主要的致病原是HHV-6B","(B) 95%的病童年齡在2歲以前，感染年齡高峰期是6個月至9個月大","(C) 皮疹呈現從軀幹到面部和四肢，通常持續1～3天，但有時也可能只在幾個小時內可見後就消失","(D) 50%原發性HHV-6B感染的兒童，發燒時間可持續6天或更長時間"],"answer":3,"image":""},{"id":"md4-112-2-2","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"112年第2次第2題","year":112,"session":2,"number":2,"question":"足月出生，目前6個月大男嬰，體重7公斤，依照兒童健康手冊的附圖，下列敘述何者最適當？","options":["(A) 體重生長指標落在第15百分位，在平均數以下，應該立即轉介評估是否有成長不良","(B) 在100名同年齡的男寶寶裡，目前體重大約排在前第15位","(C) 若一個月大時體重是6公斤，目前生長曲線走勢掉了兩個曲線區間，需立即轉介評估","(D) 此月齡平均體重為8公斤，應積極衛教家屬多增加純配方奶哺餵以達成長所需"],"answer":2,"image":"md4-112-2-2.jpeg"},{"id":"md4-112-2-3","subject":"md4","topic":"兒科-心血管呼吸","meta":"112年第2次第3題","year":112,"session":2,"number":3,"question":"男嬰出生時立即發生呼吸窘迫及發紺症狀，身體診察發現腹部扁平、最強心尖搏動點（point of maximal impulse）在右胸，下列何者為最可能的診斷？","options":["(A) 先天性橫膈膜疝氣（congenital diaphragmatic hernia）","(B) 食道閉鎖氣管食道瘻管（esophageal atresia with tracheoesophageal fistula）","(C) 後鼻孔閉鎖（choanal atresia）","(D) 胃扭轉（gastric volvulus）"],"answer":0,"image":""},{"id":"md4-112-2-4","subject":"md4","topic":"兒科-心血管呼吸","meta":"112年第2次第4題","year":112,"session":2,"number":4,"question":"下列關於呼吸窘迫症候群（respiratory distress syndrome）的敘述，何者最不適當？","options":["(A) 臨床表現為early onset of tachypnea，可能合併retraction, grunting and cyanosis，通常剛出生就是呼吸窘迫最嚴重時，在24～72小時內恢復","(B) 胸部X光表現為low lung volumes, diffuse reticulogranular pattern, and air bronchograms","(C) 處置原則包括permissive hypercapnia及avoidance of hyperoxia","(D) 成因為surfactant deficiency，導致肺泡塌陷，無法維持適當功能肺餘容積"],"answer":0,"image":""},{"id":"md4-112-2-5","subject":"md4","topic":"兒科-消化系統疾病","meta":"112年第2次第5題","year":112,"session":2,"number":5,"question":"下列有關壞死性腸炎（necrotizing enterocolitis, NEC）風險因子的敘述，何者最不適當？","options":["(A) 母乳哺餵的新生兒較餵食配方乳者容易發生NEC","(B) 妊娠週數愈低的早產兒愈容易發生NEC","(C) 文獻上報告腸道菌叢生態與NEC的發生有關","(D) 足月兒的NEC常有次發之前置因子，如先天性心臟病等"],"answer":0,"image":""},{"id":"md4-112-2-6","subject":"md4","topic":"兒科-心血管呼吸","meta":"112年第2次第6題","year":112,"session":2,"number":6,"question":"兒童常會被聽到心雜音，下列何者不是功能性心雜音（innocent or functional murmur）的特色？","options":["(A) 中等音高（medium-pitched）的收縮期雜音（systolic murmur）","(B) 第三級的全收縮期雜音（pansystolic murmur）","(C) 心雜音的大小聲會受呼吸與姿勢影響","(D) 輕壓頸靜脈（jugular vein）可使心雜音變小聲"],"answer":1,"image":""},{"id":"md4-112-2-7","subject":"md4","topic":"兒科-感染神經","meta":"112年第2次第7題","year":112,"session":2,"number":7,"question":"8個月大男嬰，因高燒5天來求診，身體診察發現在卡介苗接種處出現紅腫、皮膚出現紅疹、舌頭紅腫如草莓般，眼結膜有充血現象，但沒什麼眼屎增加的感覺。下列何種疾病的可能性最高？","options":["(A) Kawasaki disease","(B) pharyngoconjunctival fever","(C) sepsis","(D) rheumatic fever"],"answer":0,"image":""},{"id":"md4-112-2-8","subject":"md4","topic":"兒科-心血管呼吸","meta":"112年第2次第8題","year":112,"session":2,"number":8,"question":"一週大的新生兒，被發現有發紺（cyanosis）的現象，胸部X光有明顯的肺部充血，懷疑可能有心臟血管異常，下列鑑別診斷何者最不需要考慮？","options":["(A) 心室中隔缺損（ventricular septal defect）","(B) 全肺靜脈回流異常（total anomalous pulmonary venous return）","(C) 三尖瓣閉鎖（tricuspid atresia）合併肺動脈狹窄（pulmonary stenosis）","(D) 動脈幹異常（truncus arteriosus）"],"answer":[0,2],"image":"","answer_note":"更正:第8題答Ａ或Ｃ或AC者均給分"},{"id":"md4-112-2-9","subject":"md4","topic":"兒科-消化系統疾病","meta":"112年第2次第9題","year":112,"session":2,"number":9,"question":"4週大足月男嬰無特殊病史，全母乳哺餵。因持續黃疸與解灰白色糞便就診。身體診察無生長遲滯，體溫、活動力正常，鞏膜與皮膚黃，並有輕度肝腫大、茶色尿。檢驗結果：total bilirubin 15 mg/dL、direct bilirubin 12.7 mg/dL、ALT 45 U/L、AST 52 U/L、ALP 600 U/L。下列敘述何者最不適當？","options":["(A) 剖腹探查及膽道攝影（laparotomy and direct cholangiography）是主要的診斷方式","(B) 肝切片組織病理顯示廣泛性發炎細胞浸潤、肝細胞壞死、肝內膽管無明顯異常，可以確診肝外膽道閉鎖（biliary atresia）","(C) 膽道閉鎖（biliary atresia）的手術方式稱為葛西氏手術（Kasai procedure）","(D) 膽道閉鎖（biliary atresia）手術的黃金時間為8週大以前"],"answer":1,"image":""},{"id":"md4-112-2-10","subject":"md4","topic":"兒科-消化系統疾病","meta":"112年第2次第10題","year":112,"session":2,"number":10,"question":"15歲男孩因臉部長青春痘求醫，醫生開立了藥物治療5天後，他出現了吞嚥疼痛的症狀，下列敘述何者最不適當？","options":["(A) 可能是doxycyline引起的食道炎","(B) 睡前服藥時沒有配足量的水喝是可能的原因","(C) 內視鏡檢查呈現廣泛性的食道潰瘍","(D) 支持性療法包括吃流質食物、抑酸劑等"],"answer":2,"image":""},{"id":"md4-112-2-11","subject":"md4","topic":"兒科-消化系統疾病","meta":"112年第2次第11題","year":112,"session":2,"number":11,"question":"1歲6個月大男童，無特殊病史，解大量褐紅色血便被送到急診。最近2週無發燒、嘔吐、腹痛、皮膚疹或服用藥物。男童平時每日解一次成形軟便，未曾發生血便。身體診察顯示略顯蒼白、心搏快、腹部軟、沒有壓痛（tenderness）或反彈痛（rebound tenderness）。血紅素值10.8 g/dL、糞便潛血反應呈陽性。下列何項檢查對於確定診斷的敏感性最高？","options":["(A) 腹部血管攝影（abdominal angiography）","(B) 肝膽道閃爍攝影（hepatobiliary scintigraphy）","(C) 梅克爾憩室檢查（Meckel scan enhanced with cimetidine）","(D) 上消化道內視鏡檢查（upper GI panendoscope）"],"answer":2,"image":""},{"id":"md4-112-2-12","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"112年第2次第12題","year":112,"session":2,"number":12,"question":"有關腎病症候群（nephrotic syndrome）患者容易受到感染的原因，下列何者最不適當？","options":["(A) 源於低免疫球蛋白血症（hypoglobulinemia）","(B) 源於低白血球症（leukopenia）","(C) 源於尿液流失補體C3與C5","(D) 源於尿液流失alternative pathway的factor B與factor D"],"answer":1,"image":""},{"id":"md4-112-2-13","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"112年第2次第13題","year":112,"session":2,"number":13,"question":"關於小兒夜間遺尿症（nocturnal enuresis），下列敘述何者最不適當？","options":["(A) 如果父母其中之一在小時候有夜間遺尿症，則其子女有夜間遺尿症的風險會提高","(B) 要先排除尿崩症、糖尿病和慢性腎臟疾病造成的次發性夜間遺尿症","(C) 應評估過夜禁食之尿液滲透壓，以排除多尿造成的次發性夜間遺尿症","(D) 因為藥物治療效果很好，應列為第一線治療"],"answer":3,"image":""},{"id":"md4-112-2-14","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"112年第2次第14題","year":112,"session":2,"number":14,"question":"有關兒童的紅斑性狼瘡腎炎（lupus nephritis）之敘述，下列何者最不適當？","options":["(A) 兒童的紅斑性狼瘡常合併腎炎","(B) WHO分級class IV的病童會出現血尿、蛋白尿與急性腎臟損傷的變化","(C) 類固醇脈衝治療（pulse therapy）與免疫抑制劑適用於所有分級的紅斑性狼瘡腎炎","(D) 血管張力素轉換酶抑制劑（ACEI）與血管張力素受體阻斷劑（ARB），可以有效控制血壓並且減少蛋白尿"],"answer":2,"image":""},{"id":"md4-112-2-15","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"112年第2次第15題","year":112,"session":2,"number":15,"question":"兒童異位性皮膚炎的好發位置，下列何者最不可能？","options":["(A) 嬰幼兒臉部","(B) 青少年四肢屈側","(C) 嬰幼兒包尿布區域","(D) 幼兒四肢伸側"],"answer":2,"image":""},{"id":"md4-112-2-16","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"112年第2次第16題","year":112,"session":2,"number":16,"question":"關於過敏機轉，下列敘述何者最不適當？","options":["(A) Th2在IgE相關過敏性疾病中扮演重要的角色","(B) Th2會分泌IL-4、IL-5、IL-13等細胞激素（cytokines）","(C) innate lymphoid cells（ILC）目前可分為ILC1s、ILC2s、ILC3s","(D) ILC3s會被IL-33、IL-25與TSLP活化而誘發過敏反應"],"answer":3,"image":""},{"id":"md4-112-2-17","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"112年第2次第17題","year":112,"session":2,"number":17,"question":"關於蕁麻疹（urticaria）的敘述，下列何者最不適當？","options":["(A) 症狀為突發性、隆起於皮膚的風疹塊（wheal）","(B) IgE媒介所導致的過敏反應","(C) 病灶持續時間達4星期，即為慢性蕁麻疹（chronic urticaria）","(D) 慢性蕁麻疹（chronic urticaria）會影響較深處的皮膚及黏膜組織造成腫脹，稱之為血管性水腫（angioedema）"],"answer":2,"image":""},{"id":"md4-112-2-18","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"112年第2次第18題","year":112,"session":2,"number":18,"question":"關於兒童特發性血小板減少性紫斑症（idiopathic thrombocytopenic purpura, ITP），下列敘述何者最適當？","options":["(A) 通常發生在病毒感染後1～4週後","(B) 好發年齡在11～14歲","(C) 常會合併嚴重貧血現象","(D) 治療以輸血小板為主"],"answer":0,"image":""},{"id":"md4-112-2-19","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"112年第2次第19題","year":112,"session":2,"number":19,"question":"關於兒童癌症，下列敘述何者最不適當？","options":["(A) 白血病是兒童最常見的癌症之一","(B) 實體腫瘤（solid tumor）的正確診斷常需要影像與組織學判讀","(C) 大部分兒童癌症主要的治療是使用標靶藥物","(D) 特定疾病（如神經纖維瘤）的兒童罹患癌症的風險會增加"],"answer":2,"image":""},{"id":"md4-112-2-20","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"112年第2次第20題","year":112,"session":2,"number":20,"question":"關於異體造血幹細胞移植的適應症，下列何者最不適當？","options":["(A) 重型地中海型貧血","(B) 急性淋巴性白血病","(C) 嚴重型再生不良性貧血","(D) 系統性紅斑性狼瘡"],"answer":3,"image":""},{"id":"md4-112-2-21","subject":"md4","topic":"兒科-心血管呼吸","meta":"112年第2次第21題","year":112,"session":2,"number":21,"question":"下列病因與兒童休克型態的關聯，何者最不適當？","options":["(A) 張力性氣胸：阻塞性（obstructive）","(B) 擴張性心肌病變：心因性（cardiogenic）","(C) 心包膜填塞：分布性（distributive）","(D) 腎病症候群：低容積性（hypovolemic）"],"answer":2,"image":""},{"id":"md4-112-2-22","subject":"md4","topic":"兒科-心血管呼吸","meta":"112年第2次第22題","year":112,"session":2,"number":22,"question":"下列何者不屬於低壓缺氧（hypobaric hypoxia）時所可能表現的順應（acclimatization）現象？","options":["(A) 呼吸加速","(B) 血壓上升","(C) 心跳加速","(D) 血管張力（venous tone）下降"],"answer":3,"image":""},{"id":"md4-112-2-23","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"112年第2次第23題","year":112,"session":2,"number":23,"question":"下列何種病因在兒童族群當中，最不會出現多尿（polyuria）症狀？","options":["(A) 中樞型尿崩症（central diabetes insipidus）","(B) 低血鈣症（hypocalcemia）","(C) 原發性多喝症（primary polydipsia）","(D) 第1型糖尿病（type 1 diabetes mellitus）"],"answer":1,"image":""},{"id":"md4-112-2-24","subject":"md4","topic":"兒科-內分泌遺傳","meta":"112年第2次第24題","year":112,"session":2,"number":24,"question":"下列關於兒童性早熟的敘述，何者最不適當？","options":["(A) 女孩8歲以前、男孩9歲以前有第二性徵的出現，即符合性早熟的定義","(B) 並非所有的性早熟都會影響病童的最終成人身高（adult height）","(C) 相較女孩而言，男孩性早熟有較高的可能是器質性（organic）原因所導致","(D) 中樞性性早熟的病童都應接受性釋素類似物（GnRH agonist）治療，以延緩青春期的進展"],"answer":3,"image":""},{"id":"md4-112-2-25","subject":"md4","topic":"兒科-內分泌遺傳","meta":"112年第2次第25題","year":112,"session":2,"number":25,"question":"13歲男孩因身材矮小而就診，出生時體重3公斤，父親164公分，母親153公分。此男孩身體診察顯示身高136公分（低於第3百分位），體重38公斤（第10百分位），左右睪丸均為4毫升，無陰毛發育，骨齡檢查結果為11歲。應優先考慮下列那一種診斷？","options":["(A) 家族性身材矮小（familial short stature）","(B) 體質性生長遲延（constitutional growth delay）","(C) 腦垂體低能症（hypopituitarism）","(D) 先天性腎上腺增生（congenital adrenal hyperplasia）"],"answer":2,"image":""},{"id":"md4-112-2-26","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"112年第2次第26題","year":112,"session":2,"number":26,"question":"患有潛在疾病的患者，常會增加特定嚴重感染的發生風險，下列潛在疾病與引發感染之組合，何者最不恰當？","options":["(A) 無脾症：常見b型流行嗜血桿菌和肺炎鏈球菌引起的菌血症","(B) 鐮狀細胞病：常見沙門氏菌引起的骨髓炎","(C) 補體缺乏：常見瘧原蟲引起的瘧疾","(D) 原發性先天性中性球減少症：常見金黃色葡萄球菌或綠膿桿菌感染之膿瘍"],"answer":2,"image":""},{"id":"md4-112-2-27","subject":"md4","topic":"兒科-感染神經","meta":"112年第2次第27題","year":112,"session":2,"number":27,"question":"3個月大男嬰近兩天在臉上、身上出現一些水泡樣的丘疹，無發燒，無呼吸道及腸胃道症狀。依據臨床表徵與接觸史，下列何者是最有可能的感染來源？","options":["(A) 2天前姐姐出現嬰兒玫瑰疹","(B) 2週前哥哥出現水痘","(C) 5天前媽媽出現帶狀疱疹","(D) 3週前鄰居出現手足口症"],"answer":1,"image":""},{"id":"md4-112-2-28","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"112年第2次第28題","year":112,"session":2,"number":28,"question":"3歲男童無特殊病史或藥物過敏史，因發燒就診，耳溫測量為40℃，診斷為急性扁桃腺炎。下列發燒處置及衛教，何者最不適當？","options":["(A) 可以使用ibuprofen暫時降溫","(B) 僅靠溫水拭浴無法達到降低體溫的效果","(C) 使用退燒藥無法改變疾病病程","(D) 發燒的機轉為身體散熱不良"],"answer":3,"image":""},{"id":"md4-112-2-29","subject":"md4","topic":"兒科-感染神經","meta":"112年第2次第29題","year":112,"session":2,"number":29,"question":"有關單純型熱性痙攣（simple febrile seizure）的敘述，下列何者最不適當？","options":["(A) 一般發生在6～60個月的孩童（巔峰12～18個月）","(B) 家族中有熱性痙攣病史的機率較一般人高","(C) 通常都在發燒的24小時以內發作，而且不超過一次","(D) 發作時間通常超過15分鐘，甚至可能產生癲癇重積狀態（status epilepticus）"],"answer":3,"image":""},{"id":"md4-112-2-30","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"112年第2次第30題","year":112,"session":2,"number":30,"question":"有關妥瑞氏症候群（Tourette syndrome）的敘述，下列何者最不適當？","options":["(A) 包含動作型、聲音型抽動（tics），症狀時間超過一年","(B) 需注意有無合併注意力不足／過動症（attention-deficit/hyperactivity disorder）","(C) 大多數個案在進入成年期，症狀會越來越明顯","(D) 有些個案可能會合併有強迫症（obsessive-compulsive disorder）"],"answer":2,"image":""},{"id":"md4-112-2-31","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"112年第2次第31題","year":112,"session":2,"number":31,"question":"下列何疾病會造成前囟門（anterior fontanelle）早期關閉？","options":["(A) craniosynostosis","(B) achondroplasia","(C) hypothyroidism","(D) hydrocephalus"],"answer":0,"image":""},{"id":"md4-112-2-32","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"112年第2次第32題","year":112,"session":2,"number":32,"question":"3個月大寶寶洗澡時被發現右側頭頂有一包血腫，無發燒、咳嗽、流鼻水等症狀，但是奶量減少且有些嗜睡。下列敘述何者最適當？","options":["(A) 這個年紀的頭部外傷，大多數是寶寶的日常活動受傷所導致","(B) 如臨床評估需要，腦部核磁共振（MRI）可初步偵測可能的腦內出血","(C) 身體診察發現寶寶的左大腿內側有瘀傷，此部位是此年紀活動常見的受傷部位","(D) 受虐性腦傷（abusive head trauma）應列入鑑別診斷"],"answer":3,"image":""},{"id":"md4-112-2-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"112年第2次第33題","year":112,"session":2,"number":33,"question":"有關粒線體基因致病性變異的遺傳（mitochondrial inheritance），下列敘述何者最不適當？","options":["(A) 粒線體DNA主要是遺傳自母親（maternal inherited）","(B) 男女皆有可能罹患此類疾病","(C) 變異形式主要為缺失（deletion）或點突變（point mutation）","(D) 一般人身上都帶有一個由母親遺傳而來的粒線體基因病變"],"answer":3,"image":""},{"id":"md4-112-2-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"112年第2次第34題","year":112,"session":2,"number":34,"question":"下列關於異位性皮膚炎（atopic dermatitis）的敘述，何者錯誤？","options":["(A) 嬰兒時期（infancy）可發生在臉部","(B) 嬰兒時期（infancy）多發生在肢體屈側（flexor side）","(C) 嬰兒時期（infancy）常伴隨食物過敏","(D) 成人時期（adulthood）的異位性皮膚炎，可以慢性手部濕疹（chronic hand eczema）作為表現"],"answer":1,"image":""},{"id":"md4-112-2-35","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"112年第2次第35題","year":112,"session":2,"number":35,"question":"55歲男性乾癬患者同時有高血壓及高血脂，自述最近乾癬症狀加劇。該病人服用之藥物如下，何者與乾癬惡化最為相關？","options":["(A) furosemide","(B) propranolol","(C) prazosin","(D) atorvastatin"],"answer":1,"image":""},{"id":"md4-112-2-36","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"112年第2次第36題","year":112,"session":2,"number":36,"question":"13歲男孩，近一個月在頸部出現皮疹如圖所示，最可能的診斷為何？","options":["(A) 汗管瘤（syringoma）","(B) 類澱粉症苔癬（lichen amyloidosus）","(C) 尋常性痤瘡（acne vulgaris）","(D) 扁平疣（verruca plana）"],"answer":3,"image":"md4-112-2-36.jpeg"},{"id":"md4-112-2-37","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"112年第2次第37題","year":112,"session":2,"number":37,"question":"承上題，下列何種治療較為適當？","options":["(A) 手術切除","(B) 外用類固醇","(C) 外用抗生素","(D) 冷凍治療"],"answer":3,"image":""},{"id":"md4-112-2-38","subject":"md4","topic":"皮膚-腫瘤","meta":"112年第2次第38題","year":112,"session":2,"number":38,"question":"8歲女童，主訴近兩年來發現右手食指指甲下出現如圖①所示慢慢變大而且會痛的增生物。臨床醫師排了一個X光攝影檢查，結果如圖②③箭頭所示。下列何者是最可能的診斷？","options":["(A) 甲下病毒疣（subungual viral wart）","(B) 甲下角化棘皮瘤（subungual keratoacanthoma）","(C) 甲下外生骨（subungual exostosis）","(D) 甲下血管球腫瘤（subungual glomus tumor）"],"answer":2,"image":"md4-112-2-38.jpeg"},{"id":"md4-112-2-39","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"112年第2次第39題","year":112,"session":2,"number":39,"question":"在國內使用下列何種藥物以前，建議先做HLA-B*1502基因檢測，以避免產生Stevens-Johnson syndrome或toxic epidermal necrolysis？","options":["(A) abacavir","(B) allopurinol","(C) carbamazepine","(D) hydralazine"],"answer":2,"image":""},{"id":"md4-112-2-40","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"112年第2次第40題","year":112,"session":2,"number":40,"question":"有關全身性硬化症（systemic sclerosis）各項症狀的治療選擇，下列何者正確？","options":["(A) 皮膚硬化；UVA1紫外光治療","(B) 手指潰瘍；局部類固醇注射","(C) 微血管擴張；口服類固醇治療","(D) 皮膚鈣化；復健物理治療（physiotherapy）"],"answer":0,"image":""},{"id":"md4-112-2-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"112年第2次第41題","year":112,"session":2,"number":41,"question":"有關下列疾病與指甲變化的配對，何者最不常見？","options":["(A) 乾癬（psoriasis）；點狀凹痕（pitting）","(B) 扁平苔癬（lichen planus）；指甲萎縮","(C) 圓禿（alopecia areata）；油滴狀變色（oil spot/ salmon spot）","(D) 甲癬（tinea unguium）；指甲下角質增厚（subungual hyperkeratosis）"],"answer":2,"image":""},{"id":"md4-112-2-42","subject":"md4","topic":"皮膚-感染","meta":"112年第2次第42題","year":112,"session":2,"number":42,"question":"下列有關化膿性汗腺炎（hidradenitis suppurativa）之敘述，何者錯誤？","options":["(A) 男性較女性常見","(B) 病灶通常呈對稱分布於腋下或腹股溝處","(C) 針對廣泛性反覆發作的病灶，手術切除合併皮瓣重建是一個合理的治療選項","(D) 長期發炎的病灶會有產生鱗狀上皮細胞癌的可能"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第42題一律給分 (原公告答案 A)"},{"id":"md4-112-2-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"112年第2次第43題","year":112,"session":2,"number":43,"question":"下列有關Darier disease之敘述，何者錯誤？","options":["(A) 為體染色體顯性遺傳疾病","(B) 冬季時因皮膚乾燥，病灶容易惡化","(C) 指甲脆弱易裂，並可見紅色或白色條紋（longitudinal bands）","(D) 皮膚可能合併細菌或病毒的感染"],"answer":1,"image":""},{"id":"md4-112-2-44","subject":"md4","topic":"神經-中風","meta":"112年第2次第44題","year":112,"session":2,"number":44,"question":"毛毛樣血管疾病（moyamoya disease），指的是下列何種病變？","options":["(A) 腦部腫瘤延著小血管擴散","(B) 腦部動靜脈畸形合併周圍血管增生","(C) 顱內大血管阻塞合併側枝循環增生","(D) 中樞結核感染合併血管炎"],"answer":2,"image":""},{"id":"md4-112-2-45","subject":"md4","topic":"神經-中風","meta":"112年第2次第45題","year":112,"session":2,"number":45,"question":"有關腦中風預防策略，下列敘述何者最不恰當？","options":["(A) 症狀性顱內中大腦動脈70%狹窄，應優先考慮使用抗凝血劑（anticoagulant）預防中風","(B) 症狀性顱外內頸動脈70%狹窄，可考慮頸動脈支架置放術（carotid artery stenting）預防中風","(C) 來源不明之栓塞型中風（embolic stroke of undetermined source），可使用抗血小板藥物預防中風","(D) CHA2DS2-VASc分數為0分之非瓣膜性心房顫動（atrial fibrillation），暫不使用抗血栓藥物"],"answer":0,"image":""},{"id":"md4-112-2-46","subject":"md4","topic":"神經-中風","meta":"112年第2次第46題","year":112,"session":2,"number":46,"question":"49歲男性平常有高血壓，因突發性右側肢體無力及麻木而就診，就診當天的無顯影劑腦部電腦斷層（non- contrast CT）檢查結果如下圖①，5天後的腦部磁振造影（MRI）檢查結果如下圖②（Fluid attenuated inversion recovery, FLAIR）及圖③無施打顯影劑之T1影像。下列何者最有可能是此病人的診斷？","options":["(A) 高血壓引發腦出血","(B) 腦腫瘤合併中心壞死（central necrosis）","(C) 多發性硬化症（multiple sclerosis）急性發作","(D) 弓形蟲（toxoplasma）腦內感染"],"answer":0,"image":"md4-112-2-46.jpeg"},{"id":"md4-112-2-47","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"112年第2次第47題","year":112,"session":2,"number":47,"question":"10歲女童因「夢遊症」求診，她入睡時間正常，但入睡後約1～3小時會突然從床上坐起來在房間走動，偶爾會打開門走出去，又走回臥室。整個發作期間都是一些簡單沒有實際意義的行為，每週約發生1次，每次持續約15～30分鐘，白天特別累時夜晚就容易發生，隔天早上不記得昨夜發生的事，腦波檢查沒有癲癇症的證據。下列敘述何者錯誤？","options":["(A) 通常發生在非快速動眼期睡眠（non-rapid eye movement sleep, NREM sleep）之第三期（stage N3）","(B) 有可能合併夜驚症（sleep terrors）和覺醒障礙症（confusional arousals）","(C) 發作時為夢境實演（dream enactment behavior）的行為","(D) 除非有安全上的考量，基本上不需要藥物治療"],"answer":2,"image":""},{"id":"md4-112-2-48","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"112年第2次第48題","year":112,"session":2,"number":48,"question":"下列何種神經傳導物質與偏頭痛最沒有關聯？","options":["(A) 降鈣素基因相關胜肽（calcitonin gene-related peptide）","(B) 血清素（serotonin or 5-hydroxytryptamine）","(C) 乙醯膽鹼（acetylcholine）","(D) 多巴胺（dopamine）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第48題一律給分 (原公告答案 C)"},{"id":"md4-112-2-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"112年第2次第49題","year":112,"session":2,"number":49,"question":"下列敘述何者最不可能是癲癇誘發因素？","options":["(A) 15歲女孩於3歲大時曾發作單純型熱痙攣（simple febrile seizure），後續神經學功能正常無後遺症","(B) 60歲陳舊性大片腦中風女性患者，近日發生尿路感染合併敗血症","(C) 38歲男性癲癇患者，因抗癲癇藥物用完自行停藥三日","(D) 55歲男性糖尿病患者血糖控制不佳，伴有酮酸中毒症"],"answer":0,"image":""},{"id":"md4-112-2-50","subject":"md4","topic":"神經-失智退化運動障礙","meta":"112年第2次第50題","year":112,"session":2,"number":50,"question":"關於巴金森氏病（Parkinson disease）之治療，下列何者錯誤？","options":["(A) 左多巴（levodopa）是黃金治療準則，愈早使用大劑量對病患愈有利","(B) 多巴胺促效劑（dopamine agonist）是治療選擇之一，尤其是對較年輕的患者","(C) 多巴胺促效劑（dopamine agonist）可作用於不同類型之dopamine receptors","(D) 對口服藥物藥效波動大的患者，視丘下核（subthalamic nucleus）刺激術是有效的治療選擇"],"answer":0,"image":""},{"id":"md4-112-2-51","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"112年第2次第51題","year":112,"session":2,"number":51,"question":"關於普里昂疾病（prion disease），下列敘述何者錯誤？","options":["(A) prion disease是因為病毒感染造成普里昂蛋白（prion protein）的錯誤摺疊（misfolding）之後形成的神經退化性疾病","(B) 可分為散發性（sporadic），普里昂蛋白基因突變（genetic mutations in the prion protein gene）及後天性（acquired），其中以散發性最多","(C) 散發性的庫賈氏症（sporadic Creutzfeldt-Jakob disease）臨床表現為快速進展的認知功能障礙、行為改變、動作障礙、視覺障礙及全身的症狀（constitutional symptoms）","(D) 散發性的庫賈氏症（sporadic Creutzfeldt-Jakob disease）診斷除臨床表現之外，目前尚需要腦波、腦部磁振造影或腦脊髓液的14-3-3蛋白檢測"],"answer":0,"image":""},{"id":"md4-112-2-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"112年第2次第52題","year":112,"session":2,"number":52,"question":"王小姐40歲，三年前開始出現不自主的動作如擠眉弄眼、扮鬼臉、聳肩、抬手或扭腰等等，在身體各部位出現，且愈來愈頻繁。一年前她記憶力有衰退現象，常常打錯字，她的父親在48歲時也出現類似症狀，在55歲時自殺死亡。她最可能的診斷是：","options":["(A) 脊髓小腦共濟失調症（spinocerebellar ataxia）","(B) 巴金森氏病（Parkinson disease）","(C) 亨丁頓氏病（Huntington disease）","(D) 肌萎縮性側索硬化（amyotrophic lateral sclerosis）"],"answer":2,"image":""},{"id":"md4-112-2-53","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"112年第2次第53題","year":112,"session":2,"number":53,"question":"下列疾病的臨床症狀，何者最不可能出現波動性（fluctuating）或間歇性（intermittent）無力？","options":["(A) 肌無力症候群（myasthenic syndrome）","(B) 甲狀腺亢進相關的低血鉀性肌肉無力（thyrotoxic hypokalemic weakness）","(C) 週期性麻痺（periodic paralysis）","(D) 運動神經元疾病（motor neuron disease）"],"answer":3,"image":""},{"id":"md4-112-2-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"112年第2次第54題","year":112,"session":2,"number":54,"question":"關於多發性肌炎（polymyositis）的敘述，下列何者最不恰當？","options":["(A) 常出現複視症狀","(B) 少數可能伴隨有癌症","(C) 主要為侵犯肢體近端肌肉","(D) 以類固醇治療為主"],"answer":0,"image":""},{"id":"md4-112-2-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"112年第2次第55題","year":112,"session":2,"number":55,"question":"18歲男性，游泳跳水時，不慎頭部撞擊到泳池底部，神經學檢查發現肛門反射（anal reflex）及球海綿體肌反射（bulbocavernosus reflex）消失，同時四肢運動及感覺功能喪失，其最佳的診斷為何？","options":["(A) 頸椎第五節（C5）前脊髓損傷","(B) 頸椎第五節（C5）後脊髓損傷","(C) 頸椎第五節（C5）中央脊髓症候群","(D) 頸椎第五節（C5）脊髓休克"],"answer":3,"image":""},{"id":"md4-112-2-56","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"112年第2次第56題","year":112,"session":2,"number":56,"question":"關於多發性硬化症（multiple sclerosis），下列敘述何者錯誤？","options":["(A) 為中樞神經白質去髓鞘病變（demyelinating disease）","(B) 緯度愈高，天氣愈冷的地區，發生率愈低","(C) 視神經發炎是常見的初始症狀","(D) 病人可能合併疲倦及沮喪等症狀"],"answer":1,"image":""},{"id":"md4-112-2-57","subject":"md4","topic":"神經-失智退化運動障礙","meta":"112年第2次第57題","year":112,"session":2,"number":57,"question":"唐氏症（Down syndrome）的病人在40歲之後會出現阿茲海默氏病（Alzheimer disease）的神經病理變化。這個現象是因為下列那個基因過度表現所造成的？","options":["(A) APOE","(B) PSEN1","(C) PSEN2","(D) APP"],"answer":3,"image":""},{"id":"md4-112-2-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"112年第2次第58題","year":112,"session":2,"number":58,"question":"關於急性化膿性腦膜炎（acute purulent meningitis）的敘述，下列何者最恰當？","options":["(A) 高達80%以上的病人會同時出現高燒、頸部僵硬及意識改變的臨床表徵","(B) 因B型鏈球菌（group B streptococcus）感染造成的比率約5%","(C) 在得知細菌培養結果之前，為防治具盤尼西林抗藥性的肺炎鏈球菌（S. pneumoniae），所使用的抗生素須包括第三代的頭孢菌素類（cephalosporin）","(D) 病人腦壓升高時，可能會出現心跳變快、血壓上升及呼吸不規則的變化"],"answer":2,"image":""},{"id":"md4-112-2-59","subject":"md4","topic":"精神-精神病","meta":"112年第2次第59題","year":112,"session":2,"number":59,"question":"有關妄想（delusion）內容的敘述，下列何者最適當？","options":["(A) 病人表示同事是受到黑道指使，要來殺害他的，事實卻非如此，是一種虛無（nihilistic）妄想","(B) 病人表示自己是神仙下凡，一直宣稱自己能夠拯救世人，是一種誇大（grandeur）妄想","(C) 病人表示同事對她笑就是對方愛上自己，雖然對方澄清絕無此意，病人仍堅持己見，是一種忌妒（jealousy）妄想","(D) 病人表示同事在走廊聊天，就是互傳訊息，想要聯手對付他，是一種控制（control）妄想"],"answer":1,"image":""},{"id":"md4-112-2-60","subject":"md4","topic":"精神-器質性與物質使用","meta":"112年第2次第60題","year":112,"session":2,"number":60,"question":"有關物質或藥物引發精神病症之敘述，下列何者最不適當？","options":["(A) 觸幻覺是使用古柯鹼（cocaine）的特徵","(B) 物質或藥物引發精神病症的妄想以被害妄想最常見","(C) 現實感（reality testing）佳","(D) 顳葉癲癇（temporal lobe epilepsy）可能導致嗅幻覺"],"answer":2,"image":""},{"id":"md4-112-2-61","subject":"md4","topic":"精神-精神病","meta":"112年第2次第61題","year":112,"session":2,"number":61,"question":"關於思覺失調症（schizophrenia）之敘述，下列何者最不適當？","options":["(A) 根據DSM-5，思覺失調症病人中約有5%～6%病患死於自殺，但此數據有可能被低估","(B) 負性症狀與mesolimbic pathway之異常有關","(C) 思覺失調症患者有相當比例有憂鬱症狀，也可使用抗憂鬱藥物合併治療","(D) 思覺失調症患者之認知功能退化比其正性精神症狀更可預測其社會功能影響"],"answer":1,"image":""},{"id":"md4-112-2-62","subject":"md4","topic":"精神-精神病","meta":"112年第2次第62題","year":112,"session":2,"number":62,"question":"有關情緒穩定劑之敘述，下列何者最不適當？","options":["(A) 鋰鹽（lithium）可降低雙相情緒障礙症（bipolar disorder）患者的自殺風險","(B) 情緒穩定劑相較於抗精神病藥物對懷孕胎兒畸形之危險較低","(C) 服用鋰鹽（lithium）治療應注意飲水量，以免鋰鹽濃度起伏過大","(D) 鋰鹽（lithium）濃度過高時可能出現手抖、腹瀉、口齒不清"],"answer":1,"image":""},{"id":"md4-112-2-63","subject":"md4","topic":"精神-精神官能症","meta":"112年第2次第63題","year":112,"session":2,"number":63,"question":"有關強迫症的治療，下列敘述何者最適當？","options":["(A) 精神分析心理治療非常有效","(B) benzodiazepine能有效預防","(C) 行為治療合併藥物治療具有療效","(D) lithium是首選藥物"],"answer":2,"image":""},{"id":"md4-112-2-64","subject":"md4","topic":"精神-精神病","meta":"112年第2次第64題","year":112,"session":2,"number":64,"question":"關於情緒障礙症（mood disorders）的敘述，下列何者最不適當？","options":["(A) 不同國家可觀察到重鬱症（major depressive disorder）之盛行率在女性約為男性的兩倍","(B) 第一型雙相情緒障礙症（bipolar I disorder）盛行率無性別差異","(C) 第一型雙相情緒障礙症患者中合併物質濫用、恐慌症與強迫症的比例高於重鬱症（major depressive disorder）患者","(D) 第二型雙相情緒障礙症的患者之自殺死亡率較第一型雙相情緒障礙症患者低，且其初發病年齡較晚"],"answer":3,"image":""},{"id":"md4-112-2-65","subject":"md4","topic":"精神-精神官能症","meta":"112年第2次第65題","year":112,"session":2,"number":65,"question":"陳先生35歲，經歷一次大車禍倖存，之後經常心悸、坐立不安、失眠、惡夢、凡事淡漠、不願提及該事件等，症狀已持續8個月未緩解，下列敘述何者最適當？","options":["(A) 其診斷最可能是適應障礙症（adjustment disorder）","(B) 其神經影像可能有杏仁核（amygdala）結構的改變","(C) 其神經影像會有基底核（basal ganglia）功能過低情況","(D) 頂葉（parietal lobe）會出現鈣化現象"],"answer":1,"image":""},{"id":"md4-112-2-66","subject":"md4","topic":"精神-精神官能症","meta":"112年第2次第66題","year":112,"session":2,"number":66,"question":"關於藥物對性功能的影響，下列何者最不適當？","options":["(A) selective serotonin-norepinephrine reuptake inhibitors（SNRIs）及selective serotonin reuptake inhibitors（SSRIs）可能導致低性欲及高潮障礙","(B) cyproheptadine與amantadine皆有助於改善selective serotonin reuptake inhibitors（SSRIs）導致之性功能異常","(C) lithium亦可能導致勃起障礙","(D) bupropion和risperidone能提高性慾"],"answer":3,"image":""},{"id":"md4-112-2-67","subject":"md4","topic":"神經-失智退化運動障礙","meta":"112年第2次第67題","year":112,"session":2,"number":67,"question":"有關失智症（dementia）之敘述，下列何者最不適當？","options":["(A) 一般研究發現年紀老化、有失智症家族史及女性為失智症的危險因子","(B) 大約三分之一的失智症患者在其失智症的病程中會出現妄想（delusion）及幻覺（hallucination）","(C) 失智症的病程通常是逐步（progressive），且不可逆（irreversible）的智能受損（intellectual impairment），而其盛行率隨年紀愈大而增加","(D) 老年人有憂鬱症、甲狀腺低下症或維他命缺乏可能會出現失智的症狀"],"answer":1,"image":""},{"id":"md4-112-2-68","subject":"md4","topic":"精神-器質性與物質使用","meta":"112年第2次第68題","year":112,"session":2,"number":68,"question":"下列有關海洛因之敘述，何者最適當？①中毒時宜給與naloxone進行緊急治療 ②意識混亂、呼吸淺、瞳孔縮小是海洛因戒斷的核心症狀 ③即使急性戒斷期過去，仍有可能殘存戒斷症狀達數個月之久 ④methadone和buprenorphine可使用於戒斷期，但是戒斷期過後再用此兩種藥物會不利於戒除海洛因","options":["(A) 僅①③","(B) ①②④","(C) ①③④","(D) ②③④"],"answer":0,"image":""},{"id":"md4-112-2-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"112年第2次第69題","year":112,"session":2,"number":69,"question":"有關K他命（ketamine）濫用，下列敘述何者最適當？","options":["(A) 使用後可能會產生幻覺和身體與現實解離狀態（dissociative state）","(B) 濫用途徑只能用注射或口服，不能用鼻吸入","(C) 不會導致如思覺失調症之精神病態","(D) 藥理機轉與安非他命相似，主要作用在多巴胺（dopamine）系統上"],"answer":0,"image":""},{"id":"md4-112-2-70","subject":"md4","topic":"精神-器質性與物質使用","meta":"112年第2次第70題","year":112,"session":2,"number":70,"question":"62歲男性每天平均飲用3瓶米酒，少進食已超過20年，某日中午依平常習慣飲用米酒後不久，出現步態不穩與意識混淆，送至醫院時身上仍有酒味，檢查發現有眼球震顫現象，針對立即的處置，下列何者最適當？","options":["(A) 給與短效型苯二氮平（benzodiazepine）","(B) 靜脈補充大量葡萄糖液","(C) 肌肉注射抗精神病劑，如haloperidol","(D) 注射thiamine"],"answer":3,"image":""},{"id":"md4-112-2-71","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"112年第2次第71題","year":112,"session":2,"number":71,"question":"有關自閉症類群障礙症（autism spectrum disorder）的語言症狀，下列敘述何者最適當？","options":["(A) 語言發展障礙是目前自閉症類群障礙症的核心診斷準則（core criteria）","(B) 若患者的口語用「你想要吃糖」來代表「我想要吃糖」，這是屬於仿說（echolalia）的症狀","(C) 大約有三分之二以上的患者從未發展出有用的語言（useful speech）","(D) 有些年幼的患者可能會讀許多字，但卻對所讀的字不太理解"],"answer":3,"image":""},{"id":"md4-112-2-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"112年第2次第72題","year":112,"session":2,"number":72,"question":"有關注意力不足／過動症的病因學與神經學研究，下列敘述何者最適當？","options":["(A) 主要是由環境因子而非基因遺傳所導致的疾病","(B) 遺傳率（heritability）大約為15%","(C) 腦部造影顯示大多數病患都有明顯的結構異常","(D) 前額葉（prefrontal cortex）的功能主要與注意力和衝動控制有關，為注意力不足／過動症常被研究的腦部區域"],"answer":3,"image":""},{"id":"md4-112-2-73","subject":"md4","topic":"醫學倫理與法規","meta":"112年第2次第73題","year":112,"session":2,"number":73,"question":"有關對病人進行約束與隔離的規範，下列敘述何者最不適當？","options":["(A) 情況緊急時，可以先口頭醫囑逕行之","(B) 必須定期審視並記錄被隔離或約束的病人的狀況","(C) 醫囑必須明確訂出方式與時間","(D) 初始醫囑如需延展，需要再次評估約束或隔離的必要性"],"answer":0,"image":""},{"id":"md4-112-2-74","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"112年第2次第74題","year":112,"session":2,"number":74,"question":"某病人常抱怨右側髖關節疼痛且走路一拐一拐的。門診的X光片影像如圖所示，下列敘述何者錯誤？","options":["(A) 此疾病好發於青少年","(B) 病灶在股骨頭（femoral head）","(C) 造成此問題的原因為生長板（growth plate）受傷","(D) 建議以保守治療為主，不建議手術治療"],"answer":3,"image":"md4-112-2-74.jpeg"},{"id":"md4-112-2-75","subject":"md4","topic":"神經-中風","meta":"112年第2次第75題","year":112,"session":2,"number":75,"question":"有關急性腦中風病人接受頭部電腦斷層檢查的結果，下列敘述何者錯誤？","options":["(A) 如果看到出血，則病人無法接受血栓溶解治療","(B) 有可能看到硬腦膜下出血或腫瘤","(C) 如果頭部電腦斷層檢查正常，則病人不需接受血栓溶解治療","(D) 在阻塞的大血管近端內出現高密度動脈徵象（dense artery sign），是急性缺血性中風的早期影像特徵之一"],"answer":2,"image":""},{"id":"md4-112-2-76","subject":"md4","topic":"神經-失智退化運動障礙","meta":"112年第2次第76題","year":112,"session":2,"number":76,"question":"80歲男性無故離家走失一天，被發現在公園呆坐自言自語，由救護人員送到急診室，生命徵象無明顯異常，家屬表示病人有失智症（dementia）病史。下列敘述何者最不適當？","options":["(A) 此病人的鑑別診斷應該包括譫妄（delirium）、失智症或精神疾病","(B) 失智症通常不會出現幻覺（hallucination）","(C) 如果病人有肢體震顫（tremor）的症狀，應該可以排除譫妄","(D) 病人抵達急診室後，應儘快做血糖檢測"],"answer":2,"image":""},{"id":"md4-112-2-77","subject":"md4","topic":"精神-精神官能症","meta":"112年第2次第77題","year":112,"session":2,"number":77,"question":"下列有關恐慌症（panic disorder）的敘述，何者最不適當？","options":["(A) 恐慌症會重複性發作，且發作後常伴隨對未來發作的擔憂","(B) 恐慌症的發作常有前兆，通常是可預期的","(C) 恐慌症一旦發作，通常數分鐘內症狀達到最嚴重","(D) selective serotonin reuptake inhibitors（SSRI）或selective norepinephrine reuptake inhibitors（SNRI）類的抗憂鬱藥物比alprazolam更適合當維持性治療藥物"],"answer":1,"image":""},{"id":"md4-112-2-78","subject":"md4","topic":"皮膚-感染","meta":"112年第2次第78題","year":112,"session":2,"number":78,"question":"一位85歲中風臥床的男性病人，平時住在安養中心，這幾天於指縫、腋下和鼠膝部出現紅疹合併癢的情形，其他同室住民也有類似症狀，下列敘述何者錯誤？","options":["(A) 接觸病人時必須做好接觸隔離","(B) 皮內隧道（burrow）是此皮膚病的特徵，最常出現在肚子的皮膚上","(C) 刮取少許隧道（burrow）的皮屑，在顯微鏡下觀察是否有疥蟲或是蟲卵可幫助診斷","(D) 免疫不全者或是糖尿病人，可出現高度角質的斑塊或是痂結"],"answer":1,"image":""},{"id":"md4-112-2-79","subject":"md4","topic":"醫學倫理與法規","meta":"112年第2次第79題","year":112,"session":2,"number":79,"question":"基因資訊的某些特質，使它比一般醫學檢驗更容易衍生倫理問題，關於這些特質，下列敘述何者最不適當？","options":["(A) 基因資訊通常涉及個人與家族","(B) 基因檢測通常可以準確地預測未來的疾病狀況","(C) 基因檢測常涉及無法有效治療或預防的疾病","(D) 基因檢測結果可能帶來對個人的歧視或傷害"],"answer":1,"image":""},{"id":"md4-112-2-80","subject":"md4","topic":"醫學倫理與法規","meta":"112年第2次第80題","year":112,"session":2,"number":80,"question":"5歲的女童因為末期腎病又無法透析，需要換腎治療，她有一個12歲的姊姊和4歲的弟弟。父母和姊姊都有意願捐腎給她。抽血基因比對發現母親不合，但是與爸爸和姊姊的基因匹配。爸爸擔心手術有風險，而且自己是家中唯一的經濟來源，希望醫師告訴其他家人他的基因「不匹配」，下列醫師處置何者最適當？","options":["(A) 醫師應遵從父親的要求，告訴其他的家人「出於醫療的原因」，父親不適合捐腎","(B) 告訴父親腎臟移植成功的機會大於父親因麻醉或手術死亡的概率，希望他重新考慮","(C) 尊重父親的選擇，改建議12歲的姊姊作為女童的腎臟捐贈者","(D) 避免破壞家庭成員間的和諧，建議放棄移植手術"],"answer":1,"image":""},{"id":"md4-113-1-1","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"113年第1次第1題","year":113,"session":1,"number":1,"question":"足月新生兒出生時為3000公克，下列有關體重成長的描述，何者最可能屬於異常值？","options":["(A) 3天大時，體重2600公克","(B) 5天大時，體重2800公克","(C) 1個月大時，體重4000公克","(D) 2個月大時，體重4900公克"],"answer":0,"image":""},{"id":"md4-113-1-2","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"113年第1次第2題","year":113,"session":1,"number":2,"question":"足月新生兒出生體重3200公克，出生後全母乳哺餵，7天大時體重為3150公克。血清總膽紅素為12 mg/dL，大便顏色正常且活力佳。媽媽非常擔心寶寶體重沒有增加及持續黃疸，下一步處置，下列何者最為適當？","options":["(A) 安排腹部超音波檢查","(B) 安排住院照光治療","(C) 建議持續追蹤觀察","(D) 建議媽媽停餵母奶"],"answer":2,"image":""},{"id":"md4-113-1-3","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"113年第1次第3題","year":113,"session":1,"number":3,"question":"有關早產兒呼吸暫停（apnea of prematurity）診斷的敘述，下列何者最不適當？","options":["(A) 定義為無症狀呼吸中止時間大於10秒","(B) 可能伴隨心搏過緩（bradycardia）","(C) 可能伴隨發紺（cyanosis）","(D) 早產兒呼吸暫停多屬於mixed apnea"],"answer":0,"image":""},{"id":"md4-113-1-4","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"113年第1次第4題","year":113,"session":1,"number":4,"question":"於產房剛出生的寶寶，經初始步驟處理後，發現呼吸窘迫、心跳每分鐘50下。下一步的處置，何者最為適當？","options":["(A) 開始胸外按壓","(B) 給與epinephrine","(C) 給與氧氣面罩","(D) 給與正壓換氣"],"answer":3,"image":""},{"id":"md4-113-1-5","subject":"md4","topic":"兒科-消化系統疾病","meta":"113年第1次第5題","year":113,"session":1,"number":5,"question":"下列關於壞死性腸炎（necrotizing enterocolitis）的敘述，何者最不適當？","options":["(A) 是新生兒時期最常見危及生命的腸胃道急症","(B) 三大危險因子為早產、腸道細菌移生（bacterial colonization of the gut）及配方奶餵食","(C) 臨床表現可能有活力差、體溫不穩定、腹脹、餵食不耐受、血便等，嚴重者可能腸穿孔、腹膜炎、休克，甚至死亡","(D) 腹部X光典型特徵有腸壁積氣（pneumatosis intestinalis），通常在出生後1週內發生"],"answer":3,"image":""},{"id":"md4-113-1-6","subject":"md4","topic":"兒科-心血管呼吸","meta":"113年第1次第6題","year":113,"session":1,"number":6,"question":"關於先天性心臟病嬰兒與兒童的一般性照顧原則，下列敘述何者最不適當？","options":["(A) 絕大多數的常規疫苗都可以施打，包括流行性感冒疫苗","(B) 呼吸道融合病毒單株抗體的施打對於有血行動力學明顯異常的病人很重要","(C) 所有先天性心臟病兒童在做牙科治療前都必須進行細菌性心內膜炎的預防","(D) 對於發紺性心臟病的病童，要特別注意脫水與缺鐵性貧血的問題"],"answer":2,"image":""},{"id":"md4-113-1-7","subject":"md4","topic":"兒科-心血管呼吸","meta":"113年第1次第7題","year":113,"session":1,"number":7,"question":"在下列何種危急型先天性心臟病的新生兒中使用前列腺素E1（prostaglandin E1, PGE1），對病情最沒有幫助？","options":["(A) 嚴重主動脈弓窄縮（coarctation of the aorta）","(B) 三尖瓣閉鎖（tricuspid atresia）","(C) 危急型肺動脈瓣狹窄（critical pulmonary valve stenosis）","(D) 上心臟型全肺靜脈回流異常合併阻塞（supracardiac type total anomalous pulmonary venous return with obstruction）"],"answer":3,"image":""},{"id":"md4-113-1-8","subject":"md4","topic":"兒科-心血管呼吸","meta":"113年第1次第8題","year":113,"session":1,"number":8,"question":"新生兒出生後24小時測量其上肢及下肢血氧飽和度，如果測得血氧異常且下肢血氧飽和度較上肢低10％，因而懷疑是發紺型先天性心臟病，下列何者最不可能？","options":["(A) 左心室發育不全症候群（hypoplastic left heart syndrome）","(B) 大動脈轉位（transposition of the great arteries）","(C) 輕度及中度肺動脈瓣狹窄(mild or moderate pulmonary stenosis)","(D) 主動脈弓中斷（interrupted aortic arch）"],"answer":2,"image":""},{"id":"md4-113-1-9","subject":"md4","topic":"兒科-消化系統疾病","meta":"113年第1次第9題","year":113,"session":1,"number":9,"question":"關於先天性巨大結腸症，下列敘述何者最適當？","options":["(A) 致病機轉為在脹大的結腸黏膜下層（submucosal）和肌間層（myenteric plexus）缺少神經節細胞（ganglion cells）","(B) 早產兒胎便超過48小時未解，可診斷此疾病","(C) 腹脹是最常見症狀，嘔吐、生長不良、腹瀉都可能發生","(D) 手術治療唯一方法要先做腸造瘻口（ostomy），等嬰兒營養狀態改善後再做一次確切（definite）的手術"],"answer":2,"image":""},{"id":"md4-113-1-10","subject":"md4","topic":"兒科-消化系統疾病","meta":"113年第1次第10題","year":113,"session":1,"number":10,"question":"12歲男童，體重85公斤，因為發燒、上腹痛、背痛與嘔吐到兒科急診就醫。男童無外傷、排尿正常及無腹瀉。身體診察顯示上腹部與背部有壓痛（tenderness）；血清脂解酶（lipase）濃度為正常值上限之5倍；腹部超音波檢查顯示胰臟明顯腫大。下列何項處置最不適當？","options":["(A) 給與鎮痛藥物以控制疼痛","(B) 積極給與靜脈輸液補充治療","(C) 停止嘔吐後即可開始進食","(D) 應常規給與預防性廣效型抗生素"],"answer":3,"image":""},{"id":"md4-113-1-11","subject":"md4","topic":"兒科-感染神經","meta":"113年第1次第11題","year":113,"session":1,"number":11,"question":"下列肝炎病毒中，何者最容易經由媽媽垂直感染嬰兒？","options":["(A) A型","(B) B型","(C) C型","(D) E型"],"answer":1,"image":""},{"id":"md4-113-1-12","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"113年第1次第12題","year":113,"session":1,"number":12,"question":"下列何者最不可能引起高血鉀？","options":["(A) 腎衰竭（renal failure）","(B) 使用藥物furosemide（diuretics）","(C) 橫紋肌溶解症（rhabdomyolysis）","(D) 使用藥物cyclosporine（calcineurin inhibitor）"],"answer":1,"image":""},{"id":"md4-113-1-13","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"113年第1次第13題","year":113,"session":1,"number":13,"question":"關於先天性腎源性尿崩症（congenital nephrogenic diabetes insipidus, CNDI），下列敘述何者最不適當？","options":["(A) 最常見的遺傳模式是X-linked recessive","(B) 大多數的CNDI是因AQP2基因突變引起","(C) CNDI的治療包括要限制鈉的攝取量","(D) 藥物治療上建議使用thiazide類的利尿劑"],"answer":1,"image":""},{"id":"md4-113-1-14","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"113年第1次第14題","year":113,"session":1,"number":14,"question":"關於兒童急性腎損傷（acute kidney injury, AKI）的診斷與處置，下列何者最不適當？","options":["(A) 高血鉀症的心電圖變化包括：高T波、QRS波變寬、ST節段下降等","(B) 高血鉀症時，使用葡萄糖酸鈣（calcium gluconate）可快速的穩定心肌，但並無降血鉀功能","(C) 在身體水份足夠前提下，對利尿劑（furosemide）完全無反應，應即停用利尿劑並限水","(D) 應積極的補充碳酸氫鈉（NaHCO3），以維持重碳酸鹽（HCO3）在20～26 mEq/L的範圍"],"answer":3,"image":""},{"id":"md4-113-1-15","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"113年第1次第15題","year":113,"session":1,"number":15,"question":"有關antinuclear antibody（ANA）呈現陽性，下列敘述何者最不適當？","options":["(A) 通常titer越高，自體免疫疾病的可能性越高","(B) 正常人不到1%會呈現陽性，因此特異度（specificity）達90%","(C) 95%以上的systemic lupus erythematosus（SLE）患者會呈現陽性","(D) 其titer高低與SLE的疾病活性（disease activity）無關"],"answer":1,"image":""},{"id":"md4-113-1-16","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"113年第1次第16題","year":113,"session":1,"number":16,"question":"關於全身性紅斑性狼瘡（systemic lupus erythematosus, SLE），下列敘述何者最不適當？","options":["(A) 引起腎絲球腎炎最主要的致病機轉為免疫複合體（immune complex）沉積","(B) 是一種慢性發炎性疾病","(C) 好發於女性","(D) 影響血液系統會造成白血球及血小板上升"],"answer":3,"image":""},{"id":"md4-113-1-17","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"113年第1次第17題","year":113,"session":1,"number":17,"question":"有關嬰兒異位性皮膚炎（atopic dermatitis），下列敘述何者最不適當？","options":["(A) 大部分患童在一出生即有皮膚炎表現","(B) 長大後較易罹患氣喘及過敏性鼻炎","(C) 嬰兒期好發於兩頰、頭皮與四肢伸側","(D) 具家族史及血中極高的IgE為預後不佳之指標"],"answer":0,"image":""},{"id":"md4-113-1-18","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"113年第1次第18題","year":113,"session":1,"number":18,"question":"在急性淋巴性白血病中，下列何種分子或染色體變化代表預後不佳？","options":["(A) ETV6-RUNX1；t(12;21)","(B) hyperdiploidy；＞50 chromosomes","(C) KMT2A(MLL)-AF4；t(4;11)","(D) TLX1/HOX11；t(10;14)"],"answer":2,"image":""},{"id":"md4-113-1-19","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"113年第1次第19題","year":113,"session":1,"number":19,"question":"關於遺傳性癌症易感症候群（syndromes predisposing to cancer）與其較可能罹患腫瘤的對照，下列何者最不適當？","options":["(A) 神經纖維瘤第1型：惡性周邊神經鞘腫瘤（malignant peripheral nerve sheath tumor）","(B) 神經纖維瘤第2型：視神經膠質瘤（optic glioma）","(C) 家族性視網膜母細胞瘤（familial retinoblastoma）：骨肉瘤","(D) Li-Fraumeni症候群：肉瘤、腎上腺皮質上皮瘤、乳癌"],"answer":1,"image":""},{"id":"md4-113-1-20","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"113年第1次第20題","year":113,"session":1,"number":20,"question":"3歲蠶豆症（G6PD deficiency）男童在吃了一整包蠶豆酥的隔天，出現了深色尿、黃皮膚。抽血檢查發現Hb 7.5 gm/dL。關於男童的情況，下列敘述何者最適當？","options":["(A) 蠶豆症為體隱性遺傳，是臺灣新生兒篩檢項目之一","(B) 此男童的周邊血液抹片檢查可能見到bite cell型態的紅血球","(C) 此男童應該是產生了Coombs test positive hemolysis","(D) 針對此男童，退燒藥選擇aspirin（acetylsalicylic acid）比diclofenac更適合"],"answer":1,"image":""},{"id":"md4-113-1-21","subject":"md4","topic":"兒科-心血管呼吸","meta":"113年第1次第21題","year":113,"session":1,"number":21,"question":"關於兒童異物吸入所引起之呼吸道阻塞，下列敘述何者最不適當？","options":["(A) 可能會聽到喘鳴（stridor）的聲音","(B) 即使沒有看到異物，也應儘速將手指伸入兒童的嘴巴，將異物挖出","(C) 如果意識清醒，可鼓勵兒童咳嗽，將異物咳出","(D) 小於1歲使用拍背壓胸法，大於1歲使用的哈姆立克法是腹部壓迫法"],"answer":1,"image":""},{"id":"md4-113-1-22","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"113年第1次第22題","year":113,"session":1,"number":22,"question":"2歲女童，安靜時出現下列何種現象時，應注意可能有組織灌流不足的狀況？","options":["(A) 呼吸速率為每分鐘20～30次","(B) 心跳速率為每分鐘160下","(C) 四肢末梢溫暖，無大理石斑","(D) 微血管回填時間為1.5秒"],"answer":1,"image":""},{"id":"md4-113-1-23","subject":"md4","topic":"兒科-內分泌遺傳","meta":"113年第1次第23題","year":113,"session":1,"number":23,"question":"生長激素注射治療在許多疾病有實證醫學證據支持，且符合美國FDA及臺灣健保給付標準，但不包括下列何種疾病？","options":["(A) 狄喬治氏症候群（DiGeorge syndrome）","(B) 透納氏症候群（Turner syndrome）","(C) SHOX基因異常（SHOX gene abnormality）","(D) 普瑞德威利氏症候群（Prader-Willi syndrome）"],"answer":0,"image":""},{"id":"md4-113-1-24","subject":"md4","topic":"兒科-內分泌遺傳","meta":"113年第1次第24題","year":113,"session":1,"number":24,"question":"失鹽型之先天性腎上腺增生症（congenital adrenal hyperplasia, salt-wasting form）為腎上腺酵素缺乏的疾病。下列何項最不符合此疾病急性發病的檢驗結果？","options":["(A) 代謝性酸血症（metabolic acidosis）","(B) 低血鈉（hyponatremia）","(C) 低血鉀（hypokalemia）","(D) 低血糖（hypoglycemia）"],"answer":2,"image":""},{"id":"md4-113-1-25","subject":"md4","topic":"兒科-內分泌遺傳","meta":"113年第1次第25題","year":113,"session":1,"number":25,"question":"12歲女孩，發現甲狀腺腫大，甲狀腺及後眼眶組織切片顯示為淋巴球及漿細胞浸潤（infiltration of the thyroid gland and retroorbital tissues with lymphocytes and plasma cells），家族中有人罹患自體免疫甲狀腺疾病，下列何者為最有可能之診斷？","options":["(A) chronic lymphocytic thyroiditis","(B) Graves disease","(C) toxic multinodular goiter","(D) acute（infectious）thyroiditis"],"answer":1,"image":""},{"id":"md4-113-1-26","subject":"md4","topic":"兒科-感染神經","meta":"113年第1次第26題","year":113,"session":1,"number":26,"question":"3個月大的男嬰高燒6天，無新冠病毒感染病史。軀幹及四肢可見皮膚紅疹且四肢腫脹，結膜充血發紅，同時有草莓舌及嘴唇乾裂，在頸部可摸到淋巴結腫大，經臨床醫師評估後接受每公斤2 gm的免疫球蛋白治療。下列敘述何者最不適當？","options":["(A) 最可能的診斷為mucocutaneous lymph node syndrome","(B) 退燒後可使用口服低劑量aspirin繼續治療","(C) 因此病人治療有使用免疫球蛋白治療，在12個月大時的水痘疫苗及15個月大的日本腦炎疫苗皆需要延後施打","(D) 需安排心臟超音波檢查是否有冠狀動脈擴張"],"answer":2,"image":""},{"id":"md4-113-1-27","subject":"md4","topic":"兒科-感染神經","meta":"113年第1次第27題","year":113,"session":1,"number":27,"question":"下列何種疫苗適合於10個月大的嬰兒接種？","options":["(A) 4價去活化流感疫苗","(B) 23價多醣體肺炎鏈球菌疫苗","(C) 日本腦炎活性減毒疫苗","(D) 9價人類乳突病毒疫苗"],"answer":0,"image":""},{"id":"md4-113-1-28","subject":"md4","topic":"兒科-感染神經","meta":"113年第1次第28題","year":113,"session":1,"number":28,"question":"13個月大的男童發燒、咳嗽、流鼻水、眼睛結膜充血3天。入院2天後持續發燒，身上出現紅疹。實驗室檢驗WBC 5,600/μL，血清C-reactive protein 12 mg/L（正常值為＜5 mg/L）、AST 30 U/L、ALT 35 U/L。下列何種處置對臨床診斷最沒有幫助？","options":["(A) 抽血檢測過敏指數（IgE）","(B) 詳細查詢疫苗接種史、接觸史及旅遊史","(C) 安排心臟超音波檢查，尤其注意冠狀動脈是否異常","(D) 抽血送細菌培養"],"answer":0,"image":""},{"id":"md4-113-1-29","subject":"md4","topic":"兒科-內分泌遺傳","meta":"113年第1次第29題","year":113,"session":1,"number":29,"question":"8個月大的男嬰，仍不會翻身，而出生後一直有餵食困難的情況。身體診察發現四肢張力低下，且與人眼神接觸少，互動不佳。家族史呈現男嬰的舅舅、阿姨早夭，而舅公、外婆都有智能不足的情況，下列何者是該男嬰最有可能的診斷？","options":["(A) Prader-Willi syndrome（PWS）","(B) Duchenne muscular dystrophy","(C) congenital myasthenic syndromes","(D) Leigh syndrome"],"answer":3,"image":""},{"id":"md4-113-1-30","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"113年第1次第30題","year":113,"session":1,"number":30,"question":"2歲男童到醫院做健康檢查，下列發展項目中那一項屬於發展遲緩警訊？","options":["(A) 不會單腳站","(B) 不會騎三輪車","(C) 不會畫圓形","(D) 不會揮手再見"],"answer":3,"image":""},{"id":"md4-113-1-31","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"113年第1次第31題","year":113,"session":1,"number":31,"question":"3歲小男童，粗動作發展正常、已會跑步，但尚不會主動用口語表達，且有眼神迴避的現象，每天喜歡持續性玩小車車和看旋轉的東西，最可能是下列何種診斷？","options":["(A) 雷特氏症候群（Rett syndrome）","(B) 注意力不足／過動症（attention-deficit/hyperactivity disorder）","(C) 學習障礙（learning disability）","(D) 自閉症類群障礙症（autism spectrum disorder）"],"answer":3,"image":""},{"id":"md4-113-1-32","subject":"md4","topic":"兒科-感染神經","meta":"113年第1次第32題","year":113,"session":1,"number":32,"question":"12歲男童因發燒全身紅疹到急診室，看診醫師沒有得過水痘也沒有接種過水痘疫苗，診察時也沒有穿戴適合的個人防護裝備。3天後病童確診水痘感染。此醫師應接受下列何種處置最為適當？","options":["(A) 有水痘症狀再服用抗病毒藥物","(B) 立即預防性服用抗病毒藥物","(C) 馬上到門診接種水痘疫苗","(D) 即刻開始在家隔離一週觀察症狀"],"answer":2,"image":""},{"id":"md4-113-1-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"113年第1次第33題","year":113,"session":1,"number":33,"question":"下列何者不是愛德華氏症（Edwards syndrome, Trisomy 18）常見之臨床表徵？","options":["(A) 小頭（microcephaly）","(B) 小下巴（micorgnathia）","(C) 扁平枕骨（flat occiput）","(D) 搖椅腳（rocker-bottom feet）"],"answer":2,"image":""},{"id":"md4-113-1-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"113年第1次第34題","year":113,"session":1,"number":34,"question":"關於異位性皮膚炎（atopic dermatitis）的敘述，下列何者錯誤？","options":["(A) 第二型輔助T細胞（T helper 2 cells, Th2 cells）在致病機轉上扮演重要角色","(B) 病灶可能合併有金黃色葡萄球菌（Staphylococcus aureus）或單純性疱疹病毒（Herpes simplex virus）感染","(C) 絕大多數患者有絲聚蛋白（filaggrin）基因突變","(D) 若患者有濕疹樣病灶合併血小板低下及免疫功能異常，則需考慮Wiskott-Aldrich syndrome之可能"],"answer":2,"image":""},{"id":"md4-113-1-35","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"113年第1次第35題","year":113,"session":1,"number":35,"question":"關於藥物所引起的皮膚反應，下列敘述何者正確？","options":["(A) acute generalized exanthematous pustulosis的發生，常和macrolide及quinolone等抗生素有相關，會在軀幹及對磨部位（intertriginous region）出現膿疱，也會引發關節炎","(B) tetracycline主要是引起黏膜的色素沉著，不會發生在sun-exposed areas","(C) 藥物所引起的subacute cutaneous lupus erythematosus，通常在用藥後平均一週內，就會引發此皮膚症狀","(D) sorafenib（signal transduction inhibitors）會引發手足皮膚反應（hand-foot skin reaction）及落髮（alopecia）"],"answer":3,"image":""},{"id":"md4-113-1-36","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"113年第1次第36題","year":113,"session":1,"number":36,"question":"下列那些特徵與臨床表現，對於乾癬性關節炎的診斷較無幫助？","options":["(A) 手指呈現香腸指樣的腫脹表現","(B) 頭皮有嚴重皮膚乾癬病灶","(C) 類風濕因子呈現陽性","(D) 手指甲呈現指甲增厚與表面有點狀凹陷"],"answer":2,"image":""},{"id":"md4-113-1-37","subject":"md4","topic":"皮膚-感染","meta":"113年第1次第37題","year":113,"session":1,"number":37,"question":"有關甲癬（onychomycosis）的敘述，下列何者錯誤？","options":["(A) 非皮癬菌（nondermatophytes）也可能導致甲癬的發生","(B) 甲癬患者常同時罹患足癬","(C) griseofulvin是口服抗黴菌治療甲癬最佳的選擇，因為治療效果最好","(D) 糖尿病及愛滋病是罹患甲癬的危險因子"],"answer":2,"image":""},{"id":"md4-113-1-38","subject":"md4","topic":"皮膚-感染","meta":"113年第1次第38題","year":113,"session":1,"number":38,"question":"關於疥瘡（scabies）的治療藥物，下列何者正確？","options":["(A) 老人及小孩，建議使用lindane做為第一線外用藥物","(B) 孕婦可以安全使用口服ivermectin","(C) crotamiton 10% cream目前被認為是最有效的外用藥物","(D) permethrin藥膏可與口服ivermectin一起用於挪威型疥瘡（Norwegian scabies）之治療"],"answer":3,"image":""},{"id":"md4-113-1-39","subject":"md4","topic":"皮膚-腫瘤","meta":"113年第1次第39題","year":113,"session":1,"number":39,"question":"91歲男性，到院求診時發現其指甲的黑色素區塊一直延伸到甲緣近心端的皮膚（箭頭指示處），後來病理切片證實是肢端惡性黑色素瘤。箭頭所指為下列何者？","options":["(A) Darier sign","(B) Hutchinson sign","(C) Auspitz sign","(D) Nikolsky sign"],"answer":1,"image":"md4-113-1-39.jpeg"},{"id":"md4-113-1-40","subject":"md4","topic":"皮膚-腫瘤","meta":"113年第1次第40題","year":113,"session":1,"number":40,"question":"46歲男性，左腳出現紫色斑塊與丘疹約半年，皮膚切片檢查顯示真皮層紡錘狀細胞浸潤（spindle cell infiltration），以及裂隙狀血管腔（slit-like vascular spaces）。病人於五年前接受腎臟移植，其皮膚病灶之最可能診斷是：","options":["(A) 血管肉瘤（angiosarcoma）","(B) 隆凸性皮膚纖維肉瘤（dermatofibrosarcoma protuberans）","(C) 卡波西氏肉瘤（Kaposi sarcoma）","(D) 鬱血性皮膚炎（stasis dermatitis）"],"answer":2,"image":""},{"id":"md4-113-1-41","subject":"md4","topic":"皮膚-感染","meta":"113年第1次第41題","year":113,"session":1,"number":41,"question":"35歲男性病患，3天前於四肢及手掌出現靶心樣紅疹，手掌病灶如附圖。初期發作時伴有發燒38度。患者過去也曾反覆發生類似的情況。下列何種病原被認為與此疾病有較高的相關？","options":["(A) Treponema pallidum","(B) Herpes simplex virus","(C) Enterovirus 71","(D) Epstein-Barr virus"],"answer":1,"image":"md4-113-1-41.jpeg"},{"id":"md4-113-1-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"113年第1次第42題","year":113,"session":1,"number":42,"question":"48歲婦人使用口服荷爾蒙治療停經症候群半年後，在臉部出現如圖所示之皮膚色素沉著，下列敘述何者正確？","options":["(A) 白人比黃種人較易發生此病","(B) 通常伴有肝功能異常","(C) 二氧化碳（CO2）雷射治療是最佳處置","(D) 外用含有氫醌（hydroquinone）的藥膏可以改善"],"answer":3,"image":"md4-113-1-42.jpeg"},{"id":"md4-113-1-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"113年第1次第43題","year":113,"session":1,"number":43,"question":"下列有關水疱性表皮鬆解症（epidermolysis bullosa）之敘述，何者錯誤？","options":["(A) 皮膚裂解的位置由淺層至深層排序為epidermolysis bullosa simplex、junctional epidermolysis bullosa、dystrophic epidermolysis bullosa","(B) localized epidermolysis bullosa simplex是最常見的subtype","(C) 可能會伴隨指甲、牙齒、眼睛、頭髮之異常","(D) 為自體免疫水疱疾病之一，治療以免疫抑制劑為主"],"answer":3,"image":""},{"id":"md4-113-1-44","subject":"md4","topic":"神經-中風","meta":"113年第1次第44題","year":113,"session":1,"number":44,"question":"下列何者最不會是造成大腦靜脈竇栓塞（cerebral venous sinus thrombosis）的原因？","options":["(A) 使用避孕藥","(B) 抗磷脂質症候群（antiphospholipid syndrome）","(C) 腦膜炎","(D) 同半胱胺酸缺乏（homocysteine deficiency）"],"answer":3,"image":""},{"id":"md4-113-1-45","subject":"md4","topic":"神經-中風","meta":"113年第1次第45題","year":113,"session":1,"number":45,"question":"使用第十因子抑制劑（factor Xa inhibitor）的病人若發生腦出血，下列何種藥物或治療對此病人最恰當？","options":["(A) 新鮮冷凍血漿（fresh frozen plasma）","(B) 單株抗體反轉劑（idarucizumab）","(C) 凝血酶複合濃縮物（prothrombin complex concentrate）","(D) 血小板輸注（platelet transfusion）"],"answer":2,"image":""},{"id":"md4-113-1-46","subject":"md4","topic":"神經-中風","meta":"113年第1次第46題","year":113,"session":1,"number":46,"question":"於急性缺血性腦中風，神經細胞在缺氧及缺少葡萄糖（glucose）時會產生一連串反應導致腦細胞死亡，下列何者最不可能會發生？","options":["(A) 粒線體（mitochondria）難以合成三磷酸腺苷（ATP）","(B) 細胞內鈣離子濃度降低","(C) 產生麩胺酸（glutamate）神經毒性和自由基（free radical）","(D) 產生發炎反應"],"answer":1,"image":""},{"id":"md4-113-1-47","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"113年第1次第47題","year":113,"session":1,"number":47,"question":"13歲女學生半年來經常熬夜讀書，早上起床常有短暫性全身抽動（myoclonus），上肢特別明顯，意識清楚。這次被父母送來急診主要是因為全身痙攣（convulsion）。病人智力正常，腦部斷層和磁振造影無異常發現，腦波出現不規律之全面性4-6Hz棘慢波複合波，病人過去曾經有肝炎病史。下列何種抗癲癇藥物最適合使用？","options":["(A) valproate","(B) levetiracetam","(C) phenytoin","(D) carbamazepine"],"answer":[0,1],"image":"","answer_note":"更正:第47題答Ａ或Ｂ或AB者均給分"},{"id":"md4-113-1-48","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"113年第1次第48題","year":113,"session":1,"number":48,"question":"下列何種治療對延遲型睡眠週期症候群（delayed sleep phase syndrome）最不合適？","options":["(A) 晚上照光治療","(B) 褪黑激素（melatonin）每晚0.2～0.5mg","(C) 每天延後睡覺2～3個小時，連續幾天，以重置生物鐘","(D) 晚間給與褪黑激素促效劑（melatonin agonist）"],"answer":0,"image":""},{"id":"md4-113-1-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"113年第1次第49題","year":113,"session":1,"number":49,"question":"下列有關癲癇（epilepsy）及癲癇發作（seizure）之敘述，何者正確？","options":["(A) 90%的腦傷病人在一年內會發生創傷後癲癇","(B) 在所有年齡層，頭部外傷都是最常見的癲癇病因","(C) 小於15歲病人其癲癇發病的最常見病因為腦血管病變","(D) 癲癇病人接受抗癲癇藥物治療，約6～7成可達到癲癇發作緩解（remission）"],"answer":3,"image":""},{"id":"md4-113-1-50","subject":"md4","topic":"神經-失智退化運動障礙","meta":"113年第1次第50題","year":113,"session":1,"number":50,"question":"66歲女性最近一個多月來出現記憶力減退、視幻覺、走路不穩，突然聽見鞭炮聲會身體顫抖。她的腦部磁振造影擴散加權成像（diffusion-weighted imaging）結果如下圖。她最可能的診斷是：","options":["(A) 邊緣性腦炎（limbic encephalitis）","(B) 庫賈氏症（Creutzfeldt-Jakob disease）","(C) 血管性失智症（vascular dementia）","(D) 多發性硬化症（multiple sclerosis）"],"answer":1,"image":"md4-113-1-50.jpeg"},{"id":"md4-113-1-51","subject":"md4","topic":"神經-失智退化運動障礙","meta":"113年第1次第51題","year":113,"session":1,"number":51,"question":"用來治療阿茲海默氏病（Alzheimer disease）的藥物memantine，它最主要的機轉是：","options":["(A) 乙醯膽鹼酯酶（cholinesterase）抑制劑","(B) 阻斷N-methyl-D-aspartate（NMDA）glutamate受體","(C) 抑制γ secretase","(D) 抑制β secretase"],"answer":1,"image":""},{"id":"md4-113-1-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"113年第1次第52題","year":113,"session":1,"number":52,"question":"關於肌萎縮性側索硬化（amyotrophic lateral sclerosis, ALS），下列敘述何者錯誤？","options":["(A) ALS是最常見的運動神經元疾病（motor neuron disease），會造成上及下運動神經元漸進性的退化。大部分是散發的（sporadic），少數是家族遺傳性的（familial），無法從臨床表現上去區分這兩種的ALS","(B) ALS臨床變異性很高，病人可以有不同的發病部位、惡化順序及上下運動神經元受影響的比例。因與額顳葉失智症（frontotemporal dementia, FTD）常有共同的遺傳基因，可視為與FTD為同一個疾病群（disease spectrum）","(C) ALS第一個被發現的基因是superoxide dismutase 1（SOD1）gene，也是目前歐洲最常見造成familial ALS的原因","(D) 臨床上若病人有無痛性漸進性的肌肉無力萎縮，甚至肌束跳動（fasciculation），且沒有明顯的感覺功能障礙、複視、眼皮下垂、膀胱功能障礙時，要考慮可能是ALS"],"answer":2,"image":""},{"id":"md4-113-1-53","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"113年第1次第53題","year":113,"session":1,"number":53,"question":"下列關於肌無力症候群（myasthenic syndrome or Lambert-Eaton syndrome）的敘述，何者錯誤？","options":["(A) 體內有免疫抗體攻擊突觸前神經終端（presynaptic nerve terminals）的鉀離子通道","(B) 通常於成年人發病","(C) 約有一半的病人可以合併體內惡性腫瘤","(D) 口乾是一個常見的自律神經失調症狀"],"answer":0,"image":""},{"id":"md4-113-1-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"113年第1次第54題","year":113,"session":1,"number":54,"question":"下列有關三叉神經痛的敘述，何者錯誤？","options":["(A) 疼痛侷限於三叉神經單條或多條分支範圍的劇烈疼痛","(B) 常發生於中老年人","(C) 成因可能與三叉神經在腦幹附近的動／靜脈血管壓迫或拉扯有關，尤其是下小腦動脈（inferior cerebellar artery）","(D) carbamazepine是治療的選項之一"],"answer":2,"image":""},{"id":"md4-113-1-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"113年第1次第55題","year":113,"session":1,"number":55,"question":"格林–巴利症候群（Guillain-Barré syndrome）合併呼吸肌無力時，首選治療為何？","options":["(A) 類固醇（corticosteroid）脈衝療法","(B) cyclophosphamide靜脈輸注","(C) 支持性內科療法即可，不至有生命危險","(D) 血漿交換或血漿分離術（plasma exchange / plasmapheresis）"],"answer":3,"image":""},{"id":"md4-113-1-56","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"113年第1次第56題","year":113,"session":1,"number":56,"question":"關於多發性硬化症（multiple sclerosis, MS）及視神經脊髓炎（neuromyelitis optica spectrum disorder, NMOSD）之比較，下列何者錯誤？","options":["(A) MS病人女比男多，而NMOSD病人男比女多","(B) 臨床症狀及預後，通常NMOSD病人比MS病人嚴重","(C) 寡株帶（oligoclonal band）常見於MS病人的腦脊髓液中，而水離子通道蛋白抗體（aquaporin- 4 antibody）常見於NMOSD病人","(D) MS病人脊髓發炎長度大都小於三節；而NMOSD病人其脊髓發炎長度等於三節或多於三節以上"],"answer":0,"image":""},{"id":"md4-113-1-57","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"113年第1次第57題","year":113,"session":1,"number":57,"question":"關於腦下垂體腫瘤，下列敘述何者最不恰當？","options":["(A) 雙顳側偏盲（bitemporal hemianopia）可能是症狀之一","(B) 可能會因為壓迫視交叉（optic chiasm）或直接侵犯視神經造成病人視力喪失","(C) 常合併血中泌乳激素低下（hypoprolactinemia）","(D) 頭痛是常見的臨床表現"],"answer":2,"image":""},{"id":"md4-113-1-58","subject":"md4","topic":"神經-失智退化運動障礙","meta":"113年第1次第58題","year":113,"session":1,"number":58,"question":"下列何種遺傳疾病的致病突變不是三核苷酸重複序列擴增（trinucleotide repeat expansion）？","options":["(A) 亨丁頓氏病（Huntington disease）","(B) 第二型小腦脊髓共濟失調症（spinocerebellar ataxia type 2）","(C) 威爾森氏病（Wilson disease）","(D) 第三型小腦脊髓共濟失調症（spinocerebellar ataxia type 3）"],"answer":2,"image":""},{"id":"md4-113-1-59","subject":"md4","topic":"精神-精神病","meta":"113年第1次第59題","year":113,"session":1,"number":59,"question":"有關僵直狀態（catatonia）的敘述，下列何者最不適當？","options":["(A) 患者會出現運動性活動減少或增加情形，這兩種極端的運動性障礙可以交替出現","(B) 以僵直狀態表現的主要精神疾病，以在住院病人中思覺失調症最多，情感疾患次之","(C) 抗精神病劑也可能會導致僵直狀態","(D) 患者可能會出現模仿言語（echolalia）及模仿動作（echopraxia）"],"answer":1,"image":""},{"id":"md4-113-1-60","subject":"md4","topic":"精神-精神病","meta":"113年第1次第60題","year":113,"session":1,"number":60,"question":"有關雙相情緒障礙症（bipolar disorder），下列敘述何者最不適當？","options":["(A) 家族中有罹患雙相情緒障礙症者，罹患憂鬱症的機率可能較一般人高","(B) 同卵雙胞胎其中一位罹患雙相情緒障礙症，另一位罹患雙相情緒障礙症的機率約25%","(C) 雙相情緒障礙症多有躁期及鬱期，鬱期出現的頻率通常比躁期多，大約只有10%～20%的患者只出現躁期，沒有經歷過鬱期","(D) 年輕人急性期的鋰鹽治療濃度宜介於0.6～1.2 mEq/L"],"answer":1,"image":""},{"id":"md4-113-1-61","subject":"md4","topic":"精神-器質性與物質使用","meta":"113年第1次第61題","year":113,"session":1,"number":61,"question":"有關鋰鹽（lithium）在治療病人時的敘述，下列何者最不適當？","options":["(A) 可能出現噁心、嘔吐、腹瀉、視力模糊等副作用","(B) 嚴重中毒時有可能出現痙攣、心律不整或昏迷等症狀","(C) 血液透析是解救嚴重中毒的方法","(D) 目前臨床上最有效監測鋰鹽中毒的方法為臨床觀察"],"answer":3,"image":""},{"id":"md4-113-1-62","subject":"md4","topic":"精神-精神病","meta":"113年第1次第62題","year":113,"session":1,"number":62,"question":"一位中年女性病人，深信鄰居偷走她的珠寶，處處刁難她。此外，眼前的丈夫只剩下外表，整個人的內在都被鄰居所取代，且電視都在報導女病人的事情，以致女病人攻擊其丈夫。下列敘述何者最適當？","options":["(A) 若須強制住院，須先徵得其丈夫同意","(B) 被偷妄想（delusions of being stolen）只出現於患思覺失調症（schizophrenia）的病人","(C) 如要診斷思覺失調症（schizophrenia），須排除安非他命（amphetamine）或其他物質的影響","(D) 為了治療該病人，首選用藥是苯二氮平（benzodiazepine）"],"answer":2,"image":""},{"id":"md4-113-1-63","subject":"md4","topic":"醫學倫理與法規","meta":"113年第1次第63題","year":113,"session":1,"number":63,"question":"有關安樂死（euthanasia）的敘述，下列何者最不適當？","options":["(A) 撤除病人維生系統是被動式安樂死之一","(B) 在病人要求下，以解除痛苦措施協助病人安樂死，屬被動式方法之一","(C) 主動式安樂死爭議仍多","(D) 憂鬱症是評估安樂死問題的重要項目"],"answer":1,"image":""},{"id":"md4-113-1-64","subject":"md4","topic":"精神-精神官能症","meta":"113年第1次第64題","year":113,"session":1,"number":64,"question":"有關失眠患者的臨床表現和治療，下列敘述何者最不適當？","options":["(A) 白天常打瞌睡的人須評估是否有阻塞性呼吸障礙","(B) 睡眠困難的頻率，為每週3次以上且達3個月者，符合失眠症（insomnia disorder）之診斷標準","(C) 失眠皆因其他疾病所導致的症狀，一定能查出潛在疾病","(D) 使用鎮定安眠類藥物處方，一般建議以不超過兩週為原則"],"answer":2,"image":""},{"id":"md4-113-1-65","subject":"md4","topic":"精神-精神官能症","meta":"113年第1次第65題","year":113,"session":1,"number":65,"question":"關於飲食疾患中的嗜食症（binge eating disorder）與暴食症（bulimia nervosa）的敘述，下列何者最不適當？","options":["(A) 臨床證據顯示，抗憂鬱劑（如fluoxetine）可用於治療暴食症","(B) 嗜食症患者不會有反覆代償性減重行為（如催吐、使用瀉劑等）","(C) 嗜食症患者不會有使體態纖瘦的強烈渴望","(D) 暴食症患者之自我評價不因對身材或體重的看法而有不當影響"],"answer":3,"image":""},{"id":"md4-113-1-66","subject":"md4","topic":"醫學倫理與法規","meta":"113年第1次第66題","year":113,"session":1,"number":66,"question":"根據美國食品藥物管理局（FDA）在孤兒藥法（Orphan Drug Act）中定義的醫療食品（medical food），是指「食品製劑在醫生的監督下食用，用於疾病或病症的治療，並基於公認的科學原理，通過醫學評估所建立特定的營養療法」。在臨床應用方面，下列敘述何者最不適當？","options":["(A) 醫學藥物研發投入資源，收集豐富的臨床試驗資料，政府對藥物上市的規範嚴謹，首重實證（隨機分配有安慰劑做為控制組的臨床試驗）","(B) 憂鬱症病因複雜，如果只偏重藥物單一療法，易造成整體療效不足","(C) S-adenosyl-L-methionine（SAMe）的作用機轉，主要是促進serotonin和norepinephrine的合成","(D) Omega-3的作用機轉，主要是血清素回收抑制作用"],"answer":3,"image":""},{"id":"md4-113-1-67","subject":"md4","topic":"精神-器質性與物質使用","meta":"113年第1次第67題","year":113,"session":1,"number":67,"question":"有關老年人相關精神問題及疾病之敘述，下列何者最不適當？","options":["(A) 老年人自殺危險性比其他年齡族群高，且約有1/3的自殺原因是孤單（loneliness）","(B) 慮病症（hypochondriasis）發生高峰年齡層主要在60歲以上的老年人口族群","(C) 焦慮症（anxiety disorder）通常開始於成年早期或中年期，但仍有些第一次焦慮症發生於60歲以上老年人","(D) 一般臨床而言，老年人發生與呼吸相關的睡眠障礙症（breathing-related sleep disorders）之經驗比年輕成年人高"],"answer":1,"image":""},{"id":"md4-113-1-68","subject":"md4","topic":"精神-器質性與物質使用","meta":"113年第1次第68題","year":113,"session":1,"number":68,"question":"有關譫妄症患者的治療方式，下列何者最不適當？","options":["(A) 可使用抗精神藥物來治療其行為紊亂和激躁","(B) 若有失眠最好用短、中效半衰期benzodiazepines來幫助其睡眠","(C) 在病人身邊擺放家人照片和時鐘，幫助建立定向感","(D) 可長時間約束，以避免病人暴力和預防跌倒"],"answer":3,"image":""},{"id":"md4-113-1-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"113年第1次第69題","year":113,"session":1,"number":69,"question":"有關臺灣採用美沙冬（methadone）替代療法治療海洛因（heroin）成癮，下列敘述何者最適當？","options":["(A) 長期使用多數患者會導致憂鬱或嗜睡（drowsiness）","(B) 主要使用途徑為靜脈注射","(C) 不會導致依賴（dependence）","(D) 長期使用美沙冬後，藥效持續24小時以上，每天給與一次治療即可"],"answer":3,"image":""},{"id":"md4-113-1-70","subject":"md4","topic":"精神-器質性與物質使用","meta":"113年第1次第70題","year":113,"session":1,"number":70,"question":"苯二氮平類（benzodiazepines, BZDs）在臨床上廣泛被使用，下列敘述何者最適當？","options":["(A) BZDs戒斷症狀和酒精很相似，都有焦慮、不悅、失眠，甚至抽搐的可能性","(B) BZDs戒斷誘發的抽搐多半在停用後的10天左右最易發生","(C) 半衰期較長之BZDs，成癮性較高","(D) 男性濫用者較女性多"],"answer":0,"image":""},{"id":"md4-113-1-71","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"113年第1次第71題","year":113,"session":1,"number":71,"question":"有關自閉症類群障礙症（autism spectrum disorder）的症狀，下列敘述何者最適當？","options":["(A) 患者社交發展的主要特徵是完全缺乏依附行為（absent attachment behavior）","(B) 與同年齡孩童相比，患者面對陌生人時的反應會更為顯著不安","(C) 認知功能上，患者的視覺空間（visual-spatial）能力會優於口語理解（verbal reasoning）能力","(D) 患者雖然有社交功能障礙，但與同年齡孩童相比，其心智理論（theory of mind）功能並無缺損"],"answer":2,"image":""},{"id":"md4-113-1-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"113年第1次第72題","year":113,"session":1,"number":72,"question":"有關中樞神經刺激劑（CNS stimulant）用來治療注意力不足／過動症，下列何者最不適當？","options":["(A) 常用的中樞神經刺激劑為methylphenidate，其作用機轉為血清素回收抑制劑（serotonin reuptake inhibitor）","(B) 可提升社交互動和衝動控制","(C) 對於大多數的注意力不足／過動症三大核心症狀有效","(D) 副作用主要是食慾降低或影響睡眠"],"answer":0,"image":""},{"id":"md4-113-1-73","subject":"md4","topic":"精神-精神官能症","meta":"113年第1次第73題","year":113,"session":1,"number":73,"question":"詐病（malingering）與佯病（factitious disorder）之最大區別為何？","options":["(A) 佯病為個案有意圖的（intentionally）裝病","(B) 佯病找不到真正的身體疾病或其他精神疾病","(C) 詐病為個案主要的意圖在維持病人的角色（sick role）","(D) 詐病有明確的外在的因素。如避免法律事件、逃避兵役等"],"answer":3,"image":""},{"id":"md4-113-1-74","subject":"md4","topic":"神經-中風","meta":"113年第1次第74題","year":113,"session":1,"number":74,"question":"84歲女性，有高血壓病史，突然頭痛噁心而至急診求診。頭部電腦斷層檢查發現有廣泛蜘蛛網膜下腔出血（subarachnoid hemorrhage, SAH）併腦室內出血；進一步做頭部血管攝影檢查，影像如附圖（右側及左側頸動脈造影），造成她SAH的原因最可能為下列何者？","options":["(A) 右側內頸動脈（ICA）和後交通動脈（PCommA）交界腦動脈瘤","(B) 左側內頸動脈（ICA）和後交通動脈（PCommA）交界腦動脈瘤","(C) 右側前大腦動脈瘤","(D) 左側前大腦動脈瘤"],"answer":0,"image":"md4-113-1-74.jpeg"},{"id":"md4-113-1-75","subject":"md4","topic":"神經-中風","meta":"113年第1次第75題","year":113,"session":1,"number":75,"question":"關於腦梗塞（cerebral infarction）的影像，下列敘述何者錯誤？","options":["(A) 通常12小時之內的頭部電腦斷層（CT）掃描看不到明顯變化","(B) 兩週左右的頭部電腦斷層（CT）或磁振造影（MRI）靜脈注射顯影劑後，可能會有顯影加強現象","(C) 頭部電腦斷層（CT）比磁振造影（MRI）更容易偵測腦梗塞之後的出血性轉化（hemorrhagic transformation）","(D) 擴散加權影像（diffusion-weighted-imaging）上偵測到的異常可以持續兩週左右"],"answer":2,"image":""},{"id":"md4-113-1-76","subject":"md4","topic":"兒科-感染神經","meta":"113年第1次第76題","year":113,"session":1,"number":76,"question":"關於受虐性腦傷（abusive head trauma, AHT）的敘述，下列何者錯誤？","options":["(A) 以前叫做嬰兒搖晃症候群（shaken baby syndrome），亦屬兒童虐待（child abuse）","(B) retinal hemorrhages是AHT重要的診斷依據","(C) 常發生於未滿三歲嬰幼兒","(D) 幼兒在大人膝蓋上晃動或拋起等動作具有危險性，也會造成嬰兒搖晃症候群的腦傷"],"answer":3,"image":""},{"id":"md4-113-1-77","subject":"md4","topic":"精神-器質性與物質使用","meta":"113年第1次第77題","year":113,"session":1,"number":77,"question":"23歲男性經常使用某種物質，病人因全身無力、情緒低落到急診，體溫37℃，血壓120/76 mmHg，心跳80/min，呼吸10/min。下列何種物質最有可能是病人長期濫用而致有此戒斷症狀？","options":["(A) amphetamine","(B) Heroin","(C) alcohol","(D) benzodiazepine"],"answer":0,"image":""},{"id":"md4-113-1-78","subject":"md4","topic":"皮膚-感染","meta":"113年第1次第78題","year":113,"session":1,"number":78,"question":"下列有關軟組織感染的敘述，何者錯誤？","options":["(A) 丹毒（erysipelas）最常見以group A Streptococcus的感染為主","(B) 健康的成年人，下肢出現局部蜂窩性組織炎，但沒有併發菌血症，可考慮門診使用口服抗生素的處理方式","(C) 高壓氧（hyperbaric oxygen）使用於厭氧菌所引起的壞死性筋膜炎（necrotizing fasciitis）具有極佳的治療效果","(D) 疼痛異常的情形與臨床的皮膚病灶表徵不符，需將壞死性筋膜炎（necrotizing fasciitis）列入鑑別診斷"],"answer":2,"image":""},{"id":"md4-113-1-79","subject":"md4","topic":"醫學倫理與法規","meta":"113年第1次第79題","year":113,"session":1,"number":79,"question":"夫妻雙方皆為某種體染色體隱性遺傳疾病的帶因者，因此為胎兒進行產前遺傳檢測，結果顯示胎兒有異常。下列後續處置何者最不適當？","options":["(A) 只要胎兒確定罹患此遺傳疾病，應積極勸其中止懷孕","(B) 因為檢測可能不準確，應以其他檢驗方式進行確認後，才決定後續處置","(C) 若該疾病對生活影響不大，可以考慮繼續懷孕","(D) 若為重大遺傳疾病，諮詢內容應包含該疾病的治療及相關社會福利資源"],"answer":0,"image":""},{"id":"md4-113-1-80","subject":"md4","topic":"醫學倫理與法規","meta":"113年第1次第80題","year":113,"session":1,"number":80,"question":"25歲男子經過幾週的乾咳、發燒、盜汗，抽血檢測確認人類免疫缺乏病毒抗體陽性。他有一位固定的女性性伴侶，剛懷孕3個月，但男子遲遲不肯將病情告知其性伴侶，下列敘述何者最不適當？","options":["(A) 在特定且有限的情況下，醫師揭露病人隱私並不違反醫學倫理","(B) 基於醫師的保密義務，只能提醒患者通知其性伴侶","(C) 如果保密可能造成第三方的嚴重傷害，醫師應該要揭露","(D) 衛生主管機關可介入，直接或匿名通知他的性伴侶"],"answer":1,"image":""},{"id":"md4-113-2-1","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"113年第2次第1題","year":113,"session":2,"number":1,"question":"一歲半的孩子，下列何項描述最可能代表有發展遲緩，需要進一步轉介？","options":["(A) 僅能說出身體4個部位","(B) 僅能說2個有意義的單字","(C) 僅能說1種顏色","(D) 僅能指認3種動物"],"answer":1,"image":""},{"id":"md4-113-2-2","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"113年第2次第2題","year":113,"session":2,"number":2,"question":"依照我國兒童健康手冊規定，嬰幼兒輸注血液製劑後，需與活性減毒疫苗接種有所間隔。下列關於間隔之建議，何者最不適當？","options":["(A) 注射呼吸道融合病毒（RSV）預防性單株抗體（palivizumab），應間隔3個月","(B) 接受高劑量（≧1g/kg）免疫球蛋白靜脈注射後，應間隔11個月","(C) 輸過血或接受靜脈血液製品者，應間隔6個月。但輸注的若為洗滌紅血球則無需間隔","(D) 一般肌肉注射免疫球蛋白或B型肝炎免疫球蛋白，應間隔3個月"],"answer":0,"image":""},{"id":"md4-113-2-3","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"113年第2次第3題","year":113,"session":2,"number":3,"question":"下列關於胎便吸入（meconium aspiration）之敘述，何者最為適當？","options":["(A) 羊水胎便染色（meconium-stained amniotic fluid）多發生於早產兒","(B) 有羊水胎便染色之新生兒，約有60%發生胎便吸入症候群（meconium aspiration syndrome）","(C) 胎便吸入症候群會增加新生兒持續性肺高壓症（persistent pulmonary hypertension of newborn）發生機會","(D) 有胎便吸入症候群之新生兒，表現以呼吸道阻塞為主，容易造成肺塌陷，不會增加氣胸機率"],"answer":2,"image":""},{"id":"md4-113-2-4","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"113年第2次第4題","year":113,"session":2,"number":4,"question":"下列關於新生兒常規照護（routine newborn care）及評估的敘述，何者最不適當？","options":["(A) 肌肉注射vitamin K1以預防新生兒出血性疾病","(B) 給與tetracycline眼藥膏以對抗gonococcal ophthalmia neonatorum","(C) 正常足月新生兒呼吸速率約為每分鐘30～60次","(D) Ortolani test是測試髖關節是否滑脫（unstable hip dislocating from the acetabulum）"],"answer":3,"image":""},{"id":"md4-113-2-5","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"113年第2次第5題","year":113,"session":2,"number":5,"question":"下列關於糖尿病母親所生嬰兒（infant of diabetic mothers）的敘述，何者最不適當？","options":["(A) 約36～45%為large for gestational age（LGA），若有LGA，則產傷（birth trauma）及生產窒息（birth asphyxia）風險較高","(B) 可能造成紅血球增多症（polycythemia），發生高膽紅素血症（hyperbilirubinemia）的機率也會上升","(C) 可能有心臟擴大（cardiomegaly）及心室中隔肥厚（interventricular septal hypertrophy）","(D) 出生後容易有低血糖（hypoglycemia）、高血鈣（hypercalcemia），並且經常表現出肌張力低下、昏睡、吸吮力差等症狀"],"answer":3,"image":""},{"id":"md4-113-2-6","subject":"md4","topic":"兒科-心血管呼吸","meta":"113年第2次第6題","year":113,"session":2,"number":6,"question":"3個月大的足月產男嬰，出生體重為3058公克，目前體重為4075公克，奶量為每四小時70 c.c.，身體診察有聽到心雜音。此病人最不可能的診斷為下列何項？","options":["(A) 第二型心房中隔缺損（atrial septal defect, ASD type 2），缺損為5 mm","(B) 第二型心室中隔缺損（ventricular septal defect, VSD type 2），缺損為6 mm","(C) 完全型心內膜墊缺損（complete endocardial cushion defect, ECD），缺損為6 mm","(D) 開放性動脈導管管狀型（tubular type patent ductus arteriosus, PDA），直徑為5 mm"],"answer":0,"image":""},{"id":"md4-113-2-7","subject":"md4","topic":"兒科-心血管呼吸","meta":"113年第2次第7題","year":113,"session":2,"number":7,"question":"關於開放性動脈導管（patent ductus arteriosus, PDA），下列敘述何者最不適當？","options":["(A) 常見於早產兒（prematurity）","(B) 身體診察常發現有較寬的脈搏壓（wide pulse pressure）","(C) 可以使用prostaglandin類藥物促使其閉合","(D) 可於左側近鎖骨部位聽到連續性心雜音（continuous murmur）或收縮性心雜音（systolic murmur）"],"answer":2,"image":""},{"id":"md4-113-2-8","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"113年第2次第8題","year":113,"session":2,"number":8,"question":"下列何項系統疾病為兒童次發性高血壓（secondary hypertension）最常見的原因？","options":["(A) 心血管系統（cardiovascular system）","(B) 腎臟系統（renal system）","(C) 內分泌系統（endocrine system）","(D) 中樞神經系統（central nervous system）"],"answer":1,"image":""},{"id":"md4-113-2-9","subject":"md4","topic":"兒科-消化系統疾病","meta":"113年第2次第9題","year":113,"session":2,"number":9,"question":"關於病毒性肝炎血清學檢查結果的判讀，下列何者最適當？","options":["(A) Anti-HAV IgM(+)表示A型肝炎病毒的急性感染","(B) Anti-HBsAg(+)，Anti-HBc IgG(+)是接種B型肝炎疫苗後的反應","(C) Anti-HCV(+)表示過去曾感染C型肝炎病毒，但已痊癒","(D) Anti-HBc IgM(+)，HBs Ag(+)，Anti-HBs(-)表示B型肝炎病毒的慢性感染"],"answer":0,"image":""},{"id":"md4-113-2-10","subject":"md4","topic":"兒科-消化系統疾病","meta":"113年第2次第10題","year":113,"session":2,"number":10,"question":"有關孩童食道異物的敘述，下列何者最不適當？","options":["(A) 吞入鈕扣型電池須等待禁食時間足夠後，才能取出","(B) 誤吞異物最常見的是硬幣","(C) 至少30%孩童食道異物完全沒有任何症狀","(D) 誤吞異物的檢查以胸頸、腹部X光為先"],"answer":0,"image":""},{"id":"md4-113-2-11","subject":"md4","topic":"兒科-消化系統疾病","meta":"113年第2次第11題","year":113,"session":2,"number":11,"question":"下列何者最不可能合併hydrops of the gallbladder？","options":["(A) 川崎氏症（Kawasaki disease）","(B) 鏈球菌咽炎（streptococcal pharyngitis）","(C) 肥胖（obesity）","(D) 全靜脈營養（total parenteral nutrition）"],"answer":[1,2,3],"image":"","answer_note":"更正:第11題答Ｂ或Ｃ或Ｄ或BC或BD或CD或BCD者均給分"},{"id":"md4-113-2-12","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"113年第2次第12題","year":113,"session":2,"number":12,"question":"下列有關兒童夜尿（nocturnal enuresis）的敘述，何者最不適當？","options":["(A) 男生的發生率高於女生","(B) 須排除其他造成夜尿的可能原因","(C) 診斷定義為4歲以上仍有夜間不自覺排尿","(D) 有家族或遺傳傾向"],"answer":2,"image":""},{"id":"md4-113-2-13","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"113年第2次第13題","year":113,"session":2,"number":13,"question":"關於兒童紫斑性腎炎（Henoch-Schönlein purpura nephritis），下列敘述何者最不適當？","options":["(A) 腎臟切片的適應症包括：每日尿中蛋白質流失大於1克、高血壓、腎功能惡化","(B) 約50%的兒童紫斑症會侵犯腎臟，其腎臟的病理變化幾乎與IgA腎病變相同，無法區分","(C) 出現紫斑的初期立即使用類固醇，可以預防日後腎炎的發生或減輕其嚴重度","(D) 大多數起始表現為血尿合併輕微蛋白尿或無蛋白尿，無需治療而自動痊癒"],"answer":2,"image":""},{"id":"md4-113-2-14","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"113年第2次第14題","year":113,"session":2,"number":14,"question":"10歲的男孩血尿兩年，家族史發現舅舅正接受洗腎治療，而且有雙側聽力障礙及圓錐形晶狀體（anterior lenticonus）。下列何者是最可能的診斷？","options":["(A) IgA nephropathy","(B) thin basement membrane disease","(C) Alport syndrome","(D) focal segmental glomerulosclerosis"],"answer":2,"image":""},{"id":"md4-113-2-15","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"113年第2次第15題","year":113,"session":2,"number":15,"question":"兒童異位性皮膚炎（atopic dermatitis）的皮膚症狀，最少出現下列何種表徵？","options":["(A) 搔癢（pruritus）","(B) 脫屑（scaling）","(C) 苔癬化（lichenification）","(D) 風疹塊（wheal）"],"answer":3,"image":""},{"id":"md4-113-2-16","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"113年第2次第16題","year":113,"session":2,"number":16,"question":"下列何種自體抗體（autoantibody）是紅斑性狼瘡（systemic lupus erythematosus, SLE）的特異性抗體，與疾病的活動性（activity）及是否併發腎絲球腎炎（lupus nephritis）最有相關？","options":["(A) anti-SSA及anti-SSB antibody","(B) anti-centromere antibody","(C) anti-dsDNA antibody","(D) anti-Smith antibody"],"answer":2,"image":""},{"id":"md4-113-2-17","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"113年第2次第17題","year":113,"session":2,"number":17,"question":"有關兒童特發性關節炎（juvenile idiopathic arthritis, JIA）的敘述，下列何者最不適當？","options":["(A) 發病於小於16歲的兒童","(B) 關節炎的症狀要持續6週以上","(C) 最常見的JIA類型是少關節炎型（oligoarthritis）","(D) 疾病開始的6週內少於或等於5個關節發炎，屬於少關節炎型（oligoarthritis）"],"answer":[2,3],"image":"","answer_note":"更正:第17題答Ｃ或Ｄ或CD者均給分"},{"id":"md4-113-2-18","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"113年第2次第18題","year":113,"session":2,"number":18,"question":"關於兒童骨腫瘤（bone tumor），下列敘述何者最不適當？","options":["(A) 骨肉瘤（osteosarcoma）好發於急速生長的青少年，罹病個案的身高一般屬同齡層中較高者","(B) 帶有RB1基因生殖細胞系突變（germline RB1 gene mutation）的孩子，罹患骨肉瘤的機率較同齡層高","(C) 10歲以下兒童的骨腫瘤，伊文氏肉瘤（Ewing sarcoma）的發生率較骨肉瘤高","(D) 長骨幹骺處（metaphyses of long bone）是伊文氏肉瘤（Ewing sarcoma）的好發位置"],"answer":[2,3],"image":"","answer_note":"更正:第18題答Ｃ或Ｄ或CD者均給分"},{"id":"md4-113-2-19","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"113年第2次第19題","year":113,"session":2,"number":19,"question":"關於兒童癌症與其常見臨床症狀的敘述，下列何者最不適當？","options":["(A) 白血病：臉色蒼白、身上多處瘀青或出血點、發燒等","(B) 神經母細胞瘤：肢體疼痛、貧血、浣熊眼等","(C) 視網膜母細胞瘤：白瞳、斜視、視力下降等","(D) 肝母細胞瘤：腹部腫塊、血尿、高血壓等"],"answer":3,"image":""},{"id":"md4-113-2-20","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"113年第2次第20題","year":113,"session":2,"number":20,"question":"關於兒童癌症診斷時的相對應檢查，下列何者最不適當？","options":["(A) 肝母細胞瘤：human chorionic gonadotropin（hCG）","(B) 生殖細胞瘤：α-Fetoprotein（AFP）","(C) 神經母細胞瘤：尿液vanillylmandelic acid（VMA）","(D) 急性淋巴性白血病：骨髓細胞遺傳學（染色體）檢查"],"answer":0,"image":""},{"id":"md4-113-2-21","subject":"md4","topic":"兒科-心血管呼吸","meta":"113年第2次第21題","year":113,"session":2,"number":21,"question":"2歲女童，發燒4天，精神活力差，血壓65/35 mmHg，心跳每分鐘165下。下列何者是其最不可能的臨床表現？","options":["(A) 膚色呈網狀紋路（mottling）","(B) 呼吸暫停（apnea）","(C) 腸道蠕動增快","(D) 尿量明顯減少"],"answer":2,"image":""},{"id":"md4-113-2-22","subject":"md4","topic":"兒科-心血管呼吸","meta":"113年第2次第22題","year":113,"session":2,"number":22,"question":"兒童呼吸窘迫進行呼吸治療的一般原則，下列敘述何者最適當？","options":["(A) 優先使用侵入性的正壓通氣模式","(B) 若置放氣管內管，優先選擇有氣囊的","(C) 兒童呼吸器通常不須使用氣流潮濕裝置","(D) 為配合呼吸器使用，皆須使用肌肉鬆弛劑"],"answer":1,"image":""},{"id":"md4-113-2-23","subject":"md4","topic":"兒科-心血管呼吸","meta":"113年第2次第23題","year":113,"session":2,"number":23,"question":"高中男生與同學打籃球劇烈碰撞之後產生氣胸，血氧飽和濃度88%。有關其臨床表現，下列何者最為適當？","options":["(A) 呼吸會呈現Cheyne-Stokes respiration","(B) 胸痛程度通常與肺部塌陷嚴重度成正比","(C) 可能有通氣與灌流差異現象（ventilation-perfusion mismatch）","(D) 在X光影像上，氣管顯影會偏移向氣胸的同側肺部"],"answer":2,"image":""},{"id":"md4-113-2-24","subject":"md4","topic":"兒科-內分泌遺傳","meta":"113年第2次第24題","year":113,"session":2,"number":24,"question":"關於先天性腎上腺增生症（congenital adrenal hyperplasia），下列敘述何者最適當？","options":["(A) 21-羥化酶缺乏（21-hydroxylase deficiency）是造成此疾病的唯一原因","(B) 若合併醛固酮缺乏（aldosterone deficiency），出生72小時內一定會發生失鹽危症（salt-losing crisis）","(C) 是46, XX女嬰有性發展障礙（disorders of sex development）最常見的原因","(D) 強烈建議於懷第一胎時進行常規產前診斷（prenatal diagnosis）"],"answer":2,"image":""},{"id":"md4-113-2-25","subject":"md4","topic":"兒科-內分泌遺傳","meta":"113年第2次第25題","year":113,"session":2,"number":25,"question":"關於兒童及青少年肥胖防治，下列敘述何者最不適當？","options":["(A) 大於兩歲孩童身體質量指數（BMI）大於第95百分位定義為肥胖","(B) 大於兩歲孩童身體質量指數（BMI）介於第85～95百分位定義為過重","(C) 兒童時期肥胖的孩子，成人時期較容易產生代謝症候群","(D) 兒童肥胖屬於慢性發炎的狀況，可以使用抗發炎藥物治療"],"answer":3,"image":""},{"id":"md4-113-2-26","subject":"md4","topic":"兒科-感染神經","meta":"113年第2次第26題","year":113,"session":2,"number":26,"question":"1歲女童反覆高燒至40℃ 3天，退燒之後精神尚可，伴有輕微腹瀉。第4天後退燒但軀幹出現疹子，關於此疾病的敘述，下列何者最不適當？","options":["(A) 最可能的診斷為roseola infantum","(B) 最主要的致病原為human herpesvirus 8","(C) 此疾病通常為自限性（self-limited）","(D) 在uvulopalatoglossal junction處常可見Nagayama spots"],"answer":1,"image":""},{"id":"md4-113-2-27","subject":"md4","topic":"兒科-心血管呼吸","meta":"113年第2次第27題","year":113,"session":2,"number":27,"question":"目前認為下列何者最能減輕哮吼（viral croup）的症狀？","options":["(A) 化痰藥（mucolytic agents）","(B) 氣管擴張劑（bronchodilator）","(C) 抗生素（antibiotics）","(D) 類固醇（steroid）"],"answer":[1,3],"image":"","answer_note":"更正:第27題答Ｂ或Ｄ或BD者均給分"},{"id":"md4-113-2-28","subject":"md4","topic":"兒科-感染神經","meta":"113年第2次第28題","year":113,"session":2,"number":28,"question":"3歲女孩，最近4天有輕微頭痛併有發燒達39℃，且有喉嚨痛、微咳、活力變差的症狀。身體診察發現頸部淋巴結腫大，扁桃腺有滲出物，且脾臟腫大。實驗室檢驗發現alanine aminotransferase（ALT）升高，下列何項檢驗對診斷最有幫助？","options":["(A) 抗鏈球菌溶血素O抗體（antistreptolysin O, ASLO）","(B) 抗A型肝炎的IgM","(C) 肺炎鏈球菌尿液中抗原","(D) 抗Epstein-Barr病毒的VCA-IgM"],"answer":3,"image":""},{"id":"md4-113-2-29","subject":"md4","topic":"兒科-感染神經","meta":"113年第2次第29題","year":113,"session":2,"number":29,"question":"腦性麻痺的致病危險因子與盛行率的描述，下列何者最不適當？","options":["(A) 腦性麻痺全球的盛行率有稍微上升","(B) 大部分腦性麻痺的原因都是生產中的併發症所造成的（如產程中窒息）","(C) 未開發國家生產併發症所造成腦性麻痺的比例，比開發國家高","(D) 雙胞胎腦性麻痺的危險性會比單胞胎高"],"answer":1,"image":""},{"id":"md4-113-2-30","subject":"md4","topic":"兒科-感染神經","meta":"113年第2次第30題","year":113,"session":2,"number":30,"question":"新生兒發現尾骶骨凹陷（sacral dimple），若僅合併下列何項特徵，則可先觀察，暫不需做核磁共振之影像學檢查？","options":["(A) 皮膚發育不全（aplasia cutis）","(B) 凹陷距肛門邊緣（anal verge）1.5公分","(C) 凹陷處長有毛髮","(D) 附近合併血管瘤"],"answer":1,"image":""},{"id":"md4-113-2-31","subject":"md4","topic":"兒科-感染神經","meta":"113年第2次第31題","year":113,"session":2,"number":31,"question":"關於Dravet syndrome的敘述，下列何者最不適當？","options":["(A) 誘發痙攣的體溫通常比熱性痙攣低","(B) 開始發生痙攣的年紀比多數的熱性痙攣小","(C) 疾病初期可能會出現局部熱性痙攣重積狀態（focal febrile status epilepticus）","(D) 基因變異以CDKL5為主"],"answer":3,"image":""},{"id":"md4-113-2-32","subject":"md4","topic":"兒科-心血管呼吸","meta":"113年第2次第32題","year":113,"session":2,"number":32,"question":"關於休克（shock）的敘述，下列何者最為適當？","options":["(A) 低血壓是休克的早期表現","(B) 張力型氣胸造成分布性休克（distributive shock）","(C) 心搏過速是休克的早期表現","(D) 過敏性反應造成阻塞性休克（obstructive shock）"],"answer":[0,2],"image":"","answer_note":"更正:第32題答Ａ或Ｃ或AC者均給分"},{"id":"md4-113-2-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"113年第2次第33題","year":113,"session":2,"number":33,"question":"關於Gaucher disease type 1的敘述，下列何者最不適當？","options":["(A) 猶太人發生率最高","(B) 常以快速神經退化為初始表現","(C) 是因為acid β-glucosidase酵素活性缺乏導致","(D) 可以enzyme replacement therapy和bone marrow transplantation治療"],"answer":1,"image":""},{"id":"md4-113-2-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"113年第2次第34題","year":113,"session":2,"number":34,"question":"下列關於蕁麻疹（urticaria）的敘述，何者錯誤？","options":["(A) 臨床上急性與慢性蕁麻疹的區分以六週做為分界","(B) 蕁麻疹可能與血管性水腫（angioedema）一起出現","(C) 與第一型過敏反應（type I hypersensitivity）相關","(D) 慢性蕁麻疹的第一線治療為環孢素（cyclosporine）"],"answer":3,"image":""},{"id":"md4-113-2-35","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"113年第2次第35題","year":113,"session":2,"number":35,"question":"50歲女性病患主訴如圖所示的皮疹發生於背部，頭皮，手肘及膝蓋處有十餘年時間，最有可能的診斷為何？","options":["(A) 尋常性乾癬（psoriasis vulgaris）","(B) 尋常性魚鱗癬（ichthyosis vulgaris）","(C) 蕁麻疹（urticaria）","(D) 玫瑰糠疹（pityriasis rosea）"],"answer":0,"image":"md4-113-2-35.jpeg"},{"id":"md4-113-2-36","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"113年第2次第36題","year":113,"session":2,"number":36,"question":"過敏性接觸性皮膚炎（allergic contact dermatitis）和刺激性接觸性皮膚炎（irritant contact dermatitis）的比較，下列敘述何者正確？","options":["(A) 前者比較常見","(B) 後者比較嚴重","(C) 前者需要先前的暴露以造成致敏","(D) 後者可用貼膚試驗（patch testing）確診"],"answer":2,"image":""},{"id":"md4-113-2-37","subject":"md4","topic":"皮膚-感染","meta":"113年第2次第37題","year":113,"session":2,"number":37,"question":"下列那一個疾病和馬拉色菌（Malassezia）感染較無關係？","options":["(A) 汗斑（pityriasis versicolor）","(B) 新生兒頭部膿疱病（neonatal cephalic pustulosis）","(C) 脂漏性皮膚炎（seborrheic dermatitis）","(D) 凹陷性角質溶解症（pitted keratolysis）"],"answer":3,"image":""},{"id":"md4-113-2-38","subject":"md4","topic":"皮膚-感染","meta":"113年第2次第38題","year":113,"session":2,"number":38,"question":"一名年輕男性從小患有異位性皮膚炎，最近因皮膚病灶惡化且有刺痛感前來求診，如圖所示，最有可能之診斷為何？","options":["(A) 膿痂疹（impetigo）","(B) 疱疹性濕疹（eczema herpeticum）","(C) 水痘（varicella）","(D) 葡萄球菌皮膚燙傷樣症候群（staphylococcal scalded skin syndrome）"],"answer":1,"image":"md4-113-2-38.jpeg"},{"id":"md4-113-2-39","subject":"md4","topic":"皮膚-腫瘤","meta":"113年第2次第39題","year":113,"session":2,"number":39,"question":"3歲男童，據家長陳述近兩年來發現小孩腳掌出現如圖所示慢慢變大的皮下腫塊。小孩雖無不適之主訴，但有時會不經意去摳抓病灶，病灶隨後會出現暫時性的紅腫及搔癢感，像是蕁麻疹發作時的皮膚症狀。下列何者是最可能的診斷？","options":["(A) 脂肪瘤（lipoma）","(B) 肥大細胞瘤（mastocytoma）","(C) 血管纖維瘤（angiofibroma）","(D) 平滑肌瘤（leiomyoma）"],"answer":1,"image":"md4-113-2-39.jpeg"},{"id":"md4-113-2-40","subject":"md4","topic":"皮膚-腫瘤","meta":"113年第2次第40題","year":113,"session":2,"number":40,"question":"承上題，上述皮膚腫瘤經搔抓而出現暫時性蕁麻疹樣的情形，臨床稱之為何？","options":["(A) Koebner phenomenon","(B) Darier sign","(C) Auspitz sign","(D) Nikolsky sign"],"answer":1,"image":""},{"id":"md4-113-2-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"113年第2次第41題","year":113,"session":2,"number":41,"question":"56歲女性出現如圖所示病灶，最可能的診斷與最重要的實驗室檢查項目為何？","options":["(A) 紅斑性狼瘡（lupus erythematosus）；抗核抗體（antinuclear antibodies, ANA）","(B) 皮肌炎（dermatomyositis）；抗核抗體（antinuclear antibodies, ANA）","(C) 紅斑性狼瘡（lupus erythematosus）；補體（complement）","(D) 皮肌炎（dermatomyositis）；肌胺酸激酶（creatine kinase, CK）"],"answer":3,"image":"md4-113-2-41.jpeg"},{"id":"md4-113-2-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"113年第2次第42題","year":113,"session":2,"number":42,"question":"下列何種疾病最不可能造成皮膚黑色素沉著（hypermelanosis）？","options":["(A) 愛迪生氏病（Addison disease）","(B) 遲發性皮膚紫質症（porphyria cutanea tarda）","(C) 維他命B12缺乏症（vitamin B12 deficiency）","(D) Waardenburg症候群（Waardenburg syndrome）"],"answer":3,"image":""},{"id":"md4-113-2-43","subject":"md4","topic":"兒科-感染神經","meta":"113年第2次第43題","year":113,"session":2,"number":43,"question":"下列有關史特基–韋伯氏症候群（Sturge-Weber syndrome）的敘述，何者錯誤？","options":["(A) 血管病變常發生在單側臉部三叉神經第一分枝支配的皮膚區域","(B) 病人伴有癲癇症的機率不高","(C) 單側眼周皮膚發生血管病變時，此眼後續發生青光眼的機率很高","(D) 發生突變的基因是EPHB4"],"answer":1,"image":""},{"id":"md4-113-2-44","subject":"md4","topic":"神經-中風","meta":"113年第2次第44題","year":113,"session":2,"number":44,"question":"有關缺血性腦中風之抗血栓藥物（antithrombotic drugs）的使用，下列敘述何者最不恰當？","options":["(A) 未發生腦出血性轉型（hemorrhagic transformation）應在中風發生48小時內常規使用抗凝血劑（anticoagulant）","(B) 輕度缺血性中風，短期使用aspirin合併clopidogrel可減少中風復發的機會","(C) 急性大腦靜脈竇栓塞（cerebral venous sinus thrombosis）應優先考慮使用抗凝血劑（anticoagulant）","(D) 頭頸部動脈剝離（arterial dissection），抗凝血劑（anticoagulant）和aspirin的療效相似"],"answer":0,"image":""},{"id":"md4-113-2-45","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"113年第2次第45題","year":113,"session":2,"number":45,"question":"70歲女性為肺癌病人，因右腳無力就診，抽血檢查發現D-dimer檢驗數值為16 mg/L（正常值為＜0.5 mg/L），腦部磁振造影（MRI）檢查結果如下圖（①fluid–attenuated inversion recovery [FLAIR]；② 施打顯影劑之T1影像；③diffusion–weighted imaging [DWI]）。下列何者最可能是腦部病灶的原因？","options":["(A) 多發性腦轉移","(B) 肺結核感染","(C) 可逆性後腦病變症候群（posterior reversible encephalopathy syndrome, PRES）","(D) 多發性腦梗塞"],"answer":3,"image":"md4-113-2-45.jpeg"},{"id":"md4-113-2-46","subject":"md4","topic":"神經-中風","meta":"113年第2次第46題","year":113,"session":2,"number":46,"question":"一位急性缺血性中風病人的臨床表現包括右側顏面麻木（numbness）、右側肢體失調（ataxia）、右側霍納氏症候群（Horner's syndrome）及左側肢體對疼痛感覺下降，此病患最有可能的中風位置位於下列何處？","options":["(A) 右內側視丘（thalamus）","(B) 左內側中腦（midbrain）","(C) 左外側橋腦（pons）","(D) 右外側延腦（medulla）"],"answer":3,"image":""},{"id":"md4-113-2-47","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"113年第2次第47題","year":113,"session":2,"number":47,"question":"36歲女性，最近三年有失眠的困擾。在夜間坐著，特別是躺在床上的時候，覺得兩小腿有一種非動不可的感覺，伴隨一種難以言喻的酸麻。所以她必須不斷的伸一伸、踢一踢或起來走一走，煎熬整夜。下列何者與她的臨床診斷最不可能相關？","options":["(A) 缺鐵性貧血（iron deficiency anemia）","(B) 慢性腎臟病（chronic kidney disease）","(C) 癲癇症（epilepsy）","(D) 睡眠週期性肢體抽動症（periodic limb movements in sleep）"],"answer":2,"image":""},{"id":"md4-113-2-48","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"113年第2次第48題","year":113,"session":2,"number":48,"question":"68歲男性肝硬化病人，同時也有高血壓和糖尿病正接受治療中。因為中大腦動脈梗塞造成中風後癲癇，使用下列何種抗癲癇藥物最為合適？","options":["(A) phenytoin","(B) valproic acid","(C) levetiracetam","(D) perampanel"],"answer":2,"image":""},{"id":"md4-113-2-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"113年第2次第49題","year":113,"session":2,"number":49,"question":"下列何者不是治療急性偏頭痛發作的藥物？","options":["(A) erenumab","(B) sumatriptan","(C) dihydroergotamine","(D) prochlorperazine"],"answer":0,"image":""},{"id":"md4-113-2-50","subject":"md4","topic":"兒科-感染神經","meta":"113年第2次第50題","year":113,"session":2,"number":50,"question":"20歲女性最近兩週發生癲癇，也有幻視幻聽，妄想旁人要害她，肢體及臉、口部會有不自主的抽搐動作。她過去身體健康，也沒有使用任何藥物。腦部磁振造影掃描結果正常，她最可能的診斷是：","options":["(A) 抗NMDA受體腦炎（anti-N-methyl-D-aspartate receptor encephalitis）","(B) 隱球菌腦膜炎（cryptococcal meningitis）","(C) 腸病毒腦炎（enterovirus encephalitis）","(D) 鏈球菌腦膜炎（streptococcal meningitis）"],"answer":0,"image":""},{"id":"md4-113-2-51","subject":"md4","topic":"神經-失智退化運動障礙","meta":"113年第2次第51題","year":113,"session":2,"number":51,"question":"關於巴金森氏症候群（parkinsonian syndrome）的敘述，下列何者錯誤？","options":["(A) 後天的（acquired）巴金森氏症的成因包含藥物引發、水腦、缺氧性腦病變、病毒感染或腦炎後遺症、一氧化碳中毒、腦中風等","(B) 常見的Parkinson-Plus syndrome包含大腦皮質基底核退化症（corticobasal degeneration）、多重系統萎縮症（multiple system atrophy）及進行性上眼神經核麻痺症（progressive supranuclear palsy）","(C) 巴金森氏病（Parkinson disease）是最常見的神經退化性動作障礙疾病，其主要臨床表現為顫抖（tremor）、動作遲緩（bradykinesia）、肢體僵硬（rigidity）及姿勢不穩（postural instability）","(D) 巴金森氏病（Parkinson disease）是運動障礙疾病，不會有非動作（non-motor）相關症狀"],"answer":3,"image":""},{"id":"md4-113-2-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"113年第2次第52題","year":113,"session":2,"number":52,"question":"對於威爾森氏病（Wilson disease）之敘述，下列何者錯誤？","options":["(A) 是一種體隱性遺傳疾病，因ATP7B基因突變導致","(B) 常見的神經學檢查異常包括：精神症狀、巴金森氏症（parkinsonism）、說話及吞嚥困難、肌張力不全、姿態性顫抖和步態異常等","(C) 因體內銅離子代謝異常，患者血液中ceruloplasmin的濃度通常高於正常值","(D) 治療可用排銅藥物（如penicillamine）或抑制銅離子吸收（如zinc sulphate）"],"answer":2,"image":""},{"id":"md4-113-2-53","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"113年第2次第53題","year":113,"session":2,"number":53,"question":"22歲女性，突發性左半身無力，肌力僅3分及右半身麻木，經檢查右側肢體對針刺感覺（pinprick sensation）有明顯下降，下列臨床症候中，何者最不可能合併出現？","options":["(A) 左腳Babinski sign異常","(B) 右側肢體對震動感覺（vibratory sensation）有明顯下降","(C) 左側肢體對關節位置感覺（joint position sensation）有明顯下降","(D) 右側肢體對溫度感覺（temperature sensation）有明顯下降"],"answer":1,"image":""},{"id":"md4-113-2-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"113年第2次第54題","year":113,"session":2,"number":54,"question":"肌電圖中關於自發性活動電位的顫波（fibrillation）或正相尖波（positive sharp wave）通常代表肌肉出現「去神經（denervation）現象」，下列何者最不易看到此現象？","options":["(A) 運動神經元疾病（motor neuron disease）","(B) 多發性肌炎（polymyositis）","(C) 糖尿病多發性神經病變（diabetic polyneuropathy）","(D) 週期性麻痺（periodic paralysis）"],"answer":3,"image":""},{"id":"md4-113-2-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"113年第2次第55題","year":113,"session":2,"number":55,"question":"30歲女性，右眼瞼下垂兩個月，但無複視，此症狀早上比較輕微，睡前比較嚴重。最可能的診斷為何？","options":["(A) 格林–巴利症候群（Guillain-Barré syndrome）","(B) 重症肌無力（myasthenia gravis）","(C) 腦動脈瘤（cerebral artery aneurysm）","(D) 運動神經元疾病（motor neuron disease）"],"answer":1,"image":""},{"id":"md4-113-2-56","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"113年第2次第56題","year":113,"session":2,"number":56,"question":"關於腦膜瘤（meningioma）的敘述，下列何者錯誤？","options":["(A) 是第二常見的原發性顱內腫瘤","(B) 發生的機會隨著年齡增加而增加","(C) 女性發生腦膜瘤的機率比男性高","(D) 可能發生在脊髓硬腦膜"],"answer":0,"image":""},{"id":"md4-113-2-57","subject":"md4","topic":"神經-失智退化運動障礙","meta":"113年第2次第57題","year":113,"session":2,"number":57,"question":"下列何者基因發生致病突變會導致肌萎縮性側索硬化（amyotrophic lateral sclerosis）？","options":["(A) SOD1","(B) APP","(C) LRRK2","(D) parkin"],"answer":0,"image":""},{"id":"md4-113-2-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"113年第2次第58題","year":113,"session":2,"number":58,"question":"35歲男性，三天前開始突然頭痛、發燒、頸部僵硬，於急診執行腰椎穿刺檢查，數值如下：腦脊髓液（CSF）紅血球（RBC）= 0 /μL；白血球（WBC）= 40 /μL（90%為淋巴球、10%為中性球），蛋白質（protein）= 50 mg/dL；葡萄糖（glucose）= 70 mg/dL。下列何者為最可能的診斷？","options":["(A) 病毒性腦膜炎","(B) 細菌性腦膜炎","(C) 結核性腦膜炎","(D) 隱球菌腦膜炎"],"answer":0,"image":""},{"id":"md4-113-2-59","subject":"md4","topic":"精神-精神病","meta":"113年第2次第59題","year":113,"session":2,"number":59,"question":"陳先生目前45歲，於21歲時被診斷為思覺失調症，已住過精神科病房多次，病情復發原因為未定時服用精神科藥物。近年來在家人的協助下，定期於精神科門診接受治療追蹤，已無幻聽和被害妄想等症狀，但家屬發現陳先生比較少話，衛生習慣不佳，不愛洗澡，被動退縮等行為表現，一直未明顯改善。下列那種情況解釋陳先生目前之行為表現最適當？","options":["(A) 思覺失調症的正性症狀","(B) 思覺失調症的負性症狀","(C) 思覺失調症的認知障礙","(D) 思覺失調症合併焦慮症狀"],"answer":1,"image":""},{"id":"md4-113-2-60","subject":"md4","topic":"精神-精神病","meta":"113年第2次第60題","year":113,"session":2,"number":60,"question":"有關精神疾病之藥物治療，下列敘述何者最不適當？","options":["(A) 長期使用鋰鹽（lithium）可能有甲狀腺及心臟之副作用","(B) 抗精神病藥物clozapine與抗憂鬱藥物fluvoxamine會有藥物交互作用","(C) 情緒穩定劑valproic acid和lamotrigine併用時，可能影響濃度增加過敏的機率","(D) 抗精神病藥物作用在多巴胺（dopamine）接受器，會導致姿態性低血壓"],"answer":3,"image":""},{"id":"md4-113-2-61","subject":"md4","topic":"精神-精神病","meta":"113年第2次第61題","year":113,"session":2,"number":61,"question":"下列何項憂鬱症狀較無法預測日後衍生出雙相情緒障礙症（bipolar disorder）？","options":["(A) 在25歲以前有合併精神病症狀之憂鬱症發作","(B) 大於5次以上之憂鬱發作","(C) 合併有精神運動性遲滯","(D) 與生活事件有關之憂鬱症發作"],"answer":3,"image":""},{"id":"md4-113-2-62","subject":"md4","topic":"精神-精神病","meta":"113年第2次第62題","year":113,"session":2,"number":62,"question":"有關類思覺失調症（schizophreniform disorder）的敘述，下列何者最不適當？","options":["(A) 其症狀表現與思覺失調症相似，只是症狀持續時間大於1個月，少於6個月","(B) 其盛行率無性別差異","(C) 有半數以上會進展成思覺失調症","(D) 抗精神病藥物的療效優於思覺失調症"],"answer":1,"image":""},{"id":"md4-113-2-63","subject":"md4","topic":"精神-精神官能症","meta":"113年第2次第63題","year":113,"session":2,"number":63,"question":"有關特定畏懼症（specific phobia）之治療方式，下列何者常用且最有效？","options":["(A) 光照治療（light therapy）","(B) 電痙攣治療（electro-convulsive therapy）","(C) 行為治療（behavior therapy）","(D) 抗精神病劑（antipsychotics）治療"],"answer":2,"image":""},{"id":"md4-113-2-64","subject":"md4","topic":"精神-精神官能症","meta":"113年第2次第64題","year":113,"session":2,"number":64,"question":"吳小姐，35歲，因在辦公室裡突然呼吸困難、頭暈、心悸、害怕、覺得快要死掉或心臟病發作，被送到綜合醫院急診，經詳細檢查，包括心電圖、心臟超音波和實驗室檢驗等，均無異常發現，其在過去1個月已有4次發作，會持續約30分鐘或至送醫診治才好些，轉至精神科治療後，病情逐步緩解。下列診斷中，何者最適當？","options":["(A) 泛焦慮症","(B) 強迫症","(C) 恐慌症","(D) 適應障礙症合併焦慮症狀"],"answer":2,"image":""},{"id":"md4-113-2-65","subject":"md4","topic":"精神-精神病","meta":"113年第2次第65題","year":113,"session":2,"number":65,"question":"有關憂鬱症的敘述，下列何者最不適當？","options":["(A) 至少會有憂鬱情緒（depressed mood）或失去興趣（loss of interest）的其中一項","(B) 可能會出現食慾增加、睡眠增加的生理變化","(C) 考慮抗憂鬱劑之成癮風險，治療4到6週後，憂鬱症狀一旦緩解，宜及早停藥","(D) 三環抗憂鬱劑過量時會有致死的危險性；血清素再吸收抑制劑（SSRI）則較為安全"],"answer":2,"image":""},{"id":"md4-113-2-66","subject":"md4","topic":"精神-器質性與物質使用","meta":"113年第2次第66題","year":113,"session":2,"number":66,"question":"有關慢性疲勞症候群（chronic fatigue syndrome）的敘述，下列何者最適當？","options":["(A) 有淋巴結痛（tender lymph nodes）則可排除此症候群","(B) 需鑑別感染引起之疲勞","(C) 適度休息可以改善症狀","(D) 僅少數個案可能符合重鬱症診斷"],"answer":1,"image":""},{"id":"md4-113-2-67","subject":"md4","topic":"神經-失智退化運動障礙","meta":"113年第2次第67題","year":113,"session":2,"number":67,"question":"有關阿茲海默症（Alzheimer's disease）生物標記的敘述，下列何者最適當？","options":["(A) apolipoprotein E4基因是阿茲海默症必要且充分病因，所以可以當作診斷標記","(B) 類澱粉蛋白相關（amyloid-based）的標記具有早期診斷價值","(C) 類澱粉蛋白相關（amyloid-based）的標記包括陽性類澱粉蛋白正子攝影（positron emission tomography）與較高濃度的腦脊髓液amyloid beta-42濃度","(D) 腦部磁振造影掃描顯示海馬迴體積減少是類澱粉蛋白相關（amyloid-based）的標記"],"answer":1,"image":""},{"id":"md4-113-2-68","subject":"md4","topic":"精神-器質性與物質使用","meta":"113年第2次第68題","year":113,"session":2,"number":68,"question":"有關長期大量飲用酒精造成之Wernicke-Korsakoff syndrome，下列敘述何者最適當？","options":["(A) 出現的初期，應給與大劑量的thiamine","(B) Wernicke's encephalopathy即使在治療後，幾乎會發展成Korsakoff's syndrome","(C) 其眼球動作異常（ocular motility abnormality），經常只涉及單側眼睛，若涉及雙側眼睛，也是對稱的表現","(D) 出現短期記憶（short-term memory）障礙，其神經病理學上主要和顳葉受損有關"],"answer":0,"image":""},{"id":"md4-113-2-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"113年第2次第69題","year":113,"session":2,"number":69,"question":"中樞神經興奮劑（stimulant）誘發精神相關疾病與其症狀，下列敘述何者最不適當？","options":["(A) 中毒會產生失眠及睡眠剝奪（sleep deprivation），戒斷時期會產生嗜睡及夢魘（nightmare）","(B) 誘發焦慮症狀，可發生在中毒期及戒斷期","(C) 誘發的幻覺以幻聽為主，而視幻覺及觸幻覺較不常見","(D) 安非他命誘發的焦慮症以及精神疾病，皆須長期接受抗精神病藥物或抗焦慮劑治療，至少一年"],"answer":3,"image":""},{"id":"md4-113-2-70","subject":"md4","topic":"精神-器質性與物質使用","meta":"113年第2次第70題","year":113,"session":2,"number":70,"question":"76歲男性，平日合併使用具有抗乙酼膽鹼類（anti-cholinergic）的腸胃藥物與安眠藥，完成髖關節手術後，尿管留置，在加護病房裡出現譫妄症。下列有關病因的分析，何者最不適當？","options":["(A) 病患的年齡性別，可能是前置因子（predisposing factor）","(B) 術前使用的上述兩類藥物可能是前置因子（predisposing factor）","(C) 加護病房的環境可能是前置因子（predisposing factor）","(D) 髖關節手術可能是誘發因子（precipitating factor）"],"answer":2,"image":""},{"id":"md4-113-2-71","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"113年第2次第71題","year":113,"session":2,"number":71,"question":"有關自閉症類群障礙症（autism spectrum disorder）的相關特徵，下列敘述何者最適當？","options":["(A) 大約80%的兒童患者合併有智能不足的現象","(B) 在合併有智能不足的患者中，約有30%是屬於輕度到中度障礙的範圍（mild to moderate range）","(C) 年幼患者很少合併有過動或注意力不足的症狀","(D) 患者對於外在的感官刺激主要都是出現反應過低（underrespond）的現象，很少出現反應過強（overrespond）的現象"],"answer":1,"image":""},{"id":"md4-113-2-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"113年第2次第72題","year":113,"session":2,"number":72,"question":"有關注意力不足／過動症（ADHD）的治療，下列敘述何者最適當？","options":["(A) 心理治療是第一線的治療方式","(B) methylphenidate是臺灣唯一核准治療ADHD的中樞神經興奮劑（stimulant）","(C) 治療ADHD的藥物atomoxetine是新一代的中樞神經興奮劑（stimulant）","(D) 根據美國食品藥物管理局（Food and Drug Administration）的規定，病人必須滿3歲以上才能服用methylphenidate"],"answer":1,"image":""},{"id":"md4-113-2-73","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"113年第2次第73題","year":113,"session":2,"number":73,"question":"謝先生55歲，罹患重鬱症多年，不規則治療，無業，某天早上夫妻口角，獨自出門散心，卻從大樓頂樓跳下死亡，下列敘述何者最適當？","options":["(A) 夫妻關係應是自殺主因","(B) 重鬱症不會有現實感不佳之症狀","(C) 其致病機轉最可能有血清素（serotonin）的相關異常","(D) 即使有家人陪伴，也無法防止他跳樓自殺"],"answer":2,"image":""},{"id":"md4-113-2-74","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"113年第2次第74題","year":113,"session":2,"number":74,"question":"關於轉移性腦瘤（brain metastasis）的影像表現，下列敘述何者錯誤？","options":["(A) 若無出血，轉移性腦瘤在不注射顯影劑的電腦斷層影像通常是低密度的病灶","(B) 在頭部電腦斷層和磁振造影檢查，靜脈注射顯影劑之後，轉移性腦瘤通常呈現顯影加強現象","(C) 在成人的後顱窩腦實質病灶，最不可能是轉移性腦瘤","(D) 轉移性腦瘤若是單一性，可能和原發性腦腫瘤無法區分"],"answer":2,"image":""},{"id":"md4-113-2-75","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"113年第2次第75題","year":113,"session":2,"number":75,"question":"有關肘關節附近骨折的X光片敘述，下列何者最適當？","options":["(A) 肱骨遠端前脂肪墊向前移位時，若無明顯可見骨折線，則可完全排除骨折","(B) 骨折後一星期左右常出現高密度骨質區域","(C) 不明顯且無位移的骨折，在受傷後一星期左右可能較為明顯可見","(D) 骨折固定後，在骨釘旁出現的低密度區域相當常見，只需觀察"],"answer":2,"image":""},{"id":"md4-113-2-76","subject":"md4","topic":"皮膚-感染","meta":"113年第2次第76題","year":113,"session":2,"number":76,"question":"下列敘述何者不是壞死性筋膜炎在影像學上的表現？","options":["(A) 沿著筋膜平面上有液體積存","(B) 如果筋膜可以被顯影劑顯現代表已經壞死","(C) 皮下或軟組織內有氣體積存","(D) 深層筋膜厚度增加"],"answer":1,"image":""},{"id":"md4-113-2-77","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"113年第2次第77題","year":113,"session":2,"number":77,"question":"23公斤兒童需禁食（NPO）時，前24小時基本輸液（fluid），平均每小時要給多少毫升（mL）？","options":["(A) 35","(B) 45","(C) 55","(D) 65"],"answer":3,"image":""},{"id":"md4-113-2-78","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"113年第2次第78題","year":113,"session":2,"number":78,"question":"一位25歲女性，和朋友上山沿途採集花草，回家後雙手出現多處小水泡與癢疹，如圖，最可能的診斷為何？","options":["(A) tinea manuum","(B) psoriasis","(C) sunburn reaction","(D) contact dermatitis"],"answer":3,"image":"md4-113-2-78.jpeg"},{"id":"md4-113-2-79","subject":"md4","topic":"醫學倫理與法規","meta":"113年第2次第79題","year":113,"session":2,"number":79,"question":"在小兒心臟門診時，楊媽媽揚言要控告她的婦產科醫師，因為產前做超音波檢查時都說孩子正常，等到孩子出生後發現有複雜難治的心臟病。楊媽媽問小兒心臟科醫師那位婦產科醫師是否有過失。小兒心臟科醫師之回應，下列何者最恰當？","options":["(A) 「當時胎兒還小，婦產科醫師要看到母體內胎兒心臟的異常與否，要視產前當時的情況而定。」","(B) 「看不到那種心臟結構的異常，確實有疏失。」","(C) 「他是我的同事，我不方便評論。」","(D) 「妳還是去問那位婦產科醫師才對。」"],"answer":0,"image":""},{"id":"md4-113-2-80","subject":"md4","topic":"醫學倫理與法規","meta":"113年第2次第80題","year":113,"session":2,"number":80,"question":"有關為病人守密，下列敘述何者適當？①病人有權利決定是否讓他人知道自己的祕密，但此權利以「是否會傷害他人」作為界限 ②醫院工作人員可以在公開場合討論病患病情，只要不公開其姓名 ③如果病患的病情會影響到他人，便可將其個資全數向社會公開，以免他人受害 ④若病人的某些個資已經進入公共領域或被公開，醫療人員便沒有對這些資訊保密的必要","options":["(A) ①④","(B) ①②③","(C) ②③④","(D) ①②"],"answer":0,"image":""},{"id":"md4-114-1-1","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"114年第1次第1題","year":114,"session":1,"number":1,"question":"下列有關自費疫苗接種建議之敘述，何者最不適當？","options":["(A) 肺炎鏈球菌疫苗有結合型以及多醣體疫苗兩種，其中結合型疫苗不適用於2歲以下幼兒","(B) 幼童常規接種的百日咳抗體只能維持5～10年，建議青少年自費接種一劑減量破傷風白喉非細胞性百日咳混合疫苗（Tdap）","(C) 曾施打過水痘疫苗者仍可能罹患水痘，稱為突破性感染。建議未得過水痘的幼童在4～6歲自費接種第二劑水痘疫苗","(D) 針對欲前往麻疹流行地區之6個月以上未滿1歲嬰兒，建議可先自費接種一劑麻疹腮腺炎德國麻疹混合疫苗（MMR疫苗）"],"answer":0,"image":""},{"id":"md4-114-1-2","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"114年第1次第2題","year":114,"session":1,"number":2,"question":"下列有關母乳哺餵之敘述，何者最不適當？","options":["(A) 母乳哺育可以減少寶寶過敏性疾病以及成人期心血管疾病的發生率","(B) 哺餵母乳的媽媽罹患乳癌及卵巢癌的機率較低","(C) 喝母乳的寶寶黃疸可能持續到6個月才完全消退","(D) 喝母乳的寶寶在頭幾個月的大便通常是稀稀水水的，甚至一吃就解，這是正常現象"],"answer":2,"image":""},{"id":"md4-114-1-3","subject":"md4","topic":"兒科-消化系統疾病","meta":"114年第1次第3題","year":114,"session":1,"number":3,"question":"27週出生的早產兒，開始餵食12天後，突然發生嗜睡、腹脹、含膽汁嘔吐、糞便帶血絲等症狀。其腹部X光檢查如下圖。發生此狀況時，下列何種處置最不適當？","options":["(A) 給與廣效抗生素","(B) 增加靜脈輸液給與量","(C) 會診小兒外科考慮手術","(D) 安排上消化道攝影檢查"],"answer":3,"image":"md4-114-1-3.jpeg"},{"id":"md4-114-1-4","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"114年第1次第4題","year":114,"session":1,"number":4,"question":"剛出生新生兒之血紅素（hemoglobin）為9.7 g/dL，血球容積比（hematocrit）為30%，平均紅血球體積（mean corpuscular volume, MCV）為80 fL，由此檢驗值可推測此新生兒最有可能的診斷為何？","options":["(A) 缺鐵性貧血（iron deficiency anemia）","(B) β型地中海型貧血（β-thalassemia）","(C) α型地中海型貧血（α-thalassemia）","(D) 蠶豆症（glucose-6-phosphate dehydrogenase deficiency）"],"answer":2,"image":""},{"id":"md4-114-1-5","subject":"md4","topic":"兒科-消化系統疾病","meta":"114年第1次第5題","year":114,"session":1,"number":5,"question":"嬰兒出生後無法進食，持續使用靜脈營養（parenteral nutrition）。第40天後出現黃疸、糞便呈極淡黃色，實驗室檢查值：ALT（alanine aminotransferase）為125 U/L，serum total bilirubin為12 mg/dL，conjugated bilirubin為5.6 mg/dL。下列何者最不可能是此嬰兒黃疸之原因？","options":["(A) 新生兒膽道閉鎖（biliary atresia）","(B) 新生兒肝炎症候群（neonatal hepatitis syndrome）","(C) 靜脈營養導致之膽汁滯留（parenteral nutrition cholestasis）","(D) 吉伯特氏症候群（Gilbert syndrome）"],"answer":3,"image":""},{"id":"md4-114-1-6","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第1次第6題","year":114,"session":1,"number":6,"question":"關於兒童心肌炎（myocarditis），下列敘述何者最不適當？","options":["(A) 病毒感染是引起兒童心肌炎常見的病因","(B) 有部分的心肌炎是屬於輕症","(C) 聽診心音有摩擦音（friction rub），代表心包膜也受影響","(D) 兒童心肌炎如果恢復後，大多數會留下嚴重後遺症"],"answer":3,"image":""},{"id":"md4-114-1-7","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第1次第7題","year":114,"session":1,"number":7,"question":"出生2天的女嬰發紺，被診斷為大血管轉位（d-transposition of the great arteries with intact ventricular septum）。下列何者之處置最不適當？","options":["(A) 若兩心房間交通受限，做心房造口術（atrial septostomy）","(B) 靜脈注射前列腺素（prostaglandin E1, PGE 1）","(C) 為避免造成肺部壓力上升，應儘量避免放置氣管內管","(D) 儘快進行心臟矯正手術（arterial switch operation）"],"answer":2,"image":""},{"id":"md4-114-1-8","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第1次第8題","year":114,"session":1,"number":8,"question":"關於各種先天性心臟病引起心臟衰竭的臨床症狀表現時機，下列何者最為適當？","options":["(A) 大型的心室中隔缺損（ventricular septal defect, VSD）通常出生一週之內就可能會有心臟衰竭的症狀表現","(B) 大型的心房中隔缺損（atrial septal defect, ASD）通常在一歲之內就可能會有心臟衰竭的症狀表現","(C) 左心發育不全症候群（hypoplastic left heart syndrome, HLHS）通常在胎兒時期就可能會發生心臟衰竭的症狀表現","(D) 亞柏斯坦畸形（Ebstein anomaly）合併嚴重三尖瓣逆流通常在胎兒時期就可能會發生心臟衰竭的症狀表現"],"answer":3,"image":""},{"id":"md4-114-1-9","subject":"md4","topic":"兒科-消化系統疾病","meta":"114年第1次第9題","year":114,"session":1,"number":9,"question":"關於肝炎病毒潛伏期（incubation periods），下列敘述何者最適當？","options":["(A) A型肝炎病毒的潛伏期約為15～19天","(B) B型肝炎病毒的潛伏期約為30天","(C) C型肝炎病毒的潛伏期約為7天","(D) E型肝炎病毒的潛伏期約為90天"],"answer":0,"image":""},{"id":"md4-114-1-10","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"114年第1次第10題","year":114,"session":1,"number":10,"question":"足月新生男嬰，出生體重3公斤，全母乳哺餵，出生後6小時開始出現黃疸。身體診察顯示鞏膜與皮膚黃疸。下列何項檢驗結果最可以支持男嬰的黃疸是溶血造成的？","options":["(A) 直接型膽紅素（direct bilirubin）濃度上升","(B) 直接庫氏試驗（direct Coombs test）陰性","(C) 周邊血液抹片可見紅血球碎片（fragmented red blood cells）","(D) 紅血球容積比（hematocrit）55%"],"answer":2,"image":""},{"id":"md4-114-1-11","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"114年第1次第11題","year":114,"session":1,"number":11,"question":"3歲男童無特殊病史，因高燒、倦怠（malaise）、陣發性腹痛、頻繁水瀉2天被送到急診。男童無嘔吐，無服用抗生素。身體診察顯示體溫40.2℃、口腔黏膜乾、心搏快、腹部軟、沒有壓痛（tenderness）或反彈痛（rebound tenderness）。觸診時，男童突然腹絞痛，接著排出含有血絲黏糊便。下列何者是最可能的致病菌？","options":["(A) 輪狀病毒（Rotavirus）","(B) 諾羅病毒（Norovirus）","(C) 志賀氏桿菌（Shigella）","(D) 梭狀困難桿菌（Clostridium difficile）"],"answer":2,"image":""},{"id":"md4-114-1-12","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"114年第1次第12題","year":114,"session":1,"number":12,"question":"關於自體顯性多囊腎（autosomal dominant polycystic kidney disease, ADPKD）及自體隱性多囊腎（autosomal recessive polycystic kidney disease, ARPKD），下列敘述何者最不適當？","options":["(A) ADPKD之囊泡表現可見於肝臟、脾臟、胰臟與女性卵巢","(B) ARPKD較常出現在新生兒時期，可能伴隨有羊水過少、肺部發育不全等表現","(C) 兩者皆可能出現血尿、高血壓、腎衰竭等併發症","(D) 大部分ADPKD的基因缺陷發生在第6對染色體"],"answer":3,"image":""},{"id":"md4-114-1-13","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"114年第1次第13題","year":114,"session":1,"number":13,"question":"關於急性鏈球菌感染後腎炎（acute poststreptococcal glomerulonephritis）的描述，下列何者最為適當？","options":["(A) 最常發生於3歲以下的孩童","(B) 最常見表現為咽喉感染後1至3天內發生巨視性血尿","(C) 於90%的病童其血液中C3與C4數值同時明顯下降","(D) 早期使用抗生素治療鏈球菌並無法減少腎炎的發生"],"answer":3,"image":""},{"id":"md4-114-1-14","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"114年第1次第14題","year":114,"session":1,"number":14,"question":"5歲女童高燒3日及膿尿（pyuria ; WBC 100～150/HPF），住院接受抗生素治療。經投與經驗性抗生素治療3日後，高燒並沒有改善。腹部電腦斷層（有注射顯影劑）檢查顯示如圖，女童最可能的診斷為：","options":["(A) 急性腎絲球腎炎（acute glomerulonephritis）","(B) 急性大葉性腎盂腎炎（acute lobar nephronia）","(C) 急性腎膿瘍（acute renal abscess）","(D) 急性腎梗塞（acute renal infarction）"],"answer":1,"image":"md4-114-1-14.jpeg"},{"id":"md4-114-1-15","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"114年第1次第15題","year":114,"session":1,"number":15,"question":"關於過敏性紫斑症（Henoch-Schönlein purpura），下列敘述何者最為適當？","options":["(A) 紫斑（purpura）主要出現在上肢及軀幹","(B) 抽血大部分會發現血小板低下","(C) 病理表現為血管炎（vasculitis）與IgA沉積在小血管","(D) 大部分病患會造成腎臟發炎，應儘快給與類固醇治療"],"answer":2,"image":""},{"id":"md4-114-1-16","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"114年第1次第16題","year":114,"session":1,"number":16,"question":"有關兒童特發性關節炎（juvenile idiopathic arthritis），下列敘述何者最不適當？","options":["(A) 是指16歲以下至少關節腫痛6週以上","(B) 是兒童最常見的慢性風濕性疾病","(C) 要長期追蹤注意是否合併虹彩炎（anterior uveitis）","(D) 生物製劑（如Omalizumab）可用於治療嚴重者"],"answer":3,"image":""},{"id":"md4-114-1-17","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"114年第1次第17題","year":114,"session":1,"number":17,"question":"有關慢性蕁麻疹，下列敘述何者最適當？","options":["(A) 是指病程反覆發作14天以上","(B) 可能是自體免疫疾病，如：thyroid disease的先期表現","(C) 血清過敏原（specific IgE）檢驗為常規檢測項目","(D) 用第2代抗組織胺治療，即使效果不好也不宜增加劑量"],"answer":1,"image":""},{"id":"md4-114-1-18","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"114年第1次第18題","year":114,"session":1,"number":18,"question":"關於剛出生健康足月新生兒的血液學變化，下列敘述何者最適當？","options":["(A) 與學齡兒童相比，紅血球體積較小，血紅素較低，此乃生理性貧血","(B) 除了第八因子濃度比較接近成人的濃度，其餘的凝血因子濃度都較成人低","(C) 蛋白C與蛋白S數值較學齡兒童高","(D) 血小板功能較學齡兒童佳"],"answer":1,"image":""},{"id":"md4-114-1-19","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"114年第1次第19題","year":114,"session":1,"number":19,"question":"關於兒童癌症，下列敘述何者最不適當？","options":["(A) 兒童癌症僅有少數（8～10%）為偶發，大部分（90%以上）都與先天性的遺傳疾病有關","(B) 白血病是臺灣及美國最常見的兒童癌症類別","(C) 在全面接種B型肝炎疫苗的國家，可觀察到兒童肝細胞癌（hepatocellular carcinoma）的發生率明顯下降","(D) 較可能發生在青少年時期的癌症，有骨癌、何杰金淋巴瘤、性腺癌（卵巢或睪丸癌）及上皮癌等"],"answer":0,"image":""},{"id":"md4-114-1-20","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"114年第1次第20題","year":114,"session":1,"number":20,"question":"3歲男童因發燒1週合併輕度貧血，做骨髓抽吸抹片檢查時發現多處細胞叢集（clumps）形成薔薇狀構造（rosette formation），並圍繞著一些纖維狀物質。下列何者為最有可能的診斷？","options":["(A) 神經母細胞瘤（neuroblastoma）","(B) 急性淋巴性白血病（acute lymphoblastic leukemia）","(C) 感染性單核球增多症（infectious mononucleosis）","(D) 高雪氏症（Gaucher disease）"],"answer":0,"image":"md4-114-1-20.jpeg"},{"id":"md4-114-1-21","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"114年第1次第21題","year":114,"session":1,"number":21,"question":"關於小兒敗血症與敗血性休克的敘述，下列何者最適當？","options":["(A) 敗血症會造成單一身體器官失能，導致死亡","(B) 敗血症是一種感染過程中，造成兒童局部性發炎反應的現象","(C) 兒童敗血症之早期症狀通常為低血壓","(D) 敗血性休克造成血行動力學不穩定或呼吸窘迫時，需要考慮插管治療"],"answer":3,"image":""},{"id":"md4-114-1-22","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第1次第22題","year":114,"session":1,"number":22,"question":"對於兒童氣胸發生後的治療方針，下列敘述何者最適當？","options":["(A) 輕至中度的氣胸，有機會在1個星期內自己改善","(B) 第一次發作的氣胸，其程度小於5%的病童，需要胸管引流治療","(C) 氣胸第一次發作，應使用化學性肋膜黏連術（chemical pleurodesis）治療","(D) 氣胸發作次數與外科內視鏡手術治療時機無關"],"answer":0,"image":""},{"id":"md4-114-1-23","subject":"md4","topic":"兒科-感染神經","meta":"114年第1次第23題","year":114,"session":1,"number":23,"question":"2歲女童，發燒、持續昏睡、呼吸喘及有肌躍型抽搐，身體診察有口腔潰瘍，手部、足部與臀部出現紅色丘疹及水泡。關於此病症的敘述，下列何者最不適當？","options":["(A) 肌躍型抽搐為類似受到驚嚇的動作，可能是腸病毒重症之前兆","(B) 可能是腸病毒71型感染併發重症合併腦幹腦炎，須進行腦脊髓液檢查","(C) 為維持該童之基本血壓，應快速給與大量靜脈輸液","(D) 若因心臟衰竭有休克症狀、血壓下降之情形，升壓藥物應優先使用milrinone"],"answer":2,"image":""},{"id":"md4-114-1-24","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"114年第1次第24題","year":114,"session":1,"number":24,"question":"足月新生兒，出生體重4250公克。因為呼吸喘，入住新生兒病房。母親懷孕時有妊娠糖尿病，僅以飲食控制。出生4小時後，因為活動力不佳，檢查發現低血糖（血糖：39 mg/dL）。下列何種處置最不適當？","options":["(A) 立即靜脈給與2 c.c./kg的葡萄糖水（10%），等到血糖＞70 mg/dL，再抽血檢查低血糖的原因","(B) 需注意是否同時有低血鈣（hypocalcemia）、低血鎂（hypomagnesemia）的情形","(C) 考慮安排心臟超音波，檢查是否有心臟構造的問題","(D) 因出生體重過重，要注意是否有產傷（birth trauma）"],"answer":0,"image":""},{"id":"md4-114-1-25","subject":"md4","topic":"兒科-內分泌遺傳","meta":"114年第1次第25題","year":114,"session":1,"number":25,"question":"14歲女孩有無痛性的雙側甲狀腺腫大，合併心悸、體重減輕、月經不規則。實驗室檢查顯示，free T4 3.6 ng/dL（參考值0.79～1.89）、TSH＜0.03 mIU/L（參考值0.5～5.5）。下列何者是最可能的診斷？","options":["(A) 葛雷夫氏病（Graves disease）","(B) 橋本氏病（Hashimoto disease）","(C) 乳突狀甲狀腺癌（papillary thyroid cancer）","(D) 亞急性甲狀腺炎（subacute thyroiditis）"],"answer":0,"image":""},{"id":"md4-114-1-26","subject":"md4","topic":"兒科-感染神經","meta":"114年第1次第26題","year":114,"session":1,"number":26,"question":"2歲男童發燒5天伴隨全身性瘀點（petechiae）而住院，同時有鼻塞及雙眼眼皮浮腫。身體診察發現頸部淋巴結腫大、扁桃腺有滲出物。抽血檢查：Hb 10 g/dL、WBC 18800/μL、atypical lymphocyte 16%、platelet 20000/μL，GOT 194 IU/L、GPT 109 IU/L、CRP 0.5 mg/dL，EB VCA IgM＞160.0 U/mL；血液塗片染色如圖所示。有關此疾病的敘述，下列何者最不適當？","options":["(A) 最有可能為Epstein-Barr virus感染","(B) 圖中血液塗片中箭頭所指為非典型淋巴球（atypical lymphocyte）","(C) 因為血小板低下症狀嚴重，應儘快使用抗病毒藥物治療","(D) 短期皮質類固醇治療，可能有助於此病症的特定併發症"],"answer":2,"image":"md4-114-1-26.jpeg"},{"id":"md4-114-1-27","subject":"md4","topic":"兒科-感染神經","meta":"114年第1次第27題","year":114,"session":1,"number":27,"question":"關於活性減毒疫苗，下列敘述何者最不適當？","options":["(A) 麻疹、水痘疫苗和B型流行性腦脊髓炎疫苗都是活性減毒疫苗","(B) 活性減毒疫苗往往會誘發長期免疫反應","(C) 大多數活性減毒疫苗通常只需要接種1劑或2劑","(D) MMR活性減毒疫苗需重複接種的目的是誘導那些對第一劑沒有反應者的初始免疫反應（initial immune response）"],"answer":0,"image":""},{"id":"md4-114-1-28","subject":"md4","topic":"兒科-感染神經","meta":"114年第1次第28題","year":114,"session":1,"number":28,"question":"關於麻疹腮腺炎德國麻疹混合疫苗（MMR疫苗）接種及疑似麻疹個案接觸者暴露後預防建議措施的敘述，下列何者最不適當？","options":["(A) 距最近一次暴露72小時內，滿6個月至未滿1歲嬰兒可由醫師評估後選擇接種MMR疫苗或肌肉注射麻疹免疫球蛋白（IMIG）","(B) 注射麻疹免疫球蛋白（IMIG）後，為了提高保護效力，須於2週時再接種MMR疫苗","(C) 未滿1歲嬰兒提前接種MMR疫苗進行暴露後預防時，仍須於滿1歲後，按時程重新完成2劑公費常規疫苗接種","(D) 未滿1歲嬰兒之暴露後預防如接種MMR疫苗，後續接種常規MMR疫苗，應至少間隔28天"],"answer":1,"image":""},{"id":"md4-114-1-29","subject":"md4","topic":"兒科-感染神經","meta":"114年第1次第29題","year":114,"session":1,"number":29,"question":"有關腦性麻痺的敘述，下列何者最不適當？","options":["(A) 造成早產兒的腦性麻痺主要的病灶是腦室旁白質軟化","(B) 超過7成以上的腦性麻痺個案發生的原因與新生兒窒息有關","(C) athetoid cerebral palsy可能起因於核黃疸（kernicterus）的結果","(D) 可能合併有癲癇、認知功能障礙或語言發展遲緩等問題"],"answer":1,"image":""},{"id":"md4-114-1-30","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"114年第1次第30題","year":114,"session":1,"number":30,"question":"關於兒童頭痛，下列那一項病史最不需要考慮進行神經影像學檢查？","options":["(A) 頭痛合併有癲癇發作","(B) 家族有偏頭痛病史","(C) 咳嗽時頭痛會更加劇烈","(D) 沒有外傷的情況下從來沒有經歷過如此劇烈之頭痛"],"answer":1,"image":""},{"id":"md4-114-1-31","subject":"md4","topic":"兒科-內分泌遺傳","meta":"114年第1次第31題","year":114,"session":1,"number":31,"question":"關於Wilson disease的敘述，下列何者最不適當？","options":["(A) 10歲以前發病的族群，常以神經學症狀為主要表現，尤其是癲癇發作","(B) 屬隱性遺傳疾病，因第13對染色體上ATP7B基因出現變異","(C) 神經學外的表現還有肝衰竭、肝硬化、凝血功能異常等","(D) 不能完全以ceruloplasmin levels確立或排除診斷，仍需考慮急性發炎疾病、懷孕等因素"],"answer":0,"image":""},{"id":"md4-114-1-32","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"114年第1次第32題","year":114,"session":1,"number":32,"question":"關於兒科病童在急診就診的初步評估，下列何者最為適當？","options":["(A) 初步評估的兒童評估三角（pediatric assessment triangle）著重的重點為呼吸道（airway）、呼吸（breathing）、循環（circulation）","(B) 初步評估發現病童為危急狀態，應在完成初級（primary）、次級（secondary）與三級評估（tertiary assessment）後，再進行緊急處理","(C) 初級評估（primary assessment）中，收縮壓的最低標準，1歲以上需≧「70 mmHg＋年紀（以年算）× 2」，在10歲以上為≧90 mmHg","(D) 三級評估（tertiary assessment）包括焦點式病史詢問及身體診察"],"answer":2,"image":""},{"id":"md4-114-1-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"114年第1次第33題","year":114,"session":1,"number":33,"question":"下列那一個狀況最不需要接受遺傳諮詢？","options":["(A) 年齡35歲以上的懷孕婦女","(B) 上一胎為先天性異常孩子的父母","(C) 經歷重複流產的婦女","(D) 確診為缺鐵性貧血的婦女"],"answer":3,"image":""},{"id":"md4-114-1-34","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"114年第1次第34題","year":114,"session":1,"number":34,"question":"30歲女性，在軀幹及四肢出現靶心狀病灶及水疱，同時伴隨口腔糜爛，眼結膜紅腫以及會陰部糜爛。下列何者為最可能之診斷？","options":["(A) 多型性紅斑（erythema multiforme）","(B) 梅毒（syphilis）","(C) 汗疱疹（pompholyx）","(D) 結節性紅斑（erythema nodosum）"],"answer":0,"image":"md4-114-1-34.jpeg"},{"id":"md4-114-1-35","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"114年第1次第35題","year":114,"session":1,"number":35,"question":"基於乾癬的免疫致病機轉，以下列那一細胞激素作為標靶阻斷時無法達到有效治療？","options":["(A) TNF-α","(B) IL-17A","(C) IL-4","(D) IL-23"],"answer":2,"image":""},{"id":"md4-114-1-36","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"114年第1次第36題","year":114,"session":1,"number":36,"question":"有關脂漏性皮膚炎（seborrheic dermatitis）的敘述，下列何者正確？","options":["(A) 皮膚受Malassezia furfur感染與此病無關","(B) HIV感染不會加重脂漏性皮膚炎的臨床症狀","(C) 遇到難以控制的脂漏性皮膚炎患者，醫師須考慮該患者罹患乾癬的可能性","(D) Parkinson disease不會加重脂漏性皮膚炎的臨床症狀"],"answer":2,"image":""},{"id":"md4-114-1-37","subject":"md4","topic":"皮膚-感染","meta":"114年第1次第37題","year":114,"session":1,"number":37,"question":"下列關於皮膚的病毒感染之敘述，何者錯誤？","options":["(A) 感染性紅斑（erythema infectiosum）是parvovirus B19感染所導致，典型是像slapped cheek的臉部紅疹","(B) 水痘（varicella）的疫苗保護力極佳，打過疫苗的人就不可能再被varicella-zoster virus（VZV）感染而長出水痘","(C) 手足口病（hand-foot-mouth disease）其致病原的主要感染途徑是糞口傳染","(D) 尖圭濕疣（condyloma acuminatum）主要的致病原為HPV-6及HPV-11"],"answer":1,"image":""},{"id":"md4-114-1-38","subject":"md4","topic":"皮膚-感染","meta":"114年第1次第38題","year":114,"session":1,"number":38,"question":"25歲男性志願役士兵，平常在軍隊整天穿著軍靴，此次因腳底會散發異味的問題來就診，病灶如圖所示，最可能的診斷為何？","options":["(A) 足癬（tinea pedis）","(B) 異汗性濕疹（dyshidrotic eczema）","(C) 凹陷性角質溶解症（pitted keratolysis）","(D) 掌蹠膿疱症（palmoplantar pustulosis）"],"answer":2,"image":"md4-114-1-38.jpeg"},{"id":"md4-114-1-39","subject":"md4","topic":"皮膚-腫瘤","meta":"114年第1次第39題","year":114,"session":1,"number":39,"question":"某些遺傳性症候群的患者由於先天性基因的缺失，往往造成其皮膚發生鱗狀上皮細胞癌的機率較常人高。這些症候群不包括下列何者？","options":["(A) 著色性乾皮症（xeroderma pigmentosum）","(B) 韋爾納症候群（Werner syndrome）","(C) 史特基–韋伯氏症候群（Sturge-Weber syndrome）","(D) 眼皮膚白化症（oculocutaneous albinism）"],"answer":2,"image":""},{"id":"md4-114-1-40","subject":"md4","topic":"皮膚-腫瘤","meta":"114年第1次第40題","year":114,"session":1,"number":40,"question":"55歲男性，自兩年前在軀幹與四肢陸續出現許多無症狀的紅色斑塊，並合併輕微脫屑（如圖所示），經KOH檢查並未發現有黴菌感染；最近數週發現有些病灶形成結節。皮膚切片之病理檢查結果顯示表皮中有許多異常細胞浸潤如附圖。此患者最可能的診斷為下列何者？","options":["(A) 蕈狀肉芽腫（mycosis fungoides）","(B) 類肉瘤（sarcoidosis）","(C) 蟹足腫（keloid）","(D) 結節性癢疹（prurigo nodularis）"],"answer":0,"image":"md4-114-1-40.jpeg"},{"id":"md4-114-1-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"114年第1次第41題","year":114,"session":1,"number":41,"question":"38歲女性病人，下肢出現病灶已有兩週（如附圖），曾服用過口服抗生素並沒有改善。來院接受皮膚切片檢查，病理結果顯示為septal panniculitis。下列敘述何者正確？","options":["(A) 此疾病常常同時伴隨血管炎的發生","(B) 此疾病病理下常常可看到許多plasma cell浸潤","(C) 此疾病最有可能是lupus panniculitis","(D) 常見的原因包括感染、藥物或免疫疾病"],"answer":3,"image":"md4-114-1-41.jpeg"},{"id":"md4-114-1-42","subject":"md4","topic":"皮膚-感染","meta":"114年第1次第42題","year":114,"session":1,"number":42,"question":"25歲女性發現雙側腋下及腹股溝出現反覆發炎疼痛之結節並有膿樣的分泌物，經診斷為化膿性汗腺炎（hidradenitis suppurativa）。下列有關化膿性汗腺炎之敘述，何者錯誤？","options":["(A) 在病灶處若有長期無法癒合的傷口，可能是鱗狀上皮細胞癌","(B) 嚴重度可用Hurley stage評估","(C) 對於嚴重度較輕之病患，首選治療為口服tetracycline或塗抹clindamycin藥膏","(D) 為細菌感染所致，故不可給與環孢素（cyclosporin）或類固醇等免疫抑制藥物"],"answer":3,"image":""},{"id":"md4-114-1-43","subject":"md4","topic":"兒科-內分泌遺傳","meta":"114年第1次第43題","year":114,"session":1,"number":43,"question":"下列何種疾病之遺傳模式是體染色體隱性遺傳（autosomal recessive）？","options":["(A) 第一型神經纖維瘤病（neurofibromatosis type I）","(B) 結節性硬化症（tuberous sclerosis）","(C) 著色性乾皮症（xeroderma pigmentosum）","(D) Peutz-Jeghers症候群（Peutz-Jeghers syndrome）"],"answer":2,"image":""},{"id":"md4-114-1-44","subject":"md4","topic":"神經-中風","meta":"114年第1次第44題","year":114,"session":1,"number":44,"question":"脊髓梗塞（spinal cord infarction）的臨床表現，下列敘述何者最不恰當？","options":["(A) 胸椎之前脊髓症候群（thoracic anterior cord syndrome）的典型症狀為雙下肢無力及本體感覺喪失，但對溫度感覺則不影響","(B) 症狀常在數分鐘到數小時內發生惡化","(C) 症狀初期常出現下肢肌腱反射喪失","(D) 在梗塞區域的皮節（dermatome）常會有疼痛感"],"answer":0,"image":""},{"id":"md4-114-1-45","subject":"md4","topic":"神經-中風","meta":"114年第1次第45題","year":114,"session":1,"number":45,"question":"血栓移除術（endovascular thrombectomy）為缺血性腦中風之重要急性治療方法，下列敘述何者錯誤？","options":["(A) 血栓移除術主要應用於大血管阻塞的急性中風病人，針對小血管阻塞的病人（lacunar infarct）並不適用","(B) 針對大血管阻塞的病人，於進行血栓移除術治療打通血管後，會再施行血栓溶解治療（thrombolytic therapy），以進一步減少遠端小血栓所造成的腦梗塞","(C) 進行血栓移除術打通血管，主要是要救回腦部半影區（penumbra）的組織","(D) 使用腦部灌流造影（perfusion scan）可幫助篩選適合接受血栓移除術的病人，腦中風於發生24小時內尚有機會接受治療"],"answer":1,"image":""},{"id":"md4-114-1-46","subject":"md4","topic":"神經-中風","meta":"114年第1次第46題","year":114,"session":1,"number":46,"question":"56歲男性，因為腦內出血（intracerebral hemorrhage）合併右側偏癱（hemiparesis）。他罹患高血壓多年，但卻從未接受治療。根據病史，最可能的病灶位置在：","options":["(A) 殼核（putamen）","(B) 前額葉（prefrontal lobe）","(C) 枕葉（occipital lobe）","(D) 小腦（cerebellum）"],"answer":0,"image":""},{"id":"md4-114-1-47","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"114年第1次第47題","year":114,"session":1,"number":47,"question":"下列何者不是預防偏頭痛發作的藥物？","options":["(A) propranolol","(B) carbamazepine","(C) topiramate","(D) onabotulinum toxin type A"],"answer":1,"image":""},{"id":"md4-114-1-48","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"114年第1次第48題","year":114,"session":1,"number":48,"question":"下列何者不是入睡抽動（hypnic jerks）常見的加重因子？","options":["(A) 睡眠不足","(B) 睡前喝水","(C) 睡前劇烈運動","(D) 情緒壓力"],"answer":1,"image":""},{"id":"md4-114-1-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"114年第1次第49題","year":114,"session":1,"number":49,"question":"對於不是重積癲癇（status epilepticus）的一般癲癇病人，下列抗癲癇藥物的使用，何者錯誤？","options":["(A) 起始治療應根據病人的癲癇種類，選取單一種最適宜的藥物","(B) 起始治療劑量應由低劑量開始，以減少急性副作用","(C) 起始治療即應達到血中高藥物濃度，以確保療效","(D) 後續藥物調整，應根據病人的反應與副作用而定"],"answer":2,"image":""},{"id":"md4-114-1-50","subject":"md4","topic":"神經-失智退化運動障礙","meta":"114年第1次第50題","year":114,"session":1,"number":50,"question":"30歲女性持柺杖至神經科門診就診，主訴近一年來走路不穩的情況愈來愈明顯，說話也變得口齒不清。身體診察發現眼動緩慢且有眼震，肢體測距不準，肌腱反射異常增強，她的父親及祖母也有類似症狀。據上描述，下列何種診斷最為可能？","options":["(A) 脊髓小腦共濟失調（spinocerebellar ataxia）","(B) 威爾森氏病（Wilson disease）","(C) 巴金森氏病（Parkinson disease）","(D) 庫賈氏病（Creutzfeldt-Jakob disease）"],"answer":0,"image":""},{"id":"md4-114-1-51","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"114年第1次第51題","year":114,"session":1,"number":51,"question":"60歲女性在唱卡拉OK後，突然開始不停的重複提問同一個問題，如「現在幾點鐘？」、「這裡是那裡？」等等。當獲得回答以後，又會馬上忘記。她可以自己走路、吃東西和洗澡，但是行為表現和平時很不一樣。10小時後，她恢復正常，但是她對於這10小時內的事情完全沒有記憶。有關此疾病，下列敘述何者最恰當？","options":["(A) 只有新發生的事情記不起來，以前的事都可以記住","(B) 後續追蹤容易發生中風","(C) 偏頭痛是此病的危險因子","(D) 腦部血流檢查可發現大腦前動脈血流灌注不良"],"answer":2,"image":""},{"id":"md4-114-1-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"114年第1次第52題","year":114,"session":1,"number":52,"question":"有關阿茲海默氏病（Alzheimer disease），下列敘述何者錯誤？","options":["(A) 是最常見的退化型失智症","(B) APP、PSEN1及PSEN2基因突變，會造成隱性遺傳","(C) 病理特徵是細胞外類澱粉斑塊與細胞內神經糾結","(D) 臨床症狀有時會出現妄想症狀"],"answer":[1,2],"image":"","answer_note":"更正:第52題答Ｂ或Ｃ或BC者均給分"},{"id":"md4-114-1-53","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"114年第1次第53題","year":114,"session":1,"number":53,"question":"有關肌萎縮性側索硬化（amyotrophic lateral sclerosis）的敘述，下列何者正確？","options":["(A) 會侵犯自律神經系統","(B) 不會侵犯感覺神經系統","(C) 不會侵犯上運動神經元","(D) 不會侵犯下運動神經元"],"answer":1,"image":""},{"id":"md4-114-1-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"114年第1次第54題","year":114,"session":1,"number":54,"question":"下列有關「吞嚥困難」的特徵，何者較少發生在中風病人，而是重症肌無力病人特有的表現？","options":["(A) 吞嚥困難對「流質食物」特別嚴重","(B) 吞嚥困難常會合併「講話不清楚（dysarthria）」","(C) 吞嚥困難常在「夜間惡化」，以致無法順利進食晚餐","(D) 吞嚥困難常會合併「流口水（drooling）」"],"answer":2,"image":""},{"id":"md4-114-1-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"114年第1次第55題","year":114,"session":1,"number":55,"question":"60歲男性主訴漸進性步態不穩6個月，合併尿失禁，神經學檢查發現膝反射和踝反射消失，感覺性共濟失調（sensory ataxia），下肢振動覺和關節本體感覺受損，瞳孔光反射異常，聚焦反射（accommodation reflex）正常，最可能的診斷為：","options":["(A) 前額葉腦中風（prefrontal lobe infarct）","(B) 中腦中風（midbrain infarct）","(C) 梅毒脊髓症（tabes dorsalis）","(D) 亞急性合併退化（subacute combined degeneration）"],"answer":2,"image":""},{"id":"md4-114-1-56","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"114年第1次第56題","year":114,"session":1,"number":56,"question":"關於腦炎的敘述，下列何者錯誤？","options":["(A) 腦炎常因病毒感染而發生，也可以是因為自體免疫的機制而發病","(B) 常見的臨床病症包括發燒、意識障礙與癲癇發作","(C) 腦脊髓液檢查中白血球的數量增加是腦炎診斷的必要條件","(D) 當病人疑似罹患病毒性腦炎時，在確定感染的病原體前，可先開始使用acyclovir治療"],"answer":2,"image":""},{"id":"md4-114-1-57","subject":"md4","topic":"神經-失智退化運動障礙","meta":"114年第1次第57題","year":114,"session":1,"number":57,"question":"45歲女性，六年前開始情緒不穩，常易怒煩躁；一年後，動作變得笨拙且容易跌倒。再過兩年，雙腿出現一些不自主、小幅度、無規律性扭動，之後持續惡化並延伸至上肢、軀幹及頭頸部。目前已無法行走，同時也出現記憶衰退。病人父親於40歲時有類似症狀，此病人最可能罹患下列何種疾病？","options":["(A) 亨丁頓氏病（Huntington disease）","(B) 額顳葉失智症（frontotemporal dementia）","(C) 威爾森氏病（Wilson disease）","(D) 第六型小腦脊髓共濟失調症（spinocerebellar ataxia type 6）"],"answer":0,"image":""},{"id":"md4-114-1-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"114年第1次第58題","year":114,"session":1,"number":58,"question":"關於急性瀰漫性腦脊髓炎（acute disseminated encephalomyelitis, ADEM）的敘述，下列何者錯誤？","options":["(A) 常發生在病毒或細菌感染後","(B) 偶爾在疫苗接種後發生","(C) 常是單一病程，不會反覆發病","(D) 較好發於成年人"],"answer":[2,3],"image":"","answer_note":"更正:第58題答Ｃ或Ｄ或CD者均給分"},{"id":"md4-114-1-59","subject":"md4","topic":"精神-精神病","meta":"114年第1次第59題","year":114,"session":1,"number":59,"question":"有關妄想症（delusional disorder）的敘述，下列何者正確？","options":["(A) 盛行率與思覺失調症相近","(B) 發病年齡早於思覺失調症","(C) 常會出現幻覺症狀，特別是聽幻覺","(D) 社會或感官的隔離是妄想症的危險因子之一"],"answer":3,"image":""},{"id":"md4-114-1-60","subject":"md4","topic":"精神-精神病","meta":"114年第1次第60題","year":114,"session":1,"number":60,"question":"有關思覺失調症（schizophrenia）的敘述，下列何者錯誤？","options":["(A) 盛行率男女相同","(B) 女性患者發病年齡通常晚於男性患者","(C) 男性患者較容易受到負性症狀（negative symptoms）影響而導致功能受損","(D) 當發病年齡晚於60歲時將被歸類為晚發性思覺失調症（late-onset schizophrenia）"],"answer":3,"image":""},{"id":"md4-114-1-61","subject":"md4","topic":"精神-精神病","meta":"114年第1次第61題","year":114,"session":1,"number":61,"question":"有關思覺失調症（schizophrenia）的敘述，下列何者錯誤？","options":["(A) 患者的生殖力（fertility rate）低於一般人口","(B) 有高比例罹患內科疾病，其中高達一半可能未被診斷","(C) 同卵雙胞胎的思覺失調症共病率（concordance rate）約為50%","(D) 父親年齡大於60歲所生產的小孩，長大後罹患思覺失調症的機會增加"],"answer":0,"image":""},{"id":"md4-114-1-62","subject":"md4","topic":"精神-精神病","meta":"114年第1次第62題","year":114,"session":1,"number":62,"question":"有關雙相情緒障礙症（bipolar disorders）之敘述，下列何者錯誤？","options":["(A) 大多數bipolar II的個案診斷後，5年內不太會轉變成bipolar I的診斷","(B) 電痙攣療法（electroconvulsive therapy﹐ECT）可使用於嚴重的躁期或鬱期治療","(C) 大約有一半的患者會只發作過一次躁症或鬱症，而不再復發","(D) 發病的平均年齡比憂鬱症早"],"answer":2,"image":""},{"id":"md4-114-1-63","subject":"md4","topic":"精神-精神官能症","meta":"114年第1次第63題","year":114,"session":1,"number":63,"question":"和壓力反應最有相關的內分泌系統，俗稱壓力賀爾蒙，下列何者為最相關？","options":["(A) 性荷爾蒙系統","(B) 腸胃系統的神經胜肽","(C) 下視丘–腦下垂體–腎上腺軸（hypothalamic-pituitary-adrenal axis）","(D) 血清素系統（serotonergic system）"],"answer":2,"image":""},{"id":"md4-114-1-64","subject":"md4","topic":"精神-精神官能症","meta":"114年第1次第64題","year":114,"session":1,"number":64,"question":"有關群纖維肌痛（fibromyalgia）症候群有關的藥物治療，下列何者最不適當？","options":["(A) narcotics是解除疼痛的首選","(B) pregabalin是適合用藥之一","(C) 抗鬱劑扮重要角色","(D) 一般止痛藥亦有效果"],"answer":0,"image":""},{"id":"md4-114-1-65","subject":"md4","topic":"精神-精神官能症","meta":"114年第1次第65題","year":114,"session":1,"number":65,"question":"關於焦慮性疾患（anxiety disorders）的描述，下列何者錯誤？","options":["(A) 包括廣泛性焦慮症、恐慌症、畏懼症等疾病","(B) 依美國流行病學研究，為盛行率最高的精神疾病","(C) 大部分焦慮性疾患發病年齡在青少年或成年早期","(D) 大部分焦慮性疾患之盛行率男性大於女性"],"answer":3,"image":""},{"id":"md4-114-1-66","subject":"md4","topic":"精神-精神官能症","meta":"114年第1次第66題","year":114,"session":1,"number":66,"question":"有關偷竊癖（kleptomania），下列何者錯誤？","options":["(A) 偷到東西後常有張力紓解感","(B) 常與情緒疾患（mood disorders）有較高比率共病（comorbidity）","(C) 女性盛行率較男性高","(D) 偷竊的行為多為計畫性，通常經過仔細規劃"],"answer":3,"image":""},{"id":"md4-114-1-67","subject":"md4","topic":"神經-失智退化運動障礙","meta":"114年第1次第67題","year":114,"session":1,"number":67,"question":"有關血管性失智症（vascular dementia）之敘述，下列何者錯誤？","options":["(A) 約占所有失智症（dementia）患者15～30%，是所有失智症患者中第二常見類型","(B) 好發年齡約在60～70歲，常見於女性","(C) 常在發病前就有高血壓及心血管疾病史","(D) 不同於阿茲海默症漸進性退化，血管性失智症多階梯式退化"],"answer":1,"image":""},{"id":"md4-114-1-68","subject":"md4","topic":"神經-失智退化運動障礙","meta":"114年第1次第68題","year":114,"session":1,"number":68,"question":"依據美國精神醫學會所出版的精神疾病診斷準則手冊第五版（DSM-5），有關認知功能的範疇（cognitive domain），下列何者錯誤？","options":["(A) 執行功能（executive function）","(B) 語言（language）","(C) 社會認知（social cognition）","(D) 定向感（orientation）"],"answer":3,"image":""},{"id":"md4-114-1-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"114年第1次第69題","year":114,"session":1,"number":69,"question":"興奮劑（stimulant）引起的精神病的症狀與處理，下列敘述何者錯誤？","options":["(A) 精神病症狀以視幻覺最常見","(B) 妄想與幻覺是興奮劑所致精神病的主要症狀","(C) 也有可能出現蟲爬感（formication or the sensation of bugs crawling beneath the skin），令個案出現搔抓行為","(D) 主要的治療是短期使用antipsychotics，例如haloperidol"],"answer":0,"image":""},{"id":"md4-114-1-70","subject":"md4","topic":"精神-器質性與物質使用","meta":"114年第1次第70題","year":114,"session":1,"number":70,"question":"某48歲工人，過去工作狀況尚可，但長期每天持續有喝烈酒習慣，某日因胰臟炎住院因此停止喝酒，3天後個案逐漸出現入睡困難、焦躁不安，甚至定向感喪失，連家人也不認識。此狀態最可能之診斷為何？","options":["(A) Wernicke's腦病變（encephalopathy）","(B) 急性震顫（tremulousness）","(C) 酒精戒斷譫妄（alcohol withdrawal delirium）","(D) 酒精性失智（alcohol-induced persistent dementia）"],"answer":2,"image":""},{"id":"md4-114-1-71","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"114年第1次第71題","year":114,"session":1,"number":71,"question":"有關自閉症類群障礙症（autism spectrum disorder）的藥物治療（psychopharmacological interventions），下列何者最正確？","options":["(A) 藥物治療主要目的是用來改善自閉症的核心症狀（例如：社會－情緒相互性、非語言的溝通行為）","(B) risperidone（抗精神病藥物的一種）已被證實可以減低自閉症的激躁（irritability）行為","(C) methylphenidate是治療注意力不足／過動症的藥物，對自閉症合併的過動症狀並不具治療效果","(D) 一些營養補充品，例如：綜合維他命、必需脂肪酸（essential fatty acid），對自閉症的的溝通行為已被證實具有療效"],"answer":1,"image":""},{"id":"md4-114-1-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"114年第1次第72題","year":114,"session":1,"number":72,"question":"侵擾性情緒失調疾患（disruptive mood dysregulation disorder, DMDD）和對立性反叛疾患（oppositional defiant disorder, ODD）之比較，下列敘述何者錯誤？","options":["(A) 兩者都會有易怒（irritability）、發脾氣（temper outbursts）及生氣（anger）","(B) 幾乎符合DMDD診斷之患者的症狀都可以符合ODD診斷要件","(C) 幾乎符合ODD診斷之患者症狀並不完全符合DMDD之診斷要件","(D) DMDD之症狀包括惱怒（annoyance）與對立（defiance），ODD之診斷要件也有這兩個症狀"],"answer":3,"image":""},{"id":"md4-114-1-73","subject":"md4","topic":"醫學倫理與法規","meta":"114年第1次第73題","year":114,"session":1,"number":73,"question":"依據我國現行精神衛生法，下列何種疾病不屬於精神疾病的範圍？","options":["(A) 反社會性人格違常","(B) 精神病","(C) 精神官能症","(D) 酒癮、藥癮"],"answer":0,"image":""},{"id":"md4-114-1-74","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"114年第1次第74題","year":114,"session":1,"number":74,"question":"53歲女性，一個月來有頭痛現象，根據所附二張MRI影像，下列何者為最可能的診斷？","options":["(A) 內頸動脈動脈瘤","(B) 腦膜瘤","(C) 多形性膠質母細胞瘤","(D) 腦下垂體腺瘤"],"answer":3,"image":"md4-114-1-74.jpeg"},{"id":"md4-114-1-75","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"114年第1次第75題","year":114,"session":1,"number":75,"question":"出生4個月大的早產兒，因小腸壞死長期使用靜脈營養注射，因雙側踝關節變形所照的X光影像如圖示，下列何者為最常見的診斷？","options":["(A) 壞血症（scurvy）","(B) 甲狀腺機能亢進（hyperthyroidism）","(C) 骨質骨髓炎（osteomyelitis）","(D) 佝僂症（rickets）"],"answer":3,"image":"md4-114-1-75.jpeg"},{"id":"md4-114-1-76","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第1次第76題","year":114,"session":1,"number":76,"question":"7歲男童因異物梗塞無法出聲時，下列處置何者最適當？","options":["(A) 如果沒看到異物，可用手指嘗試掏挖","(B) 如果沒看到異物，可用器械嘗試掏挖","(C) 如果沒看到異物，使用哈姆立克法急救","(D) 若處置過程中病童失去意識，立即實施環甲膜穿刺術（needle cricothyrodotomy）通氣"],"answer":2,"image":""},{"id":"md4-114-1-77","subject":"md4","topic":"精神-器質性與物質使用","meta":"114年第1次第77題","year":114,"session":1,"number":77,"question":"有關卡西酮（cathinone）類物質的濫用敘述，下列何者最適當？","options":["(A) 化學結構類似ketamines","(B) 會刺激正腎上腺素（norepinephrine）、多巴胺（dopamine）的釋出","(C) 會產生鎮靜安眠的作用，常被用作性侵的協助藥物","(D) 在常見濫用物質的尿液檢驗中會被當作ketamines而檢驗出來"],"answer":1,"image":""},{"id":"md4-114-1-78","subject":"md4","topic":"精神-器質性與物質使用","meta":"114年第1次第78題","year":114,"session":1,"number":78,"question":"引起老人譫妄（delirium）的藥物，下列何者最不常見？","options":["(A) atropine","(B) haloperidol","(C) lorazepam","(D) meperidine"],"answer":1,"image":""},{"id":"md4-114-1-79","subject":"md4","topic":"醫學倫理與法規","meta":"114年第1次第79題","year":114,"session":1,"number":79,"question":"滿24週之胎兒，預估體重500公克，因破水併子宮收縮，安胎無效，準備生產。胎兒父親要求放棄此胎兒，出生後不要施予急救。下列何種做法最為適當？","options":["(A) 根據優生保健法規範，告知父母不可在此時放棄","(B) 與父母親說明此週數新生兒的預後，並討論出生後處置方式","(C) 因為將來養育的責任在父母身上，應尊重父親不救治之意願","(D) 胎兒未出生係屬於母親身體自主權的範圍，母親是唯一的決定者"],"answer":1,"image":""},{"id":"md4-114-1-80","subject":"md4","topic":"醫學倫理與法規","meta":"114年第1次第80題","year":114,"session":1,"number":80,"question":"10歲的小女孩有一個罹患急性淋巴性白血病的12歲姐姐。她與姐姐HLA完全相符，因此在2年前是姐姐接受骨髓移植的最佳骨髓捐贈者。2年後姐姐白血病復發，醫師與家屬決定再拚一次骨髓移植。所以這個10歲的小女孩入院準備抽取骨髓。她卻在抽骨髓的當天早上逃離了醫院，隨後雖然找到了她，但抽取骨髓程序只好延後。下列做法何者最為適當？","options":["(A) 只要父母同意即可抽取妹妹的骨髓","(B) 告知妹妹要對姐姐有愛心，勸說她捐贈骨髓","(C) 請心理師或兒童友善醫療團隊介入，取得妹妹同意後進行","(D) 因涉及家人間之利益衝突，訴請法院裁決"],"answer":2,"image":""},{"id":"md4-114-2-1","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"114年第2次第1題","year":114,"session":2,"number":1,"question":"母親帶5個月大的寶寶來接種卡介苗，下列衛教說明，何項最不適當？","options":["(A) 提醒定期幫寶寶修剪指甲，避免抓傷注射部位","(B) 注射部位1～2週後會呈現一個小紅結節，可能會有些微痛癢","(C) 注射部位4～6週後可能會有膿瘍或潰爛，需擠壓引流出膿","(D) 注射部位平均4個月後會開始結痂，留下淡紅色的小疤痕"],"answer":2,"image":""},{"id":"md4-114-2-2","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"114年第2次第2題","year":114,"session":2,"number":2,"question":"20天大的寶寶來就診，媽媽主訴寶寶的大腿皺褶不對稱，下列相關檢查與結果的敘述，何者最不適當？","options":["(A) 做大腿外展檢查，若不對稱，則外張角度小的一側有問題","(B) 嬰兒仰躺做Galeazzi sign檢測，若膝蓋高度不對稱，較高的一側有問題","(C) 做Barlow test，測試未脫臼的髖關節於施壓後是否會產生脫臼現象","(D) 做Ortolani test，測試若有處於脫臼的髖關節能否被復位"],"answer":1,"image":""},{"id":"md4-114-2-3","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"114年第2次第3題","year":114,"session":2,"number":3,"question":"根據本國疫苗常規接種時程，對於滿1歲又15天幼兒，下列何者不是所需接種的預防針？","options":["(A) 水痘疫苗","(B) 麻疹、腮腺炎、德國麻疹混合疫苗","(C) 第一劑日本腦炎疫苗","(D) 第三劑13價肺炎鏈球菌疫苗"],"answer":2,"image":""},{"id":"md4-114-2-4","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"114年第2次第4題","year":114,"session":2,"number":4,"question":"有關新生兒indirect hyperbilirubinemia的成因中，下列何者屬於肝臟膽色素排除不足（decreased hepatic bilirubin clearance）所致？","options":["(A) ABO incompatibility","(B) hereditary spherocytosis","(C) G6PD deficiency","(D) Gilbert disease"],"answer":3,"image":""},{"id":"md4-114-2-5","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第2次第5題","year":114,"session":2,"number":5,"question":"下列關於早產兒的開放性動脈導管（patent ductus arteriosus, PDA）敘述，何者最不適當？","options":["(A) 出生週數愈小，發生機率愈高，其他PDA延後關閉的風險因子包含hypoxia、acidosis、systemic hypotension等","(B) 可能導致left ventricular volume overload及pulmonary edema","(C) 若需治療，藥物可選用prostaglandin E1（PGE1），但須注意血小板數值、是否有急性出血、腸胃道狀況及腎功能","(D) 若需surgical ligation，術後6～12小時仍需注意血壓下降的狀況"],"answer":2,"image":""},{"id":"md4-114-2-6","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第2次第6題","year":114,"session":2,"number":6,"question":"有關川崎氏症（Kawasaki disease）臨床症狀及治療的敘述，下列何者最不適當？","options":["(A) 急性期出現兩眼結膜充血或口腔黏膜變化，四肢和軀幹亦可能出現不同型態的紅疹","(B) 急性期會出現手指、腳趾脫皮現象；發病約2～3週後會出現手腳掌紅腫的現象","(C) 急性期治療，一般建議使用免疫球蛋白合併阿斯匹靈（aspirin）治療","(D) 若免疫球蛋白使用後沒有順利退燒，可考慮再使用第二輪免疫球蛋白治療"],"answer":1,"image":""},{"id":"md4-114-2-7","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第2次第7題","year":114,"session":2,"number":7,"question":"關於兒童心雜音（cardiac murmur），下列敘述何者最適當？","options":["(A) 功能性心雜音（innocent murmur）常見於學齡前兒童，特色為高頻如音樂般（musical）的3～4度收縮期心雜音","(B) 連續性心雜音（continuous murmur）常在開放性動脈導管（patent ductus arteriosus）病患身體診察時聽到","(C) 法洛氏四重症（tetralogy of Fallot）常聽到射出性收縮期心雜音（systolic ejection murmur）是源自於心室中隔缺損（ventricular septal defect）","(D) 心房中隔缺損（atrial septal defect, ASD）病患的心雜音，其來源為血流由左心房經過ASD到右心房造成的"],"answer":1,"image":""},{"id":"md4-114-2-8","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第2次第8題","year":114,"session":2,"number":8,"question":"下列引起兒童猝死原因所占的比例，何者最少？","options":["(A) QT波延長症候群（long QT syndrome）","(B) 冠狀動脈起始部位發育異常（anomalous origin of coronary artery）","(C) 肥厚性心肌病變（hypertrophic cardiomyopathy）","(D) 二尖瓣脫垂（mitral valve prolapse）"],"answer":3,"image":""},{"id":"md4-114-2-9","subject":"md4","topic":"兒科-消化系統疾病","meta":"114年第2次第9題","year":114,"session":2,"number":9,"question":"關於B型肝炎病毒，下列敘述何者最適當？","options":["(A) 母親為B型肝炎帶原者，哺餵母乳會增加新生兒感染B型肝炎病毒的機會","(B) B型肝炎病毒是雙股RNA病毒","(C) 新生兒感染B型肝炎病毒後，約有90%的機會會成為慢性B型肝炎患者","(D) 成人感染B型肝炎病毒後，約有50%的機會會成為慢性B型肝炎患者"],"answer":2,"image":""},{"id":"md4-114-2-10","subject":"md4","topic":"兒科-消化系統疾病","meta":"114年第2次第10題","year":114,"session":2,"number":10,"question":"關於肥厚性幽門狹窄（hypertrophic pyloric stenosis），下列敘述何者最適當？","options":["(A) 是一種常見造成嬰兒嘔吐的疾病，超過80%與其他先天性異常有關","(B) 典型的病例常見血中呈現低氯代謝性酸中毒","(C) 超音波檢查為最常用來診斷的工具，可以看到string sign或pseudokidney sign","(D) 外科手術（pyloromyotomy）是有效的治療方法，若不適合手術可以使用atropine"],"answer":3,"image":""},{"id":"md4-114-2-11","subject":"md4","topic":"兒科-消化系統疾病","meta":"114年第2次第11題","year":114,"session":2,"number":11,"question":"關於兒童食道異物的敘述，下列何者最不適當？","options":["(A) 好發於5歲以前的幼童，以錢幣誤食為最常見","(B) 症狀上可以無症狀、吞嚥困難或是呼吸喘來表現","(C) 若是X光無法顯影的異物，建議以鋇劑對比（barium contrast）檢查法來發現","(D) 鈕扣型電池的異物必須在2小時內儘快以內視鏡移除，避免潰瘍和日後食道狹窄後遺症"],"answer":2,"image":""},{"id":"md4-114-2-12","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"114年第2次第12題","year":114,"session":2,"number":12,"question":"學校尿液篩檢診斷了許多兒童期血尿與蛋白尿的孩童，關於其鑑別診斷，下列敘述何者最不適當？","options":["(A) 尿液鏡檢下有棘紅細胞（acanthocyte）通常代表腎絲球來源的血尿","(B) 學齡期持續性蛋白尿，大部分為腎絲球或腎小管的病變","(C) 血尿合併血塊，或血尿只發現在末段尿液者，較可能為下泌尿道所引起的原因","(D) 腎小管性蛋白尿為低分子量蛋白質（low-molecular-weight protein），而非白蛋白（albumin）"],"answer":1,"image":""},{"id":"md4-114-2-13","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"114年第2次第13題","year":114,"session":2,"number":13,"question":"8個月大男嬰因發燒住院，實驗室檢查結果如下：WBC 18600/μL，Seg 89%，Lym 10%，Mono 1%，反應性蛋5白（CRP）8.6 mg/dL，urine routine WBC＞100/HPF，尿液培養長出E. coli，colony count＞10/mL，下列 處置何者最不適當？","options":["(A) 抗生素治療要7～14天","(B) 應安排腎臟超音波檢查","(C) 立即腎臟皮質攝影（Tc-99m-DMSA renal cortical scan）是必要的檢查","(D) 根據American Academy of Pediatrics guidelines，2～24月大的病童於腎臟超音波檢查異常或反覆泌尿道感染時，應考慮voiding cystourethrogram（VCUG）檢查"],"answer":2,"image":""},{"id":"md4-114-2-14","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"114年第2次第14題","year":114,"session":2,"number":14,"question":"38歲的孕婦，在懷孕期間被診斷有羊水過少，男嬰出生後即發現有呼吸窘迫，腎臟超音波檢查發現雙側腎臟均呈現高回音（hyperechogenic），且腎臟體積均較正常新生兒大，但未見到明顯的囊泡（renal cysts）。下列何者為男嬰最可能的診斷？","options":["(A) 顯性遺傳之多囊性腎病變（autosomal dominant polycystic kidney disease）","(B) 隱性遺傳之多囊性腎病變（autosomal recessive polycystic kidney disease）","(C) 多囊性腎發育不全（multicystic dysplastic kidney）","(D) 後尿道瓣（posterior urethral valves）"],"answer":1,"image":""},{"id":"md4-114-2-15","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第2次第15題","year":114,"session":2,"number":15,"question":"關於exhaled nitric oxide（FeNO），下列敘述何者最不適當？","options":["(A) 是一種非侵入性的檢查","(B) 主要是測嗜中性血球的發炎反應","(C) 可以用來做為氣喘的輔助診斷","(D) 5歲以上病童通常可以配合檢測"],"answer":1,"image":""},{"id":"md4-114-2-16","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第2次第16題","year":114,"session":2,"number":16,"question":"造成早期兒童氣喘變成持續性氣喘（persistent asthma）的危險因子，下列何者最不適當？","options":["(A) 女性","(B) 暴露於二手菸的環境","(C) 本身有異位性皮膚炎","(D) 父母親有氣喘"],"answer":0,"image":""},{"id":"md4-114-2-17","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第2次第17題","year":114,"session":2,"number":17,"question":"4歲女童，急性腹痛和呼吸急促，呼吸異常費力且血氧下降，體溫、血壓與尿量皆正常。胸部X光片未發現發炎浸潤，血中二氧化碳濃度過高。此女童最有可能的診斷為何？","options":["(A) 急性腸胃炎","(B) 急性氣喘發作","(C) 糖尿病酮酸血症（diabetic ketoacidosis, DKA）","(D) 過敏性紫斑症（anaphylactoid purpura）"],"answer":1,"image":""},{"id":"md4-114-2-18","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"114年第2次第18題","year":114,"session":2,"number":18,"question":"關於地中海型貧血，下列敘述何者最不適當？","options":["(A) 通常會呈現小球性貧血","(B) 造血幹細胞移植可治癒重型地中海型貧血的患者","(C) 重型β型地中海型貧血患者在一出生就會表現出貧血","(D) 重型α型地中海型貧血主要是在胎兒時期會造成胎兒水腫"],"answer":2,"image":""},{"id":"md4-114-2-19","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"114年第2次第19題","year":114,"session":2,"number":19,"question":"關於兒童急性淋巴性白血病（acute lymphoblastic leukemia, ALL），下列敘述何者最適當？","options":["(A) 11～18歲的兒童發生率較0～10歲的兒童高","(B) 初診斷時，常見周邊血液抹片有芽細胞（blast cells），血液檢查會合併貧血、血小板增多","(C) 13歲男性，周邊血液抹片有芽細胞（blast cells），併有巨大縱隔腔腫塊（huge mediastinal mass），T-cell ALL是最有可能的診斷","(D) 初始治療時，若發生腫瘤溶解症候群（tumor lysis syndrome），抽血檢驗可見高尿酸、高血鉀與低血磷"],"answer":2,"image":""},{"id":"md4-114-2-20","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"114年第2次第20題","year":114,"session":2,"number":20,"question":"3歲男童為重型A型血友病（severe hemophilia A）患者，下列敘述何者最不適當？","options":["(A) 為性聯遺傳","(B) 若有出血，常以關節或肌肉出血來表現","(C) 有出血時才需注射凝血因子，以免頻繁的注射，反而造成需要注射的時候無效","(D) 若男童遭遇危及生命的出血，需設法將凝血因子活性輸至100%"],"answer":2,"image":""},{"id":"md4-114-2-21","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第2次第21題","year":114,"session":2,"number":21,"question":"3歲女童，發燒4天，精神活力差，血壓60/30 mmHg，血氧飽和濃度95%，心跳每分鐘160下，呼吸每分鐘50次。有關初期休克治療目標，下列何者最適當？2","options":["(A) 心輸出量指數（cardiac index）在1～3 L/min/m","(B) 血壓上升到70/40 mmHg","(C) 中央靜脈血氧濃度≧70%","(D) 尿量在0.1～0.5 mL/kg/hr"],"answer":2,"image":""},{"id":"md4-114-2-22","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第2次第22題","year":114,"session":2,"number":22,"question":"之前健康情形良好的3個月男嬰兩天前開始鼻塞、流鼻水及輕微發燒，目前呼吸喘且費力。呼吸速率每分鐘75次，心跳每分鐘110下，體溫38.1℃，身體診察雙側吐氣期有wheezing、吸氣期無濕囉音（crackles）。下列何者為最可能的診斷？","options":["(A) 嚴重氣喘發作","(B) 細菌性肺炎","(C) 病毒性細支氣管炎","(D) 先天性心臟病"],"answer":2,"image":""},{"id":"md4-114-2-23","subject":"md4","topic":"兒科-內分泌遺傳","meta":"114年第2次第23題","year":114,"session":2,"number":23,"question":"關於先天性甲狀腺低能症（congenital hypothyroidism），下列敘述何者最不適當？","options":["(A) 成因可能為甲狀腺發育不良（thyroid dysgenesis）","(B) 早期診斷及治療對於孩子腦部及生長發育至關重要，尤其是3歲以前","(C) 臺灣目前的新生兒篩檢，是採集新生兒的足跟血檢驗甲狀腺素（T4）","(D) 一般建議levothyroxine的治療劑量為10～15 μg/kg/day"],"answer":2,"image":""},{"id":"md4-114-2-24","subject":"md4","topic":"兒科-內分泌遺傳","meta":"114年第2次第24題","year":114,"session":2,"number":24,"question":"下列何種疾病最不可能造成男孩性促素非依賴型性早熟（gonadotropin-independent precocious puberty）？","options":["(A) 下視丘錯構瘤（hypothalamic hamartoma）","(B) 分泌人類絨毛膜促性腺激素的腫瘤（human chorionic gonadotropin-secreting tumor）","(C) 先天性腎上腺增生症（congenital adrenal hyperplasia）","(D) 家族性男性性早熟（familial male precocious puberty）"],"answer":0,"image":""},{"id":"md4-114-2-25","subject":"md4","topic":"兒科-內分泌遺傳","meta":"114年第2次第25題","year":114,"session":2,"number":25,"question":"有關典型21-羥酶缺乏（classic 21-hydroxylase deficiency）所導致先天性腎上腺增生（congenital adrenal hyperplasia）的病人，下列敘述何者最不適當？","options":["(A) 單純雄性化型（simple virilizing form）比失鹽型（salt-wasting form）發生率高","(B) 位於第六對染色體短臂的CYP21基因突變所致","(C) 大多數突變為CYP21基因與pseudogene CYP21P間的重組（recombination）所致","(D) 未及時治療，失鹽型（salt-wasting form）患者可能於出生後數週內因休克死亡"],"answer":0,"image":""},{"id":"md4-114-2-26","subject":"md4","topic":"皮膚-感染","meta":"114年第2次第26題","year":114,"session":2,"number":26,"question":"2歲男童發燒5天，嘴唇及臉部出現許多紅疹及結痂（如圖示），經檢查發現牙齦處也有紅腫流血，身體其他部位則無疹子。最可能的致病原為何？","options":["(A) enterovirus","(B) herpes simplex virus","(C) varicella-zoster virus","(D) Epstein-Barr virus"],"answer":1,"image":"md4-114-2-26.jpeg"},{"id":"md4-114-2-27","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第2次第27題","year":114,"session":2,"number":27,"question":"有關嬰幼兒急性細支氣管炎（acute bronchiolitis）之敘述，下列何者最不適當？","options":["(A) 呼吸道融合病毒（RSV）是最常見引起急性細支氣管炎的病毒","(B) 鼻病毒（rhinovirus）可引起急性細支氣管炎","(C) 病毒性細支氣管炎常會同時伴隨細菌性感染（bacterial superinfection）","(D) 高風險族群可以施打呼吸道融合病毒（RSV）被動免疫單株抗體，以預防重症3"],"answer":2,"image":""},{"id":"md4-114-2-28","subject":"md4","topic":"兒科-感染神經","meta":"114年第2次第28題","year":114,"session":2,"number":28,"question":"10個月大的男嬰，高燒3天，無明顯呼吸道及腸胃道症狀，血液檢查顯示血中白血球數為6,800/mm，中性3球45%，淋巴球48%，單核球7%，血色素（hemoglobin）值為10.8 g/dL，血小板數為350,000/mm，C-反應蛋白（C-reactive protein）數值為0.5 mg/dL，尿液分析顯示尿蛋白30 mg/dL，WBC 3～5/HPF，RBC 0～ 2/HPF，下列的診斷何者最有可能？","options":["(A) 嬰兒玫瑰疹（roseola infantum）","(B) 急性腎盂腎炎（acute pyelonephritis）","(C) 德國麻疹（rubella）","(D) 川崎氏症（Kawasaki disease）"],"answer":0,"image":""},{"id":"md4-114-2-29","subject":"md4","topic":"兒科-感染神經","meta":"114年第2次第29題","year":114,"session":2,"number":29,"question":"因核黃疸（kernicterus）造成的腦性麻痺，最常為下列何者？","options":["(A) spastic hemiplegia","(B) spastic diplegia","(C) spastic quadriplegia","(D) athetoid cerebral palsy"],"answer":3,"image":""},{"id":"md4-114-2-30","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"114年第2次第30題","year":114,"session":2,"number":30,"question":"關於注意力不集中過動症（attention-deficit/hyperactivity disorder, ADHD）的敘述，下列何者最不適當？","options":["(A) 母親懷孕過程中使用非法藥物或喝酒過量可能為致病危險因子之一","(B) 有癲癇、神經皮膚症候群的兒童中有較高機率發生ADHD共病症","(C) 兒童是否有ADHD跟基因並沒有關聯","(D) ADHD的核心症狀為注意力不集中、過動及衝動控制不佳，學童盛行率約為5～10%"],"answer":2,"image":""},{"id":"md4-114-2-31","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"114年第2次第31題","year":114,"session":2,"number":31,"question":"第一次發作之多發性硬化症（multiple sclerosis, MS）與急性瀰漫性腦脊髓炎（acute disseminated encephalomyelitis, ADEM）之鑑別診斷，下列何者最不適當？","options":["(A) 多發性硬化症較常發生於10歲以上","(B) 多發性硬化症病人較常有單側之視神經炎","(C) 多發性硬化症病人較少出現癲癇","(D) 視丘、基底核之MRI變化較常出現於多發性硬化症病人"],"answer":3,"image":""},{"id":"md4-114-2-32","subject":"md4","topic":"兒科-心血管呼吸","meta":"114年第2次第32題","year":114,"session":2,"number":32,"question":"3歲女童因為呼吸喘來兒童急診，下列合併的臨床特徵或病史中，何者不是發展至呼吸衰竭的高風險病況？","options":["(A) 吞了一顆鈕扣電池","(B) 有氣切管的患者","(C) 在家有短暫發紺，到院血氧都正常","(D) 吞了一顆磁鐵，目前無呼吸窘迫表現"],"answer":3,"image":""},{"id":"md4-114-2-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"114年第2次第33題","year":114,"session":2,"number":33,"question":"若一位唐氏症患者其染色體檢查結果為父母其中一位為21;21轉位帶因者（translocation (21;21) carrier）導致，則此對父母再生出活產新生兒為唐氏症的機率為何？","options":["(A) 5～7%","(B) 25%","(C) 50%","(D) 100%"],"answer":3,"image":""},{"id":"md4-114-2-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"114年第2次第34題","year":114,"session":2,"number":34,"question":"下列何者不適合用在異位性皮膚炎（atopic dermatitis）的治療？","options":["(A) 免疫抑制劑（immunosuppressants）","(B) 長期口服類固醇（long term oral corticosteroid）","(C) 外用類固醇（topical corticosteroid）","(D) 窄波紫外線B光（narrow band UVB）"],"answer":1,"image":""},{"id":"md4-114-2-35","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"114年第2次第35題","year":114,"session":2,"number":35,"question":"下列何種病理特徵最不會在乾癬病灶中表現？","options":["(A) 角質層出現嗜中性球（neutrophils in corneal layer）","(B) 表皮層出現規則棘狀增生（regular acanthosis）","(C) 表皮下出現水疱（subepidermal blisters）","(D) 真皮層出現增加的單核球（mononuclear cells）"],"answer":2,"image":""},{"id":"md4-114-2-36","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"114年第2次第36題","year":114,"session":2,"number":36,"question":"關於結節性癢疹（prurigo nodularis）及慢性單純性苔癬（lichen simplex chronicus）的敘述，下列何者錯誤？","options":["(A) 四肢伸側是好發的部位","(B) 通常會有難以控制的劇癢症狀","(C) 誘發原因主要是癢，進而慢性地摩擦搔抓所致","(D) 此二疾病若發生在異位性皮膚炎的患者，通常年紀較長"],"answer":3,"image":""},{"id":"md4-114-2-37","subject":"md4","topic":"皮膚-感染","meta":"114年第2次第37題","year":114,"session":2,"number":37,"question":"Imiquimod用於治療尖圭濕疣（condyloma acuminatum）的主要機轉為：","options":["(A) 去角化作用","(B) 直接毒殺病毒","(C) 抑制病毒複製","(D) 增強宿主免疫反應"],"answer":3,"image":""},{"id":"md4-114-2-38","subject":"md4","topic":"皮膚-感染","meta":"114年第2次第38題","year":114,"session":2,"number":38,"question":"49歲男性，三天前右下腰部有刺痛感，開始使用痠痛藥布，就診時發現該處出現數顆小水疱及紅色丘疹，伴隨輕微癢感，下列敘述何者正確？","options":["(A) 需做Tzanck smear，正確做法為取水疱內澄清液體去做染色","(B) Tzanck smear出現多核巨細胞並無法辨別是單純性疱疹（herpes simplex）或是帶狀疱疹（herpes zoster）","(C) 如果病患沒有神經痛或搔癢，就可以排除帶狀疱疹（herpes zoster）","(D) 此病患否認小時候有得過水痘，一定不可能是帶狀疱疹"],"answer":1,"image":""},{"id":"md4-114-2-39","subject":"md4","topic":"皮膚-腫瘤","meta":"114年第2次第39題","year":114,"session":2,"number":39,"question":"一位皮膚多發性神經纖維瘤（neurofibromatosis）的病患，臨床上看到皮膚有許多摸起來很軟且大小不一的皮膚腫瘤，甚至在皮膚腫瘤的表皮上輕壓時，觸診的指頭可以感覺凹陷進皮膚內。上述的臨床特性稱為下列何者？","options":["(A) Apple-jelly sign","(B) Buttonhole sign","(C) Auspitz sign","(D) Nikolsky sign"],"answer":1,"image":"md4-114-2-39.jpeg"},{"id":"md4-114-2-40","subject":"md4","topic":"皮膚-腫瘤","meta":"114年第2次第40題","year":114,"session":2,"number":40,"question":"89歲的老先生，過去兩年來頭皮上陸續出現多個類似瘀傷的斑塊（如圖所示），最近病灶出現疼痛的症狀，因此求診並接受皮膚切片手術。病理圖像如附圖（H&E stain, 400X）。下列何者為最可能的診斷？","options":["(A) 基底細胞癌（basal cell carcinoma）","(B) 血管肉瘤（angiosarcoma）","(C) 皮脂腺癌（sebaceous carcinoma）","(D) 鱗狀細胞癌（squamous cell carcinoma）"],"answer":1,"image":"md4-114-2-40.jpeg"},{"id":"md4-114-2-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"114年第2次第41題","year":114,"session":2,"number":41,"question":"55歲男性病人，後頸部出現腫塊已經數個月了。病理切片顯示pandermal thickening with broad collagen bundles separated by mucin deposits。下列何者是此皮膚症狀較可能合併的疾病？","options":["(A) 糖尿病","(B) 甲狀腺功能低下","(C) 貧血","(D) 尿毒症"],"answer":0,"image":"md4-114-2-41.jpeg"},{"id":"md4-114-2-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"114年第2次第42題","year":114,"session":2,"number":42,"question":"下列有關白斑（vitiligo）之敘述，何者錯誤？","options":["(A) 約20%病患會合併自體免疫疾病，其中最常見的為自體免疫甲狀腺疾病","(B) 主要成因為黑色素細胞（melanocyte）功能下降，黑色素（melanin）製造減少所致","(C) 活性期可見Koebner phenomenon","(D) 伍氏燈（Wood lamp）為一種紫外光，照射於皮膚後可以讓病灶與正常皮膚色差更加明顯，協助診斷白斑"],"answer":1,"image":""},{"id":"md4-114-2-43","subject":"md4","topic":"皮膚-腫瘤","meta":"114年第2次第43題","year":114,"session":2,"number":43,"question":"發生於黏膜部位的神經瘤（mucosal neuromas）常見於下列何者？","options":["(A) 史特基–韋伯氏症候群（Sturge-Weber syndrome）","(B) 多發性內分泌腫瘤，第IIb型（multiple endocrine neoplasia, type IIb）","(C) Gardner症候群（Gardner syndrome）","(D) Gorlin症候群（Gorlin syndrome）"],"answer":1,"image":""},{"id":"md4-114-2-44","subject":"md4","topic":"神經-中風","meta":"114年第2次第44題","year":114,"session":2,"number":44,"question":"前脈絡叢動脈（anterior choroidal artery）阻塞造成的缺血性腦中風，下列何者是最不常見的臨床症狀？","options":["(A) 半邊視野缺損（hemianopia）","(B) 半邊肢體無力（hemiplegia）","(C) 感覺功能下降（hypesthesia）","(D) 半邊忽略（hemineglect）"],"answer":3,"image":""},{"id":"md4-114-2-45","subject":"md4","topic":"神經-中風","meta":"114年第2次第45題","year":114,"session":2,"number":45,"question":"基底動脈頂端阻塞（top of the basilar artery occlusion）影響較少的結構為：","options":["(A) 中腦（midbrain）","(B) 橋腦（pons）","(C) 視丘（thalamus）","(D) 枕葉（occipital lobe）"],"answer":1,"image":""},{"id":"md4-114-2-46","subject":"md4","topic":"神經-中風","meta":"114年第2次第46題","year":114,"session":2,"number":46,"question":"67歲男性病人，被家人發現突然無法言語及右側肢體無力，之後意識逐漸昏迷，其腦部電腦斷層掃描如下，針對此病人所做的降腦壓治療，何者最不適當？","options":["(A) 將病床頭側抬高20～30度","(B) 高滲透壓製劑治療","(C) 類固醇治療","(D) 過度換氣法（hyperventilation）治療"],"answer":2,"image":"md4-114-2-46.jpeg"},{"id":"md4-114-2-47","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"114年第2次第47題","year":114,"session":2,"number":47,"question":"34歲女性，左側眼窩內頭痛，有時會延伸到左側額顳區，每次發作約2～45分鐘，一天發作至少5次以上，發作時伴隨左側流眼淚和流鼻水並會干擾她的日常生活。頭痛3天內會自動緩解，神經影像學檢查正常。下列何種藥物對她特別有療效？","options":["(A) verapamil","(B) carbamazepine","(C) acetaminophen","(D) indomethacin"],"answer":3,"image":""},{"id":"md4-114-2-48","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"114年第2次第48題","year":114,"session":2,"number":48,"question":"26歲女性，兩年來晚上睡眠中會突然出現臉部表情驚恐，四肢亂動，約持續20秒後結束。發作後意識清楚，能正確對答，每次發作的表現都一樣。最近三個月幾乎每晚發作5次以上，且都是叢發性（cluster）發作，白天午睡時偶爾也會發作，清醒時則完全正常，最可能的診斷為下列何者？","options":["(A) 恐慌症（panic disorder）","(B) 異睡症（parasomnia）","(C) 額葉癲癇（frontal lobe epilepsy）","(D) 顳葉癲癇（temporal lobe epilepsy）"],"answer":2,"image":""},{"id":"md4-114-2-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"114年第2次第49題","year":114,"session":2,"number":49,"question":"針對生育年齡婦女的癲癇治療，在致畸胎特性上，應最優先考慮下列那一種藥品？","options":["(A) valproate","(B) topiramate","(C) lamotrigine","(D) phenytoin"],"answer":2,"image":""},{"id":"md4-114-2-50","subject":"md4","topic":"神經-失智退化運動障礙","meta":"114年第2次第50題","year":114,"session":2,"number":50,"question":"有關失智症的敘述，下列何者錯誤？","options":["(A) 低教育程度是失智症的危險因子","(B) 類澱粉斑塊是由類澱粉蛋白先驅物（amyloid precursor protein）經由單一酵素裁切而成","(C) 唐氏症的腦部病理表現與阿茲海默氏病類似","(D) 額顳葉失智症常見的亞型是行為亞型（behavioral variant）"],"answer":1,"image":""},{"id":"md4-114-2-51","subject":"md4","topic":"神經-失智退化運動障礙","meta":"114年第2次第51題","year":114,"session":2,"number":51,"question":"53歲男性至神經科門診就診，主訴近一年來動作遲緩、僵硬，頭部總是向後仰，眼睛轉動緩慢，無法自主性往下看，且家人觀察到他最近時常往後跌倒。依此描述，下列何種診斷最為可能？","options":["(A) 巴金森氏病（Parkinson disease）","(B) 多重系統萎縮症（multiple system atrophy）","(C) 進行性上眼神經核麻痺症（progressive supranuclear palsy）","(D) 路易氏體失智症（dementia with Lewy bodies）"],"answer":2,"image":""},{"id":"md4-114-2-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"114年第2次第52題","year":114,"session":2,"number":52,"question":"關於肢體僵硬（rigidity）的敘述，下列何者最正確？","options":["(A) 在搬動肢體關節檢查時，出現的阻力與檢查速度無關（velocity-independent）","(B) 在搬動肢體關節檢查時，會出現類似折疊刀（clasp-knife）的阻力","(C) 對上肢屈肌（flexors）之影響比伸肌（extensors）嚴重","(D) 在搬動肢體關節檢查時，方向突然改變，阻力會延後出現"],"answer":0,"image":""},{"id":"md4-114-2-53","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"114年第2次第53題","year":114,"session":2,"number":53,"question":"下列會引起肌肉萎縮的疾病中，那一個會同時有肌腱反射上升的現象？","options":["(A) 肌萎縮性側索硬化（amyotrophic lateral sclerosis）","(B) 小兒麻痺（poliomyelitis）","(C) 重症肌無力（myasthenia gravis）","(D) 多發性肌炎（polymyositis）"],"answer":0,"image":""},{"id":"md4-114-2-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"114年第2次第54題","year":114,"session":2,"number":54,"question":"68歲男性，上週出現發燒腹瀉，這幾天突然出現排尿困難及全身無力送來急診。神經學檢查顯示意識正常，雙頰作臉部表情困難，四肢力氣差（肌力3分），四肢末端有輕微麻木感及振動感覺下降，肌腱反射消失。下列敘述何者正確？","options":["(A) 神經電氣學檢查如果沒看到神經傳導變慢或傳導阻滯（conduction block）就可以排除格林–巴利症候群（Guillain-Barré syndrome）","(B) 使用類固醇（corticosteroid）治療無法縮短病程或影響預後","(C) 腦脊髓液檢查時白血球（white blood cell）至少＞10 cells/μL","(D) 臨床症狀急速惡化下，血漿分離／交換（plasmapheresis/plasma exchange）比靜脈免疫球蛋白注射（intravenous immunoglobulin）為更合適的治療方式"],"answer":1,"image":""},{"id":"md4-114-2-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"114年第2次第55題","year":114,"session":2,"number":55,"question":"60歲女性車禍後出現頸部疼痛，雙側上肢肌肉力量3分，雙側下肢肌肉力量4分，雙上肢及上身溫痛覺消失，關節體位感覺（joint position）仍存在，其最可能診斷為何？","options":["(A) 頸椎第五節（C5）脊髓休克","(B) 頸椎第五節（C5）後脊髓損傷","(C) 頸椎第五節（C5）中央脊髓症候群","(D) 頸椎第五節（C5）Brown-Séquard症候群"],"answer":2,"image":""},{"id":"md4-114-2-56","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"114年第2次第56題","year":114,"session":2,"number":56,"question":"關於腦膿瘍（brain abscess）的敘述，下列何者錯誤？","options":["(A) 並非所有病人在診斷時都會有發燒的現象","(B) 病人應儘早進行腦脊髓液檢查，以確定病原菌","(C) 關於後顱窩腦膿瘍的診斷，磁振造影比電腦斷層攝影更靈敏","(D) 利用立體定位（stereotactic guidance）方式來進行腦膿瘍的抽取與引流（aspiration and drainage）有助於腦膿瘍的診斷與治療"],"answer":1,"image":""},{"id":"md4-114-2-57","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"114年第2次第57題","year":114,"session":2,"number":57,"question":"關於中樞神經系統惡性腫瘤轉移的敘述，下列何者最不恰當？","options":["(A) 最常發生腦轉移的惡性腫瘤是肺癌與乳癌","(B) 最常發生腦膜轉移（leptomeningeal metastases）的惡性腫瘤是淋巴癌","(C) 攝護腺癌與乳癌易轉移至硬腦膜（dura）","(D) 腦部最常發生腫瘤轉移的部位是灰白質交界"],"answer":1,"image":""},{"id":"md4-114-2-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"114年第2次第58題","year":114,"session":2,"number":58,"question":"下列何者不是視神經脊髓炎（neuromyelitis optica spectrum disorder）的核心臨床病症（core clinical characteristics）？","options":["(A) 最後區症候群（area postrema syndrome）","(B) 失語症（aphasia）","(C) 視神經炎（optic neuritis）","(D) 急性脊髓炎（acute myelitis）"],"answer":1,"image":""},{"id":"md4-114-2-59","subject":"md4","topic":"精神-精神官能症","meta":"114年第2次第59題","year":114,"session":2,"number":59,"question":"有關情緒障礙症（mood disorders）之敘述，下列何者正確？","options":["(A) 憂鬱症及雙相情緒障礙症都是在低社經地位階層發生率較高","(B) 雙相情緒障礙症的發病年齡較重鬱症早","(C) 雙相情緒障礙症的診斷必須躁期及鬱期都出現過","(D) 雙相情緒障礙症患者的性別比率以女性較男性多"],"answer":1,"image":""},{"id":"md4-114-2-60","subject":"md4","topic":"精神-精神病","meta":"114年第2次第60題","year":114,"session":2,"number":60,"question":"下列何者不是符合思覺失調症（schizophrenia）的DSM-5診斷準則（diagnostic criteria）症狀？","options":["(A) 幻覺（hallucinations）或妄想（delusions）","(B) 負性症狀（negative symptoms）","(C) 混亂無組織的言語或行為（disorganized speech or behaviors）","(D) 定向感異常（disorientation）"],"answer":3,"image":""},{"id":"md4-114-2-61","subject":"md4","topic":"精神-精神病","meta":"114年第2次第61題","year":114,"session":2,"number":61,"question":"下列何者為思覺失調症（schizophrenia）預後較差的因子？","options":["(A) 晚發","(B) 女性","(C) 明顯誘發因子","(D) 明顯的思考貧乏及社交退縮"],"answer":3,"image":""},{"id":"md4-114-2-62","subject":"md4","topic":"精神-器質性與物質使用","meta":"114年第2次第62題","year":114,"session":2,"number":62,"question":"有關慢性阻塞性肺病與精神疾病的關聯性，下列何者錯誤？","options":["(A) 共病恐慌症的比率不會比一般人高","(B) 睡眠障礙與一些內科疾病有關，包含慢性阻塞性肺病","(C) 共病焦慮症的比率較一般人高","(D) 病人如果發生服藥過量，例如alpha-2 agonists過量時，可能會引起焦慮、顫抖等症狀"],"answer":0,"image":""},{"id":"md4-114-2-63","subject":"md4","topic":"精神-精神官能症","meta":"114年第2次第63題","year":114,"session":2,"number":63,"question":"關於benzodiazepine（BZD）類藥物的敘述，下列何者錯誤？","options":["(A) 除了抗焦慮及協助睡眠作用之外，也有抗癲癇的作用","(B) 與ω receptor結合後，經由GABA complex發生作用","(C) 安全性高，並非管制藥品","(D) 是用在酒癮戒斷治療的第一線治療"],"answer":2,"image":""},{"id":"md4-114-2-64","subject":"md4","topic":"精神-精神官能症","meta":"114年第2次第64題","year":114,"session":2,"number":64,"question":"有關憂鬱症之敘述，下列何者錯誤？","options":["(A) 發炎理論可以用來解釋憂鬱症和心血管疾病、代謝疾病及癌症的高度共病性","(B) 急性壓力事件本身會造成cortisol及glucocorticoid的缺乏，進一步影響到大腦功能（例如hippocampus）","(C) 患者可能較高比例的快速動眼期睡眠（rapid eye movement sleep）和前額葉（prefrontal cortex）的功能低下","(D) 患者之大腦功能異常可透過藥物或心理治療矯正"],"answer":1,"image":""},{"id":"md4-114-2-65","subject":"md4","topic":"精神-精神官能症","meta":"114年第2次第65題","year":114,"session":2,"number":65,"question":"精神科所使用的生理回饋（biofeedback）治療是應用下列那個原理？","options":["(A) 操作型制約（operant conditioning）","(B) 古典制約（classical conditioning）","(C) 系統減敏感法（systematic desensitization）","(D) 洪水法（flooding）"],"answer":0,"image":""},{"id":"md4-114-2-66","subject":"md4","topic":"精神-精神官能症","meta":"114年第2次第66題","year":114,"session":2,"number":66,"question":"對於強迫症之敘述，下列何者錯誤？","options":["(A) 以反覆出現強迫想法或動作為主要表現之障礙","(B) 患者覺得此強迫想法或動作合理，但卻努力抗拒","(C) 可能會單獨存在強迫想法","(D) 大部分患者於25歲以前發作"],"answer":1,"image":""},{"id":"md4-114-2-67","subject":"md4","topic":"神經-失智退化運動障礙","meta":"114年第2次第67題","year":114,"session":2,"number":67,"question":"有關阿茲海默症（Alzheimer's disease）之敘述，下列何者錯誤？","options":["(A) 是所有失智症（dementia）患者中最常見的一種失智類型","(B) 雖病因仍未完全了解，但腦神經系統中出現大量類澱粉蛋白（amyloid）沉積物是此疾病的一大特點","(C) 研究指出約有90%有阿茲海默症患者具家族史","(D) 常被提及的腦神經傳遞物質之病理生理（pathophysiological）變化，是乙醯膽鹼（acetylcholine）及正腎上腺素（norepinephrine）流失或活性降低"],"answer":2,"image":""},{"id":"md4-114-2-68","subject":"md4","topic":"精神-器質性與物質使用","meta":"114年第2次第68題","year":114,"session":2,"number":68,"question":"鎮靜安眠用藥不當使用，容易出現濫用或成癮問題，下列敘述何者錯誤？","options":["(A) benzodiazepine中毒可能會造成敵意或攻擊行為，特別是併用酒精時","(B) 戒斷症狀的表現上，長效型（long-acting）benzodiazepines比短效型（short-acting）嚴重","(C) 停止使用鎮靜安眠用藥，不宜過快，避免反彈性焦慮或嚴重失眠","(D) 長期不當使用鎮靜安眠用藥會造成記憶力退化，也會提升譫妄（delirium）與精神病癥（psychotic symptoms）的風險"],"answer":1,"image":""},{"id":"md4-114-2-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"114年第2次第69題","year":114,"session":2,"number":69,"question":"有關譫妄（delirium）相關的前置因子（predisposing factor）之敘述，下列何者錯誤？","options":["(A) 增加食慾","(B) 老年人","(C) 患有認知障礙（major neurocognitive impairment）","(D) 知覺障礙（失明／失聰）"],"answer":0,"image":""},{"id":"md4-114-2-70","subject":"md4","topic":"精神-器質性與物質使用","meta":"114年第2次第70題","year":114,"session":2,"number":70,"question":"某55歲事業成功應酬飯局很多的商人，長期每天有喝烈酒習慣，某日因急性胃腸炎住院而停止喝酒，4天後商人逐漸出現難以入睡、煩躁不安，意識有點不清楚，連家人也不認識。有關對此商人之臨床描述與處置，下列何者最不適當？","options":["(A) 首先考慮給與苯二氮平（benzodiazepine）","(B) 為保護個案不因躁動而跌倒，必要時可進行短期之身體約束，但須密切觀察","(C) 服用propranolol可降低交感神經的過度活躍（sympathetic hyperactivity）","(D) 若此個案發生癲癇時，癲癇之型態最常為小發作"],"answer":3,"image":""},{"id":"md4-114-2-71","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"114年第2次第71題","year":114,"session":2,"number":71,"question":"有關自閉症類群障礙症（autism spectrum disorder, ASD）的共病或鑑別診斷，下列何者最正確？","options":["(A) 精神疾病共病（comorbid mental disorders）並不常見，大約少於10%有精神疾病共病","(B) 大約僅有4%的個案有兩個或以上的精神疾病共病（comorbid mental disorders）","(C) 與選擇型不語症（selective mutism）的鑑別，主要在於ASD患者，在熟悉的人或情境下語言溝通正常，但在某些情境下卻沉默不語","(D) 如果個案同時符合ASD與注意力不足／過動症的診斷標準，可以同時給予兩個診斷"],"answer":3,"image":""},{"id":"md4-114-2-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"114年第2次第72題","year":114,"session":2,"number":72,"question":"有關兒童青少年憂鬱症診斷之敘述，下列何者錯誤？","options":["(A) 常表現出坐立難安（restlessness），有時被誤認為注意力不足過動症候群","(B) 會因疲累或失去活力，早上抗拒起床去上學、白天嗜眠","(C) 由於其認知功能尚未發展完全，所以無須評估是否有無價值感或罪惡感","(D) 常抱怨反應變慢、專注力不佳或不自主做白日夢"],"answer":2,"image":""},{"id":"md4-114-2-73","subject":"md4","topic":"醫學倫理與法規","meta":"114年第2次第73題","year":114,"session":2,"number":73,"question":"有關對病人進行約束的適當時機或情況（indications），下列敘述何者錯誤？","options":["(A) 防止對治療計畫或物理性環境造成重大干擾","(B) 基於病人的自願合理要求","(C) 為了減少過度的感覺刺激","(D) 作為進行中行為治療的一部分"],"answer":2,"image":""},{"id":"md4-114-2-74","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"114年第2次第74題","year":114,"session":2,"number":74,"question":"關於腦膜瘤（meningioma）的影像特徵，下列敘述何者錯誤？","options":["(A) 腫瘤通常會貼著硬腦膜生長","(B) 腫瘤包圍大血管時通常不會造成血管狹窄","(C) 腫瘤細胞有可能會侵犯附近的骨頭","(D) 打完顯影劑以後通常有很好的顯影加強現象"],"answer":1,"image":""},{"id":"md4-114-2-75","subject":"md4","topic":"神經-中風","meta":"114年第2次第75題","year":114,"session":2,"number":75,"question":"50歲女性患者，近期因急性心臟衰竭而昏迷，接受電腦斷層檢查，圖為注射顯影劑後的影像，下列何者是最可能的診斷？","options":["(A) 瀰漫性腦炎（diffuse encephalitis）","(B) 肝性腦病變（hepatic encephalopathy）","(C) Wernicke氏腦病變（Wernicke's encephalopathy）","(D) 缺氧缺血性腦病變（hypoxic ischemic encephalopathy）"],"answer":3,"image":"md4-114-2-75.jpeg"},{"id":"md4-114-2-76","subject":"md4","topic":"神經-失智退化運動障礙","meta":"114年第2次第76題","year":114,"session":2,"number":76,"question":"75歲男性有失智症（dementia）及高血壓病史，因為晚上不睡覺，白天容易情緒躁動，由照顧他的外傭送到急診，下列敘述何者最不適當？","options":["(A) 失智症病人經常會出現行為障礙，尤其是照顧者感到不堪負荷時，容易成為急診就診的常見原因","(B) 評估病人的第一步應該先確認是否有譫妄（delirium）情形，並且鑑別診斷是否合併有其他身體疾病","(C) 失智症病人工作及社交能力下降","(D) 病人躁動吵鬧要下床解尿，建議給予適當約束，並且應該放置導尿管以避免在廁所發生事故"],"answer":3,"image":""},{"id":"md4-114-2-77","subject":"md4","topic":"醫學倫理與法規","meta":"114年第2次第77題","year":114,"session":2,"number":77,"question":"兒童身體虐待的表現，下列那一項最常被忽視？","options":["(A) 瘀傷","(B) 骨折","(C) 燙傷","(D) 頭部外傷"],"answer":0,"image":""},{"id":"md4-114-2-78","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"114年第2次第78題","year":114,"session":2,"number":78,"question":"急診常見的皮膚過敏性反應，下列敘述何者錯誤？","options":["(A) 蕁麻疹皮膚病灶表現為邊緣容易界定的皮疹，常帶有極度搔癢感","(B) 血管水腫的反應與蕁麻疹類似，但影響深及真皮層","(C) 如曾經使用過Penicillin無過敏反應，再度使用時不會產生致死性的過敏性反應","(D) 針劑比口服的Penicillin更容易產生嚴重致死的過敏反應"],"answer":2,"image":""},{"id":"md4-114-2-79","subject":"md4","topic":"醫學倫理與法規","meta":"114年第2次第79題","year":114,"session":2,"number":79,"question":"一位思覺失調症的病人，近期因服藥遵囑性不佳，出現明顯被害妄想，認為自己的氣喘是隔壁住戶長期施放毒氣殘害自己所造成，於就診時向治療氣喘的內科醫師表示：「想要報復對方」。下列何種臨床處理方式最不恰當？","options":["(A) 耐心地說服病人氣喘與鄰居無關，並鼓勵持續接受氣喘與思覺失調症的治療，並試著釐清「想要報復對方」的意思","(B) 有技巧地釐清所謂「想要報復對方」的細節，不論該報復方法是否會造成傷害，應儘可能取得病人同意，轉告其精神科醫師","(C) 基於醫療人員的「守密」義務，不得將病人的病情與意圖告知任何人，如此方能維繫醫病間的信賴，有助治療成效","(D) 當醫師判斷病人報復對方的可能性與傷害性極高，應立即請警衛協助留置病人，通知家屬，並聯絡精神科醫師協助後續處置"],"answer":2,"image":""},{"id":"md4-114-2-80","subject":"md4","topic":"醫學倫理與法規","meta":"114年第2次第80題","year":114,"session":2,"number":80,"question":"5歲大的陳小弟罹患黏多醣症（Mucopolysaccharidosis），他出現很典型的面部疾病特徵。雖然你知道須遵循病患肖像權及隱私規範，但為了在討論會中使用並教導學生，你必須顯現病童眼睛及整個面部的特寫，製成教學ppt。下列何種處理措施最重要？","options":["(A) 限定「此照片只做教學用途」加上保密措施","(B) 需取得倫理委員會的審查許可","(C) 向法定代理人詳細解釋處理方式，並取得同意","(D) 必須遮蔽雙眼以防止辨識"],"answer":2,"image":""},{"id":"md4-115-1-1","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"115年第1次第1題","year":115,"session":1,"number":1,"question":"下列有關嬰兒安全睡眠環境安排的敘述，何者最為適當？","options":["(A) 床欄杆要圍一圈軟墊或棉被防撞","(B) 嬰兒床擺在媽媽房間，但嬰兒需與媽媽不同床","(C) 給寶寶睡枕頭，以維持頭型","(D) 放一些填充玩偶陪伴，以增加安撫感"],"answer":1,"image":""},{"id":"md4-115-1-2","subject":"md4","topic":"兒科-感染神經","meta":"115年第1次第2題","year":115,"session":1,"number":2,"question":"有關卡介苗（Bacille Calmette-Guérin vaccine, BCG疫苗）的接種，下列敘述何者最不適當？","options":["(A) 卡介苗是以牛的分支桿菌（Mycobacterium bovis）製成之活性疫苗","(B) 目前我國政策建議出生滿5～8個月接受預防接種，但長住高發生率地區或即將前往結核病高盛行國家，可考慮提早接種","(C) 接種卡介苗主要是避免結核性腦膜炎或瀰漫性感染（disseminated and meningeal tuberculosis）等併發症","(D) 卡介苗接種後，約4～6個月皮膚結核菌素測試（tuberculin skin test），才會轉為陽性"],"answer":3,"image":""},{"id":"md4-115-1-3","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"115年第1次第3題","year":115,"session":1,"number":3,"question":"足月新生兒因分娩延長，婦產科醫師以真空吸引協助娩出。出生後兩小時頭圍增加1公分，膚色蒼白，心跳每分鐘190次，血壓42/20 mmHg。附圖為頭部剖面圖，最可能造成大量出血的位置為圖中何處？","options":["(A) 圖中位置①","(B) 圖中位置②","(C) 圖中位置③","(D) 圖中位置④"],"answer":2,"image":"md4-115-1-3.jpeg"},{"id":"md4-115-1-4","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第1次第4題","year":115,"session":1,"number":4,"question":"嬰兒使用呼吸器時，下列何種設定調整無法增加氧合（oxygenation）？","options":["(A) 調高最高吸氣壓力（peak inspiratory pressure）","(B) 調高吐氣末端正壓（positive end-expiratory pressure）","(C) 調高氣流流量（gas flow）","(D) 調高吐氣時間（expiratory time）"],"answer":3,"image":""},{"id":"md4-115-1-5","subject":"md4","topic":"兒科-消化系統疾病","meta":"115年第1次第5題","year":115,"session":1,"number":5,"question":"依現行衛生福利部疾病管制署建議，媽媽為B型肝炎表面抗原（HBsAg）陽性之B型肝炎帶原者之新生兒，最遲需於出生後幾小時內注射B型肝炎免疫球蛋白（hepatitis B immunoglobulin, HBIG）？","options":["(A) 24小時","(B) 36小時","(C) 48小時","(D) 72小時"],"answer":0,"image":""},{"id":"md4-115-1-6","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第1次第6題","year":115,"session":1,"number":6,"question":"下列何種先天性心臟病或是心臟手術後，最不會被聽到連續性的心雜音（continuous murmur）？","options":["(A) 接受central shunt人工分流管術後","(B) 冠狀動脈竇破裂到右心室（ruptured sinus of Valsalva aneurysm to right ventricle）","(C) 大型的主動脈到肺動脈側枝血管（major aortopulmonary collateral arteries, MAPCAs）","(D) 肺動脈－肺靜脈瘻管（pulmonary arteriovenous fistula）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第6題一律給分 (原公告答案 D)"},{"id":"md4-115-1-7","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第1次第7題","year":115,"session":1,"number":7,"question":"在兒童先天性心臟病的自然病史（natural history），下列何種先天性心臟病最不會出現肺動脈高壓（pulmonary hypertension）的併發症？","options":["(A) 心房中隔缺損（atrial septal defect）","(B) 開放性動脈導管（patent ductus arteriosus）","(C) 大血管轉位（dextro-loop transposition of the great arteries）","(D) 法洛氏四重症（tetralogy of Fallot）"],"answer":3,"image":""},{"id":"md4-115-1-8","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"115年第1次第8題","year":115,"session":1,"number":8,"question":"若嬰幼兒時期對下列食物產生過敏，何種食物的過敏最不容易隨年紀增長而消失？","options":["(A) 牛奶","(B) 黃豆","(C) 海鮮","(D) 蛋"],"answer":2,"image":""},{"id":"md4-115-1-9","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"115年第1次第9題","year":115,"session":1,"number":9,"question":"下列何者不是Langerhans cell histiocytosis的特色？","options":["(A) CDla：positive","(B) Birbeck granule：positive","(C) hemophagocytic histiocyte：positive","(D) eosinophilic granuloma"],"answer":2,"image":""},{"id":"md4-115-1-10","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第1次第10題","year":115,"session":1,"number":10,"question":"1歲小朋友診斷細支氣管肺炎，下列何者是呼吸作功增加的現象？","options":["(A) 頸部僵硬","(B) 鼻翼搧動","(C) 頭部轉動","(D) 呼吸暫停"],"answer":1,"image":""},{"id":"md4-115-1-11","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第1次第11題","year":115,"session":1,"number":11,"question":"15歲男孩，身體診察發現右上肢血壓為190/95 mmHg、背後兩肩胛骨間有收縮期雜音、右側橈（radial）動脈脈搏清楚，但兩側股動脈之脈搏摸不清楚。下列何種疾病應優先列入鑑別診斷？","options":["(A) 主動脈弓縮窄（coarctation of aorta）","(B) 主動脈瓣狹窄（aortic stenosis）","(C) 上主動脈瓣狹窄（supravalvular aortic stenosis）","(D) 下主動脈瓣狹窄（subaortic stenosis）"],"answer":0,"image":""},{"id":"md4-115-1-12","subject":"md4","topic":"兒科-消化系統疾病","meta":"115年第1次第12題","year":115,"session":1,"number":12,"question":"有關嬰兒腸絞痛診斷，下列何者最不適當？","options":["(A) 發生在小於5個月的嬰兒","(B) 照顧者的主訴可以當診斷的依據","(C) 病人呈現生長遲滯現象","(D) 臨床診斷標準為嬰兒每天哭鬧時間大於3小時，一星期發生3天以上"],"answer":2,"image":""},{"id":"md4-115-1-13","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"115年第1次第13題","year":115,"session":1,"number":13,"question":"3個月大的足月產男嬰，每天排便一次。今天因反覆嘔吐與腹脹，嘔吐物呈綠色，而至急診室求診。抽血檢 -++ 驗結果pH=7.15，PaCO2=28 mmHg，HCO3=16.5 mmol/L，BE=-8.5 mmol/L，[Na]=114 mEq/L，[K]=5.1 - mEq/L，[Cl]=68 mmol/L，BUN/creatinine=52/1.5 mg/dL；最有可能的診斷為何？","options":["(A) 腸道旋轉不良（malrotation）併中腸扭結（midgut volvulus）","(B) 肥厚性幽門狹窄（hypertrophic pyloric stenosis）","(C) 先天腎上腺增生（congenital adrenal hyperplasia）","(D) 先天巨腸症（congenital aganglionic megacolon）"],"answer":0,"image":""},{"id":"md4-115-1-14","subject":"md4","topic":"兒科-消化系統疾病","meta":"115年第1次第14題","year":115,"session":1,"number":14,"question":"關於急性胰臟炎（acute pancreatitis）的敘述，下列何者最不適當？","options":["(A) 造成孩童急性胰臟炎的主因，包括外傷、感染及膽道或胰管結構異常","(B) 引起兒童急性胰臟炎最常見的藥物是ibuprofen","(C) 嚴重急性胰臟炎身體診察時，肚臍周圍皮膚可能會有藍紫色瘀血出現（Cullen sign）","(D) 實驗室血液檢驗中，脂肪酶（lipase）的特異性（specificity）比澱粉酶（amylase）高"],"answer":1,"image":""},{"id":"md4-115-1-15","subject":"md4","topic":"兒科-體液電解質與腎功能","meta":"115年第1次第15題","year":115,"session":1,"number":15,"question":"3歲幼兒（懷孕週數31週，出生體重1450公克），主訴身高及體重皆小於第3百分位，過往病史有反覆肌肉無力、痙攣及多尿。其血液檢查呈現低血鉀、低血氯、高腎素和高醛固酮濃度、高pH值與高碳酸根離子；尿液檢查為高尿鈣症。下列診斷何者最為可能？","options":["(A) 腎小管酸血症（renal tubular acidosis）","(B) 慢性腹瀉（chronic diarrhea）","(C) 巴特氏症候群（Bartter syndrome）","(D) 吉特曼氏症候群（Gitelman syndrome）"],"answer":2,"image":""},{"id":"md4-115-1-16","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"115年第1次第16題","year":115,"session":1,"number":16,"question":"關於兒童慢性腎臟病（chronic kidney disease, CKD），下列敘述何者最不適當？","options":["(A) 小於5歲的孩童，發生的主因為先天腎臟與尿路異常（congenital abnormalities of kidney and urinary tract）","(B) 身材矮小是兒童慢性腎臟病的重要表現，主因生長激素（growth hormone）與胰島素樣生長因子1（insulin-like growth factor 1）缺乏導致","(C) CKD病童高血壓的首選藥為血管張力素轉化酶抑制劑（ACEI）或血管張力素受體阻斷劑（ARB）","(D) 鈣、磷電解質失調與CKD病童的血管鈣化有關"],"answer":1,"image":""},{"id":"md4-115-1-17","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"115年第1次第17題","year":115,"session":1,"number":17,"question":"關於夜尿（nocturnal enuresis），下列敘述何者最不適當？","options":["(A) 依照臨床上的定義，「夜尿」是指大於5歲的小孩在睡眠期間膀胱發生不自主排尿","(B) 口服或鼻噴（nasal spray）抗利尿激素（ADH）的類似物如desmopressin acetate，是夜尿的首選治療方式","(C) 兒童夜尿宜詳細病史詢問、理學檢查與實驗學檢查來排除器質性的疾病如糖尿病、尿崩症、慢性腎臟病","(D) 導致孩童夜尿的原因很多，包括生理、心理或遺傳等因素"],"answer":1,"image":""},{"id":"md4-115-1-18","subject":"md4","topic":"兒科-感染神經","meta":"115年第1次第18題","year":115,"session":1,"number":18,"question":"有關A群鏈球菌感染（group A streptococcus infection）的猩紅熱與川崎氏症（Kawasaki disease），下列敘述何者最不適當？","options":["(A) 都會發燒、起疹子、草莓舌","(B) 都有可能於指尖脫皮（desquamation）","(C) 都好發於5歲以上病童","(D) 鏈球菌感染用抗生素治療；川崎氏症急性期用intravenous immunoglobulin（IVIG）與aspirin"],"answer":2,"image":""},{"id":"md4-115-1-19","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第1次第19題","year":115,"session":1,"number":19,"question":"關於氣喘運動誘發測驗，下列敘述何者最不適當？","options":["(A) 持續有氧運動或跑步6～8分鐘","(B) 一般兒童運動後可以增加FEV1（一秒內用力吐氣容積）5～10%","(C) 未經適當治療的氣喘兒童，在運動誘發測試後，其FEV1通常會下降＞15%","(D) 學齡兒童運動誘發氣喘，通常在20分鐘開始，於30分鐘後達到最嚴重狀況"],"answer":3,"image":""},{"id":"md4-115-1-20","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"115年第1次第20題","year":115,"session":1,"number":20,"question":"下列何者不屬於大球性貧血（macrocytic anemia）？","options":["(A) 硫胺素反應性貧血（thiamine responsive anemia）","(B) 鉛中毒（lead poisoning）","(C) 范可尼貧血（Fanconi anemia）","(D) 葉酸缺乏（folate deficiency）"],"answer":1,"image":""},{"id":"md4-115-1-21","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"115年第1次第21題","year":115,"session":1,"number":21,"question":"關於兒童腫瘤可能造成的臨床徵象與實驗室檢查結果，下列敘述何者最不適當？","options":["(A) 類卡波西血管內皮細胞瘤（Kaposiform hemangioendothelioma）：瘀血、紫斑、血小板下降、微小血管內溶血性貧血","(B) 松果體母細胞腫瘤（pineoblastoma）：尿崩（diabetes insipidus）、乳溢（galactorrhea）、甲狀腺機能亢進（hyperthyroidism）","(C) 威爾姆氏腫瘤（Wilms tumor）：血尿（hematuria）、腹腔腫塊（abdominal mass）、部分凝血活酶時間延長（elevated partial thromboplastin time）","(D) 嗜鉻細胞瘤（pheochromocytoma）：陣發性高血壓（paroxysmal hypertension）、蒼白（pallor）、冒冷汗（sweating）、高尿液游離後腎上腺髓素濃度（high urine metanephrine level）"],"answer":1,"image":""},{"id":"md4-115-1-22","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第1次第22題","year":115,"session":1,"number":22,"question":"足月出生體重3.1公斤之新生兒，剛出生時哭聲宏亮，Apgar score於第一分鐘及第五分鐘為8分及9分。出生一小時後出現呼吸喘及發紺。聽診時發現其右邊呼吸音減弱，無腹部凹陷。下列何者為最可能的診斷？","options":["(A) 右側自發性氣胸","(B) 發紺型先天性心臟病","(C) 左側橫膈膜疝氣","(D) 病毒性細支氣管炎"],"answer":0,"image":""},{"id":"md4-115-1-23","subject":"md4","topic":"兒科-感染神經","meta":"115年第1次第23題","year":115,"session":1,"number":23,"question":"下列何者不是兒童腸病毒重症發生的前兆？","options":["(A) 呼吸急促","(B) 持續嘔吐","(C) 結膜出血","(D) 肌躍型抽搐（myoclonic jerk）"],"answer":2,"image":""},{"id":"md4-115-1-24","subject":"md4","topic":"兒科-內分泌遺傳","meta":"115年第1次第24題","year":115,"session":1,"number":24,"question":"下列何者不是目前臺灣健保給付生長激素治療的適應症？","options":["(A) 腦瘤導致生長激素缺乏症（growth hormone deficiency）","(B) 羅素－西弗氏症（Russell-Silver syndrome）","(C) 普瑞德威利氏症候群（Prader-Willi syndrome）","(D) 透納氏症（Turner syndrome）"],"answer":1,"image":""},{"id":"md4-115-1-25","subject":"md4","topic":"兒科-內分泌遺傳","meta":"115年第1次第25題","year":115,"session":1,"number":25,"question":"13歲男孩被診斷為嚴重糖尿病酮酸中毒（severe diabetic ketoacidosis）而住進加護病房，下列那一個實驗室檢查結果最可能在此病人身上表現？","options":["(A) 血鈉（sodium）及血液滲透壓（osmolality）皆低於正常值","(B) 血清尿素氮（BUN）及肌酸酐（creatinine）皆低於正常值","(C) 血氧（O2）及總二氧化碳（total CO2）皆高於正常值","(D) 血液陰離子間隙（anion gap）高於正常值"],"answer":3,"image":""},{"id":"md4-115-1-26","subject":"md4","topic":"兒科-感染神經","meta":"115年第1次第26題","year":115,"session":1,"number":26,"question":"8歲男童高燒一星期求診，併有頭痛、腹痛和嘔吐的症狀。約在發燒10天前到山區掃墓。身體診察發現左側鼠蹊部淋巴結腫大、腹股溝發現約1.5cm×1.0cm的焦痂（eschar）。抽血報告顯示Hb 13.6 g/dL，WBC 13300/μL，platelet 275000/μL，GOT 212 U/L，GPT 359 U/L，CRP 7.535 mg/dL。最有可能的診斷為下列何者？","options":["(A) 登革熱（dengue fever）","(B) 鉤端螺旋體病（leptospirosis）","(C) 恙蟲病（scrub typhus）","(D) 炭疽熱（anthrax）"],"answer":2,"image":""},{"id":"md4-115-1-27","subject":"md4","topic":"兒科-感染神經","meta":"115年第1次第27題","year":115,"session":1,"number":27,"question":"12歲男童，因發燒與咳嗽4天就診，診斷為非典型肺炎，並給與azithromycin 10 mg/kg/day QD 3天治療。治療後一天隨即退燒，兩次抽血檢驗Mycoplasma pneumoniae的IgG與IgM抗體均為陰性。下列何者是最可能的病原？","options":["(A) Streptococcus pneumoniae","(B) Chlamydia trachomatis","(C) Chlamydia pneumoniae","(D) Mycoplasma hominis"],"answer":2,"image":""},{"id":"md4-115-1-28","subject":"md4","topic":"兒科-感染神經","meta":"115年第1次第28題","year":115,"session":1,"number":28,"question":"關於嬰兒玫瑰疹（roseola infantum）的敘述，下列何者最不適當？","options":["(A) 引起玫瑰疹的病毒是human herpesvirus 6（HHV-6）和HHV-7","(B) 皮膚紅疹通常與發燒同時出現，多分布在軀幹，燒退後2～3天逐漸消失","(C) 亞洲病童常可在懸壅垂兩側發現稱之為永山斑（Nagayama spots）的潰瘍","(D) 可併發痙攣，但日後再發生癲癇的機率不會比一般人高"],"answer":1,"image":""},{"id":"md4-115-1-29","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"115年第1次第29題","year":115,"session":1,"number":29,"question":"關於自閉症類群障礙症（autism spectrum disorder）的描述，下列何者最適當？","options":["(A) 自閉症的語言表達能力通常不會受到影響","(B) 自閉症目前已經有抽血的生物標記（biomarker）可以用來診斷","(C) 目前對於自閉症的核心症狀已有很有效的藥物治療","(D) 自閉症約有50%病患有智能不足的問題"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第29題一律給分 (原公告答案 D)"},{"id":"md4-115-1-30","subject":"md4","topic":"兒科-內分泌遺傳","meta":"115年第1次第30題","year":115,"session":1,"number":30,"question":"10個月嬰兒因點頭性痙攣就診，身體診察皮膚有六處鯊魚皮斑（shagreen patch）及五小片褪色白斑（hypopigmented macules），額頭有血管纖維瘤（angiofibroma），心臟超音波發現一顆橫紋肌瘤（rhabdomyoma），下列何者為最可能的診斷？","options":["(A) Sturge-Weber症候群","(B) 神經纖維瘤（neurofibromatosis）","(C) 結節性硬化症（tuberous sclerosis）","(D) 線狀皮脂腺痣症候群（linear nevus sebaceous syndrome）"],"answer":2,"image":""},{"id":"md4-115-1-31","subject":"md4","topic":"兒科-感染神經","meta":"115年第1次第31題","year":115,"session":1,"number":31,"question":"有關熱性痙攣後續發展為癲癇的危險因子，下列何者機率最低？","options":["(A) 單純性發作（simple type）","(B) 發燒不到1小時就發生熱性痙攣","(C) 有神經發展方面的障礙或缺陷","(D) 有癲癇的家族病史"],"answer":0,"image":""},{"id":"md4-115-1-32","subject":"md4","topic":"兒科-感染神經","meta":"115年第1次第32題","year":115,"session":1,"number":32,"question":"8歲女童，高燒3天合併喉嚨痛、無法進食、倦怠。身體診察發現雙眼皮浮腫、化膿性扁桃腺炎、脾臟腫大。下列敘述何者最適當？","options":["(A) 身體診察可能會發現雙側頸部淋巴結腫大及肝腫大","(B) 會表現出嗜中性白血球（neutrophil）增多的現象，診斷標準檢驗為血液培養","(C) 需抗生素治療，但若使用青黴素類抗生素（如ampicillin），可能會有紅疹現象","(D) 感染後常出現感染後腎小球腎炎"],"answer":0,"image":""},{"id":"md4-115-1-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"115年第1次第33題","year":115,"session":1,"number":33,"question":"有關Huntington disease（HD）與fragile X syndrome的比較，下列何者最不適當？","options":["(A) 兩者親代的premutation expansions會導致子代full mutations的機率增加","(B) premutation alleles中重複序列的次數：HD 29～35次；fragile X syndrome 55～200次","(C) 重複序列：CAG in Huntington disease；CGG in fragile X syndrome","(D) fragile X syndrome的重複序列擴增來自父親"],"answer":3,"image":""},{"id":"md4-115-1-34","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"115年第1次第34題","year":115,"session":1,"number":34,"question":"26歲的女性患者罹患中重度乾癬（病灶占全身體表面積30%）且合併有乾癬性關節炎，對於此患者的治療計畫，下列何者錯誤？","options":["(A) 建議施打IL-17A抑制劑，可同時治療皮膚和關節炎症狀","(B) 照光治療建議使用在病灶體表面積小於10%的患者，所以不是治療選擇","(C) 患者有懷孕計畫，口服藥物包括acitretin、methotrexate都有致畸胎性（teratogenic），需要避免使用","(D) 相較於IL-17A抑制劑，IL-23抑制劑較不會產生發炎性腸道疾病（inflammatory bowel disease）的副作用"],"answer":1,"image":""},{"id":"md4-115-1-35","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"115年第1次第35題","year":115,"session":1,"number":35,"question":"關於接觸性皮膚炎（contact dermatitis）的敘述，何者錯誤？","options":["(A) 雙手反覆碰水若引起刺激性接觸性皮膚炎（irritant contact dermatitis），其病灶通常會在雙手都出現","(B) 橡膠手套若引起過敏性接觸性皮膚炎（allergic contact dermatitis），其病灶不一定會在雙手都出現","(C) 染髮劑中的para-phenylenediamine（PPD）若引起過敏性接觸性皮膚炎（allergic contact dermatitis），其病灶只會發生於頭皮，不會發生於額頭或頸部","(D) 貼膚測試（patch test）有助於診斷過敏性接觸性皮膚炎（allergic contact dermatitis）"],"answer":2,"image":""},{"id":"md4-115-1-36","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"115年第1次第36題","year":115,"session":1,"number":36,"question":"關於扁平苔癬（lichen planus）的敘述，下列何者錯誤？","options":["(A) 病灶為紅紫色、多角型的扁平丘疹或斑塊","(B) 病灶常伴隨膿疱","(C) 好發部位包括口腔黏膜","(D) 可用外用皮質類固醇治療"],"answer":1,"image":""},{"id":"md4-115-1-37","subject":"md4","topic":"皮膚-感染","meta":"115年第1次第37題","year":115,"session":1,"number":37,"question":"下列關於頭癬（tinea capitis）的敘述，何者錯誤？","options":["(A) 不注意個人衛生是可能的危險因子之一","(B) 若是懷疑頭癬感染，可以考慮伍氏燈（Wood lamp）、KOH檢查、黴菌培養或切片檢查，以幫助診斷","(C) 若是在伍氏燈（Wood lamp）下看到頭髮上有黃綠色螢光，則可確定是髮癬菌屬（Trichophyton species）的感染","(D) 在確定診斷後，口服抗黴菌藥是治療首選"],"answer":2,"image":""},{"id":"md4-115-1-38","subject":"md4","topic":"皮膚-感染","meta":"115年第1次第38題","year":115,"session":1,"number":38,"question":"55歲男性因胯下出現搔癢的紅疹來就診，病人提到工作時常流汗，其病灶如圖一所示。伍氏燈（Wood lamp）的檢查結果如圖二所示。最可能的診斷為何？","options":["(A) 紅癬（erythrasma）","(B) 股癬（tinea cruris）","(C) 對磨疹（intertrigo）","(D) 念珠球菌感染（candidiasis）"],"answer":0,"image":"md4-115-1-38.jpeg"},{"id":"md4-115-1-39","subject":"md4","topic":"皮膚-腫瘤","meta":"115年第1次第39題","year":115,"session":1,"number":39,"question":"關於基底細胞癌（basal cell carcinoma），下列敘述何者錯誤？","options":["(A) 為最常見的皮膚惡性腫瘤","(B) 手術切除為治療選擇之一","(C) 轉移機率甚高，常需配合化學治療","(D) 可能與日光曝曬有關"],"answer":2,"image":""},{"id":"md4-115-1-40","subject":"md4","topic":"皮膚-腫瘤","meta":"115年第1次第40題","year":115,"session":1,"number":40,"question":"有關皮膚黑色素細胞癌（cutaneous melanoma）的危險因子，下列何者最正確？","options":["(A) 持續少量日曬的人","(B) 深色皮膚的人","(C) 天生紅髮或金髮的人","(D) 易曬黑不易曬傷的人"],"answer":2,"image":""},{"id":"md4-115-1-41","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"115年第1次第41題","year":115,"session":1,"number":41,"question":"關於化膿性汗腺炎（hidradenitis suppurativa），下列敘述何者正確？","options":["(A) 體重過輕是惡化因子之一","(B) 臨床上好發於頭頸部，不易發生於腋下與胯下","(C) 疾病的最初起因是來自於大汗腺的細菌感染","(D) anti-TNF-α（adalimumab）單株抗體是核准的治療方式之一"],"answer":3,"image":""},{"id":"md4-115-1-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"115年第1次第42題","year":115,"session":1,"number":42,"question":"下列有關男樣多毛症（hirsutism）之敘述，何者錯誤？","options":["(A) 亦稱為毛髮增多症（hypertrichosis）","(B) 上唇為常見的位置","(C) 檢測血液可能有雄性素升高的現象","(D) 若男樣多毛症的症狀在短時間內出現，應考慮腎上腺或卵巢腫瘤"],"answer":0,"image":""},{"id":"md4-115-1-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"115年第1次第43題","year":115,"session":1,"number":43,"question":"25歲男性，青春期後開始在雙側腋下及胯下出現搔癢刺痛之紅色斑塊，並伴隨皮膚糜爛（erosive erythematous plaques），尤其在夏天時特別嚴重。經詢問後發現其父親及祖父亦有類似症狀。其最有可能為下列何種疾病？","options":["(A) Darier disease","(B) Galli-Galli disease","(C) Hailey-Hailey disease","(D) beriberi disease"],"answer":2,"image":""},{"id":"md4-115-1-44","subject":"md4","topic":"神經-中風","meta":"115年第1次第44題","year":115,"session":1,"number":44,"question":"關於急性缺血性腦中風之血栓溶解治療，下列敘述何者錯誤？","options":["(A) 常規治療為經動脈內施打組織胞漿素原活化劑（tissue plasminogen activator, t-PA），以減少藥物劑量並降低出血機率","(B) 靜脈血栓溶解治療可增加預後較佳之病人比例，但顱內出血的比例也會顯著上升","(C) 由於組織胞漿素原活化劑（tissue plasminogen activator, t-PA）的半衰期較短，因此t-PA治療需在部分藥物快速輸注（bolus）後，於60分鐘內將剩餘劑量進行連續性輸注","(D) 所有腦中風病人在接受血栓溶解治療前，皆應該進行腦部影像學檢查（如電腦斷層或磁振造影）"],"answer":0,"image":""},{"id":"md4-115-1-45","subject":"md4","topic":"神經-中風","meta":"115年第1次第45題","year":115,"session":1,"number":45,"question":"82歲女性病人突然發生右側枕葉頭痛合併左側視野缺損，無顯影劑之腦部電腦斷層（non-contrast CT）檢查結果如下圖①，磁振造影之磁敏感加權成像（susceptibility weighted imaging, SWI）結果如下圖② ③。下列何者最有可能是此病人的診斷？","options":["(A) 腫瘤併發腦轉移及腦出血","(B) 腦部隱球菌（cryptococcus）感染合併腦出血","(C) 大腦類澱粉血管病變（cerebral amyloid angiopathy）合併腦出血","(D) 原發性中樞神經系統血管炎（primary angiitis of central nervous system）合併腦出血"],"answer":2,"image":"md4-115-1-45.jpeg"},{"id":"md4-115-1-46","subject":"md4","topic":"神經-中風","meta":"115年第1次第46題","year":115,"session":1,"number":46,"question":"反覆發生右眼暫時性黑矇症（transient monocular blindness, amaurosis fugax），下列何者是最有可能的病因？","options":["(A) 右側內頸動脈狹窄（internal carotid artery stenosis）","(B) 右側鎖骨下動脈狹窄（subclavian artery stenosis）","(C) 右側中大腦動脈狹窄（middle cerebral artery stenosis）","(D) 心房顫動造成心因性血栓（cardiac emboli）"],"answer":0,"image":""},{"id":"md4-115-1-47","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"115年第1次第47題","year":115,"session":1,"number":47,"question":"37歲的男性因全身痙攣路倒被救護車送到急診，據路人描述從開始發作到進入急診大約15分鐘。標準急救流程已經建立完成，下列有關癲癇之敘述，何者錯誤？","options":["(A) 痙攣須持續超過30分鐘，才可以診斷為重積癲癇（status epilepticus）","(B) 立即給與lorazepam靜脈注射，若癲癇未停止，5分鐘後可以再重複一次","(C) 開始給與phenytoin、valproic acid或levetiracetam靜脈注射","(D) 若給與靜脈注射之抗癲癇藥物後仍未停止發作，需進行插管，開始給與propofol、midazolam或phenobarbital靜脈注射"],"answer":0,"image":""},{"id":"md4-115-1-48","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"115年第1次第48題","year":115,"session":1,"number":48,"question":"下列何者不屬於國際頭痛學會偏頭痛的診斷標準？","options":["(A) 畏光且怕吵","(B) 搏動性","(C) 噁心或嘔吐","(D) 味覺異常"],"answer":3,"image":""},{"id":"md4-115-1-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"115年第1次第49題","year":115,"session":1,"number":49,"question":"21歲女性，自4年前開始有白日嗜睡的困擾。她生活作息正常，但是6個月前和同學開玩笑的時候開始出現眼瞼和頭部下垂，以及雙膝癱軟的情形，有時因此摔倒，發作時意識正常。晚上睡覺常出現全身不能動彈，感覺有黑影壓在身上，令她非常害怕。下列何者是最可能的致病機轉？","options":["(A) 腦部異常放電（癲癇樣波）","(B) 下視丘泌素（hypocretin）缺乏","(C) 神經肌肉交接傳遞異常","(D) 血鉀過低"],"answer":1,"image":""},{"id":"md4-115-1-50","subject":"md4","topic":"神經-失智退化運動障礙","meta":"115年第1次第50題","year":115,"session":1,"number":50,"question":"患有意想運動性失用症（ideomotor apraxia）的病人，可執行下列何種測試？","options":["(A) 形容如何寄一封信的步驟","(B) 示範刷牙時如何拿牙刷","(C) 模仿檢查者使用槌子","(D) 用剪刀剪出一直線"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第50題除未作答者不給分外，其餘均給分 (原公告答案 A)"},{"id":"md4-115-1-51","subject":"md4","topic":"神經-失智退化運動障礙","meta":"115年第1次第51題","year":115,"session":1,"number":51,"question":"65歲男性走路小碎步，容易跌倒。他的太太表示他最近事情常常記不起來，反應遲鈍，有時也會尿失禁。他的腦部電腦斷層掃描結果如下，如果接受腦室腹腔分流術（ventriculoperitoneal shunt）治療，下列敘述何者最恰當？","options":["(A) 走路比記憶力容易進步","(B) 術前腦壓測量通常不正常","(C) 尿失禁最容易進步","(D) 手術後進步通常可以持續5年以上"],"answer":0,"image":"md4-115-1-51.jpeg"},{"id":"md4-115-1-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"115年第1次第52題","year":115,"session":1,"number":52,"question":"50歲認知功能正常的巴金森氏病（Parkinson disease）患者之藥物治療，下列何者最不適當？","options":["(A) anticholinergics","(B) cholinesterase inhibitors","(C) dopamine agonists","(D) monoamine oxidase type B inhibitors"],"answer":1,"image":""},{"id":"md4-115-1-53","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"115年第1次第53題","year":115,"session":1,"number":53,"question":"下列有關脊髓症候群（spinal cord syndrome）的敘述，何者錯誤？","options":["(A) 脊椎性休克（spinal shock）是指在急性脊髓損傷該節以下的肌腱反射會上升","(B) Brown-Sé quard症候群是指在脊髓損傷該節以下的同側肢體無力及本體感覺（proprioception）的消失","(C) 前方脊髓症候群（anterior cord syndrome）本體感覺可以保留","(D) 中心脊髓症候群（central cord syndrome）肌肉無力的現象在上肢遠比下肢嚴重"],"answer":0,"image":""},{"id":"md4-115-1-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"115年第1次第54題","year":115,"session":1,"number":54,"question":"31歲男性，開車停在路口等紅燈時，不幸遭後車追撞，引起兩側上肢麻木疼痛，最可能傷及下列何種神經路徑？","options":["(A) 脊髓丘腦徑（spinothalamic tract）","(B) 脊神經（spinal nerve）","(C) 椎體徑（pyramidal tract）","(D) 後柱（posterior column）"],"answer":0,"image":""},{"id":"md4-115-1-55","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"115年第1次第55題","year":115,"session":1,"number":55,"question":"下列何種周邊神經系統疾病的致病機轉與代謝異常有關？","options":["(A) 格林–巴利症候群（Guillain-Barré syndrome）","(B) 運動神經元疾病（motor neuron disease）","(C) 類澱粉樣神經病變（amyloid neuropathy）","(D) 皮肌炎（dermatomyositis）"],"answer":2,"image":""},{"id":"md4-115-1-56","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"115年第1次第56題","year":115,"session":1,"number":56,"question":"關於原發性中樞神經淋巴瘤（primary central nervous system lymphoma, PCNSL）的敘述，下列何者錯誤？","options":["(A) 與一般民眾相較，人類免疫不全病毒（human immunodeficiency virus, HIV）感染者有較高罹患PCNSL的風險","(B) 與一般民眾相較，接收器官移植的病人有較高罹患PCNSL的風險","(C) 人類疱疹病毒6（human herpesvirus 6）在PCNSL的致病機制中扮演了重要角色","(D) 對於疑似PCNSL的病人，在進行病理切片確定診斷前，不宜使用類固醇治療"],"answer":2,"image":""},{"id":"md4-115-1-57","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"115年第1次第57題","year":115,"session":1,"number":57,"question":"關於貝克氏肌肉失養症（Becker muscular dystrophy）的敘述，下列何者錯誤？","options":["(A) 是因為dystrophin基因發生突變而致病","(B) 發病時的臨床症狀常是雙下肢近端肌肉無力","(C) 部分病人的發病年齡可以在20歲以後","(D) 四分之一病人的致病突變是由父親遺傳來的"],"answer":3,"image":""},{"id":"md4-115-1-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"115年第1次第58題","year":115,"session":1,"number":58,"question":"對於病毒性腦炎的敘述，下列何者正確？","options":["(A) 第一型單純疱疹病毒（HSV-1）通常是造成疱疹病毒腦炎的元凶，也容易在口腔周圍出現疱疹","(B) 帶狀疱疹病毒（VZV）和小兒麻痺病毒一樣，常造成運動神經元感染","(C) 小時候受過水痘（chickenpox）感染的病童，成年後就不會受到帶狀疱疹的侵犯","(D) 疱疹病毒腦炎所侵犯的範圍，侷限在腦幹，尤其是延腦後半部"],"answer":0,"image":""},{"id":"md4-115-1-59","subject":"md4","topic":"精神-精神病","meta":"115年第1次第59題","year":115,"session":1,"number":59,"question":"下列何者不屬於僵直症（catatonia）的精神症狀？","options":["(A) mannerism","(B) mutism","(C) nihilism","(D) negativism"],"answer":2,"image":""},{"id":"md4-115-1-60","subject":"md4","topic":"精神-精神病","meta":"115年第1次第60題","year":115,"session":1,"number":60,"question":"關於雙極情緒障礙症鬱期（bipolar depression）的藥物治療，下列敘述何者最不適當？","options":["(A) 使用risperidone","(B) 使用鋰鹽","(C) 使用lurasidone","(D) 使用lamotrigine"],"answer":0,"image":""},{"id":"md4-115-1-61","subject":"md4","topic":"精神-精神官能症","meta":"115年第1次第61題","year":115,"session":1,"number":61,"question":"下列關於精神疾病治療的敘述，何者最適當？","options":["(A) 與抗憂鬱劑治療重鬱症做比較，電痙攣治療（electroconvulsive therapy）的效果比較快出現，但是療效則沒有差異","(B) 對於抗憂鬱劑沒有療效的重鬱症患者，大約有一半的個案在接受電痙攣治療（electroconvulsive therapy）會出現治療效果","(C) 重鬱症患者合併有身體症狀障礙症（somatic symptom disorder）對於電痙攣治療（electroconvulsive therapy）會有比較差的治療反應","(D) 當躁期病人對於鋰鹽療效不佳時，可以加上電痙攣治療（electroconvulsive therapy）來促進治療反應"],"answer":2,"image":""},{"id":"md4-115-1-62","subject":"md4","topic":"精神-器質性與物質使用","meta":"115年第1次第62題","year":115,"session":1,"number":62,"question":"吳先生，32歲男性，因為疲倦嗜睡被家人帶來醫院。吳先生表示今天特別想吃東西，並且在昏睡時會做鮮明的惡夢。家人表示吳先生有上夜店的習慣，最後一次上夜店是兩三天前。吳先生的臨床表現最可能是下列何種狀況？","options":["(A) Heroin withdrawal","(B) Alcohol withdrawal","(C) Methamphetamine withdrawal","(D) Hypnotic withdrawal"],"answer":2,"image":""},{"id":"md4-115-1-63","subject":"md4","topic":"精神-器質性與物質使用","meta":"115年第1次第63題","year":115,"session":1,"number":63,"question":"有關譫妄（delirium）的描述，下列何者最不適當？","options":["(A) 相較於失智症，譫妄的發作較快，且波動性較大","(B) 某些嚴重的躁症患者會有極度的混亂行為，與譫妄難以區別","(C) 如果是hypoactive的譫妄，常與鬱症患者難以區別","(D) 譫妄的腦波（EEG）典型呈現generalized paroxysmal fast activity"],"answer":3,"image":""},{"id":"md4-115-1-64","subject":"md4","topic":"精神-精神病","meta":"115年第1次第64題","year":115,"session":1,"number":64,"question":"關於抗精神病藥物（antipsychotics）之敘述，下列何者最不適當？","options":["(A) 不少抗精神病藥物會引發心臟方面副作用，包括心臟傳導異常","(B) 抗精神病藥物的其中一種嚴重副作用為抗精神病藥惡性症候群（neuroleptic malignant syndrome），有可能致命","(C) 一旦產生抗精神病藥惡性症候群，使用dantrolene治療可能有效","(D) 施打長效針劑（long-acting depot）是克服病人不服藥的方式之一，目前臨床上最常使用的是效期一年之長效針劑"],"answer":3,"image":""},{"id":"md4-115-1-65","subject":"md4","topic":"精神-器質性與物質使用","meta":"115年第1次第65題","year":115,"session":1,"number":65,"question":"有關譫妄（delirium）的敘述，下列何者最適當？","options":["(A) 應優先使用低劑量抗精神病藥物以快速控制激動和混亂","(B) 非藥物介入以身體約束優先，以減少精神科藥物對譫妄的影響","(C) 發生譫妄的病人3個月後的死亡率約20～30％","(D) 使用苯二氮平類藥物可有效緩解譫妄"],"answer":2,"image":""},{"id":"md4-115-1-66","subject":"md4","topic":"精神-精神官能症","meta":"115年第1次第66題","year":115,"session":1,"number":66,"question":"關於強迫症（obsessive-compulsive disorder）大部分的個案其病程之描述，下列何者最適當？","options":["(A) 急性發作，經積極治療後，快速緩解（rapid remission）","(B) 陣發性（episodic）發作","(C) 持續（continuous）而慢性化（chronic）","(D) 雖然積極治療，仍急遽惡化（deteriorative）"],"answer":2,"image":""},{"id":"md4-115-1-67","subject":"md4","topic":"精神-精神官能症","meta":"115年第1次第67題","year":115,"session":1,"number":67,"question":"懼曠症（agoraphobia）最常與下列何種疾病共病（comorbid）或共同存在（coexist）？","options":["(A) 憂鬱症（depressive disorders）或憂鬱症狀","(B) 思覺失調症（schizophrenia）或幻覺妄想症狀","(C) 雙極情感疾患（bipolar disorder）或躁症症狀","(D) 恐慌症（panic disorder）或恐慌症狀"],"answer":3,"image":""},{"id":"md4-115-1-68","subject":"md4","topic":"精神-精神官能症","meta":"115年第1次第68題","year":115,"session":1,"number":68,"question":"關於性別不安（gender dysphoria）的敘述，下列何者最適當？","options":["(A) 性別不安應該先排除雙性人（intersex）診斷","(B) 若欲診斷兒童有性別不安，個案須強烈渴望成為異性，或堅持他或她就是異性（或有別於被指定性別的其他性別）","(C) 若為成年人之後才展現之性別與指定性別（birth-assigned gender）之間顯著不一致，期間雖未達6個月，仍可被診斷性別不安","(D) 美國精神醫學會建議，改變性別認同或性傾向的心理治療愈早施行愈有效"],"answer":1,"image":""},{"id":"md4-115-1-69","subject":"md4","topic":"精神-器質性與物質使用","meta":"115年第1次第69題","year":115,"session":1,"number":69,"question":"下列何種藥物或物質的定位不屬於中樞神經刺激劑（stimulants）？","options":["(A) Cocaine","(B) Methamphetamine","(C) Methylphenidate","(D) Ketamine"],"answer":3,"image":""},{"id":"md4-115-1-70","subject":"md4","topic":"精神-器質性與物質使用","meta":"115年第1次第70題","year":115,"session":1,"number":70,"question":"29歲男子，大量使用某種物質後出現食慾降低、情緒激躁不安、血壓增高、心跳加速、多疑。下列何者為此男子最可能使用的物質？","options":["(A) 安非他命（amphetamine）","(B) 愷他命（ketamine）","(C) 大麻（cannabis）","(D) 幻覺劑（hallucinogen）"],"answer":0,"image":""},{"id":"md4-115-1-71","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"115年第1次第71題","year":115,"session":1,"number":71,"question":"有關侵擾性情緒失調症（disruptive mood dysregulation disorder）的敘述，下列何者最不適當？","options":["(A) 是DSM-5新納入的診斷，特徵是嚴重，不適切的，且反覆的脾氣爆發至少1週3次以上","(B) 侵擾性情緒失調症需與注意力不足／過動症（ADHD）鑑別診斷，應避免將此兩診斷並存","(C) 18歲以上初次就診的病患不適用此診斷","(D) 如果病患的疾病生理與特徵很類似雙極情緒障礙症（bipolar disorder），藥物治療的首選是非典型抗精神病劑（atypical antipsychotic agents）或情緒穩定劑（mood stabilizers）"],"answer":1,"image":""},{"id":"md4-115-1-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"115年第1次第72題","year":115,"session":1,"number":72,"question":"有關注意力不足／過動症（ADHD）的敘述，下列何者最適當？","options":["(A) 很大一部分的病因（約75％）可為基因遺傳所解釋","(B) ADHD需與特定的學習障礙症（specific learning disorders）鑑別，兩診斷不能同時成立","(C) 相較於過動的症狀，注意力不足的症狀通常會較早消失痊癒","(D) 1999年在美國進行的Multimodal Treatment Study of Children with ADHD（MTA）研究，發現ADHD個案單純接受行為治療，比起單純接受藥物治療，ADHD的核心症狀改善較為明顯"],"answer":0,"image":""},{"id":"md4-115-1-73","subject":"md4","topic":"精神-精神病","meta":"115年第1次第73題","year":115,"session":1,"number":73,"question":"23歲的小芬，數年以來情緒持續地極不穩定，長期感到空虛，常常覺得自己一無是處，總是擔心家人和男友會拋棄她，只要覺得別人好像要疏遠自己，就反覆以自殺威脅他們。某次在和男友嚴重爭吵後，行為舉止突然變得幼稚如小孩，還說耳朵聽到已過世的外祖父在和自己說話，因而被送至醫院急診。關於小芬的人格，下列敘述何者最適當？","options":["(A) 為依賴型人格障礙症（dependent personality disorder）","(B) 對此人格障礙症患者，心理治療和藥物治療各有效果，而兩者合併並無更佳的效果","(C) 辯證行為治療（dialectical behavior therapy）對於此人格障礙症患者具有療效，尤其割腕行為","(D) 要改善此人格障礙症的自我觀感和社會關係困難的核心症狀，最有效的治療藥物是苯二氮平（benzodiazepine）"],"answer":2,"image":""},{"id":"md4-115-1-74","subject":"md4","topic":"兒科-消化系統疾病","meta":"115年第1次第74題","year":115,"session":1,"number":74,"question":"出生兩天大的女嬰因嘔吐不止就醫，接受上消化道攝影結果如圖示，下列何者為最可能之診斷？","options":["(A) 中腸旋轉不良","(B) 肥厚性幽門狹窄","(C) 胃食道逆流","(D) 空腸閉鎖症"],"answer":0,"image":"md4-115-1-74.jpeg"},{"id":"md4-115-1-75","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"115年第1次第75題","year":115,"session":1,"number":75,"question":"56歲男性，主訴近2年來雙側視力模糊，頭部磁振造影檢查結果如附圖，下列何者為最可能之診斷？","options":["(A) 腦下垂體腺瘤（pituitary adenoma）","(B) 視神經膠質瘤（optic glioma）","(C) 動脈瘤（aneurysm）","(D) 松果體腫瘤（pineal tumor）"],"answer":0,"image":"md4-115-1-75.jpeg"},{"id":"md4-115-1-76","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"115年第1次第76題","year":115,"session":1,"number":76,"question":"有關癲癇重積（status epilepticus）的描述，何者錯誤？","options":["(A) 單次抽搐時間≧10分鐘","(B) 兩次或兩次以上抽搐之後意識沒有恢復","(C) 癲癇重積可能會造成神經損傷","(D) 靜脈注射抗癲癇藥物是必要的"],"answer":0,"image":""},{"id":"md4-115-1-77","subject":"md4","topic":"神經-中風","meta":"115年第1次第77題","year":115,"session":1,"number":77,"question":"針對急性腦中風病人之緊急處置，下列敘述何者錯誤？","options":["(A) 疑似中風個案在急診應儘速完成國家衛生院腦中風量表（National Institutes of Health Stroke Scale, NIHSS）的評估，以便早期決定施予血栓溶解劑治療","(B) 缺血性中風病人，在使用高血壓藥物治療後，病人的血壓維持在190/116 mmHg時，可以使用血栓溶解劑治療","(C) NIHSS評估量表，分數愈高，神經症狀愈嚴重","(D) 治療蜘蛛膜下腔出血時，使用nimodipine具有保護腦部的作用"],"answer":1,"image":""},{"id":"md4-115-1-78","subject":"md4","topic":"精神-器質性與物質使用","meta":"115年第1次第78題","year":115,"session":1,"number":78,"question":"有關Naloxone的敘述，下列何者最適當？","options":["(A) 可以對抗嗎啡類物質在各種嗎啡類受器的作用，但是對μ受器對抗作用較弱","(B) 它可以噴到鼻腔內使用，吸收情形與肌肉注射相當","(C) 它的作用時間與大多數嗎啡類藥物相當，所以大多不需要多次給與來對抗嗎啡類藥物中毒","(D) 使用後可反轉嗎啡類產生的呼吸抑制，幾乎沒有什麼副作用"],"answer":1,"image":""},{"id":"md4-115-1-79","subject":"md4","topic":"醫學倫理與法規","meta":"115年第1次第79題","year":115,"session":1,"number":79,"question":"40歲的甲先生剛因為自己有心律不整，被診斷有法布瑞氏症（Fabry disease），而了解到法布瑞氏症是一個X染色體遺傳的晚發性疾病，因此他急著帶自己3歲活蹦亂跳的女兒乙來進行法布瑞氏症帶因者篩檢，希望可以儘早為她做後續保險的規劃。下列敘述何者最不適當？","options":["(A) 此作法將影響乙未來婚姻與生育的規劃，應等乙成年後在知情且同意的狀況下進行","(B) 甲的X染色體應該會遺傳給乙，所以不需要進行基因檢測","(C) 乙成年前不會有症狀，目前進行檢驗非屬必要且可能造成資源浪費","(D) 乙檢測後才可以進行各項醫療或意外險的商業投保，可及早開始準備"],"answer":3,"image":""},{"id":"md4-115-1-80","subject":"md4","topic":"醫學倫理與法規","meta":"115年第1次第80題","year":115,"session":1,"number":80,"question":"某教學醫院的王醫師是個熱心的老師，他十分注重身體檢查，每兩個月，他就會選一個嬰兒室的新生兒，示範全身身體檢查，並讓5位醫學生用此嬰兒實際演練直到熟練。下列敘述何者最適當？","options":["(A) 身體檢查非侵入性，不必告知同意步驟","(B) 這是很好而值得鼓勵的教學活動","(C) 即使告知家長獲得同意，亦屬不適當","(D) 可以進行，但應給予同等於「標準化病人」之酬勞"],"answer":2,"image":""},{"id":"md4-115-2-1","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"115年第2次第1題","year":115,"session":2,"number":1,"question":"下列何者最不可能出現在滿2歲大孩子的發展指標中？","options":["(A) 上下樓梯（walks up and down stairs）","(B) 知道全名（knows full name）","(C) 打開門（opens doors）","(D) 跳躍（jumps）"],"answer":1,"image":""},{"id":"md4-115-2-2","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"115年第2次第2題","year":115,"session":2,"number":2,"question":"貧血病人血液抹片發現有很多spherocytes，最不可能是下列何種疾病？","options":["(A) ABO血型不合引起的溶血性貧血（ABO incompatibility induced hemolytic anemia）","(B) 自體免疫性溶血性貧血（autoimmune hemolytic anemia）","(C) 遺傳性球形紅血球症（hereditary spherocytosis）","(D) G6PD缺乏症引起的溶血性貧血（G6PD deficiency induced hemolytic anemia）"],"answer":3,"image":""},{"id":"md4-115-2-3","subject":"md4","topic":"兒科-內分泌遺傳","meta":"115年第2次第3題","year":115,"session":2,"number":3,"question":"關於兒童第1型糖尿病（type 1 diabetes mellitus）及第2型糖尿病（type 2 diabetes mellitus），下列敘述何者最適當？","options":["(A) 第1型糖尿病病童比第2型糖尿病病童有較高比例的糖尿病家族史（family history）","(B) 第1型糖尿病病童在40歲後或肥胖後會轉變成第2型糖尿病","(C) 第1型糖尿病及第2型糖尿病病童均需要接受飲食控制及維持良好的運動習慣","(D) 兒童第1型糖尿病為先天性，而兒童第2型糖尿病是飲食異常及肥胖造成"],"answer":2,"image":""},{"id":"md4-115-2-4","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第2次第4題","year":115,"session":2,"number":4,"question":"關於急性細支氣管炎（acute bronchiolitis）之敘述，下列何者最適當？","options":["(A) 病理機轉為細支氣管平滑肌收縮導致呼吸費力","(B) 聽診時可聽見wheezing及crackles","(C) 最重要的致病原為流行性感冒病毒（influenza virus）","(D) 最主要的治療方式為吸入性抗病毒藥物"],"answer":1,"image":""},{"id":"md4-115-2-5","subject":"md4","topic":"兒科-感染神經","meta":"115年第2次第5題","year":115,"session":2,"number":5,"question":"關於痙攣性雙側麻痺（spastic diplegia）的描述，下列何者最不適當？","options":["(A) 是所有腦性麻痺中最常見之型態","(B) 肢體障礙通常上肢比下肢嚴重","(C) 早產兒的腦室旁白質軟化症（periventricular leukomalacia）是常見致病因","(D) 要注意兒童的動作發展，尤其是爬行動作"],"answer":1,"image":""},{"id":"md4-115-2-6","subject":"md4","topic":"兒科-感染神經","meta":"115年第2次第6題","year":115,"session":2,"number":6,"question":"有一個寶寶在1歲10個月時因川崎氏症而接受高劑量（2 g/kg）免疫球蛋白注射，今日滿2歲3個月。若想要注射日本腦炎活性減毒疫苗，下列建議何者最為適當？","options":["(A) 今日可以注射","(B) 今日不可以注射，建議下個月再注射","(C) 今日不可以注射，建議再過3個月就可以注射","(D) 今日不可以注射，建議再過6個月就可以注射"],"answer":3,"image":""},{"id":"md4-115-2-7","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"115年第2次第7題","year":115,"session":2,"number":7,"question":"下列何種狀況最容易造成Apgar score的偽陰性？","options":["(A) 母親被給與magnesium sulfate過後出生的新生兒","(B) 新生兒先天性肌肉病變（congenital myopathy）","(C) 胎兒的血液中catecholamine過高者","(D) 早產兒"],"answer":2,"image":""},{"id":"md4-115-2-8","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"115年第2次第8題","year":115,"session":2,"number":8,"question":"依異常發生的機轉命名與定義，附圖箭頭處造成的異常，最可能屬於那一種先天缺陷分類？","options":["(A) 畸形（malformation）","(B) 發育不良（dysplasia）","(C) 形變（deformation）","(D) 發育中斷（disruption）"],"answer":3,"image":"md4-115-2-8.jpeg"},{"id":"md4-115-2-9","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"115年第2次第9題","year":115,"session":2,"number":9,"question":"下列關於新生兒復甦術（neonatal resuscitation program）的敘述，何者最不適當？","options":["(A) 新生兒復甦術處置流程依循C（circulation）A（airway）B（breathing）的原則","(B) 過程中若需要監測血氧（SpO2），應監測右上肢血氧","(C) 初始步驟後，若經適當正壓換氣後，心率仍為每分鐘50下，在考慮開始胸部按壓前，應先置放氣管內管","(D) 胸部按壓與正壓換氣比為3：1"],"answer":0,"image":""},{"id":"md4-115-2-10","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第2次第10題","year":115,"session":2,"number":10,"question":"下列有關心房中隔缺損（atrial septal defect, ASD）異常心音成因的敘述，何者最不適當？","options":["(A) 收縮期雜音的成因是因為過多的血流流經中隔缺損","(B) 收縮期雜音的成因是因為過多的血流流經右心室出口與肺動脈瓣膜","(C) 固定分裂的第二心音（wide and fixed S2 split）的成因是因為過多的血流流經肺動脈瓣膜","(D) 舒張期心雜音的成因是因為過多的血流流經三尖瓣"],"answer":0,"image":""},{"id":"md4-115-2-11","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第2次第11題","year":115,"session":2,"number":11,"question":"1歲大女嬰因為有心雜音，診斷為supravalvular aortic stenosis合併peripheral pulmonary stenosis。下列何種先天性症候群最需被優先考慮？","options":["(A) Noonan syndrome","(B) William syndrome","(C) Turner syndrome","(D) CHARGE syndrome"],"answer":1,"image":""},{"id":"md4-115-2-12","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第2次第12題","year":115,"session":2,"number":12,"question":"足月男嬰出生體重為3.5公斤，1個月大時被聽到第3度收縮期的心雜音，懷疑是心室中隔缺損（ventricular septal defect）。下列何種臨床表現或是檢查結果暗示已有心臟衰竭的可能？","options":["(A) 目前體重為4公斤","(B) 平靜時的呼吸次數為每分鐘40次","(C) 平靜時的心跳次數為每分鐘120下","(D) 右側肋骨下緣可摸到約1公分的肝臟"],"answer":0,"image":""},{"id":"md4-115-2-13","subject":"md4","topic":"兒科-消化系統疾病","meta":"115年第2次第13題","year":115,"session":2,"number":13,"question":"有關正常腸道發展，下列敘述何者最不適當？","options":["(A) 食道、胃及前段十二指腸是由前腸（foregut）發展而成","(B) 降結腸及上段肛管是由後腸（hindgut）發展而成","(C) 神經峭（neural crest）細胞的遷移是由顱部至尾部","(D) 小腸及全段橫結腸是由中腸（midgut）發展而成"],"answer":3,"image":""},{"id":"md4-115-2-14","subject":"md4","topic":"兒科-消化系統疾病","meta":"115年第2次第14題","year":115,"session":2,"number":14,"question":"關於兒童吞食異物（foreign bodies）的敘述，下列何者最適當？","options":["(A) 就診時還在食道，如果沒有導致吞嚥困難，可先再觀察24小時","(B) 鈕扣電池（button batteries）因為體積較小容易排出，一般以觀察為主","(C) 誤食一枚錢幣在胃中，可先觀察一個月，若無排出，則建議用胃鏡移除","(D) 青少年或成人如胃中有長度超過5公分的異物，建議先使用胃鏡移除"],"answer":[2,3],"image":"","answer_note":"更正:第14題答Ｃ或Ｄ或CD者均給分"},{"id":"md4-115-2-15","subject":"md4","topic":"兒科-消化系統疾病","meta":"115年第2次第15題","year":115,"session":2,"number":15,"question":"關於膽道閉鎖（biliary atresia）的敘述，下列何者最不適當？","options":["(A) 新生兒糞便如呈現淡黃色或灰白色，應懷疑是否有膽道閉鎖或肝內膽汁滯留的可能","(B) 西方國家膽道閉鎖的發生率，比東亞國家為高","(C) 膽道閉鎖在肝切片檢查最重要的特徵是膽管增生（bile ductular proliferation）","(D) 膽道閉鎖宜及早完成診斷，建議在60天以內完成葛西手術（Kasai procedure）"],"answer":1,"image":""},{"id":"md4-115-2-16","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"115年第2次第16題","year":115,"session":2,"number":16,"question":"有關嬰幼兒阻塞性尿路疾病（obstructive uropathy）之影像學檢查，下列何者最不適合？","options":["(A) 靜脈注射腎盂攝影（intravenous pyelogram）","(B) 排尿時膀胱尿道攝影術（voiding cystourethrogram）","(C) 前行性腎盂攝影（antegrade pyelogram）","(D) 核醫掃描（renal scintigraphy）"],"answer":0,"image":""},{"id":"md4-115-2-17","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"115年第2次第17題","year":115,"session":2,"number":17,"question":"關於多囊性腎發育不全（multicystic dysplastic kidney），下列敘述何者最不適當？","options":["(A) 另一側腎臟可能會有膀胱輸尿管逆流（vesicoureteral reflux）","(B) 通常是雙側腎臟異常","(C) 是新生兒腹部腫塊最常見原因","(D) 併發症包括高血壓與發生Wilms tumor，要定期接受腎臟超音波追蹤"],"answer":1,"image":""},{"id":"md4-115-2-18","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"115年第2次第18題","year":115,"session":2,"number":18,"question":"有關兒童泌尿道感染（urinary tract infection）之危險因子（risk factors），下列何者最不適當？","options":["(A) 泌尿系統結構異常（anatomic abnormality）","(B) 便秘（constipation）","(C) 如廁訓練時（toilet training）","(D) 割包皮男孩（circumcised male）"],"answer":3,"image":""},{"id":"md4-115-2-19","subject":"md4","topic":"兒科-感染神經","meta":"115年第2次第19題","year":115,"session":2,"number":19,"question":"2歲男孩發燒7天，皮膚有紅疹，身體診察發現雙眼結膜充血、無分泌物，嘴唇乾裂合併草莓舌，右側頸部有1.8公分的淋巴結。下列敘述何者最不適當？","options":["(A) 診斷可能為黏膜皮膚淋巴腺綜合症（mucocutaneous lymph node syndrome）","(B) 實驗室檢查常出現高血鈉","(C) 應進一步安排心臟超音波檢查","(D) 尿液常規檢查可能出現無菌性膿尿（sterile pyuria）"],"answer":1,"image":""},{"id":"md4-115-2-20","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"115年第2次第20題","year":115,"session":2,"number":20,"question":"下列何者為Henoch-Schönlein purpura最不常見的臨床表現？","options":["(A) 關節痛（arthralgia）","(B) 腹痛（abdominal pain）","(C) 血尿或蛋白尿（hematuria or proteinuria）","(D) 嗜中性白血球低下（neutropenia）"],"answer":3,"image":""},{"id":"md4-115-2-21","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第2次第21題","year":115,"session":2,"number":21,"question":"5歲女童流鼻水，咳嗽一週以上，最近3～4天高燒達39.5℃，且鼻水轉變為黃綠濃稠狀，伴有頭痛，夜間咳嗽較明顯，此外無其它症狀。最可能的診斷為：","options":["(A) 急性鼻咽炎（acute nasopharyngitis）","(B) 急性鼻竇炎（acute sinusitis）","(C) 急性支氣管炎（acute bronchiolitis）","(D) 過敏性鼻炎（allergic rhinitis）"],"answer":1,"image":""},{"id":"md4-115-2-22","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"115年第2次第22題","year":115,"session":2,"number":22,"question":"關於幼兒期接受癌症治療多年後，較常產生的延遲效應（late adverse effect），下列敘述何者最不適當？","options":["(A) anthracyclines類藥物（如doxorubicin）：高頻為主的聽力下降","(B) 頭部放療：影響執行功能、注意力、記憶力、處理速度、視力","(C) bleomycin藥物：肺纖維化","(D) vincristine及vinblastine：周邊神經病變"],"answer":0,"image":""},{"id":"md4-115-2-23","subject":"md4","topic":"兒科-血液腫瘤免疫","meta":"115年第2次第23題","year":115,"session":2,"number":23,"question":"有關兒童特發性血小板低下性紫斑症（idiopathic thrombocytopenic purpura）的敘述，下列何者最不適當？","options":["(A) 約有2至3成的病童會發生腦出血","(B) 約7至8成的病童，會在6個月內血小板數目恢復正常","(C) 青春期的女生，需注意是否有全身性紅斑性狼瘡（systemic lupus erythematosus）的可能","(D) 家屬常會敘述孩童前一天完全正常，隔天身上就到處是出血點和瘀青"],"answer":0,"image":""},{"id":"md4-115-2-24","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第2次第24題","year":115,"session":2,"number":24,"question":"關於肋膜積液是滲出液（exudate）或是漏出液（transudate）的鑑別診斷，下列何者最不適當？","options":["(A) exudate之液體所含之蛋白質經常＞3.0 g/dL","(B) transudate之液體pH值經常＜7.2","(C) exudate之液體中的lactate dehydrogenase（LDH）值經常＞200 IU/L","(D) transudate之液體中的葡萄糖經常≧60 mg/dL"],"answer":1,"image":""},{"id":"md4-115-2-25","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第2次第25題","year":115,"session":2,"number":25,"question":"有關兒童呼吸衰竭的診斷及處置，下列敘述何者最適當？","options":["(A) 治療時需維持血氧飽和濃度至少大於98%","(B) 血液氣體分析緊急時可使用微血管血（capillary blood gas）","(C) 血液氣體分析以代謝性酸中毒為主","(D) 胸部X光的診斷標準為兩側呈全花白狀"],"answer":1,"image":""},{"id":"md4-115-2-26","subject":"md4","topic":"兒科-內分泌遺傳","meta":"115年第2次第26題","year":115,"session":2,"number":26,"question":"下列何種狀況最不可能造成次發性腎上腺功能不全（secondary adrenal insufficiency）？","options":["(A) 先天性腎上腺增生症（congenital adrenal hyperplasia）","(B) 突然停掉服用超過一個月的腎上腺皮質酮（prednisolone）","(C) 前腦無裂畸形（holoprosencephaly）","(D) 腦垂體（pituitary gland）曾接受過放射線治療（radiotherapy）"],"answer":0,"image":""},{"id":"md4-115-2-27","subject":"md4","topic":"兒科-內分泌遺傳","meta":"115年第2次第27題","year":115,"session":2,"number":27,"question":"下列何種狀況是造成11個月大正常生長的嬰兒有維生素D缺乏（vitamin D deficiency）的危險因子？","options":["(A) 純母乳哺育僅到2個月大","(B) 冬季住在高緯度地區","(C) 母親於哺育期間有補充維生素D","(D) 嬰兒皮膚白皙不黝黑"],"answer":1,"image":""},{"id":"md4-115-2-28","subject":"md4","topic":"兒科-感染神經","meta":"115年第2次第28題","year":115,"session":2,"number":28,"question":"關於流行性感冒病毒（influenza virus），下列敘述何者最適當？","options":["(A) antigenic drift只會發生在A型流感病毒","(B) 目前B型流感病毒流行株分成Victoria及Yamagata lineage","(C) H7N9病毒株屬於季節流感病毒（seasonal influenza virus）的一種","(D) 抗流感病毒藥物oseltamivir作用屬於cap-dependent endonuclease inhibitor"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第28題一律給分 (原公告答案 B)"},{"id":"md4-115-2-29","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"115年第2次第29題","year":115,"session":2,"number":29,"question":"關於發燒（fever），下列敘述何者最不適當？","options":["(A) 人的體溫不是一個固定溫度，通常會在一個範圍內起伏，當肛溫超過攝氏38度時稱為發燒","(B) 人體的體溫控制中樞在下視丘","(C) 感染、發炎反應或腫瘤（neoplastic）等產生熱源（pyrogens），是發燒唯一的機轉","(D) 在人類身上，發燒會抑制身上微生物的增生，且增加發炎反應（inflammatory response），對人體是有益的"],"answer":2,"image":""},{"id":"md4-115-2-30","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"115年第2次第30題","year":115,"session":2,"number":30,"question":"6歲男童，上課時常常坐不住，愛四處亂跑，無法專心學習，對老師的勸誡皆不聽從，同學們也都因此排擠他。醫師評估可能是注意力不足／過動症（attention-deficit/hyperactivity disorder, ADHD），有關此病症，下列敘述何者最適當？","options":["(A) 診斷必要的條件包含腦波檢查結果是正常","(B) 學齡前的孩子還太小，所以不應該有ADHD診斷","(C) 大約60～80%ADHD的兒童到青春期症狀不會持續存在","(D) 診斷上相關症狀應需持續超過6個月"],"answer":3,"image":""},{"id":"md4-115-2-31","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"115年第2次第31題","year":115,"session":2,"number":31,"question":"下列何者不是5歲兒童下運動神經元（lower motor neuron）受損的症狀？","options":["(A) 肌肉無力","(B) 無Babinski sign","(C) 肌肉不自主顫動（fasciculation）","(D) 深層肌腱反射變強"],"answer":3,"image":""},{"id":"md4-115-2-32","subject":"md4","topic":"兒科-感染神經","meta":"115年第2次第32題","year":115,"session":2,"number":32,"question":"意識改變是臨床上很重要的評估，Glasgow Coma Scale（GCS）昏迷指數≦8時，往往需要積極維持呼吸道之處理。下列關於兒童意識評估的描述，何者最不適當？","options":["(A) GCS中，「語言表達反應」在嬰幼兒與較大兒童意識評估上有所不同","(B) 「坐立難安、激動（restless, agitated）」在嬰幼兒的GCS語言項目評為3分","(C) 「可定位疼痛（localizes pain）」在嬰幼兒的GCS動作項目上評為5分","(D) 長期臥床無反應的病患，開閉眼、肢體動作、腦幹反射與呼吸型態皆為Full Outline of Unresponsiveness score評估的項目"],"answer":1,"image":""},{"id":"md4-115-2-33","subject":"md4","topic":"兒科-內分泌遺傳","meta":"115年第2次第33題","year":115,"session":2,"number":33,"question":"有關克林菲特症候群（Klinefelter syndrome）的敘述，下列何者最不適當？","options":["(A) 本症為男性引起性腺功能低下與不孕症最常見的原因","(B) 由於是先天染色體異常疾病，所以出生時即外觀明顯異常","(C) 本症形成原因為精子或卵子在減數分裂過程中產生性染色體不分離所致","(D) 本症病人成年時身材較高，但睪丸較小，且精蟲偏少，甚至無精蟲"],"answer":1,"image":""},{"id":"md4-115-2-34","subject":"md4","topic":"皮膚-濕疹與皮膚炎","meta":"115年第2次第34題","year":115,"session":2,"number":34,"question":"染髮劑引起接觸性皮膚炎最常見的過敏原為下列何者？","options":["(A) 鎳（nickel）","(B) 對次酚二胺（para-phenylenediamine, PPD）","(C) 鉻（chromium）","(D) 環氧樹酯（epoxy resin）"],"answer":1,"image":""},{"id":"md4-115-2-35","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"115年第2次第35題","year":115,"session":2,"number":35,"question":"下列何種現象或特徵較不屬於斑塊型乾癬（plaque-type psoriasis）可能會有的臨床特徵？","options":["(A) Darier sign","(B) Woronoff ring","(C) Auspitz sign","(D) Koebner phenomenon"],"answer":0,"image":""},{"id":"md4-115-2-36","subject":"md4","topic":"兒科-消化系統疾病","meta":"115年第2次第36題","year":115,"session":2,"number":36,"question":"12歲男性，下肢出現紅疹（如附圖），同時伴有腹痛及關節痛症狀。在皮膚紅疹出現前，曾發生過感冒。對於此病症相關的臨床檢查，下列何者較不需要？","options":["(A) 皮膚切片併免疫螢光染色檢查","(B) 紅血球沉降速率","(C) 尿液檢查","(D) 血清免疫球蛋白E（IgE）"],"answer":3,"image":"md4-115-2-36.jpeg"},{"id":"md4-115-2-37","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"115年第2次第37題","year":115,"session":2,"number":37,"question":"48歲男性，因為痛風服用allopurinol後，出現高燒且全身（含生殖器及口腔黏膜）水疱潰瘍，皮膚科醫師確診為Stevens-Johnson syndrome，下列敘述何者錯誤？","options":["(A) 皮膚病理切片可見到表皮層和真皮層的裂解，表皮細胞明顯壞死","(B) 皮膚組織直接免疫螢光檢查（direct immunofluorescence test）呈現表皮層和真皮層之間線狀分布的免疫堆積","(C) 常侵犯眼睛黏膜","(D) 若無感染的症狀，不必常規使用抗生素，且以支持性療法為主"],"answer":1,"image":""},{"id":"md4-115-2-38","subject":"md4","topic":"皮膚-感染","meta":"115年第2次第38題","year":115,"session":2,"number":38,"question":"下列關於帶狀疱疹（herpes zoster）的敘述，何者正確？","options":["(A) 若病灶侵犯L2 dermatome，則病人很可能會有排泄功能的異常，如排尿困難","(B) 帶狀疱疹若在鼻頭出現水疱則為Hutchinson sign，此時病人預後較佳，不易有併發症","(C) 臉部的帶狀疱疹若在耳朵也出現水疱且合併耳痛耳鳴，須小心Ramsay Hunt syndrome的可能性，其原因為第五對腦神經的侵犯導致","(D) 帶狀疱疹後神經痛（postherpetic neuralgia）是指皮膚病灶癒合後仍有神經痛的情況，年紀大的病人發生機率較高"],"answer":3,"image":""},{"id":"md4-115-2-39","subject":"md4","topic":"皮膚-感染","meta":"115年第2次第39題","year":115,"session":2,"number":39,"question":"30歲男性，自述於一年前開始在頸部出現無痛性肉色小丘疹如圖所示，數量慢慢變多，有的丘疹亦有變大之情形，下列敘述何者錯誤？","options":["(A) 可將病灶中心的角質栓子擠出，用Giemsa染色後顯微鏡鏡檢，以確定診斷","(B) 此疾病可自行消失，所以不需抽血檢查及治療","(C) 皮膚切片病理檢查可觀察到表皮細胞內含大型嗜伊紅性的包涵體","(D) 不可自行抓摳病灶，以免周邊皮膚自體接種傳染"],"answer":1,"image":"md4-115-2-39.jpeg"},{"id":"md4-115-2-40","subject":"md4","topic":"皮膚-腫瘤","meta":"115年第2次第40題","year":115,"session":2,"number":40,"question":"60歲婦女，主訴近一年來發現手指指甲出現如圖一所示之縱向的凹痕，並且此指甲凹痕近心端的甲緣皮膚可以看到一個圓形鼓起的結節，微感壓痛。磁振造影檢查結果如圖二。下列何者是最可能的診斷？","options":["(A) 血管球腫瘤（glomus tumor）","(B) 波文氏病（Bowen's disease)","(C) 黏液樣偽囊腫（myxoid pseudocyst）","(D) 甲下外生骨（subungual exostosis）"],"answer":2,"image":"md4-115-2-40.jpeg"},{"id":"md4-115-2-41","subject":"md4","topic":"皮膚-腫瘤","meta":"115年第2次第41題","year":115,"session":2,"number":41,"question":"45歲男性，主訴近一年來在左側大腿出現一個直徑約7 mm硬實的結節（圖一），偶爾有自發性的痛感。臨床醫師用兩根手指掐捏腫瘤的邊緣，發現上述的病灶會凹陷，出現了很典型的dimple sign（圖二）。下列何者為最可能的診斷？","options":["(A) 皮膚纖維瘤（dermatofibroma）","(B) 脂肪瘤（lipoma）","(C) 神經纖維瘤（neurofibroma）","(D) 血管瘤（hemangioma）"],"answer":0,"image":"md4-115-2-41.jpeg"},{"id":"md4-115-2-42","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"115年第2次第42題","year":115,"session":2,"number":42,"question":"28歲的女性因每日落髮大於150根而至皮膚科就診。經詢問後發現，其3個月前開始減肥並實行嚴格的卡路里控管，體重減少約15公斤。仔細觀察頭皮並沒有發炎的現象，毳毛（vellus hair）也沒有增加。此病患落髮的原因最有可能為下列何者？","options":["(A) 休止期落髮（telogen effluvium）","(B) 生長期落髮（anagen effluvium）","(C) 圓禿（alopecia areata）","(D) 紅斑性狼瘡（lupus erythematosus）"],"answer":0,"image":""},{"id":"md4-115-2-43","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"115年第2次第43題","year":115,"session":2,"number":43,"question":"25歲Darier disease女性病患，正在接受口服維他命A酸的治療，下列何者錯誤？","options":["(A) 因為口服維他命A酸會致畸胎，治療中應建議病患避孕","(B) 此疾病會因為曬太陽改善，應建議病患多曝曬陽光","(C) 指甲變異為診斷依據之一，常出現白及紅色的直條紋，成縱向指甲瘠或V型裂痕","(D) 病灶可能會伴隨異味，而讓患者生活適應感到不便"],"answer":1,"image":""},{"id":"md4-115-2-44","subject":"md4","topic":"神經-中風","meta":"115年第2次第44題","year":115,"session":2,"number":44,"question":"關於急性缺血性腦中風之處置，下列何者最適當？","options":["(A) 不論到院時血壓數值，皆應控制在185/110 mmHg以下","(B) 不論到院時血糖數值，皆應控制在140～180 mg/dL","(C) 輕度中風建議短期合併抗血小板藥物clopidogrel與ticagrelor","(D) 頸動脈剝離建議使用抗凝血劑或抗血小板藥物預防再次中風"],"answer":3,"image":""},{"id":"md4-115-2-45","subject":"md4","topic":"神經-中風","meta":"115年第2次第45題","year":115,"session":2,"number":45,"question":"一位52歲女性，家族中有母親與哥哥曾因顱內動脈瘤破裂導致蜘蛛網膜下腔出血。她本身患有多囊腎病（autosomal dominant polycystic kidney disease），目前無神經症狀。接受腦部MRI時，意外發現一顆5 mm的後交通動脈（posterior communicating artery）動脈瘤。下列敘述何者最適當？","options":["(A) 該動脈瘤5年內破裂風險極低（＜1％），無需追蹤","(B) 因動脈瘤位於後循環，5年內破裂風險約2.5％，應考慮積極評估或處理","(C) 若無高血壓或家族史，後交通動脈瘤5 mm的破裂風險與前大腦動脈／中大腦動脈類似","(D) 除非有動靜脈畸形共病，多囊腎病並非顱內動脈瘤的危險因子"],"answer":1,"image":""},{"id":"md4-115-2-46","subject":"md4","topic":"神經-中風","meta":"115年第2次第46題","year":115,"session":2,"number":46,"question":"一位70歲男性，有高血壓與糖尿病病史。近兩週出現三次相似的短暫左手無力與構音不清，每次持續約3～ 5分鐘後完全恢復，未伴有頭暈或視覺異常，腦部MRI無明顯急性病灶。下列何者最可能為其暫時性腦缺血發作的病理機轉？","options":["(A) 來自心臟或頸動脈粥樣硬化斑塊的栓塞，造成暫時遠端血管阻塞後自行溶解","(B) 穿通動脈因脂玻璃樣變化（lipohyalinosis）與微血管硬化造成反覆短暫低灌流","(C) 椎基底動脈區血流動態不足造成的低血流量","(D) 可逆性腦血管收縮症候群所致的血管痙攣性"],"answer":1,"image":""},{"id":"md4-115-2-47","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"115年第2次第47題","year":115,"session":2,"number":47,"question":"50歲男性，在夜間睡眠中經常出現大聲叫喊和拳打腳踢等激烈行為，有時會跌下床導致受傷。當他被妻子叫醒或因為撞擊醒來的時候，通常能夠清楚地描述與其肢體動作相符的生動夢境。關於此病症的敘述，下列何者最適當？","options":["(A) 此病症通常發生在非快速動眼期（non-rapid eye movement, NREM）睡眠的第三期（N3）階段，主要在前半夜","(B) 此病症的確定診斷須經多項生理睡眠檢查（polysomnography）","(C) 此病症是運動神經元疾病（motor neuron disease）的前驅症狀","(D) 治療此病症的首選藥物是modafinil，因為它可以平衡睡眠和清醒狀態"],"answer":1,"image":""},{"id":"md4-115-2-48","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"115年第2次第48題","year":115,"session":2,"number":48,"question":"45歲女性，最近一個月出現記憶障礙與反覆右手抽搐。MRI T2 flair影像顯示顳葉高訊號變化，腦電圖（EEG）顯示局部慢波，血清抗體陽性。下列何者為最可能之病因？","options":["(A) HSV（herpes simplex virus）腦炎","(B) 自體免疫性邊緣葉腦炎（autoimmune limbic encephalitis）","(C) 多發性硬化症（multiple sclerosis）","(D) 代謝性腦病變（metabolic encephalopathy）"],"answer":1,"image":""},{"id":"md4-115-2-49","subject":"md4","topic":"神經-癲癇頭痛睡眠","meta":"115年第2次第49題","year":115,"session":2,"number":49,"question":"28歲女性，患有青少年肌陣攣型癲癇（juvenile myoclonic epilepsy, JME）。她單用valproic acid治療，癲癇控制良好，向醫師諮詢孕期用藥的安全性。關於valproic acid在孕期使用的敘述，下列何者最適當？","options":["(A) valproic acid與其他抗癲癇藥物相比，致畸胎風險無顯著差異","(B) valproic acid與胎兒神經管缺陷的風險增加相關，應該避免或非不得已謹慎使用","(C) 建議懷孕期間將藥物換成topiramate，以確保胎兒安全","(D) 建議懷孕期間將藥物換成levetiracetam，由於藥物代謝動力學穩定，懷孕期間無需監測血清藥物濃度"],"answer":1,"image":""},{"id":"md4-115-2-50","subject":"md4","topic":"神經-失智退化運動障礙","meta":"115年第2次第50題","year":115,"session":2,"number":50,"question":"一位78歲男性，具有高血壓與糖尿病病史，近半年出現認知下降。家屬描述病人步態變慢、注意力下降、情緒低落，沒有明顯記憶力減退。神經學檢查中發現輕度下肢僵硬，MRI顯示多發性深部白質缺血病灶。下列何者為最可能之失智症診斷？","options":["(A) 阿茲海默病（Alzheimer disease）","(B) 額顳葉失智症（frontotemporal dementia）","(C) 多發性腦梗塞失智症（multi-infarct dementia）","(D) 路易體失智症（dementia with Lewy bodies）"],"answer":2,"image":""},{"id":"md4-115-2-51","subject":"md4","topic":"神經-失智退化運動障礙","meta":"115年第2次第51題","year":115,"session":2,"number":51,"question":"下列疾病的主要病理變化，何者不屬於tau蛋白病變（tauopathy）？","options":["(A) 多重系統萎縮症（multiple system atrophy）","(B) 進行性上眼神經核麻痺症（progressive supranuclear palsy）","(C) 皮質基底核退化症（corticobasal degeneration）","(D) 阿茲海默病（Alzheimer disease）"],"answer":0,"image":""},{"id":"md4-115-2-52","subject":"md4","topic":"神經-失智退化運動障礙","meta":"115年第2次第52題","year":115,"session":2,"number":52,"question":"關於本態性顫抖（essential tremor）的敘述，下列何者最不適當？","options":["(A) 通常出現雙手對稱性的靜止性顫抖（resting tremor）","(B) 需排除甲狀腺功能亢進及藥物過量（如：lithium或valproate），以確立診斷","(C) 常用的治療藥物，包括propranolol及benzodiazepines","(D) 對於藥物治療反應差的病人，可考慮使用聚焦超音波燒灼術"],"answer":0,"image":""},{"id":"md4-115-2-53","subject":"md4","topic":"兒科-內分泌遺傳","meta":"115年第2次第53題","year":115,"session":2,"number":53,"question":"有關唐氏症（Down syndrome）的敘述，下列何者最適當？","options":["(A) 致病原因是染色體18的一段出現異常的現象","(B) 時常出現身高矮小、脊柱側彎，但是智力不受影響","(C) 可以抽取孕婦的羊水，來檢測胎兒是否有三染色體的不正常表現","(D) 在成年後會因為運動神經元死亡而造成肌肉萎縮無力"],"answer":2,"image":""},{"id":"md4-115-2-54","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"115年第2次第54題","year":115,"session":2,"number":54,"question":"50歲男性，罹患上呼吸道感染數日，兩天前起床後出現步態不穩與複視。神經學檢查發現眼球在每個方向的運動都受到限制，肢體動作不協調，並伴隨深部肌腱反射消失。下列何者是最可能的診斷？","options":["(A) 腦幹中風（brainstem stroke）","(B) 病毒性腦炎（viral encephalitis）","(C) 米勒費雪症候群（Miller Fisher syndrome）","(D) 重症肌無力（myasthenia gravis）"],"answer":2,"image":""},{"id":"md4-115-2-55","subject":"md4","topic":"皮膚-自體免疫色素角化","meta":"115年第2次第55題","year":115,"session":2,"number":55,"question":"在皮肌炎（dermatomyositis）中，下列那一項臨床或實驗室發現最具有特異性？","options":["(A) 近端肌肉無力","(B) 血清肌酸激酶（CK）升高","(C) 關節疼痛","(D) Gottron's丘疹或紫羅蘭色皮疹（heliotrope rash）"],"answer":3,"image":""},{"id":"md4-115-2-56","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"115年第2次第56題","year":115,"session":2,"number":56,"question":"76歲男性，慢性腎功能衰竭，接受腎臟移植後開始服用環孢素（cyclosporine）和類固醇。數月後出現近端肌無力，以下肢最明顯，但血清肌酸激酶（CK）正常。下列何者為最可能的診斷？","options":["(A) 類固醇引起的肌病（steroid myopathy）","(B) 尿毒症神經病變（uremic neuropathy）","(C) 多發性肌炎（polymyositis）","(D) 重症肌無力（myasthenia gravis）惡化"],"answer":0,"image":""},{"id":"md4-115-2-57","subject":"md4","topic":"神經-脊髓周邊神經肌肉","meta":"115年第2次第57題","year":115,"session":2,"number":57,"question":"以無力為主要表現的疾病，神經傳導檢查（nerve conduction study, NCS）對下列何者之診斷最有實質助益？","options":["(A) 重症肌無力（myasthenia gravis, MG）","(B) 裘馨肌肉失養症（Duchenne muscular dystrophy, DMD）","(C) 皮肌炎（dermatomyositis）","(D) 慢性脫髓鞘多發性神經炎（chronic inflammatory demyelinating polyradiculoneuropathy, CIDP）"],"answer":3,"image":""},{"id":"md4-115-2-58","subject":"md4","topic":"神經-脫髓鞘感染腫瘤","meta":"115年第2次第58題","year":115,"session":2,"number":58,"question":"關於多發性硬化症（multiple sclerosis, MS）的敘述，下列何者最不適當？","options":["(A) 在MS的致病過程中，T淋巴球和B淋巴球的功能調控，兩者均有失常","(B) MS的發病病程有多種形式，其中以原發持續惡化型（primary progressive type）最常見","(C) MS是一種慢性中樞神經系統自體免疫疾病，其特徵是發炎和神經退化","(D) MS的診斷標準（McDonald criteria）包括臨床、放射線、腦脊髓液檢查結果，以確定疾病在病程和病灶位置上的表現"],"answer":1,"image":""},{"id":"md4-115-2-59","subject":"md4","topic":"精神-精神病","meta":"115年第2次第59題","year":115,"session":2,"number":59,"question":"依據DSM-5-TR，關於雙極情緒障礙症（bipolar disorder）的描述，下列何者最不恰當？","options":["(A) 生產後4週內發作的mood episode都可稱為peripartum onset subtype","(B) 1年內有4次以上的mood episode可稱為rapid cycling subtype","(C) 一般而言，第一型雙極情緒障礙症之躁期的持續時間至少要1週","(D) 一般而言，第二型雙極情緒障礙症之輕躁期的持續時間至少要1週"],"answer":3,"image":""},{"id":"md4-115-2-60","subject":"md4","topic":"精神-器質性與物質使用","meta":"115年第2次第60題","year":115,"session":2,"number":60,"question":"在精神狀態檢查（mental status examination, MSE）中，下列何者最能評估認知功能？①病人無法記住三個單詞（例如：蘋果、快樂、腳踏車）並在五分鐘後無法正確回憶 ②病人說話內容缺乏邏輯，句子之間沒有明顯的連貫性，且表達混亂 ③病人持續感到悲傷，對先前感興趣的活動失去興趣 ④請病人畫11點10分的時鐘","options":["(A) 僅①②","(B) 僅①④","(C) 僅①③④","(D) ①②③④"],"answer":1,"image":""},{"id":"md4-115-2-61","subject":"md4","topic":"精神-精神病","meta":"115年第2次第61題","year":115,"session":2,"number":61,"question":"有關關係妄想（delusion of reference）的病人主訴，下列何者最適當？","options":["(A) 我在想什麼他們都知道","(B) 我有超能力要拯救世界","(C) 我的行為都被別人控制","(D) 電視上播放的節目暗藏著要傳遞給我的訊息"],"answer":3,"image":""},{"id":"md4-115-2-62","subject":"md4","topic":"精神-器質性與物質使用","meta":"115年第2次第62題","year":115,"session":2,"number":62,"question":"下列何者不是美國睡眠醫學會（American Academy of Sleep Medicine），失眠藥物治療臨床指引中，針對失眠治療的建議（recommend）用藥？","options":["(A) melatonin","(B) doxepin","(C) suvorexant","(D) ramelteon"],"answer":0,"image":""},{"id":"md4-115-2-63","subject":"md4","topic":"精神-器質性與物質使用","meta":"115年第2次第63題","year":115,"session":2,"number":63,"question":"下列關於照會聯商精神醫學（consultation-liaison psychiatry）之敘述，何者最不適當？","options":["(A) 照會聯商精神醫學認為精神疾患可影響內科疾病的預後","(B) 綜合醫院住院患者憂鬱疾患的盛行率高於社區與基層診所民眾","(C) 憂鬱同時是冠狀動脈心臟病（coronary artery disease）的危險因子與不良預後因子","(D) 罹患身體疾病患者，女性、未滿40歲等是自殺企圖的危險因子"],"answer":3,"image":""},{"id":"md4-115-2-64","subject":"md4","topic":"精神-精神官能症","meta":"115年第2次第64題","year":115,"session":2,"number":64,"question":"26歲張小姐，個性內向、怕生，從小在學校朋友就少，自大學起張小姐開始頻繁出現持續性的心悸、失眠及對未來或小事過度擔憂等症狀，也難以集中注意力，總擔心自己表現不佳，導致身心俱疲。下列有關焦慮症的診斷及治療，下列敘述何者最不適當？","options":["(A) 流病研究發現常見的焦慮症，像是廣泛性焦慮症、恐慌症，傾向有家族聚集性（familial aggregation）","(B) 社交焦慮症（social anxiety disorder）是可能的診斷之一，女性罹患此症的比例與男性差不多","(C) 在治療焦慮症上，增加腦部血清素的藥物，像是SSRI或SNRI是一線治療選擇","(D) 影像學研究顯示左背外側前額葉（left dorsolateral prefrontal cortex）可作為影像生物標記（biomarker）協助診斷焦慮症"],"answer":3,"image":""},{"id":"md4-115-2-65","subject":"md4","topic":"精神-精神官能症","meta":"115年第2次第65題","year":115,"session":2,"number":65,"question":"有關於鬱症發作（depressive episodes）的敘述，下列何者最不適當？","options":["(A) 第一次重鬱症被診斷前多數患者已呈現憂鬱症狀（depressive symptoms）多時，若能及早介入，則可避免後續的鬱症發作","(B) 雙極情緒障礙症的鬱症發作與重鬱症的鬱症發作，兩者的自殺風險相當","(C) 反社會行為、逃學等皆可能是青少年期憂鬱症狀的表現","(D) 10％~15％的重鬱症患者會自殺死亡"],"answer":1,"image":""},{"id":"md4-115-2-66","subject":"md4","topic":"神經-失智退化運動障礙","meta":"115年第2次第66題","year":115,"session":2,"number":66,"question":"阿茲海默失智症與輕度認知障礙（mild cognitive impairment）兩者診斷的基本差別（primary differentiation）是依照下列那一個特徵？","options":["(A) APOE4 allele有無","(B) 腦脊髓液（CSF）β-amyloid濃度高低","(C) 腦影像生物標記陽性或陰性","(D) 日常生活功能退化"],"answer":3,"image":""},{"id":"md4-115-2-67","subject":"md4","topic":"神經-失智退化運動障礙","meta":"115年第2次第67題","year":115,"session":2,"number":67,"question":"下列有關鑑別失智症與譫妄症的敘述，何者最不適當？","options":["(A) 短時間觀察，譫妄症的病程通常較起伏（fluctuates）","(B) 譫妄症發生幻覺的機率多於失智症","(C) 譫妄症的注意力受損情況通常較為嚴重","(D) 兩者不會併存"],"answer":3,"image":""},{"id":"md4-115-2-68","subject":"md4","topic":"精神-器質性與物質使用","meta":"115年第2次第68題","year":115,"session":2,"number":68,"question":"關於酒精誘發（alcohol-induced）之精神疾患，下列描述何者最適當？","options":["(A) 若以幻覺為主之酒精誘發之精神病疾患（alcohol-induced psychotic disorder），在幻覺消失後，大部分病人現實感（reality testing）會恢復","(B) 酒精誘發之持續失憶疾患（alcohol-induced persisting amnestic disorder），通常很少發生在35歲之後","(C) 酒精誘發之情感疾患（alcohol-induced mood disorder），針對憂鬱情緒，宜儘速使用抗憂鬱藥物治療","(D) 酒精誘發之焦慮疾患（alcohol-induced anxiety disorder），約有20％的病人自陳有過恐慌發作（panic attack）"],"answer":0,"image":""},{"id":"md4-115-2-69","subject":"md4","topic":"神經-失智退化運動障礙","meta":"115年第2次第69題","year":115,"session":2,"number":69,"question":"有關皮質下失智症與皮質失智症（subcortical and cortical dementia）的鑑別比較，下列何者最不恰當？","options":["(A) 語文能力：皮質失智症（cortical dementia）早期就會出現失語症（aphasia）","(B) 計算能力：皮質失智症（cortical dementia）早期就容易受影響","(C) 情緒：皮質失智症（cortical dementia）較容易出現憂鬱情緒","(D) 動作速度，如手指輕敲測驗（finger tapping test）：皮質下失智症（subcortical dementia）較慢"],"answer":2,"image":""},{"id":"md4-115-2-70","subject":"md4","topic":"兒科-一般兒科與新生兒","meta":"115年第2次第70題","year":115,"session":2,"number":70,"question":"關於2歲時典型發展幼兒的發展狀況，下列敘述何者最適當？","options":["(A) 可以一步一踏板的走下樓梯","(B) 可以了解因果關係並簡單回答，例如：當你肚子餓的時候可以做什麼？","(C) 聽到自己的名字時會有所反應（refers to self by name）","(D) 無法區辨熟悉的家人與陌生人，陌生人靠近時大多不會害怕"],"answer":2,"image":""},{"id":"md4-115-2-71","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"115年第2次第71題","year":115,"session":2,"number":71,"question":"有關注意力不足／過動症（ADHD）的病程與預後，下列何者最適當？","options":["(A) 相較於過動的症狀，注意力不足的症狀通常會較早消失痊癒","(B) 由於注意力不足／過動症狀隨年齡漸長而改善，通常患者不會有社交功能上的問題","(C) 症狀通常在6～10歲之間會自然逐漸改善","(D) 超過一半比例的患者，ADHD症狀會持續到成人期"],"answer":3,"image":""},{"id":"md4-115-2-72","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"115年第2次第72題","year":115,"session":2,"number":72,"question":"有關自殺個案的評估與介入（intervention），下列敘述何者最適當？ ①憂鬱症與自殺的危險（risk）有關，企圖自殺（attempted suicide）個案若經評估為罹患憂鬱症，需積極治療 ②懷疑個案可能有自殺意念，需作詳細精神狀態（mental state）評估，但不宜觸及自殺想法，以免強化個案的自殺意念 ③若自殺方式為跳樓，個案的自殺意念較強，再發生自殺行為的危險（risk）也較高 ④人格違常（personality disorder）與自殺的危險（risk）無關","options":["(A) 僅①③","(B) 僅②④","(C) 僅①②③","(D) ①②③④"],"answer":0,"image":""},{"id":"md4-115-2-73","subject":"md4","topic":"精神-兒童青少年自殺其他","meta":"115年第2次第73題","year":115,"session":2,"number":73,"question":"有關兒童不良對待（child maltreatment）之敘述，下列何者最適當？","options":["(A) 性虐待（sexual abuse）是最常見的兒童不良對待形式","(B) 未供給兒童所需的營養、未注意兒童從高處掉落的危險，是兒童忽略（child neglect）","(C) 兒童生病，父母卻延遲、甚至拒絕帶去就醫，屬於身體虐待（physical abuse）","(D) 父母忙著做生意，到了10月份還沒帶孩子去小學報到上一年級，屬於情緒虐待（emotional abuse）"],"answer":1,"image":""},{"id":"md4-115-2-74","subject":"md4","topic":"神經-中風","meta":"115年第2次第74題","year":115,"session":2,"number":74,"question":"80歲女性因為頭痛到急診就醫，根據所附兩張頭部電腦斷層（CT）影像，下列敘述何者錯誤？","options":["(A) 有蜘蛛網膜下腔出血","(B) 比較像外傷造成的腦出血","(C) 有腦組織實質的出血","(D) 應該做電腦斷層血管造影（CTA）來排除血管病變"],"answer":1,"image":"md4-115-2-74.jpeg"},{"id":"md4-115-2-75","subject":"md4","topic":"兒科-泌尿系統疾病","meta":"115年第2次第75題","year":115,"session":2,"number":75,"question":"隱睪症的影像偵測工具中，最先應施行者為何？","options":["(A) 超音波","(B) 腹部X光片","(C) 電腦斷層掃描","(D) 磁振造影"],"answer":0,"image":""},{"id":"md4-115-2-76","subject":"md4","topic":"兒科-心血管呼吸","meta":"115年第2次第76題","year":115,"session":2,"number":76,"question":"關於兒童與嬰兒的心肺復甦，下列何者最適當？","options":["(A) 9歲30公斤重的兒童可以使用成人的自動體外心臟去顫器（Automated External Defibrillator）","(B) 小於1歲的嬰兒檢查脈搏以股動脈為主","(C) 小於1歲的嬰兒異物哽塞可以使用哈姆立克法急救","(D) 急救時胸部按壓深度，至少為胸部前後徑尺寸的四分之一"],"answer":0,"image":""},{"id":"md4-115-2-77","subject":"md4","topic":"神經-失智退化運動障礙","meta":"115年第2次第77題","year":115,"session":2,"number":77,"question":"有關失智症（dementia）的敘述，下列何者最不適當？","options":["(A) 失智症最常見的原因是阿茲海默症（Alzheimer's disease）及血管性失智症（vascular dementia）","(B) 失智症的確診不易，需要先排除其他疾病","(C) 失智症加上步履不穩以及尿失禁症狀，應考慮常壓水腦症（normal-pressure hydrocephalus）","(D) 偽性失智症（pseudodementia）專指症狀與真正失智症難以區分的腦炎或中樞神經系統感染"],"answer":3,"image":""},{"id":"md4-115-2-78","subject":"md4","topic":"皮膚-感染","meta":"115年第2次第78題","year":115,"session":2,"number":78,"question":"75歲男性安養院住民，因半夜全身搔癢被送到急診，理學檢查發現下腹、腋下、肚臍與生殖器處有多處丘疹與指甲抓痕，該病人最有可能的診斷為何？","options":["(A) 疥瘡（scabies）","(B) 蕁麻疹（urticaria）","(C) 乾癬（psoriasis）","(D) 異位性皮膚炎（atopic dermatitis）"],"answer":0,"image":""},{"id":"md4-115-2-79","subject":"md4","topic":"兒科-內分泌遺傳","meta":"115年第2次第79題","year":115,"session":2,"number":79,"question":"罹患tuberous sclerosis complex（TSC）的媽媽帶其15歲的兒子來門診進行第二意見的諮詢，因為先前有醫師說應該要做基因檢測，兒子目前並無任何TSC表徵。關於遺傳諮詢的內容，下列敘述何者最不妥當？","options":["(A) 了解媽媽想要進行基因檢測的目的，並說明TSC疾病的表徵與遺傳機率","(B) 兒子雖然尚未成年，仍應尊重其是否接受基因檢測的意願","(C) 相關神經學及影像檢查若無異狀，應待兒子成年後再決定是否進行基因檢測","(D) 若母親表示希望為兒子進行基因檢測，醫師可配合提供以降低母親的疑慮"],"answer":3,"image":""},{"id":"md4-115-2-80","subject":"md4","topic":"醫學倫理與法規","meta":"115年第2次第80題","year":115,"session":2,"number":80,"question":"6歲腎病症候群男童，腎臟切片診斷為focal segmental glomerulonephritis。3年來以類固醇治療無效，腎功能在這半年內急速變壞。這天，他因為嚴重水腫、肺積水喘息而入急診，醫師診斷為尿毒症需要緊急洗腎，並主張開始長期洗腎。病童的爸爸卻拒絕接受洗腎，認為洗腎將影響孩子免疫系統，是一條不歸路，應該還有許多好的治療方法，執意要帶孩子回家。對此事件，下列何種處置最恰當？","options":["(A) 通報社會局等相關主管單位","(B) 鑑定孩子的決策能力以為治療依據","(C) 請家長簽拒絕治療聲明書即可放行","(D) 強制病童住院治療"],"answer":0,"image":""}];
